window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[20]=[{"i":51868,"n":"שאבאד, אברהם חיים ממינסק","f":"שמואל צבי מוילנא","k":"בעל תולדות הימים","bt":"תרד","bp":"וילנא","b":"עבר עם הוריו למינסק. בקי בתורה והשכלה. חתן משפחת עליאשברג. גביר מחכמי מינסק גבאי ביהמ\"ד ופעל לטובת מוסדות צדקה וחסד. המציא מכונת חשבון-תרנו וקיבל בעדה אות כבוד בצרפת. פרסם מאמרים בכתבי עת בעברית וברוסית. חיבר \"תולדות הימים\" לקורות הקהילה במינסק."},{"i":51869,"n":"שאבאד, שמואל צבי ממינסק","f":"צמח","bp":"וילנא","dt":"תרנא - ב שבט","dp":"מינסק","b":"גביר מחכמי מינסק. בניו - הגבירים ר אברהם חיים, ר מרדכי (מארק)."},{"i":51870,"n":"שאבו, שמעון מטריקאלה ולאריסה","f":"דוד","b":"רב בטריקאלה, (גם בלאריסה?)-שנות ה-ש' בזמן ר שלמה הכהן משלוניקי שהזכירו בשו\"ת מהרש\"ך."},{"i":51871,"n":"שאבול, יונה משלוניקי","dt":"רץ - ה אב","dp":"שלוניקי","b":"ממגורשי ספרד, מחכמי שלוניקי."},{"i":51872,"n":"שאבריינו, אברהם מאדרינופול","f":"משה","b":"רב באדרינופול-שנות ה-ש'. בנו - ר משה."},{"i":51873,"n":"שאבריינו, משה מאדרינופול","f":"אברהם מאדרינופול","b":"רב באדרינופול-שלא."},{"i":51874,"n":"שאברלס, דוד מפרשבורג","f":"יוסף","dt":"תקעא - ב אלול","dp":"פרשבורג","b":"גבאי מחכמי פרשבורג. נהרג עק\"ה."},{"i":51875,"n":"שאג, יעקב מבאנביץ","dt":"תריד","b":"תלמיד החת\"ס. בזיוו\"ש חתן ר שלמה פלעש מנייטרא. רב בבאנביץ(=בנוביץ)-תקפט (באוצר הרבנים - תרך). תשובה אליו ב\"חתם סופר\"."},{"i":51876,"n":"שאג, שמואל ליב מפפדמ","bp":"באנביץ","b":"נכד ר שמעון אופנהיים מפרשבורג. תלמיד השב\"ס-תרמד. רב בפפד\"מ."},{"i":51877,"n":"שאג-צוובנר, אברהם מקוברסדורף","f":"יהודה ליב משאג","k":"בעל אהל אברהם","bt":"תקסא","bp":"פריישטאט (הונגריה)","dt":"תרלו - כט אדר","dp":"ירושלים","b":"תלמיד ר יצחק פרנקל מבראגנדורף, וחת\"ס. חתן ר אהרן הלוי שפיץ מהאליטש (שידוכו של החת\"ס), ובזיוו\"ש חתן ר נפתלי הירץ אופנהים מפרשבורג. עבר לפרויענקירכן, רב בשאטמנסדורף-תקפז, קוברסדורף-תריב. עלה לירושלים-תרלג עם תלמידו ר יוסף חיים זוננפלד (והתגורר ב\"בית יעקב\" שנבנה לזכרו של ר יעקב עטלינגר).","bk":[["אהל אברהם – שו\"ת",""],["דרשות מהרא\"ש",""]]},{"i":51878,"n":"שאגל, דוד משנדרובקא","f":"יהודה ליב","bt":"תרמ","b":"רב בשנדרבקה(=שענדעריווקא)-פלך קיוב-תרסג."},{"i":51879,"n":"שאד, משה","dt":"שסז - כט טבת","b":"מו\"צ בפרג"},{"i":51880,"n":"שאהין ן, יעקב החבר","f":"נסים גאון","k":"בעל פירוש לספר יצירה","b":"רב בקירואן בזמן הגאונים רב שרירא ורב האי, וכנראה שאגרת רב שרירא גאון נכתב בתשובה לשאלתו. חיבר תשובות ופירוש על ספר יצירה (יש אומרים שהפירוש לספר יצירה אינו ממנו - אלא מר אדוניס בן תמים)."},{"i":51881,"n":"שאהין ן, נסים גאון מקירואן","f":"יעקב בר נסים","k":"בעל המפתח","b":"מגדולי דורו בקירואן לצד רבינו חננאל בן חושיאל. תלמיד אביו ור חושיאל. בקי בשפות ומדעים ועמד בקשר עם גאוני בבל ועם רב האי גאון שהשיב לו הרבה. וכן עם מחותנו ר שמואל הנגיד בספרד שקיבל את תורת רב האי דרך ר נסים, בנו היחיד ר יעקב נפטר צעיר ו שמואל הנגיד כתב לו שיר תנחומין על כך. חיבר גם \"מגילת סתרים\", ו\"חבור יפה מהישועה\". חיבר גם ספרים שאבדו ובהם ספר המצוות ו\"סדר מקבלי התורה\"."},{"i":51882,"n":"שאהן, מנחם מנדל מראטה","dt":"תרמב - יב ניסן","b":"רב ברעטע(=רעטה)-תקצב. חתנו - ר ישראל איסר פרוסטיץ."},{"i":51883,"n":"שאווילזון, ישראל ממינסק","dt":"תרס","b":"מגדולי החזנים בדורו. חזן בסלונים, מינסק-תרכה."},{"i":51884,"n":"שאול (ברבי) מהלברשטט","b":"רב-שנת תפ. בנו - ר מאיר ברבי מפרשבורג."},{"i":51885,"n":"שאול (שואל) מולקוביניץ","b":"רב בולקוביניץ-אוקראינה (ליד פרוסקרוב). בנו - ר ליביש."},{"i":51886,"n":"שאול (שואל) ממינסק","f":"שלמה","b":"דיין במינסק, הסכים על \"דרך תבונות\" מינסק תקצה, עם ר ישראל מיכל ישורון, ור יהודה ליב די בוטין."},{"i":51887,"n":"שאול אהרן מליסעץ","b":"רב בליסעץ-תרל, בנו זלמן על מקומו אחריו."},{"i":51888,"n":"שאול אשטרוק הכהן מאלגיר","dt":"קנד","b":"רב בספרד, עבר לאלגיר לפני פרעות קנא, רב ודיין ורופא בתלמסאן, אלגיר. רופא החצר בתלמסאן ובאלגיר. בשנת קנא ויתר על משרת הדיין לטובת ר יצחק בונשתרוק מספרד. לאחר שהגיע הריב\"ש וראה שלא נהגו בו כבוד - התערב לטובתו והשיג לו משרת דיין מטעם שליט תלמסאן."},{"i":51889,"n":"שאול דוד מוילנא","f":"מאיר למדן","dt":"תרמ - יג אדר","b":"דיין בוילנא-תרלג על מקום אביו."},{"i":51890,"n":"שאול הכהן מג'רבה","k":"בעל שפתי רננות","bt":"תקלב","dt":"תרח - טו אייר","b":"מחכמי ג'רבא. אחיין של ר נסים הכהן בעל \"מעשה נסים\", ור רחמים הכהן מג'רבא. ראב\"ד בחארה צגירה - ג'רבא - כ-30 שנה. ייצג את קהלות במחלוקת עם אנשי חארה-כבירה, שנידונה אצל רבני תונס ר יצחק טייב ור ישועה בסיס. חיבר גם \"לחם הבכורים\", \"שי למורא\", \"קרני רמים\", \"בינה לעתים\", ועוד. מאמרים ממנו ב\"אוצר התורה\" - ג'רבה תרץ, פירוש לאזהרות ר יצחק בן ראובן ונדפסו ע\"י בנו ר משה ב\"קרן דוד\" - גרבה תרעו."},{"i":51891,"n":"שאול הכהן מהיבנוב","b":"אב\"ד היבניב-תקפט."},{"i":51892,"n":"שאול הכהן מקנדיא","k":"בעל התכלית","b":"מחכמי איטליה, רב בקנדיא-כרתים, בזמן מהרם פאדובה, תלמיד ר אליהו בן אלקנה דילדגו. עבר לתורכיה ולימד פילוסופיה."},{"i":51893,"n":"שאול הלוי מאמצ'יסלב וירושלים","f":"יוסף","dt":"תרב - ז תמוז","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":51894,"n":"שאול הלוי מאפטא","b":"רב באפטא-תקכ\"ט"},{"i":51895,"n":"שאול הלוי מהארקה","f":"צבי הירש","dt":"תריג","dp":"טבריה","b":"מחכמי טבריה מעדת החסידים, בשנת תקפז חתם על כתב שליחות לר ישראל קרא, ועל מכתב ראשי עדת החסידים אודות השליח ר משה יפה. ר ישראל משקלוב מזכירו במכתב."},{"i":51896,"n":"שאול הלוי מטורבין","f":"נפתלי הירץ הלוי","b":"רב בטורבין-תק\"נ"},{"i":51897,"n":"שאול הלוי מירושלים","b":"מחכמי ירושלים, בשנת תקמב חתם על כתב שליחות ר רפאל בן רובי."},{"i":51898,"n":"שאול הלוי מסימיאטיש","f":"יהושע הלוי","b":"רב בסימיאטיש-תק\"י"},{"i":51899,"n":"שאול הלוי מעמדן והאג","f":"יצחק סגל","bt":"תעד","dt":"תקמה - כה אייר","b":"חתן ר אריה ליב מלבוב ואמשטרדם, וגיסו של ר שאול מאמשטרדם. מגדולי חכמי דורו, ישב 55 שנים בתענית, רב בעמדן-תקב, האג והמדינה-תקח. תשובה ממנו ב\"אור ישראל\" לר ישראל ליפשיץ."},{"i":51900,"n":"שאול טוביה מטלז","f":"מרדכי","b":"תלמיד ר זאב וולף ליפקין. רב בטלז-תקצז, פוניבז'."},{"i":51901,"n":"שאול יהודה ליב הכהן מחברון","dt":"תרנג - ג טבת","dp":"ירושלים","b":"חסיד חב\"ד. רב בקונסטנטינוגרד(=קראסנוגרד), ועוד ערים ברוסיה, עלה לארץ וכיהן כרב קהלת חב\"ד בחברון לצדו של ר שמעון מנשה חייקין, עבר לירושלים."},{"i":51902,"n":"שאול יהודה ממיץ","dt":"תטז - כד תשרי","b":"רב במיץ"},{"i":51903,"n":"שאול יהושע השל מברודי","f":"משה בשקא","b":"מגדולי חכמי ברוד-תר\"י"},{"i":51904,"n":"שאול כץ הכהן מאוסטרהא","f":"מאיר מעיר חדש ואוסטר","dt":"תקעז - כט ניסן","dp":"אוסטרהא","b":"פרנס מחכמי אוסטרהא ומלמד תורה לרבים בזמן ר חיים רפפורט שהזכירו בספרו וביקש הסכמתו בכפיית גט. נזכר גם ב\"מאיר נתיבים\"."},{"i":51905,"n":"שאול ליב הכהן","f":"אהרן הכהן","b":"רב-שנת תק\"צ"},{"i":51906,"n":"שאול מאוסטרין","b":"רב באוסטרין-תק\"ס"},{"i":51907,"n":"שאול מאזמיר","f":"עזרא","b":"רב באזמיר, חתם-תר עם ר חיים דוד צורייאנו ור רחמים אליהו חזן."},{"i":51908,"n":"שאול מאשכנז","f":"דוד","b":"מגדולי חכמי אשכנז-ש\"ס"},{"i":51909,"n":"שאול מברודי וקראקא","f":"אברהם זאב","dt":"תקנג - י סיון","dp":"קראקא","b":"דרשן ומקובל. רב בברודי, קראקא-תקם. חתן ר משה יאכט ב\"ר דוד אב\"ד אמשטרדם."},{"i":51910,"n":"שאול מבריסק וקרקא - הזקן","f":"אברהם יהושע השל מקרא","bp":"לובלין","dt":"תסז - יז אייר","dp":"גלוגא","b":"חתן ר ליב הויכער (הגבוה) מקראקא (ולפי עיר תהלה-בריסק - חתן ר זכריה מנדל-בנו של ר ליב הויכער). רב בלאקטש, בריסק-תמח, אפטא וגליל קראקא, קראקא-תנח או תסא על מקום אביו (בגלל שהיה צעיר בזמן פטירת אביו-תכד כיהנו בינתים רבנים אחרים ובהם ר אריה יהודה ליב) ור יהודה ליב בן יצחק איזיק על מקומו אחריו, אפטא, ברסלוי-תסד, נפטר בדרך לאמשטרדם (בעיר גלוגא) לכהן שם כרב - ונזכר בפנקס בית הכנסת בגלוגא. הסכים על \"אהל יעקב\"-תנח, \"נחלת יעקב\", \"ראש יוסף\"-תס, ועוד. בניו - ר אריה ליב מרישא-חתן החכם צבי, ר יהושע השל מוילנא."},{"i":51911,"n":"שאול מדובנא ואמשטרדם (לוונשטם","f":"אריה ליב מאמשטרדם","k":"בעל בנין אריאל","bt":"תעז","bp":"רישא","dt":"תקן - ז תמוז","dp":"אמשטרדם","b":"מצאצאי השר ר שאול וואהל. נכד-אבי אמו ה\"חכם צבי\", נכד ר שאול מבריסק ואמשטרדם בן ר יהושע השל מקראקא ובריסק. חתן ר אברהם כהנא מאוסטרהא ודובנא בן ר שלום שכנא. מגדולי חכמי דורו. חתן ר אברהם כהנא מאוסטרהא ודובנא. רב בלוקאטש-תצז, דובנא-תקה על מקום חותנו וגיסו וראש ישיבה שם, ור נפתלי הרץ הלברשטט על מקומו אחריו בדובנא. אמשטרדם-תקטו על מקום אביו ובנו ר יעקב משה על מקומו אחריו. אחיו של ר צבי הירש מלונדון וברלין. הגר\"א כתב אליו \"אהובי... שמו נודע בשערים...\" נזכר ב\"כתבי הגאונים\" לרצ\"ה הורביץ. בניו גם - ר אריה ליב לוונשטם-חתן היעב\"ץ, ר יעקב משה לוונשטם מאמשטרדם."},{"i":51912,"n":"שאול מדוברומיל","dt":"תרעח - בערך","b":"רב בדוברומיל בזמן ר אברהם מרדכי רימלט."},{"i":51913,"n":"שאול מדרויא ווילנא","dt":"תקעג - יב אד\"א","dp":"וילנא","b":"מחכמי וילנא, מתלמידי הגר\"א, מקובל."},{"i":51914,"n":"שאול מהורוקא וטבריה","f":"צבי הירש מהורוקא","b":"מחכמי טבריה."},{"i":51915,"n":"שאול מוילקומיר","b":"מרבני ווילקומיר"},{"i":51916,"n":"שאול מזולקוא","f":"מרדכי","b":"נכד ר העשל מקראקא, ונכד(-אבי אמו) בעל קיקיון דיונה. מחכמי זולקוא, חתם-תפד עם ראש הקהל, ובשנת תצט חתם על בחירת ראשי העדה."},{"i":51917,"n":"שאול מזולקוא","b":"חתם-תז עם ר אברהם גראפין, ר יהושע פאלק שור, ר שמריה הורביץ ועוד."},{"i":51918,"n":"שאול מז'וסלי (קצנלנבוגן)","f":"אריה ליב מברוד","b":"אב\"ד ז'וסלי(זאסלא). בניו - ר אריה ליב מטאוריג-(נפטר תקצט), ר מאיר רובין בעל \"מיישר תועי דרך\"."},{"i":51919,"n":"שאול מז'וסלי - ב","b":"רב בזאסליא(=ז'וסלי)-תרלד בערך על מקום ר מנחם מנדל בן דוד."},{"i":51920,"n":"שאול מזסלב","b":"אב\"ד זסלב. בנו ר אריה ליב אברהם (נפטר לובלין תקעט)."},{"i":51921,"n":"שאול מחאטין","b":"רב בחאטין-תר\"מ"},{"i":51922,"n":"שאול מטבריה","f":"צבי הירש סגל מהארקי","dt":"תריג - א טבת","b":"ממנהיגי חסידי רייסין בטבריה על מקום אביו. ולאחר פטירתו הפך ביתו לבית תפלה לחסידים."},{"i":51923,"n":"שאול מטומשוב","f":"ישראל ורעשנא מקאבלין","b":"רב בטומשוב. אחיהם של ר אברהם מוועלין, ור משה מלובלינץ וליסא."},{"i":51924,"n":"שאול מלאמז","f":"משה","k":"בעל גבעת שאול","b":"נכד(-אבי אמו) ר ר יצחק כהנא-שפירא (אביו של ר יעקב מחלמא). רב בלאמז-תקלד, וואין-תקל. בנו - ר יהושע זליג מלאמז."},{"i":51925,"n":"שאול מלובלין","f":"מאיר","b":"רב בלובלין-תקמב."},{"i":51926,"n":"שאול מלובלין","f":"חיים דוד","dt":"תקכח - א אלול","dp":"לובלין","b":"מחכמי לובלין."},{"i":51927,"n":"שאול מלובלין","f":"נחום","dt":"תקלז - יג אב","dp":"לובלין","b":"נכד ר יו\"ט ליפמן מצוזמיר. מחכמי לובלין."},{"i":51928,"n":"שאול מלודמיר","f":"יעקב מלודמיר","b":"רב בברסטיצקא-תפא, לודמיר-תקיא. נאמן מדינת ואהלין. הסכים על \"בית אברהם\"-תקיג. בנו ר פנחס מאוסטרהא, ר זלמן אפרים על מקומו אחריו בברסטיצקא.."},{"i":51929,"n":"שאול מלומזה","dt":"תקלא - טז טבת","b":"רב בלאמזא"},{"i":51930,"n":"שאול מלוניל","f":"משלם בן יעקב","k":"הרא\"ש מלוניל","b":"מגדולי הראשונים בחכמי צרפת-ד'תת\"צ. חיבר ספר המתנות, ועוד. מאמר ממנו בסוף \"חובות הלבבות\". מתורתו בספר השלמה לר משלם שכותב עליו דודי. אחיהם של ר אהרן ור יעקב הנזיר (וכך נאמר גם על ר אשר בן שאול מלוניל - ?). מתלמידיו: ר אשר בן שלמיה בעל חדושי הש\"ס. ישנו חכם בשם ר אשר בן שאול מלוניל וישנו בלבול ביניהם."},{"i":51931,"n":"שאול מלושטין","f":"משה","dt":"תקמב - כז אדר","b":"רב בלושטין"},{"i":51932,"n":"שאול ממוסול","f":"חכם חי","b":"רב במוסול-עירק."},{"i":51933,"n":"שאול ממזיבוז","b":"רב במזיבוז-תקצ\"ה"},{"i":51934,"n":"שאול מנשה מנדבורנה","b":"רב בנדבורנה-תרל, בנו ר ישראל קרל על מקומו אחריו. חסיד ר יעקב שמשון מקוסוב."},{"i":51935,"n":"שאול מעירק והודו","f":"יוסף עבדאללה","k":"בעל גבעת שאול","bt":"תרי","bp":"עירק","dt":"תרסו - יט אב","b":"פייטן וחוקר מחכמי בגדד, עבר להודו והונג קונג. חיבר גם \"משבצת התרשיש\", משיריו ב\"שירה ופיוט של יהודי בבל\"."},{"i":51936,"n":"שאול מפשדברז'","b":"רב בפשדברז'"},{"i":51937,"n":"שאול מקאליש","dt":"תפא - כט שבט","b":"רב בקאליש"},{"i":51938,"n":"שאול מקוסוב וקוברין","b":"אב\"ד קוסוב, קוברין. חברו ומחותנו של הגדול ממינסק. בנו - ר אברהם מאיר אשכנזי מלאהוסק. נכדו-בן בתו - החזון איש."},{"i":51939,"n":"שאול מקידאן","f":"השל","b":"רב בקידאן-לפני תק."},{"i":51940,"n":"שאול מקרלין וירושלים","dt":"תקצז - א תמוז","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":51941,"n":"שאול מראסיין","f":"אריה ליב מטאוריג","dt":"תרלו","b":"גביר מחכמי ראסיין."},{"i":51942,"n":"שאול משינאווא","b":"רב בשינאווא. חתנו היה ר יוסף יוסקא וסטרייך, נכדו - ר דוד קלגסברון-ברדק מירושלים."},{"i":51943,"n":"שאול משלוניקי","f":"שלמה בן דוד","dt":"תקב","dp":"שלוניקי","b":"רב בשלוניקי על מקום ר שמואל צדוק ור יוסף דוד. גיסו של הדיין ר בנימין עשאל, ורב הגדול על מקום ר יצחק בדרשי, ור יוסף ן ארדיט על מקומו אחריו. חתם ראשון על \"זהורי חמה\" לר יצחק קריספין-תצח."},{"i":51944,"n":"שאול משקלוב","b":"מחכמי שקלוב. בנו - ר אברהם בעל \"שני המאורות\" ו\"גאון אברהם\". גיסו - ר משה רוסקעס משקלוב בעל \"זכרון למשה\"."},{"i":51945,"n":"שאול פיבש מלבוב","f":"אליהו","dt":"תקפב - כב שבט","dp":"זולקוא","b":"ראב\"ד בלבוב."},{"i":51946,"n":"שאול שמעון מלובלין","f":"יהודה הלוי","b":"אחיו של המהרש\"א. דיין בלובלין-שפז. חיבר סליחה לקדושי וארשא-שנו. הגיה את חלק מספרי אחיו - וחתם בסוף מסכת נידה."},{"i":51947,"n":"שאולזון, אברהם דב מירושלים","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":51948,"n":"שאולזון, אהרן אלימלך מירושלים","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"תבונה\" - ירושלים תשא. עורך \"שילה\" - ירושלים תשה."},{"i":51949,"n":"שאולזון, אליעזר שאול","f":"זליג פאי","b":"רב בווילקי,ציזעווע,רמסגעט"},{"i":51950,"n":"שאולזון, שאול אלחנן מירושלים","f":"רא\"ה","b":"מראשי כולל פינסק קרלין בירושלים-תרסה."},{"i":51951,"n":"שאולי, משה הכהן מפרס","k":"בעל הבשם","r":"הרב הראשי ליהדות איראן בישראל ובתפוצות","bt":"תרפ","dt":"תשנה - כו תשרי","dp":"ירושלים","b":"עלה בנערותו ולמד בישיבות ירושלים, תלמיד הראשל\"צ הרב עוזיאל. מחכמי ירושלים ומקובל, מלמד במקומות רבים. רב יוצאי פרס בארץ ובתפוצות-תשי.","bk":[["זהר הבשם",""],["זיו הבשם",""],["חכמת הבשם",""],["ניחוחות הבשם",""],["שחר הבשם",""]]},{"i":51952,"n":"שאומן, אברהם דוד מקיטוב","bt":"תרע","bp":"קיטוב","dt":"תשלה","b":"עבר מקיטוב לוינה, למד בביהמ\"ד לרבנים וגם בביה\"ס לרפואה. עבר לגינואה, טורינו. מורה ורב בטורינו אצל ר קסטל בולוניזה, רב בגינואה. לזכרו - \"דוד שאומן, דברי הגות\" מילנו תשלז (רובו באיטלקית)."},{"i":51953,"n":"שאטיבי, יהושע מספרד","k":"תרגם ספר הקצרת","b":"רופא מחכמי ספרד."},{"i":51954,"n":"שאטין, אברהם יונתן בנימין מבער","f":"שמעון הכהן משאראש","b":"מחכמי בערעג-ראקוש-תרלז. בנו - ר שמעון הכהן ממעדיער."},{"i":51955,"n":"שאטין, אשר אנשל מפעסט","f":"יהושע מטשנגער","b":"מגיד שיעורים בפעסט."},{"i":51956,"n":"שאטין, בנימין וולף מדירנפורט","f":"יוזפא שאטין","b":"רב בדירנפורט-תקע."},{"i":51957,"n":"שאטין, הלל ממנהיים","f":"שמואל ממנהיים","dt":"תקפג","b":"רב במנהיים על מקום אביו."},{"i":51958,"n":"שאטין, הניך הכהן מגלוגא","f":"יוסף שאטין","dt":"תקז - א שבט","b":"רב בגלוגא"},{"i":51959,"n":"שאטין, יהושע מטשנגער","b":"חתן ר אברהם יונגרייז מטשנגער. בנו - ר אשר אנשל מפעסט."},{"i":51960,"n":"שאטין, יוזאפ כץ מליסא וגלוגא","b":"רב בליסא-תק\"כ,גלוגא רבתי"},{"i":51961,"n":"שאטין, יצחק מטשנגר","f":"יהושע מטשנגר","dt":"תשד","b":"חתן ר אשר רנשל יונגרייז מטשנגר. דומ\"צ בטשענגער"},{"i":51962,"n":"שאטין, צבי הכהן מבטורקעז","f":"שמעון משאראש-פאטק","bt":"תרמד","bp":"עיר חדש","dt":"תשד","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן ר ישראל רייך מבאטורקעז. רב בברין, באטורקעז על מקום חותנו. נספה בשואה."},{"i":51963,"n":"שאטין, שלמה ממגנצא","b":"מגדולי חכמי אשכנז,מרביץ תורה במיינץ-שנת ר'"},{"i":51964,"n":"שאטין, שמואל הכהן מפפד\"מ","f":"יוסף יוזפא","k":"מהרשש\"ך","r":"אב\"ד דראמשטאט ואח\"כ ר\"מ ואב\"ד בפרנקפורט","bt":"תד","dt":"תעט - יח תמוז","dp":"פפד\"מ","b":"תלמיד ר ישעיה הורביץ-נכד השל\"ה. מחכמי פפד\"מ ורב בביהמ\"ד של ר מנס דרמשטט, רב מדינת דרמשטט-תסד, רב זמני בפפד\"מ-תסג על מקום ר יוסף שמואל עד למינוי ר נפתלי הכהן בעל \"סמיכת חכמים\", ושוב אחרי שעזב ור אברהם ברוידא על מקומו אחריו. זקנו של החתם סופר. מקורב לבעל \"חות יאיר\" המזכירו בספרו. חיבר \"כוס ישועות\", ועוד. הסכים על תהלים שהוציא ר דוד גרינהוט-תעב. חתניו - ר משה ממפד\"מ-זקנו של החת\"ס, ר יהודה ליב פרנקפורטור ממטרסדורף שערך את הגהות אביו ר יוסף שמואל על הש\"ס - והוסיף עליהם משלו. גיסו - ר משה פרנקפורט מאמשטרדם בעל \"זה ינחמנו\".","bk":[["כוס הישועות \\ חידושי מהרשש\"ך - על הש\"ס",""]]},{"i":51965,"n":"שאטין, שמואל מפפד\"מ ומנהיים","f":"משה","dt":"תקנז - יא תשרי","b":"אחיין ר שמואל מפפד\"מ. רב ור\"מ בקלויז במנהיים-תקי כ-47 שנה, ובנו ר הלל על מקומו אחריו. היה מהמערערים על הגט מקליווא-תקכו."},{"i":51966,"n":"שאטין, שמעון הכהן - הסבא","f":"משה יחיאל","k":"בעל כהונת עולם","bt":"תקס - בערך","dt":"תרכא -א-יא חשון","dp":"שאראש-פוטוק?","b":"מצאצאי המהרשש\"ך. תלמיד ר עקיבא איגר. מרביץ תורה במאד, טוקאי, רב בשארוש-פאטאק-תקצג. נזכר אצל קרובו החת\"ס."},{"i":51967,"n":"שאטין, שמעון הכהן ממעדיער-הנכד","f":"אברהם יונתן בנימין","bt":"תרלז","bp":"בערעג-ראקוש","dt":"תרצח - א כסלו","dp":"מעדיער - ירושלים","b":"תלמיד השב\"ס, ור דוד ניימן מפרשבורג. חתן ר יהושע השל וייס ממעדיער. רב במעדיער-תרף על מקום חותנו, וחתנו ר פנחס אשר גולדברגר על מקומו אחריו."},{"i":51968,"n":"שאטר, נתן","f":"יעקב קאליפארי","b":"רב ביאנוב-תק\"ס"},{"i":51969,"n":"שאי, יוסף ל' מפרשבורג","b":"ממיסדי האגודה הציונית \"יגדיל תורה\" (ששינתה שמה ל\"אהבת ציון\") בפרשבורג - אחרי תרנז - שעסקה בלימוד גמרא למשתתפיה."},{"i":51970,"n":"שאי, מיכאל מפרשבורג וניו יורק","f":"ישעיה ישכר ממאשן","bt":"תרנד","bp":"מאשאן-מאדיאראוואר-פרשבורג","dt":"תשלט - יא ניסן","b":"תלמיד הדעת סופר. חתן ר אלתר שאול פפר מניו יורק. רב בניו יורק ועל מקום חותנו-תרצו - בבימ\"ד אנשי אונגרין בניו יורק. חוקר תולדות קהלת פרשבורג."},{"i":51971,"n":"שאירה, יעקב מספרד","b":"חכם בחכמת התכונה תחת המלך אלפונסו בספרד. חיבר ספרים על חכמת התכונה - בכת\"י. נסע בשליחות מלך ערבי להודו ותרגם ספר התם והמכוער - מלשון הודית לערבית, וכן תרגם את לוחות התכונה של החכם ההודי - חנבה לערבית. נזכר בפירוש הראב\"ע."},{"i":51972,"n":"שאך, שמואל","bt":"תרכד","dt":"תרצח - יב טבת","b":"רב בשיקאגו-תר\"ס"},{"i":51973,"n":"שאכיץ, מרדכי מעיר חדש","dt":"תקע","b":"דיין בעיר חדש אצל ר יעקב נייפלד - יחד עם ר אברהם וינר. נספד ע\"י החת\"ס."},{"i":51974,"n":"שאלאניקייו, משה יוסף משלוניקי","dt":"תקם","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":51975,"n":"שאלודיש די, שם טוב משלוניקי","dt":"שעד - יט כסלו","dp":"שלוניקי","b":"תלמיד ישיבת ר אהרן ן חסון. מחכמי שלוניקי. תשובותיו בספרי חכמי דורו ובהם \"משפט צדק\" לר מאיר מלמד. נפטר צעיר."},{"i":51976,"n":"שאלתיאל השתדלן מקושטא","b":"שתדלן(=קהייא) בקושטא-רעט ומקורב למלכות בזמן סולימאן השני, נזכר בשו\"ת הרא\"ם. הוסר ממשרתו והוחזר ע\"י ראשי קהלות קושטא."},{"i":51977,"n":"שאלתיאל חן, זרחיה מספרד","f":"יצחק","k":"בעל אמרי שפר","b":"מחכמי ברצלונה-ה'מד, בקי בפילוסופיה. חיבר פירושים לתנ\"ך ולמורה נבוכים, ועוד, תרגם ספרים מערבית. מכתבים ממנו לר הלל מפיררה אודות \"מורה נבוכים\" - נדפסו ב\"אוצר נחמד\". לפי ארזי הלבנון - עבר לאיטליה, רופא ברומא, חיבר \"תקות אנוש\" על איוב ו\"אמרי דעת\" על משלי."},{"i":51978,"n":"שאלתיאל ממגנצא","b":"מגדולי חכמי מגנצא-ד'תת\"ק"},{"i":51979,"n":"שאלתיאל מצפת","f":"אברהם - [ידידיה]","k":"בעל ריוח והצלה","b":"מחכמי צפת. בשליחות ברודוס-תקפא והמשיך באיטליה ותורכיה. נלקח בשבי ע\"י שודדים וניצל, וחיבר \"ריוח והצלה\"."},{"i":51980,"n":"שאלתיאל ן, שאלתיאל משלוניקי","f":"חיים","b":"דיין בשלוניקי-תקסג עם ר חיים יוסף ן אדון ור אברהם גטניו. הסכים על פסק של ר דוד קראסו."},{"i":51981,"n":"שאלתיאל, אברהם בכור משלוניקי","f":"שמואל","b":"מחכמי שלוניקי. הגיה \"מעט מים\" לר אברהם נחמן הכהן-תרלז. חיבר פזמונים ובקשות וחלקם נדפסו. ממיסדי חברת \"ישועה ורחמים\"-תרנג."},{"i":51982,"n":"שאלתיאל, אברהם משלוניקי","dt":"תקלח","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":51983,"n":"שאלתיאל, ביניקו משה","b":"מראשי קהלת שלוניקי-תרפא."},{"i":51984,"n":"שאלתיאל, דוד סעדי משלוניקי","dt":"תש..","b":"דיין בשלוניקי. נספה בשואה."},{"i":51985,"n":"שאלתיאל, יהושע","b":"מגדולי חכמי איטליה,מרביץ תורה בבולוניה-ר\"פ"},{"i":51986,"n":"שאלתיאל, יוסף משלוניקי","f":"אברהם","k":"בעל ויוסף אברהם","dt":"תרכג","dp":"שלוניקי","b":"רב בשלוניקי. חיבר דרשות לתורה בשם \"ויוסף אברהם\", ופירוש לפרקי אבות."},{"i":51987,"n":"שאלתיאל, מאיר מירושלים","f":"משולם","b":"תלמיד ביהמ\"ד לרבנים בירושלים. ממיסדי הסתדרות הצעירים הספרדים וחלוצי המזרח."},{"i":51988,"n":"שאלתיאל, משולם מסופיה","f":"אברהם","bt":"תרל","bp":"סופיה-בולגריה","b":"חתן ר יצחק אשכנזי (בנו של הראשל\"צ ר אברהם אשכנזי). עלה לירושלים בעזרת הגביר מאיר מנשה שגדלו, ש\"ץ ב\"אהל משה\" וב\"אוהבי ציון\" לעדת יהודי פרס. פעיל צבור."},{"i":51989,"n":"שאלתיאל, שבתי משלוניקי","dt":"תרס","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":51990,"n":"שאמאנון, יוסף משלוניקי","dt":"תעד","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":51991,"n":"שאמאריל, שלמה משלוניקי","dt":"תץ","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":51992,"n":"שאמי - משפחה","b":"פירוש השם שאמי = דמשק."},{"i":51993,"n":"שאמי, יהודה ממצרים","b":"רב במצרים-סוף שנות ה-ש'."},{"i":51994,"n":"שאמי, יהושע חיים בן ציון מירוש","bt":"תרלד","bp":"ירושלים","b":"רופא בחברון-תרנט, יפו, פעיל צבור."},{"i":51995,"n":"שאמי, יצחק מחברון","f":"אליהו","k":"בעל עקדה","bt":"תרמח","bp":"חברון","b":"מורה במושבה עקרון, דמשק, בולגריה, עסקן צבור, פרסם מאמרים ב\"השופר\", חזר לארץ-תרעט, עבר לטבריה, חיפה. חיבר ספורים."},{"i":51996,"n":"שאמי, עובדיה מירקדו מקושטא","bt":"תרד","bp":"קושטא","dt":"תרפז - אדר","dp":"תל אביב","b":"על בנערותו לירושלים והיה אצל דודו - הגביר רפאל נפתלי הלוי. כנר מחונן."},{"i":51997,"n":"שאמי, רפאל מלאריסה","f":"שמואל","b":"מראשי קהלת לאריסה-תמח."},{"i":51998,"n":"שאמעס, אהרן מרקיטנא","f":"יעקב אליהו","bt":"תרלג","dt":"תשב - יד אלול","b":"תלמיד כולל קובנא. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי, ר אלתר מקונסטנטין, ר יצחק שלמה יואל מראוונא, ר יחיאל מיכל טיבמן מסלאויטא. רב ברקיטנא-ווהלין-תרסח."},{"i":51999,"n":"שאנג'י - משפחה","b":"משפחה בספרד ובתורכיה."},{"i":52000,"n":"שאנג'י ן, אברהם מדמשק וקושטא","f":"אפרים","b":"מחכמי דמשק-רן וקושטא, והיה מגיה בדפוס קושטא. מליצה ממנו ב\"שורש ישי\" למהר\"ש אלקבץ, נזכר בשו\"ת ר בצלאל אשכנזי, ועוד."},{"i":52001,"n":"שאנג'י ן, אישטרוק מסופיה ירוש","f":"דוד מניקופול","bt":"של","bp":"ניקופול","dt":"תג-ד","dp":"ירושלים","b":"תלמיד ר שלמה הכהן-המהרש\"ך בשלוניקי, ראש ישיבה, מחכמי ניקופול, רב בקושטא, בסופיה-שמ(או שן) ור יעקב נפתלי על מקומו אחריו-שעו (בשנת שנב נתמנה ע\"י רבו-ר שלמה הכהן - לפשר במחלוקת בין ר אהרן מלטי ור יוסף אלבו), רצה לעלות לירושלים והתעכב בקושטא בבית ר ישראל בנבנישתי (אביו של בעל \"כנסת הגדולה\" המזכירו בספרו) ולדעת רוזניס בביתו של ר חיים בנבנישתי, ויש אומרים שעלה לירושלים. מוזכר \"בשיירי כנסת הגדולה\" ב\"גט פשוט\" ו\"עזרת נשים\" לר משה בן חביב. גם אביו היה מרבני קושטא.כתביו אבדו במהלך השנים. עלה לירושלים ונספד בידי ר עזריה פיגו בספר \"בינה לעתים\", וב\"אור מאיר\"."},{"i":52002,"n":"שאנג'י ן, אליהו משלוניקי","dt":"תפט","dp":"ירושלים","b":"מרבני שלוניקי, ברח בגלל רדיפת השלטונות שתבעו מס גם מתלמידי חכמים, עלה לירושלים. ממשפחת ר אליעזר שאנג'י בעל \"דת ודין\", ונצר לר אפרים שאנג'י רופא המלך אלפונסו, שוגרש מספרד והגיע לחצר הסולטן בתורכיה. בנו ר יצחק היה גם הוא מרבני שלוניקי ובספרו \"באר יצחק\" הביא מתורת אביו. נספד בספר \"טירת כסף\" דרוש ג, ובספר \"יקרא דשכבי\" דרוש קח."},{"i":52003,"n":"שאנג'י ן, אליהו משלוניקי","b":"מדפיס בשלוניקי-תקמה אצל דוד ישראליג'ה ומרדכי נחמן."},{"i":52004,"n":"שאנג'י ן, אליעזר מקושטא","f":"נסים","k":"בעל דת ודין","bt":"תכ","bp":"קושטא","dt":"תעב","dp":"קושטא","b":"תלמיד ר יוסף קצבי. דיין בקושטא, נשא ונתן עם ר יהודה רוזניס, ומהר\"ם שלטון. דיינים עמו - ר אהרן רומנו, ר שבתי לילו, ר יוסף אשכנזי, ר יוסף קצבי. רוב כתביו אבדו בשריפה בקושטא-תעב, ובנו ר חיים הו\"ל משארית כתביו את \"דת ודין\" קושטא תפב."},{"i":52005,"n":"שאנג'י ן, אפרים מספרד - א","b":"מחכמי ספרד. השתתף בויכוח עם הנוצרי ניקולאי די ואלנסיא בימי דון פדרו מלך אראגון. נזכר ב\"שבט יהודה\"."},{"i":52006,"n":"שאנג'י ן, אפרים מספרד וקושטא","b":"מגדולי חכמי ספרד, רופא למלך אלפונסו מפורטוגל, עבר לקושטא-רמה והיה רופא השולטן מוחמד השני. בניו: ר משה, ר מאיר, ר נסים-המשורר. חתנו - ר יעקב בונשיניור."},{"i":52007,"n":"שאנג'י ן, דוד מקושטא וניקופול","dt":"שמב","b":"גביר מחכמי ניקפול, קושטא-של בזמן המהרש\"ק. בניו ר אישטרוק ן שנגי - רב בקושטא, ר ציון. נספד ב\"בית נאמן\"."},{"i":52008,"n":"שאנג'י ן, חיים אברהם אליעזר","dt":"תקנג - כא אייר","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקלז בשליחות \"בית אל\" ועל כתב שליחותו חתם ר יום טוב אלגזי."},{"i":52009,"n":"שאנג'י ן, חיים מקושטא","f":"אליעזר","b":"רב בקושטא-שנות ה-ת'."},{"i":52010,"n":"שאנג'י ן, יהודה מגליפולי","b":"מחכמי שלוניקי, רב בגליפולי-תך בערך."},{"i":52011,"n":"שאנג'י ן, יעקב מקושטא","f":"נסים","k":"תנו רבנן","dt":"תנו","dp":"קושטא","b":"רב בקושטא-שנות ה-ת'. אחיו הצעיר של ר אליעזר מקושטא."},{"i":52012,"n":"שאנג'י ן, יעקב מרודוס","bp":"קושטא","b":"שו\"ב ברודוס-תץ."},{"i":52013,"n":"שאנג'י ן, יצחק משלוניקי","f":"אליהו","k":"בעל באר יצחק","bt":"תמג או תע","bp":"קושטא או שלוניקי","dt":"תקיט - ט תמוז","dp":"ירושלים","b":"תלמיד ר מרדכי עזריה, ר שלמה אמריליו. סופר, דיין ורב הכולל בשלוניקי, והחזיק ישיבה בביתו מיסודו של הגביר יצחק שלום מלארסו(=לאריסה). רבה של קושטא, אחר פטירת מחותנו ר דוד סירירו. נאסר ע\"י השלטון כדי ללחוץ על הקהלה בענין המס. עלה לירושלים-תקיז והיה מחברי \"בית אל\"-תקיח (אחד מ-24 המקובלים שם). חיבר \"באר יצחק\" שלוניקי תצה, \"בארות המים\", \"באר לחי\", ועוד. חתניו: ר יוסף נחמולי שהספידו בספרו \"אשד הנחלים\", ר יעקב שירירו, ר יצחק הירירה, ר וידאל שבתי."},{"i":52014,"n":"שאנג'י ן, מאיר מקושטא","f":"אפרים מספרד וקושטא","dt":"תה - אחרי","b":"משורר, פוסק, רב בקושטא. מחברי המשורר - ר גדליה ן יחיא."},{"i":52015,"n":"שאנג'י ן, משה מקושטא","f":"אפרים מספרד וקושטא","b":"רב בקושטא-שכז, משורר. מתורתו בשו\"ת ר מאיר די בוטון."},{"i":52016,"n":"שאנג'י ן, משה מקושטא - ב","b":"דיין בקושטא-שנות ה-ת' אצל ר יום טוב ן יקר, חתום על כתב המינוי למשלחת שמונתה לחקור אודות נתן העזתי."},{"i":52017,"n":"שאנג'י ן, נסים מספרד","f":"אפרים","b":"חכם מגדולי משוררי ספרד ועבר לקושטא-רץ."},{"i":52018,"n":"שאנג'י ן, נסים מקושטא - ב","f":"אפרים","bp":"קושטא","b":"משורר מחכמי קושטא, עבר לשלוניקי והיה מחברי בית המדרש לשירה של ר משה ן יחיא, נדד בארצות שונות ובהם בהודו."},{"i":52019,"n":"שאנג'י ן, נסים מקושטא - ג","f":"יהודה הרופא בן נסים","b":"רב בקושטא-שנות ה-ת'. בניו - ר אליעזר בעל \"דת ודין, ור יעקב."},{"i":52020,"n":"שאנג'י ן, ציון מניקופול","f":"דוד","b":"רב בניקופול על מקום ר יצחק ן משה ביג'ה. אחיו - ר אשטרוק. נזכר ב\"עזרת נשים\"."},{"i":52021,"n":"שאנג'י ן, שלמה מירושלים","b":"מחכמי ירושלים בשנת שפה בזמן פרעות אבן פארוך."},{"i":52022,"n":"שאנג'י ן, שלמה משלוניקי","b":"רב בשלוניקי-תרס."},{"i":52023,"n":"שאנג'י ן, שלמה משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה."},{"i":52024,"n":"שאנג'י ן, שמואל מירושלים","dt":"תקכז - ד סיון","dp":"ירושלים","b":"רופא מחכמי ירושלים."},{"i":52025,"n":"שאנג'י, מינטיש משלוניקי","b":"מראשי קהלת שלוניקי-תרפא. נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":52026,"n":"שאנטיש די, יוסף","b":"מחכמי ספרד, מתלמידי ר יונה החסיד מברצלונה. עלה לעכו בשנת נ (1290) בערך והיה מרבניה. חליפת שות בינו לרשבא ומובא בשות הרשבא."},{"i":52027,"n":"שאפיט, אהרן יהושע מקוברין","f":"מאיר מארים מקוברין","b":"בנו של מחבר \"ניר\" על הירושלמי. עלה לארץ והתישב בטבריה."},{"i":52028,"n":"שאפיט, בצלאל חיים מויאזין","f":"מאיר מארים מקוברין","b":"בנו של מחבר \"ניר\" על הירושלמי. אב\"ד ויאזין."},{"i":52029,"n":"שאפיט, מאיר מארים מקוברין","f":"משה פסטירינר","k":"בעל ניר, לולאות","bt":"תקס","dt":"תרלג-ד - י חשון","b":"תלמיד ר נח מלכוביץ, ר משה מקוברין, ר אברהם מסלונים. בגיל 15 כונה בידי האדמור ר יצחק מנסכיז \"הגאון הצדיק\". רב במייצט-תקעה - בהיותו בן 15, וישנובה, שוינצין, יאקובשטט, קוברין. מתלמידיו ר זלמן סנדר כהנא-שפירא. בניו: ר בצלאל חיים מויאזין, ר אהרן יהושע מקוברין. חתנו ר יצחק מתתיהו סנדברג.","bk":[["ללאת – מ\"מ מבבלי לירושלמי \\ לולאות",""],["ניר – ירושלמי",""]]},{"i":52030,"n":"שאפלך, אליעזר","b":"תלמיד החת\"ס. דיין-תקצט. תשובה אליו ב\"חתם סופר\"."},{"i":52031,"n":"שאפפליך, אנשיל מרוסהיים","b":"רב בעיר רוסהיים בעלזס. חיבר ספרים בכת\"י."},{"i":52032,"n":"שאפר, אבא שבתי מארה\"ב","k":"ד\"ר שאפר","bp":"בויסק","b":"תלמיד ר הלל הכהן קליין, ר עזריאל הילדסהיימר. חתן ר אלכסנדר משה לפידות. רב קהלת \"שארית ישראל\" בבולטימור."},{"i":52033,"n":"שאפר, אליעזר מפרשבורג","bp":"טרעבושאן","dt":"תש..","dp":"אושוויץ","b":"הגיע מטרעבושן-סלובקיה אחרי מלחה\"ע ה-I, תלמיד ה\"דעת סופר\" בישיבת פרשבורג, מזכיר משרד כולל אונגרין בפרשבורג, מקורב לציונות. נספה בשואה."},{"i":52034,"n":"שאפרנה, דוד","b":"מחכמי טורקיה בזמן המהרשד\"ם"},{"i":52035,"n":"שאץ, מרדכי מסויסלאץ","k":"בעל תורת מרדכי","b":"אב\"ד סויסלאץ"},{"i":52036,"n":"שאקו, דוד יהודה הכהן מירושלים","f":"יצחק בכור","bt":"תרלז","bp":"ירושלים","b":"חבר בועד העדה הספרדית בירושלים."},{"i":52037,"n":"שאקו, דוד יהודה יהושע הכהן","bp":"בוקרשט","dt":"תרכא","dp":"ירושלים?","b":"חתן הראשל\"צ אג\"ן. מחכמי ירושלים. בניו - ר רפאל יהושע, בכור יצחק, שלמה."},{"i":52038,"n":"שאקו, יהודה הכהן מירושלים","f":"רפאל יהושע","bt":"תרכא או תרלח","bp":"ירושלים","b":"למד בישיבת \"תפארת ירושלים\"-תרסא, מרביץ תורה, סופר ומזכיר בי\"ד במצרים, דיין בירושלים-תרסט, משגיח בישיבת \"פורת יוסף\", כתב חידושים ופסקים בהלכות שחיטה וטריפות, פרסם מאמרים ב\"המאסף\"."},{"i":52039,"n":"שאקו, נסים הכהן מירושלים","b":"מקובל מחכמי \"בית אל\" בירושלים."},{"i":52040,"n":"שאקו, רפאל יהושע הכהן מירושלים","f":"דוד יהודה יהושע","bt":"תריז","bp":"ירושלים","dt":"תרפט - טז שבט","dp":"ירושלים","b":"מחכמי ירושלים בשנת תריז, חתן ר אברהם פנסו. בשנת תרמה בשליחות בתורכיה אפריקה והודו. דיין אצל ר וידאל חנוך אנגל. חידושיו ב\"המאסף\" ובכתב יד."},{"i":52041,"n":"שאקי, אברהם חי","f":"רפאל עובדיה","k":"בעל שער הקדיש","dt":"תרס","b":"מחכמי קושטא, עלה לצפת וחתם עם ר שלמה יוסף חכים, היה ראבד בצפת לפני ר חיים סתהון, חיבר ספר בכתב יד \"שער הקדים (הקדיש?)\", תשובה שלו בספר \"מעשי איש\" על אהע\"ז."},{"i":52042,"n":"שאקי, אלברט משלוניקי","b":"רופא בשלוניקי-תרס - בבית החולים האיטלקי (שהיה בו מחלקה כשרה)."},{"i":52043,"n":"שאקי, ג'יליבי סימן טוב מקושטא","b":"גביר בקושטא, עזר לקהלת אזמיר-תקנב להקים מחדש את בתי הכנסת שנהרסו בשריפה-תקכב עם מאיר אג'ימאן ושלמה קאמונדו. היה מחלוקת בינו יחד עם שותפו שלמה קאמונדו לבין רבה של אדרינופול ר מרדכי בכמוה\"ר מנחם."},{"i":52044,"n":"שאקי, דוד משלוניקי","dt":"תקיז - בערך","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":52045,"n":"שאקי, זכריה משלוניקי","dt":"תקא","dp":"שלוניקי","b":"גביר בשלוניקי. נפטר במגיפה-תקא."},{"i":52046,"n":"שאקי, חיים יצחק מקושטא","k":"בעל מילי דאבות","r":"מרבני קושטא","bt":"תריג","bp":"איסטיפול ליד איסטנבול","b":"תלמיד ר שלמה קמחי. רב בקושטא, חבר בית הדין הגדול. חיבר ספרים בלדינו.","bk":[["טריזורו דיל ז'ודאאזימו - אבות",""],["לה איסטוריה אוניב'ירסאל – תולדות עם ישראל בי\"ג כרכים",""]]},{"i":52047,"n":"שאקי, יהודה מבואנוס איירס","b":"מורה בצפת, מטולה, צידון, ביירות, התישב בבואנוס איירס-ארגנטינה."},{"i":52048,"n":"שאקי, יהודה מקושטא וצפת","f":"אברהם חיים","dt":"תקצז","dp":"צפת","b":"רב בקושטא, עלה לצפת והיה מחכמיה ואחר כך לרב, נספה ברעש."},{"i":52049,"n":"שאקי, יוסף עובדיה משלוניקי","k":"שלוניקי","dp":"תרסח","b":"מחכמי שלוניקי-תרס."},{"i":52050,"n":"שאקי, יצחק בכור הכהן","bt":"תרא או תרכא","dt":"תרסו - כג אייר","dp":"ירושלים","b":"מחכמי ירושלים, דיין אצל ר יוסף רפאל עוזיאל, בשליחות בבלקן, ש\"ץ אצל הגביר מאיר גאני. מחדושיו ב\"שערי רחמים\" לחרי\"ף."},{"i":52051,"n":"שאקי, יצחק משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":52052,"n":"שאקי, יצחק משלוניקי","b":"קומוניסט, נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":52053,"n":"שאקי, סימן טוב מקושטא","b":"ג'יליבי (שר) בקושטא, מקורב למלכות-תקסו."},{"i":52054,"n":"שאקי, עובדיה מלאריסה","b":"מראשי קהלת לאריסה-תמח."},{"i":52055,"n":"שאקי, עובדיה מצפת","f":"אברהם חי","k":"בעל משלי אמת","bt":"תרמח (תרצח?)","bp":"צפת","b":"מחכמי צפת, בשליחות בחו\"ל."},{"i":52056,"n":"שאקי, רפאל אברהם (עובדיה)","k":"בעל שמן ראש","b":"מחכמי באלאט-קושטא-תקף. נזכר אצל ר חיים פלאג'י ב\"כף החיים\". חתם על מכתב רבני צפת-תרה (עלה לארץ?). בנו - ר חיים."},{"i":52057,"n":"שאקי, שלמה הכהן מירושלים","bt":"תריט","bp":"ירושלים","dt":"תרעז - יב אייר","dp":"ירושלים","b":"מחכמי ירושלים ומבין חכמי \"בית אל\"."},{"i":52058,"n":"שאראלט - משפחה במינסק","b":"משפחה עשירה במינסק, היו מוקירי תורה ולקחו לבנותיהם חתנים מיוחסים."},{"i":52059,"n":"שאראנו, יהודה משלוניקי","b":"דיין בשלוניקי-של."},{"i":52060,"n":"שארגער, ליפמן מיעמרינג","bp":"געוויטש (מעהרין)","dt":"תקצז - כו סיון","dp":"יעמרינג","b":"תלמיד החת\"ס. חתן ר אברהם שיק מראב. רב בקאלרי-תקסו, רבה הראשון של יעמרינג-תקעז (במורשת הונגריה - תקף). תשובה אליו ב\"חתם סופר\"."},{"i":52061,"n":"שאריליו, שלמה","b":"דיין. נזכר בשות מהרשד\"ם, חתם בשות \"אהלי תם\" לר תם ן יחיא."},{"i":52062,"n":"שארין, אברהם יואל מזכרינא","f":"דוד שארין","b":"רב בזכרינא-תק\"צ"},{"i":52063,"n":"שארין, דוד","f":"פנחס שארין","b":"בנו - ר אברהם יואל מזאכרינה."},{"i":52064,"n":"שארין, חיים מזכרינא","f":"אברהם יואל שארין","k":"בעל דברי חיים","b":"מקובל,רב בזכרינא-תר\"י"},{"i":52065,"n":"שארין, יואל","k":"העילוי מפולטובה","bt":"תרלא","dt":"תרפז - יא אב","b":"מגדולי חכמי דורו,מרביץ תורה בוואהלין"},{"i":52066,"n":"שארין, פנחס"},{"i":52067,"n":"שארלין-ספרא, חיים מנדל מירושלי","k":"בעל לחם שערים","b":"ספרא ודיינא בירושלים-תרע. חתם שמו \"חיים מנדל סד\"ד\". חיבר גם \"אמרי שפר\"."},{"i":52068,"n":"שארפהארץ, ישראל דוד משברשין","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אסיפת חכמים\" - מלניץ תרפח, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"הכרם\" - וארשא תרצא, \"הנשר\" - טירנוי תרצג-תשד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"תצא תורה\" - קריניצה תרצא."},{"i":52069,"n":"שארקי, חיים ממצרים","b":"מחכמי אלכסנדריה-שסב."},{"i":52070,"n":"שארקי, מכלוף מאלגיר","bt":"תך","dt":"תץ - בערך","b":"רב באלגיר, וחתם על שטר מתנה - נזכר ב\"אהל דוד\" אוכספורד 1932."},{"i":52071,"n":"ש\"ב, יצחק משטמפן","b":"דיין בשטמפן, נבחר-תקסז למלא מקום ר לוי פולק אך לא כרב ראשי."},{"i":52072,"n":"ש\"ב, פיישל","b":"תלמיד הכת\"ס, ור אליעזר רוזנר מנייטרא ומהרם שיק. רשם את תורת רבו הכת\"ס ונדפס ממנו - תרטז פרשבורג."},{"i":52073,"n":"שבאבו - משפחה","b":"משפחה במזרח שמקורה באשכנז."},{"i":52074,"n":"שבאבו ידיע זיין, יהושע ממצרים","b":"מדפיס אצל ר יונה בן יעקב אשכנזי בקושטא-תע. (ואולי הוא טעות והכוונה לרב ממצרים בשם זה שהדפיס את ספרו שם \"מטה יוסף\")"},{"i":52075,"n":"שבאבו ידיע זיין, ישועה ממצרים","f":"אברהם","k":"בעל פרח שושן","bt":"תל","dt":"תצח - תקט","b":"תלמיד ר אברהם בן מרדכי הלוי בעל \"גנות ורדים\", ור יצחק אריפול. רב במצרים, עלה לצפת-תפו. חתן ר יוסף הלוי נזיר מקהיר בעל \"מטה יוסף\" והו\"ל את ספר חותנו, רב במצרים על מקום חותנו. חיבר גם \"שערי ישועה\", \"שערי אורה\", ו\"שערי תורה\"."},{"i":52076,"n":"שבאבו, אברהם חיים","b":"מחכמי צפת, שד\"ר-אלול-תר\"ל"},{"i":52077,"n":"שבד, צמח","f":"יוסף זליג","k":"בעל אוטאביאגרפיע","bt":"1864","bp":"וילנא","dt":"1935","dp":"וילנא","b":"למד רפואה במוסקבה. רופא בוילנא-1894. פעיל ציבור ומיסד בתי ספר של ערב לנשים. ציר בועידת ההשכלה בפטרבורג. ממיסדי המפלגה העממית. השתתף במהפכת 1905 והוגלה לחו\"ל. פעיל בועד העזרה \"אזע\". חבר עירית וילנא. ממיסדי \"החברה האתנוגרפית\" ו\"ייווא\". חבר הסנט הפולני. פרסם מאמרים מדעיים ופרסם חוברות באידיש בנושאי רפואה. עורך קבצים שונים ובהם \"ווילנער זאמלבוך\"-תרעז."},{"i":52078,"n":"שבדרון, יוסף מפרוביזנא","f":"יצחק","k":"בעל פרטי התנאים","bt":"תרמא","b":"נכד המהרש\"ם וגדל אצלו, העתיק את תשובות זקנו בספר שממנו נדפסו, והוסיף הערותיו בר\"ת: א\"ה נ\"ה. חתן הגביר ר יצחק גוטספלד מפרוביזנא, ועבר לשם. עלה לארץ-תרצב והתישב בהרצליה. חיבר \"פרטי התנאים והנהגתה פה פראבוזנא\" דרוהוביטש תרעג."},{"i":52079,"n":"שבדרון, יעקב מקולומיאה","f":"משה מביניוב","k":"בעל שושנת יעקב","bt":"תר","b":"עבר מביניוב (ליד זלוטשוב) לקולומיאה. חסיד זידיטשוב. אחיו של המהרש\"ם. נפטר ללא ילדים. חיבר \"שושנת יעקב\" - נדפס בתוך ספר אחיו \"משפט שלום\", וכן \"זכר זאת ליעקב\" בתוך \"דעת תורה גילוי דעת\" לאביו."},{"i":52080,"n":"שבדרון, יצחק הכהן מחאצמיר","f":"שלום מרדכי - המהרש\"ם","k":"בעל מנחת יצחק","bt":"תרטז","dt":"תרף","dp":"ירושלים","b":"חתן ר יעקב וינטקוריב מטלומטש. ניהל את אחוזת טרגוביצה של חותנו. רב בחאצימירש (חצי עמר). עלה לירושלים-תרסג (ויש אומרים תרעד), והיה דיין אצל רא\"צ שור (עם ר שלמה אהרן ורטהימר, ור אברהם חיים איפ). בנו ר שלום מרדכי - המגיד הירושלמי - מהדיר ספרי אביו וזקנו. חיבר \"עין הרועים\", \"מנחת יצחק\" על התוספתא - ירושלים תרע. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":52081,"n":"שבדרון, יצחק מזלוטשוב","f":"משה מביניוב","bt":"תרח","dt":"תרעח","dp":"וינה","b":"התגורר באחוזת המשפחה בביניוב (ליד זלוטשוב). חתן ר אשר זליג גלרנטר מבורשטין. גביר ת\"ח ומשכיל. התקרב לציונות התכתב עם הרצל, וביקר בארץ. אחיו של המהרש\"ם."},{"i":52082,"n":"שבדרון, משה","f":"שלום","k":"אבי המהרשם","dt":"תרמג","b":"אביו של המהרש\"ם. חתן ר אשר אנשל מרדכי, ונכדת ר יעקב דרעזין (שדודו זקנו היה ר מרדכי מנריוב נכד הבית יוסף - ר יוסף קארו). בעל ביח\"ר ליי\"ש באחוזת ביניוב (ביענוב) ליד זלוטשוב. עסק רוב זמנו בתורה."},{"i":52083,"n":"שבדרון, משה מהליטש","f":"יצחק מחוצמר","k":"בעל מצבת אהרן","bt":"תרמד","dt":"תרעו","dp":"וינה","b":"חתן הגביר מיקולינצר מאלסק. רב בהליטש. חיבר \"מצבת אהרן\" דרוהוביטש תרסח."},{"i":52084,"n":"שבדרון, משה מזברז","f":"משה מביניוב","dt":"תרפח - ג ניסן","b":"אחיו של המהרשם. חסיד בויאן."},{"i":52085,"n":"שבדרון, צבי הירש מבוברקא","f":"שלום מרדכי - המהרש\"ם","bt":"תרכד","dt":"תש","b":"חתן ר משה ב\"ר יגיד מבוברקא, עבר אליו לבוברקא, לצורטקוב ולבסוף בלמברג-תרס. נספה בשואה. הוציא לאור את ספר \"דרכי שלום\" לאביו."},{"i":52086,"n":"שבדרון, שלום מברזן","f":"אליהו","b":"חסיד פרימישלן. חתן נכדת רצ:ה מגלינא. זקנו של המהרש\"ם."},{"i":52087,"n":"שבדרון, שלום מרדכי מברזן","f":"משה מביניוב","k":"מהרש\"ם מברזן","r":"המגיד הירושלמי, מו\"ל וכותב הערות על ספר דעת תורה","bt":"תקצה","bp":"ביניוב (ליד זלוטשוב)","dt":"תרעא - טז שבט","b":"מגדולי הפוסקים בדורו. מקורב לגדולי האדמורים, נחשב אצל אדמורי בלז לפוסק העיקרי. חסיד זידיטשוב, צורטקוב, והוסיאטין. נחשב ליורשו של ר יואל נתנזון בעל השו\"מ כמשיב הדור. חתן ר אברהם יקיר מבילקמין, ועבר לשם. חזר לזלוטשוב. רב בפוטיק-זלוטי-תרכז, יזלוביץ ותלמידו ר מאיר ארק על מקומו אחריו, בוצאץ-תרמא ועל מקומו אחריו ר מאיר ארק, ברזן על מקום ר יצחק שמלקיס. סירב להצעות רבנות שונות ובהם רב ראשי באמריקה. ענה לשאלות מכל הארצות ובין השואלים \"החפץ חיים\". חיבר \"משפט שלום\" למברג תרלא, ועוד. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד, \"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא, \"קובץ מפרשי התורה\" - מארגרטן תרצג, \"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["דעת תורה אורח חיים","מפרשי שו\"ע"],["גילוי דעת – טריפות",""],["גליונות מהרש\"ם – ירושלמי ועוד",""],["דעת תורה – או\"ח ויו\"ד",""],["דרכי שלום – כללי הש\"ס ופוסקים",""],["הגהות מהרש\"ם – ש\"ס",""],["מהרש\"ם",""],["משפט שלום",""],["תכלת מרדכי – עה\"ת",""],["הגדת ר' שלום",""],["הוא היה אומר - אבות",""],["לב שלום - דרשות",""],["קול חוצב - ביוגרפיה",""],["שאל אביך ויגדך - סיפורים",""],["שו\"ת מהרש\"ם",""],["דעת תורה",""],["מהרש\"ם (שו\"ת)",""],["משפט שלום - חו\"מ",""],["עין הרועים",""],["תכלת מרדכי - דרשות",""],["דעת תורה הקדמות ליורה דעה","מפרשי שו\"ע"],["דעת תורה פתיחות ליורה דעה","מפרשי שו\"ע"],["דעת תורה יורה דעה","מפרשי שו\"ע"],["דעת תורה מי הדעת","מפרשי שו\"ע"],["דעת תורה קונטרס אחרון","מפרשי שו\"ע"],["דעת תורה הוראות איסור והיתר","מפרשי שו\"ע"],["דעת תורה נספחים ליורה דעה","מפרשי שו\"ע"],["דעת תורה שו\"ת דרכי שלום","מפרשי שו\"ע"],["מהרש\"ם","שו\"ת - אחרונים"]],"e":"תקצ\"ה-תרע\"א"},{"i":52088,"n":"שבדרון, שלום מרדכי מירושלים","f":"יצחק מחוצמר","k":"המגיד הירושלמי","bt":"תרעג","bp":"ירושלים","dt":"תשנח","dp":"ירושלים","b":"תלמיד ישיבות לומזה וחברון. ר\"מ בישיבת מקור חיים. ההדיר ספרי זקנו - המהרש\"ם, ואת \"לב אליו\" לר אליהו לפיאן. חתן ר חיים ליב אוירבך, והיה גיסו של שלמה זלמן אוירבך. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא. מעורכי \"אוצר הפוסקים\" - ירושלים תשו."},{"i":52089,"n":"שבדרון-שרון, אברהם","f":"יצחק מזלוטשוב","bt":"תרלח","bp":"ביניוב","dt":"תשיח","b":"ד\"ר לכימיה ופילוסופיה. החליף שם משפחתו לשרון וניהל את נכסי אביו. אסף כתבי יד ותמונות של גדולי ישראל. הצליח להעלות עמו את האוסף לירושלים-תרפז והעביר אותו לספריה הלאומית ושימש כמנהלו מטעם הספריה. חתן דב פרידברג."},{"i":52090,"n":"שבות, אהרן מחלב","b":"רב בארם צובה"},{"i":52091,"n":"שבזי, יוסף ממשתא","b":"מגדולי משוררי ופייטני תימן-שנת ת'"},{"i":52092,"n":"שבזי, שלום מתימן","f":"יוסף בן ישראל","k":"בעל מדרש חמדת הימים","r":"מאורה של יהדות תימן","bt":"שעט","bp":"נגד אלוליד-תימן","dt":"תע - ט שבט","dp":"תימן","b":"מחכמי תימן וגדול המשוררים בה, למד אצל חכמי צנעא, התישב בשבז-תימן, ועבר לתעיז הסמוכה. הכיר את חכמי צנעא בזמן גלות מוזע-תלט. חיבר גם \"כתאב אלזיג\", ועוד. מיוחס לו \"ספר החול - גורל החול\" מונקטש תרלד, כנגד מסית גוי בשם \"אבן אלואן\" שסחף יהודים וגויים אחריו ב\"מעשי נסים\" שעשה, ור שלום פעל להחזיר יהודים שהתפתו ללכת אחריו. חיבר שירים ופיוטים רבים ובהם על גזירת העטרות שסופה גלות מוז\"ע ושבה נספו מרבית יהודי תימן, על שבתי צבי, ועוד מאות שירים. בניו מרי שמעון שכיהן כראב\"ד, יהודה שנפטר צעיר ובנותיו - מרים שנפטרה צעירה והזכירה בשיריו ושמעה שקברה הפך למקום עליה לרגל. יש אומרים תאריך פטירתו - תנה.","bk":[["גורל החול - גורלות",""],["חמדת ימים - על התורה",""],["חפץ חיים - שירה",""],["כתאב אלזיג - אסטרולוגיה",""],["ספר המרגלית - תפילות שונות, קמיעות, סגולות ועוד",""],["ספר השירים הגדול והשלם",""],["פירוש על הלכות שחיטה",""],["שימוש תהלים - לאמירת תהילים לפי הצרכים",""],["תכלאל משתא שבזי - סידור מכתב ידו",""]]},{"i":52093,"n":"שבזי, שמעון מתימן","f":"שלום","k":"בעל ספר המרגלית","bt":"ת","bp":"שרעב-תימן","dt":"תסח - אחרי","dp":"שרעב-תימן","b":"רב ודיין ומשורר בחמיאר-שרעב-תימן. נודע כמלוב\"ן. חיבר עם אביו - ספר המרגלית."},{"i":52094,"n":"שביב מקירואן","f":"יעקב","b":"מרבני קירואן הראשונים - שנות ה-ד'תר'. תשובות אליו מגאוני בבל בתשובות הגאונים."},{"i":52095,"n":"שבלת, אליעזר","bt":"1897","bp":"נאדזינג-פלך וילנא","dt":"1941","b":"תלמיד ישיבת ליטא, ורכש השכלה כללית. תרגם לליטאית את \"שיר השירים\". עתונאי, מתרגם מליטאית עבור \"טאג\" בוילנא, פרסם ב\"אונזער פריינד\" בוילנא, ב\"אידישע שטימע\", ועוד בקובנא. נספה בשואה - בזמן שניסה להימלט מקובנא לרוסיה."},{"i":52096,"n":"שבץ, אליעזר זיידל","b":"רב בקוזיאן-תרצ\"ד"},{"i":52097,"n":"שבצקין, אברהם מפרשבורג וארה\"ב","b":"חזן בפרשבורג, עבר לארה\"ב. פעל משם להצלת בני קהלתו בפרשבורג בזמן השואה."},{"i":52098,"n":"שבשוביץ, פנחס","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":52099,"n":"שבשקביץ, יוסף מהוסטמליא","f":"ברוך","bt":"תרלו","b":"מצאצאי ר מנחם מנדל מבוריסלוב. רב בבאלאווניבקה-פלך קיוב-תרנו, הוסטומול-פלך קיוב-תרסו. נסמך להוראה ע\"י: ר אהרן זאב וייל מקיוב, ר\"ש אהרנסון מקיוב, ר זכריה רוזנפלד מארה\"ב."},{"i":52100,"n":"שבתון, נסים מקהיר","b":"נזכר בספר הדרשות לר חיים חברייא, ועד בפרשת הגט של נסים ענקארי ונזכר בשות מהרם גאביזון."},{"i":52101,"n":"שבתי","k":"ר' שבתי כורך ספרים","b":"עניו-שנת ת\"ק"},{"i":52102,"n":"שבתי","f":"נפתלי צבי"},{"i":52103,"n":"שבתי בכר אליה מקושטא","f":"אליה","b":"סופר הקהל בקושטא-שנות ה-ת'-תק'."},{"i":52104,"n":"שבתי ברוך מארטא","b":"רב בארטא-שנות ה-ש'."},{"i":52105,"n":"שבתי הכהן - הש\"ך","f":"מאיר כץ - גבורת אנשי","k":"בעל הש\"ך","r":"רב ופוסק - רב באמסטיבובה","bt":"שפב","bp":"וילנא-אמסטיבאוו","dt":"תכג - א אד\"א","dp":"הלישוי-מורביה","b":"נכד ר משה מפפד\"מ. מגדולי הפוסקים בכל הדורות. חתן ר בנימין זאב וולף מייזלש מוילנא. נשלח ע\"י אביו ללמוד בקראקא אצל ר יהושע בעל \"מגיני שלמה\", למד גם אצל ר השל בלובלין, וחזר לוילנא וכיהן כדיין אצל ר משה לימא בעל \"חלקת מחוקק\", וחיבר \"שפתי כהן\" - ש\"ך על השו\"ע בגיל 24. היה מחלוקת כנגדו בגלל שחלק על קדמונים ובין החולקים בעל הט\"ז, וא\"ש קידנובר, ועוד. השיב למתנגדיו ב\"נקודות הכסף\". בפרעות תח ברח מהקוזקים מוילנא הגיע ללובלין אך גם משם נאלץ לברוח הגיע למיהרן וכיהן כרב בדרזניץ, חיבר \"מגילת עיפה\" על קורותיו. רב בהלישוי (ר מנחם מנדל בעל \"צמח צדק\" נשאל מקהילת הלישוי אודותיו ושאל את ר השל מלובלין שעבר אצלו בניקלשבורג ור השל ענה לו - ראוי הוא לשבת על מקומך בניקלשבורג וכו'). חיבר סליחות וקינות על גזירות תח, ושירים. תולדותיו ב\"כתר כהונה\" לח.ד. פרידברג. חתניו - ר דוד כתבן בן יצחק מזולקוא, ר מנחם מאניש, ר אהרן מגזע צבי. בניו - ר משה, ר מאיר.","bk":[["ש\"ך",""],["גבורת אנשים (שו\"ת)",""],["דינא דגרמי",""],["תקפו כהן",""]],"e":"שפ\"ב-תכ\"ג","rb":"אמסטיבובה","co":{"a":"53.166667,24.466667","d":"49.338842,17.641807"}},{"i":52106,"n":"שבתי הכהן ידיע יעיש ממצרים","b":"רב במנצורה-מצרים-תסב."},{"i":52107,"n":"שבתי הכהן מאדרינופול","b":"מגדולי חכמי אדרינופולי-ר\"מ"},{"i":52108,"n":"שבתי הכהן מירושלים","f":"יוסף","b":"מחכמי ירושלים, בשנת תסה בשליחות בקורפו ונתמנה לרב שם."},{"i":52109,"n":"שבתי הכהן מקורפו","f":"יצחק","b":"רב בקורפו-ר\"צ"},{"i":52110,"n":"שבתי הכהן משלוניקי","f":"מלכיאל","k":"בעל ספר השם","bp":"יון (האי ניגרופונטי)","b":"מחכמי שלוניקי, בן דורו של הריב\"ש. תלמיד ר זכריה הכהן, רבו של ר מנחם ן תמר. נדד בארצות שונות. חיבר גם \"ארון הברית\", \"ארון העדות\", והשגות על פירושי ראב\"ע ורלב\"ג והיה במחלוקת אודות פירוש האבן עזרא עם ר מרדכי כומיטיאני(=כומטינו)."},{"i":52111,"n":"שבתי הלוי מחוליוב","k":"בעל ציוני ש\"ס","bt":"תרמא","bp":"חוליוב","dt":"תשיח","b":"רב בחצר סדיגורא. ר\"מ בישיבת טשרנוביץ-תרפז, פשמישל. עלה לארץ-תרצג והיה ממיסדי ספרית הרמבם בתל אביב. חיבר \"ציוני ש\"ס\" תל אביב תשיד."},{"i":52112,"n":"שבתי הלוי מקושטא - א","b":"ממונה על איסור והיתר בקושטא-תקב. דיין אצל ר אברהם בן יוסף רוזניס-תקו. חתם על תקנות שונות עם חכמי עירו."},{"i":52113,"n":"שבתי הלוי מקושטא - ב","b":"ממונה על איסור והיתר בקושטא-תרנד, חבר בועד הרוחני על מקום הרב פריסקו-תרנד, אב\"ד-תרסט, סגנו של החכם באשי ר חיים נחום-תרעב. חתם עם פסקים ותקנות רבים."},{"i":52114,"n":"שבתי המכונה בכור וידאל","dt":"תקכב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":52115,"n":"שבתי חביב מיוון","f":"אבישי","b":"פייטן מחכמי יוון בזמן הרא\"ם. פיוטים ממנו במחזור בכת\"י."},{"i":52116,"n":"שבתי יונה משלוניקי","f":"יונה","k":"בעל שי למורא","dt":"שפא - לפני","b":"מחכמי שלוניקי, תלמיד ר אברהם די בוטון בעל \"לחם משנה\", ר אהרן ששון ור יוסף ן עזרא. חיבר גם פירוש על רבינו ירוחם, ועוד. תלמידו ר שמואל גאון הו\"ל את ספרו \"שי למורא\" שלוניקי תיג. בנו ר דוד יונה - הו\"ל את ספרו \"שי למורא - תיג."},{"i":52117,"n":"שבתי יעקב מסעלעצניק","f":"אברהם יצחק מסלצניק","b":"חתן משפחת - באקסט. תלמיד ר ישראל סלנטר. קרוב משפחתם של ר צבי הירש רבינוביץ מקובנא ושל ר אליעזר גורדון מטלז. חתנו - ר יהודה אידלסון מארה\"ב."},{"i":52118,"n":"שבתי מארטא - א","f":"משה","b":"דיין בארטא-ש' בערך, חתם על התיר עגונה עם ר בנימין בעל שו\"ת בנימין זאב."},{"i":52119,"n":"שבתי מארטה - ב","f":"משה","b":"דיין בארטה-תעד בענין השליח ר שמשון גומץ פאטו."},{"i":52120,"n":"שבתי מוילנא","f":"אליעזר","b":"מגדולי ווילנה-תק\"ע"},{"i":52121,"n":"שבתי מוילנא","f":"שבתי","dt":"תקצא - כ תמוז","dp":"וילנא","b":"מנקה ארובות בחצר קריינעס ברחוב היהודים בוילנא. סייע לחבריו ר ברוך חייט, ר יהושע חייט ועוד להקים ישיבה והצליח לגייס כסף והקים את הישיבה בחצר מיילא - וזו היתה ראשתיה של ישיבת מייל'ס בוילנא."},{"i":52122,"n":"שבתי מויניצה וארץ ישראל","b":"עלה לארץ-שנות ה-תקמ'."},{"i":52123,"n":"שבתי מטורנא","b":"רב בטורנא-תרה. תשובה אליו ב\"שם משמעון\"."},{"i":52124,"n":"שבתי מירושלים","f":"אברהם","dt":"תקצה - ט אלול","b":"מחכמי ירושלים, בשליחות בתורכיה והאזור, נתמנה לרב ברוסג'וק-בולגריה על מקום ר אברהם גראסיאני. חיבר דרושים, פירושים ושו\"ת בכת\"י."},{"i":52125,"n":"שבתי ממונשטיר","b":"רב במונשטיר-שץ."},{"i":52126,"n":"שבתי מנירנברג","b":"מגדולי חכמי אשכנז בנירנברג-קע\"א"},{"i":52127,"n":"שבתי מנשה מצפת","b":"מקובל בצפת, מתלמידי האר\"י. חתם עם רבני צפת ונזכר ב\"אבקת רוכל\". מחכמי צפת-רצח, נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים."},{"i":52128,"n":"שבתי מסופיה","f":"שלמה","b":"גביר מחכמי סופיה-תקטו, תמך בהדפסת \"פרי הארץ\" עם חבריו אהרן ושבתי צלמונה. (אולי הוא בעצמו זהה לר שבתי צלמונה?)"},{"i":52129,"n":"שבתי מפיעסק","b":"רב בפיעסק"},{"i":52130,"n":"שבתי מפרמישלא","k":"בעל סדור תפלה","b":"חיבר סדור תפלה - זולצבך, דקדוק על ספר מהלך שבילי הדעת לר משה קמחי."},{"i":52131,"n":"שבתי מקולשין","b":"רב בקאלשין-תק\"ל"},{"i":52132,"n":"שבתי מקעסטהעלי","b":"רב בקעסטהעלי-תק\"ע"},{"i":52133,"n":"שבתי מקראס","b":"רב בקראס. חתן ר יוקיל הורביץ מחברת התחינות."},{"i":52134,"n":"שבתי מראשקוב - הזקן","f":"צבי הירש","k":"בעל סידור רבי שבתי","bt":"תטו","dt":"תקה","b":"מקובל, מחכמי ראשקוב(=רשקוב). תלמיד הבעשט. סופר סת\"ם ומעתיק מומחה של כתבי יד. חיבר \"סידור רבי שבתי\". בנו - ר יוסף תלמידו של ר פנחס מקוריץ, ונכדו - האדמור ר זלמינא מראשקוב."},{"i":52135,"n":"שבתי מראשקוב - הנכד","f":"שלמה זלמינא מראשקוב","k":"אדמור מראשקוב","dt":"תרמג - ח טבת","b":"נינו של ר שבתי מראשקוב תלמיד הבעשט. בניו - ר יחיאל יוסף ור משה אברהם על מקומו אחריו."},{"i":52136,"n":"שבתי מרומא","f":"יצחק מפונטי קורבו","b":"רב ברומא. חתום ב\"מלחמה לה'\"-תעד על החרם נגד נחמיה חיון. תשובה ממנו ב\"בכורי קציר\"."},{"i":52137,"n":"שבתי משלוניקי - ב","f":"אנגל","dt":"תקכא - בערך","dp":"שלוניקי","b":"חתן ר וידאל שבתי והגיה את ספר חותנו \"ספור החיים\". (ראה גם: אנגל, שבתי מירושלים)."},{"i":52138,"n":"שבתי סגל מפלטשין","f":"יצחק דוד","k":"בעל שות הרשביד","bt":"תקץ","bp":"פלשטין-ליד קמניץ פודוליה","dt":"תרסג","dp":"בוהש","b":"נכד ר משה מקיטוב, אחיו של ר ישראל קיטובר מלניוויץ אב\"ד פלטשין. רב ביאסי, מיהלן, סוליצה, רדוביץ, בוהש - כארבעים שנה. חיבר \"שו\"ת הרשבי\"ד\" קלוזש תרפו."},{"i":52139,"n":"שבתי עלי מקושטא","b":"רב בקושטא, נזכר ב\"חיים ושלום\" לר חיים פלאג'י."},{"i":52140,"n":"שבתי צבי מקורג'ישמא","dt":"תקסד - טו כסלו","dp":"אזמיר"},{"i":52141,"n":"שבתי רפאל מירושלים","k":"בעל תעלומות ומקורות","bt":"ת","bp":"יון","b":"הגיע בילדותו לקושטא, עלה לירושלים-תכג. שליחו של ש\"ץ באירופה לבשר את התגלותו. חיבר \"תעלומות ומקורות החכמה...\" - אמשטרדם, והיה מחלוקת עליו מר יעקב ששפורטש שהזהיר \"שלא כיון אל האמת\"."},{"i":52142,"n":"שבתי שלמה משלוניקי","dt":"תיג - יד אד\"א","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":52143,"n":"שבתי שפטל","b":"רב בבאגדע-תקע\"ה"},{"i":52144,"n":"שבתי שפטל הלוי","b":"רב במוגנדורף-תר\"כ"},{"i":52145,"n":"שבתי שתדלן מלובלין","b":"מראשי הח\"ק בלובלין-תסז."},{"i":52146,"n":"שבתי, אברהם","dt":"תרמט - כא אייר","b":"מקובל, מחכמי ארם צובה, , עלה לירושלים"},{"i":52147,"n":"שבתי, גבריאל יהושע מירושלים","f":"גבריאל שבתי יהושע","bt":"תקעג","dt":"תרמא - יח טבת","b":"מחכמי שלוניקי, עלה לירושלים-תרא-תריג. בניו ר חזקיה שבתי, ר גבריאל שבתי."},{"i":52148,"n":"שבתי, גבריאל מירושלים","f":"שבתי יהושע גבריאל","dt":"תרעא - ד חשון","dp":"ירושלים","b":"מחכמי ירושלים, דיין אצל ר יוסף רפאל עוזיאל, חידושים ממנו בספרו של ר רחמים פרנקו \"שערי רחמים\". חתם על תעודות שונות."},{"i":52149,"n":"שבתי, דוד","f":"חיים","dt":"תמט - ז טבת","dp":"שאלוניקי","b":"מרבני ודייני שאלוניקי"},{"i":52150,"n":"שבתי, וידאל משלוניקי","bt":"תכה","dt":"תקו","b":"מחכמי שאלוניקי, דיין-תצ\"ט, פוסק, חתן ר' יצחק ן' שאנגי"},{"i":52151,"n":"שבתי, חזקיה יהושע מירושלים","f":"שבתי יהושע גבריאל","k":"בעל דברי חזקיה","bt":"תרכב או תריא","bp":"שלוניקי","dt":"תשיב-טו - כג אב","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לארץ-תרכח, חתן ר' אלעזר מזרחי שד\"ר ירושלים וחברון למקומות רבים, חבר הרבנות בירושלים-תרנו-תרס, מ\"מ הרב הראשי ביפו-תרס, חכם באשי בטריפולי-תרסד, חכם באשי בחלב-תרסח, אב\"ד בירושלים-תרפו, חבר הרבנות הראשית בירושלים-תש, חיבר \"דברי חזקיה\". פרסם מאמרים ב\"הפוסק\" - תל אביב תש-תשיד, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":52152,"n":"שבתי, חנניה יהושע גבריאל ממצרי","f":"גבריאל שבתי","k":"בעל מנחת החג","bt":"תרלה","bp":"שלוניקי","dt":"תשטז - כו חשון","b":"עלה לארץ עם הוריו בגיל שנה, תלמיד \"דורש ציון\" בירושלים, ישיבת \"תפארת ירושלים\". חתן בת אחי הרב היר\"ח. בין מייסדי בית חינוך יתומים הספרדי בירושלים, דיין-תרסו אצל ר דוד פאפו, ראב\"ד בקהיר-תרפה, אב\"ד בירושלים-תרפט. מתורתו ב\"פני דוד\" לר דוד פאפו. פרסם מאמרים ב\"המאסף\".","bk":[["מנחת החג",""]]},{"i":52153,"n":"שבתי, עזריה חנניה משלוניקי","b":"מורה עברי בוויריה-יון לפני השואה, ניצל מהשואה ואחריה כיהן כרב בשלוניקי. הו\"ל לוח שנתי מטעם קהלת שלוניקי - אחרי השואה."},{"i":52154,"n":"שגילמאס, שמואל משלוניקי","f":"משה","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תע."},{"i":52155,"n":"שדי, מנחם מן","b":"מגדולי חכמי דורו,רב בווינה-ת\"כ"},{"i":52156,"n":"שהרבאני, דוד או שאול מירושלים","f":"יהושע","bt":"תרפ","bp":"ירושלים","dt":"תשלט - כה שבט","dp":"ירושלים","b":"מקובל, בקי בש\"ס, דיין בירושלים עם ר עזרא עטייה. מלמד בפורת יוסף ובת\"ת \"בני ציון\". רב ראשי בקולומביה"},{"i":52157,"n":"שהרבני, יצחק מבגדד","f":"יהושע","dt":"תרפו - טז שבט","dp":"ירושלים","b":"מחכמי בגדד, עלה לירושלים ולמד אצל רש\"א אלפנדרי ולמד בישיבת פורת יוסף. נפטר בחיי אביו (בגיל 25)."},{"i":52158,"n":"שהרבני, מנשה סלמאן מבגדד","k":"בעל אגרת הפורים","dt":"תשך","b":"תלמיד ר משה צדקה ב\"בית זילכה\", ור יוסף חיים טוב. ראש ישיבה בבצרה, מחכמי בגדד ובין תלמידיו - ר סלמאן חוגי עבודי, ר יהושע משה, ור יעקב מוצאפי. בשליחות ביה\"ד בבגדד בקהלות יוצאי בבל בהודו וסין. רב בעמדאן ומחמרה-פרס. עלה לארץ-תשי. חיבר ספרים רבים בכת\"י."},{"i":52159,"n":"שואדישץ, בנימין הכהן מוילנא","f":"משה","k":"בנימין ראדינער","bt":"תקמב","dt":"תריב - טו טבת","dp":"וילנא","b":"תתן ר אליהו הלוי בורדא ראדינער משניפישוק. פרנס וראש הקהל בשניפישוק, דיין בוילנא-תקצא. הסכים על ש\"ס וילנא-תקצה, חתם על כמה פסקים בפנקס הגר\"א, ועוד. נפטר ללא ילדים."},{"i":52160,"n":"שואלב, יוסף מקניהניטש","b":"מחמכי קניהניטש - תלמיד רב\"א וייס מטשרנוביץ אב\"ד קניהניטש שהזכירו בספרו \"אבן יקרה\"."},{"i":52161,"n":"שואלב, מנשה","b":"גביר בעל אחוזה. חתן ר משה פרידמן מזבורוב. בהיותו בשבת בצאנז הדב\"ח קראו לתורה בשם מורנו ובמוצ\"ש קיבל מברק שכל רכושו נשרף - הדב\"ח קרא לפרנסי קהילת קומרניק (מחוז למברג) ששבתו שם גם הם, והם מינוהו לרב הקהלה."},{"i":52162,"n":"שוב שמעון בן יהודה ליב","bt":"1908","dt":"ה'תשנה 1995","bk":[["בית השואבה",""]]},{"i":52163,"n":"שו\"ב, גרשון מוושקביץ","b":"רב בוושקביץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":52164,"n":"שו\"ב, זלמן מברזובקה","b":"ר\"מ בישיבת \"תורה אור\" בברעזובקה, יחד עם ר משה קראקאוו - בראשות ר שלמה לנגר."},{"i":52165,"n":"שוב, יוסף מוילנא","bt":"תרנז","dt":"תשא-ג","b":"תלמיד ישיבת סלובודקא, עבר לוילנא והיה עוזרו של ר חיים עוזר גרודזינסקי, ממיסדי \"ועד הישיבות\"-תרפו, בשליחות \"ועד הישיבות\" באמריקה ומערב אירופה-תרפח. נספה בשואה."},{"i":52166,"n":"שוב, יצחק","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":52167,"n":"שוב, משה","dt":"תשג","b":"רב בקרסלאווע"},{"i":52168,"n":"שובאקס, אברהם יעקב מירושלים","b":"מראשי כולל הפרושים בירושלים, חתם-תרן עם ראשי הכוללות."},{"i":52169,"n":"שובמאן, אליעזר מלובלין","b":"מחכמי לובלין-תרנט?"},{"i":52170,"n":"שודאדה, ישועה מאלגיר","f":"מסעוד","bt":"תל","dt":"תק","b":"רב באלגיר. חתם על שטר מתנה מאלגיר ונזכר ב\"אהל דוד\"."},{"i":52171,"n":"שודאכה, דוד מאלגיר","bt":"תס","dt":"תקל - בערך","b":"רב באלגיר. חתם על מכתב התנצלות של ר יהודה עייאש בענין עיכוב ביציאתו של ר יהודה לארץ ישראל."},{"i":52172,"n":"שודט, יהודה ליב מיערגין","b":"תלמיד החת\"ס. הגיע משטמנסדורף, רב ביערגין-תקצט."},{"i":52173,"n":"שוהם ן, אליהו","b":"תרט\"ו"},{"i":52174,"n":"שוהם ן, משה מתיריא","b":"דיין בתירייא-תקו."},{"i":52175,"n":"שוהם ן, רפאל שבתי מקושטא","b":"ממונה על איסור והיתר בקשוטא-תקעב, ראב\"ד-תקפט. נזכר ע\"י המסיונר וולף-תקפו כאחד מארבעת הרבנים בעיר."},{"i":52176,"n":"שוהם ן, שבתי מקושטא","b":"רב בקושטא-תקפז עם ר שמואל חיים ור אליהו עניו."},{"i":52177,"n":"שוהם, דן ממידן","f":"משה מדולינא","b":"רב במיידן (מרמורש) בהשפעת אדמורי זידיטשוב. חתנו - ר נחמן גרינברג."},{"i":52178,"n":"שוהם, יחיאל דב מארה\"ב","f":"שמואל יוסף","bt":"תרנא","bp":"דארשונישוק-פלך קובנא","b":"תלמיד ישיבת סלובודקא, פוניבז. נסמך מאת: ר משה מרדכי אפשטין, ר ברוך הורביץ מסלובודקא, ר אברהם זאב הלר ממאריאמפול. חתן ר יוסף יעקב מרקוס מזשידק ובולטימור. היגר לארה\"ב-תרפט וכיהן כרב בספירנג ואלי, בולטימור-תרצב. ממיסדי התאחדות תלמידי סלובודקא באמריקה."},{"i":52179,"n":"שוהם, ישראל מוורצקי","f":"משה מדולינא","b":"רב בוורצקי."},{"i":52180,"n":"שוהם, משה מדולינא","f":"דן מברודי","k":"שה\"ם - בעל דברי משה","bt":"תצ","dt":"תקף - כא תשרי","b":"אביו - תלמיד הבעשט שברכו בבן. גדל בבית הבעשט ושמע ממנו תורות שהביא בספרו. רב בדולינא-תקמו על מקום ר אברהם נח הלר. בנו ר שמואל מדולינא שההדיר את ספרו. חיבר \"דברי משה\" מזריטש תקסא, \"שרף פרי עץ חיים\", ועוד. עוד מבניו: ר דן, ר ישראל מוערצקי. (באוצר תאריך פטירתו - תקצב)"},{"i":52181,"n":"שוהם, שמואל יוסף מדרשונישוק","bp":"ראסיין","dt":"תשג","b":"רב בדרשונישוק-תרנא על מקום ר חיים אברהם ש\"ס, ווילקי. נספה בשואה."},{"i":52182,"n":"שוהם, שמואל מדולינא","f":"משה מדולינא","b":"ההדיר את ספרי אביו. נפטר ללא ילדים."},{"i":52183,"n":"שוואב, אברהם","f":"מנחם מנדל","k":"בעל דרכי יושר","b":"חיבר \"דרכי יושר\", \"מליץ יושר\" - בלשון אשכנז."},{"i":52184,"n":"שוואב, יהודה ליב מבודפשט","b":"רב בבודפשט-תקצו - בזמנו הפכה הקהילה לחשובה בקהילות הונגריה. דרשן מפורסם. הקים מוסדות חשובים ופעל לעצור את התפשטות הריפורמים בבודפשט."},{"i":52185,"n":"שוואב, יוסף מזבורוב","bt":"תרמג","dt":"תשג","b":"תלמיד בעל ראל\"ה \"הרי בשמים\". ר\"מ בישיבת אור תורה בסטניסלב. נספה בשואה."},{"i":52186,"n":"שוואב, יצחק מאה\"ו","dt":"תקמט - יא אדר","dp":"אלטונא","b":"חתן ר יצחק גונצהויזן. דיין בקהלת ואנדסבק בהמבורג וחתם עם ר רפאל הכהן-תקמז."},{"i":52187,"n":"שוואב, שמעון מניו יורק","k":"בעל בית השואבה","b":"רב \"עדת ישורון\" בניו יורק."},{"i":52188,"n":"שוואגר, אליעזר ליפא מהוסיאטין","k":"בעל אוצר כלי חמדה","bt":"תרמב","bp":"הוסיאטין","dt":"תשכא","b":"נכד ר דוד ב\"ר אהרן ליפא הגבאי בהוסיאטין. יסד עם גיסו ר דוד פרנקל את חברת \"דובב שפתי ישנים\" - שהוציאו לאור כתבי ראשונים ואחרונים - וכן עסקו במכירת ספרים באמצעות קטלוגים שהופצו בכל העולם. ניצל מהשואה - ספרייתו נשדדה בידי הנאצים, עלה לארץ והתגורר בתל אביב. חיבר \"רשימת ספרים יקרים...\" מונקטש תרסב, \"אוצר כלי חמדה\" תרסו, ועוד."},{"i":52189,"n":"שוואט, יהודה מאלגיר","b":"רב ומשורר בקצמטינא. נזכר ב\"אשכבתא דרבנן\"."},{"i":52190,"n":"שוואט, פרג'י מתונס","bp":"פאס","dp":"תסתור","b":"יליד מרוקו ועבר לתונס. פייטן מחכמי באג'ה-תונס-תס, פיוטיו נפוצו בכל רחבי צפון אפריקה."},{"i":52191,"n":"שוואלבך, יעקב מפפד\"מ","dt":"תקלו","b":"מחכמי פפד\"מ, פרשן תורה מקובל."},{"i":52192,"n":"שוואקס, אברהם יעקב מירושלים","b":"מראשי הכולל בירושלים-תרן."},{"i":52193,"n":"שוואקס, ליפמן דוד מירושלים","f":"מהר\"י","dt":"תרפב-ד - ז אד\"ב","dp":"ירושלים","b":"דיין ומו\"צ בירושלים-תריד (כך באוצר הרבנים). ראב\"ד כוללות החסידים בירושלים, חתם-תרסח עם ר צבי פסח פרנק ור משה נחום ולנשטין."},{"i":52194,"n":"שוובל (שיבל), איתמר מצורטקוב","b":"מחמכי צורטקוב-תרכא. תשובה אליו \"בית שלמה\"."},{"i":52195,"n":"שוובל, אשר ממונט קיסקא","k":"בעל ולאשר יאמר","b":"ר\"מ בישיבת נייטרא במונט קיסקא. חיבר \"ולאשר יאמר\" נ\"י תשכב."},{"i":52196,"n":"שוויכה, אהרן","dt":"תרמא - טו תמוז","b":"מגדולי רבני חלב, נפטר בדרך לכפר תידיף"},{"i":52197,"n":"שווילי, חיים מירושלים","f":"ירמיהו","k":"בעל חזון החיים","bt":"תרסז","bp":"ירושלים","b":"גדל בעיר אוני-קוקז ולמד בישיבה, עבר לקוטאיס, חזר לארץ-תרפא, פרסם מאמרים בעתוני נוער דתי."},{"i":52198,"n":"שווילי, יוסף מירושלים","f":"יעקב חכמי","bt":"תרמו","b":"פעיל צבור בירושלים ותל אביב, יועצו של קונסול אמריקה בזמן מלחה\"ע ה-I ופעל לחלוקת כספי סיוע לנזקקים."},{"i":52199,"n":"שווילי, יעקב מאחיסקא-קווקז","f":"יוסף חכמי","k":"חכמשווילי","dt":"תרנב - כד תמוז","dp":"ירושלים","b":"עלה לארץ-תרכז מראשוני עדת הגורג'ים בירושלים."},{"i":52200,"n":"שווילי, ירמיה מירושלים","k":"חאחיאשבילי","b":"תלמיד ר נסים דאנון, עבר לקוטאיס-בקווקז וכיהן שם כרב-[תרע..]"},{"i":52201,"n":"שווימער יחיאל נתן בן יוסף","bt":"1890","dt":"ה'תשיב 1952","bk":[["חקרי הלכות",""],["קונטרס הלכה",""]]},{"i":52202,"n":"שווינפורט, יעקב","f":"שמואל","b":"מחכמי צפת, בשנת שעג שליח בפרנקפורט, ור יוסף הכהן בעל \"יוסף אומץ\" התיעץ עמו בנוגע ללימוד קבלה. ר אליהו לואנץ כותב ב\"מעגלי צדק\": \"קבלתי מהר\"ר יעקב וכו' שבא מצפת...\"."},{"i":52203,"n":"שווירה, אברהם","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":52204,"n":"שווערד, ישראל","dt":"תשג","b":"רב ברוונא"},{"i":52205,"n":"שוורדורף, אליעזר","b":"רב בלובלין"},{"i":52206,"n":"שוורדורף, דב בר מגורייא","f":"אברהם דוד טבל ברלינר","b":"רב בגורייא"},{"i":52207,"n":"שוורדורף, דב בר מגורייא וטומשו","f":"אליעזר שוורדורף","b":"רב בגורייא,טאמשוב"},{"i":52208,"n":"שוורדורף, מנחם נחום מלוואווא","b":"שו\"ב בלוואווא-פלך חרסון כ-40 שנה, ובנו ר אליהו יהודה ליב - רב בלוואווא."},{"i":52209,"n":"שוורדורף, נחמיה","f":"אליעזר שוורדורף","b":"מו\"צ בלובלין"},{"i":52210,"n":"שוורדורף, שמואל אליהו","f":"אליעזר שוורדורף","dt":"תרלח - ב תמוז","b":"גביר,רב פעלים,קרוב למלכות בבילגורייא"},{"i":52211,"n":"שוורדלוב, אליהו יהודה ליב","f":"מנחם נחום מלוואווא","bt":"תרטו","b":"חתן ר דב טויבר על \"דובב שפתי ישנים\". רב בלאווא-פלך חרסון-תרעה. נסמך מאת: ר שניאור זלמן פינסקר מחרסון, ר פולק מקהלת \"שדה מנוחה\". חתניו - ר אברהם בן שרגא פיבוש טויבר מנאווא-קובנא מיענאקיעייא, ר שלמה בן נחום מניקולייב."},{"i":52212,"n":"שוורדשרף, אליעזר מלובלין","f":"דובריש הלפרין","bt":"תקנז","dt":"תרמא","b":"מחכמי לובלין. (סירב להצעות רבנות טשחיויב ושדלץ). חיבר פירוש להגדה \"דמשק אליעזר\" קולומיאה תרמג."},{"i":52213,"n":"שוורדשרף, דובריש מגוריי","f":"אליעזר מלובלין","b":"רב בגוריי, טומשוב."},{"i":52214,"n":"שוורדשרף, דוד טבל מבילגורי","f":"דובריש מגוריי","bt":"תר","dt":"תרסב","b":"חתן נכדת החכם צבי. מחכמי בילגורי."},{"i":52215,"n":"שוורדשרף, משה יעקב מקולומיאה","f":"דוד טבל מבילגורי","k":"בעל תורת העמים","bt":"תריח","bp":"בילגורי","dt":"תרפב","b":"שם המשפחה מופיע גם - ש\"ש. חתן הנגיד ר שאלתיאל איזיק מקולומיאה. מחכמי קולומיאה, עבר לבודפשט וחזר לקולומיאה. פעל להקמת דת יראת ד' בה יחזיקו גם הגויים - שיקבלו עליהם 7 מצוות בני נח. חיבר \"דעת לנבונים\" מונקטש תרנט, \"תורת העמים\" מונקטש תרנט, ועוד."},{"i":52216,"n":"שוורדשרף, שמואל אליהו מבילגורי","f":"אליעזר מלובלין","dt":"תרלח","dp":"וארשא","b":"חתן ר יחזקאל מאיר פרנקל-תאומים וינברג מבילגורי."},{"i":52217,"n":"שוורדשרף-הלפרין, דובריש","f":"מרדכי מקידאן","bt":"תקי","dt":"תקפד","b":"אביו ר מרדכי היה גיסו של הגר\"א, והיה תלמידו של הגר\"א. רב בלובלין. בחר שם משפחה בגזירת השלטון - שוערדשרף (מוהל) על כי היה מוהל."},{"i":52218,"n":"שוורזענן, ישראל","f":"מרדכי","k":"בעל קהלות ישורון","b":"חיבר \"קהלות ישורון\" תקל."},{"i":52219,"n":"שוורצבוים, יחזקאל צבי מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":52220,"n":"שוורצבוים, יחיאל מיכל מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":52221,"n":"שוורצבוים, יעקב ישעיה מסוסנובי","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":52222,"n":"שוורצבורג, אברהם ליב מארה\"ב","f":"יום טוב","bp":"בוברויסק","b":"תלמיד ישיבת ר יהושע במינסק, ישיבת טלז, היגר לארה\"ב ולמד רפואת שיניים. רופא וסופר בניו יורק."},{"i":52223,"n":"שוורצבורד, אריה יוסף מסקאלא","b":"רב דרשן בסקאלא - תשובה אליו בשו\"מ."},{"i":52224,"n":"שוורצבך, אריה ליב מסקאלא","b":"מחנך בסקאלא. הוציא לאור ציור המקדש-תרע."},{"i":52225,"n":"שוורצברג, דוד מואשוואר","b":"רב בואשוואר על מקום ר משה טופונרה ור שמואל שוורצשטין-תרו."},{"i":52226,"n":"שוורצברג, יהושע מזאריק","f":"יוסף","k":"בעל אבני יהושע","bp":"ליפנא","b":"רב בלאשקי, פלאצק, זאריק ובנו ר שמחה צבי על מקומו אחריו. חיבר גם חומות יהושע."},{"i":52227,"n":"שוורצברג, שמחה צבי מזאריק","f":"יהושע - חומת יהושע","b":"חסיד אלכסנדר, אב\"ד בזאריק על מקום אביו. פרסם מאמרים ב\"בית ישראל\"-\"בית שמואל\" - לודז תרץ, \"כרם בית שמואל\" - פיעטרקוב תרצא, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":52228,"n":"שוורצמן, אברהם מטרנופול","b":"חסיד מחכמי טרנופול, נאמן ביתו של האדמור ראי\"ה השל ממזבוב. בעל תפלה אצל האדמור רמ\"ש מהוסיאטין."},{"i":52229,"n":"שוורצמן, בנימין מנחם מאונדין","f":"זבולון","k":"בעל משאת בנימין","bt":"תרכא","bp":"פוניבז","b":"תלמיד ר\"ה סלנטר, ר\"א תאומים. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא, רמ\"י בעל \"פתח הדביר\", ר\"צ רבינוביץ מוילנא, ר\"ר שפירא מוולוזין. רב בקריזבורג-תרנז, אונדין-תרסז, צ'סניק-תרעג, עלה לארץ-תרפב. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. חיבר גם \"נחלת בנימין\", \"דבר בעתו ושביתת השבת\", ועוד."},{"i":52230,"n":"שוורצמן, חיים קלונימוס","b":"חיבר-תרצט חיבור בנוי על דברי 'בני ישכר' על הגזרות הצפויות לעם ישראל (לפני השואה)."},{"i":52231,"n":"שוורצמן, מאיר","k":"בעל הרבי הראשון מגור","b":"נספה בשואה."},{"i":52232,"n":"שוורצמן, מאיר מאמריקה","f":"ישראל משה","k":"בעל מאיר עיני ישרים","bt":"תרסא","bp":"זאגראווע-פולין","b":"תלמיד ר אברהם יצחק הלוי מזאגראווע, ר שלמה גרודזינסקי, ר מאיר דן פלוצקי בעל \"כלי חמדה\". נסמך מאת: ר שמואל דוידוביץ מגורשקוביצה. רב בויניפג-קנדה, ונצואלה. מראשי אגודת ישראל בפולין ויצא בשליחות במקומות שונים מטעם מרכז אגודת ישראל בפולין. חיבר \"מאיר עיני ישרים\" סט לואיס תשב. פרסם מאמרים ב\"הלפיד\" - וארשא תרצז, \"מרכז התורה\" - מונטריאול תשב."},{"i":52233,"n":"שוורצמן, פנחס אברהם מסוקולוב","b":"רב בסוקולוב."},{"i":52234,"n":"שוורצמן, שלום מסטריזוב","f":"פנחס אברהם מסוקולוב","k":"שלום נאמן","bt":"תרכה","dt":"תשטז","b":"חסיד סדיגורא מחכמי סטריזוב - נאמן על נכסי הגביר ר יעקב קנר. חתן הרב שיף מנביליץ. עלה לארץ-תרצה, עם נכדו ר מאיר מרדכי הכהן גוטוירט - שנרצח ע\"י ערבים-תרצט."},{"i":52235,"n":"שוורצמן, שלמה מוערבלי","b":"דומ\"צ בווערבלי-תרע\"ד"},{"i":52236,"n":"שוורצמן, שמעון מוארשא","bt":"תרע","dt":"תשג","b":"רב ברוספשה. עורך \"הלפיד\" - וארשא תרפז."},{"i":52237,"n":"שוורצשטין, אברהם יהודה ליב","f":"יוסף שמואל מושוואר","b":"רב בשימנאי(=נאגי-שימוני) על מקום אביו-תריב."},{"i":52238,"n":"שוורצשטין, יוסף שמואל מואשוואר","b":"רב בואשוואר-תרו בערך על מקום ר משה טופונרה, שימאני(=נאגי-שימוני)-תקעו ובנו ר אברהם על מקומו אחריו."},{"i":52239,"n":"שוורצשטין, ישראל מאיזנהים","f":"יוסף שמואל מואשוואר","k":"בעל עבודת ישראל","bt":"תר","dt":"תרנו - בערך","b":"תלמיד הכת\"ס, ור עזריאל הילסהימר מאיזנשטט. רב ברעבורג-תרל, אונטר-איזנהיים - תרלה."},{"i":52240,"n":"שוורצשילד, א' משה מפפד\"מ","dt":"תקפא - אחרי","b":"דיין בפפד\"מ-תקנה. הספיד את ר ליזר ואלי-תקפא יחד עם ר שלמה זלמן טריר."},{"i":52241,"n":"שוורצשילד, דוד מפפד\"מ","f":"יחיאל מיכל","b":"שמש קהלת פפד\"מ-תקמב בזמן ר פנחס הורביץ בעל ההפלאה."},{"i":52242,"n":"שוורצשילד, יצחק מאיר מפפד\"מ","dt":"תקלז - כב טבת","b":"דומ\"צ מראשי קהילת פפד\"מ-תפ בערך."},{"i":52243,"n":"שוורצשילד, ישראל מפפד\"ם","f":"יחיאל מיכל","b":"סופר קהלת פפד\"ם, ובנו ר יהודה ליב על מקומו אחריו."},{"i":52244,"n":"שוורצשילד, משה מפפד\"מ","dt":"תקכז - כא אייר","b":"מרביץ תורה, דיין בפפד\"מ ומאגודת הרבנים שעמדו בראש הקהילה אחר עזיבת ר יעקב יהושע בעל \"פני יהושע\"."},{"i":52245,"n":"שוחט - וילבושביץ, מניה","f":"ישראל","bt":"1880","bp":"לוסוסנה-ליד גרודנא","dt":"1961","dp":"ת\"א - כפר גלעדי","b":"פעילה בתנועה המהפכנית ברוסיה, וב\"בונד\", נאסר במוסקבה. יסדה את \"מפלגת הפועלים הבלתי תלויה\". סייעה לארגון הועידה הציונית במינסק-1902. השתתפה בקשר להתנקשות בפלבה. עלתה לארץ-1904 והיתה מראשוני ארגון \"השומר\". ממייסדי כפר גלעדי."},{"i":52246,"n":"שוחט, אברהם מבגדד","f":"יוסף","bt":"תקצא","dt":"תרלג","b":"מלמד תינוקות מחכמי בגדד, ומשורר."},{"i":52247,"n":"שוחט, אברהם שמואל מארה\"ב","k":"בעל למען דעת","b":"נכד ר אורי דוד אפריון. עסקן מחכמי בולטימור-תרסז."},{"i":52248,"n":"שוחט, אהרן יהודה ליב הכהן","f":"שמעון מדינוביץ","bt":"תרמב","b":"חתן ר אברהם בן שמעון דנציגר מוינקוביץ. רב במאראוונע-קרליוויץ-פודוליה-תרסו. נסמך מאת: ר אלתר מקונסטנטין."},{"i":52249,"n":"שוחט, ברוך מאיר יעקב מקרלין","f":"עזרא הלוי","k":"אדמור מקרלין סטולין","b":"נכד ר יוחנן מסטולין לוצק. חתן ר משה דוד שטיינוואהרצל-ראש ישיבת בובוב בארה\"ב. הוכתר כאדמור בילדותו. וכיהן כאדמור בניו יורק ובירושלים, עלה לירושלים-תשנא."},{"i":52250,"n":"שוחט, דוד מזאגר","b":"נכד ר דוד וואלפע ממערץ (המכונה ר דודל קראזער)."},{"i":52251,"n":"שוחט, חיים נתן מאבעל וארה\"ב","k":"בעל זכר חיים","b":"רב באבעל-פלך קובנה, פורטלנד-ארה\"ב-תרעג."},{"i":52252,"n":"שוחט, יוסף","f":"אברהם","b":"משורר מחכמי בגדד, בומביי. שיר ממנו-תרד ב\"שירים ותשבחות\" בכת\"י."},{"i":52253,"n":"שוחט, יוסף מבגדד","f":"שלמה אברהם","b":"מחכמי בגדד, חתם על כתובה-תקעה."},{"i":52254,"n":"שוחט, יצחק מבגדד ונאצריה","f":"יוסף","bt":"תקצג","dt":"תרצד","b":"מחכמי בגדד ומשורר. רב בנאצריה."},{"i":52255,"n":"שוחט, מאיר חיים מוורקוביץ","f":"דב","b":"נכד ר שמשון יהודה ליב בן ר דב מסטעפין בן ר יצחק שפירא מצאצאי ה\"מגלה עמוקות\". חתן ר שמואל רוטנברג מראוונא. רב בהורדניא-פלך מינסק-תרנט, וורקוביץ(=וארקאויטש)-ווהלין-תרסג. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":52256,"n":"שוחט, משה מבאנגור-ארה\"ב","k":"בעל הד משה","b":"רב בבאנגאר-ארה\"ב-תרע\"א,עלה לירושלים-תרצ\"ג. חיבר \"הד משה\" וילנא תרצב."},{"i":52257,"n":"שוחט, נתן מדעאבל","b":"רב בדעאבל-תרנ\"ז"},{"i":52258,"n":"שוחט, עזרא מבבל","bp":"בגדד","dt":"תש","b":"מחכמי בגדד, רב ומלמד בבצרה-תרמח, רב בעמארה-תרסו."},{"i":52259,"n":"שוחט, רחמים מבגדד","f":"שלמה אברהם","b":"מחכמי בגדד-תקעב."},{"i":52260,"n":"שוחט, ש","dt":"תרס - ו שבט","b":"תלמיד הכת\"ס, ור יהודה אסאד. רב בוואשוואר-תרכה. בנו ר ה' ברגר - רב בקראטושין."},{"i":52261,"n":"שוחט, שאול ידידיה מקאווליווסק","k":"בעל ברכת שאול","bp":"זאגר ישן-פלך קובנא","b":"נסמך מאת: ר יצחק אלחנן מקובנא. חתן ר שמואל הורביץ מקרטינגה. רב בקרקלן-פלך קובנא, קאווילווסק-פלך יקטרינסלב, יקטרניסלב, נאוי-ואראנצווקא-פלך חרסון, היגר לארה\"ב וכיהן כרב בקנזס-סיטי-תרסו, חיבר גם \"בית ידידיה\", חכמת ידידיה\", \"תפארת ידידיה\". פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":52262,"n":"שוחט, שלמה אברהם מבגדד","dt":"תרא - לפני","b":"דיין בבגדד-תקמה אצל ר יחזקאל אלייא יחזקאל, ור אלייא יחזקאל סופר. בנו ר רחמים רב בבגדד-תקעב, בנו ר יוסף חתם על כתובה-תקעה."},{"i":52263,"n":"שוחט, שלמה בכור מירושלים","dt":"תרנט - לפני","dp":"ירושלים ?","b":"מחכמי ירושלים-תרנ נזר ב\"פני איש\" ליש\"א. בנו - ר יהודה נפטר צעיר."},{"i":52264,"n":"שוחט, שלמה מבגדד","dt":"תר","b":"דיין בבגדד אצל ר יחזקאל אליא סופר-תקנה."},{"i":52265,"n":"שוחט, שמעון מבגדד","f":"רחמים","b":"מחכמי בגדד. העתיק-תקסא את \"שלחן טהור\" לר דוד פארדו. חתם על שטר חילוק מתנות וצדקות-תקפט."},{"i":52266,"n":"שוחטוביץ, אברהם יצחק מארה\"ב","f":"דוד","bp":"סלונים","b":"מצאצאי ר דוד מנוברדוק בעל \"גליא מסכת\". נסמך מאת ר יוסף שלופר מסלונים, ר מרדכי רוזנבלט וייצעל. חתן ר אליהו הכהן מטאוריג. נידון למות בידי הרוסים בזמן מלחה\"ע ה-I וניצל, הגיע לדוינסק אל מחותנו ר מאיר שמחה הכהן בעל \"אור שמח\". רב בניו יורק. חיבר ספרי הלכות ודרושים - בכת\"י. בניו - ר אהרן ור מרדכי."},{"i":52267,"n":"שוחטוביץ, אהרן מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":52268,"n":"שוחטמן, מרדכי מטשערניוויץ ונ\"י","f":"צבי יהודה","k":"בעל תורה תמימה","bt":"תרמד","bp":"שארגארוד-פלך מוהילוב","dt":"תשח - ל אד\"א","dp":"ניו יורק","b":"נכד ר שמשון אוסטרופולר. תלמיד דודו ר חנוך משאריגרד, ר חנוך קרופניק משארגארוד, ר מרדכי יתום, ר הלל פוסק, ר חיים סולוביציק, ר פנחס מפאסטוב. חתן ר יעקב יוסף מולר מפישטאנקא-פלך פודולסק. רב בטשערניוויץ-פודוליה-תרסו, סורוקה-בסרביה והיה סגנו של של הרב הראשי צירלסון, בזמן המהפכה ברוסיה ארגן הגנה יהודית נאסר ונידון למות וניצל, יצא לפאריס וכיהן כרב קהלת \"יבנה\" ודיין ומנהל מחלקת העגונות, סייע לפליטים מגרמניה, ברח לוישי-תש ועמד בראש ביהמ\"ד לרבנים בקלרמון פערמונט, בורדו, ניס ויסד שם בי\"ד עם ר ד\"ר איזנשטט, הרב אופשטין ורבינשטין. ניצל מהשואה דרך מרוקו-תשב והיגע לארה\"ב ויסד קהלה ליהודי רוסיה בניו יורק עם הרב איזנשטט. פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן. נסמך מאת: ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ר אליהו פוסק בעל \"כורת הברית\", מרבותיו, ועוד. חיבר ספר על הרמב\"ם בשם \"תורה תמימה\" ובו שלשה חלקים (משנה תורה, משנת חכמים, משנה ברורה)."},{"i":52269,"n":"שוחמי, אליהו מאזמיר","dt":"תקמט - כד אדר","dp":"אזמיר","b":"גביר מחכמי אזמיר-שנות ה-ת'."},{"i":52270,"n":"שוחמי, אלישע מאזמיר","dt":"תקמט - כד אדר","dp":"איזמיר","b":"חכם כולל, מרביץ תורה באיזמיר"},{"i":52271,"n":"שוחמי, אפרים מאזמיר","k":"בעל תורכיה מול צרפת","bt":"תרלא","bp":"אזמיר","dt":"תרצה - חשון","dp":"פאריס","b":"מאנשי אליאנס באזמיר, הו\"ל \"איל מונדו\"(=העולם)-תרפא, עבר לפאריס-תרפג."},{"i":52272,"n":"שוחמי, משה מאזמיר","dp":"צפת","b":"גביר מחכמי אזמיר-שנות ה-ת', עלה לצפת. נספד מאת אחיינו - ר ברזילי יעבץ מאזמיר."},{"i":52273,"n":"שוחמי, עמרם מפאס","b":"מחכמי פאס-שנות ה-ש', חברו של ר שמואל בן סעדיה ן דנון שהזכירו בספרו."},{"i":52274,"n":"שוחמי, שלמה מקושטא","b":"גביר מחכמי קושטא-שנות ה-תק'."},{"i":52275,"n":"שוטלנד, חיים אליעזר מארה\"ב","bt":"תרנג","dt":"תרצח - כג טבת","b":"רב בניו יורק,ברוקלין,פטרסון"},{"i":52276,"n":"שוטלנד, חיים צבי הירש ממאדין","f":"יהודה","k":"בעל מים חיים","bt":"תרמה","dt":"תש","b":"רב בברזן, דומברובה, שו\"ב בבאנוב (ליד רוזוודוב), שו\"ב במאדין(=מיידאן) (ליד קולבוסוב) ורב שם. דרשן נודד. נספה בשואה. חיבר \"מים חיים\" פיעטרקוב תרפז, ועוד. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אסיפת חכמים\" - מלניץ תרפח, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה, \"קובץ דרושים\" - פיעטרקוב תרפג, \"עמק הלכה\" - באטארקס תרפא."},{"i":52277,"n":"שויגר, אלעזר מנייטרא","dt":"תשד","b":"רב בנייטרא"},{"i":52278,"n":"שויגר, טוביה משעניא","f":"משה הלוי","dt":"תשד","b":"חתן ר משה חיים ליטש-רוזנבוים מקלינורדין. רב בשעניא-תרנה."},{"i":52279,"n":"שויגר, יצחק מטאפלטשן","f":"משה שמואל","k":"בעל ברכת יצחק","bt":"תרט או תריג","bp":"אונגריש בראד","dt":"תרפג - יג תשרי","dp":"טאפלטשן","b":"תלמיד הכת\"ס, ור חיים צבי מנהיימר מאונגוואר. חתן ר ישעיה יחזקאל לינק מטאפלטשן. דיין ומו\"ץ וראש ישיבה בטאפלטשן-תרם כ-50 שנה אצל ר נחום שלזינגר ועל מקומו אחריו. פרסם מאמרים בשבח הציונות ב\"תל תלפיות\" - תרנב."},{"i":52280,"n":"שויגר, לאזאר מערלוי","k":"בעל הדת באור הפסיכול","b":"רב קהילת הסטטוס-קוו בערלוי(=אויהל)-1904, וד\"ר אמיל רות על מקומו אחריו. חיבר ספרים בנושאי דת וחברה."},{"i":52281,"n":"שויגר, נתן נטע הלוי","b":"רב בפורוסלו-תרכ\"ו"},{"i":52282,"n":"שויגר, צבי הרש הלוי מזנטא","f":"משה בן נתן נטע","bt":"תרכה","dt":"תרצב - בערך","b":"תלמיד השב\"ס. רב בשטוהל-ויסנבורג, זענטא-תרסד. אחיו של ר טוביה משעניא."},{"i":52283,"n":"שוימר, יוסף מאיר","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":52284,"n":"שוימר, שמואל מיאסי","b":"עורך כתב העת \"בית ועד לחכמים\" - יאסי תרסט."},{"i":52285,"n":"שויס, חיים בנימין","f":"צבי","k":"בעל די גרויסע אידישע","bt":"1884","bp":"גורז'ד","dt":"1953","b":"מורה לעברית בויסבאדן, חזר לגורז'ד ופרסם מאמרים בשפות שונות. היגר לארה\"ב-1910 ופרסם מחקרים וספרי עם. פרופ' לתנ\"ך והיסטוריה בבימ\"ד למורים-1918, ובלוס אנגלס. חיבר גם ביוגרפיות על אישים ומחקרים על תולדות קהלות ובהם וילנא, גרודנא, בריסק ועוד."},{"i":52286,"n":"שויער-הרואה, ישראל מסבאטישט","f":"עזריאל","dt":"תריט - כד איר","dp":"סאבאטישט","b":"תלמיד החת\"ס. רב בבאנביץ-תקפד, סאבאטישט-תקפט, חתנו ר יעקב קופל רייך על מקומו אחריו (ולאחר מכן בבודפשט)."},{"i":52287,"n":"שויצר, אברהם מויקרסהיים","f":"יוסף","bt":"תרלג","b":"חתן ר נתן במברגר מוירצבורג. רב בויקרסהיים-תרסג."},{"i":52288,"n":"שויצר, צבי מלמברג","f":"אברהם","dt":"תשנב","b":"חסיד בללז. חתן נכדת הנודע ביהודה. ניצל מהשואה, ואחריה עבר לארה\"ב, והתישב בניו יורק. בנו ר שלמה יהודה רב במונסי, ובנו ר יעקב דוד משגיח בישיבת \"תורה ודעת\"."},{"i":52289,"n":"שויצר, שמואל דוד מוארשא","dt":"תרלט - כב תשרי","b":"חריף,מרביץ תורה בוורשה"},{"i":52290,"n":"שויק ן, יצחק מבגדד","f":"ישראל","k":"בעל תוכחות ליוה\"כ","bt":"ד'תתקכז (1167)","bp":"בגדד","dt":"ז (1247)","dp":"בגדד - ירושלים","b":"ראש ישיבת בגדד-ד'תתקפא (1221). חיבר וידויים ותוכחות ליוה\"כ ונדפסו במחזורים. נזכר ב\"חתכמוני\", התכתב עם ר אברהם בן הרמבם, קינה עליו מהפייטן ר אלעזר הבבלי."},{"i":52291,"n":"שויקה, מנחם מחלב","f":"אהרן","dt":"תרצד - יא כסלו","dp":"קהיר","b":"רב בחלב, עבר למצרים בזמן מלחמת העולם ה-I. חברו של ר יעקב סופר בעל \"כף החיים\" בחכמת הקבלה."},{"i":52292,"n":"שוכליר, משה מפאס","b":"מחכמי פאס-שנות ה-ר', שאלה ממנו ב\"חוט המשולש\" לר\"ש דוראן ששאל עם חברו ר יוסף כרבשא."},{"i":52293,"n":"שוכמן, מאיר ממיטאוי","b":"גביר במיטאוי."},{"i":52294,"n":"שוכריאל, יצחק מאלגיר","bt":"רץ","dt":"שס - בערך","b":"רב ורופא באלגיר, התכתב עם ר אברהם ן טוואה בעניני הלכה. עצמותיו הועברו-תרנז לבית עלמין חדש ברובא סט-אוגין באלגיר עם פינוי בית העלמין הישן."},{"i":52295,"n":"שוכרל, שמואל מאלגיר","b":"מחכמי ווהראן. נזכר במסייעים להדפסת \"פרקי אבות\" ברלין תרח. כנראה ממשפחת ר יצחק שוקריאל מאלגיר."},{"i":52296,"n":"שול, יוסף מיברוב","f":"שרגא פיבל","dt":"תש..","b":"תלמיד יח\"ל. סידר לדפוס את \"גבעת הלבונה\" לדודו ר נפתלי הירץ בומבך, ובסופו \"נס על הגבעה\" - ממנו. נספה בשואה."},{"i":52297,"n":"שולאל, אברהם הכהן מאלגיר","bt":"קן","dt":"רל - בערך","b":"תלמיד הרשב\"ץ. דיין בהוניין-אלגיר."},{"i":52298,"n":"שולאל, אברהם הכהן מספרד","bt":"קי","dt":"קץ - בערך","b":"דיין במיורקה, ואולי עבר לאלגיר. תשובה אליו בשו\"ת תשב\"ץ."},{"i":52299,"n":"שולאל, דוד הכהן מאלגיר","bt":"קל","dt":"רי - בערך","b":"רב ודיין בתנס. שאלות ממנו לרשב\"ץ בשו\"ת הרשב\"ץ בענין אנוסים ועוד."},{"i":52300,"n":"שולאל, דוד הכהן מאלגיר","bt":"תקן","dt":"תרל - בערך","b":"רב באלגיר. הסכים על \"חסד ה'\" ירושלים תרצא."},{"i":52301,"n":"שולאל, חיים ממצרים","f":"מימון","b":"מחכמי מצרים-רלו, ולכבודו כתב ר משה מסעוד את ספר המכתם."},{"i":52302,"n":"שולאל, יוסף הכהן ממצרים","b":"מחכמי מצרים-תיב, והעיד בפני רבני מצרים. נזכר בשו\"ת \"דרכי נעם\"."},{"i":52303,"n":"שולאל, יצחק הכהן ממצרים","f":"אברהם","k":"יצחק הנגיד","dt":"רפג-ה - א כסלו","dp":"ירושלים","b":"אחיינו של ר נתן הכהן שולאל מירושלים. כנראה עלה מאלגיר לירושלים, לפני שנת רעד, הגיע למצרים עם דודו ר נתן. היה ראש הקהלה במצרים ובארץ ישראל אחר פטירת ר יהונתן הנגיד, הקים ישיבה גדולה ובראש הישיבה עמדו ר שמואל מסעוד ור יוסף בן מני, והתצטרפו אליה רבים ממגורשי ספרד ומארצות שונות. נשא ונתן בהלכה עם גדולי דורו ומוזכר בתשובות הרדב\"ז מהר\"י בירב והרלב\"ח."},{"i":52304,"n":"שולאל, ישעיה צבי מזקליטשין","b":"תשובה אליו במנחת יחיאל."},{"i":52305,"n":"שולאל, מרדכי הכהן","dt":"תקפא - יט חשון","dp":"ירושלים.","b":"מחכמי ירושלים."},{"i":52306,"n":"שולאל, משה הכהן מאלגיר","bt":"קפ","dt":"רן - בערך","b":"דיין ומנהיג הקהלה בהוניין-אלגיר. היה בקשר מכתבים עם הרשב\"ש המכנהו \"הנשיא\". תשובות ממנו אצל ר\"י ששפורטש מהוניין."},{"i":52307,"n":"שולאל, משה הכהן מחלב","dt":"תרמב - ח ניסן","b":"רב בחלב."},{"i":52308,"n":"שולאל, נתן (יונתן) הכהן ממצרים","f":"סעדיה או חיים","bt":"קצז","bp":"תלמסאן (מרוקו)","dt":"רסב - כד אייר","dp":"מצרים","b":"רב בתלמסאן, עלה לירושלים-רלב והיה שם נגיד, בשנת תרלט עמד בראש ישיבה בירושלים, נאלץ לברוח למצרים-רמא והתמנה שם לנגיד ור יצחק על מקומו אחריו (לדברי רוזניס המדובר לא בבנו יצחק אלא בבן אחיו). הוא הפקיד את ר עובדיה מברטנורא על ביתו בירושלים. הרדב\"ז התמנה לדיין בבית דינו כשהגיע למצרים. בניו - סעדיה, אפרים, אברהם, יצחק."},{"i":52309,"n":"שולאל, נתן הכהן מאלגיר","bt":"קע - בערך","dt":"רן - בערך","dp":"תלמסאן","b":"רב בתלמסאן, והיה גם זקן הקהל ונשיא, ואולי הוא שהיה נגיד במצרים (ראה ר יונתן)."},{"i":52310,"n":"שולאל, סעדיה הכהן מאלגיר","bt":"קן","dt":"רך - בערך","b":"כנראה הגיע מספרד-קנא, רב בתלמסאן, ר\"מ ומלמד לתלמידים. בנו - ר נתן הנגיד ממצרים."},{"i":52311,"n":"שולאל, שלום הכהן מאלג'יר","k":"בעל נוה שלום","dt":"תקסד - לפני","b":"תלמיד ר יעקב בן נאיים. רב באלגיר. מתשובותיו ב\"נוה שלום\"."},{"i":52312,"n":"שולביץ, אליעזר","bt":"תריב (באוצר תרז","dt":"תרצב","b":"מתלמידי ר ישראל סלנטר הקים את ישיבת לומז'ה ובפרילוקי, עלה לפתח תקוה בשנת תרפה. בנו ר חיים הירש מויגובה. חתניו - ר יהושע זליג רוך, ר משה אריה עוזר."},{"i":52313,"n":"שולביץ, חיים הירש מלומזה","f":"אליעזר מלומזה","b":"רב בויגובה."},{"i":52314,"n":"שולביץ, יצחק דוד מקאמרוב","f":"ישראל","bt":"תרלב","b":"נכד ר יעקעלע מזאנאווצי. רב בואנסווא-פלך לומזה, קאמרוב-פלך לומזה-תרסה."},{"i":52315,"n":"שולהוף, אסתר מברלין","dt":"תעד","b":"בעלה הראשון ר ישראל אהרן - שלחני בחצר מלכי פרוסיה, בעלה השני - ליבמן יוסט מברלין נתמנה בזכותה להיות שלחני המלך, לאחר פטירתו הפכה בעצמה לשלחני המלך. קבלה רשיון לבנית ביכ\"נ בביתה. בנה היה ראש הקהלה, וחתנה האב\"ד-תע."},{"i":52316,"n":"שולהוף, יעקב מפרג","f":"יונה-קיקיון דיונה","b":"חתן הגביר ר אנשל שולהוף. רב בפרג. שינה שמו לשם חותנו."},{"i":52317,"n":"שולהוף, יצחק הלוי מאויבן","f":"שלמה זלמן הקדוש","k":"בעל מגילת אויבן","bt":"תי","dt":"תצג - ג שבט","b":"חתן ר אפרים הכהן מפרג ובזיוו\"ש חתן ר יצחק ליב וועלי. רב באויבן, נפל בשבי התורכים לאחר שנחרבה העיר ונפדה בידי ר צבי הירש לאזלש משטמפן, דיין בפרג. חיבר ספר על הטבח שנעשה ביהודי אויבן בזמן כיבושה מידי התורכים - ומספר על פדיון השבויים בעזרת ר שלמה אופנהימר מוינה וסנדר טאוסיק מפרג. בנו - ר ליב, חתנו - ר שמחה פופרש."},{"i":52318,"n":"שולהוף, ליב","f":"יצחק מאויבן","dt":"תע - טו טבת","b":"רב בבהמן"},{"i":52319,"n":"שולזינגר משה מרדכי בן יצחק","bt":"1941","dt":"ה'תשע 2010","bk":[["דברים שהתורה נקנית בהם",""],["זכרו תורת משה עבדי",""],["משמר הלוי",""],["שולחנך גדול משולחנם",""]]},{"i":52320,"n":"שולזינגר, אליהו מטשרנוביץ","f":"משה נח מטירספול","k":"בעל יד אליהו","bt":"תרלה","bp":"קופיטשיניץ","dt":"תשל","b":"חסיד סדיגורא. חתן ר אליעזר דב שכטר. רב בטשרנוביץ (גם בזמן השואה). ניצל מהשואה. רב בבוקרטש-תשז, עלה לארץ-תשח והתישב בבני ברק. חיבר \"יד אליהו\" בני ברק תשטז."},{"i":52321,"n":"שולם, וידאל","b":"מחכמי פריווינציאה-שנת נ'-ק', מתלמידי הרשב\"א"},{"i":52322,"n":"שולם, זכריה משלוניקי","b":"גביר מראשי קהלת שלוניקי, השתתף במשלחת אצל השולטן בקושטא-שצז בראשות ר יהודה קובו - שנהרג עק\"ה בידי השולטן."},{"i":52323,"n":"שולם, חיים מקושטא","f":"שמואל","b":"רב בקושטא-שעט. בנו ר שמואל נפטר בחייו."},{"i":52324,"n":"שולם, חנניה מפיררה","f":"שמואל","b":"רב בפיררה. תשובה ממנו-שצו מפיררה, עם ר בנימי טרבוט ור יוסף ברוך מאורבינו - החותמים במודנא."},{"i":52325,"n":"שולם, יצחק משלוניקי","f":"מנחם","dt":"שפא - ח טבת","dp":"שלוניקי","b":"גביר עסקן ומקורב לשלטון, מחכמי שלוניקי."},{"i":52326,"n":"שולם, יצחק משלוניקי - א","f":"מנחם","dt":"תלב","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":52327,"n":"שולם, יצחק משלוניקי - ב","dt":"תקיד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":52328,"n":"שולם, ישראל משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"פני אהרן\" לר אהרן אמריליו-תקנו."},{"i":52329,"n":"שולם, מיכאל יהודה מרודוס","b":"תלמיד ר חיים יהודה ישראל בעל \"קול יהודה\". רב ברודוס."},{"i":52330,"n":"שולם, מנחם משלוניקי","bt":"שמ","bp":"שלוניקי","dt":"תלא - כד ניסן","dp":"שלוניקי","b":"תלמיד ר אברהם מוטאל, כיהן כראש ישיבת ליסבון ישן בחיי רבו, ואחרי פטירתו רב אחריו בשלוניקי עם ר חיים אברהם הכהן פרחיה, ר ברוך אנג'יל, ור שמואל גאון. מתשובותיו בספרי חבריו. בנו - ר יצחק - רב בשלוניקי."},{"i":52331,"n":"שולם, שמואל מקושטא","f":"דוד","b":"רופא מחכמי קושטא. הו\"ל ספר יוחסין לר אברהם זכות - קושטא שכה."},{"i":52332,"n":"שולמן שמואל ברוך","bt":"1905","dt":"ה'תשלב 1972","bk":[["אש דת",""],["ספור מפליא הנוגע לכבוד התורה",""]]},{"i":52333,"n":"שולמן, אברהם יוסף מארה\"ב","f":"גדליה","bt":"תרלט","bp":"מזריטש","b":"נכד(-אבי אמו) ר יצחק פרידמן מירושלים בעל \"דברי גדליהו\". תלמיד ישיבות לומזה, סלובודקה. נסמך מאת ר יצחק מאיר מסלובודקה. רב בריעל-ליד לידס-אנגליה-תרפג, ר\"מ בישיבת \"תורה מציון\" בברונזויל."},{"i":52334,"n":"שולמן, אליעזר הכהן","k":"בעל ממקור ישראל","bt":"תר","bp":"קרטינגה","dt":"1904","dp":"קיוב","b":"מורה בבית הגביר ליב ברודסקי בקיוב, ונתמנה לגזבר רשי של \"החברה האלכסנדרובית\". פרסם מחקרים בתולדות הספרות האידית. חיבר גם \"זכרונות עיר מולדתי\"."},{"i":52335,"n":"שולמן, ברוך","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":52336,"n":"שולמן, דוד","f":"יחיאל","bt":"1897","bp":"פוניבז","dt":"1962","dp":"תל אביב","b":"ממיסדי \"מכבי\" והגימנסיה העברית בפוניבז. פעיל בתנועה הרביזיוניסטית. עלה לארץ-1925 והשתתף בהגנת תל אביב בזמן מאורעות-תרפט. מפעילי איגוד יוצאי ליטא."},{"i":52337,"n":"שולמן, חיים יעקב מבריסק","b":"דיין ומו\"צ בבריסק-תרע (בזמן רבנות ר חיים סולוביציק)."},{"i":52338,"n":"שולמן, חיים יעקב מבריסק","b":"דיין בבריסק-תרסח, חתם עם ר אברהם יצחק בליויס."},{"i":52339,"n":"שולמן, חיים יצחק","f":"משה יחיאל","k":"בעל זרע יצחק","bt":"תרלז","bp":"ז'אזמיר","dt":"תרצ","b":"תלמיד ר מאיר מיכל רבינוביץ משאט. רב ביאנובה, עבר לוילנא בזמן מלחה\"ע ה-I, חזר ליאנובה ועזר בשיקום הקהלה. ציר בכנסיות אגו\"י."},{"i":52340,"n":"שולמן, יהודה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":52341,"n":"שולמן, ירחמיאל","dt":"תשג","b":"מרביץ תורה בישיבת בית יוסף בפינסק"},{"i":52342,"n":"שולמן, ישראל מבזיליאן","b":"רב בבזיליאן-ליטא - לפני מלחה\"ע ה-I."},{"i":52343,"n":"שולמן, מנחם","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":52344,"n":"שולמן, מרדכי מארה\"ב ובני ברק","b":"ראש ישיבת סלובודקה בבני ברק-תשכט. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":52345,"n":"שולמן, משה הלוי מארה\"ב","f":"יעקב מרדכי","bt":"תרעג","bp":"רובליע-פלך פינסק","b":"תלמיד ישיבת \"בית יוסף\" בפינסק אצל ר משה רייז הי\"ד, \"בית יוסף\" בביאליסטוק אצל ר אברהם יפה'ן, ישיבת זוויהל בקורעץ \"אור תורה\" אצל ר ברוך מרדכי רייז הי\"ד. נסמך מאת: ר מאיר שלום שצרדוביצקי מביאליסטוק, ר שמחה זליג מבריסק, ר אלתר בן ציון אדרמן מלוצק, ר אברהם יפה'ן מביאליסטוק. ר\"מ בפיעטרקוב, יסד ישיבות \"בית יוסף\" בקוטנא, אזרקוב, לינטשיץ, פולאוו, אוסטראלאנקא, וישקוב, יאדוב, קולומיי, קוסוב, סוינציאן-תרצו - לבקשת ר חיים עוזר גרודזינסקי. חתן ר אברהם דוד בלומנקרנץ מניו יורק, ניצל מהשואה דרך שבדיה-תש, הגיע לארה\"ב-תשא וכיהן כר\"מ בישיבת \"בית יוסף\" ביאליסטוק בניו יורק, ראש ישיבת \"נר תמיד\" בניו יורק-תשט. עסק בפעולות הצלה בזמן השואה. הניח ספר בהלכה והוראה - בכת\"י."},{"i":52346,"n":"שולמן, משה חיים מארה\"ב","f":"מרדכי יעקב","bt":"תרלב","bp":"ירושלים","b":"בעל בית מסחר בבוסטון-ארה\"ב."},{"i":52347,"n":"שולמן, נפתלי הרץ מוילנא","f":"אברהם","k":"בעל שפתי דעת","b":"הגיע לוילנא עוד בימי הגר\"א. מחכמי וילנא ובקי בשפות, מלמד תורה לבני עשירים בוילנא ובהם ר מרדכי נתנזון בן ר בינה פישל'ס. היה מחלוקת כנגדו בגלל שלימד גם שפות - והלשינו עליו ונאלץ לעזוב ולהניח את ספריו. אחיינו ר קלמן שולמן סיפר כי הוא לימד \"מורה נבוכים\" בבימ\"ד הגר\"א (ויש אומרים כי היה זה רב אחר)."},{"i":52348,"n":"שולמן, קלמן","f":"ירוחם פישל מביחוב","k":"בעל אריאל","bt":"תקעט","bp":"ביחוב","dt":"תרנט - ד שבט","b":"תלמיד בימ\"ד הגר\"א - אצל ר מאיר ריינער-תלמיד הגר\"א (ואמר כי הגר\"א שיבח את ביאור ר נפתלי הרץ ויזל לספר ויקרא), וישיבת ר ישראל גינצבורג בוילנא (יחד עם חברו דניאל חבלסון). חיבר גם \"דברי ימי עולם\", ועוד."},{"i":52349,"n":"שולמן, שלמה זלמן מצפת","b":"מחכמי צפת."},{"i":52350,"n":"שולמן, שמואל","bt":"1862","bp":"קאלואריה","dt":"1955","dp":"ניו יורק","b":"היגר לארה\"ב בילדותו. תלמיד ביה\"ס הגבוה לחכמת ישראל בברלין. רב ריפורמי בקהילות שונות בארה\"ב, ומראשי התנועה הריפורמית באמריקה. מעורכי התרגום האנגלי של התנ\"ך. התנגד ללאומיות יהודית, תמך בהתישבות יהודית בא\"י. חבר ה\"סוכנות היהודית\" כנציג ה\"לא ציונים\"."},{"i":52351,"n":"שולמן, שמחה שמואל","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"תבונה\" - ירושלים תשא, \"תל תלפיות\" - ירושלים תשא."},{"i":52352,"n":"שולמן, שמריה מארה\"ב","f":"פנחס אליהו","bt":"תרפג","bp":"ניו יורק","b":"תלמיד ישיבת \"תורה ודעת\" בניו יורק, \"נר ישראל\" בבולטימור. נסמך מאת: ר יעקב יצחק רודרמן מבולטימור. רב בקהלת \"קשר ישראל\" בוושינגטון-תשו, קהלת \"שומרי שבת\"-תשז, רב בג'רסי-סיטי-תשח."},{"i":52353,"n":"שולעוויץ, יהודה","dt":"תשג","b":"רב בגברטשוב"},{"i":52354,"n":"שומיאצקי, אליהו בנימין","f":"מנחם דוד","bt":"תרטו","b":"רב בדמיטרובקה(=דמיטראווקא)-פלך צרניגוב-תרס."},{"i":52355,"n":"שומיאצקי, ישראל דובער","f":"מנחם דוד","k":"בעל יד ישראל","bt":"תרכב","b":"מצאצאי ר יהושע משימיאץ. תלמיד כולל קובנא. רב בהאלוכאוו-תרן. נסמך מאת: הריא\"ס. חיבר שו\"ת \"יד ישראל\" - בכת\"י."},{"i":52356,"n":"שומיאצקי, מנחם דוד","b":"מקובל-תר\"כ"},{"i":52357,"n":"שונין, חיים משלוניקי","b":"מחכמי שלוניקי-שנות ה-ש'."},{"i":52358,"n":"שונינה, אברהם משלוניקי","dt":"תקיז - אחרי","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. סייע בהדפסת \"שיירי כנסת הגדולה\"-תקיז יחד עם אחיו ר יהושע."},{"i":52359,"n":"שונינה, יהושע משלוניקי","dt":"תקיז - אחרי","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. סייע בהדפסת \"שיירי כנסת הגדולה\"-תקיז יחד עם אחיו ר אברהם."},{"i":52360,"n":"שונינה, משה משלוניקי","b":"גביר בשלוניקי ותרם לת\"ת בשלוניקי-שג. (אצל רוזניס - היה גביר בשלוניקי סוף שנות ה-ת')."},{"i":52361,"n":"שונינה, שלמה משלוניקי","dt":"שפא - יז אייר","dp":"שלוניקי","b":"גביר מחכמי שלוניקי, נוסח מצבתו מאת המשורר ר אברהם ראובן ממונסטיר."},{"i":52362,"n":"שונינו, יהושע","b":"תלמיד מהר\"ם ן חביב. נזכר בספר \"גט פשוט\"."},{"i":52363,"n":"שונצא, יהושע","b":"חתנו של המהרש\"ל. תשובה ממנו בשו\"ת חותנו - המהרש\"ל."},{"i":52364,"n":"שונצינו, אברהם מקושטא","b":"גביר מחכמי קושטא-שנות ה-ת'. החזיק בכת\"י קרובו - ר יהושע, ומהם נדפס \"נחלה ליהושע\". נאסר ע\"י השלטון בקושטא ושוחרר."},{"i":52365,"n":"שונצינו, אליעזר מקושטא","f":"גרשום","b":"מדפיס בקושטא, עבר למצרים-שז והדפיס שם עד שכב."},{"i":52366,"n":"שונצינו, גרשום מאיטליה וקושטא","f":"משה","k":"בעל תוספות טוך","dt":"רצד","b":"מדפיס באיטליה בערים ברעסיציא, ארצי, פיזרו, רומיני, ארטונא, עבר לשלוניקי ולקושטא. אביו ר משה מוצאו מפירט באשכנז, מצאצאי ר משה שפירא שהיה מבעלי תוספות טוך, אסף בערי צרפת את \"תוספות טוך\" והדפיסם על הש\"ס. בנו - ר אליעזר על מקומו אחריו כמדפיס. ר גרשום חתם את שמו בלעז - הירונימוס סונג'ינו."},{"i":52367,"n":"שונצינו, גרשום מקושטא ומצרים","f":"אליעזר","b":"מדפיס בקושטא, עבר למצרים-שיז והדפיס שם \"פתרון חלומות\" לר האי גאון."},{"i":52368,"n":"שונצינו, יהושע מאזמיר - הנכד","f":"מנחם","b":"גביר מחכמי אזמיר, סייע בהדפסת \"יד אליהו\" לר\"א גאליפפה, ועוד. הו\"ל ספר זקנו \"נחלה ליהושע\". חתם על הסכמה-תקח לטובת ישוב כפר יסיף."},{"i":52369,"n":"שונצינו, יהושע מקושטא","f":"ישראל נתן","k":"בעל נחלה ליהושע","b":"מחכמי קושטא. חיבר פסקים ושו\"ת - מוזכר ע\"י החיד\"א."},{"i":52370,"n":"שונצינו, יהושע מקושטא ושלוניקי","k":"בעל נחלה ליהושע","bt":"רפ","dt":"שכט - י ניסן","dp":"קושטא","b":"רב בקהלת \"מאיור\" בקושטא, רב קהלת איטליה ובנו ר שמואל על מקומו אחריו, רב בשלוניקי. נספד ע\"י ר משה אלמושנינו והביאו בספרו \"מאמץ כח\". מתורתו בספר נכדו \"נחלה ליהושע\". התנגד לחרם של ר יוסף ן לב ומשפחת נשיא-מינדיס כנגד העיר אנקונא באיטליה. בנו גם - ר מנחם מאזמיר ונכדו ר יהושע הו\"ל מכתביו את \"נחלה ליהושע\". חתנו - ר חיים בנבנשתי."},{"i":52371,"n":"שונצינו, יהושע משה","b":"סייע בהדפסת ספר התשב\"ץ - אמשטרדם תצח."},{"i":52372,"n":"שונצינו, יהושע שלמה","dt":"רמד - ו אד\"א","b":"מגדולי חכמי צונצין(לומברדיה), הדפיס לראשונה תלמוד עם רש\"י ותוספות(שליקט ואסף מחכמי טוך) ופירוש המשניות לרמב\"ם בחיבור אחד"},{"i":52373,"n":"שונצינו, יוסף","f":"מנחם","b":"סייע ביחד עם אחיו יהושע ואחיינו משה בן יהושע בהדפסת \"שמע יעקב\" לר יעקב ישראל אלגזי."},{"i":52374,"n":"שונצינו, ישראל נתן","f":"שמואל","b":"רב ורופא. הקים בית דפוס. נלחם בעיר פירט נגד הרשע יואן די קאפישטראנו וגרש אותו משם."},{"i":52375,"n":"שונצינו, מנחם מאזמיר","f":"אברהם מאזמיר","b":"מחכמי אזמיר."},{"i":52376,"n":"שונצינו, מנחם מאזמיר","f":"יהושע מקושטא","b":"מחכמי אזמיר-שנות ה-ש'. בנו - ר יהושע הו\"ל ספר אביו \"נחלה ליהושע."},{"i":52377,"n":"שונצינו, מרדכי צמח מפרג","f":"גרשון","b":"מחכמי פרג, נסע בשליחות לאפיפיור לבטל את גזירת הגירוש מפרג-שכא."},{"i":52378,"n":"שונצינו, משה","f":"מנחם","b":"סייע לר משה ישראל ונזכר בספרו \"משאת משה\"."},{"i":52379,"n":"שונצינו, משה מאזמיר","f":"יהושע","k":"בעל תורת משה","dt":"תקי","b":"תלמיד ר אליהו הכהן האיתמרי בעל \"שבט מוסר\". מחכמי אזמיר וחבר ב\"מחזיקי תורה\". סייע בהדפסת \"מדרש תלפיות\", \"חמדת ימים\", \"משאת משה\", ועוד. מתורתו ב\"גולל אור\" אזמיר תצו."},{"i":52380,"n":"שונצינו, משה משלוניקי","b":"אולי בן אחיו של ר של המדפיס ר גרשום שונצינו. מדפיס בדפוס גדיליה בשלוניקי--רפא, ויסד דפוס משלו עם הרופא ר שם טוב אבשרנא, הדפיס \"ילקוט שמעוני\"."},{"i":52381,"n":"שונצינו, שלמה משלוניקי","b":"מדפיס בשלוניקי-רצג - כנראה אחיו של המדפיס ר גרשום בן משה."},{"i":52382,"n":"שונצינו, שמואל מקושטא","f":"יהושע מקושטא","b":"רב קהלת האיטלקים בקושטא-שכט על מקום אביו. אחיו - ר מנחם מאזמיר."},{"i":52383,"n":"שונשול, בכור שבתי מאזמיר","dt":"תרצא - ח טבת","dp":"ירושלים","b":"גביר באזמיר, עלה לירושלים, פעל להקמת מוסדות."},{"i":52384,"n":"שונשול, חיים","k":"בעל שמחה לאיש","b":"רב באזמיר. חיבר \"שמחה לאיש\""},{"i":52385,"n":"שונשיל, אברהם מאזמיר","k":"בעל עשת שן","b":"מחכמי אזמיר. חיבר עשת שן - בכת\"י, ונזכר ב\"יסד המלך\" אזמיר תרכו."},{"i":52386,"n":"שוס, מנחם מנדל מדוקלא","b":"מחכמי דוקלא. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":52387,"n":"שוסבורג, אברהם שבתי מפרשבורג","f":"מנחם מנדל מפרשבורג","dt":"תריח - יח שבט","dp":"פרשבורג","b":"מחכמי פרשבורג, והכת\"ס סיפר ששמע מהחת\"ס שהיה אחד מל\"ו צדיקים."},{"i":52388,"n":"שוסברג, גבריאל מרישא","k":"בעל פתח תשובה","b":"רב ברישא-תח, חיבר תחנות וסליחות על גזירות תח ותט."},{"i":52389,"n":"שוסברג, מנחם מנדל מפרשבורג","dt":"תקסו - כד כסלו","dp":"פרשבורג","b":"צדיק מחכמי פרשבורג, ואמרו עליו בשם הוא אחד מל\"ו צדיקים. בנו ר אברהם שבתי שנחשב גם הוא לאחד מל\"ו צדיקים."},{"i":52390,"n":"שוסהים, אהרן ליב","f":"פנחס שלמה מפשמישל","bt":"תרלח","bp":"רדימנא","dt":"תשטו","dp":"בואנוס איירס","b":"ממייסדי פועלי ציון בגליציה, עורך עתוני התנועה באידיש בקראקא, למברג, סטניסלב. היגר לארגנטינה-תרפז."},{"i":52391,"n":"שוסהים, פנחס שלמה מפשמישל","k":"בעל חזון ישעיהו","bt":"תריד","bp":"פשמישל","b":"תלמיד ר יצחק שמלקיס, רב בלמברג, זבלטוב-תרנד, טיסמניץ, סטניסלב. פעיל במזרחי. חיבר \"חזון ישעיהו\" - בכתב יד."},{"i":52392,"n":"שוסטק, יצחק מנדבורנה","k":"בעל דברי מאיר","b":"חתן ר יצחק מקלוש (אחרי ר\"מ מפרימישלן). הביא לדפוס \"מעשה פלא\" מר שלמה אפרים מלונטשיץ - קולומיאה תרם. חיבר \"דברי מאיר\" ברטפלד תרסט, ועוד."},{"i":52393,"n":"שוסטר, יצחק הלוי","b":"רב בסוקולקה-תרף."},{"i":52394,"n":"שוסטר, יצחק מסאקאלקע","bt":"תרג","dt":"תשב - יד אדר","b":"תלמיד ר משה דאנישבסקי מסלובודקה, ותלמיד בכולל בקובנה, וקיבוץ ר חיים עוזר גרודזנסקי בוילנא. חתן ר נחום גרינהויז מטראקי. רב בסאקאלקע-ליד ביאליסטוק-תרסח, בשליחות באמריקה-תרף וחתם בסינסינטי - לטובת בית חרושת למצות מנישבץ. נספה בשואה עק\"ה, לאחר שסירב לדרישת הגרמנים למסור את רשימת היהודים בעירו. בנו ר שלמה שנקרא העלוי מסאקאלקע."},{"i":52395,"n":"שוסטר, משה מסטניסלב","f":"טויבא ראסי - שם אמו","bt":"תרעב","bp":"סטניסלב","dt":"תשנא","b":"נכד הקצות. חסיד בלז. למד בישיבת אמו. ניצל מהשואה - גלה לסיביר. עלה לארץ דרך פרנוולד. מקורב לאדמורים."},{"i":52396,"n":"שוסטר, שלמה מסאקאלקע","f":"יצחק סגל מסקולקא","k":"העלוי מסאקאלקע","dp":"ארה\"ב","b":"מחכמי סאקאלקע(=סקולקא, סוקולקה) - ונחשב לעילוי מופלג, ניצל מהשואה ואחריה עלה לארץ, עבר לארה\"ב. נפטר צעיר."},{"i":52397,"n":"שוסטר, שמואל נתן מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקכה."},{"i":52398,"n":"שוסטרמן, שרגא פלק","f":"בנימין","bt":"תרלו","b":"רב בברישווקה-פלך פולטבה-תרסד."},{"i":52399,"n":"שוסלביץ, יהודה","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":52400,"n":"שועבר, מתתיהו","b":"תלמיד ר יוסף חנניא מייזלש בעל \"תפארת יוסף\" שהזכירו בספרו. מגיה שו\"ת רמ\"ץ."},{"i":52401,"n":"שועיב ן, דוד","b":"דיין בקלעת איוב"},{"i":52402,"n":"שועיב ן, יהושע מספרד ושלוניקי","k":"בעל דרשות","b":"תלמיד הרשב\"א. דרשן, רב בנאוורה, לאחר הגירוש עבר לשלוניקי (ולפי רוזנס - נשאר בספרד). חיבר דרשות. אחיו של ר יואל. מתלמידיו - ר מנחם בן זרח."},{"i":52403,"n":"שועיב ן, יואל מארגון ושלוניקי","k":"בעל עולת שבת","bp":"אראגון","b":"דרשן, רב בארגון-רכ, נאווארה, בגירוש עבר לשלוניקי. חיבר \"עולת שבת\", \"נורא תהלות\", \"עין משפט\". בנו - ר שמואל."},{"i":52404,"n":"שועיב ן, יוסף דון מספרד","dt":"רסג - אב","dp":"שלוניקי","b":"ממגורשי ספרד שהגיע לשלוניקי. בנו - הילד אברהם נפטר בחייו."},{"i":52405,"n":"שועיב ן, שמואל משלוניקי","f":"יואל מאראגון","bp":"ספרד","dt":"רפח - כב תמוז","dp":"שלוניקי","b":"מחכמי ספרד וגלה לשלוניקי. מרביץ תורה בק\"ק אראגון בשלוניקי בזמן ר מאיר ן עראמה. הו\"ל פירוש אביו לאיכה עם ביאור משלו והקדמה."},{"i":52406,"n":"שוער, אברהם מארה\"ב","b":"סופר, מלמד בישיבת רבי יעקב יוסף בניו יורק."},{"i":52407,"n":"שוערד, ישראל מראווה-רוסקה","f":"צבי הירש מראווה","bt":"תקמה","bp":"ראווה","dt":"תשב","b":"אביו היה מחכמי ראווה - אך לא נתקבל לרבנות מכיון שלא היה חסיד. חתן ר יהודה יונה בן שמחה מראווה. חסיד בלז. רב בראווה-תרעא לבקשת האדמור מהרי\"ד מבלז, בנו ר אריה רב לצדו. בעל תוקע אצל האדמור והדריך את בנו ר שלום באפטא. אחיו ר שלום מבחירי החכמים בראווה - נספה בשואה."},{"i":52408,"n":"שוערין, אליקים גץ מבאייה","f":"שמואל","bt":"תקך","bp":"שוערין","dt":"תריב","b":"תלמיד ר יוסף מפוזן-חתן הנודע ביהודה, מהר\"ם ברבי מפרשבורג. חתן הגביר ר מאיר ליב מבאייה(=ביאה) ועבר לשם. רב בסאבאדקא-תקעא, שטאמפן-תקעד אך לא כיהן בפועל, בייאה-תקעה על מקום ר מאיר א\"ש, סירב להצעת באניהאד (לשם עבר באופן זמני - וכיהן כדיין) שסייעו לקהילת באייה לאחר השריפה-תר. רב ראשי לקהלות הונגריה ובעל סמכות לאשר בחירת רבנים. בקהילת באייה היה בית כלא מיוחד לעבריינים - בין שעברו על המצוות, ובעיקר על סרבני תשלום מס הסובלנות - הכלא בוטל לאחר שבוטל מס הסבלונות. החת\"ס שנתבקש להמליץ על רב לקהלת קדלבורג המליץ על שלשה: ר אליקים גץ, ר דניאל פרוסטיץ מפרשבורג - מחותנו, ור יחזקאל בעל \"מראה יחזקאל\". חתנו - ר בנימין וולף פרוסטיץ-אב\"ד לוגאש בן ר מרדכי טסק. היה מחלוקת כנגדו מצד כמה מגדולי הונגריה בענינים שונים. נספד בליקוטי הב\"ח."},{"i":52409,"n":"שוערין, יוסף ממגנצא","b":"כתב פשקויל נגדו - מגנצא תקפ."},{"i":52410,"n":"שופט, ידידיה מארה\"ב","bt":"תרסט","bp":"כאשאן(איראן)","dt":"תשסה - כח סיון","b":"רב בטהראן-תש\"ז,דיין,דרשן,מורה בסמינר,עבר ללוס אנג'לס"},{"i":52411,"n":"שופינו, רפאל","b":"נזכר בשו\"ת ר יוסף מליריאה."},{"i":52412,"n":"שופנטל - רב בנ\"י","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":52413,"n":"שוץ, יעקב מנדל","k":"בעל מצבת קדש","b":"חיבר \"מצבת קודש\" לגאוני למברג - למברג תרך. (אוצר הספרים מ. 2003)."},{"i":52414,"n":"שוצמן, דוד מסמבור","dt":"תרצד - בערך","b":"מחכמי סמבור - תשובה אליו \"שושנים לדוד\"."},{"i":52415,"n":"שוצמן, חיים מפיסטין","f":"מרדכי","dt":"תרצח - בערך","b":"דיין ושו\"ב בפיסטין-תרסג. אביו מח\"ס \"ילקוט מרדכי\" וינה תרל."},{"i":52416,"n":"שוק, מנחם מנדל מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":52417,"n":"שוק, שמואל דב","f":"יוסף מזייבוש","bt":"תרעה","bp":"זייבוש","dt":"תשנב","dp":"ירושלים","b":"חסיד בלז. למד בישיבת טשבין. חתן ר יעקב שליסלר ממידן. ניצל מהשואה, עלה לארץ והתגורר בבני ברק."},{"i":52418,"n":"שוקיאן, פנחס","bt":"1856","bp":"ואבולניק","b":"למד בקורלנד. חובב ציון ועסקן ציוני. מורה בטרוקי - מתלמידיו פרופ' יוסף קלוזנר. עבר לוילנא והתידד עם רש\"י פין, דיק, קלמן שולמן, ועוד. פרסם ב\"המליץ\". מראשוני \"בני משה\" בוילנא. מיוזמי ביה\"ס \"בנות ישראל\" שהפך ל\"יהודיה\"."},{"i":52419,"n":"שור, אבא מוורנה","bt":"תרסט","dt":"תש..","b":"רבה האחרון של ווארנה(=וורנה)-תרצח. נספה בשואה."},{"i":52420,"n":"שור, אברהם אבא מקיטוב","f":"מאיר","b":"חתן ר חיים וגנר משאץ. רב בקיטוב. אחיינו של ר יצחק אלישע מקומפלונג וקיטוב."},{"i":52421,"n":"שור, אברהם חיים מסטנוב","f":"נפתלי הירש","k":"בעל תורת חיים","r":"אבד\"ק סטאנוב ובעלזא","bt":"1570","dt":"שצב - ט טבת","dp":"לבוב - (בלז?)","b":"רב בסטאנוב, בעלז-ליד לבוב. חיבר \"תורת חיים\" - שיטות על 9 מסכתות, \"צאן קדשים\" עם חברו ר מרדכי מברעזן. חתנו - ר צבי הירש בן עוזר מדובנא חיבר הקדמה לספרו \"תורת חיים\". נכדיו - ר מרדכי מוכיח מפרשבורג, ר חיים בן עוזר מהילדסהים הו\"ל את הספר עם תוספות ממנו. (חודש פטירתו לפי נכדו - שבט, באוצר תאריך פטירתו - תצב)","bk":[["תורת חיים","מפרשי ש\"ס - אחרונים"],["צאן קדשים",""],["תורת חיים – ש\"ס",""],["צאן קדשים (מהרח\"ש)",""],["תורת חיים ,שצ\"ב",""]],"e":"שצ\"ב [פטירה]"},{"i":52422,"n":"שור, אברהם יוסף מבוריסלב","f":"אלעזר מלמברג","k":"בעל חסד לאברהם","b":"מחכמי בוריסלב. תלמיד ר יעקב יצחק יוטס. חיבר \"חסד לאברהם\" דרוהוביטש תרמה."},{"i":52423,"n":"שור, אברהם ליב מפטרסבורג","f":"ישראל","bt":"תרנג","bp":"וארשא","b":"נכד (אבי אמו) ר מאיר גיטלסון מסלובודקא. תלמיד ישיבות מיר, טלז, סלובודקא. נסמך מאת: ר אליהו ברוך קאמאי, ר יצחק מפוניבז. חתן ר אברהם צבי פנחס מטיקטין וארץ ישראל, ובזיוו\"ש חתן הגביר ר ברוך קליאצקי. רב בפטרסבורג-ליד ליגאווקא-תרעז, קרילוב-פלך חרסון ויסד סניף לישיבת סלובודקא ועמד בראשה עם ר יחזקאל ברנשטין, שאקי-ליד קובנא-תרפב, היגר לארה\"ב-תרפו וכיהן כרב בסאוט בנד, קהלת אנשי פינסק בשיקגו-תרפט. פרסם חדושים רבים - רובם אבדו ברוסיה. עורך הירחון \"דער שיקאגער אידישע שטימע\". בנו - ר דניאל מקליבלנד, חתניו: ר מרדכי פרימק, ר דוד זופניק, ר יעקב זלמנוביץ."},{"i":52424,"n":"שור, אברהם מארה\"ב","f":"גדליה הלוי","k":"בעל מאוצר המחשבה","b":"חתן ר משה שאול פלוטשניק. חסיד גור. ר\"מ בישיבת \"קול יעקב\" בניו יורק. חיבר \"הגדה של פסח, מאוצר המחשבה\" ניו יורק תשמו."},{"i":52425,"n":"שור, אברהם מדינוב","b":"רב בדינוב לפני השואה."},{"i":52426,"n":"שור, אברהם מזמיגראד","b":"רב בזמיגראד"},{"i":52427,"n":"שור, אברהם מלבוב","f":"שמואל","b":"רב בלבוב. דודו(-אחי אביו) - ר אפרים זלמן בעל תבואות שור. בנו - ר יהודה ליב ונכדו ר אפרים זלמן מלבוב (שנפטר בשנת תלד)."},{"i":52428,"n":"שור, אברהם מסופיה","b":"דיין ביה\"ד האשכנזי בסופיה-שנות ה-תי'."},{"i":52429,"n":"שור, אברהם מפוזנא","f":"שמואל","b":"רב בפוזנא-רן. מצאצאי ר יוסף בכור שור. בנו - ר חיים, (יתכן והוא אבי משפחת שור בפולין)."},{"i":52430,"n":"שור, אברהם מפשמישל","dt":"תשב","b":"רב בפשמיש"},{"i":52431,"n":"שור, אברהם מרידיק","b":"מחכמי רידיק-תרלא."},{"i":52432,"n":"שור, אברהם עבריל מקראקא","dt":"שסג - יח שבט","b":"דיין בקראקא"},{"i":52433,"n":"שור, אברהם צבי ממנוסטרישץ","f":"שמואל יצחק","k":"בעל מנחת אברהם","bt":"תרכז","dt":"תשה","b":"רב במנוסטרישץ על מקום אביו וזקנו ר משה חיים. חתן ר פנחס ברנדויין מסטרטין. עלה לירושלים-תרסב. רכש בכסף רב את טליתו של ר ישראל מרוזין. עסקן ציבור וממונה כלולל ויזניץ-מרמורוש. נשיא ב\"ד חסידים. הוציא שבועון מחזיקי הדת תרעט-תרפג. חיבר \"מנחת אברהם\" ירושלים תרעא, ועוד. ?? לא באוצר ??"},{"i":52434,"n":"שור, אהרן בנציון מריטובה","b":"רב בריטובה."},{"i":52435,"n":"שור, אהרן יצחק שור למברג","b":"מחכמי למברג. בנו ר משולם צבי הביא לדפוס \"מעין החכמה\" - תקצד."},{"i":52436,"n":"שור, אהרן מיברוב","dt":"תקלו","b":"רב ביברוב-תקב."},{"i":52437,"n":"שור, אליהו יעקב דב","f":"חיים","k":"בעל נטיעות חיים","bt":"תרח","bp":"אניקשט","dt":"תרצו - כג אייר","dp":"ירושלים","b":"נכד ר מאיר הלוי אפשטין מוילנא. חתן ר נתן נטע בן משה מישל לוריא מקראקענאווי. רב בזופראן, ליאדי, בירז, ועיר הולדתו אניקשט על מקום ר שמואל אביגדור פיבלסון. מראשוני חובבי ציון בליטא. עלה לירושלים בשנת תרצב. חיבר ספר \"נטיעות חיים\" וילנא תרנב. \"ציון לנפש חיה\" בכתב יד"},{"i":52438,"n":"שור, אליהו-בר מאניקשט","b":"רב באניקשט על מקום ר שמואל אביגדור פיבלסון, ור אברהם מרדכי וכסלר על מקומו אחריו."},{"i":52439,"n":"שור, אליעזר זוסמן מצפת","b":"רב בצפת תקמ\"ג"},{"i":52440,"n":"שור, אליעזר ליפא שור ממיזון","b":"מחכמי מיזון (ליד דולינא). תשובה אליו ב\"מיכלא דאסותא\"."},{"i":52441,"n":"שור, אלכסנדר סנדר חיים מפשמישל","f":"ישראל מברודי","k":"בעל עלה לתרופה","bp":"ברודי","b":"נכד ה\"תבואות שור\". מחכמי פשמישל. עלה לירושלים. חתן הגביר ר יונה מזלוטופול. שינה שמו לברודסקי (על שם מוצאו - ברודי). היה עם בניו מעשירי היהודים ברוסיה. חיבר \"עלה לתרופה\" - בעילום שמו - תרלה (בהוראת ר חיים מצאנז). (הלוח נדפס בתוך הספרים \"נחלה לישראל\" ו\"ארזי לבנון\"). ?? לא באוצר ??"},{"i":52442,"n":"שור, אלכסנדר סנדר מזולקווא","f":"אפרים זלמן בן יהודה","k":"בעל שמלה חדשה","bt":"תל\"ג","dt":"תצז - כז שבט","dp":"זולקווא","b":"חתן ר מרדכי ר ליבושס מזולקווא. רב באולהנוב, מחכמי זולקווא, סירב לרבנות והתפרנס ממשרפות י\"ש בזולקווא. חיבר גם \"תבואות שור\", \"בכור שור\". חתניו - ר מנחם מניש מרגליות, ר שמואל שמלקא רוקח מזלוטשוב. חברו של ר יצחק איזיק בן אברהם מזולקוא ונקבר לצדו.","bk":[["בכור שור",""],["שמלה חדשה",""],["תבואות שור",""],["תבואות שור, שמלה חדשה , בכור שור",""]],"e":"תל\"ג~-תצ\"ז"},{"i":52443,"n":"שור, אלכסנדר סנדר מרדכי","f":"יעקב מדרנה-ווטרה","bt":"תרמא","bp":"דרנה-ווטרה","dt":"תשג","b":"חתן דודו רז\"ו למברג מקומרנא. רב וד\"ר בוינה. מלמד בסטרוזיניץ, יאסי-תרפא, בסרביה-תרפג. עלה לירושלים-תרפו, והיה מנהל סמניר למורות מזרחי. חיבר בגרמנית \"הדרכים בא\"י לפי יוסיפוס\" - תרעד, ובקיצור בעברית בספר היובל לרי\"ל מימון -תרפו. עסק בתרגום ספרי היסטוריונים רומים עם מקבילות ממקורות יהודיים. תרגם \"קדמוניות היהודים\" - תש."},{"i":52444,"n":"שור, אפרים זלמן","b":"נכד ר מנחם מנדל זולקוור מברודי. אחיו ר שלמה הורודנקר מברודי, ור יצחק חתן ר משה האדילס בלוצק. מו\"ל שעמד להוציא את התלמוד הירושלמי בוינה."},{"i":52445,"n":"שור, אפרים זלמן מבריסק","f":"נפתלי הירש(16244)","k":"בעל תבואות שור","dt":"שצד - כח תשרי","dp":"לובלין","b":"נכד ר יוסף בכור שור. חתן השר ר שאול וייל. מגדולי חכמי דורו, רב בשברשין-שעז, הורדנא, בריסק (יש אומרים לפני הב\"ח ויש אומרים אחריו) ובנו ר יעקב בעל \"בית יעקב\" על מקומו אחריו, לובלין. חתניו - ר יהודה ליב קצנלנבוגן בן מאיר, ר יעקב קופל בעליר מניימרק בן ר אהרן מולרשטין - אבי משפחת מירלס . (ר השל מבריסק היה מיועד להיות חתן חנלי בת ר שאול אך נתנה לבסוף לר יוסף - ועל כך הקפיד ואף סירב לתת סמיכה לבנה ר יעקב).","bk":[["תבואות שור הראשון",""]]},{"i":52446,"n":"שור, אפרים זלמן מלבוב","f":"יהודה ליב מלבוב","dt":"תלד - ד אייר","dp":"לבוב","b":"מגיד בלבוב. בנו - ר אלכסנדר סנדר בעל \"שמלה חדשה\"."},{"i":52447,"n":"שור, אפרים מקולומיאה","b":"שו\"ב בקולומיאה. תשובה אליו ב\"שושנים דוד\"."},{"i":52448,"n":"שור, אריה ליב מלבוב","f":"אהרן","b":"מראשי קהלת לבוב, חתם-תקי על שטר מתנה מטעם הקהלה."},{"i":52449,"n":"שור, אריה ליביש","b":"עוזרו של ר שלמה בובר."},{"i":52450,"n":"שור, בנימין מחעלם","bp":"למברג","b":"רב בחלם. מומחה בדיני ממונות ובוררות. חתן ר טודרוס לרר."},{"i":52451,"n":"שור, ברוך מלבוב","f":"חיים משה מפמורן","k":"ברוך חוטינר","bt":"תקפג","bp":"פמורן או למברג","dt":"תרסד - כא ניסן","dp":"לבוב","b":"נינו של ה\"תבואות שור\". חזן ראשי בחאטין (ונקרא בשם חוטינר), קמניץ-פודולסק, יאסי, בודפשט, למברג. נחשב לאחד מגדולי החזנים בדורו. עבר לארה\"ב (לאחר שרי\"א איטינגא פסלו בגלל מעשה שהיה שכתב מנגינה לתיאטרון העברי), חזר ללמברג. באסיפת חזנים בוינה-תרסא הוכתר כ\"מלך החזנים\". ששת בניו היו חזנים ידועים. חיבר \"בכור שור\" למברג תרלג, ועוד. בנו - ישראל הו\"ל \"נגינות ברוך שור\" ניו יורק תרסו."},{"i":52452,"n":"שור, גדליה מאיסטריק","f":"אברהם הלוי","bt":"תר","dt":"תרסט","b":"חסיד סדיגורא, דיין באיסטריק."},{"i":52453,"n":"שור, גדליה מאיסטריק ונ\"י","f":"אברהם הלוי מאיסטריק","k":"בעל אור גדול","bt":"תרעא","bp":"איסטריק","dt":"תשלט","b":"חסיד רוזין. היגר לארה\"ב-תרפא, למד בישיבת רי\"א. אחיו של ר יעקב שור-רב \"נתיבות עולם\" בניו יורק. רב בניו יורק ופעיל בצא\"י. ר\"מ שפירא שפגשו בביקורו בניו יורק העיד עליו \"זהו הראש הטוב ביותר שנזדמן לי לפגוש באמריקה\". חתן ר נחמיה איזבי מדטרויט. למד בקלצק אצל ר אהרן קוטלר. ראש ישיבת \"תורה ודעת\". חיבר \"אור גדליהו\" ניו יורק תשם."},{"i":52454,"n":"שור, גרשון מווסקביץ","b":"רב בבסקביץ-בוקובינה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":52455,"n":"שור, דוד","f":"אברהם","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":52456,"n":"שור, דוד יהודה מוילנא","f":"אלכסנדר חיים","dt":"תקסז","dp":"וילנא","b":"מחכמי וילנא. (לדעת פין הוא בנו של בעל תבואות שור - ואולי הוא בן נכדו הנקרא אלכסנדר חיים)."},{"i":52457,"n":"שור, דוד מטולנא","b":"רב בטאלנא-תר\"מ"},{"i":52458,"n":"שור, דוד מניו יורק","k":"בעל אילת השחר","b":"חיבר \"אילת השחר\" ניו יורק תשמה."},{"i":52459,"n":"שור, דניאל מארה\"ב","f":"אברהם ליב מארה\"ב","b":"תלמיד ישיבה \"תורה ודעת\" בניו יורק, טלז בקליבלנד. רב בקהלת \"שארית ישראל\" בקליבלנד."},{"i":52460,"n":"שור, הלל מקראסבאזאר","f":"בנימין מגאלאנטא","bt":"תרע","bp":"גאלאנטא","dt":"תשד - כג סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יהושע בוקסבוים מגאלאנטא. רב בגאלאנטא-תרצב על מקום אביו. נספה בשואה."},{"i":52461,"n":"שור, הלל מקראסבאזאר","b":"חתן ר יוסף בן ציון מיאלטא."},{"i":52462,"n":"שור, זאב וולף","f":"טוביה","k":"בעל מחזות החיים","bt":"1839-44","bp":"אניקשט","dt":"1910","dp":"שיקגו","b":"ממשפחת בעל \"תבואות שור\". תלמיד ביהמ\"ד לרבנים בוילנא. התישב בקובנא והתידד עם אברהם מאפו, עבר לברין והיה מקורב לבצי הרמן שפירא, ילינק, גידמן ועוד. ביקר במצרים, הודו, סין ועוד, ופרסם ב\"השחר\" אודות נסיעותיו. היגר לארה\"ב-1888 והו\"ל \"הפסגה\" בבולטימור, \"התחיה\" בשיקגו-תרס. עסקן ציןוני. ציר בקונגרס הציוני. חיבר גם \"נצח ישראל\", וערך את \"מסעות שלמה\" לשלמה ריינמן והוסיף הערות - אודות ארצות הודו וסין."},{"i":52463,"n":"שור, זאב וולף מסקלט","k":"בעל ספר הדרושים","b":"רב בסקלט. תלמיד ר משולם פייביש הלר מזבריז. חיבר \"ספר הדרושים\" מונסי תשנח - מכתב יד שהניח."},{"i":52464,"n":"שור, זלמן","dt":"תרעט","b":"נהרג עק\"ה"},{"i":52465,"n":"שור, חיים","f":"נפתלי הירש","b":"חתן ר שלמה פיינזילבר."},{"i":52466,"n":"שור, חיים מאוסטרהא","f":"יוסף ירחמיאל","dt":"תקכז","b":"פרנס מחכמי אוסטרהא-תקכג."},{"i":52467,"n":"שור, חיים מסלופקוביץ","b":"רב בסלפוקוביץ-תרכז."},{"i":52468,"n":"שור, חיים שמואל מבוקרשט","f":"יצחק איזיק מבוקרשט","k":"בעל השיב חיים","bt":"תרלא","dt":"תרצו - ג סיון","b":"נסמך מאת: ר חיים נתן דמביצר מקראקא, ר אברהם תאומים מזלישטשיק. רב בבוקרשט-תרנג על מקום אביו. התמנה לרב הראשי לרומניה, והיה מקורב לשלטון. בשליחות בניו יורק-תרפד מטעם הממשלה הרומנית. נכדו - ר יואל בער האדמור מרצפרט בסאן פאולו-ברזיל. חיבר \"השיב חיים\" - בכתב יד. הסכים על \"אהל יצחק\" - סטמר תרסג. פרסם מאמרים ב\"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה."},{"i":52469,"n":"שור, יהודה ליב מלבוב","f":"אברהם בן שמואל","b":"רב בלבוב-שצ. בנו - ר אפרים זלמן מלבוב, ונכדו - בעל תבואות שור."},{"i":52470,"n":"שור, יהודה ליב משריגרד","f":"יוסף עוזר מברסלב","k":"ר ליבלי ר ברוך'ס","dt":"תקסט","b":"חתן ר ברוך משריגרד. מוערך על ידי גדולי אדמורי דורו. בנו ר ברוך יוסף עוזר מהוש-רומניה. חיבר \"עיני ארי\" למברג תרס."},{"i":52471,"n":"שור, יהושע השל מקוריץ","f":"יקותיאל ברודא מקוריץ","dt":"תקעח - יח אדר","dp":"ברודי","b":"רב בקוריץ-תקנא, ברודי-תקסח. חתן דודו ר אברהם שור."},{"i":52472,"n":"שור, יוסף יהושע פאלק מלבוב","f":"משלם פיבש","dt":"תצט - אחרי","b":"דרשן, מו\"צ בלבוב, חתם-תעב בפנקס הקהלה, חתם-תפה על פס\"ד, חתם-תצט בענין מקום בבית כנסת, ועוד."},{"i":52473,"n":"שור, יוסף יהושע פאלק מלבוב","f":"משלם פייבוש","k":"בעל פני יהושע","b":"חתן הנגיד ר משה קזינר (המכונה ר משה ר ירחמיאלס). חיבר \"פני יהושע\" זולקוא תקב. (אולי הוא שחתם-תז עם ר אברהם גראפין ור שמריה הורביץ, ועוד). (יש בעיה עם התאריכים פעם תז ופעם תץ)."},{"i":52474,"n":"שור, יוסף יעקב מוינוטה","bt":"תרלח","dt":"תשב-ג","b":"רבה האחרון של וינוטה(=וינוטע). נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":52475,"n":"שור, יוסף מבקשביץ - א","f":"יצחק","b":"רב בבקשביץ-תקמא. ישבו בבית דינו - ר ברוך בנדיט ו אליקים גצל ב\"ר אליהו יפה."},{"i":52476,"n":"שור, יוסף מבקשביץ - ב","f":"יצחק","b":"פרנס בבקשביץ - עד תריא."},{"i":52477,"n":"שור, יעקב דוד מבוזנוב","b":"תשובה אליו \"בית יצחק\"-תריט."},{"i":52478,"n":"שור, יעקב הלוי מקרוז'","f":"אליהו","b":"מצאצאי הרמ\"א. חתן ר יחזקאל קצנלנבוגן מקידאן ואלטונא. רב בקראז(=קרוז)-תקמ. בנו - ר אברהם הלוי חתן ר מאיר גינצבורג מוויזון (ולא ככתוב באוצר - ר שמחה רפפורט - שהיה הסבא). מצאצאיו ר יחזקאל לנדא שהיה ראב\"ד בוילנא."},{"i":52479,"n":"שור, יעקב יוסף מקרטינגא","dt":"תרך","b":"רב בקרטינגא, פאקראי. בניו - ר צבי הירש מקרטינגא, ר שמואל מאיר מקידאן."},{"i":52480,"n":"שור, יעקב מאלסק","f":"אהרן ר אברמש הלוי","b":"רב בברודי, אלסק, ואחיו ר משה רב לצדו."},{"i":52481,"n":"שור, יעקב מברוזדוביץ","f":"משה חיים ממנוסטרישץ","b":"רב בברוזדוביץ-תרלב. אחיו של בעל \"מנחת שי\"."},{"i":52482,"n":"שור, יעקב מבריסק ולויצק","f":"אפרים זלמן מבריסק ול","k":"בעל בית יעקב","b":"נכד השר ר שאול וייל. חתן הגביר ר ישעיה בן ר משה ר ליזרש מבריסק. מו\"צ בבריסק-שצט, רב בלוצק(=לויצק)-תז, בריסק-תי על מקום אביו. חיבר חדושים על הש\"ס - כמוזכר בספר תלמידו \"בית הלוי\". נזכר ב\"חלקת מחוקק\" ובשו\"ת גאוני בתראי. (ר השלי מבריסק סירב לתת לו סמיכה בגלל קפידא שהיתה לו על אמו - ראה אצל אביו). חתניו - ר אליעזר ליפמן הלפרין, ר שאול קצנלנבוגן, ר יעקב אברהם בן נחמן, ר אברהם בן ר יצחק מזולקוא (ר אברהם דעס רב'ס(=רעביש))."},{"i":52483,"n":"שור, יעקב מטלוסט","k":"יעקב בן הפחח","b":"רב ומלמד בטלוסט-תרצב."},{"i":52484,"n":"שור, יעקב מלבוב","b":"דיין ומגיד בלבוב, חתם-תקכ ובשנת תקכח על פסק דין."},{"i":52485,"n":"שור, יעקב ממריאמפול","f":"צבי מבקשביץ","b":"רב במריאמפול-תרל, בקשביץ על מקום אביו."},{"i":52486,"n":"שור, יעקב מניו יורק","f":"אברהם","b":"אחיו של ר גדליה מאיסטריק-ניו יורק. רב קהילת \"המלאכים\" בניו יורק."},{"i":52487,"n":"שור, יעקב מקיטוב","f":"יצחק אלישע מטלומטש","k":"בעל דברי יעקב","r":"אב\"ד קוטב","bt":"תריג","bp":"טלומטש","dt":"תרפד - כח אב","b":"תלמיד לבעל השואל ומשיב. מיודד עם רי\"י יוטס ור שלמה בובר - והתכתבו ביניהם שנים רבות. חתן הגביר ר שאלתיאל איזיק הלוי הירש מקולומיאה. רב בדרנא-תרלח, לודמיר-תרמו וגורש על ידי הרוסים (היה שנה במאסר בגלל הלשנה של שוחט). ישב אצל הנדיב ר שמואל שטרויס מקרלסרוה - נכד הבעל שם ממיכלשטט-תרנב. יצא בשליחות הנדיב לירושלים ורכש את חצר שטרויס עבור משפחות ת\"ח. רב בקיטוב על מקום אביו (והיה מחלוקת על כך עם ר חיים גלרנטר שנתמך ע\"י חצרות סדיגורה וויזניץ). חיבר \"דברי יעקב\" קולומיאה תרמא, ועוד. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"אור תורה\" - לבוב תרפו, \"דגל התורה\" - וארשא תרפב, \"יגדיל תורה\" - וארשא-פראגא תרפז, \"שער בת רבים\" - וארשא תרפב, \"שערי תורה\" - וארשא תרסג, \"הנשר\" - פרשבורג - בהיותו בן 13!","bk":[["בעי חיי – על רבנו בחיי עה\"ת",""],["ברכת יעקב – ברכות",""],["דברי יעקב – שו\"ת",""],["הכרעת התלמיד – ע\"ס המכריע",""],["ישועות יעקב – תענית",""],["מי באר – שו\"ת ופלפולים",""],["מצות חינוך",""],["מקור חכמה – על רש\"י עה\"ת",""],["משנת רבי יעקב – מעילה, תוספתא",""],["עתים לבינה – על ספר העיתים",""]]},{"i":52488,"n":"שור, יצחק איזיק","bt":"ה'תקצו","dt":"ה'תרנד","b":"חתם עם רבני לבוב-תן על תקנת הקהלה (זולקוא) שנעשו בקוליקוב.","bk":[["תולדות אדם [קיצוש\"ע אהע\"ז]",""],["הרא\"ש","שו\"ת"]]},{"i":52489,"n":"שור, יצחק איזיק מבוקרשט","f":"מאיר מזולוקוא","k":"בעל תפארת ישראל","bt":"תקצו","bp":"רדיויץ","dt":"תרנד - כז אד\"א","b":"חסיד בלז. תלמיד זקנו ר אהרן משה טויבש. חתן ר לוי יצחק פרנקל-אשכנזי מיריטשוב. רב באזא (מודלביה), בוקרשט-תרכט לצד חותנו, ואחר כך על מקומו, (לצד רי\"מ שפילמן), (תמך ברב מסיגט בעת המחלוקת בבוקרשט), בנו ר חיים שמואל על מקומו אחריו, וכן חתנו ר דוד צבי שנפלד. חיבר \"תפארת ישראל\" למברג תרלב, ועוד."},{"i":52490,"n":"שור, יצחק איזיק מיריטשוב","f":"ישראל מיריטשוב","k":"בעל מנחה חדשה","bt":"תצ","dt":"תקס","b":"ממשפחת צבי ומרגליות.חתן הגביר ר מאיר ממאהלוב וישב אצלו. רב ביריטשוב על מקום אביו, ועמד בראש ישיבה. חיבר \"מנחה חדשה\" אלקנסיץ תקלד, ועוד. ספרו \"בית שערים\" - בכת\"י. בנו - ר דב בער."},{"i":52491,"n":"שור, יצחק איזיק מרידיק","f":"ישעיהו","bt":"תרם","bp":"רידיק","b":"תלמיד ר אברהם חיים פילרסדורף. חתן ר אברהם שיץ. עלה לארץ-תרצב. צייר אמן."},{"i":52492,"n":"שור, יצחק אלישע מטלומטש","f":"מאיר","k":"בעל ועד חכמים","bt":"תקף","dt":"תרנה","b":"רב בטלומטש-תרו, קיטוב, קומפלונג-תרך, בקשביץ-תרכה, קיטוב-תרלא. חיבר \"ועד חכמים\" למברג תרלא\" ועמו \"מאיר עיני חכמים\" לבנו ר יעקב. סיפור תולדותיו ע\"י ר יוסף כהן צדק - \"המבשר\" תרכד. (בהמשך לכתבה שלח הרב מכתב לעורך ובו חשף את שמות 3 הקמים עליו בבקשביץ - ואשר הבריחו את 6 הרבנים שקדמו לו, והם: ר יונה שעבר לסקלט, רצ\"ה הורביץ לסנוק, ר יואל אשכנזי לחודרוב, ר בנימין אלנברג ללמברג, ר שלמה אחי הרב מזלוטשוב שעלה לארץ, ור יואל בנו - בתגובה נתבעו העורך והרב בערכאות). ?? לא באוצר ??"},{"i":52493,"n":"שור, יצחק מגווזדיץ","f":"אברהם מזמיגרוד","k":"בעל כח שור","bt":"תס","bp":"ליסקא","dt":"תקלד - ל שבט","b":"רב בקליש, גווזדיץ. נפגש 3 פעמים עם הבעשט. בניו ר יעקב מפאטיק, ור אברהם מבוקרשט. חיבר \"כח שור\" קולומיאה תרמח (הובא לדפוס ע\"י נכדו ר אבנר כתבן מבראיולוב וקריובה). מחותן עם ר מאיר מרגליות בעל מאיר נתיבים המזכירו בספרו."},{"i":52494,"n":"שור, יקותיאל זלמן שור מדוקלא","f":"יעקב אברהם מנרול","b":"רב בדוקלא, האציפלאץ. הוציא לאור \"אור הישר\" עם הערות משלו - למברג תרסב, ספרו \"יד מלאכי\" עם הערות נדפס בספר \"זכור לאברהם\" - תשנג."},{"i":52495,"n":"שור, יקותיאל מליביטשוב","f":"לוי יצחק דב מראווה","bt":"תרב או תרך","dt":"תרף","b":"חתן ר דב בר הורשובסקי מליביטשוב, רב בליביטשוב לצד חותנו, רב בראווה לצד אביו, רב בליביטשוב על מקום חותנו (לאחר מחלוקת שהיתה על הרבנות עם רי\"ה פרנקל - ונבחר בתמיכת האדמור מהר\"י מבלז). בנו ר לוי יצחק דב על מקומו אחריו."},{"i":52496,"n":"שור, ישעיה מהורודנקה ויאס","f":"משה","k":"בעל כנפי נשרים","r":"אב\"ד בהארידנקא, וחאטין ובסוף ימיו אב\"ד יאס","bt":"תקלט-תקמ","bp":"מיקוליניץ","dt":"תרלט - כז אדר","b":"תלמיד ר מרדכי מקרמניץ - ששלחו לתהות על קנקן חתנו - ר אהרן מקרלין. מקורב ל\"אוהב ישראל\", ולאדמורי זידיטשוב וקוסוב. חתן הגביר ר זאב מטרנירודה, ובזיוו\"ש חתן ר יוסקא בן ר מרדכי מקרמניץ (רבו). רב בהורודנקה (בהשפעת הדע\"ק), חאטין, דולינא, זברז, יאסי-תרי על מקום ר יוסף לנדא בעל \"ברכת יוסף\". תלמידו - ר ישראל אברהם פורטוגל מסקולען בעל \"שם ושארית ישראל\". (במחלוקת עם המשכילים ועורכי \"קורות העתים\" ביאסי). חיבר גם \"כליל תפארת\", \"חזון ישעיהו\" מרמורש-סיגט תרסה. חתנו ר יצחק ליבוש טויב על מקומו בחאטין ויאסי. בנו ר דוד מרדכי חתן יוסף לנדא אב\"ד ליטין ויאס.","bk":[["כליל תפארת - על התורה",""],["כנפי נשרים",""]]},{"i":52497,"n":"שור, ישעיה מזברז","b":"רב בזבארז,עזב וחזר לברודי-תקנ\"ח"},{"i":52498,"n":"שור, ישראל הכהן מחירוב","b":"מצאצאי ה\"תבואות שור\". חזן בחירוב, רימנוב. מחבר הנעימה \"שיבנה המקדש\"."},{"i":52499,"n":"שור, ישראל מבוצאץ","b":"נסמך מר מאיר ארק, בעל תואר ד\"ר. רב קהילת בית אל בבורו פארק."},{"i":52500,"n":"שור, ישראל מיריטשוב","f":"יעקב","k":"בעל עיני ישראל","bt":"תע","dt":"תקן","b":"רב ביריטשוב-תקלג ובנו ר יצחק איזיק על מקומו אחריו, רב במוהילב. נדד בין הקהלות להרביץ תורה. חיבר \"עיני ישראל\" - מנחת ישראל\" - אלקסניץ תקלה."},{"i":52501,"n":"שור, לוי יצחק דב מליביטשוב","f":"יקותיאל מליבבטשוב","bt":"תרם","dt":"תשב","b":"רב בליביטשוב על מקום אביו. נספה בשואה."},{"i":52502,"n":"שור, לוי יצחק דב מפודקמין","f":"מנחם מנדל מברודי","k":"בעל עטרת תפארת","bt":"תקע","dt":"תרלז","b":"רב בפודקמין-תרא, ראווה-תר. בנו ר יקותיאל רב בליביטשוב. חיבר \"עטרת תפארת\" מונקטש תרעב."},{"i":52503,"n":"שור, לוי יצחק מראוה","dt":"תרכ","b":"רב בראווא"},{"i":52504,"n":"שור, לוי מברוד","f":"שלמה","k":"בעל בית לוי","bt":"תמ","bp":"זולקוא","dt":"תקיב","dp":"סטניסלב","b":"דיין בברודי. חיבר \"בית לוי\" זולקוא תצב. בנו ר מאיר אביו של ר יצחק אלישע מטלומטש."},{"i":52505,"n":"שור, מאיר מבקשביץ","f":"יצחק אלישע מקיטוב","b":"אחיו של ר יעקב מקיטוב"},{"i":52506,"n":"שור, מאיר מרדיויץ","f":"רפאל","dt":"תרנא - לפני","b":"גביר מחכמי רדיויץ. חתן רא\"מ טויבש מיאסי. בנו ר יצחק איזיק - רב בבוקרשט."},{"i":52507,"n":"שור, מנחם מנדל מברוד","f":"יקותיאל ברודא מקוריץ","bt":"תקל","dt":"תקפט","b":"חתן הגביר ר ברל צלניקר מברודי. אחיו של ר יהושע השל מקוריץ."},{"i":52508,"n":"שור, מנחם מנדל מברוד","f":"לוי יצחק דב מפודקמין","k":"בעל תורת מנחם","bt":"תקצא","dt":"תרסג - כא שבט","b":"רב בברודי-תרכז. חיבר \"תורת מנחם\" מונקטש תרסג ובראש הספר אגרת יוחסין של המחבר מאת ר אברהם איטינגא מברוד."},{"i":52509,"n":"שור, מרדכי ממורניצא","f":"מאיר","b":"מחכמי ממורניצא. תשובה אליו ב\"תולדות אדם\""},{"i":52510,"n":"שור, משה","f":"מנחם מנדל מסטנוב","b":"חתן ר אריה יהודה ליביש ממיקלניץ. בנו ר ישעיה מיאסי - נולד תקלט."},{"i":52511,"n":"שור, משה אפרים","f":"חיים","b":"רב-שנת ש'. בנו - ר נפתלי הירש, ונכדו - ר אפרים זלמן מבריסק."},{"i":52512,"n":"שור, משה חיים ממנוסטרישץ","f":"שמואל שמלקא","bt":"תקף","dt":"תרנא","b":"רב במנוסטרישץ על מקום אביו. חתן ר יצחק ממזריטש, בנו ר שמואל יצחק על מקומו אחריו. נקרא גם בירנבוים."},{"i":52513,"n":"שור, משה מבוליחוב","f":"אהרן ר אברמש הלוי","b":"רב בבוליחוב, אלסק על מקום אחיו ר יעקב."},{"i":52514,"n":"שור, משה מבוצאץ","b":"רב בבוטשטש-ת\"ר"},{"i":52515,"n":"שור, משה מסטנוב","f":"מנחם מנדל מסטנוב","b":"חתן ר אריה יהודה ליב ממיקוליניץ. ובנו היה ר ישעיה מהורודנקה. מתורתו ע\"י רמ\"מ ויזניצר בתוך \"אז נדברו\" - תשמו. פגש את הבעשט בילדותו בסטנוב."},{"i":52516,"n":"שור, משה מפשמישל","b":"רב בפשמישל-תרכג."},{"i":52517,"n":"שור, משה מקראקא","f":"נפתלי","k":"משה ר ענזילש","dt":"תנד - ה אב","dp":"קראקא","b":"ראב\"ד בקראקא-תמח."},{"i":52518,"n":"שור, משה מרדכי מברזן","b":"סופר בברזן."},{"i":52519,"n":"שור, משלם פיבש מלבוב","b":"דיין בלבוב, חתם-תצט על תקנה."},{"i":52520,"n":"שור, נחמן מסלוצק","f":"יהודה ליב","dt":"תקכט - כא ניסן","b":"מחכמי אוסטרהא."},{"i":52521,"n":"שור, נפתלי הירש מבריסק","f":"משה אפרים","dt":"שמז - ז שבט","b":"חתן ר ישראל מלובלין-גיסו של הרמ\"א בנו ר שלום שכנא מלובלין. מגדולי חכמי דורו, רב בבריסק, לובלין. מתלמידיו ר יואל סירקיש בעל הב\"ח. בניו - ר אפרים זלמן(3101), ר אברהם חיים(1087), ר שמואל(19411), חתנו - ר אליעזר ילפמן הלפרין(2685)."},{"i":52522,"n":"שור, נפתלי הירש עלזאשר","f":"זלמן שור ממהרין","b":"חתן ר ישראל מלובלין. תלמיד הרמ\"א. מחכמי פוזנא. נזכר בשו\"ת הרמ\"א. מתלמידיו ר יואל סירקיש בעל הב\"ח. בניו: ר חיים בעל \"תורת חיים\", ר אפרים זלמן בעל \"תבואות שור\". יש שכתבו שהיה אב\"ד בריסק ומחותנו של הגביר ר שאול וייל."},{"i":52523,"n":"שור, צבי הירש מבריסק","f":"זלמן ממעהרין","k":"הירש עלזאסר","b":"תלמיד הרמ\"א (ונזכר בתשובותיו). מתלמידיו - בעל הב\"ח."},{"i":52524,"n":"שור, צבי הירש מקראקא","f":"אברהם חיים שור","k":"בעל נטע שעשועים","dt":"שצה - יב שבט","dp":"קראקא","b":"חתן ר נתן שפירא בעל מגלה עמוקות (ולאחר שנפטר נישאה לר אברהם ז\"ק - שנפטר בשנת תה). תלמיד הרמ\"א, ור שלמה חסיד מלובלין. מגדולי חכמי קראקא. נפטר צעיר."},{"i":52525,"n":"שור, צבי הירש מקרטינגא","f":"יעקב יוסף מקרטינגא","b":"רב בקרטינגא-תרן - בערך'."},{"i":52526,"n":"שור, צבי זאב מוינוטה וקרטינגה","dt":"תרפט","b":"רב בוינוטה על מקום ר בנימין פרבר, קרטינגה וחתנו ר בנימין פרסקי הי\"ד על מקומו אחריו."},{"i":52527,"n":"שור, קלונימוס קלמן","b":"חתן הרב מקומרנא. תשובה אליו \"מנחת הקומץ\"-תרסו."},{"i":52528,"n":"שור, קלמן מבריסק","b":"רב בבריסק-של. נזכר בשו\"ת מהרש\"ל."},{"i":52529,"n":"שור, רפאל","f":"גדליה","k":"בעל משנת הלוי","b":"חתן ר\"י פישר (חתן הרב ממטרסדורף). ראש ישיבת \"אמרי חיים\" במונסי. חיבר \"משנת הלוי\" מונסי תשנד."},{"i":52530,"n":"שור, שמואל יצחק ממנוסטרישץ","f":"משה חיים ממנוסטרישץ","bt":"תקצט","dt":"תרסב","b":"חסיד צורטקוב. זקנו של המהר\"ם מלובלין. רב בקניהניטש-תרכט, מנוסטרישץ על מקום אביו. חתן ר שמשון מרגליות מזלוזיץ. חתנו - ר יעקב שמשון שפירא. בנו ר אברהם צבי על מקומו אחריו וראב\"ד קהילת החסידים בירושלים. חיבר שו\"ת \"מנחת שי\" למברג תרנא.","bk":[["מנחת שי","שו\"ת - אחרונים"],["מנחת שי [שו\"ת]",""]]},{"i":52531,"n":"שור, שמואל מאיר מקידאן","f":"יעקב יוסף","bt":"תרח","dt":"תרנח","b":"רב בפוקרוי-ליטא על מקום ר נחום שפירא. אחיו - ר צבי הירש מקרטינגא."},{"i":52532,"n":"שור, שמואל מטורבין","f":"נפתלי שור","dt":"שצב - כ תמוז","b":"רב בטורבין"},{"i":52533,"n":"שוראניער, י' מ' נפתלי","dt":"תרלט - א תשרי","b":"רב בקדלבורג"},{"i":52534,"n":"שוראקי, אליהו מאלגיר - א","bt":"שך","dt":"ת - בערך","b":"רב ומשורר בתלמסאן. קינות ממנו בכת\"י מתלמסאן."},{"i":52535,"n":"שוראקי, אליהו מאלגיר - ב","bt":"שסו - בערך","dt":"תסו","b":"רב ומשורר בתלמסאן. מפיוטיו ב\"שבחי אלקים\", ועוד. נפטר בגיל מעל 100."},{"i":52536,"n":"שוראקי, אליהו מאלגיר - ג","bt":"תקך","dt":"תקץ - בערך","b":"רב בתלמסאן."},{"i":52537,"n":"שוראקי, אלישע מאלגיר","bt":"תך","dt":"תץ - בערך","b":"רב בתלמסאן. נזכר ברשימת ר יצחק רוש."},{"i":52538,"n":"שוראקי, אפרים מאלגיר","bt":"קץ","dt":"רס - בערך","b":"דיין בתלמסאן, דברי תוכחה אליו מר צמח דוראן."},{"i":52539,"n":"שוראקי, יהודה מאלגיר","bt":"שך","dt":"שץ - בערך","b":"דיין בתלמסאן. התכתב עם ר אברהם עוזיאל מפאס-שע."},{"i":52540,"n":"שוראקי, יעקב מגיברלטר","b":"מחכמי גיברלטר, חתם על פס\"ד-תפה עם ר אברהם מונסון."},{"i":52541,"n":"שוראקי, יצחק","b":"רב-שנת תצ\"ט"},{"i":52542,"n":"שוראקי, יצחק מאלגיר","f":"יוסף","b":"רב בתלמסאן, ווהראן, אלגיר, פגש את ר חיים ן עטר בהיותו באלגיר, והסכים על ספרו \"ארחות חיים\". תשובה ממנו ב\"פרי צדיק\", ועוד."},{"i":52543,"n":"שוראקי, מרדכי מאלגיר","f":"סעדיה","dt":"תקס","dp":"אלגיר","b":"גביר מחכמי תלמסאן, מקורב למלך סידי מוחמד - בשנים תקיז-תקן, וסייע רבות ליהודים. נהרג עק\"ה בידי אנשי המלך."},{"i":52544,"n":"שוראקי, משה מאלגיר","bt":"של","dt":"תי - בערך","b":"דיין בתלמסאן, ערער על גט שכתב ר נתנאל קרשקש ועל כך הוכיחו שלמה צרור בספרו \"חוט המשולש\"."},{"i":52545,"n":"שוראקי, משה מצפת","b":"כנראה מוצאו באלגיר. דיין בביה\"ד הספרדי בצפת, בשליחות-תריג באדרינופול, ובצפון אפריקה-תרכב. בשנת תרכח חתם עם חכמי צפת."},{"i":52546,"n":"שוראקי, סעדיה מאלגיר","f":"אליהו","k":"בעל מונה מספר","bt":"ת","dt":"תף - בערך","b":"רב בתלמסאן-אלגיר-תנה. מכתב של היעב\"ץ (ר יעקב ן צור) הפונה אליו לעזרה לשד\"ר ירושלים ר אברהם ביטון. חיבר גם \"שיר חדש\"."},{"i":52547,"n":"שוראקי, סעדיה מאלגיר - א","bt":"קע","dt":"רמ - בערך","b":"רב בתלמסאן בזמן הרשב\"ש שכתב אליו. הרב הראשון הידוע מבני המשפחה."},{"i":52548,"n":"שורביאל, משה מברושא","b":"רב בברושא(=ברוסא) - בדור שלאחר הגירוש."},{"i":52549,"n":"שורזינר, יעקב כץ מקראקא","k":"יעקב כץ איש קוסטילץ","b":"ארי שבחבורה,מגדולי חכמי קרקא-ש\"ס"},{"i":52550,"n":"שוריאנו, יצחק משלוניקי","dt":"שה - י אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":52551,"n":"שורין, משה מריטובה ונ\"י","dt":"תשב - ז תשרי","b":"ר\"מ בריטובה, רב בארה\"ב."},{"i":52552,"n":"שורץ, א.ש.","bt":"1876","bp":"ז'אזמיר","dt":"1957","dp":"ניו יורק","b":"היגר לארה\"ב ולמד רפואה. פרסם שירים ב\"התורן\", \"הדואר\". מראשני המשוררים העבריים בארה\"ב. כמה משיריו התפרסמו באנתולוגיה של השירה העברית באמריקה."},{"i":52553,"n":"שורץ, אבא ממישיגאלע","dt":"תש","b":"רב במישיגאלע(ליטא)"},{"i":52554,"n":"שורץ, אברהם אבא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":52555,"n":"שורץ, אברהם הרש מפאלאטא","dt":"תרם - בערך","b":"מו\"ץ בפאלאטא(=וארפלאטה) בזמן ר בנימין זאב חיות."},{"i":52556,"n":"שורץ, אברהם יהודה הכהן","f":"יצחק מאיר מדרגמירשט","k":"בעל ישועות אברהם","bt":"תרמד","bp":"דראגמירשט","dt":"תשד","b":"תלמיד ה\"קדושת יו\"ט\" בסיגט. חתן ר חיים פרידמן מדאמבראד. ראש ישיבה בקולטשא-ליד פהאר-ג'ארמאט. רב במארוש-העויז(=מאראץ-העוויס). רבה הראשון של טופליצה(=שאפליצא)-תרסט כ-35 שנה. נספה בשואה. החל להדפיס \"ישועות אברהם\" והפסיק בגלל השואה. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישובה תרפח, \"לקט ששנ\"ה\" - סטמר תרצד. ?? לא באוצר ??"},{"i":52557,"n":"שורץ, אברהם יהודה הכהן מברגסאס","b":"פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":52558,"n":"שורץ, אברהם יהודה הכהן משאלא","f":"נפתלי - בית נפתלי","k":"בעל זכרון לראשונים","bt":"תרמד","dt":"תשד","dp":"אושוויץ","b":"רב בשאלא, פרשבורג. חתן ר יוסף מילר מגאלאנטא. עורך \"הנשר\" - טירנוי תרצג-תשד. חיבר \"זכרון לראשונים\", \"זכור ימות עולם\", \"שם הגדולים הרביעי\", ועוד. נספה בשואה."},{"i":52559,"n":"שורץ, אברהם יהודה ליב מברגסאס","f":"פנחס זליג חסיד הכהן","k":"בעל קול אריה","r":"אב\"ד ברגסס, ומאד","bt":"תקפד","bp":"העדילא-מאדע","dt":"תרמד - כד תשרי","dp":"העדילא-מאדע","b":"תלמיד ר שמואל גינז-שלזינגר מאבראהאם, וחת\"ס. תלמיד הדברי חיים מצאנז. חתן ר משה יהודה ליב גינצלר מאוהעל, ועבר לשם. רב בהעדילא-מאדע-תרז, ברגסאס-תרכא וחתנו ר אליעזר צוקר בעל מגדנות אליעזר על מקומו אחריו, העדילא-מאדא-תרמא (חזר לשם שנית) ובנו ר נפתלי בעל \"בית נפתלי\" על מקומו אחריו. חיבר \"קול אריה\". עוד מחתניו: ר יעקב ארנרייך-אבי ר שלמה זלמן אב\"ד שמלוי, ור חיים צבי אב\"ד מאדע. מתורתו ב\"קובץ מפרשי התורה\" - מארגרטן תרצג.","bk":[["ליקוטי קול אריה",""],["קול אריה – שו\"ת, תהילים, זמירות לשבת קודש, תורה ומועדים, הגדה של פסח",""],["קול אריה (שו\"ת)",""]],"e":"תקפ\"ד-תרמ\"ד"},{"i":52560,"n":"שורץ, אברהם יהודה ליב משימאני","f":"יוסף שמואל שורץ","b":"רב בשימאני-תרי\"ח"},{"i":52561,"n":"שורץ, אברהם יהודה מפוטיק","dt":"תרצד","b":"תלמיד המהרש\"ם. רב בפוטיק (של חסידי צורטקוב) לצד האב\"ד הרב צוייג. תשובה אליו מהמהרש\"ם מברעזן ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":52562,"n":"שורץ, אברהם יוסף מטאליא","f":"יצחק מטאליא","bt":"תרלה","bp":"טאקטא-קענעז","dt":"תש..","dp":"אושוויץ","b":"תלמיד השב\"ס, ור יעקב יוסף גינז מביסערמן. חתן ר מאיר ישעיה לפקוביץ מליסקא. מחכמי טאליא. נספה בשואה. רשם מתורת רבו הכת\"ס-תרנח."},{"i":52563,"n":"שורץ, אברהם ליב הכהן מזיבנבירג","b":"רב במאר-האשעוויץ, זיבנבירגן. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. (אחר פטירתו?)"},{"i":52564,"n":"שורץ, אברהם מאבדוקה","f":"ישראל","bt":"תרכ","b":"רב באבדוקה(=האבעדיווקא)-פודוליה-תרסא."},{"i":52565,"n":"שורץ, אברהם מדוברומיל","f":"זאב וולף","k":"אדמור מזינקוביץ","bt":"תרכו","bp":"דוברומיל","dt":"תר.. - בערך","b":"רב ואדמור בזינקוביץ, דוברומיל ופשמישל. עלה לארץ - לפני מלחמת העולם הראשונה. (אלמנתו פיגא רבקה נשאה אחר פטירתו לאדמור מללוב ר שמעון נתן בידרמן). חתנו היה ר משה מרדכי בידרמן מללוב. חיבר \"דבר אברהם\" שיצא לאור ע\"י חתנו - ירושלים [תשל]."},{"i":52566,"n":"שורץ, אברהם מס. וואראהל","f":"חיים ממישקולץ","dt":"תשד","b":"נכד האדמור ר צבי הירש פרידמן מליסקא. חתן ר ישכר דב הלוי מוואראהל. רב בוואראהל-תרצד על מקום חותנו. היה מחלוקת עם קבוצת חסידים שכינו עצמם \"קהל יראים דפה סעאיני ס. וואראהל\" והוציאו נגדו כרוז וטענו שבגללו הורחק הדיין ר משה שלום וייס מחסידי סטמר - ולבסוף השלימו, עמד בראש ישיבה קטנה שם. נספה בשואה. (לפי חכמי הונגריה - רב בוארול על מקום ר מיכאל צבי שינפלד שעלה לארץ-תרמד ?)."},{"i":52567,"n":"שורץ, אברהם נחמן מקרק וארה\"ב","f":"חיים משידלובא","bt":"תרלב","bp":"כפר לענץ ליד קרוק-פלך קוב","dt":"תרצז - כג שבט","dp":"בולטימור","b":"תלמיד ישיבת טלז, קרוק, כולל וילנא. נסמך מאת: ר אלכסנדר משה לפידות מראסיין, ר יוסף זכריה שטרן משאוועל, ר רפאל שפירא, ר יצחק אלחנן מקובנא. חתן ר אלחנן פרייל, וגיסם של ר אלעזר בעל \"המאור\" ור יהושע יוסף מקרוק בעל \"אגלי טל\". ר\"מ בקרוק-תרנה, רב בנאווע אדעס-תרנח, היגר לארה\"ב-תרסז וכיהן כרב בניו לונדון-קונטיקט, בולטימור-ארה\"ב-תרסח ויסד שם ישיבה (הראשונה מחוץ לניו יורק). פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו. בנו - ד\"ר יהושע יוסף שורץ, חתניו - ר ניסן וקסמן מלייקווד, ר רפאל פוליאקוב, ר משה ראובן חריק מבולטימור, ר אהרן פייפרמן מפליינפליד-ניו ג'רזי."},{"i":52568,"n":"שורץ, אברהם שמואל מארה\"ב","bt":"תרלו","bp":"זעזמיר","b":"חתן המטיף צ\"ה מסלונסקי. רופא, משורר עברי בניו יורק."},{"i":52569,"n":"שורץ, אהרן ישעיה מגרוסורדין","b":"מחכמי גרוסורדין."},{"i":52570,"n":"שורץ, אליעזר מפאטאק","f":"יצחק אהרן","bt":"תרכט","bp":"סיגט","dt":"תשד","b":"תלמיד בעל \"קדושת יו\"ט\". מרביץ תורה ודיין בפאטיק(=פאטאק,פוטוק)-תרנו וראש ישיבה."},{"i":52571,"n":"שורץ, אריה ליב מפרשבורג","b":"מלמד בביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה."},{"i":52572,"n":"שורץ, אריה מקרלסרוהא","bt":"תרו","bp":"טבל-ליד פאפא","dt":"תרצא","b":"תלמיד ביהמ\"ד לרבנים בברסלוי אצל ר זכריה פרנקל, בעל תואר ד\"ר. רב בקרלסרוהא-תרלה - תרנג, ראש בית המדרש לרבנים בוינה."},{"i":52573,"n":"שורץ, אשר אנשיל מגרוסורדין","b":"ראש הקהל בגרוסורדין. חתנו - ר יצחק יוחנן שטרסר מגרוסורדין."},{"i":52574,"n":"שורץ, אשר אנשיל מדברצין","f":"שלמה יוסף מדברצין","b":"תלמיד הכת\"ס והשב\"ס, ור אברהם יצחק וינברגר מקלינורדין, ור מאיר מפרלס מקראלי."},{"i":52575,"n":"שורץ, אשר אנשל מיארמוט","f":"צבי הירש מיארמוט","b":"תלמיד בעל \"מעשי למלך\" בוייצען. מכתב ממנו אצל ברוין."},{"i":52576,"n":"שורץ, אשר אנשל מניו יורק","f":"יצחק יהודה","b":"מחכמי ניו יורק, מכתב ממנו-תרנט אל ר עקיבא יוסף שלזינגר."},{"i":52577,"n":"שורץ, בנימין זאב ממנאשטור","f":"יקותיאל ממנאשטור","dt":"תרצח - כה ניסן","b":"תלמיד השב\"ס, ור יצחק זעקל פולק מבאניהאד ור יהודה גרינולד מסטמר. רב בממנאשטר-ליד סטמר-תרנז על מקום אביו וחתנו ר חיים משה פיש על מקומו אחריו."},{"i":52578,"n":"שורץ, בצלאל מגרוסורדין","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":52579,"n":"שורץ, ברוך יוסף הכהן","b":"רב בפלאנטש"},{"i":52580,"n":"שורץ, גבריאל מגרוסורדין","b":"חתן ר משה רייך ממעדיאש. רבה האחרון של גרוסורדין לאחר השואה."},{"i":52581,"n":"שורץ, דב","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":52582,"n":"שורץ, דוד מאיר","b":"תלמיד ישיבת אויהל. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":52583,"n":"שורץ, דוד מרדכי","f":"משה","bt":"1871","bp":"קובנא","dt":"1950","b":"למד רפואה בוארשא. חתן יעקב רכס מקובנא-מורה לדת היהודית בבי\"ס ממשלתיים. רופא בקובנא, מראשי התנועה הציונית בליטא, ציר בקונגרס הציוני. ממיסדי \"ספריית מאפו\" והגימנסיה הריאלית העברית. עלה לארץ-1935 והתישב בתל אביב."},{"i":52584,"n":"שורץ, ויליאם סמואל","bt":"1896","bp":"סמרגון","b":"תלמיד ביה\"ס לאמנות בוילנא. התפרסם כצייר פסל וליטוגרף."},{"i":52585,"n":"שורץ, חיים אליהו מנירדהאזא","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":52586,"n":"שורץ, חיים בן ציון מיאסין","dt":"תשד","b":"רב ביאסין"},{"i":52587,"n":"שורץ, חיים הכהן מטופליצה","f":"אברהם יהודה מטופליצה","dt":"תש..","b":"תלמיד דודו זקנו ר שלמה זלמן ארנרייך בשאמלוי. רב הצעיר בטופליצה לצד אביו. נספה בשואה. פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":52588,"n":"שורץ, חיים הכהן ממהעוויז","dt":"תש","b":"רב במ'העוויז"},{"i":52589,"n":"שורץ, חיים יצחק הכהן מסטבניץ","b":"מתורתו ב\"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו."},{"i":52590,"n":"שורץ, חיים יצחק מקרסני","dt":"תשג","b":"רב בקרסנא"},{"i":52591,"n":"שורץ, חיים מהירבין","b":"רב בהירבין-תר\"כ"},{"i":52592,"n":"שורץ, חיים ממאראשהעויז","b":"רב הצעיר במארשאהעוויז."},{"i":52593,"n":"שורץ, חיים ממישקולץ","f":"אברהם","k":"אדמור ממישקולץ","dt":"תשד","b":"נכד - מצד אמו - ר צבי הירש פרידמן האדמור מליסקא. רב ואדמור במישקולץ. נספה בשואה."},{"i":52594,"n":"שורץ, חיים משה מבזל","f":"דוד מברעזאווא","bt":"תרלא","bp":"ברעזאווא","dt":"תשו - יא כסלו","dp":"בזל","b":"תלמיד השב\"ס, ור מרדכי יהודה וינקלר מברעזווא. חתן ר אהרן ריין מבזל. רב בבאדן (שוויץ)-תרס, בזל (שוויץ). מחדושי רבו שרשם - נדפסו ב\"שבט סופר\"."},{"i":52595,"n":"שורץ, חיים שלמה הכהן מדינקיוו","f":"יהודה ישעיה שוורץ","bt":"תרמה","dt":"תשג - כב תשרי","b":"רב בדינקיוו,בוגוריי,וויסליץ-תרס\"ד"},{"i":52596,"n":"שורץ, ידל משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":52597,"n":"שורץ, יהודה אריה ליב מזלוטשוב","k":"בעל שירי אמונים","bp":"זלוטשוב","b":"מחכמי זלוטשוב. חיבר \"שירי אמונים\" למברג תרמא - כנגד המשכילים וכנגד וועלואלע זברז'ר ארנקרנץ וכנגד המחרימים את שפת האידיש. ?? לא באוצר ??"},{"i":52598,"n":"שורץ, יהודה ישעיה מבוגורייה","f":"ברוך יוסף שוורץ","k":"בעל לבוש יהודה","dt":"תרעה","b":"מובהק בהוראה,רב בבוגורייה"},{"i":52599,"n":"שורץ, יהודה מהעלישטאבא","f":"שמואל צבי","dt":"תשד - כא שבט","dp":"סערדאוהל","b":"תלמיד השב\"ס, ור יהודה אלטמן ממעזא-טשאטה. חתן ר יצחק אהרן פדרוייס מסערדאוהל ועבר לשם-תרנז. רב בהעלישטאבא, סערדאוהל. חתנו ר הלל וייס רב בסערדאוהל."},{"i":52600,"n":"שורץ, יהוסף מירושלים","f":"מנחם","k":"בעל דברי יוסף","bt":"תקסה","bp":"פלאס (בוריה)","dt":"תרכה - ט שבט","dp":"ירושלים","b":"למד בוירצבורג אצל ר נתן אדלר, ואף באוניברסיטה. בשנת תקפט הוציא לאור מפת ארץ ישראל נדפסה בוינה תקצא. בשנת תקצג עלה לירושלים ולמד ב\"בית אל\". היה חוקר ארץ ישראל וחתנו הוציא לוח זמני הזריחה והשקיעה על פי חקירתו. חיבר \"דברי יוסף\" ירושלים תרן, \"תבואות הארץ\" וקיבל על כך אות כבוד מקיסר אוסטריה, ועוד גם בגרמנית. כתב מכתבים רבים לאחיו שפורסמו בתרגום גרמני בעתונות בגרמניה. בשליחות באמריקה-תרי לטובת כולל הו\"ד ולמימון הוצאת ספריו. בספרו \"דברי יוסף\" תשובות שהשיב בניו יורק. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים תרכג.","bk":[["בשערי ירושלים",""],["דברי יוסף",""],["פרי תבואה",""],["תבואות הארץ",""]]},{"i":52601,"n":"שורץ, יום טוב מארה\"ב","f":"יעקב הלוי","k":"בעל מענה לאגרות","bp":"אושפיצין","b":"אביו בעל \"נחלת יעקב\". תלמיד יח\"ל. ניצל מהשואה, ואחריה רב בלינעברוג, רב בניו יורק. חתן ר יצחק שטיגליץ. חיבר \"מענה לאגרות\" ניו יורק תשלד (על \"אגרות משה\" לר משה פינשטיין), ועוד."},{"i":52602,"n":"שורץ, יוסף הכהן מגרוסורדין","f":"נפתלי ממאד-בית נפתלי","k":"בעל צפנת פענח-תרסט","bt":"תרלה","bp":"אויבר-וישווה","dt":"תשד - ט סיון","dp":"אושוויץ","b":"תלמיד ר אליעזר זוסמן סופר בפאקש, ור יעקב טננבוים מפוטנאק. חתן ר אליעזר דייטש מהאנשוויץ בעל \"תבואות שדה\", ועבר לשם, עבר לבניהאד עם חותנו וסייע לו בניהול הישיבה, דיין בבניהאד-תרעז על מקום חותנו, רב ומגיד בגרוסורדין-תרפד. מו\"ל ועורך כתב עת \"וילקט יוסף\"-תרנט, חיבר ספרים רבים, וחיבר ערכים רבים באנציקלופדיה \"אוצר ישראל\". חיבר גם \"פרי עץ הדר\". נחשב למומחה בספרות התורנית וביחוד השו\"ת. נספה בשואה. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"לקט ששנ\"ה\" - סטמר תרצד, \"המגיד\" - סטמר תרפח, \"הנשר\" - טירנוי תרצג-תשד, \"עמוד התורה\" - דעש תרצב, \"קובץ מפרשי התורה\" - מארגרטן תרצג.הו\"ל כתב עת \"וילקט יוסף\" - מונקטש - פאקש - באניהאד - תרנט-תרעז, בהסכמת ובהשתתפות גדולי ישראל בהונגריה, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":52603,"n":"שורץ, יוסף מקלוש","b":"תלמיד ה\"חוות דעת\" שהיה רב בקלוש, רב בקלוש על מקום רבו. עמו בבית דינו ר ישראל משולם הלוי ור מנשה בר שיסל. רב בבורשטיין. עלה לארץ."},{"i":52604,"n":"שורץ, יוסף צבי הלוי","f":"חיים יהודה מסאמוש","k":"בעל בן יוסף-תרפו","bp":"סאמוש-אויוואר","b":"תלמיד ר יצחק הכהן מסאמוש-אויוואר, ור יחזקאל בנעט בוואראהל. רב בעניעד-תרעד, לאזנדורף, ספשי-סט גיורג- תרפד על מקום הרב ד\"ר יוסף ניימן. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. נספה בשואה."},{"i":52605,"n":"שורץ, יוסף שמואל","b":"רב-שנת ת\"ר"},{"i":52606,"n":"שורץ, יעקב חיים מטעבל","b":"רב בטעבל"},{"i":52607,"n":"שורץ, יעקב יחיאל מקראלי","dt":"תשד","b":"חתן ר ברוך בנדיט ליכטנשטין מקראסנא. דיין בקרולה(=קראלי)-תרסח כ-36 שנה. חתנו - ר שמואל דוד מטלג'ש. נספה בשואה."},{"i":52608,"n":"שורץ, יעקב מזלוטושוב","b":"פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":52609,"n":"שורץ, יעקב משה מקרסני","f":"ר\"י","dt":"תרסח- יא ניסן","b":"תלמיד ר אברהם שאג-צוובנר בקוברסדורף. רב בקראסנא-תרך, רב הקהלה האורטודוכסית בקרולה(=קראלי)-תרמא שנוסדה אז. מקורב לאדמורי סיגט ודעש. בנו - ר ישעיה (עורך \"עמוד התורה\" בדעש)."},{"i":52610,"n":"שורץ, יצחק אהרן ממזלבריץ","b":"רב בהומנא, דומ\"צ במזאלבריץ-תרע\"ד"},{"i":52611,"n":"שורץ, יצחק אהרן מסיגט","dp":"ירושלים","b":"ראש השובי\"ם בסיגט. עלה לירושלים. נכדו - ר מרדכי צבי מטשיק-סערעדא."},{"i":52612,"n":"שורץ, יצחק איזיק מאונסדורף","f":"בנימין","dt":"תקצב - יא אב","b":"ראש הקהלה באונסדורף."},{"i":52613,"n":"שורץ, יצחק איזיק מטראנאוועני","f":"זאב","k":"בעל באר יצחק-תשכב","b":"גיסו של ר יחיאל יוסף קרויס אב\"ד טארנאוועני. דיין בדיצ'ו סט מארטו(=טארנאוועני) לפני השואה. ניצל מהשואה, ואחריה עלה לארץ-תשך. והתישב בבני ברק."},{"i":52614,"n":"שורץ, יצחק איצק מגומבין","f":"יקותיאל זלמן","dt":"תקצד","b":"ראב\"ד בגומבין-תקנד כ-40 שנה. בניו - ר פנחס נפתלי מחוסט בעל \"נפש טובה\", מאיר שמעון."},{"i":52615,"n":"שורץ, יצחק הכהן מסטופניץ","f":"ברוך יוסף שוורץ","b":"רב בסטופניץ"},{"i":52616,"n":"שורץ, יצחק זעקל מסאלארד","dt":"תשד","b":"חתן ר ברוך בנדיט ליכטנשטין מקראסנא. רב בסאלארד-תרפב על מקום גיסו ר צבי כהן. נספה בשואה."},{"i":52617,"n":"שורץ, יצחק מאיר הכהן מדרגמירש","f":"נפתלי-בית נפתלי","k":"בעל אמרי יצחק-תרעב","bt":"תרכו","dt":"תרצו - ז ניסן","b":"חתן הגביר ר יוסף מרדכי כהנא מדרגמירשט. רב בכפר דראגמירשט-תרסג. חיבר גם \"כבוד שבת\", ועוד. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד, \"תורה מציון\" - ירושלים תרנה-תרסה. בנו - ר אברהם ליב מאראץ."},{"i":52618,"n":"שורץ, יצחק מבריסל","b":"רב בבריסל-תרע."},{"i":52619,"n":"שורץ, יצחק מהאלאש","bt":"תריא","dt":"תשד","dp":"אושוויץ","b":"דומ\"צ בהאלאש-תרנח. נספה בשואה."},{"i":52620,"n":"שורץ, יצחק מטאליא","b":"תלמיד הכת\"ס. מחכמי טאליא. בנו ר אברהם יוסף מטאליא."},{"i":52621,"n":"שורץ, יקותיאל ממונשטיר","f":"אליהו משה","bt":"תרכא","bp":"קטשקעמעט","dt":"תרנז - יט תשרי","b":"תלמיד הכת\"ס, ור משה פולק מבאניהאד. חתן ר דוד אריה דוידודביץ ממדיאר-לאפוש ועבר לשם. רבה הראשון של מאנאשטור-ליד סטמר-תרלה, בנו ר בנימין זאב וולף על מקומו אחריו. מתורתו ב\"שערי צדק\", \"אבני צדק\"."},{"i":52622,"n":"שורץ, ישכר דב בר מבאניהאד","f":"אליהו משה","bp":"קעטשקמעט","dt":"תרעז - ל אב","dp":"באניהאד","b":"תלמיד הכת\"ס. חתן ר אהרן שמואל הלוי פולק מבאניהאד. ממיסדי הקהלה החרדית בבניהאד. רשם בכת\"י מתורת רבו."},{"i":52623,"n":"שורץ, ישכר דב הכהן מדלגוב","f":"יהודה ישעיה שוורץ","dt":"תשה","b":"רב בדאלגוב,אוסטרובצה"},{"i":52624,"n":"שורץ, ישכר דב הכהן מרוגריה","f":"חיים שלמה שוורץ","dt":"תשג","b":"רב ברוגריה-תרפ\"ד"},{"i":52625,"n":"שורץ, ישעיה מדעש","f":"יעקב משה מקראלי","b":"עורך \"עמוד התורה\" - דעש תרצב."},{"i":52626,"n":"שורץ, ישראל דב בר מקלוש","b":"רב בקלוש. עלה לארץ-תרכה. תלמיד חבר למהרש\"ק שהזכירו בספרו."},{"i":52627,"n":"שורץ, ישראל יעקב","f":"יצחק איזיק","k":"בעל קענטאקי","bt":"1885","bp":"פאטרושון-ליד קובנא","b":"בן לרבה של פאטרושון. תלמיד ישיבת קובנא, נתפס להשכלה. תרגם את שירי ביאליק. היגר לארה\"ב ופרסם ב\"יודישען קעמפפער\" שירים ותרגומים. פרש לעיירה לקסינגטון ועסק במסחר והמשיך לחבר פואימות."},{"i":52628,"n":"שורץ, ישראל מקלן","k":"בעל תקות אנוש","dt":"תרלה - שבט","b":"רב בבירוט-מדינת ביירן, קלן. חבר ב\"כי\"ח\" בפאריס. חיבר גם ספר בלשון אשכנז על פי הספר \"תבואות הארץ\" לדודו ר יהוסף שורץ."},{"i":52629,"n":"שורץ, מאיר מזוולוב","f":"אהרן","k":"בעל רמ\"ז","bt":"תריט","dt":"תשיג","b":"מקורב לאדמורים מזידיטשוב וספינקא. ו\"האמרי יוסף\" מספינקא הסמיכו בכתב לאדמור. רב ואדמור בזלוולוב, פודהייץ. עלה לארץ-תרפז והתקשר עם חסידי קרלין בירושלים. רוב חבוריו בקבלה אבדו עם נפילת הרובע היהודי-תשח. חיבר \"רמ\"ז\" ירושלים תש, ועוד."},{"i":52630,"n":"שורץ, מאיר משקלוב","dt":"תרפה - א טבת","b":"רב בשקלאב-תר\"נ"},{"i":52631,"n":"שורץ, מיכל מפודהייץ","b":"רב בפודהייץ - תשובה אליו ב\"נדרי זריזין\". נכדו ר פייביש רב בפודהייץ לפני השואה."},{"i":52632,"n":"שורץ, מנחם בן ציון מירושלים","b":"מראשי חסידי קרלין בירושלים-תשה."},{"i":52633,"n":"שורץ, מנחם הכהן","f":"יהודה ישעיה שוורץ","dt":"תשג","b":"רב בועד הרבנים בסוסנובצה"},{"i":52634,"n":"שורץ, מנחם ישעיה מקלויזנבורג","f":"נפתלי הכהן מהעדילא","bt":"תרל","dt":"תשד","b":"תלמיד השב\"ס. חתן ר חיים עזריאל גולדשמיט ממאסיף ועבר לשם-תרמט. רב באויבער ווישווא-תרנח, נאסור-תרעב, קלויזנבורג-תרעד. נספה בשואה."},{"i":52635,"n":"שורץ, מנחם מאויבר רינא","f":"יצחק אהרן מסיגט","bt":"תרלד","bp":"סיגט","dt":"תרפד - י אדר","b":"דיין בכפר אויבר-רינא-מארמרוש. (לא נספה בשואה - כפי שצוין במקום אחר)."},{"i":52636,"n":"שורץ, מנחם מגרוסורדין","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":52637,"n":"שורץ, מנחם מנדל מפמורן","b":"מחכמי פמורן - תשובה אליו ב\"מהרש\"ם\"."},{"i":52638,"n":"שורץ, מרדכי זאב מברגסז","f":"אברהם יהודה מברגסז","k":"בעל נר מרדכי","bt":"תרכד","bp":"ברגסז","b":"אביו בעל \"קול אריה\". גר בפודגורזע, עבר לוינר-באדן-ליד וינה. חסיד צאנז ושיניבה. חיבר \"נר מרדכי\" ניו יורק תשסג. פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":52639,"n":"שורץ, מרדכי ליב מארה\"ב","b":"רב בקליבלנד. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":52640,"n":"שורץ, מרדכי מבובוב","b":"מחכמי בובוב - תשובה אליו ב\"מנחת יחיאל\"."},{"i":52641,"n":"שורץ, מרדכי מסיגט","f":"יצחק אהרן מסיגט","k":"בעל לוטה בשמלה-תרעד","dt":"תרעט - יט אד\"א","b":"חתן ר אברהם אריה ביינהורן ממונקטש. ראש השוחטים במונקטש ומלמד לשוחטי הונגריה וטרנסילבניה ונתן \"קבלה\" למתמחים אצלו. חיבר פירוש \"לוטה בשמלה\" לספר \"שמלה חדשה\" מר אלכסנדר שור - סיגט תרעד. ?? לא באוצר ??"},{"i":52642,"n":"שורץ, מרדכי משימלויא","bt":"תקע","dt":"תרנח","b":"תלמיד החת\"ס. רב בשימלויא(=שאמלוי)."},{"i":52643,"n":"שורץ, מרדכי צבי מטשיק-סערעדא","f":"רפאל בן יצחק אהרן","k":"בעל דורש טוב לעמו","r":"מתרצ\"ב רב בקליבלנד","bt":"תרמג","bp":"סיגט","dt":"תשכב - יא אלל","b":"תלמיד השב\"ס, ר יהודה גרינוולד בסטמר, ור חנניה יו\"ט ליפא טיטלבוים מסיגט, ודודו ר אליעזר שוורץ משאראש-פוטוק. חתן ר זאב וולף ציטרון מהאידו-דאראד. רבה הראשון של טשיק-סערעדא-תרסט, היגר לאנגליה-תרעד וכיהן כרב בלונדון, אב\"ד הול. עבר לאמריקה וכיהן כרב ביאנגסטון (אוהיו), קליוולנד-תרצח. בניו - ר שמואל רב בהיוסטון (טקסס), ור משה רב בגרינבורג-פא', ור יצחק אהרן מקליבלנד. חיבר גם \"להבדיל בין הטמא\" כנגד \"טהרת הקדש\" לר ישראל חיים דיכעס מלידס. חיבר גם \"דרושי חכמה ודעת\" סט לואיס תש, \"מעשי למלך\", ועוד. גם באנגלית.","bk":[["דורש טוב לעמו - דרושים",""],["דרושי חכמה ודעת - לבאר דברי תורה על פי מדע",""],["להבדיל בין הטמא ובין הטהור - נגד קונטרס טהרת הקודש לרי\"ח דייכעס",""],["מעשי למלך - שירה",""],["עבודת תמיד - שירי קודש תפילות והודאות",""]]},{"i":52644,"n":"שורץ, משה אהרן מפאצ'א","b":"רב הקהילה הניאולוגית בפאצ'א-1857. פרסם מאמרים ב\"ניא צייט\" בוינה, ובכתב העת \"בן חנניה\"."},{"i":52645,"n":"שורץ, משה יוסף מגאלגוץ","dt":"תשג","b":"רב בגאלגוץ"},{"i":52646,"n":"שורץ, משה יוסף מפרישטט","f":"יצחק אהרן מהומנא","bt":"תרמח","bp":"הומנא","dt":"תש..","b":"רב בפרישטאט-תרפב."},{"i":52647,"n":"שורץ, משה ישעיה","dt":"תרנט - ט אד\"ב"},{"i":52648,"n":"שורץ, משה מבודפשט","dt":"תשד","b":"רב בבודפשט"},{"i":52649,"n":"שורץ, משה מהאלאש","b":"חתניו - ר שמואל קורלק מפיסקע ור אברהם גרינבגר מצעלדאמעלק."},{"i":52650,"n":"שורץ, משה מלונדון וארה\"ב","f":"עזריאל מסטמר","k":"בעל זוודין לאורחא","bt":"תרנז","bp":"סטמר","b":"תלמיד \"ערוגת הבשם\" בחוסט, ר יהודה גרינוולד בסטמר, ור עקיבא סופר בפרשבורג. חתן ר אליהו גליק מטעטש. היגר לאנגליה - לאחר מלחמת העולם ה-I וכיהן כשוחט בפורטסמות. היגר לאנידיאנפוליס-תשה, סן פרנציסקו, לוס אנג'לס. עלה לירושלים-תשלד."},{"i":52651,"n":"שורץ, נפתלי הכהן מהעדילא-מאדע","f":"אברהם יהודה-קול אריה","k":"בעל בית נפתלי","bt":"תרא-ו","bp":"מאדע","dt":"תרנז - יב כסלו","b":"חתן ר יעקב וייס מקאנטוריאנושי, בזיוו\"ש חתן הגביר ר יהודה אריה פרוכטר מאויבר-וישיווה, ועבר לשם. עבר לברגסאס ועסק במסחר ספרים, רב במאד(=העדילא-מאדע)-תרמד על מקום אביו, ראש ישיבה באויבר-וישעווא. חברו של ר נפתלי הירצקא מראצפרט. חיבר גם \"אמרי יצחק\". מקורב לאדמורי בלז ושינאווא. חיבר גם \"נפתלי שבע רצון\", ועוד. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"הנשר\" - טירנוי תרצג-תשד. הגהות על המשנה ממנו ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":52652,"n":"שורץ, נפתלי מסטמר","b":"פרסם מאמרים ב\"כתר תורה\" - גרבה תרצח."},{"i":52653,"n":"שורץ, סלומון משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":52654,"n":"שורץ, עזריאל","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":52655,"n":"שורץ, פיבל מפודהייץ","b":"רב בפודהייץ. תשובה אליו בנדרי זריזין."},{"i":52656,"n":"שורץ, פנחס זליג הכהן","f":"יצחק מאיר מדרגמירשט","k":"בעל זכרון צדיקים-תרפ","b":"חתן ר ישראל פולק מבורשה, בזיוו\"ש חתן ר אברהם יהודה הלוי. שו\"ב ורב בכפר אפאהידא-ליד קלויזנבורג. נספה בשואה."},{"i":52657,"n":"שורץ, פנחס זליג הכהן ממאדע","b":"רב במאדע-תק\"צ"},{"i":52658,"n":"שורץ, פנחס זליג הכהן מקלינורדי","f":"נפתלי ממאד - בית נפת","k":"בעל שם הגדולים מארץ","dt":"תשד","b":"מחכמי קלינורדין. חיבר \"שם הגדולים מארץ הגר\", \"גבעת פנחס\", ועוד. הו\"ל כתב עת \"אור תורה\" קלינורדין תרצב, פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"הנשר\" - טירנוי תרצג-תשד."},{"i":52659,"n":"שורץ, פנחס נפתלי ירושלמי מחוסט","f":"יצחק איצק מגאמבין","k":"בעל נפש טובה","dt":"תרמה - יט אד\"ב","b":"תלמיד ר מאיר א\"ש באונגוואר. סופר ודיין בחוסט-תרל אצל מהר\"ם שי\"ק. העתיק את שו\"ת רבו - אמרי א\"ש והכינו לדפוס."},{"i":52660,"n":"שורץ, צבי הירש הכהן מבייטש","f":"יהודה ישעיה שוורץ","dt":"תשג","b":"רב בבייטשן"},{"i":52661,"n":"שורץ, צבי הירש הכהן מסוסנוביץ","dt":"תשג","b":"רב בסוסנובצה"},{"i":52662,"n":"שורץ, צבי הירש מזלוטניק","f":"פנחס הכהן","b":"תלמיד ר דוד מנחם באבד בעל ה\"חבצלת\" שהזכירו בספרו. חתן ר אפרים חמיידס מבקשביץ. רב בזלוטניק, אזיפולי, בקשביץ על מקום חותנו."},{"i":52663,"n":"שורץ, צבי הירש מירמוט","b":"מג\"מ ביארמוט(=ירמוט)-תרמז. חתנו - ר מנחם צבי רוזנברג (13611) (ולפי מכתב נכדו ר אשר אנשל שורץ המובא אצל ברוין היה חתנו של ר מנחם צבי רוזנברג ולא חותנו), לאחר שנפטר נשאה אלמנתו לר אשר אנשל וייס (3555)."},{"i":52664,"n":"שורץ, רפאל מסיגט","f":"יצחק אהרן מסיגט","b":"אביו של ר מרדכי צבי מטשיק-סערעדא."},{"i":52665,"n":"שורץ, שאול הכהן מסטופניץ","f":"יצחק שוורץ","b":"רב בסטופניץ"},{"i":52666,"n":"שורץ, שלמה יהודה משטינמאנגר","f":"מאיר אשר מבודפשט","k":"בעל אבני שיש","bt":"תרסט","bp":"בודפשט","dt":"תש..","b":"תלמיד הדעת סופר, ור ישראל ולץ מבודפשט. חתן ר דניאל בוכינגר משטינמאנגר, ועבר לשם ולימד תורה לתשב\"ר. נספה בשואה."},{"i":52667,"n":"שורץ, שלמה מבאגריי","dt":"תשא","b":"רב בבאגריי"},{"i":52668,"n":"שורץ, שמואל הכהן מסטמר","f":"נפתלי-בית נפתלי","k":"בעל תולדות גאוני הגר","dt":"תשד","b":"תלמיד ר שלמה זלמן ארנרייך בשאמלוי, ר מרדכי ליב וינקלר במאד, ור אליעזר דייטש בבניהאד. חתן ר חיים יהושע זייף מלאפוש. מחכמי מאד, מגיד בסטמר לפני השואה. הו\"ל כתב עת \"לקט ששנה\"-תרצד. חיבר תולדות גאוני הגר הטמונים בבית החיים במאד - טולצבא תרעא. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. עורך \"לקט ששנ\"ה\" - סטמר תרצד. ?? לא באוצר ??"},{"i":52669,"n":"שורץ, שמואל מקאשוי","dt":"תשד","b":"מרביץ תורה בקאשוי"},{"i":52670,"n":"שורצר, דב בריש מנרול","f":"שלום מנרול","bt":"תרסה","dt":"תשן","b":"גבאי א\"י בנרול. חתן ר דב בריש שנבלום מרישא. עלה לארץ-תרצה. בנו ר שלום - ר\"מ בישיבת \"בית התלמוד\" בירושלים."},{"i":52671,"n":"שורצר, שלום מנרול","f":"ישראל צבי","dt":"תרצח","b":"רב בנרול, ליפסק."},{"i":52672,"n":"שורקין, יעקב משה מניו יורק","b":"חתן ר יעקב קנטרוביץ מארה\"ב. ר\"מ בישיבת רבי חיים ברלין בניו יורק."},{"i":52673,"n":"שורשטין, אלכסנדר סנדר","f":"יוסף סגל מנמירוב","b":"תלמיד ר יצחק שמלקיס שהזכירו בספרו \"בית יצחק\"-תרלח."},{"i":52674,"n":"שורשטין, יוסף סגל מנמירוב","b":"מחכמי נמירוב, למברג."},{"i":52675,"n":"שושי, אליהו ממצרים","b":"מחכמי אל-מנצורה-מצרים-שנות ה-ת'."},{"i":52676,"n":"שושן הכהן מג'רבה","f":"כלפון משה-שואל ונשאל","k":"בעל פרח שושן","dt":"תשלו","b":"מחכמי ג'רבא, דאג למנות את ר אלטר מאזוז לשו\"ב בג'רבא, וסמך רק על שחיטתו. עסק במסחר ספרים וצרכי דת, כיהן כדיין עם ר רחמים חיותה חי הכהן, ור שלמה מאזוז. הו\"ל את ספרי אביו, עלה לישראל-תשטז וכיהן כרב במושב איתן. חיבר גם \"ממלכת כהנים\", ו\"מעשה שושן\"."},{"i":52677,"n":"שושן הכהן מג'רבה","b":"הו\"ל \"אוצר התורה\" - ג'רבא תרץ."},{"i":52678,"n":"שושן, אברהם מאמשטרדם","dt":"תרכב - יז חשון","b":"תלמיד ר יוסף אשר למל מהאג, ר אליהו כתריאל מרוטרדם. דיין ור\"מ באמשטרדם, אב\"ד בהאג. הניח פירוש למשנה והלכות שחיטה. מתלמידיו: ר יוסף הירש מאמשטרדם, ר יהודה ליב משעפס ואמירספאט, ר ירמיה דילעסוס ממעפעל, ר נחמן נתן קורונל מאמשטרדם בעל \"בית נתן\"."},{"i":52679,"n":"שושן, אברהם מטולידו","f":"דוד","k":"בעל עליות על השס","dt":"צט - כד אלול","b":"דיין מחכמי ספרד בטוליטולא, תלמיד הרא\"ש, חיבר חידושים לש\"ס \"עליות\""},{"i":52680,"n":"שושן, אברהם מטולידו - א","b":"רב בטולידו-ד'תתקן. נזכר ב\"תחכמוני\"."},{"i":52681,"n":"שושן, אברהם מירושלים","b":"מחכמי ישיבת נוה שלום בירושלים-תקיח."},{"i":52682,"n":"שושן, אברהם ממצרים וכיאו","bp":"מצרים","b":"חתן ר חיים אלפואל מרודוס. רב בכיאו."},{"i":52683,"n":"שושן, אברהם ממרוקו","f":"שלמה","bt":"תרה","bp":"דבדו","dt":"תשא","dp":"מוגאדור","b":"דיין, ראש ישיבה, עבר לתאזה, הקים ישיבה במאראכיש, ספרא דדיינא בפאס, אב\"ד במוגאדור"},{"i":52684,"n":"שושן, אברהם מספרד","f":"יצחק","k":"אבן אסחאק","b":"מיושבי טולידו. חתן השר אלמשדוף ר מאיר ן שושן-אבי השרים דון יצחק ודון יוסף. גזבר המסים למלכות ספרד. נזכר בספר \"גן המשלים\" לר טודרוס ושם שיר לכבוד המשפחה - אולם גם שיר כנגדם. הרמ\"ה חיבר שיר לכבודו, וכן ר אברהם הירחי- בעל המנהיג והקדיש להם שנים מספריו - כהוקרה על שתמכו בו."},{"i":52685,"n":"שושן, אברהם מספרד ומצרים","b":"מגולי ספרד,מגדולי רבני מצרים-ר\"צ"},{"i":52686,"n":"שושן, אהרן מאזמיר","dt":"תל - ז חשון","b":"רב באזמיר"},{"i":52687,"n":"שושן, אהרן מצפת","f":"יהודה","b":"מחכמי צפת בשנת תמח, בשנת תעג חתם על אגרת שליחות של ר שמואל בן עובדיה הלוי."},{"i":52688,"n":"שושן, אליהו הלוי מסאלי","b":"מחכמי סאלי-שנות ה-ת'. חתנו - ר אליעזר דאבילה."},{"i":52689,"n":"שושן, אליעזר מקושטא","b":"רב בקושטא-שנות ה-ש'."},{"i":52690,"n":"שושן, אליעזר משלוניקי","b":"מחכמי שלוניקי-שנה. נתמנה ע\"י ר תם ן יחיא להדפיס את ספרו יחד עם ר מאיר יצחקי."},{"i":52691,"n":"שושן, אשר מקוסובה וזעטיל","f":"יוסף מנחם","k":"בעל מעשה שושן","bt":"תקצד","bp":"קוסובה","b":"למד בילדותו עם ר בנימין זקהיים מיקטריניסלב. עבר לזעטל-תרכה והתפרנס ממסחר."},{"i":52692,"n":"שושן, דוד מספרד","f":"יעקב","b":"רב בטוליטולא, מדקדק-שנת נ'"},{"i":52693,"n":"שושן, דוד מקומורג'ינה","b":"רב בקומורג'ינה-שנות ה-ש'."},{"i":52694,"n":"שושן, דוד משלוניקי וירושלים","k":"בעל דבש וחלב","dt":"רצג-ו","dp":"ירושלים","b":"מחכמי ספרד, רב כולל, רופא, איש מדע, אחרי הגירוש עבר לשלוניקי-רנב, עלה לירושלים. שלח מליצה לדון יהודה בנבנשתי, בשנת רסט חתם על התקנה לשחרר תלמידי חכמים ממס. דיין בבית דינו של ר יצחק שולל עד שנת רץ. בשנת רפה מינהו הנגיד כאפוטרופוס על בנו אברהם. דיין, ראש ישיבה, רב ראשי בירושלים על מקום ר עובדיה מברטנורא, חיבר \"דבש וחלב\". בספריה הלאומית קולופון ובו \"קניתיו מיד החכם דוד שושן וכו' אני דוד ן זמרא. מוזכר בספרי חכמי דורו. סגי נהור."},{"i":52695,"n":"שושן, דוד משלוניקי וקושטא","dt":"שסא - אחרי","dp":"קושטא","b":"סגי נהור. רב ור\"מ בק\"ק שלום בשלוניקי-שמד על מקום ר יצחק אדרבי, עבר לקושטא-שסא, והשביע את אנשי הקהלה שלא למנות רב במשך עשר שנים, ולאחר פטירתו קיבלו היתר מר אהרן ן חסון לקחת את ר שמואל פלונרטין לרב. הסכים על \"יפה תואר\"."},{"i":52696,"n":"שושן, חיים דוד","f":"אברהם","bt":"תרמה","dt":"תשך","dp":"קאזאבלנקה","b":"למד ולימד בישיבת אביו עשרים שנה, דיין בדבדו-תרסה, רב בתאורירת-תרפד, ספרא דדיינא במוגאדור-תרפט, דיין במוגאדור-תרצז, דיין בקזבלנקה(=דאר-לבידא)-תשב, אב\"ד תשט."},{"i":52697,"n":"שושן, חיים מפאס","b":"מחכמי פאס-שנות ה-ש'."},{"i":52698,"n":"שושן, יהודה מספרד","f":"דוד או יצחק","k":"בעל פירוש שיר השירים","b":"מחכמי ספרד, בגירוש עבר לטורקיה-רנב, רב בשלוניקי, חיבר פירושים לחמש מגילות ומסכת אבות (נקראים \"פירושי החסיד\" מובא בפירושי הרב יוסף יעבץ). מוזכר ב\"ראשית חכמה\", \"מנות הלוי\" . חיבר פירוש לאבות - הוזכר ב\"מדרש שמואל\", ופירוש לאסתר ורות - הוזכר ב\"מנות הלוי."},{"i":52699,"n":"שושן, יהודה מספרד ומגניסיאה","b":"מחכמי ספרד, רב במגניסיאה-תורכיה."},{"i":52700,"n":"שושן, יהודה מצפת","b":"איש מופת בצפת-ש\"ל"},{"i":52701,"n":"שושן, יהודה משלוניקי","b":"רב בשלוניקי-שנות ה-ש'."},{"i":52702,"n":"שושן, יהושע מירושלים","b":"מרבני ירושלים-תר\"ס"},{"i":52703,"n":"שושן, יהושע משלוניקי","dt":"תעח","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":52704,"n":"שושן, יהושע משלוניקי","dt":"תקכח","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":52705,"n":"שושן, יוסף הנשיא מטולדו","f":"שלמה","dt":"ד'תתקסה","b":"שר מחכמי טוליטולה. נזכר אצל אלחריזי."},{"i":52706,"n":"שושן, יוסף מספרד","k":"בעל פירוש על אבות","b":"מקובל, רב בסראגוסה-קפ, חברו של הריב\"ש. חיבר פירוש למסכת אבות ונזכר ב\"מדרש שמואל\"."},{"i":52707,"n":"שושן, יוסף משלוניקי","f":"יהושע משלוניקי","dt":"תקלא","dp":"שלוניקי","b":"גביר בשלוניקי-תע כאביו לפניו."},{"i":52708,"n":"שושן, יוסף משלוניקי","b":"גביר בשלוניקי. תרם מגרש להקמת בימ\"ד לרבנים - נוסד בתרנז."},{"i":52709,"n":"שושן, יצחק מפאס","f":"משה","b":"מחכמי פאס, העתיק בכתב ידו תפלות מכל השנה עם פירוש ממנו לאזהרות לר שלמה ן גבירול."},{"i":52710,"n":"שושן, ישראל מאנגורה","dt":"שנט","b":"גביר באנגורה. הניח בצוואתו סכום גדול לת\"ת בשלוניקי-שנט."},{"i":52711,"n":"שושן, משה מאזמיר","dt":"תלח - יז תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":52712,"n":"שושן, משה מאלכסנדריה","b":"רב באלכסנדריה-שנות ה-ר'."},{"i":52713,"n":"שושן, משה מירושלים","dt":"שפג - אחרי","b":"מחכמי ירושלים, הגיע לצפת לייצג את אמו בדין לפני ר שלמה סיריליאו כנראה לפני שנת שך ונזכר בשו\"ת המבי\"ט. מופיע גם ב\"אבקת רוכל\", בשליחות ר יוסף קארו באיטליה-שי להדפיס את ספרו \"בית יוסף\". בשליחות באיטליה עוד כמה פעמים עד שנת שכג. היה במחלוקת עם ר משה רוזא ותמכו בו חכמי ארץ ישראל. חתם על תקנות שונות בשנים שמז-שפג, וביניהם על התקנה נגד הפירוד-שפג."},{"i":52714,"n":"שושן, שלמה משלוניקי","f":"שמואל","b":"תלמיד ר יצחק אדרבי. מחכמי שלוניקי. כתב את תולדות רבו ועל קורות יהודי שלוניקי בזמנו ונדפס בסוף \"דברי שלום\" לר יצחק אדרבי - שמה."},{"i":52715,"n":"שושן, שמואל מאזמיר","dt":"תקיח - כו ניסן","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'."},{"i":52716,"n":"שושן, שמואל מספרד","f":"ששון ן, שמואל","b":"ואולי להיפך?"},{"i":52717,"n":"שושן, שמואל משלוניקי","b":"מחכמי שלוניקי - שנות הר'."},{"i":52718,"n":"שושנה, אברהם מאלגיר וצפת","bt":"תקמד","bp":"אלגיר","dt":"תרך - בערך","b":"מחכמי אלגיר, עלה לארץ-אחרי תקץ, מחכמי צפת, חתם בשנת תקצט ותריג על מכתבי ראשי העדה בצפת."},{"i":52719,"n":"שושנה, אהרן","dt":"תרצא - ו אייר","b":"מרבני מראקש"},{"i":52720,"n":"שושנה, דוד","b":"מקובל"},{"i":52721,"n":"שושנה, דוד ממראקש","k":"בעל שמן זית זך","dt":"תרנח - כב שבט","b":"מקובל, מחכמי מראקש, חיבר \"שמן זית זך\". בנו - ר יוסף. (בארזי הלבנון שנת פטירתו - תש)."},{"i":52722,"n":"שושנה, זבולון ממרוקו","k":"בעל שפתי שושנה","b":"מרבני מרוקו, חיבר \"שפתי שושנה\" על התורה"},{"i":52723,"n":"שושנה, יוסף מאלגיר","bt":"תן","dt":"תקך - בערך","b":"רב בווהראן, תשובה אליו מר רי\"ש צרור ב\"פרי צדיק\"."},{"i":52724,"n":"שושנה, יוסף מצפת","f":"שלמה","b":"מחכמי צפת, בשנת תקפא חתם עם גדולי צפת על פסק דין."},{"i":52725,"n":"שושנה, יעקב מאלגיר","bt":"תרס","dt":"תרצח","b":"רב בתביסא-אלגיר, ענאבא(=בון). התכתב עם ר יוסף משאש, ועוד. פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":52726,"n":"שושנה, ישועה ממראקש","b":"רב במראקש-שנות ה-ת'. אחד מהאסורים שנאסרו עם ר אברהם אזולאי במראקש."},{"i":52727,"n":"שושנה, רפאל חיים ממראקש","k":"בעל רחש לבי דבר טוב","bt":"תרעב","bp":"מראקש","dt":"תשמז - ב תשרי","dp":"באר שבע","b":"מלמד במראקש. חיבר חיבור על סוליכה הצדיקה. רב בדמנאת, דיין בקזבלנקה אצל ר שלום משאש. עלה לארץ-תשכו והתישב בבאר שבע וכיהן כרב שכונה. העתיק ספר \"שיר ידידות\" עם הערות וביאורים."},{"i":52728,"n":"שושנה, רפאל מצפת","f":"אברהם","b":"חתם עם רבני צפת על כתב שליחות ר חיים נחום מזרחי - צפת תרה."},{"i":52729,"n":"שושנה, שלמה מאלגיר וירושלים","bt":"תקנט","bp":"אלגיר","b":"מחכמי אלגיר, עלה לירושלים-תקצט, ויצא מיד בשליחות לאמשטרדם."},{"i":52730,"n":"שושנה, שלמה ממראקש - א","f":"שלם","b":"מחכמי מראקש, חתם-תצד עם ר אברהם עמאר, ור שלמה בנבנישתי."},{"i":52731,"n":"שושנה, שלמה ממראקש - ב","b":"רב במראקש-תקעט, חתם-תקף אז עם חברו ר אהרן הלוי, ור דוד חזן."},{"i":52732,"n":"שושנה, שמואל מאזמיר וטבריה","dt":"תקפג - ח תמוז","b":"רב באזמיר, עלה לטבריה, התגורר גם בפקיעין. בשליחות בטריפולי-תקן, והסכים שם על \"חיי אברהם\" לר אברהם כלפון.נספד ב\"תהלה לדוד\" לר דוד אמאדו. חיבר ספר שות ודרושים בכת\"י."},{"i":52733,"n":"שושנה, שמואל מטבריה","bp":"אזמיר","dt":"תקפג","dp":"טבריה","b":"עלה לטבריה והיה מחכמיה, בשנת תקן בשליחות באפריקה, במהלכה הסכים על ספר \"חיי אברהם\" לר אברהם כלפון. בשנת תקסו חתם על כתב שליחות ר שם טוב קלדרון."},{"i":52734,"n":"שושני, עזרא מפרס","f":"רחמים","bt":"תרמו","bp":"חמדאן(=שושן)-פרס","b":"עלה לארץ-תרסב, חזר לפרס והיה ממיסדי התנועה הציונית שם, חזר לירושלים-תרעט. פעיל צבור."},{"i":52735,"n":"שושני, רחמים מפרס","f":"שמואל - רב בהמדאן","bt":"תריד","bp":"המדאן-פרס","dt":"תרפז - י אלול","dp":"ירושלים","b":"דור שביעי לרבנים בפרס. רבה של חמדן ובורג'ירד, עלה לארץ בשנת תריד. דור שביעי לרבנות בפרס. חיבר ספרים בקבלה בכתב יד."},{"i":52736,"n":"שושקס, יוסף מוילנא","b":"מו\"צ בוילנא, ר בצלאל הכהן בן ישראל משה בעל \"ראשית בכורים\" על מקומו אחריו-אחרי תר."},{"i":52737,"n":"שזורי, שמואל אהרן מירושלים","b":"פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ-תשז."},{"i":52738,"n":"שזכוויצר, ישעיה","b":"איש מופת,רב בשזכוביצה"},{"i":52739,"n":"שחאתה, שלמה ממצרים","b":"מדפיס במצרים-תק אצל אברהם יתום."},{"i":52740,"n":"שחב, אברהם","f":"יוסף","bt":"תרלג","bp":"תנעם(תימן)","b":"רב בתנעם-תרע\"ט, עלה לא\"י-תרפ\"ד"},{"i":52741,"n":"שחב, שלום מתימן","b":"מחכמי צנעא - בסוף המאה ה-19."},{"i":52742,"n":"שחור, אליהו","b":"רב בפאהוסט,עלה לירושלים-תרצ\"ד"},{"i":52743,"n":"שחור, אליעזר מניו יורק","f":"בנימין","bp":"שוערזנא-פלך מינסק","b":"נסמך מאת: ר יצחק אלחנן מקובנא. רב בניו יורק-תרע."},{"i":52744,"n":"שחור, חיים ליב ממיר","f":"משה ממיר","dt":"תרלב - ז טבת","b":"חתן ר יעקב ברלין וגיסו של הנצי\"ב. לתולדותיו - המגיד שנה טז."},{"i":52745,"n":"שחור, יוסף דוד מסמיאטיץ","f":"זיסקינד","dt":"תרסו - ח אלול","b":"רב באנטיפטליע, סמיאטיץ. גיסו ובן דודו של ר שאול קוסובסקי."},{"i":52746,"n":"שחור, ישראל איסר מוילנא","f":"יצחק איזיק","dt":"תקסג - כט שבט","dp":"וילנא","b":"גביר מחכמי וילנא."},{"i":52747,"n":"שחור, משה ממיר","f":"מאיר בן צבי הירש","b":"חתן ר יוסף דוד ממיר-בן ר מאיר שחור. אביו של ר משה שחור ממיר."},{"i":52748,"n":"שחור, נח מביאלא","dt":"תרע","b":"תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ועוד. רב בביאלא-תרמה וראש ישיבה. חתנו - ר אברהם מרדכי האדמור מגור."},{"i":52749,"n":"שחור, צבי הירש","f":"אלכסנדר סנדר מדומברו","b":"חתן ר השל סירקין משקלוב בן ר נחמן מבריסק."},{"i":52750,"n":"שחור, שלום יונה מוילנא","f":"משה ממיר","dt":"תרלו - כ אדר","dp":"וילנא","b":"בזיוו\"ש חתן ר זלמן'ס ר אורי'ס. גביר מחכמי וילנא. שליש כספי ציבור בוילנא על מקום חותנו. גבאי בחברת גמ\"ח הגדול, וגבאי עניי ירושלים."},{"i":52751,"n":"שחט, חיים נתן מפורטלנד","bt":"תריא","dt":"תרפא - ו סיון","b":"רב בפורטלנד"},{"i":52752,"n":"שחט, ידידיה","bt":"תרכב","dt":"תרפו - ט טבת","b":"רב בשיקאגו"},{"i":52753,"n":"שחיבר, יצחק משה מאר\"ץ","k":"בעל יצחק ירנן","bt":"1912","bp":"אר\"ץ","dt":"תשן","b":"תלמיד ר משה טוויל. מנהל הת\"ת בחלב, ביירות, רב בבואנוס איירס. תשובה ממנו בענין העברת ספרי התורה מצידון לברזיל לשם עברו יהודיה.","bk":[["קיצור הלכות לחגים",""]]},{"i":52754,"n":"שחר, אריה ליב","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":52755,"n":"שחר, יהודה ליב","dt":"תשיג","b":"חתן ר ירוחם לינר. רב בברוקלין-תש\"ז"},{"i":52756,"n":"שחר-פרד\"ס, יצחק מפוזנא","b":"מקובל בפוזנא-ש\"צ. בנו - ר יעקב."},{"i":52757,"n":"שטאבה, אוגוסט מממל","b":"מדפיס בממל. הדפיס \"תבונה\" - תרכא."},{"i":52758,"n":"שטאהלר, הינריך מפרשבורג","b":"מראשי הקהלה החרדית בפרשבורג-תרצא. עסק יחד עם אחיו איזי בפעולות הצלה בתחילת השואה - תרצח."},{"i":52759,"n":"שטאל, אהרן יהודה מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":52760,"n":"שטאל, משה הלוי מטריאנוב","b":"נכד ר ליבר הגדול מברדיטשוב. חתן ר ישראל בנו של ר לוי יצחק מברדיטשוב. בנו ר ישראל מקונסטנטין ישן. חתן ר ישראל מטשען (זלוטשוב)."},{"i":52761,"n":"שטאם, שלום אריה","f":"זוסמן","bp":"שיווינישוק-פלך קובנא","b":"נכד ר ליב מפאסוול. רב בטראשקין-פלך קובנא (בגיל 22), קבילניק-פלך וילנא, דונייביץ(=דונייעוויץ)-פלך וילנא, סמאליין-פלך מוהילוב, הורודוק-פלך ויטבסק-תרנח."},{"i":52762,"n":"שטאמפא, אריה ליב משטמפן","f":"ר\"ל","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן."},{"i":52763,"n":"שטאמפי, שלמה מפרשבורג","b":"מחכמי פרשבורג, חתם-תקכח על תקנות החברא קדישא."},{"i":52764,"n":"שטבון, יהודה מירושלים","dt":"תקס - ה אדר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":52765,"n":"שטג, יהודה צבי מסקוליע","f":"יוסף הלוי מזורובנא","bt":"תקס","dt":"תרמז","b":"תלמיד ר צבי איכנשטין בעל \"עטרת צבי\" מזידיטשוב. חתן ר ראובן אליקים גצל מדולינא. רב בסקוליע (40 שנה)."},{"i":52766,"n":"שטג, יוסף מזורובנא","f":"ירוחם פישל מדולינא","dt":"תריג","b":"חתן דודו ר ירוחם חיים מדולינא. רב בזורובנא (40 שנה)."},{"i":52767,"n":"שטג, יצחק מדולינא","f":"ירוחם פישל מדולינא","dt":"תקצא - יא תמוז","b":"נכד ר יוסף הלוי מדולינא. רב בדולינא על מקום אביו. אחיו ר שמואל מנהיג החסידים בדולינא."},{"i":52768,"n":"שטג, ירוחם פישל מדולינא","b":"חתן ר יוסף הלוי מדולינא נכד הט\"ז. רב בדולינא על מקום חותנו, בנו ר יצחק על מקומו אחריו."},{"i":52769,"n":"שטג, שמואל","f":"[יוסף מזורובנא]","bt":"תקעט","dt":"תרמג","b":"רב בזורובנא על מקום אביו."},{"i":52770,"n":"שטג, שמואל מדולינא","f":"ירוחם פישל מדולינא","b":"נכד ר יוסף הלוי מדולינא. מנהיג חסידי לובלין בדולינא (והיה מחלוקת עם האב\"ד ר משה שוהם). אחיו ר יצחק רב בדולינא."},{"i":52771,"n":"שטוב, חיים","f":"יוסף אשר מפודגורזע","bt":"תרעה","dt":"תשב","b":"תלמיד ישיבת בובוב בפודגורזע. חתן ר נפתלי פרנקל מצאנז. נספה בשואה. מתורתו ב-כר\"ש - תשלט."},{"i":52772,"n":"שטוב, יוסף אשר מפודגורזע","b":"חסיד מחכמי פודגורזע. חתן נכדת ר חיים גולד מקראקא."},{"i":52773,"n":"שטוב, שמואל","f":"יוסף אשר מפודגורזע","bt":"תרסז","dt":"תש..","b":"תלמיד ישיבת בובוב. חתן ר חיים גלאס מקשאנוב. מתורתו ותולדותיו - כר\"ש-תשמב. נספה בשואה."},{"i":52774,"n":"שטובנהויז, יצחק מפרמישלא","b":"מחכמי פרמישלא. תשובה אליו ב\"בית יצחק\"."},{"i":52775,"n":"שטויבר, גרשון מבורשה","b":"דיין בבורשה וראש ישיבה קטנה שם. נספה בשואה. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישובה תרפח, נזכר ב\"קרן לדוד\", ועוד."},{"i":52776,"n":"שטולמן, דוד מקלעצק","b":"פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":52777,"n":"שטולמן, צבי הכהן","b":"רב בבאביאק-תר\"ס"},{"i":52778,"n":"שטון הלוי","f":"שאול בר שמן","b":"מחכמי פאס, חתם-רפו במחלוקת הנפיחה."},{"i":52779,"n":"שטופא, דוד מפרוסטיץ","b":"רב בפרוסטיץ. חתנו - ר מיכאל ורדניק, ובזיוו\"ש ר שלום אולמן משטמפן ולקנבך."},{"i":52780,"n":"שטופאבע, יוסף","dt":"תקע - כח טבת","b":"רב בסעניץ"},{"i":52781,"n":"שטופל","k":"ראה: שטיפל","dt":"תרפט","b":"רב במיסטקובקה"},{"i":52782,"n":"שטוקהמר, אברהם מטלומטש","bp":"ברדיטשוב","dt":"תש..","b":"חזן בטלומטש. תלמיד החזן נסים בעלזר מרוסיה. ידישם של סירוטה וקוסוביצקי. נספה בשואה."},{"i":52783,"n":"שטוקהמר, יהושע משה","f":"ישכר מלרדינה","b":"מיסד ישיבת \"שבט ישכר\" בבני ברק-תשיד. בנו - הסופר החסידי ר אבישי."},{"i":52784,"n":"שטוקהמר, ישכר דב מלרדינה","f":"משה מסקול","dt":"תשד","b":"תלמיד בעל \"קדושת יו\"ט\" מסיגט, וממקורבי האדמור בעל \"עצי חיים\". חתן ר אברהם קליין מלרדינה (ליד סיגט) ועבר לשם. שו\"ב קרוב ל-50 שנה ושימש כרב בלרדינה-תרפט על מקום ר חיים אריה לרנר שעבר לניו יורק. נספה בשואה. (נכדו הסופר ר שמואל שטוקהמר פרסם פואימה לזכרו - \"בית יעקב\" תשכה)."},{"i":52785,"n":"שטוקהמר, משה מסקאהל","dt":"תרע","b":"גביר בסקול. בנו ר ישכר דב נשא דברים ביום השנה לפטירתו - מחז\"ה תרעב."},{"i":52786,"n":"שטוקהמר, נתן נטע מאזיפולי","f":"אליעזר מאזיפולי","k":"בעל חזון ימים","bt":"תרנה","dt":"תש..","b":"נשבה במלחמת העולם ה-I על ידי הרוסים ונשלח לעבוד בספריה המזרחנית בפטרוגרד. התישב בסטניסלב - ניהל ספריה כתב שירים וערך כתב עת. חיבר \"חזון ימים\" בילגורי תרצג. נספה בשואה."},{"i":52787,"n":"שטוקהמר, שמשון מוארשא","bt":"תרנט","bp":"סקול","dt":"תשה - יג אייר","b":"חסיד בלז. חתן ר יצחק וילציק מוייסל (וארשא). חברו של ר\"מ זמבה. פרסם בעתוני אגו\"י. מראשי אגו\"י. חבר בועד הרבנים בוארשא-תרצד. נספה בשואה. פרסם מאמרים ב\"הלפיד\" - וארשא תרצז, \"תלפיות\" - טרנוב תרצח."},{"i":52788,"n":"שטוקלישקווער, גבריאל מירושלים","f":"דן משקלוב","dt":"תריג - כב טבת","dp":"ירושלים","b":"מחכמי ירושלים. ראש משפחת רלב\"ג בירושלים. בנו - ר אריה ליב (רלב\"ג - ר ליב בן גבריאל), ונכדו - ר אליעזר דן."},{"i":52789,"n":"שטוקמן, מאיר מזלישטשיק","k":"בעל שליחות משה","b":"מורה בקרליפקה, טשרנוביץ. חיבר \"שליחות משה\" (תרגום מכתבי המשורר שילר) - למברג תרלט, \"אלון בכות\" טשרנוביץ תרעג."},{"i":52790,"n":"שטוקמן, נח","f":"יחיאל צבי מפשוורסק","k":"בעל שעורי חן","bt":"תרעה","dt":"תשמה","dp":"ירושלים","b":"מקורב למהרי\"ד מבלז ולרד\"ב מטשבין. חסיד בלז. ניצל מהשואה, ואחריה רב בפשמישל. עלה לירושלים וכיהן כראש ישיבת בלז. חיבר \"שעורי חן\" ירושלים תשכב."},{"i":52791,"n":"שטוקר, מתתיהו","b":"תשובה אליו - מהר\"י הכהן."},{"i":52792,"n":"שטורך, אהרן יעקב מגורליץ","f":"מנחם מנדל","bt":"תרסו","bp":"גורליץ","dt":"תש..","b":"חתן ר משה נתן גוטויין מיסלו. נספה בשואה. מתורתו ב-כר\"ש - תשמא. נספה בשואה."},{"i":52793,"n":"שטורך, אליעזר","b":"רב בדובנא"},{"i":52794,"n":"שטורך, ברוך צבי הירש","f":"מנחם מנדל","k":"הו\"ל כרם חמד","dt":"תש..","b":"תלמיד ישיבת בובוב בגורליץ. הוציא לאור בעילום שמו - \"כרם חמד\" - פיעטרקוב תרפט-תרץ - קובץ תלמידי ישיבת \"תפארת בחורים\" בגורליץ. נספה בשואה."},{"i":52795,"n":"שטורך, הלל מבוברקא","f":"מנחם הלוי","k":"בעל פרי הללוים","b":"רב בבוברקא. חיבר \"לקוטי שושנים\" תרלה, \"פרי הלולים\" למברג תרלח, ועוד."},{"i":52796,"n":"שטורך, חיים דב בריש מיימרקט","f":"שמואל ראובן מליזנסק","bt":"תרכג","dt":"תרצב","b":"רב בניימרקט-תרמה כיובל שנים - על מקום ר יוקל הירש, רב בקראקא. ממשתתפי \"אהל מועד\"."},{"i":52797,"n":"שטורך, מנחם מנדל מקאטוב","f":"הלל מבוברקא","k":"בעל הלכה ברורה","b":"חתן ר מנחם מנס גוטסמן מסוקולוב. רב בקאטוב (ליד בוריסלב). חיבר \"הלכה ברורה\" דרוהוביטש תרנא."},{"i":52798,"n":"שטורך, משה מקראקא","b":"מגדולי ראשי הישיבות,רב בקרקא"},{"i":52799,"n":"שטורך, שמואל ראובן","b":"דומ\"צ בליזניק-תר\"ל"},{"i":52800,"n":"שטורך, שמואל ראובן מליזנסק","dt":"תרלה","b":"רב בליזנסק, בנו ר יעקב מחכמי ליזנסק."},{"i":52801,"n":"שטורם, אברהם","f":"דב ברל הלוי","dt":"תשכח","b":"עבר לברלין, בובוב, עבר ללונדון-תרצט, ניו יורק-תשח. חתן ר ישעיה פלאטנער מפלאווינקע (ליד בובוב). בנו ר שבתי ישעיה - נשיא מוסדות בובוב, ולכבודו \"ברכה לראש משביר\" ניו יורק תשמו."},{"i":52802,"n":"שטורם, אברהם הכהן מברוד","b":"מחכמי ברודי - תשובה אליו \"אמרי דוד\"-תרץ."},{"i":52803,"n":"שטטהאגן, יהודה מאלטונא","f":"בנימין וולף מהלברשטט","k":"בעל מנחת יהודה","b":"תלמיד ר צבי חריף מהלברשטט, ר שמואל הלברשטט מהאנאו, מחכמי הקלויז באלטונא. חיבר \"מנחת יהודה\" אמשטרדם תקכג - על כל מלת \"כלומר\" שברש\"י."},{"i":52804,"n":"שטטהאגן, יוסף","f":"שמשון","k":"בעל דברי זכרון","bt":"ת","b":"רב בשטטהגן."},{"i":52805,"n":"שטטהגן יוסף בן שמשון","bt":"1640","dt":"ה'תעד 1714","bk":[["דברי זכרון",""]]},{"i":52806,"n":"שטטינר, גרשון מזבלטוב","b":"רב בזבלטוב."},{"i":52807,"n":"שטיא ן, אפרים ממוסול","b":"מחכמי בבל הקדמונים, תלמיד הרס\"ג. רב במוסול-ד'תרל. נזכר בקשר למחלוקת רב סעדיה גאון עם ר אהרן כליף שארמגאדי - היה מתומכי ר אהרן אך בהמשך תמך ברב סעדיה (למרות זאת מינה ר אהרן שהיה גאון על מקום רב סעדיה אחריו - מינה את ר אפרים לרב במוסול - ועל כך לעגו לו הקראים)."},{"i":52808,"n":"שטיבל, אברהם מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":52809,"n":"שטיבל, יהודה זלקין","dt":"שצה","b":"מחכמי פפד\"מ."},{"i":52810,"n":"שטיבל, יוסף מבלז","f":"אריה ליב מבלז","k":"בעל נחלת יוסף","bp":"בלז","b":"חסיד בלז. תלמיד ר שלו פוילישער המחנך של בית האדמור, ותןלמיד ר מיכלי זולקוור. ניצל מהשואה ועבר לניו יורק. חתן ר יוסף דב ב\" יעקב מאיר. חיבר \"נחלת יוסף\" ניו יורק תשמח."},{"i":52811,"n":"שטיבל, ליווא יצחק","b":"מראשי קהילת פפד\"מ-תא, בזמן ר שבתי הורביץ-בנו של השל\"ה."},{"i":52812,"n":"שטיגליץ, אברהם ישכר מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":52813,"n":"שטיגליץ, אלתר משה אליהו","f":"אפרים נתן","k":"בעל צלח החדש","bt":"תרל","bp":"טרנוב","dt":"תש","b":"חתן הגביר ר שלמה יושעה'ס הלוי רוטנברג מרוזוודוב, ועבר אל חותנו. סירב להצעות רבנות בעצת האדמור מבלז. עבר לטרנוב. חיבר \"צלח החדש\" ברטפלד תרעג, ועוד."},{"i":52814,"n":"שטיגליץ, אפרים נתן מטורנא","f":"צבי הירש מזבנא","dt":"תרעט","dp":"טרנוב","b":"גביר מחכמי טורנא. נכדו של ר זכריה מ נדל משנדישוב בעל \"דרכי צדק\". חתן הגביר ר אשר קורן מדומברובה."},{"i":52815,"n":"שטיגליץ, דוד","f":"יוסף דב חיים מבוכניה","bt":"תרעא","b":"למד בישיבת טשבין ויח\"ל. ניצל מהשואה - היה שו\"ב בעיר גורי בגיאורגיה, ואחריה רב בחוז'וב, עלה לארץ-תשט וכיהן כרב בנתניה. חתן ר חיים כץ מקושיץ. ההדיר ספר \"צלח החדש\" לזקנו."},{"i":52816,"n":"שטיגליץ, זאב אריה","f":"אפרים נתן מטורנא","dt":"תשז","b":"מחכמי טרנוב, עלה לירושלים. סבם של הרבנים ממשפחת אריאל."},{"i":52817,"n":"שטיגליץ, יצחק מאונסדורף","b":"תלמיד הדברי חיים מצאנז. חתן ר שלמה זלמן פרלשטין מאונסדורף, דיין באונסדורף-תרלו על מקום חותנו? אצל ר שלמה זלמן פרלשטין."},{"i":52818,"n":"שטיגליץ, יצחק מדומברובה","b":"חסיד בלז. חתן ר יעקב אייזלנד מדומברובה, ועבר אליו. בנו ר יעקב רב בדומברובה."},{"i":52819,"n":"שטיגליץ, מרדכי נתן ממליץ","f":"יצחק זכריה מזבנא","k":"בעל דרך ים","b":"מחסידי דזיקוב במעליץ. עבר ללמוד באוני' ברלין, התגורר בפרנקפורט ועבר לניו יורק. חיבר \"דרך ים\" מונקטש תרס."},{"i":52820,"n":"שטיגליץ,יוסף דב חיים מרוזוודוב","f":"אלתר משה אליהו","bt":"תרנב","bp":"רוזוודוב","b":"חתן הנגיד ר שאול הוכשטין מבוכניה. ניצל מהשואה. עלה לארץ-תשט."},{"i":52821,"n":"שטיגר, חיים","f":"עקיבא אפרים מזבנא","k":"בעל אמרי חיים","dt":"תרעח","dp":"צפת","b":"חיבר \"אמרי חיים\" - כתביו אבדו בשואה."},{"i":52822,"n":"שטיגר, יוסף מרדכי מאולשקוביץ","b":"רב באוסציא - לפני תרכט, אולשקוביץ."},{"i":52823,"n":"שטיגר, משה מרדכי מרדלוב","f":"עקיבא אפרים מזבנא","k":"בעל מגד שמים","bt":"תריח","dt":"תשד","b":"תלמיד השו\"מ ור אברהם בנימין קלוגר. חסיד בובוב. רב ברדלוב-תרמה. עלה לארץ-תרצה והתישב בצפת. חתן ר שמעון אליעזר רנד נווישניצא. חיבר \"מגד שמים\" קראקא תרמט, ועוד."},{"i":52824,"n":"שטיגר, עקיבא אפרים מזבנא","dt":"תרנ.. - בערך","dp":"צפת","b":"חסיד צאנז. רב בזבנא-תרך, רדלוב. עלה לארץ ונפטר בצפת אחרי תרמט."},{"i":52825,"n":"שטיגר, שמואל יהודה מטורקא","f":"צבי הרש","k":"בעל אבני שיש","bt":"תריט","bp":"טורקא","dt":"תרצא","b":"נכד ר שמואל שיינדלינגר מסאל. חתן ר צבי אריה ביינהורן. חסיד שיניבה והאדמור התיעץ עמו. התישב בברזנא-הונגריה. חיבר \"אבני שיש\" מונקטש תרפח."},{"i":52826,"n":"שטיין, אבי העזרי מאשכנז","f":"יצחק איזיק","b":"מחכמי אשכנז-רן. ערך את ביאורי אביו לסמ\"ג-רסו. חיבר הגהות ל\"לקט יושר\" לר יוסף מינסטר."},{"i":52827,"n":"שטיין, אברהם אשר זליג","f":"משה מאורישור-באר משה","bt":"תרך","bp":"כפר אורישור","dt":"תרצב - בערך","b":"מצאצאי ר יוסף קארו בעל \"בית יוסף\". גדל אצל ר ישכר בער קאהן מערדא-סענזשארץ שהיה אביו חורגו. תלמיד ר מנחם מנדל פאנט בדעש. חתן הגביר יחיאל נח מהורדו-ליד נאסוד ועבר לשם. רב בסעקעי-אודווארהי(=אודוארהעלי)-תרנב בגליל הרבנות של אביו חורגו כ-50 שנה. הו\"ל ספר אביו חורגו \"באר משה\" עם הקדמה ממנו."},{"i":52828,"n":"שטיין, אברהם יעקב מואדוביץ","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":52829,"n":"שטיין, אברהם מהידלמאש","b":"רבה הראשון של הידאלמאש-תקץ כ-30 שנה."},{"i":52830,"n":"שטיין, אברהם משה מקלויזנבורג","f":"זאב יהודה מקלויזנבור","bt":"תרלה","bp":"קלויזנבורג","dt":"תשד","b":"תלמיד ר משה שמואל גלזנר בקלויזנבורג, ובעל \"ערוגת הבשם\" בחוסט. חתן ר נחום בנימין קאליש ממונקטש וגיסו של ר משה פאנט מדעש. רב בשארמאש-ליד קלויזנבורג-תרנח, דיין בקלויזנבורג-תרסד - ובזמן הפילוג בקהלה הצטרף לקהלה הספרדית כנגד רבו רמ\"ש גלזנר. נספה בשואה. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד."},{"i":52831,"n":"שטיין, אהרן מסקימיאן","f":"אבא","bt":"תרטו","dt":"תרצד - ד חשון","b":"רב בשקדוציסק-תרמב, סקימיאן-פלך קובנא-תרמד, אניקשט, שניפישוק. נסמך מאת: ר בצלאל הכהן מוילנא, ר מרדכי קלצקי מלידא, הנצי\"ב."},{"i":52832,"n":"שטיין, אליעזר ליפמן מסערדאוהל","k":"בעל אבל משה","dt":"תריא - כז אב","b":"תלמיד החת\"ס. רב בסעליש על מקום ר חיים מאיר זאב רפפורט ור חיים משה (נכד ר יאיר-הרב הראשון שם) על מקומו אחריו, דינדיש(=דיו נאדוש), עלה לארץ וחזר להונגריה רב בסערדאהעלי-תר. חיבר גם \"ועיר שושן\" ועוד. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":52833,"n":"שטיין, אלישע מזמיגרוד","b":"רב בזמיגרוד."},{"i":52834,"n":"שטיין, אשר זליג הירש מארישאר","b":"גביר בארישאר. חתניו - ר משה שטיין מארישאר, ר מרדכי יהודה לעוו מאינטרדם, ור ישכר דב קאהן מסענזשארץ."},{"i":52835,"n":"שטיין, גרשון מקיטוב","f":"יוסף","b":"מחכמי קיטוב. תשובה אליו ב\"קנאת סופרים\". (בנו כנראה ר פנחס - דור חמישי לט\"ז)."},{"i":52836,"n":"שטיין, דוד מקיטוב","f":"פנחס מקיטוב","b":"גביר מחכמי קיטוב. ידידו של ר חיים מקוסוב. בזיוו\"ש חתן ר ישכר דב ביליג."},{"i":52837,"n":"שטיין, ויקטור מפרשבורג","b":"נשיא ארגון הקהלות הלא אורטודוכסיות בצכוסלובקיה-תרצד, וראש קהלת ישורון הקונסרבטיבית בפרשבורג. שיתף פעולה עם העסקנים החרדים בהקמת מוסדות ציבור ובהם ביה\"ח היהודי."},{"i":52838,"n":"שטיין, זלמן","b":"מחכמי מגנצא,מו\"צ באופנהיים-שנת ר'"},{"i":52839,"n":"שטיין, זלמן","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":52840,"n":"שטיין, חיים מקליבלנד","bp":"שקודוויל-ליטא","b":"ר\"מ בישיבת טלז בקליבלנד. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":52841,"n":"שטיין, טוביה פרץ","r":"דיין בקהילת דיאושדיאר","bt":"תרסו בערך","dt":"תשד","b":"רב בדיוש-דיור","bk":[["רמון פרץ - חולין",""]]},{"i":52842,"n":"שטיין, יהושע ליב","b":"רב באופינה-תר\"נ"},{"i":52843,"n":"שטיין, יואל פיבל מטבריה","b":"חתן ר דוד בן אברהם דב-חתן ר יעקב יוסף בעל \"תולדות יעקב יוסף\". ממונה על כולל ואהלין."},{"i":52844,"n":"שטיין, יוסף מקראקא","b":"שו\"ב בקראקא."},{"i":52845,"n":"שטיין, יעקב אליעזר","f":"צבי אריה מלוביטש","dt":"תשג","dp":"סיביר","b":"חסיד בלז מהיושבים אצל האדמור, והיה מחנך בבית האדמור. חתן ר יעקב פרידמן מדובצק."},{"i":52846,"n":"שטיין, יעקב יוסף","dt":"תרצ","b":"ר\"מ בניו יורק"},{"i":52847,"n":"שטיין, יצחק איזיק","k":"בעל ביאור על הסמג","bt":"ה'קצ (בערך)","dt":"רנו - א תשרי","b":"תלמיד ר טבלי מנירנברג. מגדולי התורה בחכמי אשכנז, מרביץ תורה בנירנברג, גנצהויזן, אחר הגירוש עבר לרגנסבורג, ברונא. אחיו של ר אהרן מפפנהיים. בנו - ר אבי עזרי. חיבר ביאור לסמ\"ג ונדפס בקיצור ע\"י בנו, והחיד\"א ראה את הספר הארוך. ?? לא באוצר ??","bk":[["ביאורי הסמ\"ג",""]]},{"i":52848,"n":"שטיין, יצחק מממל","f":"גרשם","bt":"תרלט","b":"רב בממל(=מעמל)-תרסו."},{"i":52849,"n":"שטיין, לוי מברלין","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":52850,"n":"שטיין, ליאופולד מפשרבורג","b":"רופא בפרשבורג, ראש הועדה לעזרה לעניים, וארגן אגודה להחזקת תמחוי-תרנא."},{"i":52851,"n":"שטיין, מאיר מיכאל מטירנא","f":"פנחס - קנאת פנחס","k":"בעל אבן המאיר","bt":"תרכה-ח","bp":"טירעק-סנט מיקלוש","dt":"תרצג - ו טבת","dp":"טירנא","b":"תלמיד השב\"ס, ור יוסף הניג מנייטרא, ור יצחק קאפף מערלוי(=אויהל), ור שמעון פרידמן מגאלאנטא. חתן ר שלמה צבי שיק מקארצאג. רב בטירעק-סנט מיקלוש-תרמו על מקום אביו, נאגי סומבאט, טירנא וציפער-תרנו, וחתנו ר מאיר צבי דושינסקי על מקומו אחריו. חיבר \"רבני הגר\"."},{"i":52852,"n":"שטיין, מנחם לוי","f":"אליעזר ליפמן שטיין","b":"רב בטשאטה,עבר לברלין-תר\"כ"},{"i":52853,"n":"שטיין, מנחם מנדל ליפא מטשרניוב","f":"דוד מקיטוב","k":"בעל חדושי הרמל","bt":"תקע","dt":"תרמב","b":"דודו של ר מאיר ארק (בן אחותו). רב בטשרניוב (ליד סטניסלב). חתן ר גדליה מרגליות, נפטר ללא ילדים. חיבר \"חדושי הרמ\"ל\" קולומיאה תרן."},{"i":52854,"n":"שטיין, מרדכי אריה ליב מגרוסורד","f":"אליעזר ליפמן מסרדאהל","dt":"תרכא-ד -יד ניסן","dp":"גרוסורדין","b":"תלמיד החת\"ס. רב בגרוסורדין-תקץ."},{"i":52855,"n":"שטיין, מרדכי אריה מגרוסורדין","dt":"תרמא","b":"ראש הדיינים בגרוסורדין, ור ישראל משה קליין על מקומו אחריו."},{"i":52856,"n":"שטיין, מרדכי משטיינמנגר","dt":"תשמד - ח כסלו","b":"חתן ר טוביה הכהן פישר משארוואר. ראש ישיבה קטנה בשטיינמנגר(=סומבוטהי), רב מושב הזורעים."},{"i":52857,"n":"שטיין, משה מגאלניצבאניא","dt":"תשד","b":"חתן ר שמחה נתן גרינבורג מקעזמרק. רב בגאלניצבאניא(=גלניץ)."},{"i":52858,"n":"שטיין, משה מערדא-סענזשארץ","f":"אברהם מהידאלמאש","k":"בעל באר משה-תרסא","bt":"תר","bp":"הידאלמאש","dt":"תרלד - ד תשרי","dp":"סענזשארץ","b":"תלמיד הכת\"ס, ודודו ר פרץ טוביה שטיין (פילדער), ור מנחם מנדל פנט מדעש. חתן ר אשר זליג הירש (שטין?) מארישאר, וגיסו של ר מרדכי יהודה לעוו מאינטרדם. רב בארישאר-תרכא על מקום רבו שעבר לדעש, ערדא-סענזשארץ(=סט-גיורג)-תרכו ור ישכר דב קאהן על מקומו אחריו. כשחלה ר יחזקאל יוסף בנו של רבו ר מנחם מנדל פאנט פנה אל תלמידו שיתפלל עליו - התיחס אל תלמידו כצדיק פועל ישועות. לאחר שנפטר נישאה אלמנתו לר ישכר בער קאהן שכיהן על מקומו אחריו בערדא-סענזשארץ.","bk":[["באר משה – עה\"ת",""]]},{"i":52859,"n":"שטיין, פנחס מטירעק","f":"ישעיה יעקב מפיווניטץ","k":"בעל קנאת פנחס","r":"אב\"ד ק\"ק טורוק ס\"ט מיקלאש","bt":"תקץ","bp":"פיווניטץ","dt":"תרמו - כ תמוז","dp":"טירעק סנט מיקלוש","b":"תלמיד הכת\"ס, ר מנחם א\"ש מאונגוואר, ור אליקים געץ שווערין מבייאה, ר יצחק משה פרלס מבאניהאד. חתן ר יו\"ט ליפמן קערעפש מאירשא ועבר לשם. רב בקהילת הסטטוס-קוו בטירעק(=טורוק) סנט מיקלוש-תרטו ובנו ר מאיר על מקומו אחריו. לחם נגד הנסיונות לתקונים בדת. נזכר ב\"יוסף דעת\".","bk":[["קנאת פינחס - שו\"ת על ד' חלקי שו\"ע",""]]},{"i":52860,"n":"שטיין, פסח מארה\"ב","f":"אהרן שמואל","k":"בעל שיעורי הגר\"פ שטי","bt":"תרעח","bp":"בריאנסק","dt":"תשסב - כח אייר","dp":"ארה\"ב-ירושלים","b":"תלמיד ר שבתי יגל, תלמיד ישיבת מיר-תרצו וגלה עם הישיבה לשנחאי, ומשם הגיע לארה\"ב - כל משפחתו נספתה בשואה. חתן ר זלמן בלוך מטלז. ר\"מ בישיבת טלז בווקליף-ארה\"ב. בנו ר זלמן שמואל - נפטר בחייו-תשמח. אביו-נספה בשואה היה תלמיד ר שמעון שקופ."},{"i":52861,"n":"שטיין, פרץ טוביה מגלניץ","dt":"תרצו","b":"תלמיד ר שמואל רוזנברג מאונסדורף. רב בגלניץ-תרפא."},{"i":52862,"n":"שטיין, פרץ טוביה מדיאשדיער","dt":"תשד","b":"חתן ר שמשון נייפלד ממישקולץ. רב בדיאשדיער על מקום חותנו. נספה בשואה?"},{"i":52863,"n":"שטיין, צבי אריה מלוביטש","f":"יעקב אליעזר","bp":"פרימישלן","dt":"תרעט","b":"חסיד בלז ומקורב למהרי\"ד. רב בלוביטש."},{"i":52864,"n":"שטיין, שלמה דוב","bt":"תרנז","dt":"תשב","b":"רב בקעלן-תרצ\"ה"},{"i":52865,"n":"שטיין, שמואל","b":"תלמיד בישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":52866,"n":"שטיינאייזן, דב בר נישויעזער","f":"קיים קדש","k":"בעל יהגה חכמה","dt":"תריח - י חשון","dp":"וילנא","b":"תלמיד ר חיים מוולוזין, מחכמי נוברדוק, דיין בוילנא-תקץ. חיבר גם \"כוכבי אור\" - בכת\"י. נפטר ללא ילדים. (נאמר כי היה ביד חכם אחד שהוציא משם חדושים ופרסמם בשמו), \"עמק הבכא\". (היה אחד מ-4 תלמידים שר חיים מוולוזין זרק בהם מרה - מלבדו גם ר יצחק אמידער - איצעלע סמארגאנער, ר ישראל ראקאווער - ר ישראל חריף, ור מאשקע רמב\"ם צייטלין, ונתקיימו על כלם דברי ר חיים הקשים וכו')."},{"i":52867,"n":"שטיינבך, אברהם מארה\"ב","b":"רב בבולטימור. הו\"ל פרק מהש\"ס באנגלית."},{"i":52868,"n":"שטיינברגר, שמואל יעקב מטימישוא","b":"ש\"ץ ורב ק\"ק יראים בסגדין-הונגריה, דיין בטימישואר-תרלה."},{"i":52869,"n":"שטיינוארצל, משה דוד מניו יורק","k":"בעל וידבר משה","b":"ר\"מ בישיבת בובוב בניו יורק-תשנב."},{"i":52870,"n":"שטייף, יונתן מבודפשט","f":"צבי מגאיא","k":"בעל למודי השם","bt":"תרלז","bp":"גאיא","dt":"תשיח - ט אלול","dp":"ניו יורק","b":"תלמיד השב\"ס, ור דוד ניימן מפרשבורג, ור אליעזר זוסמן סופר מפאקש בעל \"ילקוט אליעזר\". חתן ר מיכאל פישל מפאקש ועבר לשם. רב בגוטא-תרסו, אונגוואר-תרעב אצל ר אלעזר לעוו בעל \"פקודת אליעזר\", בודפשט-תרפג, והיה הראב\"ד-תשב. ניצל מהשואה והגיע לשוויץ-תשד. עבר לארה\"ב-תשז וכיהן כר\"מ בישיבת נייטרא במונט קיסקא וכרב \"עדת יראים\" בניו יורק, ר עזריאל יודא ליבוביץ מהאדהאז על מקומו אחריו. חיבר \"חדשים גם ישנים\", \"דרוש וחדוש\", ועוד. עורך \"החיים\" - אונגואר תרפב. עורך \"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב.","bk":[["דרוש וחידוש – פתיחה לה' נידה",""],["חדשים גם ישנים – ברכות וחולין",""],["למודי ה' – עה\"ת",""],["מהר\"י שטייף – שו\"ת",""],["מצוות ה' -",""],["מצוות ה' - , דרוש וחידוש – פתיחה לה' נידה, חדשים גם ישנים – ברכות וחולין, למודי ה' – עה\"ת , מהר\"י שטייף – שו\"ת",""]]},{"i":52871,"n":"שטייף, יוסף מברין","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":52872,"n":"שטייף, צבי מגאיא","f":"יצחק","dt":"תרנח - י אב","dp":"ירושלים","b":"מצאצאי ר יונתן איבשיץ ור מנחם מנדל קרוכמל בעל הצמח צדק. תלמיד הכת\"ס. מחכמי גאיא. עלה לירושלים-תרנח."},{"i":52873,"n":"שטייר, אלימלך","b":"פרסם מאמרים ב\"יבנה\" - לבוב תרפט."},{"i":52874,"n":"שטילבנס, פנחס זליג מאוזליאן","f":"שלום","bt":"תרח","bp":"וולוזין","b":"נכד ר אלעזר המכונה \"לייזער לעכעוויצר\" רבה של הורודוק. רב באוזליאן-תרל על מקום אביו."},{"i":52875,"n":"שטילבנס, שלום מאוזליאן - הזקן","f":"אלעזר מהורודוק","dt":"תרכט","b":"תלמיד ישיבת וולוזין. רב באוזליאן, ובנו ר פנחס זליג על מקומו אחריו."},{"i":52876,"n":"שטילבנס, שלום מדאראגאנאייא","f":"פנחס זליג שטילבנס","bt":"תרלד","b":"תלמיד ישיבת וולוזין, כולל קובנא. חתן ר מרדכי דוד הלפרט מסוסלאץ. רב בדרגנובו(=דאראגאנאייא)-פלך מינסק-תרסז. נסמך מאת: ר משה שמואל שפירא מבוברויסק."},{"i":52877,"n":"שטיליה די, יעקב משלוניקי","dt":"שיח - אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":52878,"n":"שטילינג, בנדיקט הרופא","bt":"1810","bp":"קירכהיין","dt":"תרלט","b":"רופא מלומד ובקי במדעים. המציא חוסם עורקים. חיבר ספרים ברפואה."},{"i":52879,"n":"שטילר, אלכסנדר","b":"רשם את חדושי רבותיו ובהם - בעל כתב סופר, המהר\"ם שיק, ר אהרן יהושע וינברג בעל שו\"ת מהריא\"ץ. כתב היד עבר אל אחיו - גרשון."},{"i":52880,"n":"שטילר, גרשון","b":"קיבל את כתבי אחיו - אלכסנדר, ובו חדושי רבותיו, וחתם את שמו-תרלו."},{"i":52881,"n":"שטילר, שמואל פנחס מזולקוא","f":"יעקב מבוברקא","bt":"תקסז","bp":"בוברקא","dt":"תרם","b":"רב בזולקוא. חתן ר בנימין זאב בלומנפלד מלמברג."},{"i":52882,"n":"שטינבך, מאיר","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":52883,"n":"שטינברג משה בן יצחק","bt":"1909","dt":"ה'תשנג 1993","bk":[["תורת הטור",""]]},{"i":52884,"n":"שטינברג, אברהם","f":"משה מפשמישל","k":"בעל אנציקלופדיה הלכת","bt":"תשז","bp":"מינכן","b":"רב ורופא בירושלים. חיבר \"אנציקלופדיה הלכתית-רפואית\".","bk":[["הרפואה כהלכה","הלכה ומנהג - אחרונים"]]},{"i":52885,"n":"שטינברג, אברהם מנחם מנדל","f":"מאיר","k":"בעל מחזה אברהם","bt":"תרז","bp":"סערט","dt":"תרפח - א סיון","b":"נכד ר שמעיה שטינברג. מחסידי רוזין, כונה העילוי מסערט. תלמיד ר בן ציון מסערט. חתן הנגיד ר דוד אגדשטין(=אגאטשטין) מיאסי, ובזיוו\"ש חתן הגביר ר שאלתיאל איזיק שטרנהל מקולומיאה. רב בסניאטין-תרלט (או תרכט) (והיה שם מחלוקת בין חסידי סדיגורא לויזניץ). רב בברודי-תרסז על מקום ר יצחק חיות (והיה מחלוקת בין החסידי שתמכו בו לבין המשכילים שהתנגדו) והקים שם ישיבה. ממייסדי אגודת ישראל ומראשיה. לאחר הצהרת בלפור כינסה הממשלה האוסטרית את ראשי היהודים כדי להתנגד להצהרה והוא היה מהתומכים בהצהרה וכך התקבלה ההחלטה. חיבר \"קדושת שביעית\" ירושלים תרסט, ועוד. בא לבריסק לבחון את הגרי\"ז עבור בתו - סיפר עליו לר חיים אוירבך מירושלים שלקחו לבתו. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"דגל התורה\" - וארשא תרפב, \"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"הפרדס\" - צאנז תרצא, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה, \"קובץ דרושים\" - פיעטרקוב תרפג, \"רבותינו שבגולה\" - פרשבורג תרעה. בניו: ר שמעיה מפרימישלן, ר דב מטלימאטש, ר חיים מפודגורזא, ר שלמה. חתניו: ר משה מקוסוב, ר משה באבד מטרעמבאייא, ר ליב גלקימן, ר זכריה אראק.","bk":[["מחזה אברהם - שו\"ת",""],["קדושת שביעית",""]]},{"i":52886,"n":"שטינברג, אלעזר מברלין","k":"בעל יידיש און חסידיש","b":"מצאצאי רשי. נסע בצעירותו לבלז ונעשה תלמידו של בעל החבצלת. הפך לתלמיד חכם חסידי. נספה בשואה, וכתביו אבדו. חיבר \"יידיש און חסידיש\"."},{"i":52887,"n":"שטינברג, אפרים מרדכי מנ\"י","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":52888,"n":"שטינברג, ברוך מדוניוב","f":"שמעיה מפרימישלן","bt":"תרנז","dt":"תשא","b":"רב בדוניוב-תרפד, ורב ראשי בצבא הפולני. נספה ביער קאטין (ע\"י הרוסים)."},{"i":52889,"n":"שטינברג, ברוך מלבוב","b":"מחכמי למברג. תשובה אליו ב\"משיב שלום\"-תרץ."},{"i":52890,"n":"שטינברג, דב בריש מטלומטש","f":"אברהם מנחם מנדל","bt":"תרכח","dt":"תשג","b":"חסיד בויאן. רב בטלומטש-תרנז, רישא. בזיוו\"ש חתן ר יצחק מאיר אמרויט ונכדת החוו\"ד. נספה בשואה. פרסם מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":52891,"n":"שטינברג, חיים מפודגורזע","f":"אברהם מנחם מנדל","b":"חסיד גור, מחכמי פודגורזע. חתן הגביר וידיסלבסקי מלודז. נספה בשואה."},{"i":52892,"n":"שטינברג, יהודה","k":"בעל שיחות ילדים","bt":"תרכד","bp":"ליפקאני-פלך בסרביה","b":"סופר. למד בבתי המדרש בעירו ופנה גם להשכלה. עבר אל חותנו בשטפנשט-רומניה, חזר לרוסיה והתישב בלעאווא. חיבר \"בעיר וביער\", ועוד."},{"i":52893,"n":"שטינברג, יהושע","k":"בעל מערכי לשון עבר","bt":"1839","bp":"וילנא","dt":"1908","dp":"וילנא","b":"רב מטעם בביאליסטוק, וילנא. מדריך לעברית וארמית בביהמ\"ד למורים בוילנא, ומפקח המוסד. צנזור ממשלתי-1863 עד 1908. בזכות קשריו עם השלטונות קיבל עזרה ליסוד בתי\"ס בוילנא והסביבה. פרסם מאמרים בחקר הלשון."},{"i":52894,"n":"שטינברג, יוסף","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":52895,"n":"שטינברג, יוסף אלעזר מברוד","f":"מרדכי מברודי","dt":"תריב","b":"רב בברודי-תקע."},{"i":52896,"n":"שטינברג, יוסף אלעזר מסערט","f":"מאיר מסערט","b":"מחכמי סערט-תרמו."},{"i":52897,"n":"שטינברג, יוסף מנדבורנה","b":"רב בנדבורנה-תרנח."},{"i":52898,"n":"שטינברג, יעקב שאול מסערט","f":"מאיר מסערט","bt":"תרטז","bp":"סערט","dt":"תרעג","dp":"אנטורפן","b":"חתן הגביר ר אלעזר מרגליות, עבר לאנטורפן-תרמה."},{"i":52899,"n":"שטינברג, יצחק מהליטש","f":"שמעיה מפרימישלן","bt":"תרמז","bp":"טרנוב","dt":"תשכז","b":"רב בהליטש, ירוסלב-תרפא. ניצל מהשואה, וכיהן כרב בבריסל, עלה לארץ-תשיא וכיהן כרב בתל אביב. חתן ר אלתר דב פשרונג מטושקוב (ליד בלז), ובזיוו\"ש חתן ר אליהו תאומים-פרנקל מפשוורסק."},{"i":52900,"n":"שטינברג, מאיר מסערט","f":"שמעיה","bt":"תרי","bp":"סערט","dt":"תרסג","b":"חתן הגביר ר זלמן בריש רוטנברג מברודשין, וגיסו של ר נפתלי הורביץ מסניוואץ. אביו של ר אברהם מנחם מנדל מסניאטין."},{"i":52901,"n":"שטינברג, מאיר מצורטקוב","f":"שמעיה מפרימישלן","k":"בעל שאלה ותשובה","bt":"תרסה","dt":"תשלא","dp":"לונדון","b":"רב בפרימישלן לצד אביו, רב בצורטקוב. ניצל מהשואה, עלה לארץ חתן ר אורי שכטר מאושפיצין. רב בלונדון. חיבר \"שאלה ותשובה\" לונדון תשיז."},{"i":52902,"n":"שטינברג, מכסימיליאן","f":"יהושע","bt":"1883","bp":"וילנא","dt":"1946","b":"תלמיד רימסקי=קורסקוב וחתנו. פרופ' בקונסרבטוריון-1909 בפטרבורג ומנהלו-1934."},{"i":52903,"n":"שטינברג, מרדכי מברוד","b":"נכד ר שמואל מטיסמניץ. מחכמי ברודי ואביו של ר יוסף אלעזר לויער מסערט."},{"i":52904,"n":"שטינברג, מרדכי מצ'חנוביץ","dt":"תש..","b":"תלמיד הסבא מנוברדוק. רב בצ'כנוביץ-ניישטאט. נספה בשואה."},{"i":52905,"n":"שטינברג, משה מברוד","f":"שמעיה מפרימישלן","bt":"תרסג","dt":"תשמו","b":"תלמיד זקנו ה\"מחזה אברהם\", רב בברודי-תרץ על מקום זקנו לצד ר יוסף פופרש. חתן ר יעקב פרנקל-תאומים מפודגורזע. ניצל מהשואה, וכיהן אחריה בלמברג, קראקא, פרג, עבר לארה\"ב וכיהן כרב בניו יורק. נפטר ללא ילדים. על מקומו כדיין בניו יורק ר שלמה הרבסט. רוב כתביו אבדו בשואה, חיבר והכין לדפוס \"עין משה\"."},{"i":52906,"n":"שטינברג, משה מפשמישל","f":"יצחק מירוסלב","k":"בעל תורת הגר","bt":"תרסט","bp":"פשמישל","dt":"תשנג","dp":"ירושלים","b":"רב בפרימישלן לצד זקנו ר שמעיה. חתן ר אברהם גלייכר מגורליץ. ניצל מהשואה וכיהן אחריה כרב בהוף (ליד מינכן), עלה לארץ-תשט טכיהן כרב בקרית ים, עבר לירושלים והיה מראשי אוצר הפוסקים. חיבר \"תורת הגר\" חיפה תשיד ועוד. בנו אברהם רופא ורב מחבר \"אנציקלופדיה הלכתית רפואית\"."},{"i":52907,"n":"שטינברג, שמעיה","b":"גביר. בנו - ר מאיר מצורטקוב."},{"i":52908,"n":"שטינברג, שמעיה מברוד","f":"יוסף אלעזר לויער","bt":"תקסט","bp":"ברודי","dt":"תרכה","b":"תלמיד ר צבי הירש חריף מבריגל. חתן הגביר ר אברהם מרדלר מסערט, עבר אל חותנו לסערט ושינה שמו לשטינברג (כשם חמותו)."},{"i":52909,"n":"שטינברג, שמעיה מפרימישלן","f":"אברהם מנחם מנדל","bt":"תרכה","bp":"סערט","dt":"תשא - טז תמוז","b":"חתן הגביר ר משה וקסלר מטרנוב. רב בזביא-תרמז (בקרפטים), פרימישלן-תרן. מתורתו בספרי חכמי דורו. פרסם מאמרים ב\"ועד חכמים\" - יזלוביץ (ועוד) תרנח, \"הכוכב\" - מונקטש-נ\"י תרצה, \"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":52910,"n":"שטינברג, שרגא הלוי מבני ברק","b":"חתם על תעודה של ישיבת \"תפארת ציון\" בבני ברק-תרצז."},{"i":52911,"n":"שטינברגר, אליהו מבודפשט","f":"בנימין זאב סגל","b":"עורך \"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":52912,"n":"שטינברגר, אלכסנדר הכהן מקומרנה","k":"בעל מאורות אש","bt":"תריד","bp":"גירבא-פינצעהל","dt":"תרעט - כג אייר","dp":"קאמארן","b":"תלמיד הכת\"ס, ור אברהם קרפלס מגירבע, ר יוחנן שפיץ מטאב, ר אברהם צבי אבלס משארבאגרד. מחכמי רוגנדורף. רב בקאמאדן(=קאמארען)-תרם - בקהילת היראים."},{"i":52913,"n":"שטינגר, יצחק יעקב יונה מסמבור","f":"שמואל משה","b":"רב בסמבור."},{"i":52914,"n":"שטינהיים, שלמה הלוי הרופא מאלט","k":"בעל עובדיה בן עמוס","bt":"תקמט","bp":"כפר ברוכהויזן","dt":"תרכו - ד סיון","dp":"ציריך-אלטונא","b":"רופא ופרנס באלטונא, פעל נגד הריפורמים, מקורב לר יעקב עטלינגר, פעל למען זכויות היהודים בשלזויג-הולשטין-תרא, יחד עם חברו ד\"ר גבריאל ריסער. בסוף ימיו עבר לראם, ציריך. חיבר \"דיע אפפענבארונג..\" בלשון אשכנז, ועוד."},{"i":52915,"n":"שטינהרט, אריה ליב מירושלים","f":"מרדכי","k":"בעל כור זהב","bp":"בראדשין","b":"מחכמי קאליש, עלה לירושלים."},{"i":52916,"n":"שטינהרט, חיים מזלישטשיק","b":"מחכמי זלישטשיק - תשובה אליו בטוט\"ד."},{"i":52917,"n":"שטינהרט, יוסף מאלזס","f":"מנחם","k":"בעל זכרון יוסף","bt":"תפ","dt":"תקלו - כ אב","b":"תלמיד ר יעקב פופרש מפפד\"מ. חתן ר ליב ברלין-מוכיח מפרשבורג וגיסו של ר ישעיה ברלין שנשא ונתן עמו בספרו \"זכרון יוסף\". מגדולי חכמי דורו, מרביץ תורה, רב מדינת עלזס בריקסהיים, נידרהיים-תקיג, שטרסבורג, פיורדא-תקכג. היה מתומכי ר ישראל ליפשיץ שערך את הגט מקליווא-תקכו. חתנו - ר איצק פפלצבורג בעל \"באר יעקב\" הביא מחדושיו בספרו. מחותן עם ר ישראל איסר אולמן מפיורדא."},{"i":52918,"n":"שטינהרט, יוסף מירושלים","dt":"תרכ - טז ניסן","b":"מגדולי חכמי ירושלים"},{"i":52919,"n":"שטינהרט, יוסף מקראקא","b":"נכד ר יוסף מפיורדא. מחכמי קראקא. חסיד צורטקוב. נספה בשואה. מתלמידיו ר חיים אלעזר הורביץ (חתן רמ\"מ אלתר מפביאניץ), ור שלמה גולינסקי מטבריה."},{"i":52920,"n":"שטינהרט, יעקב מאראד","b":"רב ניאולוגי באראד, יחד עם אהרן חארינער-אח\"ר, ועל מקומו אחריו, וד\"ר אלכסנדר רוזנברג על מקומו אחריו. יועץ הברון יוסף אטבאש (שיזם את האמנסיפציה ליהודים בהונגריה) לעניני יהודים. חיבר \"תכנית הלימודים בסמינר לרבנים\". עורך עתון יהודי בהונגרית \"הירנוק\" - פרשבורג תרג."},{"i":52921,"n":"שטינהרט, מנחם מנדל ממינדן","f":"שמעון מהיגספורט","k":"בעל דברי מנחם","b":"תלמיד דודו ר יוסף שטינהרט, הנודע ביהודה, ר ליב פישלס מפרג. חברו של ר בצלאל רנשבורג. מחכמי מינדן-פלך המבורג."},{"i":52922,"n":"שטינהרט, מרדכי מקלוש","b":"מחכמי קלוש-תרכט."},{"i":52923,"n":"שטינהרט, משה","f":"יוסף - זכרון יוסף","b":"בנו - ר עקיבא-תלמיד החת\"ס."},{"i":52924,"n":"שטינהרט, עקיבא מאלשא-קובין","f":"משה יעקב ולא יוסף","bt":"תקמח","dt":"תרו - ג שבט","b":"נכד ר ישראל איסר אולמן מפיורדא. תלמיד החת\"ס, ותלמיד זקנו ר יוסף שטיינהרט מפיורדא, ודודו ר שלום אולמן מלקנבך. חתן דודו ר משה אולמן מליפטא-סנט מיקלאש ועבר לשם. רב באלשא-קובין-תקעד. הו\"ל ספר זקנו ר יוסף \"משביר בר\"."},{"i":52925,"n":"שטינהרץ, שבתי מפרשבורג","bt":"תרז","dt":"תרפד - יד חשון","dp":"פרשבורג","b":"תלמיד הכת\"ס, רב בקעטשקעמעט-תרמב, פרשבורג0תרעג."},{"i":52926,"n":"שטינוורצל, משה דוד מוינה","f":"אלעזר","k":"בעל וידבר דוד","bt":"תרצד","bp":"וינה","dt":"תשנב","b":"עבר בגיל 6 לארה\"ב ולמד בישיבת מהרש\"ק. תלמיד ר ראובן גרוזובסקי ור גדליה שור. רב ור\"מ בניו יורק. ראש ישיבת בובוב-תרך. חתנו - האדמור מסטולין-קרלין. חיבר \"וידבר דוד\" ניו יורק תשנב. בנו ר אברהם חיים על מקומו אחריו."},{"i":52927,"n":"שטינזלץ, יצחק מוארשא","b":"מראשי בית החסידים דברסלב \"בית אמונה\" ברחוב גזשיבוב-וארשא."},{"i":52928,"n":"שטינזלץ, שלמה מוארשא","b":"מדפיס בוארשא - תרצז. הדפיס כתב עת \"אוצר החיים\"."},{"i":52929,"n":"שטיניץ, חיים מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":52930,"n":"שטיניץ, יחזקאל מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":52931,"n":"שטינמן אליעזר","bt":"1892","dt":"ה'תשל 1970","bk":[["גן החסידות",""],["ילקוט משלים, סיפורים, אמרי חכמה",""],["רבי ישראל בעל שם טוב",""]]},{"i":52932,"n":"שטינמן, אברהם משה מקלעוואן","f":"אריה יהודה","bt":"תרטו","b":"נסמך מאת: ר יוסף דב סולוביציק, ר יהושע מקוטנא, ר חיים אליעזר ואקס מקאליש, ר מאיר יונה מסוסלוביץ, ר יוסף מסלונים וטלז, ר מרדכי וייצל מסלונים. רב בקלעוואן-ווהלין. חיבר ספר על שמות אנשים ונשים - בכת\"י."},{"i":52933,"n":"שטינמן, אהרן ליב מבני ברק","f":"נח"},{"i":52934,"n":"שטינמן, נח","b":"בנו - ר אהרן ליב מבני ברק."},{"i":52935,"n":"שטינמן, צבי מסמרגון","b":"ר\"מ בסמרגון-תרנ\"ה,רב בניזנינובגורוד-תרס\"ה,רב ביבנאל-תרפ\"ה,רחובות"},{"i":52936,"n":"שטינמץ, אשר רובין מברגסאס","f":"חיים","k":"בעל מקוה ישראל ה-תשג","bp":"טעטש","dt":"תשד- כה אייר","dp":"אושוויץ","b":"נכד ר אשר ישעיה רובין מרופשיץ וקרא לעצמו גם בשם רובין. חתן ר ישראל פריינד מרודנא, ועבר לשם וכיהן כדיין ברודנא. רב וראש ישיבה ברודנא-תרץ על מקום חותנו שעבר להוניאד. נחשב למומחה בדיני ממונות והוזמן לשמש בורר ואב\"ד בדיני תורה מסובכים. רב הקהילה החסידית בברגסאס-תרצח וראש ישיבה. נספה בשואה. חתנו ר ישראל ניימן מירושלים."},{"i":52937,"n":"שטינמץ, דוד מטימישואר","b":"חתן ר מנשה גולדברגר מסטרופקוב, ועבר לשם. עבר להרמאנשטדט, דיין בטימישואר(=פאבריקשטדט). לא ידוע גורלו בשואה."},{"i":52938,"n":"שטינמץ, חיים ממיהלוביץ","f":"נחמן מדעש","k":"אדמור ממיהלוביץ","b":"חתן ר נפתלי מוישניצא. אדמור במיהלוביץ."},{"i":52939,"n":"שטינמץ, יעקב דב מטיטשין","b":"מחכמי טיטשין-תרסא, מתורתו ב\"ועד חכמים\" ועוד."},{"i":52940,"n":"שטינפלד, אברהם אליהו מבויד","b":"שו\"ב בבויד-ליטא ושימש גם כרב לא רשמי."},{"i":52941,"n":"שטינפלד, זאב וולף","b":"מגיד בלודז-תר\"ס. חתנו - ר פתחיה מנקין מסיינה."},{"i":52942,"n":"שטינפלד, זאב וולף מאושפיצין","f":"שמעון דב","bt":"תרסז","bp":"אושפיצין","dt":"תש..","b":"חתן ר יעקב משה קלויזנר מקרניץ, ועבר אליו. נספה בשואה. מתורתו ותולדותיו - כר\"ש-תשלט."},{"i":52943,"n":"שטינפלד, זאב וולף מיורבורג","b":"רב ביורבורג-תרלט תחת ר משה לוינזון."},{"i":52944,"n":"שטינפלד, זיסל מרמיגולה","dt":"תש..","b":"רבה האחרון של רמיגולה. נספה בשואה."},{"i":52945,"n":"שטינפלד, תנחום","dt":"תשג","b":"רב ברעמיגאלע"},{"i":52946,"n":"שטינפרס, שמחה מאוסטרופולי","f":"אברהם יצחק","k":"בעל ארגמן","bt":"תקפו","b":"רב באסטרופולי-ווהלין-תרלב. חיבר \"ארגמן\", \"נר מצוה\", ועוד."},{"i":52947,"n":"שטינקל, ראובן בן ציון מברוד","f":"מרדכי","b":"רב בברודי-תקץ."},{"i":52948,"n":"שטינר יעקב יששכר בן סיני","bt":"1806","dt":"ה'תקפט 1829","bk":[["שושנת יעקב",""]]},{"i":52949,"n":"שטינר, אברהם אהרן מפרשבורג","b":"חתן ר יצחק קרויס מראב. מחכמי פרשבורג. תלמיד הדעת סופר, ור שמואל דוד אונגרמ נייטרא. חתן ר יקותיאל דב גבירץ מטעט."},{"i":52950,"n":"שטינר, אברהם מגרוסורדין","f":"יצחק איזיק מסעמניץ","k":"בעל בית אברהם-תרצב","bt":"תרל","bp":"סעמניץ","dt":"תרצא-ט -יט ניסן","dp":"גרוסורדין","b":"תלמיד השב\"ס, ור יהודה גרינולד בבניהאד, ור יעקב קופל רייך מבודפשט. חתן ר פרץ בלוי מבודפשט ועבר לשם. רב בגרוסורדין-תרסו ב\"חברה ש\"ס\". בנו ר יצחק איזיק רב בגרוסורדין. ?? לא באוצר ??"},{"i":52951,"n":"שטינר, אברהם מקרסטיר","f":"ישעיה מקרסטיר","k":"אדמור מקרסטיר","bt":"תרמג","dt":"תרפז - יח אד\"א","b":"חתן ר מיכאל מזשירק. אדמו\"ר בקרסטור(=קרסטיר) על מקום אביו. חתנו ר יוסף מאיר רובין על מקומו אחריו."},{"i":52952,"n":"שטינר, אליהו מפרמישלא","b":"רב בפרמישלא. חסיד ר ברוך הלברשטם מגורליץ, ובעל החזקה לאגוד לרבו את ארבעת המינים."},{"i":52953,"n":"שטינר, בנימין חיים ממונט קיסקא","f":"אברהם אהרן מפרשבורג","k":"בעל בירורי השיטות","b":"ר\"מ בישיבת נייטרא במאנט קיסקא. חיבר גם \"שבח נעורים\"."},{"i":52954,"n":"שטינר, דוד","b":"תלמיד ישיבת יעמרינג. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":52955,"n":"שטינר, דוד אהרן מגרוסורדין","k":"בעל פרדס הגדה-תרפח","b":"מחכמי גרוסורדין. נספה בשואה. חיבר גם \"מוסיף חיים\" - בכת\"י. ?? לא באוצר ??"},{"i":52956,"n":"שטינר, הלל","dt":"תשד","b":"רב באילק"},{"i":52957,"n":"שטינר, הרמן מצכוסלובקיה","b":"משנה לר קלמן ובר-ראש הלשכה המרכזית לאורטודוכסים בצכוסלובקיה החדשה."},{"i":52958,"n":"שטינר, וילהלם זאב מפרשבורג","b":"עורך העתון הציוני \"פרעסבורגר יידישע צייטונג\" - בגרמנית -פרשבורג-תרסח."},{"i":52959,"n":"שטינר, יוסף אליהו מניו יורק","k":"בעל אבני שיש","b":"רב בוינה, ק\"ק \"עדת ירמים וינה\" בניו יורק."},{"i":52960,"n":"שטינר, יוסף מכפר סטרימבא","b":"דיין בכפר סטרימבא-ליד נאסוד - תרס עד לפני מלחמת העולם ה-I. נזכר בשו\"ת מהרש\"ם."},{"i":52961,"n":"שטינר, יעקב ישכר מאולינוב","f":"סיני מאולינוב","k":"בעל שושנת יעקב","bt":"תקסו","bp":"אולינוב","dt":"תקפח","b":"חיבר \"שושנת יעקב\" פרמישלא תרמב - יצא לאור ע\"י אחיינו ר אלימלך גרונר מרישא."},{"i":52962,"n":"שטינר, יעקב מגאלאנטא","f":"יהושע מגלנטא","b":"בנו של גביר מגלנטא שנשלח לפרשבורג ללמוד אצל החת\"ס."},{"i":52963,"n":"שטינר, יצחק איזק מגרוסורדין","f":"אברהם מגרוסורדין","k":"בעל מאה שערים-תשב","bt":"תרס - בערך","bp":"בודפשט","b":"רב ומגיד בגרוסורדין. נספה בשואה."},{"i":52964,"n":"שטינר, יצחק מקרסטיר","dt":"תשד - כג סיון","dp":"אושוויץ","b":"תלמיד ר חיים הלוי פלנר בבעלעד, ובנו ר יואל פלנר. ראש ישיבה ביעמרינג יחד עם ר אברהם יעקב סופר, רב ביעמרינג-תרעג על מקום ר אברהם יעקב סופר שעבר לטעט. הקפיד על שיטת אשכנז ורבים מתלמידיו שהיו חסידים - חגרו אבנטים מתחת למעיל מפאת כבוד רבם. נספה בשואה."},{"i":52965,"n":"שטינר, ישעיה מקרסטיר","f":"משה","k":"אדמור מקרסטיר","bt":"תריב","dt":"תרפה - ג אייר","b":"תלמיד ר צבי הירש האדמור מליסקא, והדברי חיים מצאנז. רב ואדמור בקרעסטיר(=בודרוג קרסטור) על מקום רבו האדמור מליסקא (שבחר בו ולא בבנו כיורשו - וכדי למנוע מחלוקת עבר לקרסטור). מפורסם כבעל מופת. חיבר \"חזון ישעיה\"."},{"i":52966,"n":"שטינר, משה מאיר הכהן","f":"פנחס שטיינר","b":"רב באילאק-תרע\"ג"},{"i":52967,"n":"שטינר, סיני מאולינוב","k":"בעל הר סיני","dt":"תרט","b":"גביר מחכמי אולינוב. נידון למות וניצל. התגורר בודוביצה שם היו עסקיו. עבר לפודגורזע. חיבר \"הר סיני\" פרזעמישל תרמג."},{"i":52968,"n":"שטינר, פנחס הכהן מאילאק","f":"יעקב מפאקש","k":"בעל בריתי שלום","bt":"תרה","bp":"פאקש","dt":"תרעג - יט כסלו","dp":"אילאק","b":"תלמיד הכת\"ס, ור אברהם צבי אבלס משארבאגרד. חתן ר מרדכי קליש מדעאקי. רב בבניהאד-תרלח, פאקש-תרם, אילאק-תרן ובנו ר יוסף מאיר משה על מקומו אחריו. חתנו - ר מרדכי אליעזר עהרענגריבער מפאפא. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":52969,"n":"שטינר, צבי הירש מפרמישלא","b":"ממשתתפי \"אהל מועד\"."},{"i":52970,"n":"שטינר, שלמה מפרשבורג","bp":"פרשבורג","dt":"תשד","dp":"אושוויץ","b":"עורך דין ובקי בשפות, מראשי ה\"מזרחי\" בפרשבורג. נספה בשואה."},{"i":52971,"n":"שטינשנידר משה","bt":"1816","dt":"ה'תרסז 1907","bk":[["משל ומליצה",""],["שני המאורות",""]]},{"i":52972,"n":"שטינשנידר, דניאל פרוסטיץ","f":"איסר פרוסטיץ","k":"בעל דן מדניאל","r":"ראב\"ד פרשבורג","dt":"ו אדר תרו","b":"נד ר דניאל פרוסטיץ מפרשבורג. דרשן, מגיד בפרשבורג-תרמ.","bk":[["מחנה דן - פסחים",""]]},{"i":52973,"n":"שטינשנידר, מיכאל"},{"i":52974,"n":"שטיער, יוסף ממיעלץ","b":"מחכמי מיעלץ. בנו ר אלימלך מנהיג צא\"י."},{"i":52975,"n":"שטיפל, דב בריש מקנטשוגה","dt":"תש..","b":"חתן ר הרשלה פרידמן משיניבה וצשינוב. דיין בקנטשוגה. נספה בשואה."},{"i":52976,"n":"שטיפל, מיכל דוד ממערעטש","f":"יוחנן","k":"בעל באר מים חיים","bt":"תרכה","dt":"תשא","b":"רב בוויסאל(=ווסאלי)-יקטרינסלב-תרנו, שדה לבן, רבה האחרון של מאראטש(=מיריטש, מערעטש)-פלך וילנא. נספה בשואה."},{"i":52977,"n":"שטיקלר, אליהו ממוסט","f":"שמאיה ממוסט","b":"חתן ר משה איזיק. שו\"ב בבלז, בניו ר שמריהו ור מרדכי על מקומו אחריו."},{"i":52978,"n":"שטיקלר, אריה ליבוש מקוליקוב","f":"צבי הירש ממוסט","bt":"תרל","dt":"תרעו - יד שבט","dp":"זנישוענוע","b":"חתן ר נתן הלוי רוזנפלד מקוליקוב. רב בקוליקוב על מקום חותנו (לאחר מחלוקת עם גיסו ר יחיאל מיכל רוזנפלד)."},{"i":52979,"n":"שטיקלר, חיים יהושע ממוסט","f":"שמריה ממוסט","bt":"תרב","dt":"תרפב","b":"חתן אחיו ר צבי הירש. רב במוסט לצד ר יחיאל דב מונד. (היה מעורב במחלוקת צאנז סדיגורא)."},{"i":52980,"n":"שטיקלר, צבי הירש","f":"שמריה מקמינקא","b":"תלמיד החוזה מלובלין. חתן ר אליהו מזולקוא, ועבר אליו."},{"i":52981,"n":"שטיקלר, צבי הירש מלמברג","f":"אריה ליבוש מקוליקוב","b":"רב בלמברג."},{"i":52982,"n":"שטיקלר, צבי הירש ממוסט","f":"שמריה ממוסט","bt":"תרג","dt":"תרלג","b":"חתן ר דב בריש פלם מאלסק. רב במוסט על מקום אביו."},{"i":52983,"n":"שטיקלר, שמריה מקמינקא","b":"תלמיד הנועם אלימלך, וידידו של החוזה מלובלין שהסמיכו להיות רבי."},{"i":52984,"n":"שטיקלר, שמריהו ממוסט","f":"צבי הירש מקמינקא","bt":"תקנב או תקנה","bp":"זולקוא","dt":"תרלב - יב תשרי","b":"תלמיד ר אורי מסטרליסק, ר צבי הירש מזידיטשוב, השר שלום מבלז, ר יוזפא שטרן וסידר את ספרו \"יד יוסף\" לדפוס. רב במוסט-תקצב. רבם של בעל \"מפרשי הים\" ור צבי הירש אורנשטין מלבוב. מכתביו נדפס \"שם משמריה\" ירושלים תשכח - ע\"י נכדו ר אברהם בן פזי."},{"i":52985,"n":"שטיקלר, שמריהו מקמינקא","dt":"כג אלול","b":"תלמיד ר אלימלך מליזנסק, חברו של החוזה מלובלין שביקרו בביתו וסמכו לאדמורות. בנו ר צבי הירש, ונכדו ר שמריהו אב\"ד מאסט גדול."},{"i":52986,"n":"שטלס, שמעון","b":"רב בפפד\"מ-ש\"מ"},{"i":52987,"n":"שטלפר, צבי הירש","b":"תלמיד ר יצחק הורביץ מזורובנא המזכירו בספרו \"תולדות יצחק\"."},{"i":52988,"n":"שטלצר, מאיר הלוי מסוירז","b":"רב בסוירז, נבריה-תרלה."},{"i":52989,"n":"שטמלפר, צבי הירש בר מסטוינוב","f":"ראה: בנבנשת די שיגוב","b":"רב בסטוינוב-תרנו, בנו ר יצחק על מקומו אחריו ונספה בשואה."},{"i":52990,"n":"שטמלק, יחזקאל","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":52991,"n":"שטמפי, מאיר מפרשבורג","f":"געצל","dt":"תסז - ג כסלו","dp":"פרשבורג","b":"מחכמי פרשבורג."},{"i":52992,"n":"שטמפלר, ברל מקולומיאה","b":"מחכמי קולומיאה - תשובה אליו ב\"פרי השדה\"."},{"i":52993,"n":"שטמפר, אברהם מירושלים","f":"בנימין","bp":"ירושלים"},{"i":52994,"n":"שטמפר, יהושע משטיינמנגר","f":"בנימין מסומבוטהי","dt":"תרסח - ה סיון","b":"הגיע משאר-בוגארד. תלמיד ר עזריאל הילדסהימר בברלין, עבר אל דודו ר אלעזר ראב - שהיה מקורב לרבנים קאלישר וגוטמכר, ובהשפעתם עלה לארץ - ברגל. למד בישיבה בירושלים. התחבר אל ר יואל משה סלומון ור דוד גוטמן והיו מייסדי פתח תקוה."},{"i":52995,"n":"שטמפר, שלמה מפתח תקוה","b":"רב וראש העיר הראשון בפתח תקוה."},{"i":52996,"n":"שטן-שטיין, יוסף הרופא מסופיה","b":"מחכמי אשכנז, לאחר הגירוש-רל הגיע לסופיה-בולגריה."},{"i":52997,"n":"שטנגן, יואל פיבוש","b":"רב-שנת ש\"כ"},{"i":52998,"n":"שטנד, ישראל אלימלך מלמברג","b":"תלמיד ר יוסף שאול נתנזון בעל השו\"מ שהזכירו בספרו-תרטז."},{"i":52999,"n":"שטנד, מאיר","b":"תשובה אליו ב\"אהל משה\"."},{"i":53000,"n":"שטנדרובסקי, יהודה משה מדוואהרט","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":53001,"n":"שטנמן, יוסף מטשטשביץ","b":"רב בטשעטשעוויץ-ת\"ר"},{"i":53002,"n":"שטנצל, יונה מסוסנוביץ.","bt":"תרסד","dt":"תשכט - יט תמוז","b":"תלמיד ישיבת חכמי לובלין. עלה לארץ, רב בתל אביב, הפיץ תכנית משנה יומית והלכה יומית לזכר קדושי השואה."},{"i":53003,"n":"שטנצל, יוסף מסוסנוביץ","b":"מו\"ץ בסוסנוביץ. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":53004,"n":"שטסל, משה אהרן","b":"מג\"מ באגראם-תר\"ל"},{"i":53005,"n":"שטעלא, יוסף מפרשבורג","f":"אברהם","k":"בעל תוצאות חיים","b":"רופא בפרשבורג-תעג - בזמן המגפה שהפילה מעל 400 חללים יהודים. חיבר ספר רפואה בשם \"תוצאות חיים\"."},{"i":53006,"n":"שטעמפעווער, מאיר מוילנא","f":"אריה","b":"מחכמי בימ\"ד על שם הגר\"א, והיה ממיסדי הישיבה שם, יחד עם חבריו ר ברוך חייט, ור יהושע חייט."},{"i":53007,"n":"שטערנן, מנדל מפפד\"מ","b":"מחכמי פפד\"מ-תע, נזכר בתשובות חכמי דורו אודות היתר שנתן לעשות קידושין על תנאי במקרה מיוחד."},{"i":53008,"n":"שטצר, שמואל","b":"תשובה אליו בשו\"מ."},{"i":53009,"n":"שטקטשינר, אלתר","b":"פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":53010,"n":"שטראה, מאיר מפרשבורג","b":"תלמיד החת\"ס. חתן ר דניאל פרוסטיץ-שטינשנידר מפרשבורג. רשם את חדושי רבו בכת\"י ומהם נדפסו."},{"i":53011,"n":"שטרויזנברג, מרדכי מיברוב","b":"דיין ביברוב-תרכב."},{"i":53012,"n":"שטרוים, פתחיה יוסף מקשאנוב","b":"מחכמי קשאנוב. התכתב עם ר שלמה מזוז בזרבה עורך מקבציאל-תרצט."},{"i":53013,"n":"שטרויס, אברהם הלוי מפישפיקלדנ","b":"חתן ר יוסף יוזפא רוזנברג מפישפיקלאדני, רב בפישפיקלאדני על מקום חותנו. חתנו - ר דוד שיק מנעמעש-סאלוק. (במקום אחר בספר \"החת\"ס ותלמידיו\" מופיע כחתן ר מנחם צבי רוזנבורג מבלאש-ירמוט - אביו של ר יוסף יוזפא)"},{"i":53014,"n":"שטרויס, אברהם מארה\"ב","f":"מנחם","b":"מחכמי בולטימור. נספד מאת ישראל פיין בספרו \"נגינות בן יהודה\" תרסז. אחיו - אליעזר."},{"i":53015,"n":"שטרויס, אברהם מטיטשין","b":"רב בטיקשין-טיקטין. אחיו של ר מאיר מחירוב. אביו של ר חיים יעקב שטרום-קנר מדוקלא."},{"i":53016,"n":"שטרויס, אוסקר מניו יורק","bt":"1859","bp":"בווריה","b":"היגר לארה\"ב ולמד משפטים. ציר ארה\"ב בתורכיה. ציר הנשיא רוזוולט באסיפת השלום בהאג."},{"i":53017,"n":"שטרויס, אליעזר מניישטאט","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":53018,"n":"שטרויס, אשר אלימלך","b":"פרסם מאמרים ב\"המאור\" - ברלין תרצג."},{"i":53019,"n":"שטרויס, דוד כץ מפיורדא","bt":"תמא","bp":"פפד\"מ","dt":"תקכג - כח אייר","b":"חתן ר נתן בן מרדכי אדלר. מגדולי חכמי דורו, רב בהעלישוי(=הולעשאו)-תעד, דיין בפפד\"מ-תפב, רב בוורמייזא-תקג, פיורדא-תקח. חתנו - ר נתן בן מרדכי אדלר מפפד\"מ."},{"i":53020,"n":"שטרויס, מאדל מקרייצנבך","f":"דוד שטרויס","dt":"תקלג","b":"רב בקרייצנבך"},{"i":53021,"n":"שטרויס, מאיר","b":"רב בחירוב"},{"i":53022,"n":"שטרויס, מנחם מנדל מפרשבורג","bt":"תקצה","dt":"תרפה - כו חשון","dp":"פרשבורג","b":"תלמיד הכת\"ס. מחכמי פרשבורג."},{"i":53023,"n":"שטרויס, משה גד מקאפוש","b":"חסיד ר יהושע פריד האדמור מקאפיש, מתושבי כפר בעש, עבר לקאפיש(=קאפוש)."},{"i":53024,"n":"שטרויס, נתן מירושלים","b":"גביר מחכמי ירושלים-תרע, גבאי ביה\"ח ביקור חולים."},{"i":53025,"n":"שטרויס, שלמה סגל","b":"רב בשומאדי,באיאם-תר\"י"},{"i":53026,"n":"שטרויס, שמואל","f":"דוד שטרויס","dt":"תקלב","b":"דומ\"צ בפיורדא"},{"i":53027,"n":"שטרויס, שמואל","b":"רב בדינוב-תק\"ס"},{"i":53028,"n":"שטרויס, שמואל מפרשבורג","f":"גבריאל הכהן ממפדמ","bt":"תקנו","b":"אמו היתה אחות החת\"ס, ולאחר שנתייתם מאמו גדל אצל החת\"ס. מחכמי פרשבורג, פפדמ-תרח."},{"i":53029,"n":"שטרולי, יהודה מבאנפי הוניאד","f":"משה מפילד","b":"תלמיד הכת\"ס. מחכמי באנפי-הוניאד. תשובה אליו ב\"כתב סופר\"."},{"i":53030,"n":"שטרולי, יחיאל מכפר פילד","f":"משה מפילד","k":"בעל אמונת אומן-תרצה","bp":"כפר פילד-ליד הוניאד","dt":"תרצב","b":"תלמיד הכת\"ס. מחכמי כפר פילד ועסק בחקלאות, עסק בתורה ונודע כצדיק. בנו ר משה חיים מסיגט הו\"ל את ספרו \"אמונת אומן\" סיגט תרצה."},{"i":53031,"n":"שטרולי, משה חיים מבאניא","f":"פרץ טוביה מקלויזנבור","dt":"תשד - סיון","b":"חתן ר משה ישראל פלדמן מדראגמירשט וברעזן-ממשפחת המהרש\"ם מברעזן. רב בבאיא-ספריע, פעלשא באניא-תרף-תרץ בערך. עסק בהכנה לדפוס של כתבי המהרש\"ם-קרובו מצד אשתו. נספה בשואה."},{"i":53032,"n":"שטרולי, פנחס מקלויזנבורג","dt":"תש..","b":"חתן ר שלמה זלמן ליכטנשטין מבעטלען. דיין בדיטשא סט מארטון, דיין בקלויזנבורג. נספה בשואה."},{"i":53033,"n":"שטרולי, פרץ טוביה מקלויזנבורג","b":"רב ומגיד בקלויזנבורג. נספה בשואה. חתנו ר יעקב שמריהו דייטש רב \"חוג חתם סופר\" בפתח תקוה."},{"i":53034,"n":"שטרום, אשר מטרנוב","b":"מחכמי טרנוב-תרכב."},{"i":53035,"n":"שטרום, ברוך מדזיקוב","b":"מחכמי דזיקוב - תשובה אליו ב\"דבר משה\"."},{"i":53036,"n":"שטרום, יעקב משטרים וירושלים","f":"יוסף שטרים","b":"מקובל בשטרים,עלה לירושלים-ת\"ס"},{"i":53037,"n":"שטרום, צבי יהודה מטורנא","b":"מחכמי טורנא-תרץ."},{"i":53038,"n":"שטרום-קנר, חיים יעקב מדוקלא","f":"אברהם או אריה ליב","k":"?","dt":"תקעג - יז אד\"א","b":"בנו או נכדו של ר אברהם קנר מרימנוב. מצאצאי הט\"ז. רב בדוקלא-תקם. גיסו של המגיד מקוזניץ. תלמיד הנועם אלימלך ור מנחם מנדל מרימנוב. מחותן עם ה\"אוהב ישראל\". חתניו: ר יצחק מאיר מאפטא וזינקוב, ר מרדכי הושע מדוקלא, ר פנחס מסטבניץ, ר מרדכי מהרניספלי."},{"i":53039,"n":"שטרומלויפר, דוד אלימלך הכהן כץ","dt":"תרצו - בערך","b":"חסיד צאנז, רב בדינוב כיובל שנים. רוב כתביו אבדו. ממשתתפי \"אהל מועד\"."},{"i":53040,"n":"שטרוסמן, משה מליפובה","b":"רבה הראשון של הקהילה הניאולוגית בליפובה."},{"i":53041,"n":"שטרוק, שלמה מיכאל","f":"אליעזר שטרוק","k":"בעל וזאת ליהודה","bt":"תקנו","dt":"תרלא - טז טבת","b":"דיין בארנסוולד, רב באויבר-זיצקא-תרי, לייפציג."},{"i":53042,"n":"שטריזנד, דב ברל מברזן","b":"מחכמי ברזן - תשובה אליו ב\"קנאת סופרים\"."},{"i":53043,"n":"שטריזנד, נחום מפוזנא וארה\"ב","k":"בעל ללמד תועים בינה","bt":"תקעט","bp":"פוזנא","b":"תלמיד ר עקיבא איגר. חתן ר יעקב ליויער מואנגרוויטץ - חתנו של ר אברהם איגר בן ר עקיבא מפוזנא. רב במעזריטץ, פארדאן-מחוז פוזנא, היגר לארה\"ב-תרכט וכיהן כרב \"שערי צדק\" בניו יורק. רב בסן פרנציסקו. חיבר \"תועים בינה\" כנגד הרפורמים - ניו יורק תרלב. הו\"ל הגהות ר עקיבא איגר - טהארן תרכט."},{"i":53044,"n":"שטרייט, דוד","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":53045,"n":"שטרייך, בריש","b":"רב בניימרקס-תר\"ע"},{"i":53046,"n":"שטריכמן, יחזקאל","f":"יצחק","bt":"1906","bp":"ספיזישוק","b":"עלה לארץ ולמד ב\"בצלאל\" ואח\"כ בפאריס ובפלורנץ. יסד עם הצייר א. סטימצקי בי\"ס לאמנות בתל אביב. צייר מפורסם."},{"i":53047,"n":"שטרימר, יוסף מפרג","b":"מחכמי פרג-ת\"כ"},{"i":53048,"n":"שטרימר, יעקב מירושלים","f":"יוסף","bt":"שפ - בערך","bp":"קאליש או פרג","dt":"תמו או תלח","dp":"ירושלים","b":"אחיו של ר שבתי משורר בס בעל \"שפתי ישנים\", היה זמן בפרג ואחר כך הגיע למצרים ורב באדרינופול-תך, בין תלמידיו ר אליעזר בן יעקב נחום אב\"ד אדרינופול ולימים \"ראשון לציון\" ובעל \"חזון נחום\". עלה לירושלים בשנת תא ונתמנה ל\"ראשון לציון\". מתומכיו ש\"ץ באדרינופול."},{"i":53049,"n":"שטריקר, שמואל צבי מעיר חדש","f":"אברהם מעיר חדש","bp":"עיר חדש","dp":"עיר חדש","b":"תלמיד הכת\"ס. חתן ר ברוך בנדיט ליכטנשטין מוועטש. רב בבעצקא, ודיין בעיר חדש למעלה מששים שנה."},{"i":53050,"n":"שטרית, דוד ממרוקו","b":"מחכמי מרוקו-שנות ה-ת', שאלה ממנו לר מנחם סירירו שחי בשנות ה-ת'."},{"i":53051,"n":"שטרית, דוד מצפרו-מרוקו","b":"תלמיד ר משה ן חמו. מו\"ץ בצפרו עם ר ישועה ן חמו. נזכר ב\"משפט וצבי\"."},{"i":53052,"n":"שטרית, חיים אליהו אברהם מצפרו","k":"בעל מלל לאברהם","dt":"תרסא - ז אלול","dp":"צפרו","b":"מחכמי צפרו-מרוקו, נסע לפאס וחלה במגיפה,חיבר \"מלל לאברהם\"."},{"i":53053,"n":"שטרית, חיים מאריף-מרוקו","b":"מחכמי אריף-מרוקו-תעח, מכתב אליו מהיעב\"ץ ור אברהם ן דנאן."},{"i":53054,"n":"שטרית, חיים מירקאדו","b":"מחכמי מרוקו-תרל בערך (נתן ספר במתנה עם הקדשה לשד\"ר ר אברהם חיים שבאבו)."},{"i":53055,"n":"שטרית, יהודה ממכנאס","b":"מחכמי מכנאס-תקעט."},{"i":53056,"n":"שטרית, יוסף ממכנאס","f":"מכלוף","b":"מחכמי מכנאס."},{"i":53057,"n":"שטרית, יעקב ממרוקו","b":"רב בפאס-תרם."},{"i":53058,"n":"שטרית, יצחק ממרוקו","dp":"קזבלנקה","b":"מחכמי מרוקו."},{"i":53059,"n":"שטרית, מכלוף ממכנאס","f":"משה","b":"רב במכנאס-תקעז, חיבר שירים בכת\"י שאבדו. ותחנה לשאילת גשמים."},{"i":53060,"n":"שטרית, מכלוף ממכנאס","dt":"תפה","dp":"אגורא\"י (ליד מכנאס)","b":"תלמיד המשבי\"ר. מחכמי מכנאס, רב באגורא\"י (כפר קטן ליד מכנאס, והיתה בו קהלה יהודית בימים קדומים)."},{"i":53061,"n":"שטרית, מכלוף ממכנאס - הזקן","b":"מחכמי מכנאס - [בשנות ה-ת]."},{"i":53062,"n":"שטרית, מכלוף ממכנאס - הנכד","f":"יוסף בן מכלוף","b":"מלומד בנסים מחכמי מכנאס, חתם-תקכא עם חכמי מכנאס."},{"i":53063,"n":"שטרית, מכלוף ממרוקו וטבריה","bt":"תרכז","bp":"תפיללאת","dt":"תשא - ח אלול","dp":"טבריה","b":"עלה ממרוקו-תרמב יחידי לטבריה בגיל 14. רב ומקובל בטבריה, ואחד האחראים על קבלת התרומות לקהלה. מתשובותיו ב\"יש מאין\" לר אליהו ילוז. הניח חבורים בכת\"י."},{"i":53064,"n":"שטרית, מכלוף מתאפילאת","b":"מחכמי תאפילאלת, חתם על שאלה לחכמי פאס עם ר יחיא ן חיון."},{"i":53065,"n":"שטרית, מסעוד מאלגיר","bt":"תק","dt":"תקע - בערך","b":"רב בבליידא-אלגיר-תקך. ונזכר אצל ר יעקב ן נאיים ב\"זרע יעקב\"."},{"i":53066,"n":"שטרית, מסעוד מאריף","b":"מחכמי אריף-שנות הת', מראשי הקהלה עם אחיו - ר אברהם ועם ר יעקב תורגמן. מכתב אליו מהיעב\"ץ."},{"i":53067,"n":"שטרית, מרדכי ממרוקו","b":"מחכמי מרוקו-תקו, שאלה ממנו לחכמי מראקש."},{"i":53068,"n":"שטרית, שלום בכור","f":"מכלוף","bt":"תרנה","bp":"טבריה","b":"קצין משטרה, שופטר בתל אביב, חיפה."},{"i":53069,"n":"שטרית, שלמה ממרוקו","b":"רב במרוקו, חתם-תרעב עם ר מימון אבוחצירא."},{"i":53070,"n":"שטרמן, משה","bt":"תרכד","b":"ר\"מ בסובאלק, מרבני ניו יורק-תרס\"ג"},{"i":53071,"n":"שטרן שמואל טוביה","bt":"1920","dt":"ה'תשסד 2004","bk":[["חוקת עולם",""],["מאורי אור",""],["תורה והמסורה",""],["התורה והמסורה","כתב אשורי ניקוד וטעמים"],["תורת התמורה","על מסכת תמורה"],["הראיון זכרו לאברהם","על מסכת חגיגה"]]},{"i":53072,"n":"שטרן, אברהם","f":"יעקב","k":"בעל מזור ותרופה","b":"רופא, חכם וסופר. חיבר \"מזור ותרופה\" - ברלין תקעז."},{"i":53073,"n":"שטרן, אברהם יהודה ליב משאק","f":"חיים","k":"בעל זכרון שמואל","bt":"תקפג","dt":"תרנו - כד סיון","dp":"שאק סעלעצע","b":"תלמיד הכת\"ס. חתן ר יעקב פונפדר משאלא ונייטרא. רב בשאק-סעלעצע-תרח."},{"i":53074,"n":"שטרן, אברהם יעקב מהרובשוב","f":"חנוך הניך","k":"בעל רנה ותפלה","bt":"תקכט","bp":"הרובשוב","dt":"תרב - כג שבט","dp":"וארשא","b":"בקי במדע, מתמטיקה, ממציא מכונת חישוב-1815. מקורב למלכות וסייע לבני עמו, פעל אצל הקיסר לאפשרות פדיון השירות בצבא בכסף, סייע להקמת ביהמ\"ד לרבנים בוארשא, עמד בראש הועדה-1825 לעניני החינוך היהודי. חיבר \"רנה ותפלה\" לכבוד הצאר ניקולאי הראשון. חתנו - ר חיים זליג סלונימסקי בעל \"תולדות השמים\"."},{"i":53075,"n":"שטרן, אברהם יצחק","f":"יונה מסאסרגן","k":"בעל ראשי תיבות-תרפו","dt":"תרפו - טז אייר","b":"פעיל ציוני רב באוי סט אנא-ליד אראד-תרס, רב בפאצ'אד-ליד טימישואר-תרעב. רב בסאס-וארוש-ליד דווה. וכל הקהלות הללו לא היו אורטודוכסיות. היו שהאשימוהו שספרו \"ראשי תיבות\" מבוסס על העתקת ספרו של ר מאיר הלפרין \"הנוטריקון הסמנים והכנויים\" וילנא תרסט - אך נפתלי בן מנחם העיד שר אברהם יצחק מעולם לא שמע על ספר זה (\"מספרות ישראל בהונגריה\")."},{"i":53076,"n":"שטרן, אברהם מטשאבא","dt":"תשד","b":"רב בטשאבא"},{"i":53077,"n":"שטרן, אברהם מנייהיזל","f":"יצחק יהודה ליב","k":"בעל מליצי אש","bt":"תרמד","bp":"פאפא","dt":"תשד - כו סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור משה יוסף הופמן מפאפא. חתן ר יוסף מאיר טיגרמן מנייהיזל ועבר לשם. רב בנייהיזל-תרע. נספה בשואה. חיבר \"כבוד שמים\", שלחן אש\" ועוד."},{"i":53078,"n":"שטרן, אברהם מפולין","f":"מאיר חיים","k":"בעל מזרחי מערבי","b":"מחכמי פולין-שנות ה-תק'. חיבר \"מזרחי\" - קיצור פירוש הרא\"ם, \"מערבי\" - הוספות על פירוש הרא\"ם."},{"i":53079,"n":"שטרן, אברהם מפפד\"מ ומורביה","dt":"תמה - יא תמוז","dp":"פפד\"מ","b":"רב בפפד\"מ, רב המדינה של מורביה. אחיו של ר מאיר מפולדא ואמשטרדם."},{"i":53080,"n":"שטרן, אברהם מקערסטעס","b":"שו\"ב בקערסטעס. נכדו(-בן בתו) ר יום טוב ברוין."},{"i":53081,"n":"שטרן, אברהם משה מסמבור","b":"רב בסמבור- פרימישלן-תרטז."},{"i":53082,"n":"שטרן, אברהם שמואל בנימין","f":"שלום דב בר מסערדאוהל","bt":"תרלד","bp":"סערדאוהל","dt":"תרץ - טז תמוז","dp":"בודפשט","b":"תלמיד השב\"ס. מחכמי בודפשט."},{"i":53083,"n":"שטרן, אהרן מסוכוסטוב","b":"רב בסוכוסטוב-תקפא (ליד קופיטשיניץ)."},{"i":53084,"n":"שטרן, אהרן מעיר חדש וניידארף","b":"דיין בעיר חדש-תקף, ניידארף."},{"i":53085,"n":"שטרן, אלימלך זאב","f":"טוביה ליב ממונקטש","k":"בעל שיחות יקרים-תרצח","bp":"סטמר","b":"חסיד אדמורי מונקטש. נספה בשואה."},{"i":53086,"n":"שטרן, אלתר","b":"תשובה אליו - \"פרי העץ\" ו\"מנחת יחיאל\" - תרעב."},{"i":53087,"n":"שטרן, אפרים מהאלמין","b":"מחכמי האלמין."},{"i":53088,"n":"שטרן, אשר אנשיל מאילאק","b":"גביר מחכמי אילאק. חתן ר משה מבאניהאד בעל \"ברכת משה\". סייע לבנו - ר יוסף נפתלי מסרעט-בוקובינה בהוצאת ספר זקנו \"ברכת משה\"."},{"i":53089,"n":"שטרן, אשר אנשיל מהמבורג","f":"מאיר","bt":"תקפ","bp":"שטינבאך","dt":"תרמח - כח אדר","dp":"המבורג","b":"תלמיד ר זקל ורמייזר בפולדא, ר ליב היילברון, ר יצחק דב במברגר. חתן ר נתן אדלר מלונדון. מלמד בוירצבורג בבית הברון יעקב הירש. אב\"ד בהמבורג-תריא על מקום ר יצחק ברנייס. נסמך מאת: ר אברהם וכסלר משוואבאך, ר יצחק דב במברגר מוירצבורג, ר קופל במברגר מוורמייזא. היה מחלוקת מצדו בענין בית הקברות החדש בהמבורג וחיבר על כך פסק דין ב\"דער אהלסדארפער בעגראבניספלאטץ..\", ועל כך נכתבו ספרים מצד מתנגדיו ומצד תומכיו ובהם - \"חסד ואמת\" כנגדו, \"צדק ומשפט\" להגנתו. בניו - ר נפתלי, מחתניו - ר מיכאל קאהן מפולדא."},{"i":53090,"n":"שטרן, בנימין מפרבעניק","b":"תלמיד החת\"ס. גביר ות\"ח בפרבעניק. השתתף מדי יום בשיעור בקהילת אויהל הסמוכה. בנו ר משה (ע\"ש החת\"ס) - רב בפאליאן-ריסקווא - וכותב בספרו כנראה בשם אביו ששמע מהחת\"ס שאין לישראל לחוג יום הולדתו - אלא יום שנכנס בברית.."},{"i":53091,"n":"שטרן, בצלאל מטרנופול","bt":"1829","bp":"טרנופול","dt":"1853","dp":"אודסה","b":"מנהל ביה\"ס באודסה על מקום זיטנפלד, יסד בי\"ס בקישינוב-תקפא. רשם את המצבות בבית העלמין הישן באודסה."},{"i":53092,"n":"שטרן, בצלאל ממלבורן וירושלים","f":"אברהם-מליצי אש","k":"בעל בצל החכמה-תשיט","r":"רב במלבורן","bt":"תרעא","bp":"נייהייזל","dt":"תשמט - כא חשון","dp":"ירושלים","b":"תלמיד הדעת סופר, ור יהושע בוקסבוים מגאלאנטא, ור שמואל דוד אונגר מנייטרא. חתן ר צבי קינסטליכר מסעבען(=הרמאנשטדט), ועבר לשם, רב בסעבען לצד חותנו-תרצה. ניצל מהשואה ואחריה רב בבודפשט-תשח, פאפא, ראש ישיבת \"מאור הגולה\" ברומא, עלה לירושלים-תשיא והתישב לצד חותנו, רב במלבורן-תשטז וראש ישיבת \"ברית אברהם\", וינה ובנו ר חיים שטרן על מקומו אחריו, ראש בימ\"ד \"אהבת ציון\" בירושלים. חיבר \"פרפראות למשנה\", ועוד. חתניו - ר שמחה בונם סופר מפרשבורג - ירושלים, ור אברהם יפה-שלזינגר אב\"ד גענף.","bk":[["בצל החכמה","שו\"ת - אחרונים"],["בצל החכמה – שו\"ת",""],["שו\"ת בצל החמה",""]]},{"i":53093,"n":"שטרן, גצל מבוצאץ","b":"מחכמי בוצאץ - תשובה אליו \"תועפות רא\"ם\"."},{"i":53094,"n":"שטרן, גרשון הכהן מבאטארקס","b":"גביר מחכמי באטארקס. חתנו - ר מרדכי בנט מאויבן ושטמפן."},{"i":53095,"n":"שטרן, גרשון ממארוש-לודאש","f":"משה","k":"בעל ילקוט הגרשוני","r":"אבד\"ק מאראש לודאש","bt":"תרכא","bp":"מאד-הונגריה","dt":"תרצו - טו אייר","b":"נכד ר אברהם חסיד מזעמפלין. תלמיד החתן סופר במטרסדורף, מהר\"ם שיק בחוסט, בעל \"קול אריה\" במאד, ר אברהם יהודה הכהן שורץ, תלמיד וחתן ר עמרם בלום באויפאלו. רבה הראשון וראש ישיבה במארוש-לודאש-תרמה למעלה מ-50 שנה. בזיוו\"ש חתן ר מרדכי יהודה פוקס. מגדולי הדרשנים והמחברים בטרנסילבניה. היה לעתים במחלוקת עם רבנים חסידיים בטרנסילבניה. ביקר בארץ-תרע וכתב על כך ב\"מסעי בני ישראל\". חיבר \"אבל כבד\" - פאקש תרמו - הספד על ר חיים סופר הכהן מפעסט. נסמך מאת: ר יואל אונגר מפאקש, ר מאיר פערלס מקרולי, ר אהרן צבי ממרגרטן.","bk":[["אבל כבד - הספד על ר' חיים סופר",""],["ברכת הנפש - ברכי נפשי וט\"ו שיר המעלות",""],["ילקוט הגרשוני - תנ\"ך ש\"ס ושו\"ע וכללים",""],["מסעי בני ישראל - מסע לארץ ישראל",""],["מקור דמעה - הספד על ר' הלל ליכטנשטין מקולמיא, ור' יצחק אהרן אטינגא אב\"ד למעברג",""],["מרבה ישיבה - מכתבים לחיזוק הישיבות",""],["מתוק לנפש - דרשות לחודש תשרי",""],["נחלת אבות - אבות (נדפס בתוך ספר ילקוט הגרשוני)",""],["פני המלך",""],["שערי מדע - הערות על שו\"ע יו\"ד (נדפס בתוך ספר מתוק לנפש)",""],["תפארת למשה - דרשה",""]]},{"i":53096,"n":"שטרן, דוד מפרקשד","dt":"תשד","b":"רב בפרקשד"},{"i":53097,"n":"שטרן, השל מואלי","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":53098,"n":"שטרן, זיסקינד מוינה ופפד\"מ","f":"זנויל","dt":"תקכד - ג כסלו","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ. פרנס ונציג קהילת פפד\"מ בוינה-תעח, יחד עם חברו ר עמנואל דראך. מתומכי ר יונתן איבשיץ בזמן המחלוקת כנגדו."},{"i":53099,"n":"שטרן, זיסקינד מפפד\"מ","f":"אברהם","b":"נאמן ושמש קהלת פפד\"מ-תקמב."},{"i":53100,"n":"שטרן, חיים מוינה","f":"בצלאל ממלבורן","b":"רב בוינה על מקום אביו"},{"i":53101,"n":"שטרן, חיים מסוקוליבקה","f":"משה אליהו הכהן","bt":"תרסא","bp":"סוקוליבקה","dt":"תשלז","b":"חתן ר זאב פרידלנדר מדברצין. גביר מחכמי בודפשט. בזמן השואה היה מראשי פעילי ההצלה - ובין פעולות עזרה לאדמורים מבלז וסטמר. עבר לארה\"ב והיה עסקן שהקים מוסדות וישיבות ונשיא מוסדות שונים."},{"i":53102,"n":"שטרן, חיים שמואל מסיגט","f":"יוסף מסיגט","bt":"תקף","bp":"סיגט","dt":"תרנג - י אלול","b":"רב בסיגט על מקום אביו, חסיד קוסוב ועמד בראש הקלויז החסידי בסיגט."},{"i":53103,"n":"שטרן, יהודה הכהן מבודפשט","f":"יו\"ט זוסמן מקיש-קערש","b":"רב בבודפשט."},{"i":53104,"n":"שטרן, יו\"ט זוסמן מקיש-קערעש","k":"בעל תוספות יו\"ט לתהל","bt":"תריט","dt":"תרעח - כ כסלו","b":"תלמיד השב\"ס, ור אליעזר זוסמן סופר מפאקש. חתן ר שלמה צובל מטירנא. מחכמי סנט ענדרע, קיש-קערעש-תרן. הו\"ל ספרי חותנו \"אמרי נועם\". פרסם מאמרים ב\"וילקט יוסף\", ועוד. בנו ר יהודה רב בבודפשט."},{"i":53105,"n":"שטרן, יוסף זכריה משאוולי","f":"נתן-ראש ברזל מניישטט","k":"בעל זכר יהוסף","r":"רב בשאוועל","bt":"תקצא","bp":"ניישטט-שאקי","dt":"תרסד - יא תשרי","b":"מגדולי חכמי דורו, חתן ר מרדכי גימפל יפה. למד בקיבוץ בסובאלק אצל ר יחיאל הלר בעל \"עמודי אור\" וכונה \"העילוי מיאשינאווקע\". רב ביאסינובקה-פלך גרודנא-תריא, שאוולי-תרכא על מקום ר יצחק איזיק רבינוביץ בעל \"עטרת יצחק\" וכיהן כ-43 שנה. היה מגדולי המשיבים וכתב אלפי תשובות לכל קצוות תבל. מחובברי ציון. התנגד לאתרוגי קורפו, לא הסכים עם היתר השמיטה-תרץ. פרסם מאמרים ב\"הלנבון\". היה במחלוקת ומלחמת דעות עם המשכילים ובעיק בלילינבלום ולילנטל שכתבו כנגדו. חיבר גם \"ביאור חדש מהריז\"ש, ועוד. תולדותיו ב\"ספרו של רבינר. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה תרנג, \"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"שערי תורה\" - וארשא תרסג.","bk":[["זכר יהוסף [עהש\"ס",""],["שו\"ת",""],["על הגדש\"פ]",""],["ביאור זכר יהוסף – הגדה של פסח",""],["ביאור חדש מהריז\"ש – ה מגלות",""],["זכר יהוסף – שו\"ת",""],["תהלוכות האגדות",""],["הגהות ריז\"ש - על הבה\"ג -",""]]},{"i":53106,"n":"שטרן, יוסף יוזפא הלוי מזולקוא","f":"שמואל הלוי מזולקוא","k":"בעל יד יוסף","r":"אב\"ד זלאקווא","bt":"תק","bp":"זולקוא","dt":"תקפז - כב טבת","dp":"זולקוא","b":"רב בזולקוא (קודם היה דיין אצל ר יעקב אורנשטין ואח\"כ ממלא מקומו - יחד עם ר יוסף אלעזר גוטליב - לאחר שר יעקב עבר ללבוב), ברודי, עמד בראש ישיבה בזולקוא על מקום ר עקיבא דיין, ומתלמידיו - ר אליהו הורשובסקי מדרוהוביטש ור שאול קצנלסון מלמברג. חיבר \"יד יוסף\" זולקוא תקפט. (מעשה שקרהו ב\"ספר סופר וסיפור\"). הסכים על \"טהרות הקדש\", \"תקפו כהן\" לבעל הש\"ך, חדושי מהר\"ם שי\"ף. בנו - ר נתן צבי הירש מטורטשין (ולפי בובר-זולקוא - נכדו).","bk":[["יד יוסף – ב\"מ ויו\"ד",""],["יד יוסף",""]],"e":"ת\"ק~-תקפ\"ז"},{"i":53107,"n":"שטרן, יוסף מוינה וסערדאוהל","b":"חתן ר שלום דב בר שטרן מסערדאוהל. רב בסערדאוהל, וינה. חתנו ואחיינו - ר דוד צבי בוימגרטן מוינה."},{"i":53108,"n":"שטרן, יוסף מקלוש(=קאליש)","f":"יצחק בן מרדכי","bt":"תקסג או תקע","bp":"סטרימטרה","dt":"תריח - טו אדר","b":"נכד אחותו של ר שמואל שמלקא מניקלשבורג. תלמיד ר מנחם מנדל מקוסוב. חתן ר מנחם מנדל שטרן מסיגט. רב בקאלוש, סיגט על מקום חותנו. בנו ר חיים שמואל על מקומו אחריו בסיגט. היה במחלוקת הלכתית עם ר יהודה מודרן מסיגט."},{"i":53109,"n":"שטרן, יוסף נפתלי","f":"אשר אנשל","k":"בעל שער יוסף","bt":"אילאק","dt":"תשלא - יד אב","dp":"ירושלים","b":"נכד ר משה פאלק בעל \"ברכת משה\". תלמיד ר פנחס שטינר מאילאק, ר ישעיה זילברשטין מויצען, רי\"צ דושינסקי בגלאנטא. חתן ר שלמה אלכסנדרי סופר בן ה\"מכתב סופר\". ניצל מהשואה והציל את כתבי חותנו-זקנו והו\"ל בירושלים תשטו. ראש ישיבת \"פרשבורג\" בירושלים על מקום ה\"דעת סופר\" חיבר הגהות \"שער יוסף\" לדרשות החת\"ס, ו\"באר מרים\" על הספר \"מכתב סופר\"."},{"i":53110,"n":"שטרן, יחזקאל מעפריעס","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח, \"הנשר\" - טירנוי תרצג-תשד."},{"i":53111,"n":"שטרן, יחיאל מיכל מפולדא","b":"רב בפולדא-תקא. נינו-נכד בתו של המהר\"ם שיף. הו\"ל את \"חדושי הלכות\" מזקנו."},{"i":53112,"n":"שטרן, יחיאל מיכל מפולדש","f":"יחזקאל","bt":"תקעא","bp":"קאלוב","dt":"תרנא - ז אדר א","dp":"פילדעש","b":"תלמיד החת\"ס. בזיוו\"ש חתן ר מאיר ליב אסטריכר. רב בפילדעש(=פולדש)-מחוז האידו-תרלו, ובנו ר מנחם מנדל על מקומו אחריו."},{"i":53113,"n":"שטרן, יעקב מקנישא","b":"דיין בקנישא, נזכר בשו\"ת החת\"ס."},{"i":53114,"n":"שטרן, יצחק איזיק להוי מקוליקוב","b":"רב בקוליקוב-תרי."},{"i":53115,"n":"שטרן, יצחק איזיק ממישקולץ","dt":"תרעג - כח תשרי","b":"נכד בעל \"שערי תורה\" מאבאוי-סאנטו. דומ\"צ במישקולץ על מקום ר אברהם דוד הופמן."},{"i":53116,"n":"שטרן, יצחק הלוי מדומברובה","b":"רב בדומברובה, (וגם אחיו ר צבי הירש רב בדומברובה), בנו ר שמעון ובנו ר משולם פיבוש על מקומו אחריו. חתן ר משה מרדכי מקראקא. עלה לארץ-תקס וכיהן ברבנות."},{"i":53117,"n":"שטרן, יצחק יהודה ליב מפאפא","f":"ראובן מגימערע","bt":"תר","bp":"גיעמערע","dt":"תרפו - כו תמוז","dp":"מאקווא","b":"תלמיד הכת\"ס. רב בפאפא, מאקווא."},{"i":53118,"n":"שטרן, יצחק יהודה מביליץ","f":"משה שמואל מביליץ","b":"תלמיד בישיבת חכמי לובלין. ניצל מהשואה ואחריה כיהן כרב בביליץ. עלה לארץ. חתן ר פנחס הלוי ברוכשטט מרוזין."},{"i":53119,"n":"שטרן, יצחק מסטרימטרה","f":"מרדכי מסלישט","k":"דער זיידע ר איציק","bt":"תקכג","dt":"תרה","b":"גביר מכניס אורחים מכפר סטרימטערע (היה היהודי הראשון שהתישב שם). בנו ר יוסף מקלוש."},{"i":53120,"n":"שטרן, יצחק צבי מסימערין","b":"שו\"ב בסימערין-תש."},{"i":53121,"n":"שטרן, ישכר בער מיריטשוב","f":"עזריאל מיריטשוב","dt":"תקנד","b":"רב ביריטשוב. חתן ר שאול מאמשטרדם."},{"i":53122,"n":"שטרן, ישכר דוב מוויצען","f":"ירוחם","bt":"תריד","bp":"האלאץ","b":"דומ\"צ בוויצען-תרנא ור\"מ בישיבה. פרסם מאמרים ב\"תל תלפיות\"."},{"i":53123,"n":"שטרן, ישעיה מיינק","f":"עזריאל","bp":"טאפלטשן","dt":"תריא - כז ניסן","b":"תלמיד החת\"ס. חתן ר יצחק מרקוס. רב ביינק - מ\"מ הרב. מכתב מהחת\"ס ובו מבקש מר משה פאקש להשלים עם ר ישעיה - שנפל מחלוקת ביניהם, ואכן השלימו."},{"i":53124,"n":"שטרן, ישראל מאישטיטשקא","f":"פנחס","b":"רב באישטיטשקא. מתורתו ב\"באר שרים\"."},{"i":53125,"n":"שטרן, ליפמן מפרשבורג","b":"מראשי קהלת פרשבורג. חתם על תקנות ביה\"ס למלאכה שע\"י הקהלה-תקפא."},{"i":53126,"n":"שטרן, מאיר מטאפאליה","b":"רב בטאפאליא-תקס\"ח"},{"i":53127,"n":"שטרן, מאיר ממגנדורף","b":"שו\"ב במגנדורף."},{"i":53128,"n":"שטרן, מאיר מפפד\"מ ופולדא","dt":"תנו","b":"תלמיד וחתן ר מנחם מנדל בס מפפד\"מ. מקובל, דיין בפפד\"מ. רב בפולדא-תכ - עד לגירוש-תלז, רב באמשטרדם. לימד קבלה את הנוצרי קנור פון רוזנרות. אחיו של ר אברהם - רבה של מורביה. בנו - ר מנחם מנדל."},{"i":53129,"n":"שטרן, מנדל מפרשבורג","f":"יצחק","b":"תלמיד בישיבת החת\"ס. מורה בביה\"ס פרימער שוהלע בפרשבורג על מקום אביו-שהתעוור, ולימד דקדוק עברי את בני החת\"ס בביתם. מגיה בדפוס שמיד בוינה. עורך המאסף \"כוכבי יצחק\". הספיד את החת\"ס בשם \"אבל משה\" וינה תר, וכן את ר אברהם לבוב. היה בעל קשרים טובים עם החת\"ס ובזכות השתדלותו נתן החת\"ס הסכמה לחכם דוקס על תרגומו לגרמנית של פירוש רש\"י."},{"i":53130,"n":"שטרן, מנחם זאב ממארוש-לודאש","f":"אפרים","k":"בעל רמז במלוא","bt":"תרסג","bp":"אויבר-וישווה","dt":"תשלה - יז תשרי","b":"תלמיד דודו ר שלמה זלמן פרידמן מראחוב, ור יואל טיטלבוים בעל \"ויואל משה\". חתן ר מאיר בנעט מטשארדא-ליד סיגט. שו\"ב במארוש-לודאש, ובהמשך גם רב בפועל-תרצו על מקום ר גרשון שטרן. ניצל מהשואה, ואחריה רב באויבר-וישווה. עלה לארץ וכיהן כרב בגבעת שאול. חיבר פירוש לתנ\"ך \"רמז במלוא\" ירושלים תשלט. ספריה-תש\"י,גבעת שאול(ירושלים)-תשכ\"ז."},{"i":53131,"n":"שטרן, מנחם מנדל הלל מביליץ","f":"יהודה מטרנוב","bt":"תרי","bp":"טרנוב","dt":"תרפח","b":"חתן ר אליעזר בנימין וולף מלייפציג. רב באנדריחוב ליד הרב הנאור אבא מצנר, רב בביליץ-תרן (לקהילה החרדית) ליד הרב הנאור ד\"ר ז שטיינר. בנו ר משה שמואל על מקומו אחריו בביליץ."},{"i":53132,"n":"שטרן, מנחם מנדל מפולדש","f":"יחיאל מיכל מפולדא","dt":"תרצ","b":"רב בפולדש(=פאלדעש,פילדא)-תרם על מקום אביו, וחתנו ר יעקב לוינגר על מקומו אחריו."},{"i":53133,"n":"שטרן, מנחם מנדל מפפד\"מ","f":"מאיר","dt":"תנו - יג אייר","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":53134,"n":"שטרן, מנחם מנדל מפרשבורג","b":"חכם,סופר בפרשבורג-ת\"ר"},{"i":53135,"n":"שטרן, מנחם מנדל מפרשבורג","f":"ר\"י","b":"תלמיד ישיבת פרשבורג.הו\"ל \"כוכבי יצחק\"."},{"i":53136,"n":"שטרן, מנחם מנדל מקאליש","f":"שמואל מדרגמירשט","k":"בעל דרך אמונה-תרטז","r":"אב\"ד סיגעט וגליל מרמרוש","bt":"תקיט","bp":"כפר דראגמירשט","dt":"תקצד - ט אדר","b":"תלמיד ר משולם איגר בפרשבורג. חתן ר בנימין ממנוסטרישץ, ועבר לשם וכיהן כדיין אצל ר יעקב מליסא בעל \"חוות דעת\" רבה של מאנוסטרישץ, לבקשתו של ר יעקב מליסא עבר עמו לקאליש ושימש כדיין וראב\"ד אצלו. התקרב לחסידות ובמיוחד לר מנחם מנדל מקוסוב ולאדמורי סאסוב. רב בסיגט-תקסב אצל ר יהודה הלר בעל \"קונטרס הספיקות\" ועל מקומו אחריו, ורב ראשי-מחוז מארמרוש על מקומו אחריו-תקעט. חתנו ובן דודו ר יוסף שטרן על מקומו אחריו בסיגט. חיבר \"דרך אמונה\" טשרנוביץ תרטז.","bk":[["דרך אמונה - על התורה",""]]},{"i":53137,"n":"שטרן, מרדכי מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":53138,"n":"שטרן, מרדכי מסלישט","f":"יוסף מצורטקוב","bt":"תצ","bp":"צורטקוב","dt":"תקס","b":"תלמיד דודו ר שמלקא מניקלשבורג. עבר למרמורש עם אחיו ר שלמה פרוכטר ור אברהם אדלר, והתישב בכפר סלישט (ליד סיגט) והקים שם בית מדרש חסידי ראשון במארמרוש."},{"i":53139,"n":"שטרן, מרדכי מקאנדאוי","bp":"קורלנד","b":"רב בקאנדאוי-קורלנד עם ר מאיר זימנסון, עלה לארץ. חתנו - ר זלמנסון מריגא בן ליב בן ר יוסף שזוארזדער."},{"i":53140,"n":"שטרן, מרדכי מקאשוי","f":"אברהם מנייהייזל","k":"בעל רב חסד","bt":"תרסט","bp":"נייהייזל","dt":"תרצה - ד כסלו","dp":"נייהייזל","b":"תלמיד הדעת סופר, וזקנו ר יוסף מאיר טיגרמן מנייהייזל, ור יהושע בוקסבוים מגאלאנטא. חתן ר שאול בראך מקאשוי, ור\"מ בישיבה של חותנו."},{"i":53141,"n":"שטרן, משה","f":"ישכר יהודה הלוי","b":"חתן ר יצחק שלמה בייגל. הביא לדפוס \"שער ההכנה\" לר נפתלי הכהן בעל \"סמיכת חכמים\" - קראקא תרצה. בסוף הספר מפרט את יחוסו שלו."},{"i":53142,"n":"שטרן, משה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":53143,"n":"שטרן, משה אריה מפרשבורג","dt":"תשד","b":"תלמיד ישיבת פרשבורג בזמן מלחה\"ע ה-I, והיה עורך מדור ההפטרה בשבועון הציוני \"זשידו סעמלא\" - בהונגרית. נספה בשואה."},{"i":53144,"n":"שטרן, משה יוחנן מגרוסורדין","dt":"תרצט - ו סיון","b":"אחיו - ר יהודה מארים."},{"i":53145,"n":"שטרן, משה מדברצין","f":"אברהם מנייהייזל","k":"בעל באר משה","r":"רב יסודי התורה בברוקלין, ומלפנים רב בדערבצין ונייהזל","bt":"תרעד","bp":"נייהייזל","dt":"תשנז - ב אב","b":"תלמיד הדעת סופר, וזקנו ר יוסף מאיר טיגרמן מנייהייזל, ור מאיר יהודה פרייא משוראן. חתן ר מרדכי ניסן הכהן שטרסר מדברצין, דיין בדברצין לצד חו\"ז - ר שלמה צבי שטרסר אב\"ד דברצין. ניצל מהשואה ואחריה רב בדברצין-תשה על מקום חו\"ז. רב בבואנוס איירס-תשי, ניו יורק בקהילת יסודי התורה, ובנו ר שלמה צבי על מקומו אחריו. פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!).","bk":[["באר משה - שו\"ת, עירובין, בירורי הלכות על בני א\"י היורדים לחו\"ל ואיפכא",""],["באר משה",""]]},{"i":53146,"n":"שטרן, משה מדרגמרשט","f":"בנימין","r":"רב בערים אויבער ווישווא, סליטש, ודראגמירישט, פאליען ריסקווה","bt":"תריב","bp":"פרעבניק-פולין","dt":"תרפג - ד שבט","b":"חתן הגביר ר יצחק ליב כהנא מאויברוישווה, ועבר לשם. עבר לכפר סלישט. רב בדראגמירשט-תרמב, פאליין-ריסקווה(=פוליען-ריסקובה)-תרן כ-30 שנה וחתנו ר דוד שפרבר על מקומו אחריו, ור אברהם איזקסון רב חסידי קוסוב על מקומו אחריו. מתורתו בספר חתנו ר דוד שפרבר \"אפרקסתא דעניא\" ירושלים תשמא.","bk":[["באר משה [שטרן]","שו\"ת - אחרונים"],["הערות על הש\"ס - נדפס בסוף ח\"א של אפרקסתא דעניא",""]]},{"i":53147,"n":"שטרן, משה מטארקאני גדול","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":53148,"n":"שטרן, משה מרימנוב","b":"רב ברימנוב-תרמג."},{"i":53149,"n":"שטרן, משה צבי מהליטשאבנה","f":"שלמה שטרן","dt":"תרמח - כו סיון","b":"רב בהעליטשאבא-תרי\"ט,עבר לסרדאהעלי"},{"i":53150,"n":"שטרן, משה צבי מניו יורק","f":"משה מדברצין - נ\"י","b":"רב בקהילת יסודי התורה בבורו פארק-תשנז על מקום אביו."},{"i":53151,"n":"שטרן, משה שמואל מביליץ","f":"מנחם מנדל הלל מביליץ","bt":"תרמח","dt":"תשג","b":"חתן ר חיים דובריש שטרוך מניימרקט. רב באנדריחוב-תרעב על מקום אביו. רב בביליץ-תרפח על מקום אביו. נספה בשואה. בנו ר יצחק על מקומו אחריו וניצל מהשואה."},{"i":53152,"n":"שטרן, משה שמואל מסערענטש","f":"אברהם יהודה ליב משאק","k":"בעל זכרון שמואל","bt":"תרז","dt":"תרסט - טז תמוז","dp":"סערענטש","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבאלאש-ירמוט, ור נתן בנימין ליבר מפרשבורג. חתן ר שרגא פייש פישמן מפרשבורג, ובזיוו\"ש חתן ר מרדכי הולנדר ממישקולץ-תרלב. גביר בסערענטש. נתקבל לרב בשאק-סעלעצע על מקום אביו - אולם סירב לרבנות."},{"i":53153,"n":"שטרן, משלם פיבוש מדומברובה","f":"יצחק הלוי מדומברובה","k":"פיבושל קינעס","dt":"תקצז - כה טבת","b":"רב בדומברובה על מקום אביו. דיין בקראקא-תקצב."},{"i":53154,"n":"שטרן, נח","f":"שמריהו","k":"תרגם ארץ השממה לאליו","bt":"1912","bp":"יאנובה","dt":"1960","dp":"תל אביב","b":"למד בהרווארד-ארה\"ב-1930. עלה לארץ-1935 והתישב בתל אביב. פרסם שירים בעתונות העברית בליטא, ובארץ. מכתביו יצא לאור \"בין ערפילים\" ת\"א 1966."},{"i":53155,"n":"שטרן, נפתלי הרץ מפרוינקירכן","dt":"תד","b":"רב בפרוינקירכן"},{"i":53156,"n":"שטרן, נפתלי צבי מטיוועש","f":"מרדכי מגלוד","k":"בעל גרסא דינקותא-תרס","dt":"תרלט - ז חשון","b":"תלמיד ר אשר אנשיל יונגרייז בטשנגר, ובעל \"ייטב לב\" בסיגט. רב בטיוועש. נפטר בגיל 25 ללא ילדים בחיי אביו."},{"i":53157,"n":"שטרן, נתן חריף מרדזימין","f":"יוסף יאנובר","b":"רב בראדזימין,וויסטאניץ,וולאדיסלבה-ת\"ר"},{"i":53158,"n":"שטרן, נתן מניישטט שאקי","b":"רב בניישטט-שאקי(=ניישטט שירווינט)."},{"i":53159,"n":"שטרן, נתן צבי הירש מראווה","f":"יוסף יוזפא מזולקוא","bt":"תקלה","dt":"תרח - בערך","b":"חתן ר נח מפוריצק. רב בטורטשין, ראווה-תקע על מקום ר מנחם מנדל. בין תלמידיו ר יצחק שמלקיס. מתורתו בתוך \"דעת ומזימה\". (לפי בובר-זולקוא - היה נכדו של ר יוסף יוזפא ולא בנו)"},{"i":53160,"n":"שטרן, צבי דוד ממוזען","b":"רב במוזען (ליד דולינא). מתורתו בשו\"ת הד\"ר."},{"i":53161,"n":"שטרן, צבי הירש הלוי מדומברובה","dt":"תקסד","b":"רב בדומברובה על מקום אבותיו. סופר ועד ארבע ארצות. בניו - ר יוסלה חריף ליכטיג על מקומו אחריו, ר יעקב סגל לבנהיים מוולברום."},{"i":53162,"n":"שטרן, צבי יהודה מבאלאש ירמוט","f":"ר\"ז","dt":"תרלט - יב ניסן","dp":"באלאש ירמוט","b":"תלמיד החת\"ס. רב בפעטיאן (ליד באלאש ירמוט), באלאש-ירמוט-תרך."},{"i":53163,"n":"שטרן, צבי יהושע מארה\"ב","bt":"1897","bp":"אייראגולה","b":"היגר בילדותו לארה\"ב. תלמיד \"היברו יוניון קולג'\" בסינסינטי. רב ריפורמי ב\"היכל ישראל\" ביוניון טאון-פנסילבניה, ו\"היכל עמנואל\" במונטריאול. מזכיר הקונגרס היהודי הראשון בג'נבה-1935. מזכיר ועידת הנוצרים והיהודים במונטריאול. חיבר ספרים באנגלית בנושאי יהדות."},{"i":53164,"n":"שטרן, רפאל מאונגוואר","b":"מראשי הח\"ק באונגוואר."},{"i":53165,"n":"שטרן, שלום דב בר מסערדאוהל","f":"שלמה מהעלישטבא","k":"בעל לשד השמן","bt":"תקצד","dt":"תרע - יט תמוז","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור ישראל יצחק אהרן לנדסברג מגרוסורדין. חתן ר דוד צבי ארנפלד מפרשבורג (חתן החת\"ס) ועבר לשם. רב בסערדאוהל-תרכו. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":53166,"n":"שטרן, שלמה זלמן","bt":"תקסז","bp":"רכניץ","b":"חוקר בחכמת ישראל. הו\"ל ספרי קדמונים ובהם: \"תשובות תלמידי מנחם ותלמידי דונש\" - וינה תרל, \"מחברת הערוך\" - תרד, \"בית הבחירה\", ועוד."},{"i":53167,"n":"שטרן, שלמה זלמן מטימישואר","f":"משה שמואל מסערענטש","k":"בעל תפארת שלמה","bt":"תרלג","bp":"מישקולץ","dt":"תרצג - אחרי","b":"תלמיד השב\"ס, תלמיד ר שמואל רוזנברג באונסדורף, ור מרדכי ליב וינקלר במאד, ור שרגא צבי טננבוים ממעזא-טשאטא ועוד. חתן ר ישראל זאב פנט מטגלאש ועבר לשם-תרסח. רב בקארא-יענא-מחוז פשט-תרעב, רב הקהילה החרדית בטימישואר-פאבריק-תרעב. הו\"ל עולת חדש השלישי עם חדושים מאביו."},{"i":53168,"n":"שטרן, שלמה זלמן ממיטאוי","f":"ברוך","b":"רב במיטאוי-תץ."},{"i":53169,"n":"שטרן, שלמה מאליטשאבא","dt":"תריט","b":"רב באליטשאבא. חתן ר שלום פרידמן מפריישטט."},{"i":53170,"n":"שטרן, שלמה מפרשבורג","b":"חבר בועד הלא רשמי של יהודי פרשבורג ועסק בהצלת יהודים בזמן השואה - כל זמן שניתן היה."},{"i":53171,"n":"שטרן, שמואל","b":"תלמיד החתן סופר"},{"i":53172,"n":"שטרן, שמואל טוביה ממקסיקו","b":"אב\"ד מקסיקו-תש."},{"i":53173,"n":"שטרן, שמואל מדרגמרשט","b":"רב בדרגמרשט-תק\"ס"},{"i":53174,"n":"שטרן, שמעון מדומברובה","f":"מנחם מנדל מדומברובה","dt":"תרצו","b":"רב בדומברובה, גדוב, ועל מקומו אחריו ר שבתי יצחק הרציג."},{"i":53175,"n":"שטרן, שמעון מדומברובה","f":"יצחק הלוי מדומברובה","k":"בעל שם משמעון","dt":"תרטז - בערך","b":"רב בדומברובה אצל דודו ר יוסף חריף לייכטג, ועל מקומו אחריו. ר צבי הירש וייס מילא את מקומו אחריו. חיבר \"שם משמעון\" למברג תרל."},{"i":53176,"n":"שטרן, שמעון מדומברובה","f":"אריה ליב","dt":"תקלח","b":"רב בדומברובה."},{"i":53177,"n":"שטרן-סטאראני, אלברט מבודפשט","b":"רב ניאולוגי בנייפעסט-1867, התפטר לאחר שבני קהילתו סירבו לקבל את חדושיו הקיצוניים בדת, ארגן פלג שרצה לנתק את קשריו עם היהדות ההיסטורית - התקנון שחיבר נדחה ע\"י שר הדתות וע\"י הסמינר לרבנים בבודפשט. עורך \"המחקר\"-1887. פרסם מאמרים בכתבי עת בנושאי יהדות וספרות עברית. מבניו: הברון יוסף סטאראני - שר המסחר אצל הקיסר פרנץ יוזף הראשון."},{"i":53178,"n":"שטרנבך, אברהם מלמברג","b":"רב בלמברג-תרס."},{"i":53179,"n":"שטרנברג, חיים מרדכי מאלכסנדר","f":"שלמה","bt":"תרלב","b":"רב באלכסנדר-וואהלין-תרנו."},{"i":53180,"n":"שטרנברג, יוסף מבודפשט","f":"משה מאטש","b":"מחכמי בודפשט. חתן ר משה נחום הירשלר מוינה. חתנו - ר אפרים פרידמן מטימשוואר."},{"i":53181,"n":"שטרנברג, יעקב דובר מקראקא","b":"מחכמי קראקא-תרכט."},{"i":53182,"n":"שטרנברג, יצחק איזיק ממערויץ","f":"משה בן שאול","bt":"תרלז","b":"מצאצאי ר יצחק איזיק מחמלניק, והמהר\"ל. חתן ר יוסף למדן מבראניווקא. רב במערעוויץ-ווהלין-תרסב. נסמך מאת: ר משה נתן רובינשטין מויניצא בעל \"אלף המגן\", ר שלום יוסף רבינוביץ מקראסני."},{"i":53183,"n":"שטרנברג, לוי מדומברבני","f":"משה בן שאול","bt":"תרמג","b":"חתן ר יוסף למדן מברניווקא (ואולי הכונה לאחיו של ר לוי - ר יצחק איזיק שטרנברג). רב בדומברבני(=דאמבריווען)-בסרביה. אחיהם של ר יצחק ממערעויץ, ר שלמה מליפוביץ."},{"i":53184,"n":"שטרנברג, מנחם מנדל מדעש","bt":"תרג","bp":"ארישאר","dt":"תרעו - ג ניסן","dp":"צפת","b":"תלמיד הכת\"ס, ור מנחם מנדל פנט מדעש. חתן ר אברהם יוחנן מדעש, ועבר לשם. עלה לצפת והיה מראשי כולל זיבנבירגן. חתניו - ר שמואל לוריא דיין בצפת, ור שמשון היימן מברעטיאג."},{"i":53185,"n":"שטרנברג, משה","f":"שאול","b":"מצאצאי בעל \"תוספות יו\"ט\", ר יצחק איזיק מחמלניק, והמהר\"ל. רב-שנת תר\"נ. בניו: ר יצחק איזיק מ מערעוויץ, ר שלמה מליפוביץ, ר לוי מדאמבריווען."},{"i":53186,"n":"שטרנברג, משה מאטש","b":"רב באטש"},{"i":53187,"n":"שטרנברג, משה מקראקא","b":"מחכמי קראקא. הוציא לאור \"מעשה טוביה\". עסק בהכנת \"אנשי שם בזמננו\". פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח."},{"i":53188,"n":"שטרנברג, נתן מלבוב","f":"אליעזר","b":"דיין בלבוב, חתם-תח עם ר יעקב קצנלנבוגן ועם ר מרדכי בן צבי הירש מלבוב, חתם-תג עם ר שמואל זנויל אירבך, ר פאלק יהושע. חתם גם שינברג (ויש אומרים שהוא חכם אחר - ראה בערכו)."},{"i":53189,"n":"שטרנברג, צבי הירש מגיידינג","b":"מחכמי גריידינג-תרלט."},{"i":53190,"n":"שטרנברג, צבי הירש מצורטקוב","b":"דומ\"צ בצורטקוב, ומשב\"ק אצל האדמור מצורטקוב-תרב (בתחילה אצל ר דוד משה ואח\"כ אצל בנו ר ישראל)."},{"i":53191,"n":"שטרנברג, שאול","b":"חתן ר איזיק מחמלניק-מצאצאי המהר\"ל. רב-שנת תר\"כ."},{"i":53192,"n":"שטרנברג, שלום יצחק מקראקא","f":"ישעיה קלונימוס הכהן","k":"בעל ברכת שלום","bt":"תרטו או תרכא","bp":"קראקא","dt":"תרצו","b":"רב הקהלה החסידית באנטורפן-תרנה. חיבר \"ברכת שלום\" אנטורפן תרץ. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד."},{"i":53193,"n":"שטרנברג, שלמה מליפוביץ","f":"משה בן שאול","b":"רב בליפוביץ-תר\"ע"},{"i":53194,"n":"שטרנברג, שמואל מבוצאץ","f":"גדליה יוסף מבוצאץ","bp":"בוצאץ","dt":"תשלז","b":"חסיד בלז. עבר לשוויץ בזמן מלחמת העולם ה-I. חתן ר מנחם מאיר רטיג מיברוב. עסק בהצלה משוייץ בזמן השואה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":53195,"n":"שטרנברג, שמשון משה","f":"שלמה אריה","k":"אדמור מקוזניץ בת\"א","b":"מצאצאי המגיד מקוזניץ. נכד ר ישראל אלעזר שפירא האדמור מקוזניץ. אדמור מקוזניץ בתל אביב."},{"i":53196,"n":"שטרנברג, שניאור זלמן מויניק","b":"רב בכפר ויניק, למברג."},{"i":53197,"n":"שטרנהל, אריה יהודה ליבש מבויאן","f":"ישראל איסר מבויאן","b":"חסיד בויאן, רב בבויאן על מקום אביו. עבר לארה\"ב."},{"i":53198,"n":"שטרנהל, דוד מירושלים","f":"משה יהושע השל מלינסק","dt":"תשיט","dp":"ירושלים","b":"חסיד הרבי משיניבה ובנו רשי\"ב מצשינוב. עלה לארץ-תרצג. הדפיס מגילת יוחסין שלו. חתן ר נתן יהודה ליב טורם מגורליץ (גיסו של הדברי חיים)."},{"i":53199,"n":"שטרנהל, דוד מקולומיאה","f":"נפתלי צבי מקולומיאה","b":"גביר מחכמי קולומיאה. בנו - ר פנחס בורטשין מסערט, ועוד."},{"i":53200,"n":"שטרנהל, יעקב מלינסק","f":"דוד מקולומיאה","b":"מחכמי לינסק. חתן הגביר ר יצחק איזיק מסניאטין."},{"i":53201,"n":"שטרנהל, יצחק מצאנז וארה\"ב","f":"דוד מגורליץ","k":"איטשע צאנזר","bt":"תרע","bp":"גורליץ","dt":"תשם","b":"תלמיד ור\"מ בישיבת דרכי תשובה במונקטש. ערך ירחון תורני \"הכוכב\" - מונקטש-ניו יורק תרצה-תשיב. חתן ר אהרן צבי קסטנבוים מטיסא-אילק. ניצל מהשואה, ואחריה רב בזלצבורג, ניו יורק. בזיוו\"ש חתן ר יהושע זיידנפלד. עבר לארה\"ב-תשיא וכיהן כרב בבולטימור. חיבר \"למכה מלכים\" מונקטש תרצב, ועוד. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":53202,"n":"שטרנהל, ישראל איסר מבויאן","f":"שואל","b":"רב בבויאן, בנו ר אריה יהודה ליבוש על מקומו אחריו."},{"i":53203,"n":"שטרנהל, מנחם מנדל מירושלים","b":"פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה, תלמיד ישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\". מעורכי \"המגיד\" - סטמר תרצט."},{"i":53204,"n":"שטרנהל, משה יהושע השל מלינסק","f":"יעקב מלינסק","dt":"תש..","b":"חסיד צאנז, שיניבה וצשינוב. נספה בשואה. חתן ר יצחק קנר מלינסק."},{"i":53205,"n":"שטרנהל, פנחס ישעיה מחנטשין","f":"יוסף ברוך","b":"רב בחנטשין-תרצג."},{"i":53206,"n":"שטרנהל, שאלתיאל יצחק מקולומיאה","f":"דוד הלוי","b":"נכדו של ר אדם בעל שם מרופשיץ. גביר בקלוש, קולומיאה-תקם. גיסו של ר יעקב קופל חסיד. חתן ר זלמן ב\"ר יעקב קופל קופילטיס מקולומיאה. בנו - ר נפתלי צבי הירש אביו של ר דוד מקולומיאה. עלה לארץ."},{"i":53207,"n":"שטרנהרץ, אברהם","dt":"תשטו - כא אלול","b":"נכד ר נתן מברסלב. רב בקרמנצוג, אומן. עלה לארץ והקים את ה\"קיבוץ\" במירון, הקים קרית ברסלב בצפת. מנהיג חסידי ברסלב בדורו. תלמידו ר גדליה קניג מצפת. בנו ר נתן."},{"i":53208,"n":"שטרנהרץ, נתן מנמירוב","f":"נפתלי הירץ","k":"בעל לקוטי הלכות","r":"מברסלב","bt":"תקם","dt":"תרה - י טבת","b":"חתן ר דוד צבי אוירבך משאריגרד קרמיניץ ומוהליב. תלמיד ר לוי יצחק מברדיטשוב, ר שלום שכנא מפרוהבישט. תלמידו וממשיך דרכו-תקסב של ר נחמן מברסלב, כותב, מסביר, מדפיס ומפיץ תורת רבו בעולם. ביקר בארץ-תקפב. חיבר גם \"לקוטי תפלות\" עלים לתרופה\", ועוד. בניו: ר שכנא, ר יצחק, ר דוד צבי, ר נחמן, ור יוסף יונה.","bk":[["חיי מוהר״ן",""],["ימי מהרנ״ת",""],["ימי מוהרנ''ת",""],["ליקוטי הלכות",""],["נסיעת הר\"ן לארץ הקדושה",""],["עלים לתרופה",""],["שבחי הר\"ן",""],["ימי מוהרנ\"ת \\ ימי נתן",""],["ליקוטי הלכות – שו\"ע",""],["לקוטי תפלות",""],["מכתבי מוהרנ\"ת - ההשמטות מספר עלים לתרופה",""],["מקור האמונה",""],["שמירת הברית",""],["ליקוטי עצות חדש",""]]},{"i":53209,"n":"שטרנזר, חיים עוזר מקולומיאה","f":"שמואל משה מקולומיאה","bt":"תריד","bp":"קולומיאה","b":"תלמיד בישיבות גליציה, היגר לארה\"ב-תרנב וכיהן כרב בניו יורק ובסן פרנציסקו-תרנד, עלה לארץ-תרפח והתגורר ברחביה-ירושלים."},{"i":53210,"n":"שטרנין, ישכר בער מסוראז","f":"יצחק","bt":"תרכה","b":"רב בסוראז-פלך ויטבסק-תרסב."},{"i":53211,"n":"שטרנליכט, השל","dt":"תשג","b":"רב בהענטשין-אלקוש"},{"i":53212,"n":"שטרנפלד, בן ציון מבילסק","f":"אריה ליב","k":"בעל שערי ציון","bt":"תקצה","dt":"תרעד","b":"רב ברוסי, מאראטש על מקום ר דוד ולפה, שרשוב, איישישוק, חיסלאוויץ, קלוואריה, בילסק-תרס. ידידו של החפץ חיים. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":53213,"n":"שטרנפלד, דניאל מברודשין","b":"מיסד ישיבת תורת חיים בברודשין בעזרת ר הלל לנגרמן מברודשין, ורשת ישיבות בגליציה המזרחית (הישיבה הראשונה בגליציה - לפי אהלי שם). עבר לטשרנוביץ ויסד את ישיבת \"באר מים חיים\". עורך שבועון \"דער יידישער צייטונג\". היה סוחר אתרוגים ופרסם ב\"דראהאביטשער צייטונג\" קריאה להעדיף אתרוגי ישראל על יון."},{"i":53214,"n":"שטרנפלד, יהושע אשר","bt":"תרכז","dt":"תשא","b":"אדמו\"ר מפוריסוב-וורשה-תרצ\"ה"},{"i":53215,"n":"שטרנפלד, יצחק איצק ממאהר","k":"בעל מטעמי יצחק -כת\"י","b":"רב במאהר(=מאר)-תקצג, באנוביץ-סלובקיה, זשאבאק. הניח חבורים בכת\"י - \"מטעמי יצחק\", \"אהל יצחק\", \"מגיד יצחק\" - ואבדו."},{"i":53216,"n":"שטרנקלר, אהרן מחודרוב","b":"רב בחודרוב-תקע. תלמיד ה\"נועם אלימלך\". חותנו של ר אלעזר ניסן טיטלבוים מדרוהוביטש."},{"i":53217,"n":"שטרסבורג, אברהם מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":53218,"n":"שטרסבורג, אהרן משטרסבורג","b":"מחכמי שטרסבורג-צרפת, עבר לאיטליה-רן, רב בפירלי. בנו ר גבריאל משטרסבורג. ונזכר ב\"שלשלת הקבלה\"."},{"i":53219,"n":"שטרסבורג, גבריאל","f":"אהרן משטרסבורג","b":"מגדולי חכמי אשכנז-רמ\"ד"},{"i":53220,"n":"שטרסברג, אברהם ליב מקוסוב","f":"זידל שלמה דוד הלוי","bt":"תרנד","bp":"קוסוב","dt":"תשמג","dp":"ירושלים"},{"i":53221,"n":"שטרסברג, יוסף יהודה מקוסוב","f":"דב הלוי","k":"בעל יד יוסף","bt":"תקפא","bp":"בוזנוב","dt":"תרעא","dp":"ירושלים","b":"רב בקוסוב-תרכא אצל ר יעקב שמשון הגר ור משה הגר. עלה לירושלים-תרנו, והיה חבר בד\"צ חסידים. בנו ר זיידל שלמה ממאה שערים. חיבר \"יד יוסף\" ירושלים תרנח. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"בית ועד לחכמים\" - נ\"י תרסג."},{"i":53222,"n":"שטרסניץ, יהודה מהליטש","b":"רב בהליטש-תקמב."},{"i":53223,"n":"שטרספלד, אלכסנדר ליפא הלוי","b":"רב בקוזובה-תרפה. נספה בשואה."},{"i":53224,"n":"שטרספלד, משה","f":"יעקב הלוי מרזלא","dt":"תשד","dp":"ירושלים","b":"מוזכר ב\"שביבי אש\"-תשד."},{"i":53225,"n":"שטרסר, אליעזר מניישטאט","bt":"תקנ-א","bp":"רגנדורף","dt":"תרט - יב טבת","dp":"ניקלשבורג","b":"תלמיד ר אלעזר רוקח מטריטש. חתן ר מאיר טורני מטריטש, ובזיוו\"ש חתן ר יעקב בער בי\"ח מניקלשבורג. רב ברגנסדורף, מגנדורף-תקפו, ראב-תקץ, עיר חדש(=ניישטאט)-תקצד. בנו - ר ליב מסארוואש, חתנו - ר אליעזר וינטר משטמפן. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז.. בנו - ר דוד יהודה ליב מסארוואש."},{"i":53226,"n":"שטרסר, דוד יהודה ליב מקולא","f":"אליעזר מעיר חדש","dt":"תרמח","b":"תלמיד ר יהודה אסאד. רב בסארוואש-תריא, קולא."},{"i":53227,"n":"שטרסר, חיים יהודה מניו יורק","f":"שמואל בנימין הכהן","bt":"תרעו","dt":"תשסד - ד טבת","b":"תלמיד הדעת סופר, ור שמואל דוד אונגרמ נייטרא ור יהושע בוקסבוים מגאלאנטא. חתן ר יעקב יחיאל שוורץ מקראלי. רב בטיסא-פירעד לצד אביו - שכיהן שם כראב\"ד. ניצל מהשואה ואחריה רב באיטליה, עבר לניו יורק וכיהן שם כרב, ויסד ביהמ\"ד \"כתב סופר\" וכיהן כר\"מ בישיבת \"חתן סופר\"."},{"i":53228,"n":"שטרסר, יונתן הכהן","dt":"תשד","b":"רב בדיור"},{"i":53229,"n":"שטרסר, יונתן הכהן מבודפשט","f":"יעקב יהודה מטאב","bt":"תרך","bp":"טאב","dt":"תרעט - יג אייר","dp":"בודפשט","b":"נכד הכת\"ס. חתן ר מנחם מאנדל הרצוג מווערבא ועבר לשם. רב בבודפשט."},{"i":53230,"n":"שטרסר, יונתן הכהן מראב","f":"עקיבא הכהן מטאקייא","bt":"תרנח","bp":"טאקייא","dt":"תשה - ל חשון","dp":"מאטהוזן","b":"תלמיד הדעת סופר, ור שמואל דוד אונגר מקרמפאך ונייטרא. חתן ר בנציון סנידרס מראב ועבר לשם. דיין בראב-תרצג. נספה בשואה. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא, \"הנשר\" - טירנוי תרצג-תשד."},{"i":53231,"n":"שטרסר, יעקב יהודה ליב מטאב","f":"משה דוד הכהן מטאב","bt":"תקצג","bp":"טאב","dt":"תרעב - ז ניסן","dp":"פרשבורג","b":"חתן רבו הכת\"ס. רב בטאב, פרשבורג. מתורתו ב\"תורת אבות\"."},{"i":53232,"n":"שטרסר, יצחק יוחנן הכהן מגרוסו'","f":"יעקב יהודה ליב מטאב","k":"בעל דברי יצחק יוחנן","bt":"תרלא","bp":"טאב","dt":"תרצד - י אלול","dp":"גרוסורדין","b":"נכד הכת\"ס. תלמיד השב\"ס, ור בנימין זאב ברייער מטאב. חתן ר אשר אנשל שוורץ - ראש הקהל בגרוסורדין, ועבר לשם. מחכמי גרוסורדין ונשיא חברת ש\"ס. ?? לא באוצר ??"},{"i":53233,"n":"שטרסר, מרדכי מאלטנדורף","f":"עקיבא מטאקאי","dt":"תשד","b":"חתן ר אורי ליפמן ביליצר מאלטנדורף. רב באלטנדורף-תרס\"ו על מקום חותנו, שאלא. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":53234,"n":"שטרסר, מרדכי ניסן מדברצין","f":"שלמה צבי מדברצין","b":"חתנו - ר משה שטרן אב\"ד דברצין, ורב בניו יורק."},{"i":53235,"n":"שטרסר, נתן נטע מהאידו-דאראג","f":"עקיבא הכהן מטאקיא","b":"חתן ר משה גינז-שלזינגר מבאדראג-קרסטור."},{"i":53236,"n":"שטרסר, עקיבא מטאקוי","f":"יעקב יהודה הכהן מטאב","bt":"תרך או תרכו","bp":"טאב","dt":"תרפד - כא אייר","dp":"טאקייא","b":"נכד הכת\"ס - אביו היה חתן הכת\"ס. תלמיד הכת\"ס והשב\"ס. חתן ר מרדכי ברוידא מיאווע. רב ביאווא(=מיאווא)-תרמג על מקום חותנו. טאקייא(=טוקאי, טאקוי)-תרנח וחתנו ר משה נתן נטע יוגנריז על מקומו אחריו. מתורתו ב\"תורת אבות\". הו\"ל ספר חמיו חדושי מהר\"מ ברודא עם תוספות ממנו - יחד עם גיסו וממלא מקומו ר יוסף ברודא מיאווע. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"הנשר\" - טירנוי תרצג-תשד."},{"i":53237,"n":"שטרסר, שלמה צבי הכהן מדברצין","f":"יעקב יהודה הכהן מטאב","bt":"תרכג או תרל","bp":"טאב","dt":"תשיג - כג תשרי","dp":"בני ברק","b":"נכד הכת\"ס. תלמיד השב\"ס, ור בנימין זאב וולף ברייער מטאב. חתן דודו ר יעקב עקיבא סופר ממיאווע - בן הכת\"ס, ועבר לשם. רב בסאבטישט-תרמט, שטיינמאנגר או טירנא-תרנה (האם אותה העיר?), דברצין-תרסב. ניצל מהשואה ועלה לארץ והתישב בבני ברק. מתורתו ב\"לשט שיבולים\". בנו ר מרדכי ניסן מדברעצין."},{"i":53238,"n":"שטרסר, שמואל בנימין הכהן מטיסא","f":"עקיבא מטאקיא","bt":"תרמה-נו","bp":"מיאווע","dt":"תשד - כא סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ודודו ר שלמה צבי שטרסר מדברצין, ור משה צבי הרש פוקס מגרוסורדין. חתן ר משה סופר מטיסא-פירעד. רב בטיסא-פירעד-תרעז על מקום חותנו. נספה בשואה."},{"i":53239,"n":"שטרסר, שמעון הכהן מפרשבורג","f":"עקיבא ממיאווע","bt":"תרנג","bp":"מיאווע","dt":"תשד - טז תמוז","b":"תלמיד הדעת סופר, ור יוסף צבי דושינסקי. חתן ר נחום גרינולד מטשאנרא, ועבר לשם-תרעח, ר\"מ בישיבה-תרפח, טשארנא-תרצח. נספה בשואה."},{"i":53240,"n":"שטרסר, שמעון מפרג","dt":"תשג","b":"ר\"מ בפרג"},{"i":53241,"n":"שטרסר, שמעון מפרשבורג","b":"תלמיד ישיבת פרשבורג. רב בפרשבורג-תרפז, ור\"מ בישיבה. מעורכי \"המעיין\" יחד עם ר שמואל בנימין סופר - כתב העת של בוגרי ישיבת פרשבורג - פרשבורג תרץ."},{"i":53242,"n":"שטרק, אברהם יהונתן מסוסנובצה","b":"רב בסוסנובצה. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":53243,"n":"שטרק, אברהם מהוניאד וקובין","b":"תלמיד הכת\"ס. רב בקובין, באנפי הוניאד-תריח, אחריו כיהן ר אברהם ישכר בער לייכטג-תרכו. התכתב עם ר מנחם מנדל בנעט מדעש שהזכירו בספרו \"שערי צדק\"."},{"i":53244,"n":"שטרק, חיים שלמה מטורקא","bt":"תרע","bp":"טורקא","b":"תלמיד ישיבת בובוב."},{"i":53245,"n":"שטרק, יצחק איזיק מסטרליסק","b":"רב בסטרליסק-תרכד."},{"i":53246,"n":"שטרק, יצחק נתן מסקול וביאלא","f":"אברהם דוד","k":"בעל יד יצחק","bt":"תרלב","b":"רב בקונסטנטיוו-ליד בנדין-תרנח, סקול(=סקאלא)-פלך קיעלץ, ביאלא. חסיד אלכסנדר. פרסם מאמרים ב\"בית ישראל\" - לודז תרץ. חיבר גם \"מנחת יצחק\", \"כרמנו\" - אלכסנדר-לודז תרצג, \"המפלפל\" - קראקא תרעג, \"נהור שרגא\" - אלכסנדר תרצט. ?? לא באוצר ??"},{"i":53247,"n":"שטרק, שמואל ישכר מסוירז ובוצאץ","f":"יחיאל אברהם","k":"שי\"ש-בעל אבני שיש","bt":"תר","bp":"סוירז","dt":"תרע","b":"תלמיד ר יצחק משלקיס. חתן ר בנימין פריינדליך מברזן. רב בסוירז, בוצאץ-תרנב תחת ר יחיאל מיכל ברומר (ועל כך היתה מחלוקת), (מתלמידיו שם - ש\"י עגנון). ויזניץ. חיבר \"מנחת עני\" למברג תרנז, ועוד."},{"i":53248,"n":"שטרק, שמואל נח מיאסווין","b":"שו\"ב ומגיד שיעור ביאסווין-ליטא."},{"i":53249,"n":"שטרקמן, יוסף מאיר","dt":"תרפט","b":"מו\"צ בקאליש-תרנ\"ט"},{"i":53250,"n":"שטרקשל, מאיר צדוק מלמברג","b":"מחכמי למברג-תרז."},{"i":53251,"n":"שטרשון, אברהם דוד מוילנא","f":"יהודה יודל מוילנא","k":"אברהמ'ל שטראשונער","bt":"תקנב","bp":"וילנא","dt":"תרטו","dp":"וילנא","b":"חתן ר שלמה זלמן - קרובו של בעל \"שלחן שלמה\". גביר פרנס ור\"מ בבימ\"ד היסו\"ד בוילנא. הניח חדושים בכת\"י. בנו ר שמעון מוילנא, חתנו - ר ישראל גורדון מוילנא. נוסח מצבתו מאת אד\"ם הכהן."},{"i":53252,"n":"שטרשון, אליהו מוילנא","f":"שמואל - הרש\"ש","b":"רב בוילנא. אחיו - ר מתתיהו."},{"i":53253,"n":"שטרשון, אליעזר מאיוויניץ","b":"רב באיוויניץ-תר\"מ"},{"i":53254,"n":"שטרשון, דוד מוילנא","f":"מתתיהו","b":"חתן ר שמואל הכהן. בזמן מלחמת נפוליאון-תקעב עבר לוילנא, עם חתנו ר שמואל-הרש\"ש. גביר בוילנא, יסד בימ\"ד בשם \"קלויז של ר דוד שטרשון\". בניו: ר חיים, ר הירש, ר משה."},{"i":53255,"n":"שטרשון, חיים","dt":"תרל - יג אד\"א","b":"גביר בליטא. דודו-אחי אמו של ר מתתיהו שטרשון."},{"i":53256,"n":"שטרשון, יהודה מוילנא וירושלים","f":"מתתיהו מאוטיאן והורו","dt":"תקפח - כט חשון","dp":"ירושלים","b":"מחכמי וילנא. נכד ר יוסף יאסקה מדובנא בעל \"יסוד יוסף\" ואביו של אברהם דוד. עלה לירושלים-תקפה."},{"i":53257,"n":"שטרשון, יצחק מקובנא","b":"ר\"מ בישיבת \"אהל יצחק\" בקובנא-תרצה, יחד עם ר איסר דריבין."},{"i":53258,"n":"שטרשון, מרדכי מוילנא","f":"יהודה זארעצער מירושל","k":"מאטיל יודיל זארעצערס","dt":"תרל - ו כסלו","b":"אחיו של ר אברהם דוד. חתן ר שמחה רפפורט מברדיטשוב-נכד ר חיים רפפורט מאוסטרהא בעל \"מים חיים\". נקרא גם מאטיל ריינעס ע\"ש אשתו. היה חבר בישיבת הארבעים. גביר מחכמי וילנא ובעל אוצר ספרים גדול. גבאי צ\"ג. בנו ר שמחה מתתיהו - נפטר בחיי אביו. חתנו ר יואל דוד - דער בעל הבת'ל. נספד ב\"הכרמל\" ע\"י קלמן שולמן."},{"i":53259,"n":"שטרשון, מתתיהו מוילנא","f":"שמואל - הרש\"ש","k":"בעל הגהות לש\"ס","bt":"תקעח","bp":"וילנא","dt":"תרמו - ו טבת","dp":"וילנא","b":"תלמיד ר ישעיה דוד מליבידוב, ר מנשה מאילייה ור יצחק מוולוזין. חתן ר יוסף אליהו עליאשברג. בקי גם בספרות ישראל לדורותיה. פרסם מאמרים בכתב עת ובהם \"היונה\" של שניאור זקש, \"המגיד\", ועוד. עשיר גדול ורכש ספרייה עשירה. פרנס בקהילת וילנא. הוריש את הספרייה לקהילת עם הבנין והיתה הספריה הציבורית הראשונה בוילנא. רשימת הספרים בספריה נדפסה בשם \"לקוטי שושנים\". ילדיו נפטרו בחייו. סירב לרבנות ברלין. תולדותיו ב\"מתתיה - באורים\" וילנא תרנג. נספד מאת ר שמעון אנטקולסקי ב\"אבל כבד\" - וילנא תרמו, עם קינה מבן אחיו - ר דוד בן יוסף שטרשון."},{"i":53260,"n":"שטרשון, שמואל","f":"אליעזר","k":"בעל לקוטי שושנים","bt":"1840","bp":"וילנא","dt":"1895","b":"ממשפחת הרש\"ש מוילנא. מגיה בדפוס ראם. ספרן בספריית שטרשון וערך את קטלוג הספרייה, בנו ר יצחק ניהל את הספריה אחריו."},{"i":53261,"n":"שטרשון, שמואל מוילנא - רש\"ש","f":"יוסף זסקביצר","k":"הרש\"ש-בעל הגהות הרשש","bt":"תקנד","bp":"זסקביץ","dt":"תרב - יא אד\"ב","b":"נכד-אבי אביו ר שמואל אב\"ד זסקביץ, ונכד ר אליהו מוולוזין אב\"ד סמרגון וזסקביץ. אחיו של ר מנשה מזסקביץ. חתן הגביר ר דוד שטרשון וקיבל את שמו. תלמיד ר אליעזר זוסקויצר, ור הירש שב\"ד. עבר לוילנא בזמן מלחמת נפוליאון עם חותנו. מחכמי \"ישיבת הארבעים\" בוילנא-תקפז. היה פרנס הקהילה ותלמיד חכם. חיבר מאמרים על קורות עיר וילנא בתוך \"קריה נאמנה\". בניו: ר אליהו, ר מתתיהו, חתניו: ר ירמיה רוטנר, ר יצחק זלקין מנסטירצינער, ר יוסף בצלאל הרכבי. תלמיד ר אברהם דנציג שהזכירו בספרו \"בינת אדם\" בשם מוהר\"ש זסקביצר."},{"i":53262,"n":"שטרשון, שמחה מתתיהו מוילנא","f":"מרדכי בן יהודה","dt":"תרכג - יד סיון","dp":"וילנא","b":"חתן ר אליהו עקיבא קמינצקי מלידא. בקי בשפות וגדול בתורה. נפטר צעיר בחיי אביו. נספד ב\"המגיד\"."},{"i":53263,"n":"שטשוב, אריה יהודה ליב מרכניץ","dt":"תקכז - ו אלול","b":"רב ברכניץ-תקח על מקום ר אהרן שבתאי פרוסטיץ ור אלעזר קליש על מקומו אחריו. היה מחלוקת כנגדו בגלל שנחשד בשבתאות והוא בתגובה החרים כמה ממתנגדיו, נאלץ לעזוב וחזר - רק לחלק מהקהילה (בהלוויתו רגמו כמה ממתנגדיו את מיטתו באבנים - עד שאחד מהם התעוור)."},{"i":53264,"n":"שטשינסקי, אברהם מנחם מנדל","b":"מחכמי דאמבייע. חיבר חדושים בכת\"י."},{"i":53265,"n":"שיאו די, משה מקושטא","f":"יצחק","b":"מחכמי קושטא-שנות ה-ש'."},{"i":53266,"n":"שיבא, שבתי מצידון","b":"רב בצידון-שנות ה-ר'-ש'."},{"i":53267,"n":"שיביליאנו, שלמה משלוניקי","dt":"רצח - יג כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53268,"n":"שיבילייו, דוד משלוניקי","dt":"שפא - ד אב","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר צעיר ללא ילדים."},{"i":53269,"n":"שיבר, בן ציון מפטשניזין","b":"רב בפטשניזין-תרפא."},{"i":53270,"n":"שיגוביא די, בנימין יוסף מירושל","b":"מחכמי ירושלים-תטז, חתם על כתב שליחות ר ברוך גד. (ראה גם: יוסף בנבנישתי די שיגוביא)"},{"i":53271,"n":"שיגוביה די, משה מאדריאנופול","f":"רא:ה בנבנשת די שיגוב"},{"i":53272,"n":"שיגורא די, אברהם מאזמיר","b":"מחכמי איזמיר"},{"i":53273,"n":"שיגורא די, אברהם מחברון","b":"מחכמי חברון, חתם בשנת תכא על אגרת שליחות ר חייא דיין"},{"i":53274,"n":"שיגורא די, אהרן מאזמיר","b":"מחכמי אזמיר"},{"i":53275,"n":"שיגורא די, אהרן ממצרים","b":"רב במצרים-שנות ה-ת'."},{"i":53276,"n":"שיגורא די, דוד מכיאו","b":"גביר מחכמי כיאו-שפ - בזמן ר כלב קלפי."},{"i":53277,"n":"שיגורא די, יהודה מקושטא","b":"רופא השולטן-שכ על מקום ר משה המון. סייע לאחיו יחד עם חברו ר יוסף המון - ובהם ליהודי שלוניקי-שכו."},{"i":53278,"n":"שיגורא די, ישראל שמואל מאזמיר","f":"פנחס רפאל יהושע","b":"רב באזמיר. הו\"ל ספר אביו \"אות היא לעולם\" עם הקדמה ממנו."},{"i":53279,"n":"שיגורא די, מאיר מאזמיר","b":"רב באזמיר. נזכר אצל ר חיים פלאג'י שראה ספר נימוקיו בכת\"י."},{"i":53280,"n":"שיגורא די, מאיר ממצרים","b":"רב במצרים. נזכר ב\"זכותיה דאברהם\"."},{"i":53281,"n":"שיגורא די, מאיר מצפת","b":"מחכמי צפת, חברו של ר חיים ירוחם וילנא, בהיותם בשליחות הסכימו על ספר \"פרדס והלכה ברורה\" לר אריה ליב מקניגסברג, בשליחות-תצו באירופה עם ר חיים יעקב בעל \"צרור החיים\", ובשליחות-תקיא עם ר יו\"ט סאביאן. כנראה פגש בליוורנו את החיד\"א המביא ממנו בספריו."},{"i":53282,"n":"שיגורא די, פנחס רפאל יהושע","f":"שמואל בן יצחק","k":"הפרד\"ס, בעל אות אמת","r":"חכם באשי איזמיר, כינה עצמו גם פר\"י שהוא ר\"ת של שמו","dt":"תריא - יח אד\"א","dp":"ירושלים","b":"רב באזמיר, ונזכר אצל חברו - שלמדו ביחד בצעירותם - ר חיים פלאגי, עלה לירושלים. חיבר גם \"אות אמת\", ועוד.","bk":[["אות אמת - סדר הפרשיות",""],["אות הברית - תהלים",""],["אות היא לעולם - ערכים בשיטות הש\"ס",""],["אות לטובה - סדר התפילות",""],["אות לישועה - דרושים למועדים",""]]},{"i":53283,"n":"שיגורא די, רחמים נסים יהודה","f":"רפאל פנחס מאזמיר","k":"בעל עקב ענוה","dt":"תרמא - טז כסלו","b":"רב באזמיר. חיבר גם ספר מערכות בכת\"י, \"אות לרחמים\" ו\"מגיד דבריו\"."},{"i":53284,"n":"שיגורא, אברהם חיים מקוש-אדאסי","b":"דיין בקוש-אדאסי-תקנט, ישב בדין פטירת יצחק אלמדיאל עם ר אפרים בכ\"ר שלמה סארדי. (ראה ר אברהם חיים דוד סארדי)."},{"i":53285,"n":"שיגורא, אהרן","b":"מגדולי חכמי מצרים-ת\"י"},{"i":53286,"n":"שידיליו, שלמה משלוניקי","b":"מחכמי שלוניקי-שנות ה-ר'-ש'."},{"i":53287,"n":"שידלוב, בנימין וולף","b":"דיין בווינה-ת\"ע"},{"i":53288,"n":"שידלוב, יצחק מטאכוי","bt":"תקעז","bp":"טוטשאפ","dt":"תרנט - כז חשון","dp":"טאכוי","b":"תלמיד הכת\"ס. רב בהוסטאון-תרח, טאכוי-תרטו."},{"i":53289,"n":"שידלף, ניסן מקאלין","b":"פרסם מאמרים ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב."},{"i":53290,"n":"שידקובסקי, חיים אהרן צבי מטומש","f":"אליעזר","bt":"תרכו","b":"רב בטומשוב-תרנה."},{"i":53291,"n":"שיוביץ, אברהם מנאפראד","f":"נחום מביסטריץ","bt":"תרנח","bp":"ביסטריץ","dt":"תשכו - יד סיון","dp":"ניו יורק","b":"תלמיד הדעת סופר, ור משה בונם קרויס מבאדן, ור יוסף צבי דושינסקי. חתן ר יחיאל צבי קראץ מאויבר-ווישווא ועבר לשם, וכיהן כראש הקהל. ניצל מהשואה ואחריה חזר לאויבר-ווישווא, רב בנאפראד. בזיוו\"ש חתן ר שמואל פרל מסיגט. עבר לצרפת, ניו יורק. חתנו - ר ישראל איסר אינדיך מסינסינטי-אוהיו."},{"i":53292,"n":"שיוביץ, נחום מזשיבוי","b":"רב בביטסריץ, זשיבוי."},{"i":53293,"n":"שיויליו, יהודה מקושטא","bp":"שלוניקי","dp":"קושטא","b":"תלמיד ר דניאל אישטרושא, מלמד תורה בקושטא-שנות ה-ת'."},{"i":53294,"n":"שיויליו, יהושע משלוניקי","dt":"תעג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53295,"n":"שיויליו, משה משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'-תק'. קרובו של ר נסים בעל \"מעשה נסים\"."},{"i":53296,"n":"שיויליו, נסים משלוניקי","f":"יהושע","k":"בעל מעשה נסים","bp":"שלוניקי","b":"דיין בשלוניקי-תפח עם ר דוד שירירו (סירירו), ור שמואל שלם. חתנו - ר משה לידידי, ודרשותיו צורפו לספר חותנו - \"מעשה נסים\" שלוניקי תקיז."},{"i":53297,"n":"שיויליו, עוזיאל משלוניקי","dt":"שצד - ו אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53298,"n":"שיזל, משה מקוסוב","b":"מחכמי קוסוב-תרצא."},{"i":53299,"n":"שיטלר, פנחס מטרנופול","dt":"תש..","b":"רב בטרנופול. חתן ר יעקב קופל לנדמן מטרנופול. נספה בשואה."},{"i":53300,"n":"שייאר, אברהם מרדכי ממושציסק","b":"מחכמי מושציסק-תרסא וראש הקהל לפני קיסטר. גיסו של ר ליב זנה. תלמידו - ר יהודה צבי קיסטר. פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":53301,"n":"שייאר, אברהם נפתלי הרץ ממגנצא","f":"דוד טבלי","k":"בעל תורי זהב","bt":"תקיג","bp":"פפד\"מ","dt":"תקפג-ב","b":"ר\"מ במגנצא-תקמג בחיי אביו, ורב על מקומו אחריו-תקנט. נספד מאת ר אברהם בנימין המבורג בספריו: \"מספד המשנה\", \"אלון בכות\"."},{"i":53302,"n":"שייאר, דוד טבלי (יעקב משה דוד)","f":"מיכל (מיכאל)","bt":"תעא","bp":"פפד\"מ","dt":"תקמג - כב תשרי","dp":"מיינץ","b":"תלמיד ר יעקב פופרש מפפד\"מ. חתן ר נתן אוטיץ מבומברג. דיין בפפד\"מ ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\", רב בבומברג-תקט על מקום חותנו ועזב בגלל הלשנה, ברלין, מיינץ-תקכח, ובנו ר הרץ אברהם נפתלי ר\"מ לצדו ועל מקומו אחריו. סירב לרבנות האגנאו והנובר. חתנו - ר גבריאל האהענעמס. בנו גם: ר מיכאל ממנהיים. מתלמידיו במיינץ - החת\"ס."},{"i":53303,"n":"שייאר, יהודה אריה ליב מפפד\"מ","bt":"תצג","dt":"תקפא - כו שבט","b":"מחכמי פפד\"מ, אב\"ד דטמולט, דיסלדורף והמדינה-תקן. הסכים על \"צל\"ח - פרג תקנד. מתורתו ב\"דברי אמונה\" פיעטרקוב תרסח. נספד מאת ר ליב קרלסבורג."},{"i":53304,"n":"שייאר, ליב יצחק מפפד\"מ","b":"מראשי קהילת פפד\"מ. היה במשלחת אל הקיסר יוזף השני-תקכו."},{"i":53305,"n":"שייאר, מיכאל","b":"רב-שנת ת\"פ"},{"i":53306,"n":"שייאר, מיכל (מיכאל) ממנהיים","f":"דוד טבלי ממגנצא","bt":"תצט","dt":"תקסט-ע","dp":"קרסלרוא","b":"ראש ישיבה במגנצא-תקלו - בזמן רבנות אביו, רב בוורמייזא-תקלח, מנהיים-תקמב וראש ישיבה. הניח דרשות בכת\"י. נפטר בהיותו בחנוכת ישיבה בקרלסרוהא. מתלמידיו במגנצא - החתם סופר."},{"i":53307,"n":"שייאר, משה מפפד\"מ","b":"מראשי קהילת פפד\"מ. היה במשלחת לכבוד הכתרת הקיסר יוזף השני-תקכו, עם חבריו ר ליזר לייטר ור זיסל קולפא."},{"i":53308,"n":"שייאר, צבי הירש","b":"רב במאינץ-תק\"צ (אולי הוא אברהם נפתלי הרץ?)"},{"i":53309,"n":"שייביץ, מרדכי","b":"מחכמי ירושלים, בשנת תסב בשליחות בברסלוי."},{"i":53310,"n":"שייבר, אלכסנדר מבודפשט","k":"בעל מקורות ותולדות י","bp":"דומבוואר","b":"מורה בביהמ\"ד לרבנים בבודפשט-1945 ומנהלו-1950. חוקר תולדות ישראל וספרותו בימי הביניים."},{"i":53311,"n":"שייטלס, אריה ליב","f":"נתן נטע","b":"רב בהורדנא-ת\"פ"},{"i":53312,"n":"שיין, אבא יהושע השל מגייוע","f":"שלמה יעקב","bt":"תרלו","dt":"תרפ - ה כסלו","b":"ר\"מ בגייעווא, רב בדנטובה-פלך קובנא-תרסח, ור אברהם פולטינוב הי\"ד על מקומו אחריו."},{"i":53313,"n":"שיין, הלל גבריאל","b":"בנו - ר שלמה יעקב בעל אבני שיש."},{"i":53314,"n":"שיין, יוסף","f":"זליג","bt":"1915","bp":"פוניבז","b":"תלמיד הגימנסיה האידית בוילקומיר. שחקן בתיאטרון היהודי במוסקבה. חיבר ספר על התיאטרון היהודי במוסקבה."},{"i":53315,"n":"שיין, יעקב מראסיין","f":"ישכר בר מראסיין","dt":"תרסב - כז שבט","dp":"ראסיין","b":"עסקן מחכמי ראסיין."},{"i":53316,"n":"שיין, יצחק מבאניהאד","f":"בנימין","bp":"בניהאד","dt":"תרסא - טו אדר","dp":"באניהאד","b":"תלמיד החת\"ס. מחכמי בניהאד ומלמד בישיבה שם. (נישא בניגוד לעצת רבו - גרמ\"מ מרגליות ב\"זכרון למשה\")."},{"i":53317,"n":"שיין, ישכר בער מראסיין","dt":"תקץ","dp":"ראסיין","b":"מחכמי ראסיין. בנו - ר יעקב."},{"i":53318,"n":"שיין, ישכר דב מהאליפאלווא","b":"תלמיד בעל \"עצי חיים\". רב בהאליפאלווא. נהרג עק\"ה-תרפד ע\"י חייל רומני ברכבת ליד קראלי. ונספד ע\"י ר שאול בראך מקראלי. חתנו ר אליהו וינברגר מירושלים קרא לספרו \"בן ישכר\" לזכרו."},{"i":53319,"n":"שיין, מאיר","b":"פרסם מאמרים ב\"התפוח\" - בנדין תרפח."},{"i":53320,"n":"שיין, מנחם מנדל מראטה","k":"בעל מנחת פתים","b":"מגדולי התורה בסלובקיה. סירב לרבנות קהילות גדולות, רב בראטה. חתנו ר ישראל איסר מפרשבורג-בן ר דניאל פרוסטיץ."},{"i":53321,"n":"שיין, מרדכי מברזן","b":"רב בבלשביץ."},{"i":53322,"n":"שיין, משה בר משוסבורג","f":"יוסף משוסבורג","bp":"שוסבורג","b":"תלמיד הכת\"ס, ור יהודה אסאד מסערדאוהל. הגיה בפרשבורג את הספר \"עקדת יצחק\". רב בקרעמז-תריד, קהילת וויעדען בוינה-תרכב."},{"i":53323,"n":"שיין, משה מביליץ","b":"רב בביליץ-תרמד."},{"i":53324,"n":"שיין, שלום הכהן מרינא-בסרביה","f":"אליהו","k":"בעל דברי שלום","bt":"תרלד","bp":"איזמאיל-בסרביה","b":"נסמך מאת: ר ברוך פולינובסקי מקישינב, ר יהושע בריסקין בעל \"תיו יהושע\", ר שמעון שלמה ורטהיים מבענדר. רב ברעני(=ריגא?)-בסרביה. פרסם מאמרים ב\"קול תורה\" - וארשא תרסח. חיבר גם \"שערי שלום\"."},{"i":53325,"n":"שיין, שלמה יעקב מקלם ולצקובה","f":"הלל גבריאל","k":"בעל אבני שיש","bt":"תריד-טו","bp":"גירטיגולה","dt":"תרצד-ט -כז אייר","dp":"קובנה","b":"תלמיד ר יעקב יוסף בישיבת וילון, ותלמיד ישיבות איישישוק וגרודנה. חתן ר ברוך פיבלסון. ר\"מ בקלם, טבריג(=טאווריג), רב בציטובאן(=ציטוביאן)-פלך קובנא-תרנג, לאצקווע(=לצקובה)-פלך קובנא-תרנט על מקום ר אברהם הורביץ. לתולדותיו \"מוריה\" תשסד."},{"i":53326,"n":"שיין, שמואל מזברז","k":"בעל משפחה במשפחה","b":"סופר. חיבר גם \"דיא צוויי שטיפבריעדער\", פרסם מאמרים בעתונים ומאספים."},{"i":53327,"n":"שיין, שמחה מפודגורזע","b":"מחכמי פודגורזע - תשובה אליו \"מנחת יחיאל\"."},{"i":53328,"n":"שיין-יפה, יצחק שמואל ממטרסדורף","f":"משה ממטרסדורף","bp":"מטרסדורף","dt":"תרפב - טז סיון","dp":"מטרסדורף","b":"תלמיד הכת\"ס, תלמיד וחתן דודו ר אהרן זינגר ממטרסדורף. מחכמי מטרסדורף."},{"i":53329,"n":"שיינבוים, אלישע (אילן-נאה)","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":53330,"n":"שיינבוים, יונה מאוסטריק","b":"ראש קהלת אוסטריק-ליד פרמישלא, חתם-תרלז על בקשה לעזרה לאחר השריפה-תרלה."},{"i":53331,"n":"שיינבוים, מאיר מירושלים","b":"מחכמי ירושלים-תרל."},{"i":53332,"n":"שיינברג חיים פנחס בן יצחק יעקב","bt":"1911","dt":"ה'תשעב 2012","bk":[["טבעת החושן",""],["מלואי אבן",""],["משמרת חיים",""],["שיעורי רבי חיים פנחס",""]],"e":"תר\"ע-תשע\"ב"},{"i":53333,"n":"שיינברגר יוסף","bt":"1918","dt":"ה'תשסז 2007","bk":[["אוצר החיים",""]]},{"i":53334,"n":"שיינגרוס, אהרן","b":"מו\"צ בוורשה-תר\"ע"},{"i":53335,"n":"שיינהוק, יוסף מסובאלק","f":"בנימין","k":"בעל תולדות הארץ","bt":"תקעב","bp":"טיקטין","dt":"תרלא - טו כסלו","dp":"סובאלק","b":"חיבר גם \"המשביר\", \"המלואים\"."},{"i":53336,"n":"שיינוק, חיים יואל מוידז","f":"רש\"ז","bt":"תרכג","b":"רב בנאסווקה-פלך צערניגוב-תרמז, וידז-פלך קובנא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":53337,"n":"שיינוק, כתריאל משה מוילנא","bp":"מיכיילישוק","dt":"תרן - ז סיון","dp":"וילנא","b":"גביר בוילנא. הקים בימ\"ד בחצרו והחזיק בו לומדי תורה. גיסו-חתן אחותו של ר ישראל אידל זרחי מאנטקלייע."},{"i":53338,"n":"שיינין, אליעזר יהודה","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":53339,"n":"שיינין, ישראל איסר מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":53340,"n":"שיינין, ליב","dt":"תשג","b":"רב בדאקשיצע"},{"i":53341,"n":"שיינס, אברהם משקלוב","b":"רב בשקלוב"},{"i":53342,"n":"שיינס, יוסף אהרן מטשערי","f":"אברהם משקלוב","b":"רב בטשערי-פלך מוהילוב."},{"i":53343,"n":"שיינס, צבי הירש מאילע","f":"יוסף אהרן מטשערי","b":"רב באולע(=אילע)-פלך ויטבסק-תרכ. חתנו - ר יוסף חיים בן שאול בלוך."},{"i":53344,"n":"שיינס, שלמה זלמן זיסל","f":"צבי מאילע-פלך ויטבסק","bt":"תרטז","b":"רב בטשערי-תרלט על מקום זקנו - ר יוסף אהרן, לעפעלי(=ליעפלי)-פלך ויטבסק-תרמט, דוברוונה(=דובראוונא)-פלך מוהילוב-תרנה, וויעליז-תרס, טשאשניק(=צאשניק)-פלך ויטבסק-תרס. חיבר ספר על הלכות מקואות - בכת\"י."},{"i":53345,"n":"שיינערט, אפרים מזולקוא","b":"דיין בזולקוא אצל ר יעקב אורנשטין-תקסד. הסכים על \"זהר חדש\" תקסז - עם ר יצחק שמשון בן פסח מראווע, ר יוסף שטרן מזוקלוא ור יוסף אלעזר גוטליב מזולקוא."},{"i":53346,"n":"שיינפינקל מקרלין","b":"גביר מחכמי קרלין. חתנו - ר אליהו וולפסון."},{"i":53347,"n":"שיינפינקל, בנימין","b":"חתן ר משה הלוי לוין מהלוסק. בניו - ר יעקב קופל, ר חיים אכסעס מקרלין."},{"i":53348,"n":"שיינפינקל, חיים אכסעס מקרלין","f":"בנימין","b":"חתן ר שלמה זלמן ליפשיץ מסלוצק. רב וגביר בקרלין."},{"i":53349,"n":"שיינפינקל, יעקב קופל","f":"בנימין","b":"חתן ר יהושע רוקח מפינסק. אחיו - הגביר ר חיים אכסעס מקרלין."},{"i":53350,"n":"שיינפינקל, שאול יחזקאל מקרלין","b":"רב בקרלין. חתן - ר אליעזר לוי הלפרין משארשוב."},{"i":53351,"n":"שיינפרוכט, ישעיה","b":"רב ביעכוב-תרמ\"ו"},{"i":53352,"n":"שיינקאפ, משה דן מארה\"ב","k":"בעל גליונות","b":"רב בספרינגפילד-אוהיו. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"המתיבתא\" - נ\"י תשג, \"קונטרס מיוחד\" - נ\"י תשא - דברי תורה מועידת המזרחי."},{"i":53353,"n":"שייקביץ, נחום מאיר מפינסק","b":"סופר בפינסק, היגר לארה\"ב עם בנו - אברהם שמ\"ר."},{"i":53354,"n":"שילה","b":"מגדולי הראשונים בחכמי יון-ד'תת\"ק"},{"i":53355,"n":"שילה מתימן","f":"טוב","dt":"תרם - בערך","dp":"עדן","b":"דיין בעדן-תימן - באמצע המאה ה-19."},{"i":53356,"n":"שילה, ישראל יעקב מאזמיר","dt":"תקמז - י אדר","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":53357,"n":"שילוירה, יצחק מאזמיר","b":"ראשון המאמינים בשבתי צבי-תח."},{"i":53358,"n":"שיליא, דב בריש מדמביץ","b":"רב בדמביץ-תרן."},{"i":53359,"n":"שילינג, מרדכי מדולינא","b":"שו\"ב בדולינא - תשובה אליו \"אבן יקרה\"."},{"i":53360,"n":"שילל, יהושע ליב מפעזינג","f":"משה שמואל מפרשבורג","k":"בעל מנהגי בעל החת\"ס","bt":"תרמו","bp":"פרשבורג","dt":"תשד","b":"תלמיד הדעת סופר. חתן דודו ר יואל גלבר מפרשבורג. מג\"מ בפרשבורג-תרסד, וינה, רב בפעזינג-תרעג. נספה בשואה."},{"i":53361,"n":"שילל, מאיר טוביה","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":53362,"n":"שילל-שילר, משה שמואל מפרשבורג","f":"יהושע יהודה ליב מראב","k":"בעל ששים אלף","bt":"תר","dt":"תרפז - י תמוז","dp":"פרשבורג","b":"תלמיד הכת\"ס. חתן ר בנימין זאב גרינספלד מפרשבורג. עסק במסחר והיה מחכמי פרשבורג ובעל קורא ביבהמ\"ד של הישיבה כארבעים שנה."},{"i":53363,"n":"שילם געלקין מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":53364,"n":"שילמס, יוסף מבריסק","b":"מחכמי בריסק-שצב-תיב."},{"i":53365,"n":"שילר, ענזיל מיכאל מאלטנהויזן","b":"מוהל באלטענהויזן-תקץ, בפנקס המוהל שלו מספר שלמד אצל המוהל ר בנימין נידרהופהיים מפפד\"מ, ואצל ר מרדכי נארדהיימר ממאלסדורף."},{"i":53366,"n":"שילר, שלום","b":"רב בעפעריעס-תר\"ח"},{"i":53367,"n":"שימון ן, אהרן מאלגיר","b":"רב באלגיר, נזכר ב\"אהל יעקב\" לר יעקב ששפורטש כ\"ספרא רבא\"."},{"i":53368,"n":"שימונוביץ, חנוך הניך מפוחאויטש","f":"מרדכי יהושע זליג","bt":"תרלא","b":"רב בפוחאוויטש-פלך מינסק-תרנב."},{"i":53369,"n":"שימונוביץ, ישעיה מניו יורק","k":"בעל עמודי שיש","b":"ניצל מהשואה והגיע לשנחאי-סין. ר\"מ בישיבת \"תורה ודעת\" בניו יורק-תשמט. פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה, \"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":53370,"n":"שימונוביץ-רטושני, אברהם מטורקא","b":"רב בטורקא - נמנה על 25 היהודים הראשונים שהורשו להתישב בטורקא-תפט."},{"i":53371,"n":"שימחוביץ, אלתר מירושלים","b":"משפיע בישיבת \"תורת אמת\" בירושלים. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":53372,"n":"שימחוביץ, צבי הירש ממינסק","f":"חיים","k":"הירשלא ר חיימקעס","b":"חתן ר שמואל ר חיימ ר שבתיל'ס לנדא מוילנא. מחכמי מינסק."},{"i":53373,"n":"שימחוביץ, שמואל","b":"חתן ר שכנא בן יונה איסרלין. גביר ותלמיד חכם."},{"i":53374,"n":"שימל, בנימין","f":"יהודה אליהו","dt":"תשמד","b":"בנו ר חיים שימל מלונדון."},{"i":53375,"n":"שימל, מנחם מנדל מקראקא","f":"חיים שמואל מקראקא","bt":"תרעה","bp":"קראקא","dt":"תשנה","dp":"בני ברק","b":"חסיד בלז. תלמיד ר יהושע מנחם ארנברג בקראקא. ניצל מהשואה ואחריה רב בקראקא, עלה לארץ-תשיא והתישב בפתח תקוה."},{"i":53376,"n":"שימשוביץ, יהודה ליב","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":53377,"n":"שימשלביץ - שמשי, צבי","f":"ראובן ישראל","k":"בעל זכרונות - תרצח","bt":"1862","bp":"סמרגון","dt":"1953","dp":"ירושלים","b":"עבר לפולטבה-אצל משפחת אשתו - עטרה קופלוביץ. הצטרף ל\"חובבי ציון\", ו\"בני משה\". ביקר בארץ-תרנא, ותרסה לצורך גאולת אדמות יוקנעם (העסקה הוכשלה ע\"י השלטון התורכי). נאסר-תרסו עם אשתו על פעילות ציונות והשתתפות ב\"הגנה\" והוגלו לסיביר. עלה לירושלים-תרצג. פרסם מאמרים בעתונות. חיבר גם ספר יוחסין למשפחות שמשי, בן צבי, ראובני, ועוד. בניו: יצחק בן צבי - נשיא מדינת ישראל, אהרן ראובני - סופר וחוקר, חתניו: ד\"ר יצחק קלוגאי, והפרופ' בנימין מזר."},{"i":53378,"n":"שימשלביץ, ב\"צ מליטא","bp":"קופצאווה-ליטא","b":"תלמיד ר ישראל סלנטר. תלמיד חכם מקפוצאווה וסוחר יערות מפורסם בליטא - ואיש מוסר למופת. ר אברהם צבי פנחס אליאשברג הרב סיפר כי היה רגיל לבוא לשאול אותו \"לימדני רבי אם הרובל הזה כשר הוא אם לאוו..\"."},{"i":53379,"n":"שינברג, אברהם","b":"פרסם מאמרים ב\"המאור\" - תל אביב תרצה."},{"i":53380,"n":"שינברג, בנימין ביניש מקראקא","dt":"תרעו","b":"נשיא א\"י בקראקא."},{"i":53381,"n":"שינברג, יעקב מזלין","dt":"תרכז","b":"רב בזלין. נפטר ללא ילדים."},{"i":53382,"n":"שינברג, משה דוד ממארוש ואשארהי","f":"ישראל מהומנא","bt":"תרלו","bp":"הומנא","dt":"תשד - ו סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור שמואל רוזנברג מאונסדורף. חתן ר דוד יהודה פולק ממאדיאר-לאפוש ועבר לשם, וכיהן כדיין. בזיוו\"ש חתן ר משה שטיין מערדא-סענזשארץ. רב במאראש-ואשארהעלי-תרעב. נספה בשואה."},{"i":53383,"n":"שינברג, נטע זאב מסעלץ","b":"מראשי קהלת סעלץ ומקורב לגדול ממינסק בשבתו בסעלץ."},{"i":53384,"n":"שינברג, ניסן מברנוביץ","k":"רבי נישה דיין","dt":"תשג","b":"דיין בברנוביץ, ורב קהלת חסידי סלונים, יו\"ר \"בית יעקב\" ומלמד שם. נספה בשואה בשושן פורים - בזמן הטבח מזג כוס שתיה אמר ליהודים סביבו אל תשכחו שפורים היום והחל לרקוד ונהרג בזמן ששר שושנת יעקב. מאמר עליו ב\"אלה אזכרה\"."},{"i":53385,"n":"שינברג, נתן מגלינא","b":"מחכמי גלינא-תרטז."},{"i":53386,"n":"שינברג, נתן מלבוב","f":"אליעזר הרופא שלי\"ט","dt":"שפב - ב טבת","dp":"לבוב","b":"דיין בלבוב. חתם על פס\"ד עם ר יעקב קצנלנבוגן."},{"i":53387,"n":"שינברג, פנחס מניו יורק","k":"בעל טבעת החושן","b":"רב בניו יורק-תשיא."},{"i":53388,"n":"שינברגר, ברוך מפרשבורג","b":"מעסקני האגודה הציונית \"יגדיל תורה\" (ששינתה שמה ל\"אהבת ציון\") בפרשבורג - אחרי תרנז - שעסקה בלימוד גמרא למשתתפיה."},{"i":53389,"n":"שינברגר, יוסף מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא, \"תבונה\" - ירושלים תשא-תשח."},{"i":53390,"n":"שינברגר, מנחם מאניש מירושלים","f":"ברוך מפרשבורג","k":"בעל תקון שבת","bt":"תרג","bp":"פרשבורג","dt":"תרנט - ב ניסן","dp":"ירושלים","b":"תלמיד הכת\"ס, ומהרם שיק. עבר למארגרעטן-תרכג, שו\"ב בסיקסא, עלה לירושלים-תרכז, ופתח תקוה. אבי משפחת שנברגר מירושלים."},{"i":53391,"n":"שינברגר, משה דוב מואשרהאלי","dt":"תשד","b":"דומ\"צ בוואשארהעלי-תרע\"ד"},{"i":53392,"n":"שינברגר, פנחס צבי מירושלים","b":"מראשי העדה החרדית בירושלים."},{"i":53393,"n":"שינברגר, צבי דב הלוי משאמלוי","dt":"כו תשרי","b":"תלמיד ר מנחם א\"ש מאונגוואר. דיין בשאמלוי(=שומלא)-תרעד."},{"i":53394,"n":"שינדלינגר, שמואל מסאל (סאליר)","f":"אברהם","k":"בעל שם משמואל","bt":"תעה","bp":"דוברומיל","dt":"תקנו - ג אב","dp":"לבוב","b":"תלמיד ר שלמה דב מגלוגא (שהיה כנראה חותנו). רב בסאהל(=סאלע), לבוב - והיה דיין אצל ר צבי הירש רוזניס. הסכים על \"מצות השם\"-לבוב תקנב, \"קצות החושן\"-תקמח, \"מחוקק יהודה\"-לחתנו. מתלמידיו - ר יעקב משה ארנברג מפרמישלא, רא\"ל מלנצהוט, ור צבי הירש חריף. בניו: ר נתן הכט, ר יהודה יודל, ר אברהם אבלי, וחתנו ר יהודה אוירבך בעל \"מחוקקי יהודה\". חיבר \"שם משמואל\" למברג תקעז."},{"i":53395,"n":"שינדלר, אברהם מרישא","dt":"תש..","b":"רב בקלויז צאנז ברישא. סוחר ועסקן ציבור והקים ישיבה בעירו-תרסה - והעמיד בראשה את ר מנדל רייך. נספה בשואה."},{"i":53396,"n":"שינדלר, אליעזר מטיטשין","f":"אברהם יצחק","bt":"תרן","bp":"טיטשין","b":"מצאצאי בעל \"אור פני משה\" מפשוורסק. עבר עם הוריו למינכן-תרנח. ממיסדי אגודת \"בני יהודה\" לחיזוק שפת האידיש. בנו אלכסנדר משה היה מנהיג התנועה הריפורמית בארה\"ב. חיבר שירים ומאמרים בעתוני זמנו. ברח מהנאצים והתישב בארה\"ב-תרצח והתיישב בלייקווד. חיבר |יידיש או חסידיש\" ניו יורק תשי, ספר שירים \"דערנער\" תרעב וחתם \"בן גולה\"."},{"i":53397,"n":"שינדלר, חיים סגל מצאנז","b":"רב בצאנז. תשובה אליו ב\"מנחת יצחק\"."},{"i":53398,"n":"שינדלר, יוסף מסאגאד","dt":"1963","b":"רב ניאולוגי בקאצ'קאמאט, לאחר השואה חזר לקהילה ואיחד את שרידי הקהילות הניאולוגית והחרדית לקהילה אחת, רב בסאגאד-1950 על מקום ד\"ר יאנו פרנקל וטאמאש ראיי על מקומו אחריו. אסף חומר על יהדות סאגאד, ערך את חוזרי אגודת הרבנים בערי המחוז-צ'ונגראד."},{"i":53399,"n":"שינדלר, מנחם מרישא","f":"חיים זאב","bt":"תרסח","bp":"רישא","b":"עלה לירושלים-תרצג וכיהן כמנהל מחלקת הנישואין בירושלים."},{"i":53400,"n":"שינהויז, אריה ליאון","k":"בעל תולדות אהרן","bt":"1867","bp":"רדושקביץ-פלך וילנא","dt":"1937","dp":"ממל","b":"התישב בממל עם אחיו-באנו, האח עסק במסחר והוא עסק בספרות וביבליוגרפיה. פרסם מאמרים ב\"המגיד\", \"הצפירה\", ועוד. פרסם גם בעתונות הגרמנית. מנכבדי הקהלה בממל, יסד את ה\"ליטעראטור פעראין\" בממל, וחברה בשם \"דוברי עברית\"."},{"i":53401,"n":"שינהורן, צבי","b":"תשובה אליו ב\"שואל ומשיב\"."},{"i":53402,"n":"שינורא די, מאיר","b":"מחכמי צפת-תקכ\"ד"},{"i":53403,"n":"שינמן, יצחק מאולינוב","b":"רב באולינוב, יסלו-תרנה."},{"i":53404,"n":"שינמן, פנחס מפודגורזע","f":"צבי הרש","k":"בעל דעת פנחס","bt":"תרעב","bp":"פודגורזע","dt":"תשס","b":"ממיסדי השומר הדתי ופעיל במזרחי. נואם מבוקש וערך מסעי הרצאות. חתן ר משה דוד פרנקל-לנדא מבריגל. ניצל מהשואה - גלו לסיביר. עלה לארץ-תשח ונעשה רב בתל אביב ויו\"ר המועצה הדתית שם. חיבר \"דעת פנחס\" תשסא."},{"i":53405,"n":"שינמן, שמואל יוסף מני\"י - שי\"ש","k":"בעל עמודי שיש","b":"רב בניו יורק. חיבר \"עמודי שיש\" באנגלית ואידיש."},{"i":53406,"n":"שינפלד שלמה יצחק בן אהרן","bt":"1860","dt":"ה'תשג 1943","bk":[["האדם המעלה",""],["עולם השקר",""],["ציונים בדרך החיים",""]]},{"i":53407,"n":"שינקמן, אליעזר מטרשקון","dt":"תש..","b":"רבה האחרון של טרשקון-ליטא. נספה בשואה. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":53408,"n":"שינקמן, ישראל מליטא וארה\"ב","k":"בעל תפארת ישראל","b":"תלמיד ישיבת סלובודקה, וולוזין, איישישוק. רב בפוסבול, פוניבז, קובנא. היגר לארה\"ב וכיהן כרב באטלנטיק סיטי."},{"i":53409,"n":"שינר, אפרים מזולקוא","b":"דיין בזולקוא אצל ה\"ישועות יעקב\" המזכירו בספרו \"הלכות ציצית\"."},{"i":53410,"n":"שינר, יוסף כץ מזורובנא","b":"מחכמי זורובנא-תרמא."},{"i":53411,"n":"שיסגל, אברהם יצחק מארה\"ב","f":"דוד","bt":"תרנ","bp":"רוסטוב","b":"תלמיד ישיבת סלובודקא, סלוצק. נסמך מאת: הרידב\"ז, ר משה מרדכי אפשטין, ר איסר זלמן מלצר. חתן ר אלימלך הלוי. רב ברוסטוב-תרעו, היגר לארה\"ב-תרפו וכיהן כרב בפוטוקט-רוד איילנד, ברוקלין-תרצד. חבר אגודת הרבנים באמריקה, ואגודת ישראל. בניו - ר אליהו משה-חתנו של ר משה פיינשטין, ר דוד."},{"i":53412,"n":"שיסגל, אליהו משה","k":"חתן ר' משה פיינשטיין","b":"ר\"מ בתפארת ירושלים בניו יורק"},{"i":53413,"n":"שיסגל, יהושע מניו יורק","k":"בעל עירוב והוצאה","b":"רב בניו יורק-תרסז."},{"i":53414,"n":"שיסל, מנשה בר מקלוש","b":"רב בקלוש על מקום ה\"חוות דעת\"."},{"i":53415,"n":"שיסקס, אברהם מוילנא","f":"שאול שיסקש מוילנא","b":"חתן ר אריה ליב מפלאצק. מחכמי וילנא."},{"i":53416,"n":"שיסקס, אליעזר אשכנזי","dp":"לובלין","b":"בניו: ר מאיר ור שאול שיסקס."},{"i":53417,"n":"שיסקס, אליעזר לייזר מוילנא","b":"הביא לקבורה בוילנא את שרידי גר הצדק אברהם - הגרף פוטוצקי שעלה על המוקד-תקט."},{"i":53418,"n":"שיסקס, מאיר מוילנא","f":"אליעזר אשכנזי מלובלי","dt":"תקצא - י תשרי","dp":"וילנא","b":"נכד ר יהודה אריה משאד. מגדולי וילנא. אולי הוא שהיה תלמיד הגר\"א, והו\"ל מתורת הגר\"א \"אליהו רבא\" ופירוש לתוספתא - זולקוא תקסד, והגר\"א כתב עליו שישב בביתו זה חמש שנים וכו'."},{"i":53419,"n":"שיסקס, שאול (שואל) מוילנא","f":"אליעזר או יהודה ליב","k":"בעל שביל הישר","dt":"תקנז - א ניסן","dp":"וילנא","b":"נכד ר משה חר\"ז מוילנא. מגדולי חכמי וילנא. בנו ר אברהם, ר צבי הירש-שנפטר בחיי אביו. חתנו ר יצחק בן שבתי שפטיל. ר שלמה זלמן-אחי ר חיים מוולוזין הגיה את ספרו בהיותו בן 21 והעיר בפני ר שאול הערות ומילואים."},{"i":53420,"n":"שיסר, אברהם מהמבורג","f":"יוסף","dt":"תפח - כד טבת","dp":"אלטונא","b":"דיין בהמבורג, מו\"ץ על מקום ר משה רטונבורג."},{"i":53421,"n":"שיף דוד טבלי בן שלמה זלמן","bt":"1720","dt":"ה'תקנא 1791","bk":[["לשון זהב",""]]},{"i":53422,"n":"שיף, אברהם אבא ממינסק","f":"אליהו ממינסק","k":"בעל תועפות ראם","bt":"תריח","bp":"מינסק","b":"תלמיד ישיבות ליטא. ר\"מ במינסק בביהמ\"ד הגדול. חיבר פירוש לספר יראים לר אלעזר ממיץ (מכת\"י פאריז) בשם \"תועפות ראם\"."},{"i":53423,"n":"שיף, אברהם אליקים גצל מרודניק","f":"מרדכי מבלוזוב","k":"בעל חמשה שערים","bt":"תרנח","bp":"בלוזוב","dt":"תשמו","b":"חסיד צאנז. תלמיד ר שלמה ליב מטיטשין ור אריה מאיר הורביץ מבלוזוב. חתן ר זאב בוק מחסידי גורליץ בניסקא (שיר אודות אשתו פרידא מאת נכדה - א.ב. \"צאנז\"). מחכמי רודניק וכיהן כרב בפועל. ניצל מהשואה ואחריה כיהן כרב באפעלן-פולין, היידנהים - שם פגש את רבו האדמור מקלויזנבורג שהורה לו לקבל תפקיד יו\"ר אגו\"י בגרמניה. עלה לירושלים-תשי והתגורר במאה שערים. חיבר \"ה' שערים\" ירושלים תשלה."},{"i":53424,"n":"שיף, אברהם אליקים מבלוזוב - א","f":"דוד מקריפטש","bt":"תקל","dt":"תקץ","dp":"קריפטש","b":"תלמיד ר זושא מאניפולי. עבר לסטריזוב ולפריסטיק אל ר מנחם מנדל מרימנוב (שם בירך אישה ואביו שחשש מהקפדת רמ\"מ מרימנוב שלחו ללובלין עד שהחוזה שלחו בחזרה). רב בבלוזוב, בנו ר מרדכי על מקומו אחריו."},{"i":53425,"n":"שיף, אברהם אליקים מבלוזוב - ב","f":"מרדכי מבוקובסק","b":"נכד זקנו בעל אותו השם. נתייתם בילדותו וגדל אצל רבו ר אשר מרופשיץ. התישב בבלוזוב וכיהן כשו\"ב אך לא כיהן כרב - בהוראת רבו."},{"i":53426,"n":"שיף, אורי פיבוש מפרנקפורט","f":"יעקב כהן צדק","bt":"אבי","dt":"רמא"},{"i":53427,"n":"שיף, אלימלך מירושלים","b":"מצאצאי הנועם אלימלך. הקים בשכונת רמות בירושלים בימ\"ד ע\"ש ליזנסק."},{"i":53428,"n":"שיף, אלימלך מליזנסק במיהא-פלוא","f":"שמעון האדמור מליזנסק","k":"אדמור מליזנסק במיהל-","dt":"תש..","b":"חתן ר יצחק מבוארשא (נדבורנא). אדמור מליזנסק במיהאי-פאלווא. נספה בשואה."},{"i":53429,"n":"שיף, אליעזר מביקסאד","bp":"מאסיף","b":"ראש ישיבה בסטמר לפני השואה. ר חיים יצחק מאליק היה ר\"מ אצלו בישיבה."},{"i":53430,"n":"שיף, בן ציון מאנטורפן","f":"שמעון מקלויזנבורג","dt":"תשג","b":"בנו של האדמור מקלויזנבורג. יהלומן באנטורפן-תרפז, חסיד בלז נספה בשואה."},{"i":53431,"n":"שיף, בן ציון מליזנסק באנטורפן","f":"שמעון מקלויזנבורג","k":"אדמור מליזנסק באנטור","dt":"תש..","b":"אדמור מליזנסק באנטורפן. נספה בשואה."},{"i":53432,"n":"שיף, בנציון מוינה","b":"נשיא השיף שוהל בוינה. חתן ר שמואל וייס ממיאווע. גיסו של ר יעקב עקיבא סופר ממיאווע בן הכת\"ס."},{"i":53433,"n":"שיף, גבריאל מצעהלים","dp":"צעהלים","b":"חתנו - ר בנימין וולף פפנהים ראש הקהלה שיף-שוהל בוינה."},{"i":53434,"n":"שיף, דוד","f":"חיים","b":"חתן ר אברהם גבירצמן מגורליץ."},{"i":53435,"n":"שיף, דוד טבלי הכהן מלונדון","f":"שלמה זלמן מפפד\"מ","k":"בעל לשון זהב","bp":"פפד\"מ","dt":"תקנב - כג כסלו","dp":"לונדון","b":"תלמיד ר יעקב פופרש ור יעקב יהושע בעל \"פני יהושע\". חתן ר יצחק זינצהיים מפפד\"מ-אחיו של ר ליב מוורמייזא ועבר לשם והיה ר\"מ בביהמ\"ד של ר ליב בוורמייזא. דיין בפפד\"מ, רב ראשי בלונדון-תקכה. אחיו - ר מאיר, וגיסו ר בער אדלר. חברו של ר נתן מאז מפפד\"מ והתייעץ עמו רבות בחילופי מכתבים ביניהם. חיבר \"לשון זהב\" ונדפס ע\"י ר גבריאל אדלר ממירנגן שהיה בן אחיינו. מתלמידיו - ר נתן בן שמעון אדלר.","bk":[["לשון זהב",""]]},{"i":53436,"n":"שיף, דוד מזמיגרוד","f":"אברהם אליקים מבלוזוב","b":"רב בזמיגרוד-תרן."},{"i":53437,"n":"שיף, דוד מקריפטש","f":"אברהם אליקים","bt":"תק","dt":"תקפד - יג תמוז","b":"דור חמישי ל\"מגיני שלמה\". תלמיד ה\"נועם אלימלך\", ר מנחם מנדל מרימנוב והחוזה מלובלין. נחשב בדורו לאחד מ-ל\"ו צדיקים. רב בקריפטש. הבני\"ש קרא לבנו \"דוד\" על שמו. חתנו ותלמידו ר אברהם גלר על מקומו אחריו. בניו: ר צבי, ר אברהם אליקים אב\"ד בלוזוב. לתולדותיו \"עטרת דוד\" מנכדו יעקב מאיר מרדכי פלדשטין - ניו יורק תשנו."},{"i":53438,"n":"שיף, זאב דב מזמושץ הלפרין","f":"צבי הירש הלפרין","k":"בעל מנחת זכרון","bt":"תקכח","bp":"זמושץ","dt":"תרב - יב שבט","dp":"קראקא","b":"שינה שם משפחתו לשיף. תלמיד בעל \"מרכבת המשנה\" ובעל \"פרי תבואה\". חתן ר אברהם ב\"ר אליעזר. גיסו בזיוו\"ש של ר אפרים זלמן מרגליות. סוחר עשיר ותלמיד חכם. תלמיד ר צבי הירש הלר בעל \"טיב גיטין\" (ודאג למינוי רבו כרב בבריגל וברודי). התרושש במלחמת השבדים, ושימש מגיה בוינה אצל אנטון שמיד, עבר ללמברג ולקראקא. ידיד למהרש\"ק ולרנ\"ק (אך לא הצליח להסיר את חרם הישוע\"י כנגדו). בנו ר ישעיה היה חתנו של ה\"ברוך טעם\". חיבר \"מנחת זכרון\" קראקא תרנד."},{"i":53439,"n":"שיף, זאב דב מלנצהוט","b":"רב בלנצהוט, בנו ר יצחק צבי הרש. חתן ר שלמה זלמן פרנקל מויליפולי."},{"i":53440,"n":"שיף, זנוויל הכהן","f":"מאיר שיף","dt":"תל"},{"i":53441,"n":"שיף, חיים","f":"יוסף מטורנא","dt":"תרפד - בערך","b":"מצאצאי ר דוד שיף מקריפטש. חתן ר נפתלי מליזנסק. בניו ר שמעון האדמור מליזנסק בקלויזנבורג, ור דוד."},{"i":53442,"n":"שיף, יהודה מבובוב","f":"ישעיה מקרשוב","b":"נכד ה\"ברוך טעם\". רב בבובוב-תרמב, ועל מקומו אחריו האדמור ר שלמה הלברשם. בנו ר חיים - ר\"מ בישיבת בובוב."},{"i":53443,"n":"שיף, יוסף","f":"יעקב מנביליץ","b":"רב בנביליץ-תרמב על מקום אביו."},{"i":53444,"n":"שיף, יוסף הרץ מפפד\"מ"},{"i":53445,"n":"שיף, יוסף מטורנא","f":"משה שמואל","b":"חסיד צאנז, מחכמי טורנא."},{"i":53446,"n":"שיף, יוסף מפפד\"מ","b":"מחכמי פפד\"מ-תפ בערך."},{"i":53447,"n":"שיף, יעקב הכהן מפפד\"מ","f":"אורי","dt":"תטו - יח כסלו","dp":"פפד\"מ","b":"מרביץ תורה, ראב\"ד בפפד\"מ, ור מנדל בס על מקומו אחריו. אביו של המהר\"ם שיף."},{"i":53448,"n":"שיף, יעקב יצחק מוינה","f":"בנציון מוינה","bt":"תרלב","bp":"וינה","dt":"תרפז","b":"תלמיד השב\"ס. דודו - ר יעקב עקיבא סופר ממיאווע. מחכמי וינה."},{"i":53449,"n":"שיף, יעקב כהן צדק מפרנקפורט","bt":"קל","b":"אבי משפחת שיף מפרנקפורט שעסקו בחלפנות והיו תלמידי חכמים."},{"i":53450,"n":"שיף, יעקב מנבליץ","f":"אברהם אליקים מבלוזוב","bt":"תקס","dt":"תרמב","b":"רב בנעבליץ-תרל, בנו ר יוסף על מקומו אחריו, וכן ר שמואל שיף."},{"i":53451,"n":"שיף, יעקב מניו יורק","f":"משה","k":"מונטיפיורי האמריקני","bt":"1847","bp":"פפד\"מ","b":"היגר לארה\"ב-1865 והתעשר ממסחר בשטרות. גביר נדבן ותרם למוסדות צדקה, לביהמ\"ד לרבנים בניו יורק, יסד מחלקה עברית בספריה העירונית בניו יורק, סייע בהקמת ת\"ת בניו יורק, תרם לפליטים יהודים במקדוניה-תרלח שברחו לשלוניקי. נפגש עם המלך אדוארד מאנגליה-1904 בביקורו בלונדון."},{"i":53452,"n":"שיף, יצחק צבי הירש מויליפולי","f":"וולף מלנצהוט","k":"אדמור מויליפולי","b":"חתן ר שלמה זלמן יוסף פרנקל האדמור מויליפולי על מקום חותנו."},{"i":53453,"n":"שיף, ישעיה אשר חיים מבוקובסק","f":"מרדכי אלימלך הלוי","bt":"תרסה","dt":"תשנג","b":"חתן ר יהודה גרשון לעזער מקאשוי. ניצל מהשואה ובזיוו\"ש חתן ר יקותיאל יהודה גרינפלד ממונקטש. עלה לארץ-תשט והתישב בפתח תקוה."},{"i":53454,"n":"שיף, ל'","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":53455,"n":"שיף, מאיר הכהן","k":"בעל דרך אניה","dt":"תקסז - ט אב","dp":"פפד\"מ","b":"חתן ר שלמה זינצהיים, וגיסו של ר דוד טבלי שייאר. רב ביהכ\"נ ע\"ש ליב רייס בפפד\"מ, וראב\"ד בפפד\"מ והדיינים שעמו ר מאיר זאמושט-בס ור ליזר וואלוי. בן אחיו של ר דוד טבלי מלונדון."},{"i":53456,"n":"שיף, מאיר הכהן מפולדא","f":"יעקב יוקב מפפד\"מ","k":"מהר\"ם שיף","bt":"שסה (או שנז)","bp":"פפד\"מ","dt":"תא - כא אדר","dp":"פפד\"מ","b":"מיודד עם ר שבתי שפטל הורביץ בעל \"ווי העמודים\". רב בפולדה-שפב (בגיל 17), מחכמי פפד\"מ, הוזמן לרבנות פרג ונפטר בדרכו לשם. רבים מכתביו אבדו בשרפה בפרנקפורט. נפטר בגיל 36. בנו היחיד נפטר ללא ילדים וחתנו שינה שמו לשיף כדי להנציח את חותנו ומצאצאיו ר יחיאל מיכל שטרן כץ שהביא לדפוס כתבי זקנו. מצאצאיו גם: ר יונתן איבשיץ, ר דוד טבלי הכהן בעל \"לשון זהב\". והבנקאי צבי הירש (הנרי) בניו יורק. ר מרדכי מורדאש מפאריצק חיבר ביאור לספריו.","bk":[["מהר\"ם שיף",""]]},{"i":53457,"n":"שיף, מרדכי אלימלך מפטריווא","f":"אשר ישעיה מבוקובסק","bt":"תרלט","bp":"בוקובסק","dt":"תשה","b":"תלמיד ר משה הלברשטם בברדיוב. חתן ר שלום זינגר מפטריווא והתיישב שם. נספה בשואה."},{"i":53458,"n":"שיף, מרדכי מארה\"ב","f":"חיים צבי","k":"בעל מחקרי מרדכי","bp":"לייזעווע-ליטא","b":"תלמיד ישיבת טלז, סלובודקא, וולוזין. נסמך מאת: ר נחמן שמואל מאדאסער בעל \"עמודי שמואל\", ר חיים פישל אפשטין מסייני בעל \"תשובה שלמה\" ר שלום איזראלסון בעל \"דברי שלום\". חתן ר גרשון ועגער-אב\"ד ועגער-ליטא. היגר לארה\"ב, רב בסינסינטי על מקום ר חיים פישל אפשטין-שעזב. חיבר גם \"עטרת מרדכי\"."},{"i":53459,"n":"שיף, מרדכי מבלוזוב - הזקן","f":"אברהם אליקים מבלוזוב","b":"רב בבלוזוב על מקום אביו. תלמיד בעל \"מלוא הרועים\", ור נפתלי מרופשיץ. חברו של הדברי חיים. רב בבוקובסק. כתביו אבדו בשואה."},{"i":53460,"n":"שיף, מרדכי מבלוזוב - הנכד","f":"אברהם אליקים מבלוזוב","dt":"תרץ","b":"נכד זקנו בעל אותו השם. חתן ר אליעזר אלסטר מקורטשין. חסיד שינאווא."},{"i":53461,"n":"שיף, מרדכי מזוהביץ","b":"רב בזוהביץ, זברז-תקנד ושם ישב כדיין עם ר ישעיה ב\"ר אליעזר ליפמן ו דוד שו\"ב ב\"ר מאיר אצל האב\"ד הרב יוסקא."},{"i":53462,"n":"שיף, משה","dt":"תרטז - כב תשרי","b":"רב ברוגנסדורף"},{"i":53463,"n":"שיף, משה דוד מפריסטיק","f":"יעקב","k":"בעל אנשי שם","bt":"תרעב","bp":"פריסטיק","dt":"תשנד","b":"חסיד בובוב. תלמיד בישיבת טשבין. עלה לארץ-תרצה ולמד בישיבת מרכז הרב. חתן ר ברוך חיים פניגשטין. פעיל באצ\"ל בתל אביב. רב בקראקס (ונצואלה), יוהנסבורג, וסאן פאולו (ברזיל). חיבר (עם רש\"ז זרסקי) \"רבני אנשי שם\" תל אביב תש, וכן מאמרים בכתבי עת שונים."},{"i":53464,"n":"שיף, משה שמואל - הנכד","dp":"רודניק","b":"נכד ר משה שמואל מטורנא. חתן רא\"ל הורביץ מלנצהוט. חסיד צאנז. היגר לברלין וגורש חזרה-תרצג."},{"i":53465,"n":"שיף, משה שמואל מטורנא - הזקן","f":"אברהם אליקים מבלוזוב","b":"חסיד החוזה מלובלין. בעל יקב מחכמי טורנא."},{"i":53466,"n":"שיף, נתן נטע מוינה","f":"בנציון מוינה","dt":"כז אלול","b":"תלמיד השב\"ס. מחכמי וינה-תרסט."},{"i":53467,"n":"שיף, שלמה מפפד\"מ","dt":"תקלח","b":"חתן ר אבלי מלונדון. מחכמי פפד\"מ. בניו ר דוד טבלי מלונדון, ר מאיר הדיין מפפד\"מ."},{"i":53468,"n":"שיף, שמעון מקלויזנבורג","f":"חיים","k":"אדמור מליזנסק בקלויז","dt":"תש..","b":"נכד האדמור ר נפתלי מליזנסק ומצאצאי ר אלימלך מליזנסק. האדמור מליזנסק בקלויזנבורג. נספה בשואה. חיבר \"נוסח הקפות..\" קלוזש תרפה. מבניו ר יחזקאל-חתן ר משה יצחק מפשוורסק אנטורפן."},{"i":53469,"n":"שיפאמי, אברהם משלוניקי","dt":"תקח","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":53470,"n":"שיפל, יוסף הכהן","dt":"תשג","b":"דומ\"צ בדזיקוב"},{"i":53471,"n":"שיפליאקוב, אברהם מארה\"ב","f":"נפתלי","bt":"תרלז","bp":"צרניגוב","b":"הגיע כנער לארה\"ב, עסקן צבור בניו יורק, וחבר בית הנבחרים בניו יורק."},{"i":53472,"n":"שיפמן, אליעזר מאיר מניר לוגאש","f":"אברהם יהודה מאטשאד","k":"בעל אם לבינה-תרפו","bt":"תרך","dt":"תרצט - טז אלול","dp":"ניר לוגאש-הונגריה","b":"תלמיד ר שמלקא מסעליש בעל \"צרור החיים\" ובנו ר פנחס חיים קליין. נסמך מאת: רבותיו הנ\"ל, ר אהרן צבי ממרגרטן, ר פנחס מניגרעשד. חתן ר צבי הירש הלר מסיגט. הקים בית דפוס באויבר-וישווה - והעבירו לגיסו ר מתתיהו הורביץ בן צבי יהודה מנאגי-באניא, דיין וראש ישיבה-תרנה באויבר-וישווה, והעביר את הדפוס לגיסו ר מתתיהו הורביץ. רב בניר-לוגאש-תרס. חתנו - ר אלכסנדר זוסא."},{"i":53473,"n":"שיפמן, אלתר חיים הלוי מטבריה","b":"מחסידי קרלין בטבריה-תרפט."},{"i":53474,"n":"שיפמן, דב בריש מפולוטקיניץ","b":"נכד הצדיק ר יעקב מטרנופול. רב בפולוטקיניץ, פרש מהרבנות והתישב באוזירן. עלה לצפת. דודו ר צבי הירש ברנדריס שלח אליו את כתב היד של תורות ר ישראל מרוזין."},{"i":53475,"n":"שיפמן, דוד מטבריה","k":"בעל הבכורים והראיון","bt":"תריב","bp":"רוסיה","dt":"תרפז","dp":"טבריה","b":"עלה לטבריה, ונמנה על גדולי הרבנים בטבריה. חיבר ספר \"הבכורים והראיון\" ירושלים תרצט, ועוד רבים בכת\"י. הסכים על \"אהל יצחק\" - סטמר תרסג."},{"i":53476,"n":"שיפמן, משה מואטיץ ופרג","f":"אהרן","bt":"תקעא","bp":"ליבנא(=ליבען) ליד פרג)","dt":"תרנד - ה שבט","dp":"פרג","b":"תלמיד החת\"ס, ר אליעזר קרפלס מליבנא. רב במישקביץ-תרו, ואטיץ-תריז, ערענוי-תרך, פרג-תרלג. העתיק מתורת רבו וממנו נדפס בחת\"ס על הש\"ס."},{"i":53477,"n":"שיפמן, משלם זושא מזמיעחוב","f":"חיים דוד","bt":"תרכד","b":"רב בזאמיעחוב-פודוליה-תרנג."},{"i":53478,"n":"שיפמן, שלמה מטבריה","b":"מחכמי טבריה-תרמו. אולי בנו של ר דוד."},{"i":53479,"n":"שיפר פיבל","bt":"1809","dt":"ה'תרלא 1871","bk":[["דבר גבורות",""]]},{"i":53480,"n":"שיפר, אביגדור מארה\"ב","b":"רב בהונגריה, היגר לארה\"ב-תרסז."},{"i":53481,"n":"שיפר, יונה מפארינצה","f":"גרשון מווליטשנה","dt":"תרעט - ד חשון","dp":"ווליטשנה","b":"תלמיד הכת\"ס. חתן דודו ר מאיר טומשוף מווליטשנה. גר בפפארניצה."},{"i":53482,"n":"שיפר, סיני מקרלסרוהא","f":"יקותיאל זאב","k":"בעל סתרי ומגיני","bt":"תריג","bp":"נאמעסטא","dt":"תרפג - טו חשון","b":"תלמיד הכת\"ס, ור עזריאל הילדסהימר. רב בהנובר-תרמב, קרלסרוהא - קהל יראים - תרמד. חיבר גם \"מנחת עני\". פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - ברלין-קראקא תרנא, \"כנסת חכמי ישראל\" - אודסה תרנג, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":53483,"n":"שיפר, פנחס חיים מלמברג","bt":"תקסח","bp":"למברג","dt":"תרמד","b":"רב בלמברג-תר על מקום ר בנימין זאב בלומנפלד (והיה מחלוקת על כך בנימוק שאינו מיוחס). פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":53484,"n":"שיפר, שמואל בנימין מאלשא","f":"יונה מפארינצה","bt":"תרלב","dt":"תש - כד תשרי","dp":"אלשא-קובין-ירושלים","b":"תלמיד השב\"ס, וקרובו ר כלב פילב שלזינגר מטאפלטשן. חתן ר חיים טיטלבוים מהעדילא-מאדע. מחכמי פארינצה, אלשא-קובין-תרעט."},{"i":53485,"n":"שיץ, אליעזר","dt":"תשג","b":"רב ברובינשטוק"},{"i":53486,"n":"שיץ, מנחם מנדל מלמברג","b":"מחכמי למברג ממנהלי בית החולים היהודי שם."},{"i":53487,"n":"שיק (ר\"ת = שם ישראל קדש)"},{"i":53488,"n":"שיק, א' ה' מפרשבורג","b":"מיסד בי\"ס פרטי בגרמנית בפרשבורג-תקפה."},{"i":53489,"n":"שיק, אביעזר יהודה זליג ליב","f":"יעקב מפרשבורג","bt":"תקעו","bp":"פרשבורג","dt":"תרמג - כ טבת","dp":"פרשבורג","b":"תלמיד ישיבת פרשבורג. חתן ר חיים בנימין וולף פולק מסערעד. רב בסערעד על מקום חותנו, עזב את רבנותו ונעשה בעל דעות מהפכניות ומתומכי קושוט - הלאומן ההונגרי, עבר לפרשבורג ועסק במסחר, וגם לימד בביה\"ס \"פרימער שוהלע\" ובביה\"ס של הקהלה. החזיק 18 תלמידים בישיבה. חיבר קונטרס נגד אחד המשכילים."},{"i":53490,"n":"שיק, אברהם מאפטא","k":"בעל בית אברהם","b":"רב באפטא-תקג. חיבר \"בית אברהם\"."},{"i":53491,"n":"שיק, אברהם מסלונים","f":"אריה יהודה מואשלישוק","k":"בעל זרע אברהם","dt":"תרלא","b":"נכד ר יום טוב ליפמן מואשלישוק. תק\"פ. חיבר \"זרע אברהם\", \"אשד הנחלים\", \"עין אברהם\", \"מאורי אש\"."},{"i":53492,"n":"שיק, אברהם מראב","f":"שמואל","dt":"תקצ - כח תמוז","b":"רב בפעדוי, מיזליץ, בלדוי, ראב-תקסג. נזכר בשו\"ת החת\"ס."},{"i":53493,"n":"שיק, אהרן","f":"ברוך שיק"},{"i":53494,"n":"שיק, אליהו מקוברין-אליהו לידער","f":"בנימין","k":"בעל עין אליהו","bt":"תקעו","bp":"ואסילישוק-פלך וילנא","dt":"תרלו - יג אלול","dp":"קוברין","b":"נקרא \"אלינקע לידער\". תלמיד ר בנימין ברודי מגרודנא. רב באמסטיבובה, לונא, דרטשין(=דראצ'ין), לידא, זאגר חדש על מקום ר שמעון הורביץ, קוברין. בזמן גזירות ניקולאי הגן במסירות נפש על בני העניים. מגדולי הדרשנים. חיבר גם \"דרך אבות\"."},{"i":53495,"n":"שיק, אלכסנדר זושא מסילאג'-פיר","bt":"תרם","dt":"תשד - טו סיון","b":"ממשפחת המהר\"ם שיק. תלמיד ר אברהם יצחק גליק בטאלטשווא, ר יהודה גרינפלד בסעמיהאי ור יהושע ברוך רייניץ בטשרנוביץ. חתן ר אליעזר מאיר שיפמן. רב בכפר סילאג'-פיר ליד טשאנד. נספה בשואה."},{"i":53496,"n":"שיק, אלקנה הלוי מקושטא","f":"יוסף","b":"מחכמי קושטא. חתם עם חבריו בפסק אודות ר שאלתיאל הנגיד-רף ונזכר בשו\"ת הרא\"ם."},{"i":53497,"n":"שיק, אריה יהודה ליב מואשלישוק","f":"יום טוב ליפמן מואשלי","b":"רב בואשילישאק(=ואשלישוק)-תר על מקום אביו. בניו - ר אברהם מסלונים בעל \"זרע אברהם\", ר יחיאל, ר בנימין, ר יום טוב."},{"i":53498,"n":"שיק, אשר אנשיל מסיקסא","f":"מנחם מנדל מסיקסא","dt":"תשד","b":"דומ\"צ בסיקסא."},{"i":53499,"n":"שיק, אשר אנשל","f":"דוד מטאקאי"},{"i":53500,"n":"שיק, בנימין","f":"אריה יהודה ליב מואשל","b":"נכד ר יום טוב ליפמן מפרוזין. בנו - ר אליהו מקוברין."},{"i":53501,"n":"שיק, ברוך משקלוב","f":"יעקב משקלוב-מורה צדק","k":"בעל עמודי שמים","dt":"תקע - א אד\"א","dp":"שקלוב","b":"מצאצאי ר ליב בעל התוספות ממינסק. רב בשקלוב-תקל. גאון בתורה בחכמה ובמדע,רופא ומהנדס. הו\"ל \"יסוד עולם\" לר יצחק הישראלי - מתוך כת\"י שקיבל מר צבי הירש מלונדון וברלין."},{"i":53502,"n":"שיק, ברכיה (דב ברנט) מטימישואר","f":"שלמה צבי מקארצג","k":"בעל דת ודין","bt":"תרלט","dt":"תשב - כג תשרי","b":"תלמיד השב\"ס, ור מרדכי הלוי הורביץ מפפד\"מ. חתן ר אברהם זינגר מוארפאלאטא. רב בסקשפהרוואר(=שטול-וייסבנבורג)-תרנט, טימישואר-יאזעפשטאט-תרסא ובנו ר מאיר שיק על מקומו אחריו. חיבר \"להצדיק את הצדיק\" ובה הצדיק את פסקי אביו, \"דת ודין\" בגרמנית אודות מעשה שקרה עם הח\"ק בטימישואר שהיתה משותפת לשתי הקהלות וכו'. חיבר גם \"ולהצדיק צדק\"."},{"i":53503,"n":"שיק, דוד יוסף מניו יורק","f":"חיים מאיר מאנאד","dt":"תרצט - יד אד\"ב","b":"נכד ר יעקב יוסף כץ מאנאד. תלמיד השב\"ס, ודודו ר מנחם מנדל שיק מסיקסא. חתן ר אשר אנשל הלוי יונגרייז מגרוסורדין. רב צבאי בזמן מלחמת העולם ה-I. עבר לניו יורק וכיהן כרב-תרפד."},{"i":53504,"n":"שיק, דוד מטאקאי","f":"יצחק איזיק","k":"בעל אמרי דוד","r":"רב בטוקאי, ומקודם בערים סעטשין, ווארנאף","bt":"תקעב","bp":"ברזאווא","dt":"תרנ-א - ג שבט","dp":"לאשנץ","b":"בן דוד של המהר\"ם שיק (אבותיהם היו אחים). חסיד הדברי חיים מצאנז. תלמיד החת\"ס, ור יעקב קופל חריף מוערבא ור יחזקאל בנעט מנייטרא. גיסו של ר שמואל הרצפלד מברעזאווא. רב ברעזאווא, סעטשין-תריא, וראנוב-תרכז, טאקייא-תרלה. בזיוו\"ש חתן אלמנת ר אברהם יעקב זינגר מלאשנץ. מתורתו ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג. חתנו - ר יעקב הברפלד מטוראלוקא. בנו - ר אשר אנשל. לתולדותיו ב\"אמרי דוד\" ברוקלין תשכד.","bk":[["אמרי דוד - על התורה, חולין, קידושין",""],["פאר דוד - דרשות (נדפס בתוך ספר אמרי דוד - חולין)",""]]},{"i":53505,"n":"שיק, דוד מנעמעש","f":"מנחם מנדל מסיקסא","bt":"תרנו","dt":"תשד","b":"תלמיד הדעת סופר. חתן ר אברהם הלוי שטוריס מפישפיקלדאני. רב בנעמעש-סאלוק. נספה בשואה. בנו - ר יעקב יוסף שיק רב בבודפשט וסידני."},{"i":53506,"n":"שיק, זליג-אביעזר ליב מפרשבורג","b":"משכיל מחכמי פרשבורג, יצא כנגד הנהגת הקהלה החרדית בראשות ר קלמן פפנהיים - בזמן הכת\"ס. עמד בראש הקהלה הניאולוגית שפרשה מקהלת פרשבורג-תרלב, אולם לאחר שהקהלה הזמינה את המטיף הקיצוני ד\"ר באק לרב הקהלה - חזר לקהלה החרדית. חיבר חוברת בשם \"קורצע אבפערטיגונג\" כנגד המשכיל יעקב קיצער שהדפיס חוברת כנגד התלמוד. פרסם מאמרים ב\"שומר ציון הנאמן\" בשם אי\"ש (אביעזר יהודה שיק)."},{"i":53507,"n":"שיק, זלמן מוילנא","k":"בעל אלף שנה וילנא","bp":"ליטא","dt":"1942","dp":"לידא","b":"מראשי האגודה לידיעת הארץ בוילנא. בעל ספריה גדולה על וילנא ועל התנועה האספרנטית (שפת אספרנטו). נספה בשואה."},{"i":53508,"n":"שיק, חיים מאיר מאנאד","f":"יעקב מנאדאודוואר","k":"הו\"ל ישרש יעקב-לאביו","bt":"תרכו-ל","bp":"טשענגער","dt":"תרצא - ב אלול","dp":"אנאד","b":"תלמיד השב\"ס. חתן ר יעקב יוסף כץ מאנאד. רב באנאד-תרן על מקום חותנו וחתנו ר יצחק חזקיה פיבל דונט על מקומו אחריו, בזיוו\"ש חתן ר יוסף שלמה רייניץ ממישקולץ. רב באנאד-תרנב. הקים ישיבה ללימוד תורה ומלאכה (ובה למדו גם חייטות, נגרות, וסנדלרות). בניו - ר דוד יוסף מניו יורק, ר משה נתן מפעסט, ר שמואל מפינצעהאלי. חתניו - ר יחזקאל פיבל דאנאטה מאנאד, ר אברהם יוסף ליכטנשטין מניראטשאד."},{"i":53509,"n":"שיק, חנוך הניך משקלוב","f":"שמואל","dt":"תקס","b":"מצאצאי בעל תוי\"ט. אב\"ד פרוזאנא, דיין בשקלוב-תקמג. נספד מאת ר יהודה ליב מאורשא בספרו \"אבל כרמים\" - שקלוב תקסה. גיסו - ר מרדכי מרגליות."},{"i":53510,"n":"שיק, י. משארוואר","b":"דיין בשארוואר."},{"i":53511,"n":"שיק, יום טוב ליפמן מואשלישוק","f":"חנוך הניך משקלוב","b":"רב בואשילישוק ובנו ר אריה יהודה על מקומו אחריו, פרוזין-תקפ. נכדו - ר אברהם מסלונים. (כנראה היה מחלוקת כנגדו - כך נרמז אצל פין)."},{"i":53512,"n":"שיק, יום טוב ליפמן מקאוולא","f":"פנחס מקוברין","bt":"תרל","b":"נכד ר אליהו לידער בעל \"עין אליהו\", ונכד-אבי אמו הגביר ר מרדכי יפה מראגוווע. חתן ר משה זקהיים מקוולא(=קאוולא, קובל). רב בקאוולא-תרסג על מקום חותנו. נסמך מאת: ר יעקב יוזף מוילנא, ר הלל ליפשיץ מסובאלק."},{"i":53513,"n":"שיק, יוסף","b":"אביו של ר משה מחוסט. חתנו - ר אהרן דושינסקי מנאדאש."},{"i":53514,"n":"שיק, יחיאל","f":"אריה יהודה מואשלישוק","b":"אחיו - ר אברהם מסלונים."},{"i":53515,"n":"שיק, יעקב ברוכין","f":"אהרן בן ברוך משקלוב","k":"בעל משכנות יעקב","r":"אחיו הגדול של הקרן אורה","bt":"תקמח","bp":"מינסק","dt":"תרה - ו כסלו","dp":"קרלין","b":"מגדולי חכמי דורו. תלמיד חבר לר חיים מוולוזין. רב בדוד-הורודוק, אב\"ד קרלין. חיבר גם \"קהילות יעקב\".","bk":[["משכנות יעקב","שו\"ת - אחרונים"],["משכנות יעקב – שו\"ת",""],["קהלת יעקב – ש\"ס ושו\"ת",""]]},{"i":53516,"n":"שיק, יעקב יוסף מבודפשט","f":"דוד מנעמעש-סאלאק","b":"רב בבודפשט, סידני."},{"i":53517,"n":"שיק, יעקב ממישקולץ ונדאודוואר","f":"דוד מברעזאווא","k":"בעל ישרש יעקב","bt":"תרז-ח","bp":"ברעזאווא","dt":"תרעה - כז חשון","dp":"נאדאודוואר","b":"תלמיד אביו, הכת\"ס, ור ירמיה לעוו מאויהל. חתן ר אשר אנשיל יונגרייז מטשענגער, ועבר לשם. רב במישקולץ-תרלד, נאדאודוואר-תרם, חתנו ובן גיסו ר ישראל יונגרייז על מקומו אחריו. בניו: ר מנחם - רב בסיקסו, ר מאיר - רב באונוד. חתניו - ר צבי פראגר מפאפראד, ר אשר אנשל וייס מסילאדי-נאדיפאלו, ר ישראל יונגרייז מנדודואר, ר אשר אנשל יונגרייז מפעהר-יארמוט, ר קלונימוס שלום קלנר מטענקע, ר חיים ארנריך מהומענע."},{"i":53518,"n":"שיק, יצחק איזיק","f":"חנוך הניך שיק","b":"רב-שנת תק\"פ"},{"i":53519,"n":"שיק, יצחק מקרלין","f":"אהרן בן ברוך משקלוב","k":"בעל קרן אורה","bt":"תקמח","bp":"מינסק","dt":"תריב - ט חשון","dp":"קרלין","b":"רב בקרלין-תרה על מקום אחיו - ר יעקב ברוכין שיק בעל \"משכנות יעקב\". בניו: ר אברהם - ובנו ר אהרן, ר יעקב ברוך, ר משה שלום, ר דוד יהודה - הו\"ל את ספר אביהם."},{"i":53520,"n":"שיק, יקותיאל מרדכי ממישקולץ","f":"מנחם מנדל שיק מסיקסא","k":"בעל המרקחת לבשמים","bt":"תרסט","dt":"תשמט - ב כסלו","dp":"קרית יואל - מונרו","b":"תלמיד הדעת סופר ועוד. חתן ר יואב אדלר מהנשביץ, ובזיוו\"ש חתן ר לוי מושקוביץ מאונגוואר. רב בפסט-סנט לורינץ-תרצג, קיש-פעסט-תשא, ערזשעבט-פאלווא, טשאבא-תשב. ניצל מהשואה ואחריה רב במישקולץ וסיקס, עבר לניו יורק-תשח, רב במקסיפורט-פא'-תשיג, ניו יורק-תשכד. הו\"ל ספרי זקנו ר דוד שיק מטאקייא, ו\"תורת עדות הזאת\" לזקנו ר שמואל יונגרייז מטשעטשע. חתם במישקולץ-תשו עם הדיינים ר אברהם יצחק ..., ר שלמה פסטרנק."},{"i":53521,"n":"שיק, מאיר","bt":"תרכט"},{"i":53522,"n":"שיק, מאיר מטימישואר","f":"ברכיה מטימישואר","b":"רב בטימישואר-תשב על מקום אביו. ניצל מהשואה ואחריה היגר לארה\"ב, וכיהן כרב במונסי."},{"i":53523,"n":"שיק, מנחם זאב מטאקאי ונ\"י","k":"בעל מנחת זאב","b":"רב בטאקאי(=טוקאי), ניו יורק. חיבר \"מנחת זאב\" נ\"י תשלח."},{"i":53524,"n":"שיק, מנחם מנדל מגרוסורדין","f":"יעקב מטשענגער","k":"בעל זכרון מנחם","bt":"תרלא או תרכא-ג","bp":"טשענגר","dt":"תרפב-ח -יב תמוז","dp":"סיקסא","b":"תלמיד השב\"ס, וזקנו ר דוד שיק מטאקייא בעל \"אמרי דוד\", ור עמרם בלום מבערטי-אויפלו. נתקבל לרב בטשאבא - ולא הגיע לשם. חתן דודו ר שמואל זאב יונגרייז מביהאר-נאדי-באיאם, ועבר לשם. עבר לנאדאודוואר לצד אביו. דיין בגרוסורדין-תרמח. קירכדורף-תרסא, סיקסא-תרסז, וחתנו ר אריה ליב יונגרייז על מקומו אחריו. חיבר \"חדושי אגדה\". הו\"ל ספר זקנו ר דוד שיק - \"מזמור לדוד\" עם הערות ממנו, וספר אביו \"ישרש יעקב\". פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח."},{"i":53525,"n":"שיק, מנשה נתן מבודפשט","b":"רב בבודפשט."},{"i":53526,"n":"שיק, משה אהרן מקארצאג","f":"שלמה צבי מקארצאג","dt":"תשא - טו חשון","dp":"קארצאג","b":"תלמיד השב\"ס, ור מרדכי הלוי הורביץ מפפדמ. רב בקארצאג לצד אביו, ועל מקומו אחריו-תרעו. נאסר בעלילת ריגול-1940. הקהילה הוציאה ספר לזכרו-1941."},{"i":53527,"n":"שיק, משה מבודפשט","dt":"תשד","b":"חתן ר יצחק איזיק הברפלד מבודפשט. רב ביהמ\"ד \"אהל אסתר\" בבודפשט על מקום חותנו."},{"i":53528,"n":"שיק, משה מחוסט","f":"יוסף","k":"בעל שו\"ת מהר\"ם שיק","r":"רב ופוסק - רב בחוסט","bt":"תקסה-ז","bp":"ברעזאווע","dt":"תרלט - א שבט","dp":"חוסט","b":"מגדולי תלמידי החת\"ס, ודודו ר יצחק פרנקל מפרונקירכן. חתן דודו הגביר ר פרץ פרנקל מהאליטש ועבר לשם. רב וראש ישיבה ביערגין-תקצח, חוסט-תרכא. בזיוו\"ש חתן אלמנת ר חיים אברהם אנרשטין מברדיוב בת ר נתן אליהו עהרמן מאירשא. החת\"ס היה מעונין בו כחתן - אולם לא נסתייע. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז.","bk":[["מהר\"ם שיק",""],["מהר\"ם שיק (שו\"ת)",""]],"e":"תקס\"ז-תרל\"ט","rb":"חוסט","co":{"b":"48.663341,17.555017"}},{"i":53529,"n":"שיק, משה נתן ממישקולץ","f":"חיים מאיר מאנאד","bt":"תרנה","dt":"תשלד - כט אב","dp":"בודפשט","b":"נכד ר יוסף שלמה רייניץ ממישקולץ. תלמיד הדעת סופר, וזקנו ר יוסף שלמה רייניץ, ועוד. חתן ר משה בנימין זאב וולף ליכטנשטרן מאורמין. רב בקהילת 'בית יעקב' בבודפשט-תשא, ניצל מהשואה ואחריה רב במישקולץ, ויו\"ר ועד הרבנים בהונגריה בבודפשט."},{"i":53530,"n":"שיק, פנחס מקוברין","f":"אליהו-עין אליהו","dt":"תרסג - כב סיון","dp":"קוברין","b":"חתן הגביר ר מרדכי יפה מראגובה וירושלים. נתמנה לרב בקוברין-תרלו על מקום אביו, אך סירב לרבנות וכיהן כמו\"ץ. חתנו - ר יוסף זלמן יהלום-שטיין מזשאבינקא. מתורתו בספרי אביו."},{"i":53531,"n":"שיק, פנחס משקלוב","f":"חנוך הניך שיק","b":"רב בשקלאב-תק\"פ"},{"i":53532,"n":"שיק, צבי אריה משארוואר","f":"יצחק משארוואר","dt":"תשנז - יב שבט","dp":"סקווירא","b":"תלמיד הדעת סופר, ור מנחם הכהן פישר משארוואר, ור אברהם אינהורן משטינמאנגר ועוד. חתן ר אשר אליקים הלוי טשעך מבורשוד-מעזא-קערעסטעש, ובזיוו\"ש חתן ר יו\"ט ליפמן גולדשטין מסערדאוהל. רב בשארוואר, ניצל מהשואה ואחריה אב\"ד שארוואר. עבר לאמריקה וכיהן כרב קהל חת\"ס בלוס אנגלס. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":53533,"n":"שיק, שלמה צבי מקארצאג","f":"נתן","k":"בעל תורה שלמה","bt":"תרד","dt":"תרעו - כ תמוז","b":"רב בקארצאג(=קיש אוי סאלאש)-תרכח. חיבר דרשות בהונגרית וגרמנית, חיבר גם \"על יהודים\". חיבר ספר על סידור רשב\"ן - וינה תרנד, הגנה על היהודים מפני עלילות דם. הסכים על \"אהל יצחק\" - סטמר תרסג, \"יגדיל תורה\" - ברלין-קראקא תרנא. בנו ר משה אהרן נאסר בעלילת ריגול-1940 ונפטר בזמן משפטו. בנו - ר בכרי'. חתנו - ר מאיר שטיין, ר משה שבתי מטורק-סענט-מיקלוש."},{"i":53534,"n":"שיק, שמואל","b":"חתן ר משה הלר. מגדולי חכמי דורו-ת\"ק. קרא שמו שי\"ק (= שם ישראל קדש). בנו - ר חנוך הניך משקלוב. חתנו - ר מרדכי מרגליות."},{"i":53535,"n":"שיק, שמואל","f":"חנוך הניך שיק","b":"רב-שנת תק\"צ"},{"i":53536,"n":"שיק, שמואל מפינצהאלי","f":"חיים מאיר מאנאד","b":"רב בפינצעהאלי."},{"i":53537,"n":"שיק, שמואל שמלקא מגירבא","f":"חיים מאיר מאנאד","bt":"תרסט","dt":"תשד - ח תמוז","b":"נכד ר שלמה רייניץ ממישקולץ. תלמיד הדעת סופר. חתן ר צבי הרש גולדשטין מאויהל. רב בגירבא-פינצעהל-תרצו. נספה בשואה."},{"i":53538,"n":"שיקוביצקי, בנימין","b":"דרשן,מגיד במינסק,עלה לא\"י-תר\"צ"},{"i":53539,"n":"שיקיל, יצחק משלוניקי","dt":"שצד - ח סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53540,"n":"שיקילי, שמואל","b":"מגדולי הראשונים בצרפת-שנת ק'"},{"i":53541,"n":"שיקלר, אברהם אבוש מרדכי מסנוק","f":"שלמה מסנוק","b":"חסיד בלז. רב בויברניפקה (אולי על מקום זקנו ר אברהם אבוש מרדכי אייזן), סנוק והיה גם ר\"מ בישיבה שהקים שם מהר\"ם שפירא."},{"i":53542,"n":"שיקלר, פנחס מטרנופול","f":"שלמה מסנוק","dt":"תש..","b":"רב בטרנופול. נספה בשואה."},{"i":53543,"n":"שיקלר, שלמה","b":"פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח."},{"i":53544,"n":"שיקלר, שלמה מגוליגור","f":"צבי","bt":"תרסא","bp":"ויזניץ","dt":"תשג","b":"חסיד ר ישראל מצורטקוב. תלמיד מהר\"ם שפירא בגלינא שהיה לו כאב לאחר שנתייתם ואף התגורר בביתו בטרנופול. עמד בראש צא\"י וערך את הבטאון \"הנצח\". חתן ר וולף ליפמן מפמורן וישב אצלו - בין תלמידיו שם ר אנשל פינק. רב בגוליגור-תרפז, קלוש-תרצב על מקום ר יוסף באבד. נספה בשואה."},{"i":53545,"n":"שיקלר, שמאי מסנוק","dt":"תשא-ד","b":"חתן ר אריה ליב וולף גינזבורג מקשוי ועבר אליו. רב במריאנבד (שם שהה בקיץ). נספה בשואה."},{"i":53546,"n":"שיראנו, אברהם ממצרים","b":"גביר במצרים-שנות ה-תק', התמנה יחד עם חברו שלמה נבארו כאפוטרופוס בצוואת הגביר משה ן עטר מרשיד."},{"i":53547,"n":"שיראנו, אברהם משלוניקי - א","dt":"תז - ט אב","dp":"שלוניקי","b":"תלמיד ר שלמה הלוי הבחור ומגדולי הישיבה. גביר מחכמי שלוניקי, מחותמי הסכמות הקהל בשלוניקי."},{"i":53548,"n":"שיראנו, אברהם משלוניקי - ב","b":"דיין בשלוניקי-תקלו."},{"i":53549,"n":"שיראנו, אברהם משלוניקי - ג","f":"יצחק?","k":"בעל מקנה אברהם","dt":"תקצו - יז אב","dp":"שלוניקי","b":"דיין בשלוניקי-תקפב יחד עם ר חיים נחמה ור יעקב מנשה, רב הכולל על מקום ר יעקב מנשה-תקצב יחד עם חבריו (כך לפי דוד פיפאנו ולפי חיים סעדיה הלוי המדובר בר אברהם ורשאנו שהיה רב הכולל). חיבר גם \"לאברהם למקנה\" והו\"ל נכדיו - ר אברהם ברכה, ור יצחק פרחיה הכהן-תרלא. הניח עוד דרושים ושו\"ת בכת\"י - ואבדו."},{"i":53550,"n":"שיראנו, יוסף דוד מירושלים","b":"מחכמי ירושלים, בשליחות בלונדון-תקנא. הדפיס את ספרי החיד\"א 'מורה באצבע' ו'ציפורן שמיר'."},{"i":53551,"n":"שיראנו, יצחק מירושלים - ב","f":"אברהם","dt":"תקיד - לפני","dp":"ירושלים","b":"מחכמי ירושלים. נספד ע\"י ר שמואל פלורנטין ב\"מנחת שמואל\". (ב\"ארזי הלבנון\" ואצל פרומקין - אולי בלבול בינו לבין ר יצחק שיראנו משלוניקי)."},{"i":53552,"n":"שיראנו, יצחק משלוניקי - א","f":"אברהם בן יעקב","dt":"תקלו - לפני","dp":"שלוניקי","b":"נכד-אבי אמו ר שמואל פלורנטין והו\"ל ספר זקנו \"בית הרואה\". תלמיד דודו ר יוסף יצחק מונטיקיו, וחיבר הקדמה והוספות לספר רבו \"יוסף עליו\"."},{"i":53553,"n":"שיראנו, מאיר משלוניקי","dt":"שפט - ט כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53554,"n":"שיראנו, שולימה משלוניקי","dt":"שפא - ט תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53555,"n":"שיראת ן, שמעון מתורכיה","b":"מחכמי תורכיה בזמן המבי\"ט ונזכר בספרו."},{"i":53556,"n":"שירווינטר, יצחק מוילנא","dt":"תרמו - כח ניסן","b":"מו\"צ בוילנא. מחותן עם ר ישראל סלנטר - בנו - ר אליהו אליעזר גרודזינסקי היה חתן ר ישראל סלנטר. חתנו - ר אברהם אבא בן חיים מזעלווא."},{"i":53557,"n":"שיריוטי, אברהם משלוניקי","dt":"תט - יא תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53558,"n":"שיריזלי-ישראל, אליהו משיריז","f":"יצחק ישראל","bp":"שיריז - יון","dt":"תרכו - י אב","b":"עלה עם אביו לירושלים-תקסז מעיר שיריז-יון, בשנת תקצו שליח ירושלים במרוקו ושם שכנע להעביר חלק מכספי הקופות שהיו מיוחדות לקהלות צפת וטבריה, גם לקהילת ירושלים. בשנת תרז בשליחות למצרים ונשאר שם כרבה של קהילת קהיר, ר יעקב ספיר בשליחותו במצרים בשנת תריח פגש בו ומספר עליו בספרו, וכן מביא תשובה שכתב לו ר אליהו בענין הישיבה במצרים. בניו: ר יום טוב, ר חיים ויטא, ר דוד."},{"i":53559,"n":"שיריזלי-ישראל, חיים משה","f":"יצחק ישראל","dt":"תרכג - כג אייר","dp":"ירושלים","b":"מחכמי ירושלים, פקיד הכולל הספרדי. אחיו של ר אליהו מקהיר."},{"i":53560,"n":"שיריזלי-ישראל, יום טוב ממצרים","f":"אליהו ממצרים","k":"בעל טיב גיטין","r":"רב ואב\"ד מצרים","bt":"תקפ","bp":"ירושלים","dt":"תרנא - יג אב","dp":"ירושלים","b":"ראב\"ד בקהיר-תרכז על מקום אביו, עלה לירושלים-תרמא. בשנת תרלא הוציא את ספרו של ר חיים מודעי \"מזכרת הגטין\". השתתף בקובץ \"תורה מציון\" שיצא לאור בירושלים - תרנה-תרסה. בניו: ר מיכאל, ר מאיר, ר משה.","bk":[["מנהגי מצרים","הלכה ומנהג - אחרונים"],["ליקוטי תשובות [משפחת ישראל]","שו\"ת - אחרונים"],["מנהגי מצרים - המנהגים הקדומים של יושבי מצרים",""],["ליקוטי תשובות",""]]},{"i":53561,"n":"שיריזלי-ישראל, יצחק מירושלים","f":"חיים","dt":"תרמג - ט אב","dp":"ירושלים","b":"דיין ועסקן ציבור בירושלים. בניו: ר מירקדו, ר מרדכי, ר רפאל."},{"i":53562,"n":"שיריזלי-ישראל, יצחק משיריז","f":"אליהו","b":"עלה משיריז-יון לירושלים-תקסז עם בניו ר אליהו (לימים רב בקהיר), ור חיים משה."},{"i":53563,"n":"שיריזלי-ישראל, מרדכי","k":"בעל מקראי קדש","dt":"תרעו - ו אייר","b":"מחכמי צפת, וירושלים."},{"i":53564,"n":"שיריזלי-ישראל, רפאל מירושלים","dt":"תרפו - כח כסלו","dp":"ירושלים","b":"חתן ר יוסף מרדכי מיוחס. מחכמי ירושלים, גבאי בביה\"ח \"משגב לדך\". בנו - ר שלמה - שי\"ש."},{"i":53565,"n":"שיריזלי-ישראל, שלמה מירושלים","f":"רפאל","bt":"תרלח","bp":"ירושלים","b":"חתן ר חזקיה שבתי. קנה יחד עם חברו בן ציון טארגן את דפוס בן יהודה, הו\"ל \"גואירטה די ירושלים\", \"הפרדס\". בזמן המחלוקת על רבנות ירושלים תמך בר אליהו משה פאניג'ל. תרגם ספרים מצרפתית. הו\"ל סידור בשם \"זכרון שיש\". עסק גם במסחר בעתיקות."},{"i":53566,"n":"שיריש, חיים מרמלה","b":"מראשי קהילת רמלה בשנת שפה, נתבקש על ידי חכמי ירושלים להשתדל למענם אצל מושל דמשק והצליח בשליחותו."},{"i":53567,"n":"שירמן חיים","bt":"1904","dt":"ה'תשמא 1981","bk":[["מבחר השירה העברית באיטליה",""]]},{"i":53568,"n":"שיש, שמואל מאלגיר","f":"אליעזר","b":"רב בתלמסאן. נזכר בשטר-תצט."},{"i":53569,"n":"שישו, שלום מצפת","dt":"תרסד - כד חשון","b":"מחכמי צפת, טבריה. מלמד לתלמידים."},{"i":53570,"n":"שישי, אברהם משלוניקי","b":"מחכמי שלוניקי, קושטא."},{"i":53571,"n":"שישקס, יוסף מוילנא","f":"שמעון בן יוסף","k":"יוסלי ר חיים'ס","bt":"תקמב","dt":"תרב - ז שבט","b":"חתן ר חיים בן טוביה כץ מוילנא. מו\"צ בווילנה. נזכר בפנקס הגר\"א כי קנה מקום בבימ\"ר הגר\"א-תקעה. הסכים על ש\"ס סלאויטה תקצה, ועוד."},{"i":53572,"n":"שך, אליעזר מנחם מבני ברק","bp":"ליטא","b":"ראש ישיבת פוניבז בבני ברק. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"כנסת ישראל\" - וילנא תרץ, \"תבונה\" - ירושלים תשא-תשח."},{"i":53573,"n":"ש\"ך, מרים","f":"יהודה ליב","bt":"1867","bp":"ואקשנה","dt":"1957","dp":"צרפת - זכרון יעקב","b":"אביה היה רב בואקשנה ומצאצי בעל הש\"ך וכונה \"ר ליבל אייזנקאפ\". עברה לקובנא ולמדה אצל פרופ' מוריץ לצרוס, עברה לפאריס ולונדון. מורה בריימס, מרסיי, פאריס. התצטרפה לציונות והיה עוזרתם של הרצל ונורדוי. בזמן מלחמ\"ה ה-I הצטרפה ל\"צלב האדום\" ועבדה עם הסופר רומאן רולאן, ולאחר המלחמה הביאה 400 יתומים מפולין לצרפת. יסדה שכונת עובדים כפר מרמורק-ליד רחובות. עלה לארץ-1948 וחברה ספר אוטוביגוגרפי בשם \"אשר אתם התהלכתי\" - ת\"א תשיא."},{"i":53574,"n":"ש\"ך, פביוס","f":"יהודה ליב","bt":"1868","bp":"ואקשנה","b":"היה עילוי בילדותו. תלמיד ישיבת וולוזין, פנה להשכלה ועבר לריגה, ברלין. הצטרף לתנועה הסוציאליסטית. יסד בקאלן את הארגון הראשון של יהודי גרמניה, הצטרף לתנועה הציונת והשתתף בקונגרס הציוני הראשון בניסוח \"תכנית בזל\", פרש מהציונות. פרסם בעתונות הגרמנית והיהודית-גרמנית כמבקר ספרותי."},{"i":53575,"n":"שך, שלמה זלמן מליטא ויפו","f":"שרגא פיבוש","bt":"תרה-ז","bp":"גורזד","dt":"תרפט - יח אב","dp":"מוצא-ליד ירושלים","b":"מחכמי ליטא מצאצאי הש\"ך מצד אביו והגר\"א מצד אמו. סירב לרבנות ועסק במסחר, ר\"מ בישיבת טלז. עלה לארץ-תרסד והתישב ביפו, ולאחר שירד מנכסיו החל לכהן כדיין - ללא שכר. ר\"מ בישיבת הרב קוק ביפו, לאחר מלחה\"ע ה-I היה חבר הרבנות בתל אביב יפו. נהרג עק\"ה ע\"י ערבים בפרעות תרפט."},{"i":53576,"n":"שכטר, אברהם אהרן מארה\"ב","dt":"תרפט - ג אלול","dp":"ניו יורק","b":"רב ביהמ\"ד בברונקס-ניו יורק."},{"i":53577,"n":"שכטר, אברהם מארה\"ב","f":"מיכאל","bp":"רומניה","b":"תלמיד ר שלמה ברייער מפפד\"מ, נסמך ממנו ומאת ר משה מרדכי אפשטין. רב ביוסטון-טקסס."},{"i":53578,"n":"שכטר, אברהם מפורמושיקא","b":"רב בפורמושיקא(רומניה)"},{"i":53579,"n":"שכטר, אברהם מקופיטשיניץ","b":"דיין באויבר-אפשא (במארמרוש), עבר לסיגט והיגר לארה\"ב."},{"i":53580,"n":"שכטר, אברהם מקראקא","k":"בעל תורת האגדה","b":"עסקן ומרצה חרדי בקראקא, ממייסדי אגו\"י. ערוך הבטאון \"דער יודיש רעליגעזער ארבייטער\". חיבר \"תורת האגדה\"."},{"i":53581,"n":"שכטר, אלימלך","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":53582,"n":"שכטר, אליעזר מחודרוב","b":"שו\"ב בחודרוב. יתכן שהיגר לארה\"ב-תרפא."},{"i":53583,"n":"שכטר, אריה ליב מאיר מהורודנקה","f":"מרדכי מהורודנקה","b":"רב בצורטקוב. נספה בשואה. אחיו - ד\"ר אהרן קוהן-שכטר בת\"א."},{"i":53584,"n":"שכטר, בונם מפאלישן","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":53585,"n":"שכטר, בנימין מפעזינג","f":"מנשה מפעזינג","bp":"גלנטא","dt":"תרלב - כח אד\"א","dp":"פעזינג","b":"תלמיד הכת\"ס. חתן ר ישראל דוד יפה מרגליות מפעזינג. רב בפעזינג(=פזינג) על מקום חותנו. בנו ר אברהם אהרן - רב בניו יורק."},{"i":53586,"n":"שכטר, דוד מטיסמניץ","f":"פנחס ואהל מקוסוב","bt":"תרה","dt":"תרף","b":"לאחר שנתייתם גדל אצל הצמח צדיק בויזניץ, ולמד ביחד עם בנו ר ברוך. מחכמי טיסמניץ. עבר לסטניסלב והיה מקורב לר חיים הגר מאטיניא."},{"i":53587,"n":"שכטר, זידא","dt":"תש..","b":"משב\"ק (משמש בקדש) אצל האדמור בעל \"דברי חיים\" מויזניץ, ואצל בנו ה\"אמרי חיים\". נספה בשואה."},{"i":53588,"n":"שכטר, חיים ממילניצה","f":"פנחס ממילניצה","k":"בעל מקור מים חיים","bt":"תרן","dt":"תשג","b":"תלמיד ר אברהם רוזנברג מקופיטשיניץ. שו\"ב במילניצה, רב ביאנוב (ליד טרמבובלה - והיה מחלוקת בינו לבין ר אליעזר לייטר מטרמבובלה). נספה בשואה. חיבר \"מקור מים חיים\" בילגוריא תרצג, ועוד. הו\"ל \"אוצר החיים\" - זאמושט תרצז. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":53589,"n":"שכטר, חיים מרדכי מחורוסטקוב","bt":"תרלה","dt":"תרפז","b":"רב בוישניובטשיק, חורוסטקוב אצל ר משולם ראטה. מצאצאי ר ישראל מרוזין ומנהיג חסידי הוסיאטין בעירו (נפרדו מקלויז צורטקוב). חתן ר משה נאס מדוניוב."},{"i":53590,"n":"שכטר, חנוך הניך מחורוסטקוב","f":"אברהם מחרסקוב","k":"בעל שתי ערים","bt":"תרלח","bp":"חרסקוב","dt":"תשטו","b":"תלמיד ר משולם ראטה. חסיד צורטקוב. חתן ר לייבל אייפרמן מקולומיאה ועבר לשם. עסקן \"המזרחי\" ויסד בעירו בי\"ס \"תחכמוני\". עלה לארץ-תרצד. חתנו היה המשורר שמשון מלצר. חיבר \"שתי ערים\" תל אביב תשיג."},{"i":53591,"n":"שכטר, יהודה הלוי","b":"פרסם מאמרים ב\"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":53592,"n":"שכטר, יעקב מבלפסט","f":"אברהם שכטר","k":"בעל לקוטי יעקב","b":"רב במנצסטר, בלפסט-תרפז. פרסם מאמרים ב\"אור תורה\" - לונדון תרצד, \"בית ועד לחכמים\" - סטמר תרפב, \"שערי ציון\" - ירושלים תרפא."},{"i":53593,"n":"שכטר, יצחק בנימין מאוי-סין","dt":"תרעא - בערך","b":"תלמיד הכת\"ס, ור בנימין זאב פוקס מסערד, ור חזקיה פיבל פלוי משוראן. מחכמי ביאלע-תרכט, אוי-סיון (ניא-סיני ליד קאמארן). שימש כטוען בדין תורה אודות הרבנות בגאלאנטא. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":53594,"n":"שכטר, ישעיה מתל אביב","k":"בעל ספר הברית","b":"שו\"ב וש\"ץ בגלדבק-גרמניה, מוהל במגדבורג, אסן, תל אביב. רשם את הבריתות ב'ספר הברית' בשנת תשד. התכתב עם רבנים רבים בגרמניה והסביבה."},{"i":53595,"n":"שכטר, ישראל","b":"רב באראד-ת\"צ"},{"i":53596,"n":"שכטר, ישראל ליב מדוניוב","f":"חיים מרדכי מחרסקוב","bt":"תרסג","bp":"דוניוב","dt":"תרפח","dp":"וינה","b":"נסמך מר אברהם יצחק סילמן מחלניק."},{"i":53597,"n":"שכטר, ישראל מאראד","bp":"פולין","b":"רב באראד-תץ."},{"i":53598,"n":"שכטר, ליב מליפקאן","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":53599,"n":"שכטר, מרדכי מהורודנקה","f":"[ישראל]","b":"רב בהורודנקה."},{"i":53600,"n":"שכטר, משה מפשמישל","b":"שו\"ב בפשמישל-תרפא."},{"i":53601,"n":"שכטר, משה שלמה מרדכי מזלישטשיק","b":"מכונה גם שפרבר. רב בזלישטשיק-תרפט (והיה מחלוקת על כך וכנראה לא נתקבל לבסוף). חתם-תרצד עם ראשי חסידות צורטקוב."},{"i":53602,"n":"שכטר, נחום שמריהו מדארבאן","f":"מרדכי יהודה מפולטושן","k":"בעל פרח שושן","bt":"תרמו","dt":"תשכז ובאוצר תשך","b":"תלמיד דודו ר יהושע פאלק זאב וולפזון מפולטושען. רב בדרבן-תרסח, הוש-תרץ, ניצל מהשואה ואחריה רב בבוקרשט-תשה, עלה לארץ-תשיב, וכיהן כרב בקרית יובל בירושלים. חיבר \"פרח שושן\" קלוזש תרפה, ועוד. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג, \"בית ועד לחכמים\" - יאסי תרסט."},{"i":53603,"n":"שכטר, עזריאל מלונדון","f":"אברהם יעקב","bp":"וינה","b":"מצאצאי מהרש\"ק. ברח מהשואה-תרצט והגיע ללונדון למד שם בישיבה וכיהן כרב. חתן ר אברהם שיינהון."},{"i":53604,"n":"שכטר, צבי הירש מברוד","f":"אריה מברודי","bp":"ברודי","b":"תלמיד ראמ\"מ שטינברג. עורך \"גפן פוריה\" (נקרא גם \"כרם צבי\") - תרפז."},{"i":53605,"n":"שכטר, צבי מחורסטקוב","f":"חיים מרדכי מחורוסטק'","k":"בעל קול צבי","bt":"תרס","bp":"חורוסטקוב","dt":"תשמב","b":"חסיד הוסיאטין-סדיגורא. רב וד\"ר בביהמ\"ד לרבנים בוינה. חתן ר מרדכי רוזן מנוסטרישטש. ניצל מהשואה ועלה לארץ-תש, כיהן כרב בתל אביב. חיבר \"קול צבי\" תל אביב תשל, ועוד."},{"i":53606,"n":"שכטר, קלונימוס קלמן מוישניצה","f":"אלכסנדר זיסקינד","bt":"תרעג","bp":"וישניצא","dt":"תשן","b":"עבר בילדותו לפפד\"מ, ועבר לסכייוונינגן (הולנד) שם התקרב לר נתן בירנבוים. מראשי אגו\"י באנטורפן ושוייץ. ניצל מהשואה והתישב בציריך, אנטורפן, שבדיה. עלה לירושלים-תשם ופעל בצדקה וחסד."},{"i":53607,"n":"שכטר, ראובן מריבטיטש","b":"רב בריבטיטש-תרצו. וגבאי א\"י."},{"i":53608,"n":"שכטר, שלמה מליסעץ","f":"יהושע","b":"מחכמי ליסעץ (ליד סטניסלב)."},{"i":53609,"n":"שכטר, שמואל זאב מלובשובקה","f":"יקותיאל אהרן","bt":"תרלה","b":"רב בלובאשאווקה-פלך חרסון-תרנה. בניו: ר יעקב, ר יהודה ליב."},{"i":53610,"n":"שכטר, שמואל מזלישטשיק","b":"מחכמי זלישטשיק - תשובה אליו ב\"אורין תליתאי\"."},{"i":53611,"n":"שכטר, שמחה מזבורוב","b":"מחכמי זבורוב. תשובה אליו \"חיים של שלום\"."},{"i":53612,"n":"שכטר, שמעון","f":"חיים מרדכי מחרסקוב","bt":"תרעד","b":"תלמיד מהר\"ם שפירא בישיבת חכמי לובלין, ולימים שליח לטובת הישיבה. עבר לסמבור וכיהן כר\"מ בישיבה שם. נספה בשואה."},{"i":53613,"n":"שכטר, שניאור זלמן","k":"בעל שיחות הני צנתרא","b":"ממשפחת חסידי חב\"ד, פנה להשכלה והיה חוקר גניזת קהיר. חיבר בעילום שמו כתבים כנגד החסידות בשם \"יחץ בן רחצה\"."},{"i":53614,"n":"שכטר, שניאור זלמן ישכר בר","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":53615,"n":"שכנא מוינה","b":"רב בווינה"},{"i":53616,"n":"שכנוביץ, חיים מארה\"ב","f":"יוסף מפלונגיאן","bt":"תרסז","bp":"טלז","b":"תלמיד ישיבת טלז, מקורב לר יוסף רוזין הרוגאצ'ובר ונסמך ממנו, ומאת ר יוסף ליב בלוך. חתן ר דב אריה אלשוואנג מגרייבה ובזיוו\"ש חתן ר שמואל ספרן מסלובקיה. רב ברעזשיצע, ר\"מ בישיבת \"בית יוסף\" בדוינסק-תרצג, ניצל מהשואה ועבר לסמרקנד ויסד שם ישיבה, הגיע לפאריס-תשו וכיהן כר\"מ בהענאוויל - לפליטי שואה שיצאו מרוסיה, היגר לארה\"ב-תשז וכיהן כרב בשיקגו ויסד שם כולל לאברכים. הניח חבורים על הש\"ס."},{"i":53617,"n":"שכנוביץ, יוסף מסויאדושץ","dt":"תשג","b":"מו\"צ בפלונגיאן, רבה האחרון של סויאדושץ(=שוודיס). בנו - ר חיים מארה\"ב."},{"i":53618,"n":"שכנוביץ, מאיר ליב הכהן מזלודק","b":"גביר תלמיד חכם מזעלודאק. חתנו - ר מאיר שלמה אביגדור רבינוביץ."},{"i":53619,"n":"שכנוביץ, מנחם דוב","bt":"תרכו","dt":"תרצ - ז ניסן","b":"רב בדאלהינוב"},{"i":53620,"n":"שכנוביץ, ש.","b":"פרסם מאמרים ב\"בית המדרש\" - מונטרה תש.. - אודות ישיבת וולוזין."},{"i":53621,"n":"שכנר, מנחם מנדל מסנוק","dt":"תש..","b":"למד בישיבות הונגריה, חזר לסנוק-תרפו, וכיהן כאדמור, סירב לקבל \"פדיונות\" ללא תמורה - כמו שיעור, הדרכה וכדומה. נספה בשואה עם משפחתו."},{"i":53622,"n":"שכרלס, אברהם דוד מפרשבורג","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":53623,"n":"שכרלס, דוד מפרשבורג","f":"ר\"י","dt":"תקעא","dp":"פרשבורג","b":"נהרג עק\"ה."},{"i":53624,"n":"שכרלס, זלמן מפרשבורג","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":53625,"n":"שכרלס, יוסף מפרשבורג","f":"זלמן","b":"מחכמי פרשבורג, חתם-תקנז על חידוש תקנות החברא קדישא שתיקן ר יום טוב ליפמן מפרשבורג."},{"i":53626,"n":"שכרלס, יעקב מפרשבורג","f":"מנדל","b":"מראשי קהלת פרשבורג-תקסז, חתם על תקנות הח\"ק בפרשבורג-תקס, ועל כתב מנוי הרבנות לחת\"ס-תקסז."},{"i":53627,"n":"שכרלס, יעקב קופל מפרשבורג","f":"יצחק","k":"בעל בני יעקב","b":"מחכמי פרשבורג. חיבר הגהות על ספר הישר בשם \"בני יעקב\", \"פרפראות לחכמה\" עם הסכמה מחת\"ס."},{"i":53628,"n":"שכרלס, יצחק מפרשבורג","f":"שמעון מפרג","k":"בעל קרבן אשם","b":"רב בפרג, הגיע לפרשבורג אחרי גירוש פרג, וכיהן כדומ\"צ בפרשבורג-תקכ אצל ר מאיר ברבי - שנתן הסכמה לספרו \"קרבן אשם\"."},{"i":53629,"n":"שכרלס, ליב מפרשבורג","f":"יוסף","b":"מחכמי פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח, ותקנות הח\"ק-תקכה, ועוד."},{"i":53630,"n":"שכרלס, מנדל מפרשבורג","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":53631,"n":"שכרלס, משה מפרשבורג","f":"מיכאל","b":"גבאי צדקה בפרשבורג, סייע לאחר השריפה-תקעא."},{"i":53632,"n":"שכרלס-שטרן, יהודה ליב מפרשבו","bt":"תקעב","bp":"פרשבורג","dt":"תרנד - יא ניסן","dp":"ירושלים","b":"תלמיד החת\"ס. עלה לירושלים-תקצז."},{"i":53633,"n":"שלאם, ברוך","bt":"תריז","dt":"תרפז","b":"רב ביוהניסבורג-תרס\"ד,"},{"i":53634,"n":"שלגר, אברהם מבקשביץ","f":"אהרן משה מבלז","bt":"תרי","dt":"תרעב","b":"חסיד בלז. חתן ר מנחם מנדל מבקשביץ, ועבר לשם, בזיוו\"ש חתן ר יושע דב לינדן. מקורב לאדמורי הדור. אחיו ר אהרן משה יהודה פרנס את אלמנתו אחריו."},{"i":53635,"n":"שלגר, אברהם מבקשביץ","f":"משלם זלמן מבקשביץ","k":"אדמור מבקשביץ","dt":"תרם - בערך","dp":"צפת","b":"אדמור בבקשביץ, חתנו ר מנחם מנדל מבקשביץ על מקומו אחריו - תלמיד מהרי\"א מזידיטשוב. מחסידי ר מאיר מפרימישלן. עלה לצפת."},{"i":53636,"n":"שלגר, יחיאל מיכל מבקשביץ","f":"אברהם מבקשביץ","k":"בעל משברי ים","bt":"תרמו","dt":"תשיז","b":"לפני בר המצווה ידע את הפרי מגדים בע\"פ. חתן ר יוסף פרידמן מגווזדיץ ועבר לשם, ובזיוו\"ש חתן ר אליעזר לנדא מבערהאמעט. רב בקלויז של אביו בבשקביץ על מקום אביו. עבר לסטרי לאחר חורבן העיר במלחמת העולם ה-I. ניצל מהשואה, ואחריה רב בבודפשט, עלה לירושלים-תשי, והיה מקורב לגדולי האדמורים בארץ. חיבר \"משברי ים\" סעאיני תרצה, ועוד. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":53637,"n":"שלגר, יצחק מבקשביץ","f":"משלם זלמן בקשביץ","b":"רב בבקשביץ על מקום אביו, בנו ר מרדכי לינדן על מקומו אחריו. תלמיד דודו ר משולם פיביש מזבריז. חתן הגביר ר יושע אקסלרוד."},{"i":53638,"n":"שלגר, משלם זלמן מבקשביץ","f":"מרדכי מברזן","b":"רבה הראשון של בקשביץ, בנו ר יצחק על מקומו אחריו."},{"i":53639,"n":"שלגר, שלום מסטרליסק","f":"יהושע צבי מסוירז","k":"בעל דברי שלום","dt":"תרמז - בערך","b":"מחסידי השרף מסטרליסק. אחיו - ר אורי מפרישמלן השתדל בהדפסת ספרו. חיבר \"דברי שלום\" פירוש לתהלים - למברג תרמח."},{"i":53640,"n":"שלדין, הנפריד","b":"רב במונסון-קנ\"ה"},{"i":53641,"n":"שלדין, זרחיה הלוי מסרגוסה","f":"יצחק","b":"אחד החכמים שהשתתפו בויכוח לפני האפיפיור בנדיקט ה- 13- בשנת ה'קיג - להשיב על טענות המומר ג'רונימו די סנטה פה. תרגם \"הפלת הפלסופים\" לאלגזלי - לבקשת דון בנבנשתי בן לביא."},{"i":53642,"n":"שלובסקי, משה יודל","k":"בעל אין דער היים","bt":"1885","bp":"ליטא","b":"פעיל בתנועה המהפכנית ס.ס. ברוסיה. היגר לארה\"ב עם אשתו חייקה כהן-ממנהיגות פועלי ציון. הקים רשת גדולה של בתי ספר על שם \"שלום עליכם\", ופעל להפצת ספרות באידיש, יסד הוצאת ספרים שהוציאה את כתבי אברהם רייזין, פינסק, ועוד. פרסם מאמרים בעתונות היהודית באמריקה. חיבר גם \"אויף א פולער וואך, ועוד."},{"i":53643,"n":"שלוכטמן, יהושע מגריווא","b":"מראשי קהלת גריווא-תרח, יסד בימ\"ד עם ר שמריה בן אליעזר הלרמן."},{"i":53644,"n":"שלום (שלמה) מקאמין קשורסק","f":"דוד - חומות ירושלים","b":"רב בקאמין-קשורסק-תקץ. בנו - ר צבי הירש מנישוויז."},{"i":53645,"n":"שלום ברוך מירושלים","dt":"תריח","dp":"ירושלים","b":"מחכמי ירושלים, מאנשי כולל וארשא. בנו - ר צבי אלימלך."},{"i":53646,"n":"שלום דב הכהן","dt":"תשג","b":"מרביץ תורה בפוניבאז"},{"i":53647,"n":"שלום הכהן מאלגיר","bt":"תרן - בערך","dt":"תשך - בערך","b":"רב בג'יריוויל(=אל באייאד)-אלגיר. שאלות ממנו לר מסעוד בעל \"פרחי כהונה\" ונזכר בספרו."},{"i":53648,"n":"שלום הכהן מג'רבה","k":"בעל חפץ יקר","bt":"תקצה","bp":"ג'רבא","dt":"תרפו - יא תשרי","dp":"טבריה","b":"נכדו של ר שאול הכהן מג'רבא בעל \"לחם בכורים\". מחכמי ג'רבא, רב בזרזיס, עלה לארץ-תרפד וכיהן כרב בטבריה. נזכר ב\"בית אברהם\" לר אברהם הכהן, וב\"פרח שושן\" לר שושן הכהן, ועוד. חיבר גם \"שערי שלום\", \"נהר שלום\", ועוד."},{"i":53649,"n":"שלום הכהן מהמבורג","f":"יעקב","k":"בעל דברי אגור","bp":"מזריטש-פולין","dt":"תרה - יד אד\"א","dp":"המבורג","b":"עבר להמבורג, משורר ופייטן, הו\"ל \"המאסף\", \"אחרי המאספים\". חיבר גם \"תפארת ישראל\", \"מטעי קדם\", ועוד."},{"i":53650,"n":"שלום הכהן מצפת","b":"מחכמי צפת-של. גיסו של בעל \"ראשית חכמה\". מתורתו בספר נכדו - \"ברכת טוב\"."},{"i":53651,"n":"שלום הכהן מקושטא","b":"רב בקושטא. חתן ר יהושע צונצין שהשיב לו בספרו. מצאצאי ר נסים יעקב הלוי מקושטא. התכתב עם מוהרש\"א אלפנדרי. חיבר שו\"ת הר\"ש הכהן מקושטא - ירושלים."},{"i":53652,"n":"שלום הכהן מקראקא","b":"רב בקרקא-שנת ש'"},{"i":53653,"n":"שלום הכהן מתימן","f":"סעדיה","bt":"תע","bp":"צנעא","dt":"תקמה","dp":"צנעא","b":"דיין בצנעא אצל המהרי\"ץ."},{"i":53654,"n":"שלום הלוי מתונס","b":"מחכמי תונס. נזכר ב\"תולדות יצחק\" לר יצחק חדאד."},{"i":53655,"n":"שלום הלוי מתימן","f":"יחיא","b":"מגדולי חכמי תימן,עלה לא\"י-תשט\"ו,מרבני תל אביב"},{"i":53656,"n":"שלום הלוי מתימן","f":"מת'נא","dt":"תרצא","dp":"דמת-תימן","b":"רב בדמת-תימן. חתם על פסקי דין-תרעב - תרפז. עמד בקשרים עם חכמי צנעא, עדן, וטבריה."},{"i":53657,"n":"שלום הלוי סגל מפודהייץ","bt":"תרך","bp":"פודהייץ","dt":"תרעח","dp":"צפת","b":"מחסידי בלז. עלה לצפת, נסע לביקור אצל אדמורי פולין. חתן נכדת ר צבי הירש מזידיטשוב. בנו ר שלמה יהודה אבי משפחה גדולה של חסידי חב\"ד בחברון וירושלים."},{"i":53658,"n":"שלום זליג הכהן מקרלסבורג","f":"שאול כהן ציון","b":"רב בקרלסבורג והמדינה-תק על מקום ר יוסף רייס-אוירבך."},{"i":53659,"n":"שלום זליג הכהן מקרלסבורג","f":"שאול","b":"רב בקרלסבורג ורב הכולל לטרנסילבניה-תקיד, ועזב-תקיח."},{"i":53660,"n":"שלום טוביה משונציאן","f":"ברוך מסוגינדט","dt":"תרח ו-ז אלול","dp":"שונציאן","b":"תלמיד ר אליהו רגולר מקאליש. רב בשונציאן-תרג. אחיו - ר אליהו מאיר מראסיין. בנו - ר ברוך ברוידא מקובנא."},{"i":53661,"n":"שלום יוסף","dt":"תרפד - יד שבט","b":"רב ביוזעפוף"},{"i":53662,"n":"שלום יעקב מנחם מתימן","bt":"תרמא","bp":"עדן-תימן","dt":"תשו - יז אד\"א","dp":"ירושלים","b":"ראש ישיבה בעדן, עמד בקשר עם ר יחיא יצחק הלוי מצנעא. תיקן תקנות, והסמיך שוחטים ורבנים בעדן. עלה לירושלים-תשד, ונקבר סמוך לרש\"ש."},{"i":53663,"n":"שלום יצחק הלוי מתימן","f":"יחיא יצחק הלוי","k":"בעל דברי חכמים","bt":"תרנ-א","bp":"צנעא","dt":"תשלג - כו תמוז","b":"מחכמי צנעא-תימן, עלה לארץ-תרפג וכיהן כדיין בתל אביב, ורב העדה התימנית. חיבר גם \"דברי חכמים\".","bk":[["דברי חכמים","שו\"ת - אחרונים"],["דברי חכמים – שו\"ע ושו\"ת",""]]},{"i":53664,"n":"שלום מבאניהאד","b":"דומ\"צ בבאניהאד-תקצ\"ו"},{"i":53665,"n":"שלום מבויסק וירושלים","f":"משה","dt":"תרסג","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תריב בשליחות ברוסיה נשא שם אישה וחזר בשנת תרך. עסק כל היום בתורה ופרנסתו ממסחר בתבואות שעסקה אשתו. בנו - ר בן ציון זילברשטין מירושלים, חתנו - ר בנימין בן יוסף יואל ריבלין, ונכדו פרופ' אליעזר ריבלין."},{"i":53666,"n":"שלום מבוקין","b":"רב בבוקין-תר\"י"},{"i":53667,"n":"שלום מהורודוק","b":"מחסידי ר אהרן הגדול מקרלין, ובנו ר אשר מסטולין. מתורתו בקובץ \"בית אהרן וישראל\". רבו האדמור מסטולין אמר עליו כי כשיסביר בעולם האמת מה פעל בחייו יאמר \"שלום\" (והכוונה לחסידו זה)."},{"i":53668,"n":"שלום מוילייקא","b":"תלמיד ר מרדכי מלכוביץ. רב במייצט, וילייקא-במינוי רבו. רבו האדמור מלכוביץ אמר עליו \"אני גדול מר שלום כי אם במשהו, כחוט השערה, אלא שמשהו זה לא יוכל להשיג לעולם\"."},{"i":53669,"n":"שלום מוילנא","f":"מנחם נחום שמש וילנא","dt":"תקצא - יט חשון","dp":"וילנא","b":"מו\"ץ בוילנא. היהודי האחרון שנקבר בבית העלמין הישן. בנו - ר יהושע על מקומו אחריו."},{"i":53670,"n":"שלום מוילנא","f":"גרשום מנדל","dt":"תקיט - ל אב","dp":"וילנא","b":"מראשי קהלת וילנא. אחיו - ר ישכר בער מוילנא, חתם-תץ עם ראשי הפרנסים."},{"i":53671,"n":"שלום מוישנה","dt":"תקצא - יח חשון","b":"נקי כפים,רב בווישנה"},{"i":53672,"n":"שלום מלבוב","b":"מו\"צ בלבוב, חתם-תכד על פס\"ד עם ר דוד מלודמיר, ר אברהם גרויפין, ר אברהם גרויפין, ועוד."},{"i":53673,"n":"שלום מלבוב","f":"ניסן","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":53674,"n":"שלום מניישטט-אסטרייך ובודין","k":"השר מנוישטט","b":"גדול חכמי אסטרייך, פוסק, ממעצבי ההלכה ומנהגי ישראל לדורותיו, מרביץ תורה, רב בווינר(=וינה)-נוישטט-קמ, בודין(=בודפשט). מתלמידיו - ר דוסא בן משה היוני מבודין, בעל תרומת הדשן. בנו - ר יצחק."},{"i":53675,"n":"שלום מפוסוול","dt":"תקנ - יג טבת","b":"רב בפוסבול"},{"i":53676,"n":"שלום מקולבסוב","b":"מחכמי קולבסוב - תשובה אליו ב\"משיב כהלכה\"."},{"i":53677,"n":"שלום מקראקא","b":"מגדולי חכמי דורו בקרקא-ש\"ע"},{"i":53678,"n":"שלום מראשקוב","f":"שלמה זלמינא","k":"אדמור מרשקוב-קולוראש","bt":"תרנד","dt":"תרץ - כא אייר","b":"חתן ר יצחק מברזנא (סטפין), ובזיוו\"ש חתן ר מרדכי מלויאב (טשרנוביל). אדמור בקולוראש-בסרביה. היגר לארה\"ב ונפטר צעיר."},{"i":53679,"n":"שלום מרדכי הכהן","r":"יחד עם בנו ר' יצחק שנולד בתרי\"ז ונפטר יט חשון תרפ","bt":"כז ניסן תקצה","dt":"טז שבט תרעא","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט.","bk":[["עין הרועים -",""]]},{"i":53680,"n":"שלום מרוביזויץ","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":53681,"n":"שלום משאט","f":"שמואל הקטן","b":"רב בשאט-ת\"ר"},{"i":53682,"n":"שלום משערשוב וירושלים","f":"דוד","dt":"תריג - חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":53683,"n":"שלום מתימן","f":"נסים","b":"רב באלצ'אלע-תימן - בשנות ה-תש'. חתם על מסמכים שונים."},{"i":53684,"n":"שלום צבי הכהן מזגרזש","bt":"תקמט","dt":"תרלז - ו טבת","b":"חתן הגביר ר יעקב אהרן הכהן שאטאן מליומירסק-זקנו של ר חנוך הניך מאלכסנדר. תלמיד היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק ועוד. רבה הראשון של זגערזש-תרל וניהל בה ישיבה."},{"i":53685,"n":"שלום צבי מגרבוביץ","b":"פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד."},{"i":53686,"n":"שלום צבי מזלישטשיק","b":"מחכמי זלישטשיק - תשובה אליו ב\"שואל ומשיב\"-תרכה."},{"i":53687,"n":"שלום ראובן מאזמיר","b":"רב באזמיר-שנות ה-ש'."},{"i":53688,"n":"שלום שכנא","k":"חתן בעל התניא","b":"רב-שנת תקסו. בנו: ר מנחם מנדל הצמח צדק. בנו או חתנו - ר ישעיה הורביץ."},{"i":53689,"n":"שלום שכנא הכהן","f":"יונה נחום מסוכטשוב","k":"בעל מאה ברכות","b":"הו\"ל \"קרבן אהרן\"-וילמשדורף תעז."},{"i":53690,"n":"שלום שכנא מטורצין","b":"רב בטורצין-ת\"צ"},{"i":53691,"n":"שלום שכנא מלובלין","f":"יוסף(65349)","dt":"שיט-ז - א כסלו","dp":"לובלין","b":"מצאצאי ר שלום מניישטט וינה. תלמיד ר יעקב פולק מפרג. גדול רבני פולין בדורו, רב וראש ישיבה בלובלין. חתנו ותלמידו הרמ\"א. בנו - ר ישראל. עוד מתלמידיו: ר למל מלובלין, ר שלמה ר ליבשס, ר משה הלפרין בעל \"זכרון משה\", ר חיים בעל \"ספר החיים\" ו\"מים חיים\", ר זכריה מנדל המכונה \"זכריה הנביא\", ר עזרא זיסקינד מפוזן\", ר אלעזר בעל \"מעשה ה\", ועוד. מתורתו ב\"פליטת סופרים\" - וילנא תרכג."},{"i":53692,"n":"שלום שכנא מפרובישץ","f":"אברהם המלאך","k":"אדמור מפרובישץ","bt":"תקכט","dt":"תקסג - יד תשרי","b":"נכד המגיד ממזריטש. חתן ר אברהם מקוריסטשוב. לאחר שנתייתם גדל אצל ר שלמה מקרלין. מתורתו והנהגותיו בספר אביו \"חסד לאברהם\", ו\"דברי שלום\". אביו של ר ישראל מרוזין."},{"i":53693,"n":"שלום שכנא מקונשטנטין","f":"דוד","b":"רב בקונשטנטין-תק\"י"},{"i":53694,"n":"שלום, אברהם מספרד וקושטא","f":"יצחק בן יהודה בן שמו","k":"בעל נוה שלום","dt":"רנב","b":"מגדולי חכמי קטלוניה-ספרד, מחכמי קושטא. פילוסוף ובקי במדעים. חיבר \"נוה שלום\" קושטא רצח, ומהר\"ם ן חביב הכין לספר מפתחות."},{"i":53695,"n":"שלום, אברהם מסרייבו","b":"רב בשאריי-בושנא"},{"i":53696,"n":"שלום, אליעזר מצפת","f":"אברהם","dt":"שכב","dp":"צפת","b":"תלמיד ר יוסף קארו, המבי\"ט, ר שלמה אלקבץ, ועוד. רב בצפת-ש' בקהל מגנסא. בנו ר אברהם שלום השני, ונכדו ר חייא שלום."},{"i":53697,"n":"שלום, אפרים משלוניקי","b":"מחכמי שאלוניקי, דרשן, דיין בשלוניקי-תמז."},{"i":53698,"n":"שלום, חייא מצפת","f":"אברהם","b":"רב בצפת-תמ, על מקום ר גבריאל איספירנסה, ואחיו ר יצחק על מקומו אחריו, היה גם במצרים והיה ממונה על הקדשי צפת וירושלים."},{"i":53699,"n":"שלום, יהודה אשטרוק","f":"שמואל שלום","k":"אשטרוק שלום","b":"רופא מחכמי ספרד-שנות ה-ק'-ר'. תרגם לעברית \"עיון שבע כוכבי לכת\" לבקשת ר רפאל בן יצחק מפאיינצו, ור שבתי בן מרדכי מסולמוני, ספר ההגיון. בנו - ר יצחק ונכדו ר אברהם בעל \"נוה שלום\". (ראה גם: אשטרוק קרשקש מספרד)"},{"i":53700,"n":"שלום, יוסף"},{"i":53701,"n":"שלום, יוסף אברהם מהודו","b":"גביר מבבל, התישב בהודו. ביקר בירושלים, תרם להקמת ישיבת \"פורת יוסף\" בירושלים ותמך בהחזקת הישיבה."},{"i":53702,"n":"שלום, יצחק","bt":"תרמו","bp":"[ארם צובא]","dt":"תשכח","b":"היגר לארה\"ב-תרע - והתעשר. ממיסדי \"אוצר התורה\" ו\"הועדה לטיפול במליון האבוד\" ופעל רבות למען שיקום עולם התורה הספרדי - בעיקר במרוקו."},{"i":53703,"n":"שלום, יצחק מספרד","f":"יהודה אשטרוק","k":"בעל נוה שלום","dt":"רנב","b":"רופא מחכמי ספרד. חיבר פירוש על \"אבן סינא\". בנו - ר אברהם שלום בעל \"נוה שלום\". נכדו (בן בתו) - ר חיים ויטאל."},{"i":53704,"n":"שלום, יצחק מצפת","f":"אברהם","dt":"תנג","dp":"צפת?","b":"מחכמי צפת-תמה, אחיו של ר חייא שלום. רב ראשי בצפת-תמד על מקום אחיו ור גבריאל איספירנסה, חתם בשנת תמח עם חכמי צפת. בשנת תמז הסכים על \"שער אפרים\" לר אפרים הכהן."},{"i":53705,"n":"שלום, יצחק משלוניקי","dt":"תקיז - בערך","dp":"שלוניקי","b":"גביר בשלוניקי. יסד ישיבה בבית ר יצחק ן שאנג'י."},{"i":53706,"n":"שלום, יצחק נסים מירושלים","dt":"תקן - אחרי","b":"מקובל, מחכמי ישיבת \"חסד לאברהם\" בירושלים-תקיח."},{"i":53707,"n":"שלום, מ' א' מפדובה","b":"ראש הקהלה בפדובה-תרכג."},{"i":53708,"n":"שלום, רפאל אברהם משלוניקי","k":"רא\"ש - בעל מנחל בדרך","b":"מחכמי שלוניקי, מכונה רא\"ש."},{"i":53709,"n":"שלום, שמואל מצרפת","b":"מגדולי רבני צרפת,מרביץ תורה בפירפיניאן-ש\"פ"},{"i":53710,"n":"שלומוביץ, אברהם אבא מיאנוב","f":"זאב מרדכי","k":"בעל נגה אש","bt":"תריב","bp":"יאנובה","dt":"תרסו","dp":"וילנא","b":"נכד ר אברהם אבלי מקרוז'. תלמיד ר שמואל נפתלי הירש אפשטין בעל \"אמרי שפר\". חתן הגביר ר מיכל גליקמן. היה מ\"פרושי קובנא\". יסד ישיבה באוטיאן. ידידו של ר בנימין איזנשטאט. רב בסויאדושץ'-תרנד-תרסג. חיבר גם הוספות והערות ל\"פתחי תשובה\". בנו - ר יעקב - שו\"ב בפישלאט-פלך קובנא."},{"i":53711,"n":"שלומוביץ, חיים יהודה","b":"חתן ר ר יקותיאל יהודה גרינוולד מיארע. רב בסלאטווינט."},{"i":53712,"n":"שלומוביץ, יצחק","dt":"תשג","b":"רב בנאניענץ-ביאליסטוק"},{"i":53713,"n":"שלומוביץ, יצחק מטומשוב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":53714,"n":"שלומוביץ, ישראל","f":"משה","k":"בעל בית ישראל","dt":"תשב-ג","b":"תלמיד ישיבת סלובודקא, טלז. נסמך מאת ר אליהו ברוך קמאי. ר\"מ בישיבת \"תורת חסד\" בלודז-תרעב, ישיבת מיר בוילנא, רב באמסטינוב, בייסיגלה, גוניונדז-ווהלין-תרס, נספה בשואה."},{"i":53715,"n":"שלומר, אהרן מסטניסלב","b":"מחכמי סטניסלב - תשובה אליו ב\"קנאת סופרים\"."},{"i":53716,"n":"שלוניקיאיו, אליעזר מתבץ","f":"משה","b":"רב בתבץ(=טיווה)-במוריאה-יון בדור שלאחר הגירוש. היה בקשרי שו\"ת עם הרא\"ם."},{"i":53717,"n":"שלוניקיאיו, משה משלוניקי","dt":"תקס - יב תשרי","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":53718,"n":"שלוס, אהרן הרץ מאופנבך","dt":"תקמו","b":"מחכמי פפד\"מ-תקך. רב באופנבך. חברו של ר נתן מאז והסכים על ספרו \"בנין שלמה\"."},{"i":53719,"n":"שלוס, יהודה חיים מפפד\"מ","f":"יעקב","dt":"תכד - כב ניסן","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ-תא, בזמן ר שבתי הורביץ-בנו של השל\"ה."},{"i":53720,"n":"שלוסברג, אברהם מאילקוסט","f":"יהודה אריה ליב","bt":"תרד","b":"רב באילקוסט(=אילוקסט)-פלך קורלנד-תרמה על מקום ר מרדכי מרגליות בעל \"סוגה בשושנים\". בנו - ר אידל מאילקוסט. אמו - רבקה יסדה בימ\"ד באילוקסט-תרכז."},{"i":53721,"n":"שלוסברג, אריה ליב מפאריס","k":"הו\"ל הלכות פסוקות","b":"מחכמי ורסיי-ליד פאריס."},{"i":53722,"n":"שלוסברג, דוד מירושלים","f":"משה","dt":"תרעח","dp":"ירושלים","b":"רב באודן, עלה לירושלים"},{"i":53723,"n":"שלוסברג, יוסף יחיאל ממינסק","f":"מאיר","dt":"תרמא - כ חשון","dp":"מינסק","b":"מחכמי מינסק. בניו - הגבירים ר משה ור מאיר ממוסקבה, ר שלום ממינסק."},{"i":53724,"n":"שלוסברג, משה אליעזר מלייפציג","b":"רב במאלאט-תר\"פ,לייפציג"},{"i":53725,"n":"שלוסברג, שלמה מאנגליה","f":"יעקב מאיר","k":"בעל אור יעקב","bt":"תרכט","b":"תלמיד ישיבת איישישוק, ר יצחק יעקב ריינס. חתן ר אברהם אהרן יודלביץ בעל \"בית אב\". רב באניקשט-פלך קובנא-תרנד על מקום ר משה יואל גוריון ור אברהם אהרן בורשטין על מקומו אחריו, קפוליא-פלך מינסק, מנצסטר-אנגליה. נסמך מאת: ר יצחק אלחנן מקובנא, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ר מאיר שמחה הכהן בעל \"אור שמח\", ר יוסף רוזין-הרוגצובר. חיבר גם \"גן הדסים\"."},{"i":53726,"n":"שלוסטש, דוד שלמה","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":53727,"n":"שלוסמן, עקיבא מפלשטין","b":"רב בפלשטין-תריח."},{"i":53728,"n":"שלוסמן, שלמה","b":"מקובל שנעלם מביתו ולא ידוע אם יצא לגלות או שעלה לצפת. נינו - הסופר דב בריש וינשטיין (נולד ברישא תרסה)."},{"i":53729,"n":"שלוסר, מאיר יעקב מאטיניא","b":"רב באטיניא-תרלג."},{"i":53730,"n":"שלוץ, משה אריה ליב","f":"שמואל דוד","bt":"תר","b":"רב בהלוכאב(=הלוכאוו)-פלך צרניגוב-תרן."},{"i":53731,"n":"שלוש, אברהם מאלגיר ויפו","f":"אהרן","dt":"תריח - ח סיון","dp":"יפו","b":"מחכמי ווהראן(=אוראן)-אלגיר, עלה ליפו-תר - בהיותם ליד החוף התהפכה אחת הסירות ו-28 עולים וביניהם 2 ילדיו של ר אברהם טבעו. הקים בית כנסת וישיבה ביפו ובין התלמידים שם: ר יעקב סמחון, ר שלמה בוחבוט, ר שלמה חזן, ועוד. מראשי הישוב ביפו."},{"i":53732,"n":"שלוש, אברהם מירושלים","b":"פרסם מאמרים ב\"מוריה\" - ירושלים תשג."},{"i":53733,"n":"שלוש, אהרן מאלגיר","f":"אברהם","bt":"תקפט","bp":"אוראן-אלגיר","dt":"תרף - יז ניסן","dp":"יפו","b":"עלה עם אביו מווהראן ליפו-תר, גאל אדמות ביפו, ממיסדי שכונות \"נוה שלום\", ו\"נוה צדק\" ביפו, וממיסדי \"אחוזת בית\" - תל אביב."},{"i":53734,"n":"שלוש, דוד ממראקש","dt":"תרנג - יג כסלו","b":"ר\"מ מחכמי מראקש."},{"i":53735,"n":"שלוש, דוד ממרוקו","dt":"תרנ","b":"מקובל, מחכמי מראקש"},{"i":53736,"n":"שלוש, יוסף אליהו מיפו","f":"אהרן","k":"בעל פרשת חיי","bt":"תרל","bp":"יפו","dt":"תרצד - יא אב","dp":"תל אביב","b":"עסקן צבור ביפו ותל אביב. חיבר \"פרשת חיי\" תל אביב תרצא."},{"i":53737,"n":"שלוש, יוסף מירושלים","bt":"תרנא","bp":"מראקש-מרוקו","dt":"תשכ - ל סיון","b":"מחכמי מרוקו, עלה לירושלים-תרסו מראשי עדת המערבים בירושלים, ומחכמי \"פורת יוסף\"."},{"i":53738,"n":"שלוש, יעקב מיפו","f":"אהרן","bt":"תרם","bp":"יפו","b":"עסקן צבור בתל אביב. אחיו של יוסף אליהו."},{"i":53739,"n":"שלוש, מכלוף ממכנאס","b":"מחכמי מכנאס-תקפט."},{"i":53740,"n":"שלוש, מכלוף משה אהרן","bp":"פאס","dt":"תרפט - טו אלול","b":"מחכמי פאס, נכד ר אברהם ישראל הצרפתי. עלה לירושלים-תרנב, בטבריה-תרפט, עבר לניו יורק-תרפט. חיבר דרושים ולקוטים בכת\"י."},{"i":53741,"n":"שלוש, מרדכי ממכנאס","b":"מחכמי מכנאס."},{"i":53742,"n":"שלוש, משה מיפו","f":"יוסף אליהו","bt":"תרמב","bp":"יפו","b":"עסקן צבור בתל אביב."},{"i":53743,"n":"שלוש, משה ממכנאס","dt":"תקסד - אחרי","b":"סופר בי\"ד במכנאס, חתם-תקנח עם ר יצחק אסקירא."},{"i":53744,"n":"שלזברג, שלמה יוסף מקוללשאק","f":"ישעיה","bt":"תרלו","b":"ממשפחת ר חיים מוולוזין. רב בקאלעלשאק-פלך וילנא-תרסד, בזמן מלחה\"ע ה-I גלה לסמולנסק וכיהן כרב עד שאבדו עקבותיו."},{"i":53745,"n":"שלזינגר, אברהם משה דובר הכהן","k":"בעל טוב עין","b":"מחכמי ירושלים."},{"i":53746,"n":"שלזינגר, אליעזר ליפמן","f":"געטשליק מהמבורג","k":"החסיד מאשכנז","bt":"תרך","dt":"תרצד","b":"אחד מ\"ארבעה הצדיקים של ר געטש\". תלמיד ר רפאל שפירא בבוברויסק, עסק בתורה בהמבורג ולפרנסתו לימד מתמטיקה וכימיה - סירב להצעה ללמד באוניברסיטה. היה מוערך ע\"י גדולי ליטא. בנו - ר יחיאל מיכל מיסד ישיבת קול תורה בירושלים."},{"i":53747,"n":"שלזינגר, געטשליק א' מהמבורג","f":"דוד","bt":"תקעג-ד","bp":"פלעהינגן-ליד קרלסרוהא","dt":"תרס - כ אלול","dp":"המבורג","b":"תלמיד ר יוסף עטלינגר, ר ליב בודנהיימר מקרלסרוהא, ישיבת ר יעקב עטלינגר במנהיים ועבר עמו לאלטונא וכיהן כר\"מ בישיבה של רבו, מחכמי הקלויז בהמבורג על מקום ר יוסף הנובר-תרה, דיין בהמבורג-תרה אצל ר אשר שטרן, וממלא מקומו. פרסם מאמרים ב\"שומר ציון הנאמן\", שו\"ת \"בנין ציון\". הסכים על \"מגיד מישרים\", \"בית אבות\". ארבעת בניו נקראו \"ארבעת הצדיקים של ר געטש\"."},{"i":53748,"n":"שלזינגר, דב בריש מברוד","k":"בעל נחלי דבש","dt":"תרכג - בערך","b":"רב ומחנך בברודי, ובלמברג. מקורב לר יוסף נתנזון בעל השו\"מ. רב בנריוב.חיבר \"נחלי דבש\" למברג תרכד."},{"i":53749,"n":"שלזינגר, דניאל משאלגא-טאריאן","b":"חתן ר שרגא פייש פולק מוויצען. רב בשאלגא-טאריאן."},{"i":53750,"n":"שלזינגר, וולף מזולצבך","k":"בעל הערות על העקרים","dp":"זולצבך","b":"רב בזולצבך, תרגם ספר העיקרים לל\"א, עם מבוא והערות - פפדמ תקצח. תמך במורדים - תרח (1848), ונאלץ לברוח לאמריקה, ושם כתב בכתב העת \"אקסידענט\" לר יצחק ליסער מפילדלפיה, רב בניו יורק, ולאחר שנרגעו הרוחות באוסטריה חזר לזולצבך. חיבר הערות על ספר העיקרים - פפד\"מ תקצח. ?? לא באוצר ??"},{"i":53751,"n":"שלזינגר, חיים יהודה מפעדא","f":"יצחק דב","r":"מו\"ץ דבודפסט","dt":"תשג - ב אב","b":"רב בפעדא-יגוסלביה-תרסה, דיין בבודפשט-תרעט.","bk":[["ישועה ונחמה",""],["לקוטי יהודה",""]]},{"i":53752,"n":"שלזינגר, טוביה דב מדוסיאט","dt":"תשא - אלול","b":"רב באבעל-ליטא, רבה האחרון של דוסיאט-ליטא. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"עמק הלכה\" - באטארקס תרפא."},{"i":53753,"n":"שלזינגר, יוסף מפרשבורג","b":"בעל בית מסחר ספרים בפרשבורג-תרנו."},{"i":53754,"n":"שלזינגר, יחיאל מפפד\"מ וירושלים","bp":"פפד\"מ","dt":"תשט - ט אדר","dp":"ירושלים","b":"תלמיד ישיבת סלובודקה, מיר, פוניבז. דיין בקהל \"עדת ישורון\" בפפד\"מ-תרצז, ברח בליל הבדולח לשוייץ, עלה לירושלים-תרצט, הקים ישיבת קול תורה. פרסם מאמרים ב\"ישורון\" - ברלין תרף. החזון איש אמר עליו כי הוא \"חפץ חיים שני\"."},{"i":53755,"n":"שלזינגר, יחיאל מפרשבורג","f":"צבי דב","k":"בעל זכרון דברים","bt":"תקע","bp":"פרשבורג","dt":"תרנא - ל אב","dp":"פרשבורג","b":"תלמיד החת\"ס. חתן ר יוסף שמואל שוורץ מפרשבורג. רב בפרשבורג. חיבר \"דברי יחיאל\" בתוך ספר בנו ר עקיבא יוסף מירושלים - \"תורת יחיאל\". חתנו ר אברהם אבא הרצל על מקומו אחריו. חתנו - ר הלל ליכטנשטין - רב בקאלאמיא. היה מקורב לחת\"ס כל ימיו ואח\"כ לבניו."},{"i":53756,"n":"שלזינגר, יעקב שמואל מפרשבורג","f":"יחיאל","bt":"תריב","bp":"פרשבורג","dt":"תרפג - כ אלול","dp":"פרשבורג","b":"תלמיד הכת\"ס והשב\"ס. רב וגבאי בישיבת פרשבורג, ציר בועידת המזרחי-תרסד. בעל תוקע בבית המדרש של הישיבה וניסו לנשלו לאחר שהשתתף בועידה הציונית של ה\"מזרחי\", אולם הוחזר לתפקידו בגלל מעשה שהיה. אחיו של ר עקיבא יוסף שלזינגר."},{"i":53757,"n":"שלזינגר, ישכר דב בר מקלן-מעהרן","k":"בעל ספר חשמונאים","b":"מחכמי קאללן-מעהרן. חיבר ספר החשמונאים - בדרך שיר."},{"i":53758,"n":"שלזינגר, ישראל דוד מפעסט","f":"מרדכי מרגליות יפה","dt":"תשכא","b":"רב בסולנוק,מו\"צ בפעסט,עלה לא\"י בחולון"},{"i":53759,"n":"שלזינגר, ישראל מוילאפאליא","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":53760,"n":"שלזינגר, כלב פיבל מטאפלטשן","f":"נחום מטרנטשין","k":"בעל תורת בר נש","bt":"תקפח","bp":"טרענטשין","dt":"תרעא - ח ניסן","dp":"טאפלטשן","b":"תלמיד הכת\"ס, ור חיים יוסף מטרעביטש. חתן ר אהרן יוסף שמואל סגל מטרענטשין. גר בוינה, רב במאר-תריז, טאפלטשן-תרלב כ-50 שנה - ובזמנו שמר על אחדות הקהילה, ובנו ר נחום על מקומו אחריו. מתשובותיו ב\"אבני חשן\", ובספר בנו \"חזון נחום\"."},{"i":53761,"n":"שלזינגר, מיכאל","b":"פרסם מאמרים ב\"ישורון\" - ברלין תרף."},{"i":53762,"n":"שלזינגר, מרדכי מאיזנשטט","b":"נכד ר יוסף שלזינגר מראיקה. גיסו של ר שלמה שור-רבה של רומניה. רב באראניוש-מאריוט על מקום חותנו ניצל מהשואה ועלה לארץ, דיין בתל אביב, ומנהל ביהמ\"ד ליוצאי נייטרא. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":53763,"n":"שלזינגר, מרדכי מקירכברג","f":"ישראל דוד מפעזינג","k":"בעל שאל לך אות","bt":"תקצח","dt":"תרסז - כג חשון","b":"גדול בנגלה ונסתר,רב בקירכברג,מג\"מ בבודפשט"},{"i":53764,"n":"שלזינגר, מרדכי צבי מלקנבך","f":"שמואל","bp":"קוברסדורף","dt":"תרנו-ז -יז כסלו","dp":"נאדי-פאלו","b":"דומ\"צ בלקנבך, רב בנאדיפאלו."},{"i":53765,"n":"שלזינגר, משה","bt":"1885","bp":"קיידאן","dt":"1932","dp":"ארה\"ב","b":"היגר בילדותו לארה\"ב, פעיל במפלגת העבודה הסוציאליסטית וממיסדי \"אינטרנשיונל ליידיס גארמנט וורקרס יוניון\" ונשיאה. יצג את תנועת הפועלים האמריקאית בקונגרסים בינלאומיים."},{"i":53766,"n":"שלזינגר, משה ישכר בער מפאקש","f":"ישראל דוד יפה-מרגליו","b":"מחכמי פאקש. חתניו - ר יצחק קרפל מפאקש, ר אברהם מילר מפאקש, ר יצחק מאיר צובל מפאקש, ור יהושע השל וייס ממעדיער."},{"i":53767,"n":"שלזינגר, משה מהלברשטט","b":"רב בהלברשטט,עלה לא\"י-תרצ\"ט"},{"i":53768,"n":"שלזינגר, משה מפרשבורג","f":"אריה יהודה","bt":"תריד","dt":"תרצח - יד אייר","dp":"פרשבורג","b":"תלמיד הכת\"ס."},{"i":53769,"n":"שלזינגר, משה סגל מאונסדורף","b":"גביר מראשי קהלת אונסדורף יחד עם ר שמואל בן מרדכי מהעלישוי."},{"i":53770,"n":"שלזינגר, נחום מטאפלטשן","f":"כלב פיבל-תורת בר נש","dt":"תרעז - כו תמוז","b":"רב בטאפולטשין(=טאפלטשן)-תרעא בחיי אביו ועל מקומו אחריו, ור יצחק שוייגר על מקומו אחריו."},{"i":53771,"n":"שלזינגר, נפתלי הירש מפפד\"מ","f":"אורי","k":"בעל שאלת חכם","b":"רופא מחכמי פפד\"מ. חיבר \"שאלת חכם\" אודות הלנת מתים לפי ההלכה - פפד\"מ תקס."},{"i":53772,"n":"שלזינגר, עקיבא יוסף מירושלים","f":"יחיאל","k":"בעל לב העברי","r":"עיבר\"י ראשי תיבות עקיבא יוסף ב\"ר יחיאל","bt":"תקצח","bp":"פרשבורג","dt":"תרפב - א אייר","dp":"ירושלים","b":"תלמיד הכת\"ס, ומהרם שיק, ור שלמה קוועטש מניקלשבורג. חתן ר הלל ליטנשטין מקולומיא, דיין אצלו במארגרטן, רב בסיקסא, קולומיא. עלה לירושלים-תרל. בנו - ר שמעון.","bk":[["בית יוסף חדש",""],["ברית עולם האחרון",""],["ברית עולם קמא",""],["חברה מחזירי עטרה ליושנה עם כולל העברים",""],["לב העיברי – צוואת החת\"ס",""],["מעשה אבות – תקנות",""],["שמרו משפט",""],["תורת יחיאל – בראשית",""]]},{"i":53773,"n":"שלזינגר, צבי דב הרש בער","f":"יחיאל מפרשבורג","bt":"תקמא","dt":"תריח - יג חשון","dp":"פרשבורג","b":"תלמיד החת\"ס, ור מרדכי בנט מניקלשוברג. מחכמי פרשבורג-תקפה."},{"i":53774,"n":"שלזינגר, שמואל זאב מאונגוואר","dt":"תשג","b":"רב באונגוואר. ואולי הוא ר שמואל זאב משאמלוי."},{"i":53775,"n":"שלזינגר, שמואל זאב משאמלוי","f":"בן ציון","dt":"תשד","b":"תלמיד ר שלמה זלמן ארנרייך משאמלוי(=שמלויא). מחכמי שאמלוי והתפרנס ממסחר. נספה בשואה. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"בית המדרש החדש\" - גריבה תרפח, \"החיים\" - אונגואר תרפב, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"לקט ששנ\"ה\" - סטמר תרצד, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה, \"שערי אורה\" - מיהאלביץ תרץ-תרצד. חיבר הגהות והערות על \"זרע אברהם\" - בכת\"י, ונערך ונדפס אחר פטירתו."},{"i":53776,"n":"שלזינגר, שמואל מדברצין","b":"חתן ר יהודה גרוסמן מאיפלשאג. רב בדברצין."},{"i":53777,"n":"שלזינגר, שמואל ממונור ודברצין","b":"רב הקהילה הניאולוגית במונור-תרעד, דברצן. מראשי הגימנסיה היהודית. לאחר פרישתו-תרפב יסדה הקהלה במונור ספריה על שמו."},{"i":53778,"n":"שלזינגר, שמואל קיצע משאהל","f":"חיים קיצע שלזינגר","dt":"תרנא - בערך","b":"תלמיד החת\"ס, והכת\"ס. חתן ר דוד טעבל שוורץ משאהל. רב בשאהל ויסד שם ישיבה. ציר בקונגרס היהודי-תרכט ופרש עם שאר הצירים החרדים, ופרסם יחד עם ר שמואל פרנקל מב\"ח, מכתב מחאה נגד חוקי הקונגרס."},{"i":53779,"n":"שלזינגר, שמעון","b":"תלמיד החת\"ס. בן אחי ר משה שלזינגר מוינה."},{"i":53780,"n":"שלזינגר, שמעון","f":"עקיבא יוסף"},{"i":53781,"n":"שלזינגר-יפה-מרגליות, יוסף מרגנ","f":"מרדכי-שאל לך אות","k":"בעל קונטרס מציצה","bt":"תריג","bp":"פעזינג","dt":"תרפא - יט אדר","dp":"קנעזיטש","b":"תלמיד הכת\"ס. נסמך מאת: ר אליעזר מנייטרא, ר שמחה בונם סופר מפרשבורג, ר מרדכי דנציג מועטש. רב במוגנדורף-תרמו. חתן ר מרדכי וייס מקנעזיטש. רב ברגנסדורף. חיבר \"שם ישראל\", \"קונרס ישוב ארץ ישראל - כנגד התנועה הציונית, ועוד. בניו: ר שמואל מאראנייש-מאראטה, ר יעקב. - שניהם חתניו של ר אברהם פרידמן מדרבניץ."},{"i":53782,"n":"שלזינגר-יפה-מרגליות, ישראל דוד","f":"מרדכי מסערעד","k":"בעל חזון למועד","r":"דיין בק\"ק סעמינטץ ואח\"כ בפעזינג","bt":"תקסב","dt":"תרכד - כד ניסן","dp":"פעזינג","b":"תלמיד החת\"ס, ור צבי הרש דייטש מנאמעסטא. חתן ר ישעיה הלוי קופמן מסעמניץ. רב בסעמניץ(=סמניץ)-תקפד, פעזינג-תקצב, חתנו - ר בנימין שכטר על מקומו אחריו.","bk":[["מחולת המחנים [שו\"ת]",""],["הר תבור - בימה באמצע בית הכנסת",""],["חזון למועד - קידוש החודש",""],["יפח לקץ - על התורה ובעל המאור על חולין",""],["מחולת המחנים - הבדל בין בתי כנסת חדשים לבתי כנסת ישנים",""]]},{"i":53783,"n":"שלזינגר-יפה-מרגליות, מרדכי","f":"ישראל דוד מפעזינג","k":"בעל מילי דאבות","bp":"פאזינג","dt":"תרטז","dp":"בודפשט","b":"תלמיד הכת\"ס, ור יהודה אסאד. חתן ר שמואל צילץ מיאקא. רב בפעזינג-תריג, קירכברג, בודפשט-תרלה."},{"i":53784,"n":"שלזינגר-יפה-מרגליות, שמואל","f":"משה ליב יוסף מרוגנדו","k":"בעל בית שמואל","bt":"תרמא","dt":"תרצח - ג חשון","b":"נכד ר מרדכי מרגליות בעל \"שאל לך אות\". תלמיד השב\"ס, ור דוד פרידמן מצעהלים. חתן ר אברהם פרידמן (איש שלום) מדרזניץ. רב בארניאש-מארוטה(=אראניאש-מאראט)-תרסז וחתנו ר מרדכי אריה הברפלד על מקומו אחריו. הו\"ל ספר זקניו מהר\"ש צילטץ ו\"מילי דאבות\". חתנו - ר חיים יעקב משה קרויס מרוגנדורף. נסמך מאת: זקנו, ר קופל רייך מבודפשט."},{"i":53785,"n":"שלזינגר-קיצע, גרשון מטימשואר","f":"חיים קיצע מאירשא","bt":"תקסא","dt":"תרט - יב חשון","b":"תלמיד החת\"ס. רב בטיסא-אוגאר. רב בטימישואר - לאחר שנשא את בתו של רב קהל הספרדים שם."},{"i":53786,"n":"שלזינגר-קיצע, מאיר מסארוואש","f":"חיים קיצע מאירשא","bt":"תקעח","bp":"[אירשא]","dt":"תרסג - כב אדר","dp":"סארוואש","b":"תלמיד החת\"ס, ור יחזקאל בנט מנייטרא, ור משה דוד אשכנזי מטאלטשווא. רב בסארוואש - ויסד בה את הקהלה החרדית. מראשי הלוחמים להעמיד הדת בעת פילוג הקהלות בהונגריה."},{"i":53787,"n":"שלחיה הכהן מקושטא","f":"דוד","b":"רב בקושטא-ש' בזמן מהר\"ם פאדובה. הסכים על \"ברכת אברהם\"-שיב."},{"i":53788,"n":"שלחני, מנחם מאיטליה","f":"ישמעאל","b":"רב באנקונה. קרובו ואולי חתנו של ר נתנאל טרבוט. הסכים על פסק של ר יהודה עשהאל מן הטוב. יורשיו מכרו ספר שלו לאספן אברהם גרציאנו. תשובה ממנו-תיד - בכת\"י, ועוד תשובה ב\"עפר יעקב\"-כת\"י - בענין ספר תורה."},{"i":53789,"n":"שלטון, בנימין","k":"בעל חושב מחשבות","b":"מרבני איזמיר, חיבר \"חושב מחשבות\""},{"i":53790,"n":"שלטון, משה מברוסה","b":"רב בברוסה-תקף. שאלה ממנו לר אליעזר די טולידו המזכירו בספרו \"משנת רבי אליעזר\"."},{"i":53791,"n":"שלטון, משה מקושטא","f":"יעקב","k":"בעל בני משה","bt":"שעה","bp":"קושטא","dt":"תמה","b":"נכד ר אליהו ן חיים (=מהראנ\"ח). תלמיד ר דוד אגוזי. רב בגליפולי-תיט, קושטא-תמז, ועסק גם בהתרת עגונות. רב בארטא-תל. דיין-תכה עם ר שמואל רוזניס ור אהרן אלימלך. גידל בביתו את בן אחיו שנפטר - ונקרא גם הוא ר משה שלטון וסייע לדודו בהדפסת ספרו."},{"i":53792,"n":"שלטון, משה מקושטא - הנכד","b":"בן אחיו של ר משה שלטון בעל \"בני משה\", ולאחר שנתייתם גדל אצלו. סייע לדודו בהדפסת ספרו."},{"i":53793,"n":"שלי, חויתא","k":"בעל מעשה חושב","dt":"תשיג - כז אב","b":"מחכמי ג'רבא,סופר סת\"ם,עסק בהעתקת כתבי יד של רבני תונס,חיבר \"מעשה חושב\" חידושי תורה ותהילים","bk":[["מעשה חושב",""]]},{"i":53794,"n":"שלי, עמנואל מג'רבה","b":"מחכמי ג'רבא, זקנו של ר שאול מקיקץ השלי. עבר לסוסה-תונס. חיבר שיטות על הש\"ס בכת\"י וקצתו נדפס ע\"י נכדיו בירחון \"קרן דוד\" ג'רבא תרעה."},{"i":53795,"n":"שליט - מרכוס, רחל","bp":"אישגנטי-ליטא","b":"למדה ציור במינכן, פאריס ולונדון. התפרסמה בציור יהודים מולינא ופולין."},{"i":53796,"n":"שליט, דוד מהרובשוב","b":"רב בהרובאשוב"},{"i":53797,"n":"שליט, הלל מהרובשוב","f":"דוד שליט","b":"מו\"צ בהרובשוב-תר על מקום אביו. נזכר בביאור מהר\"ם שיף. נכדו - ר הלל שעק מבערימליא."},{"i":53798,"n":"שליט, מרדכי מברלין","f":"חיים","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":53799,"n":"שליט, מרדכי מקובנא","k":"מוטל לאצקעווער","bp":"ראסיין","b":"מו\"צ בפרבר הר הירוק בקובנא-תרס. חתנו - ר נחום גרשון ברלין מהורדניא."},{"i":53800,"n":"שליט, משה","f":"ישעיה","k":"בעל ברית מטה משה","b":"חיבר \"ברית מטה משה\" על ההגדה."},{"i":53801,"n":"שליט, משה מליטא","bt":"1885","bp":"וילנא","dt":"1941","dp":"בעל די בילו'צעס","b":"חבר ב\"פועלי ציון\", נאסר וברח לחו\"ל. פרסם בכתבי עת בעברית ואידיש, עורך \"פלק אונד לאנד\" וילנא 1910, חיבר \"ליטערארישע עטיודן\" ובו ביקורת על פרץ, מנדלי, ברגלסון ועוד. חיסד את ביה\"ס הראשון באידיש בוילנא, מראשי \"אזע\", \"אורט\" \"יעאס\" - חברת ההגירה היהודית, ועוד. עורך רבעון \"פון נאענטן עבר\" לחקר חיי ישראל ותרבותו. נפסה בשואה."},{"i":53802,"n":"שליט, נחמיה מסאסוב","bt":"תקכ","bp":"למברג","dt":"תרי - ג כסלו","b":"תלמיד ר משולם איגרא, ור משה בעל \"אור פני משה\" מפשוורסק. רב בסאסוב אצל קרובו האדמור (היה קרוב מצד אשתו לאדמור ר משה יהודה). מילא את מקום המהרש\"ק בברודי (ע\"פ בקשתו של המהרש\"ק). תלמידו ר שלמה שפירא ממונקטש - המספר על רבו בספרו \"בית שלמה\" ושקרא לנכדו על שם רבו - נחמיה."},{"i":53803,"n":"שליטא, אליעזר ליפא זיידל","f":"בן ציון מזבורוב","bt":"תרנז","dt":"תשא","b":"חתן רא\"י הורביץ מפרוביזנא. רב ביזירנה עד השואה. נספה בשואה."},{"i":53804,"n":"שליטא, אשר מזאלוזיץ","f":"שלמה יעקב מואלדימרץ","b":"רב בזאלאזיץ-גליציה-תרך."},{"i":53805,"n":"שליטא, בן ציון מזבורוב","f":"יואל מטרנופול","bt":"תרכא","bp":"טרנופול","dt":"תשא או תשג","b":"רב בזבורוב-תרן. חתנו - ר משה קליינהנדלר. נספה בשואה."},{"i":53806,"n":"שליטא, בנימין","k":"בעל שליחות אליהו","b":"רב בניקלסבורג-תק\"ל"},{"i":53807,"n":"שליטא, יהודה ליב מואלדימרץ","b":"רב בוולאדימירץ(=ואלדימרץ). אחיו של ר יוסף-אב\"ד פינסק."},{"i":53808,"n":"שליטא, יואל מטרנופול","dt":"תרסד","b":"מחכמי טרנופול. תלמיד דודו ר יעקב שליטא מטרנופול."},{"i":53809,"n":"שליטא, יעקב מטרנופול","bt":"תקנט","dt":"תרכג","b":"רב בטרנופול. תלמיד ר יהושע באבד בעל \"ספר יהושע\". נפטר ללא ילדים."},{"i":53810,"n":"שליטא, יעקב מטרנופול","f":"בן ציון מזברוב","bt":"תרנו","bp":"זבורוב","dt":"תשב","b":"חתן ר יהושע השל באבד מטרנופול, ורב בטרנופול-תרעט על מקומו אחריו (והיתה מחלוקת בינו ובין גיסו - ר דוד מנחם באבד בעל \"החבצלת\"). (במכתב לר משולם ראטה כותב כנגד חסידי בלז בענין ארגון אסיפת רבנים). נספה בשואה."},{"i":53811,"n":"שליטא, יצחק אליהו מואלדימרץ","f":"אשר מזאלאזיץ","bt":"תריא","b":"רב בפוהאסט זרעצנא-פלך מינסק, וואלדימרץ-וואהלין-תרם על מקום זקנו."},{"i":53812,"n":"שליטא, משה מולידמרץ","f":"שלמה יעקב מולדימרץ","k":"בעל הנהגות ותקונים","bt":"תרע","dt":"תשמט","b":"תלמיד ר אהרן קוטלר בקלצק. ניצל מהשואה ואחריה לימד בישיבת שארית ישראל בברגן בלזן. עלה לארץ ועמד בראש מערכת \"אוצר הפוסקים\". חיבר \"הנהגות ותיקונים\" ירושלים תשכה, ועוד."},{"i":53813,"n":"שליטא, שלמה יעקב מואלדימרץ","f":"יהודה ליב מואלדימרץ","b":"רב בוולאדימרץ על מקום אביו, לעשנוב."},{"i":53814,"n":"שליטשטאנט, שמואל משטרסבורג","f":"אהרן","k":"בעל מרדכי קטן","b":"רב בשטרסבורג, בשנת קלו עלה לארץ ישראל ונשדד בדרכו ונאלץ לשוב למקומו. דן בדין מוסר שני יהודים ועקב כך היה נאלץ להסתתר. חיבר קיצור ספר המרדכי בשם - \"מרדכי הקטן\" בכתב יד."},{"i":53815,"n":"שלייפר, יוסף מסלונים","k":"בעל פורת יוסף","dt":"תרסג - ב אייר","dp":"סלונים","b":"תלמיד ישיבת וולוזין, וכונה \"העילוי מדינאבורג\". חתן ר יהושע איזיק שפירא - ר אייזל חריף מסלונים (עליו הסיפור הידוע כיצד בחר בו ר אייזל בוולוזין). רב בואקשינא-ליטא על מקום ר משה שפירא, דרעטשין(=דרצ'ין)-ליד סלונים, ואקשנה-תרלד, סלונים-תרמו על מקום חותנו (כ-12 שנה אחר פטירתו) ור מרדכי'לה אושמינער על מקומו אחריו. חיבר גם \"מרכבת יוסף\". בנו - ר מרדכי - רב מטעם בסלונים."},{"i":53816,"n":"שלייפר, יעקב מברוד","b":"מחכמי ברודי - תשובה אליו ב\"שערי בנימין\"."},{"i":53817,"n":"שלייפר, מרדכי מסלונים","f":"יוסף מסלונים","dt":"תש..","b":"תלמיד ישיבת סלובודקה, ביהמ\"ד לרבנים באודסה. רב מטעם בסלונים-תרעא, ציוני, בשנת תרפט בטלו הפולנים את משרת הרב מטעם והמשיך בתפקידו כעוזר האב\"ד והיה מראשי הקהלה מטעם הציונים. פרסם טור בעתון בשם \"לאהובי ורעי\". נספה בשואה."},{"i":53818,"n":"שלייפר, שלמה ממוסקבה","k":"בעל סדור השלום","dt":"תשיז - כח אד\"ב","b":"רב ראשי במוסקבה. עורך סדור השלום - מוסקבה תשטז."},{"i":53819,"n":"שליכטר (ישר), ברוך מקומרנא","f":"דוד מקומרנא","k":"בעל תורת חיים","bt":"תרנו","bp":"קומנרא","dt":"תשמט","b":"תלמיד ר משה רוזנבך מקומרנא. ממנהיגי המזרחי בעירו, עלה לארץ-תרצג, בשליחות בלונדון ובארה\"ב עבור ישיבת \"הישוב החדש\". רב בעכו-תשח. חיבר \"תורת חיים\" ירושלים תשה, ועוד."},{"i":53820,"n":"שליכטר, דוד מקומרנא","b":"חסיד שיניבה מחכמי קומרנא. תלמיד ר אליעזר צבי ספרין. גיסו ולימים חותנו של ר אברהם שלום הלברשטם. מתורתו בספרו של ר ישראל פרנקפורטר."},{"i":53821,"n":"שליכטר, שמואל חיים מקומרנא","f":"דוד מקומרנא","bt":"תרנג","bp":"קומרנא","dt":"תשב - ג חשון","b":"חתן ר ישכר דב שיקלר מזולקוא. רב בקומרנא ור\"מ בישיבת \"בני שלום\" שם. נספה בשואה."},{"i":53822,"n":"שליכר, דב מאנטורפן","b":"גביר באנטורפן. חתן נכדת ר דודו הכהן מרדומישל - הניחה קרן לכולל טשבין בבני ברק."},{"i":53823,"n":"שלימר, אברהם מארה\"ב","b":"גביר נדבן בניו יורק."},{"i":53824,"n":"שלין, אברהם יעקב מודוביצה","b":"מחכמי ודוביצה - ממשתתפי \"תלפיות\" תרצח."},{"i":53825,"n":"שליסל, אברהם מקולבסוב","f":"יעקב","bt":"תרע","bp":"מיידן","dt":"תשסג","b":"ניצל מהשואה. עלה דרך איטליה והתגורר בכפר חבד ובני ברק. רב בשטיבל אלכסנדר."},{"i":53826,"n":"שליסל, דוד ממונקטש","f":"משה יהודה מצאנז","k":"בעל אמרי דוד","bt":"תרכד או תרכו","dt":"תש - כד אד\"ב","b":"הדברי חיים היה המוהל בבריתו. חתן הגביר ר דוד יהודה ליב טרטנר מזבורוב. רב בזבורוב, מונקטש-תרפב עם הדיינים ר משה שפיצר ור מאיר זאב זלצר, ועמד בראש ישיבה שם, השכין שלום בין חסידי בלז ומונקטש. חיבר \"אמרי דוד\" וויצען תרסח, \"בית דוד\" ועוד. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח. עורך \"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב.","bk":[["אמרי דוד וכתר מצות",""],["בית דוד",""],["גן דוד",""]]},{"i":53827,"n":"שליסל, חיים יחזקאל","f":"דוד ממונקטש","bt":"תרס","b":"רב במונקטש לצד אביו. חתן ר מאיר הלוי. ניצל מהשואה והיגר לארה\"ב. הוציא לאור \"בני דוד הנאמנים\" ובו דרשות הבר מצוה של ילדיו (שאחד מהם נקרא עקיבא איגר) ועוד - מונקטש תשא."},{"i":53828,"n":"שליסל, יהודה ליב מדזיקוב","k":"ליביש חנה'ס","b":"נכד הקדוש ר יוסקי מדזיקוב שנהרג על קידוש השם. רב בדזיקוב עם אחיו ר אלכסנדר אצל ר אליעזר מדזיקוב."},{"i":53829,"n":"שליסל, יצחק בצלאל מדזיקוב","b":"מחכמי דזיקוב. חותנו של ר זאב אביגדור פינק מטרנוב."},{"i":53830,"n":"שליסל, משה יהודה מטורנא","f":"נטע שלמה מטרנוב","dt":"תרעו","dp":"ירושלים","b":"חתן ר משה ארברמן מצאנז. עבר לטורנא ולרצפרט, עלה לירושלים-תרסה עם בנו ר נטע שלמה. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":53831,"n":"שליסל, נטע שלמה - הנכד","f":"משה יהודה מטורנא","b":"עלה לירושלים-תרסה עם אביו. אחיו ר דוד השיב לו בסוף \"בית דוד\"."},{"i":53832,"n":"שליסל, נטע שלמה מטורנא - הזקן","f":"יהודה ליב","b":"נכד ר עקיבא איגר הראשון מפרשבורג בעל \"משנת דרבי עקיבא\". רב בטורנא-תרל. בנו ר משה יהודה עלה לירושלים."},{"i":53833,"n":"שליסל, נטע שלמה ממונקטש","f":"דוד מזבורוב","k":"בעל נטע שעשועים","bt":"תרסד","bp":"זבורוב","dt":"תשד - ג סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור חיים אלעזר שפירא ממונקטש ור\"מ בישיבתו. חתן ר יחזקאל מילר מקרעניצע, ועבר לשם-תרפו. רב במונקטש-תרץ לצד אביו ועל מקומו-תש, (או זבורוב-תש על מקום אביו). נספה בשואה. חיבר \"שלחן נגד צוררי\", \"דרך נשר\", ועוד. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אחיאסף\" - סטריזוב תרפט, \"אסיפת חכמים\" - מלניץ תרפח, \"בית ועד לחכמים\" - סטמר תרפב, \"הכוכב\" - מונקטש-נ\"י תרצה, \"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב, \"הפרדס\" - צאנז תרצא."},{"i":53834,"n":"שליסלבורג, פרץ מפרשבורג","b":"מגדולי חכמי פרשבורג-תצה. תשובה אליו ב\"פנים מאירות\"."},{"i":53835,"n":"שליפירז, יוסף","f":"מנחם מנדל","k":"בעל צפנת פענח","bp":"הרודישץ-פלך מינסק","dt":"תרטו - טו שבט","dp":"וילנא","b":"בקי בחשבון וחיבר לוחות לחישוב והתחבר אל ר יצחק אליהו גורלנד שלקח את ההמצאה על שמו והתעשר ממנה."},{"i":53836,"n":"שליש, אליה מטיווה","b":"רב בטיווה(=תבץ)-שנות ה-ש'."},{"i":53837,"n":"שליש, ידידיה ממצרים","b":"מגדולי רבני מצרים-רפ\"ז"},{"i":53838,"n":"שלם הכהן ממראקש - א","f":"חנניה","b":"רב במראקש, חתם-תרמא עם חכמי דורו (ובהם ר שלם הכהן - השני), חתם-תרט עם ר דוד צבאח, ר אלעזר חזאן ועוד."},{"i":53839,"n":"שלם הכהן ממראקש - ב","b":"מחכמי מראקש, חתם-תרמא עם חכמי דורו ובהם ר שלם בן חנניה הכהן - הראשון."},{"i":53840,"n":"שלם, אברהם ד'","b":"תלמיד ישיבת \"שערי ציון\" בירושלים. פרסם מאמרים ב\"בכורי ציון\" - ירושלים תשד."},{"i":53841,"n":"שלם, אברהם ממרוקו","b":"מקובל מחכמי דרעא-מרוקו-ש'."},{"i":53842,"n":"שלם, אברהם משלוניקי","f":"דוד הרופא משלוניקי","b":"רופא בשלוניקי-שד."},{"i":53843,"n":"שלם, אברהם משלוניקי","b":"מצאצאי הפוסק ר אשר שלם. פעיל מהפכני נגד השולטן והוגלה עם אחיו לטריפולי-לוב."},{"i":53844,"n":"שלם, אברהם משלוניקי","dt":"שפד - כה תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53845,"n":"שלם, אשר משלוניקי","f":"עמנואל","k":"בעל מטה אשר","bt":"תמד","b":"מחכמי טורקיה, רב בשלוניקי, חיבר \"מטה אשר\""},{"i":53846,"n":"שלם, אשר משלוניקי","dt":"1948","dp":"פאריס","b":"מצאצאי הפוסק ר אשר שלם. פעיל מהפכני נגד השולטן והוגלה עם אחיו לטריפולי-לוב."},{"i":53847,"n":"שלם, דוד","b":"מחכמי מוצל"},{"i":53848,"n":"שלם, דוד משלוניקי","dt":"שז","b":"רופא בשלוניקי, ובנו ר אברהם רופא גם הוא."},{"i":53849,"n":"שלם, חזקיה משלוניקי","dt":"תקלג","dp":"שלוניקי","b":"גביר בשלוניקי. נהרג בידי שודדים בשלוניקי-תקלג."},{"i":53850,"n":"שלם, חייא מצפת","b":"דיין בצפת-תלב אצל ר גבריאל איספירנסה, ואתו הדיינים ר שמואל עדילה, ר שלמה הלוי, ר שלמה אלימאן."},{"i":53851,"n":"שלם, יהודה משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":53852,"n":"שלם, יוסף עמנואל משלוניקי","dt":"תרכג-ה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53853,"n":"שלם, יוסף שמואל משלוניקי","b":"מחכמי שלוניקי-תרע, עלה לירושלים."},{"i":53854,"n":"שלם, יחיאל מבלגרד","f":"שלמה מסופיה ואמשטרדם"},{"i":53855,"n":"שלם, יעקב משלוניקי","k":"בעל רוח יעקב","b":"מחכמי שלוניקי. חיבר הקדמה ל\"שלמי צבור\"-תקן לר אברהם חיון. חיבר \"רוח יעקב\" ונדפס בסוף \"לב שמח\" - שלוניקי תקכד."},{"i":53856,"n":"שלם, יצחק משלוניקי","f":"עמנואל","dt":"תפד-ט","dp":"שלוניקי","b":"גביר בשלוניקי (כאביו לפניו), ותרם לתלמוד תורה. הו\"ל חדושי שבועות לרשב\"א."},{"i":53857,"n":"שלם, משה מירושלים","dt":"תקסג - יג סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":53858,"n":"שלם, משה משלוניקי","f":"עמנואל","k":"בעל טובה תוכחה","b":"רב בשלוניקי-תר. חיבר ספר מוסר בלאדינו בשם \"טובה תוכחה\"-תרו."},{"i":53859,"n":"שלם, עמנואל משלוניקי","dt":"תקא - לפני","dp":"שלוניקי","b":"גביר בשלוניקי. סייע לבניו - ר אשר ור שמואל, להקים ישיבות בשלוניקי עם ספרים יקרי ערך."},{"i":53860,"n":"שלם, עמנואל משלוניקי - ב","dt":"תקכח","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":53861,"n":"שלם, עמנואל רפאל משלוניקי","dt":"תש","dp":"פאריס","b":"מצאצאי הפוסק ר עמנואל שלם. עו\"ד בשלוניקי ומתומכי ה\"תורכים הצעירים\", היה שומר תורה, פעל כמתווך במחלוקת בין השלטון התורכי לותיקאן, ועוד. חיבר מחקרים משפטיים, עבר לפאריס-1920."},{"i":53862,"n":"שלם, רפאל יהודה משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה."},{"i":53863,"n":"שלם, רפאל יצחק מירושלים","dt":"תקף - כ תשרי","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":53864,"n":"שלם, רפואה ממצרים","bp":"צפת?","b":"רב באלכסנדריה-מצרים-תס, בזמן ה\"גינת ורדים\", והיה מגדולי הפוסקים שם. החיד\"א החזיק תשובה ממנו בכת\"י."},{"i":53865,"n":"שלם, שלום מאמשטרדם","b":"רב באמשטרדם-תק\"כ"},{"i":53866,"n":"שלם, שלמה הכהן מאמשטרדם","f":"יחיאל","k":"בעל לב שלם","bt":"תסה","bp":"אדרינופול","dt":"תקמא - יז אלול","dp":"אמשטרדם","b":"לאחר שנתייתם גדל אצל זקנו ר יוסף בן אהרן צלמונה בסופיה. תלמיד ר אליעזר נחום, ור רפאל יעקב אברהם גירון. רב הכולל בסופיה, יצא לאמשטרדם ונתעכב בדרכו בוינה, ופפד\"א, רב בבלגרד ור ישכר אבולעפיה מטבריה על מקומו אחריו, אמשטרדם על מקום ר יצחק בן דנא די בריטו וראש ישיבת \"עץ חיים\" שם. מתלמידיו ר ראובן בן יעקב משלוניקי שחיבר הקדמה לספר רבו. חיבר גם \"לב שלם\", \"שונה הלכות\", \"נחמד למראה\". בנו - ר יחיאל, חתנו - דוד בן רפאל רוסו.","bk":[["שונה הלכות [על בה\"ג]",""],["לב שלם",""]]},{"i":53867,"n":"שלם, שמואל בכור עמנואל משלוניק","b":"גביר בשלוניקי. נדב ספר תורה לישיבת ג'יליבי אליהו כהן-תריט"},{"i":53868,"n":"שלם, שמואל מאזמיר","dt":"תע","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":53869,"n":"שלם, שמואל מספרד","b":"רב בספרד, בזמן הריב\"ש, ונזכר בשות הריב\"ש ע\"י חתן הריב\"ש ר יצחק בונפוש בן שאלתיאל."},{"i":53870,"n":"שלם, שמואל משלוניקי","f":"עמנואל","k":"בעל מלך שלם","dt":"תקך-תקכו-תקע","dp":"אזמיר - ליד","b":"מחכמי שלוניקי, תלמידו של ר אברהם גטניו, עבר לפלונין - בגלל רדיפת השלטונות שתבעו מס גם מתלמידי חכמים, עלה לטבריה בעקבות רבו. בשליחות קהילת טבריה-תקיח בתורכיה ואירופה, ופעל לשכנע לתרום לא רק לירושלים אלא גם לטבריה.נפטר בדרכו חזרה ליד אזמיר. חיבר \"מלך שלם\" ו\"פתח השער\" שלוניקי תקכט. בנו ר יצחק."},{"i":53871,"n":"שלמה","f":"אברהם אבלי"},{"i":53872,"n":"שלמה","f":"יחיאל מיכל אפטא","b":"רב-שנת ת\"ק"},{"i":53873,"n":"שלמה","f":"עובדיה הדיין"},{"i":53874,"n":"שלמה","f":"עקיבא מרגליות מבוריס","b":"רב-שנת תקנ. חתנו - ר עקיבא אלטשול מסלוצק."},{"i":53875,"n":"שלמה","f":"אהרן אריה מפרעמישלן","b":"רב-שנת תק\"צ"},{"i":53876,"n":"שלמה","f":"מרדכי נסים","k":"בעל מכתב שלמה","b":"חיבר \"מכתב לשלמה\" שלוניקי תרטו, \"חשק שלמה\" קושטא תקכח."},{"i":53877,"n":"שלמה","f":"אליהו נסים","k":"בעל אדרת אליהו","bt":"תקמא","dt":"תרכב","b":"רב באיטליה."},{"i":53878,"n":"שלמה (טולדנו)","f":"יצחק","dt":"תנג"},{"i":53879,"n":"שלמה (רובין) מדולינא","dt":"תרלא","b":"תלמיד ה\"עטרת צבי\" ומהרי\"א מזידיטשוב. סופר סתם חשוב. בנו ר אליעזר המכונה \"הגדול\"."},{"i":53880,"n":"שלמה אביגדור","f":"אברהם","k":"בעל ספר המהלכות תורה","b":"חיבר ספר המהלכות תורה - בכת\"י ותרגם ספר הגלגל."},{"i":53881,"n":"שלמה אברהם מאזמיר","dt":"תיט - כז אלול","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":53882,"n":"שלמה אהרן הכהן מליפאנטו","b":"מחכמי ליפאנטו - בדור שלאחר הגירוש."},{"i":53883,"n":"שלמה אהרן זליג מיאלובקא וקאדני","f":"יואל מקמניץ","b":"נכד ר יוסף בן חיים מקמניץ."},{"i":53884,"n":"שלמה אליקים מאלכסנדריה","b":"מרבני נא אמון-תר\"י"},{"i":53885,"n":"שלמה אפנדי משלוניקי","f":"משה נחום","b":"רופא צבאי בשלוניקי-תרס."},{"i":53886,"n":"שלמה אריה ליב מטוטשין","f":"זאב וינשלבום","k":"בעל ברכת שלמה","bt":"תרט","dt":"תרפז - י תמוז","b":"גדול בנגלה ונסתר בטוטשין"},{"i":53887,"n":"שלמה אשכנזי מוורמייזא","k":"בעל מכלל יופי","b":"חיבר \"מכלל יופי\" - אמשטרדם, חיבור על הזוהר - בכת\"י - (היה בספרית ר דוד אופנהים)."},{"i":53888,"n":"שלמה אשר זלמן מבערשט","b":"רב בבערעשט"},{"i":53889,"n":"שלמה אשר זלמן מפטשניזין","f":"אברהם בנימין","b":"רב בפטשניזין, טויסט-תריז, קרליפקה-תרכג."},{"i":53890,"n":"שלמה בן דור","bt":"תשכג בערך","bk":[["אל הנער הזה התפללתי - סיפור אמונה לידת ילד תסמונת דאון",""]]},{"i":53891,"n":"שלמה בן היתום מאיטליה","k":"בעל פירוש לתלמוד","b":"מגדולי הראשונים ברבני איטליה-ד'תת\"נ"},{"i":53892,"n":"שלמה בן יצחק (רש\"י)","bt":"1040","dt":"ד'תתסה 1105","bk":[["איסור והיתר לרש\"י",""],["הסדרים לרש\"י",""],["כת''י רש''י",""],["כת''י רש''י ושאר ראשונים עה''ת הפטרות ונ''ך",""],["לקוטי הפרדס",""],["סדור רש\"י",""],["סדור רש״י",""],["ספר האורה",""],["ספר הפרדס",""],["ספר הפרדס לרש\"י",""],["עמוד די רש\"י ז\"ל",""],["פיוטי רשי (רש\"י)",""],["פירוש רש\"י",""],["פירוש רש״י",""],["פרוש המקרא לרש\"י",""],["פרוש רש\"י",""],["פרשנדתא",""],["רש\"י",""]]},{"i":53893,"n":"שלמה בן יצחק הלוי הזקן","bt":"1532","dt":"ה'שס 1600","bk":[["דברי שלמה",""],["חשק שלמה",""],["לב אבות",""],["לחם שלמה",""]]},{"i":53894,"n":"שלמה ברוך מארטא ושלוניקי","b":"מחכמי שלוניקי, דיין בארטא-יוון - שנות ה-ש' על מקום ר שבתי ברוך (כנראה אחיו), אצל ר שמואל קלעי."},{"i":53895,"n":"שלמה ברוך מקושטא","b":"דיין בקושטא אצל ר שמואל קלעי בעל \"משפטי שמואל\". תשובה ממנו בענין ירושה, והסכימו עמו חכמי דורו המהרשד\"ם, ר מרדכי מטאלון, ר שמואל טאיטצאק ועוד."},{"i":53896,"n":"שלמה ברוך משלוניקי","b":"מרבני שאלוניקי,עלה לירושלים-תי\"ד"},{"i":53897,"n":"שלמה ברוכיה משלוניקי","dt":"תסג","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":53898,"n":"שלמה גאון ארץ ישראל","f":"יהודה","bp":"[פאס-מרוקו]","dt":"ד'תתיא-1051","b":"גאון ארץ ישראל (1025), ראש הישיבה בירושלים וראש הישוב בארץ ישראל, בתקופה של גזירות קשות, מרד ערבי, רעידת אדמה, ומריבות פנימיות - פעל להשגת שלום עם הקראים, וכן הפעיל את קשריו את השלטונות לטובת אחיו. עמד בקשרים הדוקים עם יהודי מצרים ובראשם ר אפרים בן שמריה - ראה הקהלה בפוסטאט, ור סהלאן בן אברהם, וביקש עת עזרתם ליהודי ארץ ישראל. מחלוקת כנגדו מצד אחיינו ר נתן בן אברהם תלמיד ר חושיאל בקירואן, שמינה עצמו בתמיכת רבנים במצרים לגאון לצד דודו ושלא ברשות דודו. בנו ר אברהם שסייע לאביו בהנהלת הישיבה, ור יחייא שנשלח על ידי אביו ללמוד אצל רב האי גאון בפומפודיתא."},{"i":53899,"n":"שלמה גאון בגדד","f":"שמואל","b":"ראש ישיבת \"גאון יעקב\" בבגדד בזמן ר שמואל בן עלי הגאון בבבל. חיבר קינה על פטירת בנו רב שמואל גאון-ד'תתקיא, שהיה אמור לשבת על מקומו אחריו. לדעת אסף היה גאון על מקום רב עלי הלוי, ואחריו ר שמואל בן עלי. מכתב ממנו לקהלה-תסג שרב בשם ר אהרן בן מריות נהג רבנות שלא כדין והקים בי\"ד ללא רשות, והוציא לו ר שלמה, יחד עם רב דניאל גאון, כתב נידוי, עד שחזר בו אותו הרב והתירו את נידויו."},{"i":53900,"n":"שלמה דב בעריש אברהם מגלוגא","f":"צבי הירש מהלברשטט","dt":"תקכז-לו- ג תמוז","dp":"גלוגא","b":"אב\"ד גלוגא. חתן ר יעקב יהושע פאלק בעל \"פני יהושע\". תשובותיו ב\"צלעות הבית\" לר מאיר פוזנר. הסכים על \"תוספות שבת\"-תקכז, \"הארוך מש\"ך\" לקרובו ר אהרן בן משה מגזע צבי - רבה של ברלין. מחותן עם ר ישראל ליפשיץ המביא תשובה ממנו בספרו - \"אור ישראל\". בנו ר אהרן יהושע אליה אב\"ד קניגסברג וראויטש."},{"i":53901,"n":"שלמה דוד מוולוצלאווק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":53902,"n":"שלמה דמריצל(=ממרסלה-סיציליה)","f":"חיים","dt":"רץ - כב טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53903,"n":"שלמה דרשן שפירא מלובלין","b":"מחכמי לובלין. הסכים על \"אור ישראל\" לר ישראל בן אהרן משקלוב-תסא."},{"i":53904,"n":"שלמה הבבלי מרומי ומלותיר","k":"רבינו שלמה הבבלי","b":"מגדולי הקדמונים,מגאוני לותיר,פייטן מופלא ברומי-ד'תשס\"ה"},{"i":53905,"n":"שלמה הכהן - מהרש\"ך","f":"אברהם","k":"בעל שו\"ת מהרש\"ך","bt":"רפ או רצה","bp":"שירון או שלוניקי","dt":"שסא - בערך","dp":"שלוניקי","b":"תלמיד ר אברהם הכהן משלוניקי, ור יוסף פורמון. רב במונסטיר, קהילת קסטיליה בשלוניקי, חברם של המהריב\"ל ומהרשד\"ם, ויחד נחשבו לגדולי הפוסקים בדורם. בניו ר אלעזר, ר חיים, ר אברהם משלוניקי (חיבר שו\"ת), ור מתתיה.","bk":[["שו\"ת מהרש\"ך",""]]},{"i":53906,"n":"שלמה הכהן גאון ארץ ישראל","f":"יוסף","b":"גאון ישיבת ארץ ישראל (1020) על מקום ר יאשיה בן אהרן, ר שלמה בן יהודה גאון על מקומו אחריו. מכתב ממנו בענין גט בפוסטאט."},{"i":53907,"n":"שלמה הכהן חריף מפושטשאמקא","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":53908,"n":"שלמה הכהן מבגדד","k":"בעל תפארת שלמה","b":"רב בבגדד."},{"i":53909,"n":"שלמה הכהן מדברו-מרוקו","f":"יוסף","k":"בעל ויאסוף שלמה","r":"האדמ\"ר מגור","dt":"תשט - ה שבט","b":"דיין בדברו(=דבדו)-מרוקו, וראש ישיבת הכהנים שם, רב במאזאגאן-מרוקו, אוג'דא-מרוקו.","bk":[["לך שלמה",""]]},{"i":53910,"n":"שלמה הכהן מדברו-מרוקו - א","f":"אברהם","k":"ארבי לקביר","bt":"תקס","bp":"דברו-מרוקו","dt":"תרמא - חשון","dp":"דברו-מרוקו","b":"דיין ורב בישיבת אביו בדברו-מרוקו. חיבר פירוש על הרא\"ם - בכת\"י. מתלמידיו הרד\"ך. נפטר ללא ילדים."},{"i":53911,"n":"שלמה הכהן מהלברשטט","f":"אברהם יצחק","k":"בעל כה לחי","bt":"תקץ","bp":"זבורוב","dt":"תרסז","b":"תלמיד החסד לאברהם. חתן ר יעקב עטלינגר. חבר בקלויז של ר ישכר ברמן מהלברשטט ולימד שם. רב במגיסטריכט, שווערין, אפעלן-תרם, ברלין-תרן. חיבר \"כה לחי\" ברלין תרנח. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":53912,"n":"שלמה הכהן מוילנא","f":"ישראל משה הכהן","k":"בעל בנין שלמה","r":"מו\"ץ בוילנא","bt":"תקפח-צא","bp":"וילנא","dt":"תרסו - כט כסלו","dp":"וילנא","b":"מגדולי הפוסקים בדורו, מו\"ץ באנטאקליא, ראש המו\"צים בווילנה-תרכה כ-50 שנה. חיבר 37 ספרים, וביניהם גם \"עצי ברושים\". נחשב לאחד מצדיקי דורו. פרסם מאמרים ב\"עיטור סופרים\" - וילנא תרמח, \"שערי תורה\" - וארשא תרסג.","bk":[["חשק שלמה [עהש\"ס]",""],["עצי ברושים",""],["בנין שלמה",""],["בנין שלמה (החדש) - שו\"ת",""],["חי' מהרש\"ך – משניות וש\"ס",""],["עצי אלמוגים – חו\"מ",""],["עצי ברושים – שו\"ת",""],["בנין שלמה (שו\"ת)",""]],"e":"תקפ\"ח~-תרס\"ו"},{"i":53913,"n":"שלמה הכהן מזגירז","b":"רב בזגירז-תר\"ע"},{"i":53914,"n":"שלמה הכהן מיערגין","b":"רב ביערגין-תקע\"ו"},{"i":53915,"n":"שלמה הכהן מלאריסה","f":"אהרן","b":"רב בלאריסה-שנות ה-ש'."},{"i":53916,"n":"שלמה הכהן מליסא","k":"בעל אבי עזר","b":"מגדולי חכמי ליסא-תק\"מ"},{"i":53917,"n":"שלמה הכהן מליפאנטו-יוון","f":"שבתי","b":"מחכמי ליפאנטו-יוון - שנות ה-ש'."},{"i":53918,"n":"שלמה הכהן ממכנאס","f":"חיים","dt":"תקכא - אחרי","b":"מחכמי מכנאס-תפז. אולי הוא שחתם בפאס-תקה עם ר אברהם חלאוה ור שלמה עטייה."},{"i":53919,"n":"שלמה הכהן ממנטובה","f":"מנחם","b":"רב במנטובה, היה מעורב במחלוקת ר שמעון גינצבורג ור נתן שאטן-שכד."},{"i":53920,"n":"שלמה הכהן ממצרים","b":"מחכמי מצרים, תלמיד הרמבם ונזכר בתשובותיו."},{"i":53921,"n":"שלמה הכהן ממרוקו","f":"יצחק","dp":"ירושלים","b":"רב בתאוורירת-מרוקו, דיין באוג'דא ומאזאגאן-מרוקו. עלה לירושלים, בשליחות עדת המערבים."},{"i":53922,"n":"שלמה הכהן ממרוקו (סאלי?)","f":"י'","b":"מחכמי מרוקו-תפז, חיבר דרושים - בכת\"י."},{"i":53923,"n":"שלמה הכהן מסאלי-מרוקו","f":"מרדכי מסאלי","b":"רב בסאלי-מרוקו-תפו, הסכים על \"חפץ השם\", ו\"כתר תורה\". חתם בשו\"ת בית יהודה עם ר אהרן צרפתי ור שמואל קארו. חיבר קינות בכת\"י."},{"i":53924,"n":"שלמה הכהן מפרג","k":"בעל גבריאל","bt":"1825","dt":"1904","dp":"פרג","b":"חיבר \"איין שפיעגעל דער גענענווארט\", ועוד."},{"i":53925,"n":"שלמה הכהן מפרס","bp":"גולפיגן-פרס","dt":"תרלד - ט אב","b":"רב בגולפיגן-פרס, טהראן-פרס, התכתב עם ה\"בן איש חי\". תלמידיו היו רבני קהלות בפרס, היה מקורב למלכות והמלך התיעץ עמו בענינים שונים. מקובל וכותב קמיעות וסגולות."},{"i":53926,"n":"שלמה הכהן מקומורג'ינה","f":"יוסף","b":"רב בקומורג'ינה(=גיומילג'ינה)-שנות ה-ת'."},{"i":53927,"n":"שלמה הכהן מקעסטהאלי","b":"רב בקעסטהעלי-תר\"כ-תר\"נ"},{"i":53928,"n":"שלמה הכהן משלוניקי","f":"אלעזר","dt":"תלג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":53929,"n":"שלמה הכהן משלוניקי וירושלים","f":"יהודה","k":"בעל מזל שעה","dt":"תקפז - ח תמוז","dp":"ירושלים","b":"מקובל מחכמי ירושלים, בשנת תקעח בשליחות בתורכיה, בהיותו בעיר לארסו-יוון עזר בפסק דין ומובא ב\"חקרי לב\". חיבר גם \"הוראת שעה\", \"שעת הכושר\", \"שעת רצון\", \"שעות דרבנן\". בנו ר יהודה בעל \"אהל יהודה\" ו\"אשמורת הבקר\"."},{"i":53930,"n":"שלמה הכהן משנייטוך וצילץ","f":"משלם זלמן מפיורדא","dt":"תקפד - ג ניסן","b":"רב בשנייטוך, רגגנהטיים, צילץ-תקלא?."},{"i":53931,"n":"שלמה הכהן משקוטצין","b":"אב\"ד שקוטצין-תרד, חתם כדיין עם ר דב בר מייזלש מקראקא. חתם נגד אסיפת הריפורמים בברונשויג - ב\"תורת הקנאות\"."},{"i":53932,"n":"שלמה הכהן מתימן","f":"דוד","k":"בעל לחם שלמה","bt":"[שי - שכ]","bp":"תימן","b":"מקובל מחכמי דאיאן-תימן, בן דורם של ר שלום קורח בעל ספר הסגולות, ור יוחנן מזרחי מפרש המשנה . תלמידו - ר יצחק בן אברהם ונה שהעתיק את ספרו. חיבר ספר קבלה בשם \"לחם שלמה\"-שצה, (ספר הקבלה השני שנכתב בתימן), והוא משלים את ספר הסגולות לר שלום קורח. הספר נכתב במימון הגביר ר אברהם בן שלמה אלאביץ'."},{"i":53933,"n":"שלמה הלוי הבחור משלוניקי","f":"יצחק בן שלמה בן יצחק","k":"בעל שו\"ת","bt":"שלג או שמא","dt":"שצד - יא תשרי","dp":"שלוניקי","b":"תלמיד ר אברהם די בוטון. רב וראש ישיבת \"עץ חיים\" בשלוניקי על מקום אביו-רצד. חברו של ר חיים שבתי משלוניקי. מתלמידיו: ר שמואל פלורנטין, ר יהודה ג'יראסי, ר יוסף צרפתי, ר אברהם שיראנו, ר משה ויצחק אלפנדרי, ר יוסף פאשאריאל, ור שלמה פרץ. תשובותיו בספרי חכמי דורו, חיבר שו\"ת ונדפסו-תיב."},{"i":53934,"n":"שלמה הלוי הזקן מקושטא","b":"מגדולי חכמי קושטא-ש\"י"},{"i":53935,"n":"שלמה הלוי הזקן משלוניקי - ג","f":"יצחק בן שלמה משלוניק","k":"בעל חשק שלמה","bt":"רצב","bp":"שלוניקי","dt":"שס - כז אב","dp":"שלוניקי","b":"בן למשפחה מפורטוגל שעברו לשלוניקי. תלמיד בישיבת ר יוסף ן לב בשלוניקי. מגיה בדפוס שלוניקי, רב באזמיר?, אישקופיה(=אוסקוב)-יוגוסלביה-שכח, רב קהילת איבורה-בשלוניקי-שלג על מקום ר אברהם סידיליו, תיקן תקנות רבות והשיב לקהלות שונות. חיבר גם \"לב אבות\", \"לחם שלמה\", \"פי אבות\", ועוד. חיבר גם שירים. בניו: ר יצחק, ר יוסף-חתן ר יוסף אחיו של ר שלמה, חתנו - ר אהרן ששון בעל \"תורת אמת\"."},{"i":53936,"n":"שלמה הלוי חריף מפולנאה ולבוב","f":"יצחק אברהם","dt":"שצח - כו חשון","dp":"לבוב","b":"תלמיד בעל הסמ\"ע. חתן ר יוסף כץ בעל \"שארית יוסף\". רב בפולנאה, לבוב. מחותן עם ר אברהם שרנצלש מלבוב בעל סדר גיטין (מחותנו השני של ר אברהם - ר יהושע בעל מגיני שלמה). הסכים-שצו על אור חדש עם בעל הב\"ח ור אליהו קלמנקש, חתם על החרם שלא להדפיס את מאירת עינים-סמ\"ע במשך 10 שנים. בניו - ר יצחק (10671)-חתן המהרש\"א, ר משה (14714). מצאצאיו ר יצחק מפרשבורג בעל \"שיח יצחק\"."},{"i":53937,"n":"שלמה הלוי מאזמיר","f":"משה","dt":"תקלו","dp":"אזמיר","b":"אחד מ-12 הממונים באזמיר."},{"i":53938,"n":"שלמה הלוי מאיטליה","f":"אליעזר","k":"בעל מורה צדק","b":"מחכמי איטליה-שה בזמן הרא\"ם."},{"i":53939,"n":"שלמה הלוי מוילנא","f":"יהודה","b":"דיין בוילנא, חתם-תי עם בעל הש\"ך, ר חיים בן משה, ר נפתלי הרץ בן מאיר רייך. הסכים על שערי שמים-תלה לנכדו ר יחיאל בן חתנו - ר אריה ליב סגל בן נפתלי הרץ מקאליש - אחיינו של המהרש\"א. בנו - ר אברהם שנזכר בספר שערי שמים. (ראה גם ר שלמה הלוי מינץ מוילנא ואה\"ו)."},{"i":53940,"n":"שלמה הלוי מירושלים","dt":"תר","b":"מגדולי ירושלים"},{"i":53941,"n":"שלמה הלוי מירושלים","f":"רפאל הלוי","b":"מחכמי ירושלים-תר\"ל"},{"i":53942,"n":"שלמה הלוי מירושלים","f":"בנימין הלוי אשכנזי","k":"בעל לב שמחה","bp":"קושטא","dt":"תנג-ז - יא אלול","dp":"אזמיר","b":"מצאצאי ר אברהם סידיליו. תלמיד ר הדריאל ן נחמיאש. גביר מחכמי קושטא. חתן ר יונתן גלנטי וגיסו של ר משה גלנטי. עלה לצפת - אחרי תכה והיה ממחדשי הישוב יחד עם חברו ר גבריאל אישפיראסנה, כיהן כמו\"צ בירושלים, בשליחות צפת בתורכיה, רב בצידון-תלד על מקום אביו, ור אברהם גלנטי על מקומו אחריו, ביירות-תלד. עבר לאזמיר-תלה וכיהן כרב בזמן ר ישראל בן חיים בנבנישתי עד לפטירתו. בשנת תמז חתם על תקנת המס. חיבר \"לב שמחה\" שלוניקי תקסח. החזיק בכתב היד שו\"ת הרא\"ם - שירש מזקנו. בנו ר בנימין הלוי שלחם בנחמיה חייא חיון והשבתאים. גיסו - ר משה ן חביב מירושלים."},{"i":53943,"n":"שלמה הלוי מירושלים","f":"חיים","b":"מחכמי ירושלים. בשליחות בברסלוי, חתם על המכתב לברסלוי-תעז."},{"i":53944,"n":"שלמה הלוי ממראקש","b":"מו\"ץ במראקש בזמן ר אברהם אזולאי."},{"i":53945,"n":"שלמה הלוי מסאלי","b":"מחכמי מתא סאלי-מרוקו."},{"i":53946,"n":"שלמה הלוי מספרד ושלוניקי - א","k":"מאיסטרו שלמה","dt":"רצח","dp":"שלוניקי","b":"רופא מחכמי שלוניקי. זקנו של ר שלמה הלוי הזקן. בניו: ר יצחק ור יעקב ואולי גם ר יוסף. נכדו - ר שלמה בעל \"דברי שלמה\" המזכירו בספרו."},{"i":53947,"n":"שלמה הלוי מסרייבו ווינה","b":"גביר מראשי קהלת סרייבו, עבר לוינה עם רבים מבני הקהלה-תקס בערך בזמן מרד הסרבים."},{"i":53948,"n":"שלמה הלוי מפאס","b":"סופר שטרות בפאס-תרנב."},{"i":53949,"n":"שלמה הלוי מפינאלי","b":"מחכמי איטליה. נזכר ב\"פחד יצחק\"."},{"i":53950,"n":"שלמה הלוי מפפד\"מ","f":"טודרוס","b":"מחכמי פפד\"מ-שכה, חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ."},{"i":53951,"n":"שלמה הלוי מקרלין","f":"דוד הוכגלרנטר","k":"אדמור מקרלין לודמיר","bt":"תצח","dt":"תקנב-ה -כב תמוז","b":"אצל אלפסי שם אביו - מאיר. תלמיד המגיד ממזריטש, ור אהרן הגדול מקרלין. ניסה להפיץ את החסידות בליטא-תקלב, נאלץ לעבור ללודמיר-תקמו בגלל המחלוקת. מתורתו ב\"שמע שלמה השלם\". נהרג עק\"ה בזמן שהתפלל.","bk":[["שמע שלמה (קרלין)",""],["שמע שלמה",""]]},{"i":53952,"n":"שלמה הלוי מרומאטה","b":"מו\"צ ברומאטה(צרפת)-תר\"ל"},{"i":53953,"n":"שלמה הלוי משלוניקי","b":"מדפיס בשלוניקי-תקסג אצל מרדכי נחמן ורפאל קלעי."},{"i":53954,"n":"שלמה הלל מוארשא","k":"בעל עטרת שלמה","dt":"תרלד - כח אייר","b":"דיין בוארשא"},{"i":53955,"n":"שלמה המצרי מקושטא","b":"רופא המלך עמנואל הראשון בקושטא-ד'תתקלו, נזכר אצל ר בנימין מטודילא."},{"i":53956,"n":"שלמה ה\"ן דוד ויוסף מתאפילאלת","f":"יחיא","b":"מחכמי תאפילאלת-מרוקו."},{"i":53957,"n":"שלמה הנגיד ממצרים","f":"יוסף הרופא ממצרים","b":"מחכמי מצרים וראש הקהלה-רמא על מקום אביו, נזכר אצל ר משלם מוואלטרה."},{"i":53958,"n":"שלמה הקדוש ממיהאי-פאלוא","b":"רב במיהאי-פאלוא-תקצד, והקים את החברא קדישא במקום."},{"i":53959,"n":"שלמה הקראי מוילנא","f":"אהרן","k":"בעל אפריון","b":"מחכמי הקראים בוילנא, מקורב לר יהושע השל מוילנא."},{"i":53960,"n":"שלמה הרופא מפפד\"מ","f":"אברהם הרופא","b":"רופא בפפד\"מ. חתם-תטז על תקנון הרופאים בזמן ר מנדל בס מפפד\"מ."},{"i":53961,"n":"שלמה השופט מרפיח","f":"סעדיה","b":"דיין ברפיח בזמן הגאונים."},{"i":53962,"n":"שלמה השמש הסופר מירושלים","f":"סעדיה","b":"מחכמי ירושלים, בשנת שמז חתם על תקנת המס וכן בשנת שנז."},{"i":53963,"n":"שלמה וואלציס","b":"תלמיד ר פנחס מקוריץ וממסדרי כתביו. הנהגות ממנו ב\"מדרש פנחס\"."},{"i":53964,"n":"שלמה ויליזער מאילוקסט","b":"שו\"ב באילוקסט-קורלנד-תקצב, ור חיים רפאל על מקומו אחריו."},{"i":53965,"n":"שלמה זלמינא מראשקוב - א","f":"יוסף מראשקוב","k":"אדמור מראשקוב","dt":"תריב - יב ניסן","b":"אדמור בראשקוב."},{"i":53966,"n":"שלמה זלמינא מראשקוב - ב","f":"יחיאל יוסף","k":"אדמור מראשקוב","dt":"תרעו - כא חשון","b":"חתן ר אברהם יהושע השל ממזבוז (אפטא). אדמור ורב בראשקוב."},{"i":53967,"n":"שלמה זלמן (זלמלי) מוולוזין","f":"יצחק מוולוזין","k":"ר שלמה זלמלי מווילנה","bt":"תקטז","bp":"וולוזין","dt":"תקמה - יג אדר","dp":"וילנא","b":"אחיו הצעיר של ר חיים מוולוזין. תלמידו המובהק של הגר\"א. חתן הגביר ר יחיאל מיכל פעסעלס מוילנא. מגדולי דורו ונפטר צעיר. הגר\"א אמר עליו: \"ר זלמן היה הפלא ופלא\". תולדותיו ב\"תולדות אדם\" לר יחזקאל פיבל המגיד מוילנא, הגר\"א ראה את הספר."},{"i":53968,"n":"שלמה זלמן אריה ליב הכהן מצפת","f":"זאב וולף","dt":"תרז","dp":"כלכלתא","b":"מחכמי ליטא, עלה בשיירה הראשונה של תלמידי הגרא. בשליחות בליטא-תקפז, אחרי תקצב עבר לירושלים יצא בשליחות להודו ונפטר שם. מראשי הכולל בצפת, חתם-תקפט על הסכם החלוקה בין הפרושים לחסידים. חתם בירושלים-תקצב על שטר חזקה. חתנו - ר יעקב ספיר."},{"i":53969,"n":"שלמה זלמן הכהן מאוסטרהא","f":"יהודה כץ בן שלמה זלמ","k":"זלמן ר יהודה ר יוקבת","dt":"תקח - כז תמוז","dp":"אוסטרהא","b":"ראש מתיבתא ומלמד לתלמידים באוסטרהא. (היה אחד משלושת גדולי אוסטרהא בדורו שנקרא בשם זלמן והם ר אברהם משלם זלמן בן החכם צבי ונקרא - \"זלמיני\", ר שלמה הנ\"ל שנקרא - \"זעלמלא\", ותלמידו ר משלם ממזריטש שנקרא - \"ר זעלמילא מעזריטשער\". בניו: ר פסח מזסלב - ונכדו ר אבא הכהן זוסמן, ר משה מדובנא."},{"i":53970,"n":"שלמה זלמן הכהן מוילנא וטבריה","f":"צבי הירש","dt":"תקנט - כ אד\"ב","b":"בזיוו\"ש חתן ר משה סגל מהארקי. תלמיד ר מנחם מנדל מויטבסק ועלה עמו לארץ-תקלז. חתם כעד על צוואת רבו. ממנהיגי הקהלה בטבריה אחר פטירת רבו. בשליחות בחו\"ל כמה פעמים. בניו ר יצחק ור אברהם פנחס."},{"i":53971,"n":"שלמה זלמן הכהן מירושלים","f":"זאב וולף","dt":"כלכתא","dp":"תרז","b":"מראשי כולל הפרושים בירושלים, בשליחות הקהלה."},{"i":53972,"n":"שלמה זלמן הכהן מפפדמ","f":"אברהם טריר","dt":"תרז - טו חשון","b":"רב בפפד\"מ"},{"i":53973,"n":"שלמה זלמן הלוי מגלינא","dt":"תרלד","b":"רב בגלינא."},{"i":53974,"n":"שלמה זלמן זאב וולף מוילנא","f":"יחזקאל פיבל מוילנא","k":"בעל מוסר ודעת","bt":"תקמט","bp":"דראצ'ין","dt":"תרכז - י תשרי","b":"נקרא ע\"ש ר זעלמעלע-אחיו של ר חיים מוולוזין. חתן ר יצחק ישראל איסר אוריסזאהן. מגיד ואב\"ד בדראצ'ין(=דערעטשין), מגיד מישרים בוילנא-תקצג על מקום אביו, ונחשב לאחד מגדולי הדרשנים בדורו. נבחר ע\"י ראשי ישיבת וולוזין להיות בורר יחד עם ר דוד טבלי ממינסק - במחלוקת שפרצה אחר פטירת ר אליעזר יצחק. היה בקשר מיוחד עם מונטיפיורי בביקורו בוילנא, והוציא לכבודו \"תפארת משה\", והספיד את אשתו יהודית \"אלון בכות\". לאחר פטירתו בנו בני \"חברת נגרים\" בוילנא בביתו \"בית תפילה ע\"ש המגיד\".","bk":[["מוסר ודעת [על רמב\"ם]",""],["תאומי צביה",""]]},{"i":53975,"n":"שלמה זלמן יוסף מויליפולי","f":"אברהם אליהו","bt":"תקסו","dt":"תריח - ג כסלו","b":"רב בוועליפאלע"},{"i":53976,"n":"שלמה זלמן מביאלא","f":"יעקב מלודמיר","b":"חתן ר שמחה בן נחמן רפפורט מדובנא. רב בביאלא-תק. בנו - ר צבי הירש מלוקאטש, חתנו - ר יוסף."},{"i":53977,"n":"שלמה זלמן מביאליסטוק","dt":"תקעד - יח אדר","b":"רב בביאליסטוק"},{"i":53978,"n":"שלמה זלמן מבריסק","f":"יואל","b":"נכד בעל הב\"ח. חתן בעל תוי\"ט. מגדולי חכמי דורו בבריסק-תמ. חתניו - ר יחזקאל בן אברהם קצנלנבוגן מאלטונא, ר משה בן יוסף-ראש יוסף. אולי בנו - ר שמעון שנזכר בשו\"ת גבעת שאול."},{"i":53979,"n":"שלמה זלמן מבריסק","f":"ירמיה יעקב","b":"אב\"ד בגרידין, אב\"ד ור\"מ בבריסק-ת', ור יהושע השל על מקומו אחריו. הסכים על הש\"ך."},{"i":53980,"n":"שלמה זלמן מבריסק","b":"סופר קהלת בריסק-שצט."},{"i":53981,"n":"שלמה זלמן מגריידיץ","f":"אברהם","k":"ר' שלמה זלמן מקרמניץ","b":"רב בגריידיץ-ת\"ק"},{"i":53982,"n":"שלמה זלמן מדמביץ","b":"רב בדמביץ-תרכג."},{"i":53983,"n":"שלמה זלמן מהאגיטלאל","f":"נתנאל"},{"i":53984,"n":"שלמה זלמן מוארשא וקראקא","dt":"תקס - אחרי","dp":"וארשא","b":"רב בוארשא, קראקא-תקנט על מקום ר יצחק הלוי בן מרדכי, ולמעשה ישב בוארשא ולא הגיע לקראקא (כנראה בגלל התנגדות השלטון) ור צבי דוד כיהן כאב\"ד בפועל ועל מקומו אחריו."},{"i":53985,"n":"שלמה זלמן מויליפולי","dt":"תריח - יג כסלו","dp":"קרקא","b":"פועל ישועות,רב בוויעליפאלי"},{"i":53986,"n":"שלמה זלמן מוילנא","f":"חיים","dt":"תקכו - ח תמוז","dp":"וילנא","b":"דרשן, מג\"מ ומו\"ץ בוילנא ובנו ר חיים-שליח הגר\"א על מקומו אחריו-תקכו. חתם אחרי ר ליב שפירא סו\"ד-תקיז, ועוד כמה פעמים. בניו: ר הרץ-זקנו של ר הלל מאניקשט, ר יצחק אב\"ד זאסלי, ר אברהם מליפנישאק, ר זאב שו\"ב בזאסלי, ר חיים - מגיד בוילנא."},{"i":53987,"n":"שלמה זלמן מוילנא","dt":"תקסה - טו תשרי","b":"מו\"צ בווילנה"},{"i":53988,"n":"שלמה זלמן מוילנא","f":"צבי הירש כץ","dt":"תקנט","dp":"טבריה","b":"עלה עם אביו בשיירת ר שמחה מזלוזיץ בשנת תקכה. בשליחות בשנים תקלט, תקמה ותקמט."},{"i":53989,"n":"שלמה זלמן מוילנא","f":"משה יהושע ניישטטער","dt":"תרכח","b":"נכד-אבי אמו ר זעלמעלע מוילנא. בנו - ר אליהו נייוידל בעל \"מורה שפת עברית\"."},{"i":53990,"n":"שלמה זלמן מוילנא - אבי הגר\"א","f":"ישכר בער מוילנא","k":"ר' שלמה זלמן מווילנה","r":"אביו של הגר\"א","dt":"תקיט - כה כסלו","dp":"וילנא","b":"מגדולי חכמי וילנא, בניו: הגר\"א, ר ישכר בר מוילנא, ר אברהם מראגולה, ר מאיר מיאנישוק, ר משה מפאדזעלווע."},{"i":53991,"n":"שלמה זלמן מזאבלודוב","f":"חיים בן משה מקופנהגן","b":"רב בזאבלודוב."},{"i":53992,"n":"שלמה זלמן מחעלם","b":"רב בחלם-שנת ש'"},{"i":53993,"n":"שלמה זלמן מירוסלב וארשא","dt":"תקעה? - כד סיון","b":"גביר מראשי קהלת וארשא-תקסח. נכדו - ר ישעיה מושקאט מפראגא. (התאריכים לא מסתדרים)."},{"i":53994,"n":"שלמה זלמן מלבוב","f":"מאיר","b":"ראב\"ד בלבוב, חתם-תנד עם ר שלמה קרקובר ור ישעיה מלוצק, חתם-תסד עם ר ישעיה קצנלנבוגן. מגיה בשו\"ת \"שמש צדקה\" - ונציה תצו. נזכר ב\"תורת הקנאות\"."},{"i":53995,"n":"שלמה זלמן מלבוב","k":"בעל פירוש לתנך","b":"רב בונציה בזמן ר שמחה קאלימאני שחיבר עליו קינה ב\"קול עוגב\". וספר בשבחו ר שלמה אנשתרוק (רבו של ר יונה גירונדי). חיבר פירושים על התנ\"ך (באוצרות חיים לר חיים מיכל). מתלמידיו - ר דוד פארדו בעל שושנים לדוד."},{"i":53996,"n":"שלמה זלמן מלבוב","f":"אליהו","b":"מראשי קהלת לבוב, חתם-תקלו בפנקס הקהל."},{"i":53997,"n":"שלמה זלמן מליסא","b":"דיין בליסא-תס\"ה"},{"i":53998,"n":"שלמה זלמן מליסא - ב","f":"באאמ\"ו","b":"דיין בליסא-תקך, חתם עם ר צבי הירש ברלין וחבריו על מכתב לר דוד ברלין באה\"ו."},{"i":53999,"n":"שלמה זלמן ממיהלביץ","f":"ישראל או שמואל","b":"מחכמי מיהלביץ-תרכה, מכתב ממנו לר עקיבא יוסף שלזינגר."},{"i":54000,"n":"שלמה זלמן מסטרליסק","f":"משה מבריסק","k":"בעל מים אדירים","b":"רב-שנת תק\"כ"},{"i":54001,"n":"שלמה זלמן מסלוצק","dt":"תקלב","b":"רב בסלוצק"},{"i":54002,"n":"שלמה זלמן מפאקריי","f":"גרשון ראגולק","b":"רב בפאקריי-תר\"י"},{"i":54003,"n":"שלמה זלמן מפיעטריקוב","f":"ר\"י בעריש בן שלמה","b":"חתן הגביר ר צבי הירש מפיעטרקוב. אב\"ד אפאטשינוב, ובנו ר אלעזר נתמנה לרב על מקומו אחריו אך סירב."},{"i":54004,"n":"שלמה זלמן מפרישטיק","b":"רב בפרישטיק. בנו - ר יוסף צבי הירש בעל \"עוללות הבציר\"."},{"i":54005,"n":"שלמה זלמן מצשינוב","f":"יעקב","dt":"תקעט - יז תשרי","b":"תלמיד הנועם אלימלך, מחכמי צשינוב(=צעשינוב)."},{"i":54006,"n":"שלמה זלמן מקליש","b":"רב בקאליש-שצ\"ט-ת\"ג"},{"i":54007,"n":"שלמה זלמן מקלעטשוב","b":"חתן ר בנימין וולף בן אברהם אבלי חריף טרויבע מקאליש. רב בקלעטשעוו(=קלעטשוב), זלוטשוב. בנו - ר אלעזר ליסר בעל \"מגדנות אלעזר\"."},{"i":54008,"n":"שלמה זלמן מקראקא","b":"רב בקרקא-תקמ\"ז"},{"i":54009,"n":"שלמה זלמן מראסיין","f":"שמואל חסיד מראסיין","dt":"תריז","b":"רב מטעם בראסיין והגליל, ביאליסטוק. בנו - ר יצחק בן טובים מירושלים בעל \"גאון יעקב\", חתנו - ר יוסף אשרי מראסיין."},{"i":54010,"n":"שלמה זלמן מרייסין","b":"מצאצאי ר אליעזר אשכנזי בעל מעשה ה'. אחיו - ר ישעיה מויטבסק. בניו - ר משה חפץ מטשאווס, ר חיים דרויער."},{"i":54011,"n":"שלמה זלמן משובאץ","b":"רב בשובץ(=שובאץ)-תרן וחתנו ר שמואל שר רב בשובאץ - על מקומו אחריו?. בניו: ר משה מסובאלק, ר אברהם אליהו - שו\"ב במושבה בארץ ישראל, חתנו גם - ר יהודה זונדל קובלנץ."},{"i":54012,"n":"שלמה זלמן משטרסבורג","f":"יצחק איזיק","b":"מגיה בשטרסבורג-תקלז לספר - שיטה מקובצת, הו\"ל \"לחם סתרים\" לר שלמה אלגזי (מתוך עותק שקיבל מר דוד זינצהיים)."},{"i":54013,"n":"שלמה זלמן נפתלי הרץ מצפת","b":"נכד ר שלמה זלמן מירקש בעל \"שלחן שלמה\". מדקדק מחכמי צפת, מגיה ומסדר \"התהלים\" בדפוס ר ישראל בק בצפת-תקצג."},{"i":54014,"n":"שלמה זלמן תלמיד הבעשט","b":"חיבר זמר לשבת המיוסד על יסוד \"עשר ספירות\". בניו ר דב, ר זאב, ר צבי הירש-אבי האדמור ר יחזקאל טאוב מקוזמיר."},{"i":54015,"n":"שלמה זלקינד מוילנא","f":"ברוך","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה עם בניו - ר משה ור אליעזר."},{"i":54016,"n":"שלמה חגי מירושלים","b":"מחכמי ירושלים, בשנת תשנו חתם על תקנת המס, בשנת שסג בשליחות במרוקו עם ר מאיר מימרן. ר שמואל דגן מרבני פאס רשם פירוש ממנו."},{"i":54017,"n":"שלמה חיים מנפולי","f":"יחיאל רפאל כץ","b":"דיין בנפולי אצל ר יעקב לנדא."},{"i":54018,"n":"שלמה חנוך הניך מאפצאק","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":54019,"n":"שלמה חננאל משלוניקי","dt":"תמח","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":54020,"n":"שלמה חסיד מלובלין","k":"שלמה ר ליבשיס","dt":"שנא","dp":"לובלין","b":"תלמיד המהרש\"ל. אב\"ד לובלין, כנראה היה גם בקראקא. חתם ראשון על כרוז ועד ד ארצות - שלא לקנות רבנות בכסף. מתלמידיו: ר יואל בעל הב\"ח, ר ישעיה הורביץ בעל השל\"ה, ר צבי הירש שור. בנו - ר יהודה - נפטר חצי שנה אחריו. חיבר \"שמות גיטין\" - בכת\"י."},{"i":54021,"n":"שלמה חעלמא","f":"משה חר\"ח מזמושץ","k":"בעל מרכבת המשנה","bt":"תעז","bp":"זאמוטש","dt":"תקמא - כא תמוז","dp":"שלוניקי","b":"נכד בעל מגיני שלמה, ונכד(-אבי אמו) ר חיים בן שמואל (אביו של פרנס ועד דד\"א אברהם המכונה אברהם ר חיימש מלובלין). שם אביו חר\"ח (חתן ר חיים). חתן הנגיד ר משה פרנס מליסא וזאמושט ועבר אליו. רב בחעלמא-תקב (ונקרא בשם חעלמא כשם עירו). חבר בועד ארבע ארצות, זאמושט-תקכט, למברג-תקלא על מקום ר חיים רפפורט (רח\"כ) ור מרדכי זאב על מקומו אחריו, נסע לארץ-תקלז-ט והתעכב בקושטא - שם פגש את ר שלמה מולכו ושלוניקי להדפסת ספריו ושם נפטר במגפה עם אשתו. (לפי פרומקין ואחרים הגיע לארץ והיה בטבריה-תקלט ולאחר זמן בשליחות בתורכיה ונפטר בשלוניקי בזמן הדפסת ספרו \"מרכבת המשנה\" שלוניקי תקמב - ויש אומרים שזו טעות ולא הגיע לארץ- מצבתו נמצאת בשלוניקי והוא אחד מהיחידים בבית הקברות שם שמכונה \"הגאון המפורסם\"). בניו ר חיים רפפורט מרוזדול - חתן ר יצחק מאה\"ו, ר יהודה ליב מזמושץ - חתן רי\"ל משוורזניץ (בן ה\"סמיכת חכמים\"), חיבר \"מרכבת המשנה\" פפד\"א תקיא, ועוד. היה ממכשירי הגט מקליווא-תקכו. מחותן עם אב\"ד ליסא שהסכים על ספרו."},{"i":54022,"n":"שלמה חריף מזולקוא","f":"אלחנן מבוטצאץ וסטרי","dt":"תסו - כה תמוז","dp":"סלוצק","b":"נכד ר זאב וולף מאליק-חתן המהרש\"ל (ראה על כך אצל בובר). רב ברוזינאי-תמו, סלוצק-תנא. אחיו של ר אברהם אבלי מבלז."},{"i":54023,"n":"שלמה טוביה מאומסק","b":"חריף,רב באמסק-סיביר"},{"i":54024,"n":"שלמה יהודה ליב מוישקי-דוינסק","b":"רב בוישקי-דוינסק"},{"i":54025,"n":"שלמה יהודה ליב מלנעטשנא","k":"אדמור מלענטשנא","bt":"תקפה","dt":"תרנ - יט ניסן","b":"אדמו\"ר בלענטשנא-תרכ\"א"},{"i":54026,"n":"שלמה יהודה ליב מלענטשנא","f":"ברוך מרישא","k":"בעל תפארת אבות","bt":"תקלח","bp":"רישא","dt":"תרג - יג ניסן","b":"תלמיד החוזה מלובלין, והיהודי הקדוש מפשיסחא. חסך כסף לבר מצוה לקנות תפלין מר משה סופר מפשוורסק. מקורב לצדיקי פולין - ונחשב לאחד מל\"ו צדיקים כאביו לפניו. (היה מחלוקת עם ר נפתלי מרופשיץ ורצ\"א מדינוב היה לצדו). רב בבוקובסק-נאלץ לעזוב בגלל רדיפות, רוזוודוב, לנטשנא. מתלמידיו ר שמואל משיניבא בעל \"רמתים צופים\" ועוד. בניו - ר יהושע בעל \"תולדות אדם\", ר אברהם חותנו של ר שמואל ויינברג מסלונים. חיבר \"תפארת אבות\" ירושלים תשכא (ובו מתורתו ותורת בנו ונכדו) מתורתו גם בספר בנו ר יהושע \"תולדות אדם\". חתניו ר משה ליב קליגסברג, ור לייבל ראדומר."},{"i":54027,"n":"שלמה יואל מציזוב","dt":"תרסה","b":"רב בצ'יזוב"},{"i":54028,"n":"שלמה יום טוב מליכטנשטט","b":"רב בליכטנשטט-ת\"פ"},{"i":54029,"n":"שלמה יונה מאיטליה","f":"אפרים חיים","k":"בעל השפעת הרציונלזים","bt":"תקפה","bp":"איבריאה ליד טורינו","dt":"תרנט - לפני","b":"רב באיבריאה-איטליה, מודנא על מקום ר דוד זכות, ור משה קאמיאו על מקומו אחריו. חיבר ספרים על יסודות הדת באיטלקית."},{"i":54030,"n":"שלמה יונה מזלאטיק","b":"רב בזלוטיק (זלוטניק)-תרך."},{"i":54031,"n":"שלמה יוסף משלוניקי","f":"יהודה","k":"בעל לה איסטורייה דיל","b":"תרגם מאיטלקית ללאדינו את ההיסטוריה של מלחמת צרפת ופרוסיה בשם \"לה איסטורייה דילה גירה די 1870\"-תרלא."},{"i":54032,"n":"שלמה יחיאל משלוניקי","dt":"תסג","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":54033,"n":"שלמה יעקב מאי פאראן וירושלים","b":"מחכמי ירושלים."},{"i":54034,"n":"שלמה יעקב מדמשק","b":"פייטן מחכמי דמשק-ת'."},{"i":54035,"n":"שלמה יעקב נתן אריה מירושלים","f":"ראה: לב אריה, יעקב נ"},{"i":54036,"n":"שלמה יעקב רפאל מאיטליה","f":"מרדכי","b":"מחכמי איטליה, רב במודנא, פיררה. אחיהם של ר אבטליון ור יצחק, אביו של ר יהודה ממודנא בעל \"ארי נוהם\"."},{"i":54037,"n":"שלמה יצחק מואנדסבק - רופא","f":"יהודה","dt":"תקו","dp":"ונדסבק","b":"רופא מחכמי ואנדסבק."},{"i":54038,"n":"שלמה ישכר דב בריש מקארב","f":"נתן אריה","dt":"תרכט - יז כסלו","b":"רב בקארב,סוכטשוב,פלונסק,נאשעלסק,דומ\"צ בוורשה"},{"i":54039,"n":"שלמה ישראל מלייקווד","f":"משה מקראקא","b":"גר בלייקווד. חתן ר גדליה שור."},{"i":54040,"n":"שלמה כץ מזולקוא","f":"יונתן","b":"מחכמי זולקוא, חתם-תנד על תקנת הקהלה, ועוד פעמים רבות."},{"i":54041,"n":"שלמה ליב מלוגאש","b":"רב בלוגאש-תר\"כ"},{"i":54042,"n":"שלמה ליב מקדלבורג","b":"רב בקדלבורג-תצ\"ח"},{"i":54043,"n":"שלמה מאדריאנופול","f":"חיים","b":"רב באדריאנופול בדור שאחר גירוש ספרד. נזכר בספרי חכמי דורו ובהם הרלב\"ח."},{"i":54044,"n":"שלמה מאוזירן","f":"דוד","b":"מחכמי אוזירן - תשובה אליו ב\"ספר יהושע\"-תקעה."},{"i":54045,"n":"שלמה מאונגוואר","dt":"תקס","b":"דיין באונגוואר"},{"i":54046,"n":"שלמה מאופראן","f":"מסעוד","dt":"תקו","dp":"אופראן","b":"מחכמי מרוקו."},{"i":54047,"n":"שלמה מאורמייא-פרס","f":"אליהו","b":"דיין באורמייא-פרס. תשובה ממנו ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":54048,"n":"שלמה מאיזנשטט","b":"רב באייזנשטט-ת\"ק"},{"i":54049,"n":"שלמה מאיטליה","f":"היתום","bp":"חברון?","b":"מחכמי איטליה בזמנו של רשי, מפרש התלמוד, וכנראה היה יליד חברון."},{"i":54050,"n":"שלמה מאיטליה","f":"היתום","bt":"ד'תתן","dt":"ד'תתק","b":"מחכמי איטליה ומוצאו מספרד, מתורתו בספרי חכמי איטליה ובהם הרי\"ד ורבנו צדקיה."},{"i":54051,"n":"שלמה מאיספהאן-פרס","f":"דוד","b":"רב באיספהאן-פרס-תקץ, עם חברו ר יקותיאל בן נוריאל."},{"i":54052,"n":"שלמה מאיר הלוי מיגולניצה","b":"רב ביגולניצה."},{"i":54053,"n":"שלמה מאלג'יר","f":"חיים","k":"בעל שבח תודה","bt":"[תקע]","dt":"תרל - בערך","b":"כנראה מחכמי והראן-אלג'יר. חיבר ספר \"שבח תודה\" והוא שירים ופיוטים ליום פורים קטן - לזכר הצלת הקהלה-תקץ."},{"i":54054,"n":"שלמה מאלגיר","bt":"ש","dt":"שע - בערך","b":"מחכמי אלגיר בזמן ר אברהם ן טוואה שהשיב לו בספרו."},{"i":54055,"n":"שלמה מאפטא","f":"יהודה ליב","k":"בעל שבילי תורה","dt":"תקצב - כג אדר","b":"דיין באפטא-תקן, וארשא."},{"i":54056,"n":"שלמה מארגיל(=אלגיר)","f":"משה","k":"בעל בית אלקים","dt":"תקפח","b":"רב באלגיר. תרגם ספר השמים והעולם. חיבר \"בית אלוקים\" בכת\"י (די רוסי)."},{"i":54057,"n":"שלמה מארץ ישראל","f":"יהודה","b":"מחכמי ארץ ישראל בזמן הגאונים."},{"i":54058,"n":"שלמה מבאאב","f":"שלום","b":"תלמיד החת\"ס, ור מרדכי בנט מנייטרא. מחכמי באאב (גליל נייטרא)-תרז."},{"i":54059,"n":"שלמה מבאייעווע","dt":"תקעא","b":"מקורב לבעשט, המגיד ממזריטש ור שניאור זלמן מלאדי."},{"i":54060,"n":"שלמה מבגדד וירושלים","f":"יחזקאל יהודה","bt":"תקעח","bp":"בגדד","dt":"תרלב","dp":"ירושלים","b":"מחכמי בגדד נשא את רימה בת פרג חיים עבדאללה יוסף שהיתה ידועה כלמדנית ופקחית. בשנת תריד עלה לירושלים, והיה ממנהיגי עדת הבבלים שם. התפרנס מעזבון אביו אשר השאיר בכלכתה ועמד בראש ישיבת \"כנסת יחזקאל\" שיסד אביו בשנת תרד, וכן סייע לחכמי \"בית אל\"."},{"i":54061,"n":"שלמה מבוישנקוביץ","b":"גובה ראשי של מעות ארץ ישראל. גיסו של ר אברהם מקאליסק - נשא את אחותו של ר אברהם."},{"i":54062,"n":"שלמה מבוצאץ","f":"אליהו","b":"מחכמי בוצאץ - מתורתו ב\"דברי אבות\"."},{"i":54063,"n":"שלמה מביטשקא","b":"רב בביטשקא-תקע\"ה"},{"i":54064,"n":"שלמה מבילקמין","k":"ר' שלמה מבוטאטש","b":"חריף,רב בבולקאמין-תר\"מ"},{"i":54065,"n":"שלמה מגוסטינין ושירדז","b":"תלמיד ר מנחם מנדל מקוצק. רב בגוסטינין-תר, שירדז."},{"i":54066,"n":"שלמה מגיסינג","b":"רב בגיסינג-תרי\"ח"},{"i":54067,"n":"שלמה מגראנוב","f":"שמואל יהודה ליב","b":"בן האדמור מליניץ."},{"i":54068,"n":"שלמה מדולינא","dt":"תרל","b":"תלמיד ר משה אב\"ד דולינא, החוזה מלובלין, ר מנחם מנדל מקוסוב, ר צבי הירש מזידיטשוב, ור יצחק איזיק מזידיטשוב. היה סופר סת\"ם. מתולדותיו ב\"שופריה דמשה\"."},{"i":54069,"n":"שלמה מהאזנפוט","b":"רב בהאזנפוט(=האזענפוט)-תקנ. חתנו - ר מיכל מהאזנפוט. אחיו של ר אליהו ריטעווער מריטובה."},{"i":54070,"n":"שלמה מהונגריה וירושלים","dt":"תריא - יט אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":54071,"n":"שלמה מהוסיאטין","b":"רב בהוסיאטין-תקד."},{"i":54072,"n":"שלמה מהייסין","b":"תלמיד ר פנחס מקוריץ. היה במחלוקת עם חסידות ברסלב. מתורתו ב\"גאולת ישראל\"."},{"i":54073,"n":"שלמה מואנדסבק","f":"יצחק","dt":"תרי - כו תמוז","dp":"ואנדסבק","b":"מחכמי ואנדסבק."},{"i":54074,"n":"שלמה מווארניק","f":"מן","b":"רב בווארניק-ת\"ך"},{"i":54075,"n":"שלמה מוולאדיווי ולבוב","b":"דיין בוולאדיווי(-ולאדובה), חתם בלבוב-תקכח בפנקס הקהל. בנו - ר משה מולאדובה וקוזמיר בעל \"שו\"ת מהר\"ם רוטנברג אחרונים\"."},{"i":54076,"n":"שלמה מוילנא","f":"הקדוש דוב בער","dt":"תקפא - כז אד\"א","dp":"וילנא","b":"דיין בוילנא ומלמד תורה."},{"i":54077,"n":"שלמה מוילנא","b":"מגדולי חכמי ווילנה-ת\"ר"},{"i":54078,"n":"שלמה מוילנא","f":"שמואל","dt":"תקלא","dp":"וילנא","b":"מחכמי וילנא."},{"i":54079,"n":"שלמה מונייא מבלגרד ורויסטיץ","b":"ממגורשי בלגרד, רב ברויסטיץ-תמ - בערך. נכדו - ר שלמה הירש טירקלש מבודשפיץ."},{"i":54080,"n":"שלמה מור דוד","b":"מחכמי צפת, חתנו של ר משה בן מכיר. בשנת שנט בשליחות ישיבת חותנו בעין זיתים באיטליה. הדפיס את ספרו של חותנו \"סדר היום\"."},{"i":54081,"n":"שלמה מורמיזא","f":"שמשון","k":"ששו\"ן","b":"מגדולי הראשונים,מרביץ תורה בוורמייזא-ד'תת\"מ"},{"i":54082,"n":"שלמה מזאמוטש","b":"רב בזאמוטשט-ת\"ך"},{"i":54083,"n":"שלמה מזולקוא","f":"ישראל","k":"בעל תפארת הקדש","b":"מחכמי זולקוא. אולי הוא המחבר של \"אפריון שלמה\"."},{"i":54084,"n":"שלמה מזולקוא (פלק)","f":"ישכר דב בר מפודהייץ","b":"נכד הפני יהושע. אחיו - ר צבי הירש רוזניס מלבוב, וגיסו - ר צבי הירש מבוסק (או ר צבי הירש מייזלש מזולקוא)."},{"i":54085,"n":"שלמה מזידיטשוב","f":"אשר","b":"מחכמי לבוב?, בנה ביכ\"נ בזידיטשוב-תנד."},{"i":54086,"n":"שלמה מזיימל","dt":"תרכד","b":"מקובל, רב בזיימל-תקפד, ובנו ר בנימין ידידיה גרין על מקומו אחריו."},{"i":54087,"n":"שלמה מחברון","f":"דוד","b":"מחכמי חברון, חתם-תקכג על כתב שליחות ר חיים רחמים בג'איו, ור יצחק זאבי."},{"i":54088,"n":"שלמה מטבריה","f":"נתן נטע","b":"שליח ציבור של חסידי טבריה. חתם בשנים תקמו - תקנג."},{"i":54089,"n":"שלמה מטבריה","f":"זאב וולף מטשרני אוסט","dt":"תקסג - יו אב","b":"בנו של ראש קהילת החסידים בטבריה. בשליחות-תקס. נפטר בחיי אביו."},{"i":54090,"n":"שלמה מטולטשין","dt":"תח - יא תמוז","b":"רב בטולטשין. נהרג עק\"ה יחד עם בני קהילתו. ראה גם: ר חיים ור אליעזר מטולטשין."},{"i":54091,"n":"שלמה מטולטשין","b":"תלמיד הגר\"א, רב בטולטשין, עלה לירושלים בחיי הגר\"א. בנו - ר טוביה מירושלים. (לדעת ריבלין הוא אינו ר משה שלמה מטולטשין)"},{"i":54092,"n":"שלמה מטולצ’ין","bt":"1760","dt":"ה'תקפ 1820","bk":[["אבן שלמה",""]]},{"i":54093,"n":"שלמה מטורא","f":"יוסף מסרעליסק","dt":"תרלו - ט טבת","b":"רב בטורא,סערעט"},{"i":54094,"n":"שלמה מטורציאנו","bp":"טורציאנו (ספרד)","b":"עלה מספרד בשנת שפה, היה תלמיד הרמע מפאנו, נזכר בשות \"באר עשר\". מוזכר ב\"חרבות ירושלים\" כאחד הסובלים בשנת שפה בפרעות אבן פארוך."},{"i":54095,"n":"שלמה מטיווה","f":"הרא\"ש","b":"רב בטיווה(=תבץ)-שנות ה-ש'."},{"i":54096,"n":"שלמה מטיסמניץ","b":"ר\"מ בטיסמיניץ-תק\"ל"},{"i":54097,"n":"שלמה מטישביץ וזולקוא","f":"אליהו","b":"מחכמי זולקוא, חתם-תסד בזולקוא שלא יהיו קרובי הרב בתוך מנהיגי הקהל."},{"i":54098,"n":"שלמה מטראסטווץ","b":"רב בטראסטווץ-ת\"ר"},{"i":54099,"n":"שלמה מטרגוביתה","dt":"תקלט - טז שבט","b":"גביר,רב בטארגוביתה"},{"i":54100,"n":"שלמה מיורברג ווילנא","f":"אריה ליב","k":"בעל באר שבע","bp":"יורברג","dt":"תקפא - כח אד\"א","dp":"וילנא","b":"מגדולי מרביצי תורה בוילנא. חיבר גם \"אבני שהם\"."},{"i":54101,"n":"שלמה מירושלים","f":"יצחק מקאליש","dt":"י ניסן","b":"רב בירושלים,צפת,טבריה"},{"i":54102,"n":"שלמה מירושלים","f":"אברהם","b":"מחכמי ירושלים, בשנת תריא בשליחות \"בית אל\" במרוקו."},{"i":54103,"n":"שלמה מירושלים","f":"חלפתא","b":"מחכמי ירושלים, בשנת רסט חתם על תקנת המס."},{"i":54104,"n":"שלמה מירושלים","f":"אב\"ד","b":"מחכמי שקלוב או מוהילוב, עלה לירושלים בעליות הראשונות של הפרושים."},{"i":54105,"n":"שלמה מלאפאטשנא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":54106,"n":"שלמה מלאשיץ","f":"אריה ליב מרכניץ","b":"תלמיד ר נפתלי כץ בעל \"שער נפתלי\", הו\"ל את ספר רבו."},{"i":54107,"n":"שלמה מלבוב","f":"שמואל","dt":"תכד - ח אייר","dp":"לבוב","b":"פרנס מראשי קהלת לבוב. נהרג עק\"ה יחד עם אחיו אליעזר."},{"i":54108,"n":"שלמה מלבוב ומזריטש","f":"מרדכי","k":"בעל מזבח הזהב","b":"תלמיד המהרש\"ל. מרביץ תורה בלבוב, רב במזריטש-ליד אוסטרהא-שן. נזכר ב\"טיב גיטין\"."},{"i":54109,"n":"שלמה מלובלין","f":"חנוך הניך","dt":"תקיא - טו אייר","dp":"לובלין","b":"סו\"ד בלובלין. חתם על כתב החרם של ר יעקב חיים מלובלין על היוצאים כנגד ר יהונתן איבשיץ-תקיא."},{"i":54110,"n":"שלמה מלובלין","b":"סופר קהילת לובלין. חתם על שטר חזקה ביריד ירוסלב-תמז."},{"i":54111,"n":"שלמה מלודמיר","f":"משה מלאדמיר","k":"אדמור מלובלין","b":"נכד ר שלמה מקרלין. רב בלאדמיר-תר\"כ. חתן ר אהרן מטשרנוביל."},{"i":54112,"n":"שלמה מלויצק","b":"תלמיד המגיד ממזרטיש. היה במחלוקת עם ר פנחס מקוריץ בהיותם בקוריץ ור פנחס נאלץ לעבור לאוסטרהא."},{"i":54113,"n":"שלמה מלונדון","k":"רבינו שלמה מלונדון","b":"מגדולי הפוסקים,מרביץ תורה בלונדון-שנת כ'. חיבר קובץ פסקים"},{"i":54114,"n":"שלמה מליסא","f":"יהודה ליב דרשן מפרג","dt":"תקטז - אחרי","b":"אחיו של ר מיכל חסיד מברלין. דיין בליסא. בנו ר יוסף בעל יוסף אומץ."},{"i":54115,"n":"שלמה ממוהילוב","b":"מלמד תורה בוילנא. תלמיד הגר\"א."},{"i":54116,"n":"שלמה ממילייציץ","b":"רב במילייציץ-תר\"מ"},{"i":54117,"n":"שלמה ממינסק","f":"אליהו","b":"ר\"מ במינסק-תר בערך."},{"i":54118,"n":"שלמה ממראקש","f":"יאיר","dt":"תרפא","dp":"מראקש","b":"מחמכי מראקש-תרסב, דיין אצל ר\"א סמאנה. הגיה והסכים על \"קול מבשר\" לר משה רוזיליו. חתם על הסכמה לר דוד שושנה להיות ממונה כספים של ההקדש-תרכב."},{"i":54119,"n":"שלמה ממרוקו","f":"דוד בן אלישע","b":"גביר מחכמי ארטיב-מרוקו-תקלה, מכתב בקשה אליו מקהלת חברון."},{"i":54120,"n":"שלמה מנייטרא","b":"רב בנייטרא-תק\"צ"},{"i":54121,"n":"שלמה מניש","f":"יעקב","b":"דיין מחכמי ניש-תקן בערך."},{"i":54122,"n":"שלמה מסווראן","f":"משה צבי","b":"רב בסווראן-תר\"ו"},{"i":54123,"n":"שלמה מסטולין וחברון","f":"משה מסטולין","b":"נכד ר אהרן מלאכוביץ, ומצד אמו נינו של ר אשר הגדול מסטולין (פערל אמו של ר אביו-ר משה היתה בתו של ר אשר). מחכמי סטולין, עלה לארץ והתישב בחברון. חתנו - האדמור ר ירחמיאל יוסף בידרמן."},{"i":54124,"n":"שלמה מסטרליסק","f":"אורי מסטרליסק","b":"רב בסטרליסק-ת\"ר"},{"i":54125,"n":"שלמה מסלונים","b":"רב בסלונים-תק\"ע"},{"i":54126,"n":"שלמה מסלונים","b":"אביו של ר איזיק הירש מוארשא-חתן ר ליב מפלאצק בעל \"אלף המגן\" המזכירו בספרו."},{"i":54127,"n":"שלמה מסעוד מירושלים","b":"רב בירושלים-שנות ה-ר'-ש'."},{"i":54128,"n":"שלמה מסערדאהלי","b":"דומ\"צ בסערדאהעלי-תקפ\"ז"},{"i":54129,"n":"שלמה מספרד","f":"חנוך","b":"מגדולי המחקר בספרד-ק\"כ"},{"i":54130,"n":"שלמה מספרד","f":"עלי","k":"בעל חדושי תלמידי רבי","b":"מחכמי שיריא-ספרד-שנת ס', תלמיד רבינו יונה גירונדי, והרמבן, ור משה ן מוסא. חיבר חדושי תלמידי רבינו יונה."},{"i":54131,"n":"שלמה מספרד","f":"אברהם אביגדור","k":"בעל מראה האופנים","b":"רופא ומקובל בספרד. בן דורו של הרשב\"ץ. חיבר גם \"אשפירה\" ועוד."},{"i":54132,"n":"שלמה מספרד","f":"יהודה","b":"מחכמי ספרד, תלמיד הריטב\"א. חיבר חדושים לש\"ס."},{"i":54133,"n":"שלמה מספרד","f":"יונה","b":"מחכמי ספרד, גיסו של הרשב\"ץ. נהרג עק\"ה בפרעות קנא עם אביו ר יונה. מתלמידיו ר נתן נג'אר."},{"i":54134,"n":"שלמה מספרד וקושטא","f":"חנוך","k":"בעל מגלה עמוקות","b":"מחכמי ספרד-קך. בנו ר חנוך אלקונסטנטיני. חיבר \"מגלה עמוקות\" (די רוסי)."},{"i":54135,"n":"שלמה מסרקסטה-ספרד","b":"מחכמי סקרסטה-ספרד - ד'תתקצ, ומתרגם."},{"i":54136,"n":"שלמה מפוסוואל","dt":"תקסו","b":"רב בפוסבול(=פאסוואל), פומפיאן, אבלניק, אניקשט."},{"i":54137,"n":"שלמה מפינטשוב - א","k":"בעל יקהל שלמה","b":"תלמיד ר פרץ אשכנזי. חיבר \"יקהל שלמה\" והו\"ל בנו - ר נפתלי עם הערותיו."},{"i":54138,"n":"שלמה מפינטשוב - ב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ. בנו - ר בנימין."},{"i":54139,"n":"שלמה מפליבנא","f":"חיים מפליבנא","bp":"קושטא","b":"רב בפליבנא-בולגריה-ש' בערך, על מקום אביו. שאלה ממנו לר תם ן יחיא."},{"i":54140,"n":"שלמה מפצ'ל-תימן","f":"זכריה","k":"בעל נרג'ס אלקלוב","b":"מחכמי תימן במאה ה-16. חיבר ספר פילוסופי \"נרג'ס אלקלוב\" - חבצלת הלבבות העוסק בנושאי מחשבה... - בכת\"י."},{"i":54141,"n":"שלמה מפרידברג","f":"מאיר","b":"מחכמי פרידברג. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":54142,"n":"שלמה מפריישטטל","b":"רב בפריישטטל-ת\"ק"},{"i":54143,"n":"שלמה מפרמישלן","f":"יצחק מקאלוש","k":"אדמור מפרמישלן צפת","dt":"תרכח - יא ניסן","b":"נינו של ר מאיר מפרמישלן. תלמיד ר משה צבי מסאווראן. עלה לארץ והתישב בצפת, חברון וירושלים. נפטר ללא ילדים."},{"i":54144,"n":"שלמה מצרפת","k":"ר' שלמה מדריוש הקדוש","b":"מגדולי בעלי התוספות בחכמי צרפת-ד'תתק\"נ"},{"i":54145,"n":"שלמה מקאלוואריה","b":"מרבני קלוואריע(-קאלווריה)-תקס"},{"i":54146,"n":"שלמה מקאמארינו וירושלים","b":"מחכמי קאמארינו-איטליה, רב בירושלים-שנות ה-ר'-ש'."},{"i":54147,"n":"שלמה מקאסוב","b":"רב בקאסוב-תק\"ס"},{"i":54148,"n":"שלמה מקוברין","b":"חתן ר נחמן רפפורט. רב בקוברין-תקי. לפי בובר-זולקוא - חתנו - ר חיים שמחה בן נחמן רפפורט."},{"i":54149,"n":"שלמה מקושטא","f":"חיים עוזיאל","k":"בעל ענף עץ","b":"רב בקושטא וממונה על השחיטה והבדיקה, חברו של ר רפאל ביטראן מקושטא."},{"i":54150,"n":"שלמה מקושטא","f":"מזל טוב","dt":"רצב - אחרי","b":"משורר מחכמי קושטא, מדפיס בקושטא-רע, עם ר אשטרוק די טולון ור שמואל ריקומין."},{"i":54151,"n":"שלמה מקטלוניה-ספרד","f":"הרמב\"ן","b":"חתן ר יונה גירונדי. מגדולי חכמי דורו בקטלוניה-שנת נ', אליו נשלחה אגרת הרמב\"ן. בנו ר יונה."},{"i":54152,"n":"שלמה מקיוסטנדיל","f":"אברהם","b":"דיין בקיוסטנדיל-תקנה, יחד עם ר שמואל קונפורטי, ור יעקב קונפורטי."},{"i":54153,"n":"שלמה מקמרינו וירושלים","b":"דיין בירושלים-רפ\"ב"},{"i":54154,"n":"שלמה מקניגסברג","b":"רב בקניגסברג-תק\"פ"},{"i":54155,"n":"שלמה מקריט(=כרתים) וירושלים","f":"בנימין","bp":"קנדיא (כרתים)","b":"מחכמי ירושלים עלה מכרתים, בשנת רסט חתם על תקנת המס"},{"i":54156,"n":"שלמה מקרלסבורג","b":"רב בקרלסבורג-תק\"ס"},{"i":54157,"n":"שלמה מקרמניץ ולבוב","b":"דיין וסופר קהלת לבוב, חתם-תקלה על קיום חתימה."},{"i":54158,"n":"שלמה מקשנוב","dt":"יח אייר","b":"רב בקשאנוב-תק\"פ"},{"i":54159,"n":"שלמה מראשקוב"},{"i":54160,"n":"שלמה משה מקופיטשיניץ","f":"י'","dt":"תרכז - בערך","b":"רב בקופיטשיניץ-תריב."},{"i":54161,"n":"שלמה משלוניקי","f":"דוד","dt":"תנט - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":54162,"n":"שלמה משלוניקי","f":"גביריל","dt":"שעז - יד אלול","dp":"שלוניקי","b":"נהרג ליד שלוניקי בדרכו מיריד דולייא-שפח עם רבים מישראל."},{"i":54163,"n":"שלמה משקלוב","f":"יצחק","b":"מתלמידי הגרא, עלה בשנת תקעו משקלוב או מוהילוב. בשנת תר בשליחות העדה התימנית."},{"i":54164,"n":"שלמה מתימן","f":"ישועה גמליאל","bt":"תפ","bp":"צנעא","dt":"תקנה","dp":"צנעא","b":"דיין בצנעא-תקל, אצל המהרי\"ץ."},{"i":54165,"n":"שלמה נח מאלכסנדר","b":"דומ\"ץ באלכסנדר."},{"i":54166,"n":"שלמה סגל","b":"מחדושיו ב\"ברכת טוב\"."},{"i":54167,"n":"שלמה סגל הלוי מארץ ישראל","f":"חיים","b":"מחכמי ארץ ישראל, בשנת תסב בשליחות בברסלוי וכן בשנת תעט."},{"i":54168,"n":"שלמה סגל מצפת","f":"שמואל נחום גסנבויאר","bt":"תרסח","bp":"צפת","dt":"תשן","b":"גדל אצל זקנו - ר משה ברומפלד. תלמיד ר משה ליב שפירא בישיבת חב\"ד בירושלים."},{"i":54169,"n":"שלמה סגל מצפת","b":"בשליחות קהילת החסידים בצפת - מראשוני השליחים."},{"i":54170,"n":"שלמה עמנואל מדמשק","b":"רב בדמשק-קן, בזמן ר שם טוב ור פרץ ור יעקב, ושלחו ביחד שאלה לר\"ן בספרד כנזכר בשות הר\"ן."},{"i":54171,"n":"שלמה עמנואל משלוניקי","dt":"תף - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי-תם."},{"i":54172,"n":"שלמה עריפי הכהן מאלגיר","f":"יוסף","bt":"קע","dt":"רמ - בערך","b":"רב בתונאת(=תוואנת)-ליד תייארת-אלגיר. שאלה ממנו לרשב\"ש בענין מזון ורפואה ונזכר בשו\"ת הרשב\"ש."},{"i":54173,"n":"שלמה פישל ממנוסטרישץ","b":"רב במניסטריץ"},{"i":54174,"n":"שלמה פנחס מהאיסין וירושלים","dt":"תרכא - כח ניסן","dp":"ירושלים","b":"רב בהאיסין, עלה לירושלים. חתם-תרטו עם ר ניסן בק ור יוסף רוקח מאומאן בשם קהל חסידים אשכנזים בירושלים."},{"i":54175,"n":"שלמה פנחס משלוניקי","b":"מורה בביהמ\"ד לרבנים \"אור החיים\" בשלוניקי-תרף. אחיו - ר משה."},{"i":54176,"n":"שלמה פרץ מגרבה","b":"רב בגרבה. מחדושיו ב\"קרני ראם\"."},{"i":54177,"n":"שלמה צבי הירש מוילנא","f":"צמח","dt":"תקפז - כה ניסן","dp":"וילנא","b":"מרואי פני הגר\"א, מו\"צ בוילנא. נקבר לצד בעל באר הגולה."},{"i":54178,"n":"שלמה ציון משלוניקי","dt":"תרצד","dp":"שלוניקי","b":"סופר סת\"ם מחכמי שלוניקי, רב ומורה בביהמ\"ד לרבנים \"בית יוסף\", ודיין-תרעז."},{"i":54179,"n":"שלמה ר ליבוש'ס מפולנאה ולובלין","f":"יהודה ליב מלובלין","k":"מהרש\"ל השני","b":"ר\"מ בקראקא, רב בפולנאה, לובלין-שנ. חתנו - ר זאב וולף מאליק. (היו שהחליפו בינו לבין המהרש\"ל)."},{"i":54180,"n":"שלמה ראובן משירווינט","f":"דוד","dt":"תרמו","b":"רב בשירווינט-ליד וילקומיר."},{"i":54181,"n":"שלמה שאלתיאל מניקופול","b":"רב בניקופול-שנות ה-ש'."},{"i":54182,"n":"שלמה שאלתיאל משלוניקי","b":"מדפיס בשלוניקי-תקמה אצל דוד ישראליג'ה ומרדכי נחמן."},{"i":54183,"n":"שלמה שלומיל מצפת","f":"חיים מיינשטריל","k":"בעל שבחי הארי","bp":"מורביה","b":"עלה לצפת בשנת שסב-שסג והיה מחכמיה, נתן גט לאשתו שסרבה לעלות עמו. היה חתנו של ר שמואל סרוק מגורי הארי וירש ממנו כתבי יד של הארי. חיבר \"שבחי הארי\""},{"i":54184,"n":"שלמון, משה מטורדשין","k":"בעל נתיב משה","bt":"תקצה","bp":"חוסט","dt":"תרן - אחרי","b":"תלמיד ר מנחם מנדל פאנט, ר מנחם א\"ש באונגואר, ועוד. רב בטוראדשין-תרכז. חיבר \"נתיב משה\" והיה מחלוקת כנגדו מצד כמה רבנים."},{"i":54185,"n":"שלמן מרדכי די קינדערש מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":54186,"n":"שלנגר, יחזקאל הלוי מפרשבורג","bt":"תריא","dt":"תרפז - ד כסלו","dp":"פרשבורג","b":"נכד ר יהודה ליב פיש מרוזנברג - מצד אמו. תלמיד הכת\"ס, ור חזקיה פיבל פלויט משוראן והשבט סופר. חתן דודו ר יוסף פיש. מחכמי פרשבורג."},{"i":54187,"n":"שלנגר, יעקב מקאפוש","b":"מראשי קהלת קאפוש, חתם-תרמב על מינוי ר יהושע פריד."},{"i":54188,"n":"שלנק, אלחנן משה יהושע מירושלים","b":"רב בירושלים-תרע."},{"i":54189,"n":"שלנק, גמליאל מירושלים","f":"מרדכי","bp":"ירושלים","dt":"תרנו-סו","dp":"יפו - ירושלים","b":"רוקח בביקור חולים בירושלים, סופר, עו\"ד, פעיל צבור."},{"i":54190,"n":"שלנק, חיים יוחנן צבי הרש מירוש","f":"מרדכי","bt":"תקעה","bp":"שלאנק","dt":"תרמד - יב תמוז","dp":"ירושלים","b":"תלמיד החת\"ס. חתן ר דוד טבלי ברלין מלונדון. עלה לירושלים עם חותנו-תקצח ואביו. בזיוו\"ש חתן ר אריה ליב מהורדנא. ממיסדי ישיבת \"עץ חיים\" בירושלים, ומוסדות נוספים יחד עם רמ\"י שנייטוך."},{"i":54191,"n":"שלנק, יהודה ליב מירושלים","f":"יהושע","bp":"ירושלים","b":"מורה בירושלים."},{"i":54192,"n":"שלנק, מרדכי מירושלים","f":"שלמה משלאנק","k":"הו\"ל חדושי הרשב\"א","bt":"תקלג","dt":"תרכא - כט אב","dp":"ירושלים","b":"תלמיד החת\"ס, ור עקיבא איגר. מחכמי פוזנא, שלאנק, פרשבורג-תקפ והיה שם יד ימינו של החת\"ס, רב בבימ\"ד ר צבי הרש לעהרן באמשטרדם-תקצב, עלה לירושלים. הו\"ל חדושי ר\" מיגש (ושילב בהם מתורת החת\"ס - תחלתו באונס וסופו מרצון), ועוד. בנו - ר יוחנן צבי מירושלים."},{"i":54193,"n":"שלנקר, יואל מפיורדא","f":"משה","b":"מחכמי פיורדא-אחרי תעח (חתם על רש\"י לתורה - אמשטרדם תעח). כנראה נכדו - ר יואל בן דוד - מדפיס בפיורדא."},{"i":54194,"n":"שלנקר, יואל מפיורדא - הנכד","f":"דוד","b":"מדפיס בדפוס חיים בן צבי הירש בפיורדא - תקל."},{"i":54195,"n":"שלנקר, ירמיה מפיורדא","k":"בעל ירים משה","b":"מגדולי חכמי פיורדא-ת\"כ"},{"i":54196,"n":"שלעז, בן ציון מירושלים","f":"שלמה זלמן","k":"בעל שארית ציון","bp":"ליטא","dt":"תרנו","dp":"ירושלים","b":"חתן ר שבתי יפה. עלה לירושלים במאה ה-19. מחכמי ירושלים, חיבר גם \"הציבי ציונים\" ירושלים תרלא, \"ידיו אמונה\", ועוד. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. בנו - ר צבי הירש."},{"i":54197,"n":"שלעז, צבי הירש","f":"בן ציון","k":"בעל זכרון אב ואם","bp":"ז'ידיק-ליטא","b":"תלמיד ישיבת וילנא, וולוזין. יסד ישיבות בקורסון, בוגוסלב, רז'יצה(=רעזישצעוו), ברדיצ'ב ואומן, והקדיש להם את הכנסותיו מספריו. חיבר גם \"שיחות חולין של תלמידי חכמים\"."},{"i":54198,"n":"שלף, חיים מיסלו","f":"יחזקאל דודו הכהן","dt":"תשם","dp":"לונדון","b":"חסיד בובוב, רב ביסלו. חתן ר אברהם יחזקאל טיפנברון. ניצל מהשואה ועבר ללונדון."},{"i":54199,"n":"שלף, נחום מיסלו","f":"יחזקאל דודו הכהן","bp":"יסלו","dt":"תשלו","b":"חסיד בובוב, אחיו של ר חיים הרב ביסלו. חתן ר חיים פינטר מבוקובסק. ר\"מ בישיבת בובוב ביסלו. ניצל מהשואה ואחריה רב ביעלאווא, עבר ללונדון. תלמיד ר צבי הירש מייזלש שהזכירו בספרו \"בנין צבי\". בנו - ר יחזקאל דוד - ר\"מ בישיבת בובוב בלונדון. מתורתו בכר\"ש-תשלט."},{"i":54200,"n":"שלפובורסקי, מרדכי","dt":"תשכ","b":"מו\"צ בקובנה,עלה לא\"י-תש\"ט,רב בזרנוגה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":54201,"n":"שלפוברסקי, שמואל","f":"יהודה","bt":"1882","bp":"קיידאן","dt":"1949","dp":"פתח תקוה","b":"חבר עירית קובנא ופעיל בתנועה הציונית. פרסם מאמרים בעניני כלכלה. עלה לארץ-1936 והתישב באבן יהודה, פתח תקוה."},{"i":54202,"n":"שלפק, משה מבאזאר","dt":"תשג","b":"רב בבאזאר"},{"i":54203,"n":"שלקוביץ, אברהם ל' - בן אביגדור","k":"בעל אהבה וחובה","bt":"1866","bp":"ז'אלודק-פלך וילנא","dt":"1921","dp":"קרלסברד - תל אביב","b":"תלמיד ישיבות ליטא, מורה עברי בקובנא, מזכיר באגודת \"בני משה\" בוילנא ווארשא. חיבר ספורים ובהם \"לפני ארבע מאות שנה\", ועוד.יו\"ר אגודת הסופרים והעתונאים העבריים בוארשא. אחיו של הסופר שלמה גולדמן - שלמון, וגיסם של של\"ג ויהואש. הו\"ל ספרי למוד ומקרא לנוער בעברית."},{"i":54204,"n":"שם טוב אבא מקושטא","b":"מחכמי קושטא-שנות ה-ת'."},{"i":54205,"n":"שם טוב הלוי","b":"מגדולי חכמי פרובינצא-ד'תת\"ל"},{"i":54206,"n":"שם טוב הלוי מאלג'יר","b":"מחכמי אלג'יר, חברם של הריב\"ש ור עמרם אפרתי מאוראן. רב בבג'איה. נאם באספת אבל באלג'יר לזכר ר שאול אשתרוק הכהן, וסתר את טענות בונשתרוק כנגד המנוח. היה במחלוקת עם הרשב\"ץ, לאחר שהרשב\"ץ פסק נגד קרובת משפחתו - אשת יצחק עבד אל חק."},{"i":54207,"n":"שם טוב הלוי מספרד ואלגיר","bt":"קך","dt":"קץ - בערך","b":"ממגורשי ספרד, דיין בבג'איה-אלגיר, יחד עם ר בנימין עמר - ויחד הספידו את ר שאול אשתרוק הכהן, מקורב לריב\"ש ונזכר אצלו. חלק כמה פעמים על הרשב\"ץ."},{"i":54208,"n":"שם טוב הלוי מצפת","b":"מחכמי צפת. נזכר ב\"חזיונות\" לר חיים ויטאל."},{"i":54209,"n":"שם טוב המזרחי ממרוקו","dp":"תסמסלא","b":"מצדיקי מרוקו, וכנראה שמוצאו מירושלים."},{"i":54210,"n":"שם טוב חיים מקושטא","f":"שמואל - שמן המשחה","b":"מחכמי קושטא, נספד מאת ר חיים פלאג'י."},{"i":54211,"n":"שם טוב מבורגוש","b":"מחכמי ספרד. תלמדי ר יצחק בר יעקב."},{"i":54212,"n":"שם טוב מוידין","f":"ציון","b":"דיין בוידין-תקפג עם ר אברהם הכהן ור יוסף בן אברהם."},{"i":54213,"n":"שם טוב מליאון","b":"תשובות ממנו במחקר ובקבלה נדפסו בונציה (די רוסי)."},{"i":54214,"n":"שם טוב ממרוקו","f":"אברהם","b":"נגיד במרוקו, הוסר ממעמדו-רפז ונתמנה תחתיו ר שאול בן שם טוב ן רמוך."},{"i":54215,"n":"שם טוב מפארו","f":"יעקב","b":"חכם ומקובל. חיבר ספר בחכמת הקבלה על ספר הזהר."},{"i":54216,"n":"שם טוב ן שאול משלוניקי","b":"מחכמי שלוניקי-תקנה. חיבר הספד לר שלמה בולה ונדפס בסוף \"לחם שלמה\"-תקנה."},{"i":54217,"n":"שם טוב ן, יוסף","f":"שם טוב בעל האמונות","k":"בעל כבוד אלקים","bt":"קס","dt":"רכ","b":"מחכמי ספרד, מקורב למלכות, התוכח בעניני פילוסופיה. חיבר \"כבוד אלוקים\", ביאור על אגרת ר פריפוט דורנטי, \"דעת עליון\" כנגד המומר אבנר, ועוד בכת\"י (אצל די רוסי). נהרג עק\"ה. בנו - ר שם טוב."},{"i":54218,"n":"שם טוב ן, יוסף ממראקש","b":"מחכמי מראקש, חתם על פס\"ד בעניני טריפות-תקמח."},{"i":54219,"n":"שם טוב ן, יוסף מספרד ושלוניקי","f":"שם טוב בן ישועה חי","k":"בעל שארית יוסף","b":"מחכמי שלוניקי בדור שאחר הגירוש."},{"i":54220,"n":"שם טוב ן, יוסף משלוניקי","b":"מחכמי שלוניקי-שץ."},{"i":54221,"n":"שם טוב ן, יצחק מספרד","b":"תלמיד ר שם טוב ן שם טוב. מחכמי ספרד בדור שלפני הגירוש, בזמן ר יצחק קנפנטון. חיבר פירוש למורה נבוכים לרמבם."},{"i":54222,"n":"שם טוב ן, שם טוב הנכד","f":"יוסף","k":"בעל שם טוב","dt":"רמט - אחרי","b":"מחכמי ספרד-רמט, פילוסוף,דרשן."},{"i":54223,"n":"שם טוב ן, שם טוב מספרד","f":"עוזיאל","b":"תלמיד ר יצחק אבוהב. מחכמי ספרד. לאחר הגירוש התישב בצפון אפריקה."},{"i":54224,"n":"שם טוב ן, שם טוב מספרד הזקן","f":"יוסף","k":"בעל ספר האמונות","dt":"קץ","b":"מקובל וראש ישיבה בספרד-קנא, חיבר \"ספר האמונות\" ובו תקף את חכמי הפילוסופיה ובהם ר אברהם ן עזרא, הרלב\"ג, ואף את ספרי הפילוסופיה של הרמב\"ם. בניו ר יוסף, ור יצחק, ונכדו ר שם טוב - נטו דוקא לצד הרמב\"ם, ור משה אלשקר תקף בספרו \"השגות\" את ספרו של ר שם טוב. חיבר גם פירוש קבלי על הספירות, ופירוש למסכת אבות. בנו ר יוסף בעל \"כבוד אלקים\", \"עין הקורא\"."},{"i":54225,"n":"שם טוב שמעיה מסרייבו","b":"מראשי קהלת סרייבו-שנות ה-ת' - אחד משבעת טובי העיר."},{"i":54226,"n":"שם טוב, עמי הנגיד ממרוקו","b":"נגיד במרוקו, וירד ממעמדו-רפז ור שאול ברכיה ן רמוך על מקומו אחריו."},{"i":54227,"n":"שמאי מאוסטרהא","f":"יצחק איזיק מראווני","b":"חתן ר אלחנן הלפרין מזלטשוב ושאריגרד. פרנס באוסטרהא. (אולי אביו היה בנו של ר שמואל ר יעקב'ס או של ר יוזפא פרנס מדינת ואהלין - שניהם היו רבנים בראווני)."},{"i":54228,"n":"שמאי מטופרוב","b":"רב בטופרוב. תשובה אליו בטוט\"ד."},{"i":54229,"n":"שמאלהויזן, שלמה ברוך מבודפשט","f":"אברהם מבודפשט","k":"בעל שברי לוחות-תרעג","bt":"תרכד","bp":"בודפשט","dt":"תשה - כה אדר","dp":"בודפשט","b":"תלמיד ר דוד ליב זילברשטין בוויצען, ר משה פולק בבונהאד, השב\"ס, ה\"ייטב לב\", וה\"קדושת יו\"ט\" בסיגט. חתן הגביר ר אהרן יעקב אלימלך שטינמץ מביטשקוף, ועבר לשם. רב בבודפשט בחברת תהלים ליד אביו. הו\"ל \"שברי לוחות\" עם הוספות ממנו. חתנו ר משה בלוי מבודפשט-בני ברק."},{"i":54230,"n":"שמאמה, אליהו","b":"גביר-תקפח, הקדשה אליו מאת ר יוסף זמירו."},{"i":54231,"n":"שמאמה, יוסף מתוניס","b":"תלמידו בעל \"מקור ברוך\" הזכירו בספרו."},{"i":54232,"n":"שמאמה, משה מתונס","b":"רב בתונס בזמן ר אברהם חג'אג' בעל \"זרעו של אברהם\". נזכר ב\"ויאמר משה\"."},{"i":54233,"n":"שמאמה, שלמה מתונס - א","f":"יהודה","k":"בעל שורש ישי","bt":"תקלט","dt":"תקסו - כא תמוז","b":"רב בתוניס-תקמ. תלמיד ר משה שלום בעל \"ישמח משה\". נפטר בגיל 27."},{"i":54234,"n":"שמאמה, שלמה מתונס - ב","f":"שמואל - קרן הצבי","k":"בעל בגדי שש","dt":"תרטו","dp":"תונס","b":"דיין בתונס, חברו של ר אברהם יצחק בעל \"משמרות כהונה\". חיבר גם \"עמודי שש\", \"בית המלך\" ועוד. ספרו \"בגדי שש\" נדפס ע\"י נכדיו ר יצחק, ור שלמה שמאמא."},{"i":54235,"n":"שמאמה, שלמה מתונס - ג","f":"משה","k":"בעל שש אנכי","b":"כנראה נכד ר שלמה בעל בגדי שש, הו\"ל את ספר זקנו."},{"i":54236,"n":"שמאמה, שמואל מטריפולי","bt":"תקל","dt":"תר - בערך","b":"רב בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":54237,"n":"שמאמה, שמואל מתונס","k":"בעל קרן הצבי","b":"מקובל מחכמי תונס, חברו של ר יהודה נג'אר בעל \"לימודי ה'\". חיבר פירוש לספר הקרנים בשם \"קרן הצבי\"."},{"i":54238,"n":"שמאע שקאלו, שלום מחלב","f":"עזרא","dt":"תרעט","b":"מחכמי חלב."},{"i":54239,"n":"שמאע, אליהו הלוי","f":"יוסף","k":"בעל קרבן אשה","r":"רבה של ארם צובה","bt":"1775?","dt":"תקעד - יא אייר","dp":"חלב","b":"אב\"ד בחלב. חיבר \"מכשירי מילה\" ליוורנו, \"קרבן אשה\" ליוורנו.","bk":[["קרבן אשה","מפרשי רמב\"ם"],["מכשירי מילה",""]]},{"i":54240,"n":"שמאע, אליהו יוסף מחלב","bt":"תרמא","bp":"חלב","dt":"תרצג - כב אייר","dp":"ירושלים","b":"עבר לארה\"ב, ג'מייקה, ברזיל, ארגנטינה, מנצ'סטר-אנגליה, עלה לארץ, עסק בעניני צבור"},{"i":54241,"n":"שמאע, יוסף","bp":"ארם צובא","b":"עלה לירושלים. בשנת תשב יזם הקמת \"אוצר התורה\" שפעל רבות במרוקו ובצרפת להקמת מוסדות תורניים."},{"i":54242,"n":"שמאע, יצחק מפאס","b":"מחכמי פאס, הספיד את ר יהודה עוזיאל-תמט, ואת ר שלמה עמאר-תנא."},{"i":54243,"n":"שמאע-שקאלו, עזרא מירושלים","f":"שלום בן עזרא","bt":"תרנב","bp":"חלב","dt":"תשמב","dp":"ירושלים","b":"עלה לירושלים-תרעח עם אביו, מקובל בירושלים."},{"i":54244,"n":"שמאע-שקאלו, שלום מחלב וירושלים","f":"עזרא","dt":"תרעט","b":"מקובל מחכמי חלב, עלה לירושלים-תרעח עם בנו - עזרא."},{"i":54245,"n":"שמאש, משה חיים מבגדד","f":"שלמה","dt":"תרפג - כט שבט","dp":"בגדד","b":"תלמיד ר עבדאללה סומך, חתן ר יעקב יוסף הרופא מבגדד. רב ראשי בבגדד - \"חכם באשי\"-תרפא."},{"i":54246,"n":"שמו, אברהם מסופיה","b":"רב בסופיה-רל, סייע לאשכנזים שהתיישבו בסופיה. ובקהלת האשכנזים בסופיה נהגו להזכירו בתפילה בשבת שלפני שבועות."},{"i":54247,"n":"שמו, אברהם מקורפו","f":"ראובן","k":"בעל זרע אברהם","b":"רב בקורפו בזמן בעל ר יצחק למפרונטי. ידידו של ר יעקב חזק מפדובה והתכתב עמו. חיבר \"זרע אברהם\" מנטובה."},{"i":54248,"n":"שמו, דניאל מקורפו","b":"רב בקורפו-רץ, פגש את ר בנימין בעל שו\"ת בנימין זאב בהיותו שם."},{"i":54249,"n":"שמו, יהודה מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":54250,"n":"שמו, שבתי מוידין ווינה","f":"אברהם","b":"עבר מוידין לוינה, גביר מחכמי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":54251,"n":"שמואל","f":"רבינו מאיר","k":"רשב\"ם","bt":"ד'תתמה","dt":"ד'תתקיח","b":"מראשוני בעלי התוספות,ממשיך דרכו של סבו רש\"י,פרשן,פוסק,מרביץ תורה בטרויש"},{"i":54252,"n":"שמואל","f":"רבינו אלחנן","bt":"ד'תתקמד","b":"חריף ומופלג,מגדולי דורו,מבעלי התוספות"},{"i":54253,"n":"שמואל","f":"זלמן","b":"רב-שנת תר\"כ"},{"i":54254,"n":"שמואל","f":"זושא","b":"רב-שנת תר\"ל"},{"i":54255,"n":"שמואל","f":"יחיאל מיכל","b":"בנו - ר גצל."},{"i":54256,"n":"שמואל","f":"שמעון מיכל מפרשבורג","b":"סוכן הצארית אנא."},{"i":54257,"n":"שמואל (עמנואל) הנגיד ממצרים","f":"חנניה","k":"בעל מבוא התלמוד","b":"רב במצרים בדור שלפני הרמב\"ם. ולפי רוזניס נגיד במצרים-בשנת ה' - לאחר שהנגיד האחרון ממשפחת הרמב\"ם - ר דוד - עבר לדמשק, ור יוסף נגיד על מקומו אחריו. חיבר \"מבוא התלמוד\" אשר יוחס בטעות לר שמואל הנגיד מספרד."},{"i":54258,"n":"שמואל (שאמועל), יעקב מקלויזנבו","f":"צבי ממארוש","dt":"תשז","b":"פעיל ציוני בקלויזנבורג. הו\"ל שבועון \"האשכול\"-תרץ. עלה לארץ והתישב בתל אביב."},{"i":54259,"n":"שמואל אבא","f":"מנחם ידידיה","bt":"תרנב","dt":"תשב - יג אדר","b":"רב בזיכלין"},{"i":54260,"n":"שמואל אבא מזיכלין (זיכלינסקי)","f":"זליג מליוביטש","k":"אדמור מזיכלין","bt":"תקע","dt":"תרלט - כו אלול","b":"גדל אצל ר פישל מסטריקוב-שהיה לימים חותנו זקנו. חתן דודו-אחי אביו ר מרדכי מבודזנוב-נכד ר פישל מסטריקוב. תלמיד ר ליביש חריף צינץ מפלאצק, ר משה יהודה ליב מקוטנא בעל \"זית רענן\", ר יעקב האדמור מברזין, ור שמחה בונם מפשיסחא. אדמור בליוביטש אצל אביו, בודזנוב אצל חותנו, זיכלין-תרד, אזערקוב. התפרסם כבעל מופת, והיה מחלוקת כנגדו ונאסר בגלל הלשנה-תרה. מתורתו ב\"להב אש\"."},{"i":54261,"n":"שמואל אבומנצור הנגיד ממצרים","b":"נגיד במצרים-ד'תתף על מקום ר מרדכי בן אלהרביה, ור נתנאל אלנטע על מקומו אחריו."},{"i":54262,"n":"שמואל אביגדור הלוי מסערוצק","b":"רב בסערוצק. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":54263,"n":"שמואל אביגדור מאדרינופול","b":"חתן ר רפאל יעקב אברהם גירון מאדרינופול ותלמידו. חיבר פסקים וחדושים בכת\"י."},{"i":54264,"n":"שמואל אברהם מסלונים וירושלים","f":"בצלאל","k":"המחאנק (מבני ומכונן)","b":"מחכמי ירושלים."},{"i":54265,"n":"שמואל אהרן ממאציוב","dt":"תקנד - כד אלול","b":"רב במאציוב"},{"i":54266,"n":"שמואל אהרן מפולדא","dt":"תרב - ט אייר","b":"רב בפולדא"},{"i":54267,"n":"שמואל איזיק מדאשיב","bt":"תקכה","dt":"תקפז","b":"תלמיד ר נחמן מברסלב. חיבר ספרים - בכת\"י."},{"i":54268,"n":"שמואל איסר הכהן מוילנא","f":"אברהם","bt":"תקעב","dt":"תרנב - כ טבת","b":"חתן ר אליעזר דויגער-פרוזינר מוילקוביסק. מחכמי קלויז הגר\"א בוילנא. ראש ישיבת מייליס בוילנא-תריד על מקום ר שמואל שפירא כ-38 שנה. בנו ר אברהם צבי מדויג. נכדו - בן ציון כץ בעל \"מזקנים אתבונן\"."},{"i":54269,"n":"שמואל אליעזר בן יהודה אידלש","bt":"1520","dt":"ה'שצא 1631","bk":[["אוצרות מהרש\"א",""],["חדושים ממסכת י\"ט ומס’ יבמות",""],["חדושים ממסכת נדה",""],["חידושי אגדות",""],["חידושי הלכות",""],["חידושי מהרש\"א",""]]},{"i":54270,"n":"שמואל אליעזר מלודמיר","f":"אפרים נפתלי","b":"רב בלאדמיר-תט\"ו"},{"i":54271,"n":"שמואל אליקים משלוניקי","b":"דיין בשלוניקי-שמג."},{"i":54272,"n":"שמואל אריה","bt":"תרלה","dt":"תשי - א שבט","b":"רב בדובשיץ-תרס\"ה,סמיכוב-תרס\"ט,עלה לא\"י תרצ\"ט"},{"i":54273,"n":"שמואל אריה מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":54274,"n":"שמואל בכר אליה מרוסג'וק","f":"אליה","b":"משכיל מחכמי רוסג'וק-בולגריה, מורה בסופיה, הו\"ל \"איל אמיגו דיל פואיבלו\" ברוסג'וק ואח\"כ בבלגרד, ובסופיה."},{"i":54275,"n":"שמואל בכר סיניוריא הלוי מירושל","b":"מחכמי ירושלים-רע."},{"i":54276,"n":"שמואל בן יהושע זליג","bt":"1800","dt":"ה'תריח 1858","bk":[["מנחת שמואל",""]]},{"i":54277,"n":"שמואל בנימין מירושלים","dt":"תקלב - תשרי","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקף? בשליחות בכורדיסטן (לא מסתדר התאריך - אולי חכם אחר)."},{"i":54278,"n":"שמואל בנימין מפיליפופולי וירוש","f":"בנימין בכר שאול","bt":"תרלו","bp":"פיליפופולי","b":"תלמיד ר אליהו אלקלעי בפיליפופולי, עלה לירושלים, תלמיד \"דורש ציון\", ר מנחם בכר יצחק, חזר לפיליפופולי ועסק בחינוך. עסקן ציוני."},{"i":54279,"n":"שמואל בצלאל מליובאויטש","k":"הרשב\"ץ","bt":"תקפט","dt":"תרסה - יד סיון","b":"תלמיד הצמח צדק, ובנו ר שמואל מליובאויטש. למד עם ר שלום דובר ובנו ר יוסף יצחק מליובאויטש. ראש ה\"משפיעים\" בישיבת ליובאויטש."},{"i":54280,"n":"שמואל ברוך מירושלים - א","dt":"תקנא - ג תמוז","b":"מגדולי רבני ירושלים"},{"i":54281,"n":"שמואל ברוך מירושלים - ב","b":"מחכמי ירושלים-תק\"צ. בנו - ר חיים נסים ברוך מירושלים."},{"i":54282,"n":"שמואל ברוך מירושלים - ג","f":"חיים נסים ברוך","bt":"תקצט","bp":"ירושלים","dt":"תרסה - כו אלול","dp":"ירושלים","b":"חתן ר יעקב ספיר בעל \"אבן ספיר\". ממיסדי שכונת \"מאה שערים\" בירושלים."},{"i":54283,"n":"שמואל ברוך מסרייבו וירושלים","b":"רב בשאראי-בושנא,עלה לירושלים"},{"i":54284,"n":"שמואל גאון סורא","f":"חפני","k":"בעל חובת הדיינים","bp":"פאס?","b":"גאון סורא (997), על מקום ר צמח צדק. נכדו של רב כוהן צדק גאון פומפודיתא. חיבר ספרים רבים ורובם אבדו. חותנו של רב האי גאון. חיבר גם \"מבוא התלמוד\". יש אומרים שנולד בפאס."},{"i":54285,"n":"שמואל דוד מאיטליה","k":"בעל זוהר הרקיע -כת\"י","b":"מחכמי איטליה-שפג. חיבר סדר עבודה של כל ימות השנה בביהמ\"ק, זוהר הרקיע. חתנו - ר יהודה בן מיכה בן אהרן מפיסרו."},{"i":54286,"n":"שמואל דוד ממינסק","f":"צבי","dt":"תרלח - כט תשרי","dp":"מינסק","b":"אב\"ד בכמה קהלות."},{"i":54287,"n":"שמואל די, דניס דוד מוזס מברזיל","f":"משה בן שמואל","bp":"אנגליה","dt":"תרכא - חשון","b":"היגר לריו דה ז'נירו-ברזיל והתעשר. סייע לפרוטסטנים בברזיל להקים בית תפלה ועל כך תמכו באנגליה במתן זכויות ליהודים. בעל תואר בארון ממשלת פורטוגל. מקורב לקיסר ברזיל. מצאצאי ר שאול וייל, ולבקשתו חיבר צבי הירש אדלמן את הספר \"גדולת שאול\"."},{"i":54288,"n":"שמואל דמן עכו","b":"מקובל מחכמי עכו, מוזכר באגרת ר יצחק חילו משנת צג (1333) שפגש תלמיד שלו ביבנה, והראה לו ספרים עתקים בקבלה ובהם ספרו של שמאי ופרקי דרבי ישמעאל ועוד."},{"i":54289,"n":"שמואל דניאל מאזמיר - הנכד","b":"נכד ר שמואל דניאל בעל \"זקן שמואל\". מחכמי אזמיר. הו\"ל ספר זקנו - אזמיר תקיו."},{"i":54290,"n":"שמואל דניאל משלוניקי","b":"מגדולי חכמי שאלוניקי-ש\"צ"},{"i":54291,"n":"שמואל דניאל משלוניקי ואזמיר","k":"בעל זקן שמואל","bp":"שלוניקי","b":"מחכמי שלוניקי-תל-תק, עבר לאזמיר בזמן ר יוסף אישקאפה. נזכר אצל ר דוד קונפורטי. חיבר \"זקן שמואל\" על הבית יוסף, יצא לאור ע\"י ר מצליח מאיר מירושלים - מצאצאי המחבר - אזמיר תקטז. בנו - ר דניאל שמואל, ונכדו - ר שמואל דניאל השני מאזמיר הדפיס את ספרו \"זקן שמואל\" אזמיר תקיו."},{"i":54292,"n":"שמואל דרשן מקראקא","b":"דרשן,רב בקרקא-ת\"כ"},{"i":54293,"n":"שמואל הוראדנר מצפת","f":"אברהם","dt":"תקצז","dp":"צפת","b":"בשליחות קהלת וילנא להביא את כספי התרומות לצפת וירושלים-תקעט עם ר זלמן קלצקיר. נהרג ברעידת האדמה בצפת-תקצז."},{"i":54294,"n":"שמואל הכהן ביי ממצרים","dt":"שעז","dp":"מצרים","b":"ראש היהודים במצרים-שלא, ממלא מקום הג'יליבי על מקום ר יעקב חיים תלמיד הורד ממשמרתו, ור שלמה אלשקר על מקומו אחריו, וחזר אחרי שנהרג ר שמואל-שמג ור אבא אסכנדרי על מקומו אחריו. היה במחלוקת עם ר משה בן יעקב בירב, ואחיו ר יצחק בירב נידהו."},{"i":54295,"n":"שמואל הכהן הקראי מדמשק","b":"מחכמי הקראים בדמשק-שנות ה-ת'."},{"i":54296,"n":"שמואל הכהן מאיטליה","k":"בעל מתורגמן קטן","b":"רב ורופא באיטליה. חיבר \"מתורגמן קטן\" בעברית איטלקית ולטינית - בכת\"י."},{"i":54297,"n":"שמואל הכהן מאלגיר","bt":"תק","dt":"תקף - בערך","b":"רב באלגיר. חיבר הקדמות לספרים \"ימים אחדים\" ליוורנו תקן, \"נוה שלום\" ליוורנו תקסד. נזכר ברשימת הרבנים הנפטרים באלגיר."},{"i":54298,"n":"שמואל הכהן מאמדור","f":"יוסף מפיורדא","k":"בעל תשובת שמואל","dt":"תקלג - יז אייר","dp":"ראקוב","b":"נכד ר שמואל מפיורדא בעל \"בית שמואל\" על שו\"ע. רב באמדור פלך הורדנא, גליל מינסק-תקכג על מקום ר רפאל הכהן (שהיה מחותנו) וישב בתחילה במינסק ואח\"כ בראקוב (ודיינים אצלו ר משה בן צדוק, ר שלמה זלמן בן חיים, ר אליעזר בן מרדכי, ר מנחם מנדל - חתמו ב-טו אלול תקכד). ור גרשון חריף (ראש הישיבה) על מקומו אחריו. היה נכבד בעיני הגר\"א. אחיהם של ר יעקב אב\"ד לידא, ר נתן נטע אב\"ד קמניץ. בניו - ר אריה ליב-חתנו של ר רפאל הכהן מהמבורג, ר יחזקאל. חתנו - ר בצלאל מסלוצק. נכדו - ר רפאל המבורג הו\"ל את שו\"ת זקנו בשם \"מר שמואל\"."},{"i":54299,"n":"שמואל הכהן מארץ ישראל","f":"יוסף","b":"מחכמי ארץ ישראל בזמן הגאונים"},{"i":54300,"n":"שמואל הכהן מדבדו-מרוקו","b":"מחכמי דבדו-מרוקו-תרלד, חתם עם ר אהרן הכהן על שאלה מחכמי פאס."},{"i":54301,"n":"שמואל הכהן מדרמשטט","b":"רב בדרמשטט, היה מהמערערים על הגט מקליווא-תקכו."},{"i":54302,"n":"שמואל הכהן מוועליז","f":"צבי בן אלחנן","k":"בעל אות ברית","bt":"תרכה","bp":"זאגר","b":"למד רפואה והיה רופא בוועליז. פרסם מאמרים ב\"המליץ\", \"המאסף\", חיבר מאמר \"הרופא ע\"פ תורתנו הכתובה והמסורה\"."},{"i":54303,"n":"שמואל הכהן מחברון","b":"מחכמי חברון, בשנת תקד חתם על כתב שליחות ר אברהם גדיליה, בשנת תקכג על כתב שליחות ר חיים רחמים באג'יו ור יצחק זאבי. בשנת תקלב בשליחות באירופה ואמריקה, והיה בניופארט ודרש ביום התענית שהוכרז ע\"י הקונגרס בפילדפליה - לפני המהפכה. פגש את הכומר עזרא סטילס וענה לו על שאלותיו, בתקמח בשליחות באירופה. כתב שליחותו נדפס בספרדית, בחתימת רבני חברון ובהם החיד\"א שהיה חברו והזכירו בספריו."},{"i":54304,"n":"שמואל הכהן מטבריה","b":"מחכמי טבריה, חתן ר יצחק אלחדיב וחיבר הקדמה לספרו \"לשון הזהב\". בשליחות בפדובה. מחדושיו בספר \"לקוטי שושנים\" לר מרדכי גירונדי."},{"i":54305,"n":"שמואל הכהן מטבריה וירושלים","f":"שאול","b":"מחכמי טבריה, בשנת שנד חתום על תקנת המס."},{"i":54306,"n":"שמואל הכהן מטריפולי-לבנון","b":"רב בטריפולי-לבנון-שנות ה-ש' ובנו ר יוסף על מקומו אחריו. התכתב עם ר משה טרני מצפת."},{"i":54307,"n":"שמואל הכהן מירושלים","b":"דיין בירושלים. בשליחות במרוקו-תס. תשובה ממנו ב\"גנת ורדים\"."},{"i":54308,"n":"שמואל הכהן מליוורנו","f":"משה","b":"רב ומשורר בליוורנו. משיריו ב\"קול עוגב\". הגיה ספרים וביניהם \"זכות אבות\", \"עת זקנים\" ועוד. חברו של החיד\"א."},{"i":54309,"n":"שמואל הכהן מלכוביץ","f":"שמחה כהנא","b":"רב ומו\"צ בלחוויץ(=לעחיוויץ)-ווהלין-תרך. בנו - ר שמחה בורשטין מפראנפיל."},{"i":54310,"n":"שמואל הכהן ממגנצא","f":"אהרן","b":"מגדולי חכמי מגנצא-שנת ל'"},{"i":54311,"n":"שמואל הכהן ממרוקו","b":"מחכמי מרוקו-שנות ה-ת', שאל את היעב\"ץ בענין חזקה."},{"i":54312,"n":"שמואל הכהן מסלטוינה","b":"שו\"ב בסלטוינה-תרפט."},{"i":54313,"n":"שמואל הכהן מספרד","f":"יוסף","k":"בעל מנחת כהן","bt":"שך","dt":"שסא-ב","b":"תלמיד ר שלמה חושורטרוס. רב בחלב על מקום ר אברהם בן אשר, ור שמואל בן אברהם לניאדו על מקומו אחריו. משורר והתכתב בעניני שירה עם ר ישראל נג'ארה."},{"i":54314,"n":"שמואל הכהן מעכו","f":"אליעזר","b":"מחכמי עכו בשנת ד'תתקצד (1234) חתם על תקנת ר אברהם בן הרמבם."},{"i":54315,"n":"שמואל הכהן מפאס","f":"אברהם","k":"בעל משפטי שמואל","b":"רב בפאס. חיבר \"משפטי שמואל\"."},{"i":54316,"n":"שמואל הכהן מפילזן","dt":"תקסט","b":"חתן ר אלעזר לעוו-מינץ בעל שמן רוקח. רב בפילזן וקלאטטויא, נפטר צעיר וחותנו רב בראנספרג (מקום מושב הרבנות) על מקומו אחריו."},{"i":54317,"n":"שמואל הכהן מצרפת","f":"רבינו יהודה הכהן","b":"מגדולי הראשונים בחכמי צרפת-ד'תתק\"כ"},{"i":54318,"n":"שמואל הכהן מקהיר","b":"מחכמי קהיר, תושב בולאק-פרבר של קהיר. תשובה ממנו אצל חכמי דורו ובהם שות מהר\"ם גאביזון."},{"i":54319,"n":"שמואל הכהן מקושטא","f":"יוסף","b":"מדפיס בקושטא. הדפיס \"נר מצוה\"-שכז, ועוד."},{"i":54320,"n":"שמואל הכהן משלוניקי","b":"מחכמי שלוניקי-שץ, תלמיד ר שלמה ן מאיור."},{"i":54321,"n":"שמואל הלוי","f":"דוד","b":"מגדולי הראשונים-שנת ע'"},{"i":54322,"n":"שמואל הלוי","k":"בעל פירוש לתלמוד","b":"רב בזמן רב שכנא שר שלום, והיה מחלוקת ביניהם - כמבואר ב\"עצמות\" למהר\"י ן עזרא. כנראה חיבר פירוש לתלמוד."},{"i":54323,"n":"שמואל הלוי הרופא מירושלים","b":"רופא בירושלים בזמן פרעות אבן פארוך-שפה, ניסה לעזור לאחותו של ר אליעזר ארחא מחברון ונאסר על כך, שוחרר לבקשת השר מעזה שר שמואל היה רופאו. אחיו - ר יואל ור יעקב."},{"i":54324,"n":"שמואל הלוי הרופא מקוש-אדאסי","b":"רופא בקוש-אדאסי-ליד אזמיר-תקן."},{"i":54325,"n":"שמואל הלוי מאדרינופול","b":"רב באדרינופול - בדור שאחר הגירוש."},{"i":54326,"n":"שמואל הלוי מאוסטרהא","f":"חיים מאוסטרהא","k":"שמואל ר יקיר'ס","dt":"תקס - ד שבט","dp":"אוסטרהא","b":"מחכמי אוססטרהא וגבאי הח\"ק. חתן ר יקיר-מחשובי חסידי אוסטרהא, מ\"מ על מקום חותנו. הלך בבגד לבן בשבת כמנהג חסידים פרושים בימים ההם."},{"i":54327,"n":"שמואל הלוי מאלגיר","b":"ש\"ץ בביהכ\"נ של ר צמח בן הרשב\"ש באלגיר, שהזכירו בתשובה."},{"i":54328,"n":"שמואל הלוי מבגדד","f":"עלי הלוי","dt":"ד'תתקנה (1195)","b":"ראש ישיבת בגדד בזמן הרמב\"ם, והיה במחלוקת עמו. הנוסעים ר בנימין מטודילה ור פתחיה מרגנשבורג, שביקרו בבגדד, מתארים את גדלותו בתורה ובמדעים, ושידע את כל התלמוד בעל פה. כתב השגות על \"משנה תורה\" לרמב\"ם, והרמב\"ם השיב על השגותיו לאחד מתלמידיו. בתו היחידה היתה בקיאה בתלמוד ולימדה תורה לחבורים דרך חלון חדרה. חתנו ר זכריה בר ברכאל מחלאב היה אב\"ד בישיבת בגדד."},{"i":54329,"n":"שמואל הלוי מביאליסטוק","f":"יוסף","k":"בעל בגדי ישע","dt":"ה'תרה","b":"דומ\"צ בביאליסטוק-תק\"צ","bk":[["בגדי ישע [שו\"ת]",""]]},{"i":54330,"n":"שמואל הלוי מהלברשטט","f":"דוד","k":"בעל נחלת שבעה","bt":"שפד","dt":"תמא - טו תשרי","b":"תלמיד בעל הט\"ז, ר שבתי שעפטל הורביץ-בן השל\"ה. רב בהלברשטט, בומברג, שטיינבך. היה בחילופי שו\"ת עם ר יאיר בכרך בעל \"חוות יאיר\" שהשיג על ספרו ור שמואל השיב לו במהדורה בתרא."},{"i":54331,"n":"שמואל הלוי מהמדן-פרס","b":"רב בהמדן-שושן הבירה-תר\"נ"},{"i":54332,"n":"שמואל הלוי מוורמייזא","b":"מגדולי חכמי וורמייזא-שנת ר'"},{"i":54333,"n":"שמואל הלוי מטיסמניץ","f":"מרדכי סגל","b":"רב בטיסמניץ-תק-תקן, וחתנו ר מאיר בן יצחק חיות על מקומו אחריו."},{"i":54334,"n":"שמואל הלוי מירושלים","b":"דיין בירושלים, חתם עם ר משה סוזין בדבר שליחות ר אברהם שלמה זלמן אשכנזי."},{"i":54335,"n":"שמואל הלוי מלודמיר - אבי הט\"ז","k":"אבי הט\"ז","b":"רב-שנת ש\"ס. חתן ר יצחק בצלאלש אב\"ד לודמיר. גביר תלמיד חכם בלודמיר. בניו ר יצחק בעל \"חדושי מהר\"י הלוי\", ור דוד בעל הט\"ז."},{"i":54336,"n":"שמואל הלוי ממזריטש","f":"אברהם הלוי","dt":"תעט - כט טבת","b":"רב במזריטש, רישא."},{"i":54337,"n":"שמואל הלוי ממיינץ","dt":"תקעד - יח תשרי","b":"רב במיינץ"},{"i":54338,"n":"שמואל הלוי ממצרים","f":"סעדיה","b":"רב בקהיר, דיין בבית דינו של הרמב\"ם, וחתם עם הרמב\"ם על תקנת הקידושין, ועל פסקים נוספים."},{"i":54339,"n":"שמואל הלוי ממראקש","b":"מו\"ץ במראקש-תקיט עם ר אברהם קורקוס, ר יצחק חרוש, נזכר בשו\"ת ר אד\"א."},{"i":54340,"n":"שמואל הלוי מסופיה","b":"גביר בסופיה-שנות ה-ת'-תק'. נזכר ב\"שונה הלכות\" לר שלמה שלם."},{"i":54341,"n":"שמואל הלוי מספרד","f":"אשר","b":"מחכמי ברצלונה בזמן הרשב\"א, וחתם בתשובות הרשב\"א עם רבני ברצלונה."},{"i":54342,"n":"שמואל הלוי מסקול","f":"ישראל הלוי","b":"רב בסקאהל-ת\"ק"},{"i":54343,"n":"שמואל הלוי מפודהייץ","b":"רב בפדהייץ"},{"i":54344,"n":"שמואל הלוי מפוחוביץ","f":"יהודה מויסוקי","b":"רב בפוחוביץ."},{"i":54345,"n":"שמואל הלוי מפרג","f":"שמעון ברנדס","b":"מנהיג,מגדולי פרג-ת\"ך"},{"i":54346,"n":"שמואל הלוי מצפת","f":"משה","b":"מגדולי חכמי צפת-ש\"ל"},{"i":54347,"n":"שמואל הלוי מצפת","f":"עובדיה","b":"מחכמי צפת, בשנת תעד בשליחות בפיסא ואישר שם פסק דין של ר רפאל מילדולה. בשנת תעה היה בפירארה והתידד עם ר יצחק למפרונטי בעל \"פחד יצחק\". הסכים שם על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":54348,"n":"שמואל הלוי מצפת","b":"מחכמי צפת. מוזכר ב\"אמרי שפר\" לר נפתלי אשכנזי."},{"i":54349,"n":"שמואל הלוי מקושטא - ב","bt":"שע","bp":"קושטא","dt":"תלה - בערך","b":"תלמיד ר יוסף מטרני. מחכמי קושטא וראש ישיבה בקושטא, מתלמידיו ר יהודה רוזניס בעל \"משנה למלך\". רוב כתביו אבדו בשריפה הגדולה בקושטא-תך."},{"i":54350,"n":"שמואל הלוי מקושטא - הזקן","b":"תלמיד הרא\"ם. מחכמי קושטא, חתם-רפ על החזרת השתדלן ר שאלתיאל."},{"i":54351,"n":"שמואל הלוי מקושטא - הנכד","f":"משה","dt":"תץ","b":"נכד ר שמואל הלוי הזקן. אב\"ד איסור והיתר בקושטא-תע, ואח\"כ רב הכולל בקושטא ור אברהם בן חיים רוזניס על מקומו אחריו. חתם עם רבני קושטא-תעד על החרם נגד נחמיה חיון. חברו של ר יהודה רוזניס בעל \"משנה למלך\". נספד ע\"י ר יוסף דוד ב\"יקרא דשכבי\". תשובותיו בספרי חכמי דורו ובהם \"משנה למלך\", \"כהונת עולם\", \"דבר משה\". אחיו - ר יצחק הלוי-נפטר צעיר."},{"i":54352,"n":"שמואל הלוי מקראקא","b":"רב בקרקא-שנת ש'"},{"i":54353,"n":"שמואל הלוי מקרוטושין","k":"בעל דבר שמואל","b":"ראב\"ד בקארטשין-תק\"פ"},{"i":54354,"n":"שמואל הלוי מקשיבקה","b":"רב בקאשיבקה-תק\"ס"},{"i":54355,"n":"שמואל הלוי מרודוס ושלוניקי","bt":"רפ","bp":"שלוניקי","b":"תלמיד חבר לר יוסף טאיטצק. רב בשלוניקי, רודוס. הסכים על \"תפלה למשה\" לר משה אלמושנינו-שכג. השיב לר יוסף קארו."},{"i":54356,"n":"שמואל הלוי מרוהטשוב וחברון","f":"מרדכי סגל","b":"רב ברוהטשוב, מהקבוצה הראשונה של חסידי חבד בחברון ועמד בראשם, חתם על הסכם הכולל בשנת תרב. חתם-תקצד על כתב שליחות ר נתן עמרם."},{"i":54357,"n":"שמואל הלוי משלוניקי","f":"סעדי","k":"בעל איל דרייפוס אוטמ","bt":"תרכח","bp":"שלוניקי","b":"עורך עיתון אביו - \"לה איפוקה\" בשלוניקי, עבר לזמלין והו\"ל \"איל לוזירו\", פעל לשמירת שפת הלאדינו, ביקר בארץ. פרסם זכרונות אביו בעתון \"אקסיון\" - פאריס."},{"i":54358,"n":"שמואל הלוי רופא","k":"שמואל בן חכים הלוי","b":"מחכמי מצרים, עלה לירושלים ומוזכר בשות הרלבח אודות סכסוך שהיה לו. סבל בפרעות אבן פארוך בשנת שפה."},{"i":54359,"n":"שמואל המכיר מירושלים","b":"מחכמי ירושלים-רע."},{"i":54360,"n":"שמואל הנביא","dt":"כח, כט אייר ב' תתפב","bk":[["שמואל",""]]},{"i":54361,"n":"שמואל הנגיד ממצרים","f":"פלטיאל","b":"נגיד במצרים-ד'תשנה על מקום אביו."},{"i":54362,"n":"שמואל הנגיד מספרד","f":"יוסף","k":"בעל הסתפקות","bt":"ד'תשנג (933)","bp":"קורדובה-ספרד","dt":"ד'תתטז (1056)","dp":"גרנדה","b":"וזיר בגרנדה אצל המלך חבוס, ואח\"כ אצל בנו באדיס, מפקד הצבא, ומהחזיק ישיבות וחכמי תורה במדינות שונות. מחכמי ספרד, תלמיד ר חנוך, וניהל ויכוחים עם גדולי האיסלם, משורר, ומחבר ספרים. התכתב עם גדולי דורו ובהם רב האי גאון, ר חושיאל ור נסים מקירואן, ורב חזקיה ראש הגולה בבבל. חיבר פירוש לתלמוד, שו\"ת, \"הלכתא גבירתא\", ועוד. יש המיחסים לו את מבוא התלמוד אולם מחברו הוא ר שמואל בר חנניה הנגיד ממצרים שחי מאה שנה אחריו. בנו ר יוסף שנהרג עק\"ה."},{"i":54363,"n":"שמואל הקטן מקובנא","f":"יצחק","k":"בעל מגילת קובנא","bp":"וילנא","b":"מגיד וסופר הקהלה בקובנא, אחר גירוש קובנא עבר לויליאמפולי(=סלובודקה)-תקכג וכיהן כגבאי ונאמן הקהל, וגם אשתו עיתה גבאית לנשים. חיבר \"מגילת קובנא\" - לרגל שיבת יהודי קובנא לעירם. הסכים על \"באר אברהם\" לר אברהם דובער בן שלמה מאורשה. אשתו - חנה - נתמנתה בתור גבאית לנשים בויליאמפול-תקלב. בנו - ר יוסף."},{"i":54364,"n":"שמואל הקראי","f":"דוד","b":"מחכמי הקראים, נסע לארץ ישראל-תב ועבר בקושטא, מצרים, וכתב על כך."},{"i":54365,"n":"שמואל הקראי ממצרים","f":"נחמן","b":"מחכמי הקראים במצרים. חיבר ספר על קורות היהודים במצרים בשנת רפד."},{"i":54366,"n":"שמואל הרופא מלובלין","f":"מתתיהו","b":"רופא מחכמי לובלין-שנות הש'. הסכים על \"לוח החיים\" עם ר שלמה לוריא הרופא מלובלין."},{"i":54367,"n":"שמואל הרופא מלובלין","f":"יעקב","dt":"תטז - סוכות","dp":"לובלין","b":"רופא מחכמי לובלין. נהרג עק\"ה וב\"צמח צדק\" מביא את הדיון על התרת אשתו (גיטל בת הקדוש ר יעקב) מעגינותה. נזכר גם ב\"חסד שמואל\"."},{"i":54368,"n":"שמואל השלישי","f":"הושענא","b":"מחכמי עזה בזמן הגאונים."},{"i":54369,"n":"שמואל זנוויל בער חריף מאוסטריך","dt":"תקצז - כט תמוז","b":"חריף,רב בשיטוויסק,אוסטריך"},{"i":54370,"n":"שמואל זנוויל סגל","b":"מחדושיו ב\"כתונת פסים\"."},{"i":54371,"n":"שמואל זנוויל סגל מלבוב","f":"יעקב","b":"דיין בלבוב, חתם-תי עם ר נתן בן אליעזר שנבורג, חתם-תיח עם ר אברהם גרויפין."},{"i":54372,"n":"שמואל זנויל מביאליסטוק","f":"אריה ליב","b":"רב בביאליסטוק-תק\"ס"},{"i":54373,"n":"שמואל זנויל מברנדבורג וברלין","b":"אב\"ד שטרעליטץ, דיין בברלין-תקלח אל ר צבי הירש מלונדון וברלין."},{"i":54374,"n":"שמואל זנויל מגלוגוב","b":"מחכמי גלוגוב. תשובה אליו ב\"משיב כהלכה\"."},{"i":54375,"n":"שמואל זנויל מוילנא","f":"פסח גרמייזא","dt":"תקעח - אחרי","b":"גביר ופרנס בוילנא. חתם שני על תקנות ח\"ק-תקסו. נדב ביכ\"נ יחד עם גיסו ר דוד לוינסון - ונקרא \"זאבל'ס שול\". נזכר בספר דודו-אחי אמו ר יחיאל מיכל בן יהודה ליב מקלואריא - \"דרך המלך\"."},{"i":54376,"n":"שמואל זנויל מזוולוב","f":"מרדכי פעשי'ס מנריוב","b":"תלמיד ר יחיאל מיכל מזלוטשוב. אב\"ד זוואלוב-תקס. ר אורי מסטרליסק אמר עליו \"הוא מתפלל יפה ממני\". בנו ר יהודה צבי ברנדוין האדמור מסטרטין."},{"i":54377,"n":"שמואל זנויל מזולקוא","f":"יצחק","b":"חתן ר נפתלי כץ מלובלין. פרנס בזולקוא. בנו - ר יצחק מזולקוא ונכדו - ר נחמן מהורודנקא. גיסו - ר אברהם אבלי-אב\"ד זולקוא."},{"i":54378,"n":"שמואל זנויל מזנטא","b":"רב בזענטא-תר\"י"},{"i":54379,"n":"שמואל זנויל מחאדזיטץ","f":"משה יהודה ליב","b":"דיין בחאדזיטש(=חאדזייש)-תקסט, אצל ר גדליה ליפשיץ, וחתם-תקסט עמו ועם הדיין ר יצחק איצק בן משה."},{"i":54380,"n":"שמואל זנויל מלובלין ומיינץ","f":"חנוך מלובלין","k":"בעל דברי שמואל","b":"רב במיינץ-ת\"ך"},{"i":54381,"n":"שמואל זנויל מנעשוויז","b":"רב בנעשוויז-ש\"פ"},{"i":54382,"n":"שמואל זנויל מקולבסוב","b":"רב בקולבסוב-תרנח"},{"i":54383,"n":"שמואל זנויל מקראקא","b":"חתן ר הירש ר אייזיקס מקראקא. מחדושיו ב\"כתונת פסים\", הגדה \"חלוקא דרבנן\"-תנה. בנו - ר משה-נכד החלקת מחוקק (איך?) שהו\"ל שפתי כהן על התורה-ואנזבק תן."},{"i":54384,"n":"שמואל זנויל משטרליץ","f":"אברהם צבי","b":"רב בשטרליץ-תקכ\"א"},{"i":54385,"n":"שמואל זנויל סגל מלבוב","b":"חתם על תקנת קהלת זולקוא בועד זווירז."},{"i":54386,"n":"שמואל חיים אסתרוק מקושטא","f":"משה חיים","k":"בעל שמן המשחה","bt":"תקך - בערך","dt":"תרב-יב - ו חשון","dp":"ירושלים","b":"תלמיד ר רפאל יעקב אסא, ר אליהו פאלומבו, ר מנחם אשכנזי, ראש ישיבה בבלאט-קושטא, דיין אצל ר מיכאל אשכנזי עם ר משה קצינו (בעניני גיטין), היה דיין גם עם מהר\"ם מירגונטו ור אליהו בן יעקב, ועם ר אליהו פאלומבו ור עובדיה נתן. חכם באשי בקושטא-תקצז (ולפי רוזניס אולי - תקעז, על מקום ר אברהם הלוי), הודח מתפקידו ע\"י התורכים בגלל שהיה נתין אוסטרי, ור משה פריסקו השני על מקומו אחריו.ומאז כיהן כאב\"ד, עלה לירושלים-תרב. מתשובותיו ב\"שמן המשחה\"."},{"i":54387,"n":"שמואל חיים מקובסדורף","b":"רב בקובסדורף-תק\"מ"},{"i":54388,"n":"שמואל חיים מקוסוב","f":"יעקב משה","dt":"תרכו","b":"רב בקוסוב, רדאוץ - ויסד שם תלמוד תורה. נפטר ללא ילדים."},{"i":54389,"n":"שמואל חסיד מראסיין","f":"ברוך","k":"בעל תורת חסידים","bt":"תקיא","bp":"גורז'ד-פלך קובנא","dt":"תקפד - יט תמוז","dp":"ראסיין","b":"מצאצאי ר ברוך בנדיט פאדקעווער. מתלמידי הגר\"א. חתן ר זאב וולף מראסיין-בן ר שמואל מפלונגיאן. אביו היה צדיק וחסיד שהתענה 62 שנה ולא אכל דברים היוצאים מן החי. ר שמואל היה אחד מהחבורה של שלשה רבנים שנקראה \"אגודת חסידים\" ובה גם ר משה מטלז, ור מרדכי מפוקרוי - שבמשך 15 שנה עשו אגודה אחת להתנזר מכל הנאות שבעולם ולמדו תורה בחסידות ובפרישות. מתורתם בספר \"זכרון יעקב\" לנכדו ר יעקב בנדטמן בשם \"תורת חסידים\". נהג לנסוע אל הגר\"א פעמיים בשנה והגר\"א כינהו \"החסיד מזאמוט\". חתנו - ר זאב וולף מראסיין. בניו ר יהודה אביו של ר יעקב בנדטמן, ר שלמה זלמן רב מטעם בראסיין, ר ברוך בנדט משאוולי."},{"i":54390,"n":"שמואל חעלימר מאוסטרהא","f":"צבי הירש","dt":"תקנח - י טבת","dp":"אוסטרהא","b":"חתן ר מרדכי פ\"פ. פרנס באוסטרהא-תקלד יחד עם ר יקותיאל זוסמן. מבניו: ר יוסף יאסקי מאוסטרהא, ר מרדכי הירש מאוסטרהא."},{"i":54391,"n":"שמואל יהודה מויטקוב","b":"רב בויטקוב"},{"i":54392,"n":"שמואל יהודה מושאבאק מירושלים","dt":"תקמב - כה ניסן","dp":"ירושלים","b":"מחכמי ירושלים. אשתו - איסטיריא די ציון נקברה לצדו."},{"i":54393,"n":"שמואל יהודה מצליח הכהן מאיטליה","b":"רב במודנא-איטליה-תק, ומלמד לתלמידים בבוסניו, חיבר דרושים וכתבים שונים בכת\"י."},{"i":54394,"n":"שמואל יהודה'ס מוילנא","f":"ישראל חיים רי\"פ","k":"שמואל קלאצקי","dt":"תקצז - כד אד\"א","dp":"וילנא","b":"חתן ר יהודה קלאצעס, ובזיוו\"ש חתן הגביר ר אהרן מינץ ממזריטש. גביר מחכמי וילנא. פרנס קהילת וילנא - אחד מ\"שלשה עמודי וילנא\". בניו: ר דוד-חתן ר יצחק ר זלמן ר אורי'ס, ר זיסל-חתן ר יעקב יעקיל פריידעס משקלוב, ר השל, ר חיים-חתן ר יחזקאל לנדא, ר אריה ליב."},{"i":54395,"n":"שמואל יואל היללוביטש מדובנא","f":"ליבש מדובנא","b":"זקנו של ר שאול דוד פריזר (מדפיס מגילת היוחסין). חתן ר שמשון פערטיל מזיטומיר."},{"i":54396,"n":"שמואל יוסף מדזיקוב","b":"רב בדזיקוב."},{"i":54397,"n":"שמואל יוסף משלוניקי","bt":"תקסא","dt":"תרמה","dp":"שלוניקי","b":"רב הכולל בשלוניקי לצדו של ר שמואל ארדיטי. אחיו של ר דוד יוסף."},{"i":54398,"n":"שמואל יחיאל מבוטושאן","f":"דן מראדויל","k":"אדמור מראדויל","dt":"תרכב - ו ניסן","b":"רב בבאטושן. נינו של המגיד מזלוטשוב. חתן ר יוסף מאוסטילא (נסחיז), ובזיוו\"ש חתן ר יוסף מטורטשין (לובלין). חתונתו הראשונה נחשבה למפוארת בתולדות החסידות ונקראה \"החתונה מאוסטילא\"."},{"i":54399,"n":"שמואל יעקב קופל הכהן","b":"אב:ד איוואנגראד. הסכים על תהלות חיים לר חיים פלטרוביץ. (ראה גם: שמואל יעקב ברמסון בעל שמשא דשמואל)"},{"i":54400,"n":"שמואל יצחק משלוניקי - א","f":"יצחק","b":"דיין בשלוניקי-שפ."},{"i":54401,"n":"שמואל ישראל מטיטואן-מרוקו","b":"מו\"ץ בטיטואן-מרוקו, חתם-תרמא על פס\"ד. חתנו - רפאל חיים משה ן נעים."},{"i":54402,"n":"שמואל כץ מזולקוא","f":"מנחם מנדל","b":"מחכמי זולקוא, חתם-תעו על תקנת הקהלה."},{"i":54403,"n":"שמואל ליב מאורמין","b":"רב באורמין-תקע\"ח"},{"i":54404,"n":"שמואל מ"},{"i":54405,"n":"שמואל מאוזירן","b":"שו\"ב באוזירן-תרמא."},{"i":54406,"n":"שמואל מאוטיאן וקופישוק","f":"חיים","dt":"תקפב","b":"רב בסויאדושץ, אוטיאן, קופישוק."},{"i":54407,"n":"שמואל מאונסדורף","f":"מרדכי מהעלישוי","b":"גביר מראשי קהלת אונסדורף יחד עם ר משה סגל שלזינגר."},{"i":54408,"n":"שמואל מאוסטרהא","f":"יעקב מאוסטרהא","k":"ר שמואל ר יעקבס","b":"גביר ומנהיג באוסטרהא. בניו ר יוזפא אוסטרר, \"ר מרדכי ר יעקב ר שמואלס\" (כך כונה) מאוסטרהא."},{"i":54409,"n":"שמואל מאוסטרהא","f":"יהודה ליב מקרמניץ","dt":"תקכג - אחרי","b":"חתן ר נתן נטע מרגליות שפירא. מחכמי קרמניץ, אוסטרהא-תקיב. חתם ראשון על תקנה-תקיט. כנראה עזב אחרי תקכב - לא נודע לאן."},{"i":54410,"n":"שמואל מאוסטרוב","f":"פיבש","b":"רב בפרנקפורט-שעו, פשמישל, אוסטרוב על מקום אביו."},{"i":54411,"n":"שמואל מאיזנשטט ופיריישורף","b":"מקובל,רב באייזנשטט-פריישדורף"},{"i":54412,"n":"שמואל מאייברא","b":"מגדולי בעלי התוספות,מרביץ תורה,באייברא(צרפת)-ד'תתק\"ס,מגדולי נורמנדיה,מחבר תוספות אייברא"},{"i":54413,"n":"שמואל מאיר מהענינגן","b":"רב בהענינגן, מכתב המלצה ממנו-תר לר אריה ליב גינצבורג (נכד השאגת אריה)."},{"i":54414,"n":"שמואל מאיר מקראקא","b":"מחכמי קראקא. תשובה אליו ב\"שם עולם\"-תרלג."},{"i":54415,"n":"שמואל מאלגיר","f":"משה מרדכי","b":"רב בקצמטינא. נזכר ב\"יכין ובועז\". חברו של ר שמואל בן משה אטראני."},{"i":54416,"n":"שמואל מאלטונא","b":"מחכמי אלטונה-ת\"ס"},{"i":54417,"n":"שמואל מאסאד","b":"אב\"ד אסאד, חתם עם חכמי אויבן-תקעט."},{"i":54418,"n":"שמואל מאפטא","b":"רב באפטא-תק\"פ"},{"i":54419,"n":"שמואל מאפטא","f":"נפתלי הירץ","bt":"תקיד","dt":"תר - יז אב","b":"רב באפטא-תקע ובווארקי, והיה מגדולי הרבנים בדורו."},{"i":54420,"n":"שמואל מארץ ישראל","f":"יעקב","b":"מחכמי ארץ ישראל, בשנת רסט חתם על תקנת המס."},{"i":54421,"n":"שמואל מארץ ישראל","f":"שמשון משאנץ","b":"עלה בשנת ד'תתקע לפני עלית 300 בעלי התוספות, כנראה הוא בנו של הר\"ש משאנץ שעלה יחד עם ר יונתן מלוניל כשנה לפני עלית הר\"ש עצמו."},{"i":54422,"n":"שמואל מארץ ישראל","f":"ישעיה סגל מפלאצק","dt":"תקנט - כז אד\"ב","b":"עלה לארץ - לפני תקמד. בעל התניא מכנהו \"המפלג בתורה וביראה...\"."},{"i":54423,"n":"שמואל מארץ ישראל","f":"יוסף ממינסק","b":"תלמיד ר מרדכי מלכוביץ. עלה לארץ-תקצח. חתם על כתב המינוי לר אברהם מסלונים להיות הממונה על איסוף הכספים לכולל."},{"i":54424,"n":"שמואל מאשכנז","f":"מנחם","b":"מגדולי חכמי אשכנז,מרביץ תורה,גדולי הפוסקים-ד'תתק\"צ"},{"i":54425,"n":"שמואל מאשכנז","f":"נטרונאי","k":"שב\"ט","bt":"ד'תתפ","dt":"ד'תתקנז","b":"חתן הראב\"ן. נהרג עק\"ה. מגדולי חכמי אשכנז, מבעלי התוספות, פוסק, מרביץ תורה בבון, מגנצא, קולוניא, רגנשבורג. בנו - ר מרדכי מקולוניה."},{"i":54426,"n":"שמואל מאשכנז וצרפת","f":"רבינו קלונימוס הזקן","k":"בעל ספר שקד","bt":"ד'תתעה","b":"ראשון לחסידי ומקובלי אשכנז, עסק בקבלה שימושית, מגדולי חכמי דורו באשכנז וצרפת, מרביץ תורה בשפירא. חותנו של ר משה הדרשן. חיבר את שיר היחוד"},{"i":54427,"n":"שמואל מבונבורק","f":"רבינו ברוך ממגנצא","k":"בעל ספר הפרדס","b":"מגדולי חכמי אשכנז הראשונים,פוסק,פייטן,מרביץ תורה בבמברג-ד'תתק\"נ"},{"i":54428,"n":"שמואל מברגסאס","b":"דומ\"צ בברגסאס-תר\"י"},{"i":54429,"n":"שמואל מברודי","dt":"תקלח - יד ניסן","b":"גדול בנגלה ונסתר,דיין בברודי"},{"i":54430,"n":"שמואל מברנוב","f":"אביגדור","b":"רב בברנוב. תשובה אליו ב\"דברי חיים\"."},{"i":54431,"n":"שמואל מדוברומיל","b":"רב בדוברומיל-תרנא."},{"i":54432,"n":"שמואל מדינוב","b":"רב בדינוב"},{"i":54433,"n":"שמואל מדלהינוב וירושלים","f":"יהושע זליג מדלהינוב","k":"בעל מנחת שמואל","dt":"תריח - ג אב","dp":"ירושלים","b":"רב בדלהינוב ואיליה(=אילייע), עלה לירושלים. חיבר \"מנחת שמואל\" וילנא תרב, ועוד. חתניו - ר אליהו דייכס ור אליהו סטרלצר וקרא להם \"אליהו רבא\" ו\"אליהו זוטא\". פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. הסכים על \"בית נתן\" ירושלים תריד."},{"i":54434,"n":"שמואל מדנציג והפנברוק","k":"בעל נחמות ציון","b":"רב בהפנברוק-ת\"ק. זקנו של החיי אדם."},{"i":54435,"n":"שמואל מדריליטש","dt":"תרם - ג אדר","b":"תלמיד ר מאיר מאפטא."},{"i":54436,"n":"שמואל מהאסאסא","b":"דומ\"צ בהאסאסא-ת\"ר"},{"i":54437,"n":"שמואל מהורדנא","f":"אליעזר","dt":"תקצה - כה חשון","dp":"הורדנא","b":"מו\"צ בהורדנא."},{"i":54438,"n":"שמואל מהעליטש","b":"רב בהעליטש-ת\"ר"},{"i":54439,"n":"שמואל מואלקוניק ומינסק","f":"חיים","b":"תלמיד ר מנחם אליעזר בעל יעיר קינו. אב\"ד ואלקוניק, מו\"ץ במינסק."},{"i":54440,"n":"שמואל מוארבוי","b":"רב בווארבוי-תקע\"ב"},{"i":54441,"n":"שמואל מוארשא וירושלים","dt":"תרט - כ אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":54442,"n":"שמואל מוורדון-צרפת","b":"מגדולי הראשונים בחכמי צרפת,מבעלי התוספות,מרביץ תורה בוורדון-ד'תתק\"נ"},{"i":54443,"n":"שמואל מוידיסלוב ופיורדא","f":"אור שרגא פיבוש","k":"בעל בית שמואל","dt":"תנד","b":"חתן ר אריה ליב מקראקא (ר ליב דער הויכער-הגבוה). מגדולי הפוסקים בדורות האחרונים, רב בויידיסלב-תמד, מגיד בלבוב, רב בשידלוב, פיורדא-תנא. הסכים על \"נחלת שבעה\", \"באר היטב\"-זולקוא תקב. נזכר ב\"אדני פז\", \"עבודת הגרשוני\". בנו - ר יוסף. (ואינו בעל בית שמואל האחרון)"},{"i":54444,"n":"שמואל מוילנא","f":"יצחק איזיק מקרוז' וו","b":"חברם של ר חיים מוולוזין, ור יצחק מאיועניץ. עבר לוילנא עם בנו ר יצחק מעתיק בית הלל."},{"i":54445,"n":"שמואל מוילנא","f":"אביגדור חריף מרוזנוי","bt":"תצב","dt":"תקנא - כא טבת","dp":"וילנא","b":"תלמיד קרובו ר אלעזר מקראז. חתן הגביר ר יהודה ספרא ודיינא מוילנא=היסו\"ד, ובזיוו\"ש חתן ר חיים יהודה אריה איטינגא מלבוב בעל \"דברי יהודה\" או ר יהודה אריה מויטבסק בעל \"דברי אריה\" (יש בלבול בין שני חתניו של ר שמחה רפפורט). אב\"ד האחרון בוילנא-תקי-תקלח, ורב גליל סמארגון - בזמן הגר\"א. גבאי וילנא החליטו להעבירו מתפקידו לאחר פטירת אשתו-בת היסו\"ד והדבר גם למחלוקת גדולה שנמשכה מתקכז עד לפטירתו ומאז בוטלה כהונת אב\"ד וילנא ואבן הונחה על מקום הרב בביהכ\"נ כדי שלא ישב אדם שם (בראש מתנגדיו היה ר אברהם אבלי בן זאב וולף ובראש תומכיו היה ר שמעון בן זאב וולף - הגר\"א שהיה מעורב בשלב מסוים במחלוקת נאסר על רקע זה). בשנותיו האחרונות היה רב בקניגסברג על מקום בעל ה\"פרדס\", אך לא ויתר על רבנות וילנא. חיבר \"הדרת זקנים\" בכת\"י. חתנו - שהיה בן חורגו - ר ברוך מרדכי איטינגא מבוברויסק והחזיק את כתביו. בנו אליעזר נפטר צעיר. חתנו - ר ליפא איוועניצער."},{"i":54446,"n":"שמואל מוילנא","f":"משה","b":"שליח קהלת וילנא להכתרת המלך בקראקא-שצב יחד עם ר יעקב אליעזר בן משה ליזרס."},{"i":54447,"n":"שמואל מוילנא","f":"מאיר","b":"רב בוילנא, חתם-תמד על פסק דין עם ר יוסף בן יעקב, ר אהרן בן אברהם הלי הער, ר אריה לבי בן שמחה לבית אהרן."},{"i":54448,"n":"שמואל מוילנא","f":"צבי","dt":"תקך - כד שבט","dp":"וילנא","b":"מראשי קהלת וילנא."},{"i":54449,"n":"שמואל מוילנא","f":"יוסף","dt":"תקלט - יד טבת","dp":"וילנא","b":"מחכמי וילנא."},{"i":54450,"n":"שמואל מוילנא","f":"ברוך","dt":"תקסה - כה אד\"ב","dp":"וילנא","b":"מחכמי וילנא."},{"i":54451,"n":"שמואל מוילנא וירושלים","f":"שבתי","dt":"תקצט - יא אייר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":54452,"n":"שמואל מוילנא וירושלים","dt":"תרח - כ כסלו","dp":"ירושלים","b":"חתן ר עזריאל מוילנא. מחכמי ירושלים."},{"i":54453,"n":"שמואל מוינוטה-ליטא","f":"אליעזר","dt":"תרכו","b":"רב בוינוטה(=ואינוטה) ור בנימין ליפשיץ על מקומו אחריו."},{"i":54454,"n":"שמואל מויסלוביץ","b":"רב בוויסלוביץ-ת\"מ"},{"i":54455,"n":"שמואל מוירונה","f":"אלעזר מוירונה","b":"מגדולי חכמי איטליה בוירונה-שנת כ'"},{"i":54456,"n":"שמואל מזברז","f":"יצחק","b":"רב בזברז-תקצז"},{"i":54457,"n":"שמואל מזולקוא","b":"ראב\"ד בלבוב-תעז, חתם-תצט על תקנה."},{"i":54458,"n":"שמואל מזולקוא","f":"ר\"י פישלש","b":"מחכמי זולקוא, חתם-תסה על תקנת הקהלה."},{"i":54459,"n":"שמואל מזולקוא ולבוב","b":"ראב\"ד ור\"מ בלבוב חוץ לעיר. חתם-תעז עם ר אברהם גרויפין ור יהושע פאלק שור, חתם-תפח עם ר חיים יהודה ליב איטינגא, חתם-תקד עם ר אריה ליב רפפורט ור ישעיה קיקניש."},{"i":54460,"n":"שמואל מזליחוב","f":"אברהם","b":"רב-שנת ת\"ר"},{"i":54461,"n":"שמואל מזמיגראד","f":"אריה ליב מטרניגרד","b":"חתן ר משה פרנס. רב בטרניגרד-ת\"ק בנו ר יהושע השל מאפטא."},{"i":54462,"n":"שמואל מזסקוביץ","dt":"תקנב - ד ניסן","dp":"זסקוביץ","b":"חתן ר שמעון הלוי הורביץ. אב\"ד זסקוביץ-תקלב. נכדו - ר שמואל שטרשון - הרש\"ש."},{"i":54463,"n":"שמואל מזעמלין","b":"רב בזעמלין-תק\"צ"},{"i":54464,"n":"שמואל מחודרוב","b":"רב בחודרוב. תשובה אליו בשו\"מ."},{"i":54465,"n":"שמואל מחעלמא","b":"רב בחעלמא-תצ\"ח"},{"i":54466,"n":"שמואל מחרסקוב","b":"מו\"צ בחרסקוב, עלה לצפת וכיהן כדיין-תרמד, חתם עם ר זיידא קלינגר, ר דוד באבד."},{"i":54467,"n":"שמואל מטבריה","f":"יהודה","dt":"שלו","b":"נהרג עק\"ה, רב בכפר ענן סמוך לטבריה-שלו, נרצח בחזרה מהשתטחות על קברי צדיקים ומערת אליהו."},{"i":54468,"n":"שמואל מטלז","b":"מו\"צ בטלז-תק\"ע"},{"i":54469,"n":"שמואל מטריקאלה","f":"יוסף","b":"רב בטריקאלה-שצג."},{"i":54470,"n":"שמואל מיאנינה וירושלים","f":"שלמה","k":"בעל יריעות שלמה","b":"מחכמי יאנינה-יון, עלה לירושלים. חיבר \"יריעות שלמה\" לזכר בנו-תרסט."},{"i":54471,"n":"שמואל מיאסי","k":"ר' שמואל מוורניווקה","dt":"תרד - יא אייר","b":"רב ביאס"},{"i":54472,"n":"שמואל מיימוני ממצרים","f":"שלמה בן דוד","b":"מחכמי מצרים, נכד הרמב\"ם, אחיו של ר אברהם. נזכר בתקנות חכמי קנדיא כנגיד, וכן אצל ר יוסף בן תנחום הירושלמי שכתב בשיר על ר שמואל ראש הקהילות."},{"i":54473,"n":"שמואל מירושלים","b":"רב-שנת ש\"י,נשיא בירושלים"},{"i":54474,"n":"שמואל מירושלים","f":"יוסף","k":"בעל עולת תמיד?","b":"מחכמי ירושלים ודיין, מוזכר אצל ר משולם מוולטרא, יש ר שמואל בן יוסף שחיבר ספר \"עולת תמיד\" אמשטרדם תמא, ואולי שניהם זהים."},{"i":54475,"n":"שמואל מירושלים","f":"מרדכי","b":"מחכמי ירושלים בשנת רטז וחתם אז על כתב שליחות ר אברהם הלוי. בשנים רכז-רכח היה חבר בבית הדין."},{"i":54476,"n":"שמואל מירושלים","f":"אליעזר","k":"בעל דרכי נועם","b":"מחכמי ארץ ישראל, בשנת שנד חתם על תקנת המס, יש רב באותו שם שחיבר \"דרכי נועם\" קניגסברג תקכד."},{"i":54477,"n":"שמואל מירושלים","f":"הלל","b":"מחכמי ירושלים-רע."},{"i":54478,"n":"שמואל מירושלים","f":"חלפתא","b":"רב בירושלים-שנות ה-ר'-ש'."},{"i":54479,"n":"שמואל מכפר האסואסו","b":"רב בכפר האסואסו בתחילת המאה ה-19. נזכר ב\"מראה יחזקאל\"."},{"i":54480,"n":"שמואל מכפר ענן","f":"יהודה","b":"רב בכפר ענן(-ליד טבריה)- ומלמד תינוקות-שלו."},{"i":54481,"n":"שמואל מלבוב","f":"אליעזר","dt":"תט - כו טבת","dp":"לבוב","b":"ר\"מ בכמה קהלות, מרביץ תורה בלבוב."},{"i":54482,"n":"שמואל מלבוב","f":"חיים","dt":"תעב - ד אב","dp":"לבוב","b":"דרשן, מרביץ תורה בלבוב."},{"i":54483,"n":"שמואל מלבוב","f":"יהודה","dt":"תכד - ח אייר","dp":"לבוב","b":"מראשי קהלת לבוב. נהרג עק\"ה."},{"i":54484,"n":"שמואל מלבוב","b":"חתם-תן על רבני לבוב על תקנות קהלת זולקוא בקוליקוב."},{"i":54485,"n":"שמואל מלבוב","f":"הירש ר פישלש","b":"חתם-תסד על תקנת קהלת זולקוא, ועל בחירת ראשי הקהלה-תנט."},{"i":54486,"n":"שמואל מלובלין","dt":"תסב - כט סיון","b":"רב בלובלין"},{"i":54487,"n":"שמואל מלובלין","f":"יוסף יאסקה מלובלין","k":"בעל לחם רב","b":"מחכמי לובלין, רב בגניזין, עבר להוציפלוץ, רב בבומסלא-שפ."},{"i":54488,"n":"שמואל מלובלין","f":"ישראל איסר בן שמשון","dt":"תמב - כט סיון","dp":"לובלין","b":"ראש גבאי צדקה ומחכמי לובלין."},{"i":54489,"n":"שמואל מלוקטש","b":"רב בלוקאטש(=לוקטש), ניצל מהשואה והגיע לשנחאי. חתם שם-תשא עם כמה רבנים על מכתב לר ראובן כץ מפתח תקוה."},{"i":54490,"n":"שמואל מליסבק","b":"תלמיד ר מרדכי יוסף מאיזביצא, ר שמחה בונם מפשיסחא, מראשוני חסידי ר מנחם מנדל מקוצק ועזב את קוצק יחד עם רבו. השפיע רבות על חבורת החסידים בקוצק ובאזיביצא ורצו למנותו אדמור אך סירב."},{"i":54491,"n":"שמואל מליסיבוק","b":"רב בליסיבוק-תר\"ל"},{"i":54492,"n":"שמואל מלנצבורג","f":"עזריאל","k":"בעל חגורת שמואל","b":"חיבר \"חגורת שמואל\" פפד\"א תקלב.."},{"i":54493,"n":"שמואל ממגנצא","f":"ברוך","b":"מגדולי הראשונים,מרביץ תורה במגנצא-ד'תתק\"ע"},{"i":54494,"n":"שמואל ממנהיים","b":"דיין במנהיים-תק\"מ"},{"i":54495,"n":"שמואל ממנטוולא","f":"לוי","b":"מגדולי הראשונים,מרביץ תורה במנטוולא-ד'תתק\"ס"},{"i":54496,"n":"שמואל ממצרים","f":"דוד","b":"מחכמי מצרים בדור הרמב\"ם. מצאצאי הגאון אהרן בן מאיר."},{"i":54497,"n":"שמואל מנארינסק וסטולין","dt":"תרמ","b":"רב בנארינסק,קפיטקוויטש,סטאלין"},{"i":54498,"n":"שמואל מנוואריא","f":"יהודה ליב","b":"תלמיד ר מרדכי מבויסק בעל \"גדולת מרדכי\", המזכירו בספרו. רבה הראשון של נווארא(=פרידריכשטט)."},{"i":54499,"n":"שמואל מנעשוויז","b":"רב בנעשוויז-ש\"צ"},{"i":54500,"n":"שמואל מסוחאוולי","dt":"תרג - כד אדר","b":"רב בסוחאוולי(=סאחאואלי)"},{"i":54501,"n":"שמואל מסופיה","f":"דוד","bt":"תרמד","bp":"סופיה-בולגריה","dt":"תרפח - כג כסלו","b":"תלמיד בצלאל בירושלים, צייר. פרסם מאמרים ב\"תיאטרון ואמנות\". ממיסדי אגודת האמנים העברים בארץ."},{"i":54502,"n":"שמואל מסופיה","f":"שמשון","b":"דיין ביה\"ד האשכנזי בסופיה-שנות ה-תי'."},{"i":54503,"n":"שמואל מסופיה","f":"יוסף","dt":"תקעד - י ניסן","dp":"סופיה","b":"רב בסופיה."},{"i":54504,"n":"שמואל מסטניסלב","b":"מחכמי סטניסלב. תשובה אליו בטוט\"ד."},{"i":54505,"n":"שמואל מסלונים","f":"מנחם מנדל מפאטיק","dt":"תצא","b":"רב בפעמיסלא-תע\"א"},{"i":54506,"n":"שמואל מסעוד מונציה","b":"תשובה ממנו ב\"דבר שמואל\"."},{"i":54507,"n":"שמואל מסעוד מירושלים","b":"מחכמי ירושלים וראש הישיבה בזמנו של הנגיד וחתם בשנת רפא, וכן בשנת רסט על תקנת המס, בשנת רסד נזדמן לצפת."},{"i":54508,"n":"שמואל מספרד","k":"בעל ספר מאור","b":"מגדולי חכמי ספרד-שנת ע'"},{"i":54509,"n":"שמואל מספרד","f":"שניאור","k":"בעל חדושים על השס","b":"מגדולי הראשונים בחכמי ספרד-ד'תתק\"צ. חיבר חדושים על הש\"ס."},{"i":54510,"n":"שמואל מספרד","f":"סימא","b":"מחכמי ספרד, תלמיד הרא\"ש, חברו של ר משה בר יהודה הכהן."},{"i":54511,"n":"שמואל מספרד","f":"אלעזר","dt":"רנב - לפני","b":"רב בספרד, נפטר לפני הגירוש."},{"i":54512,"n":"שמואל מסקוליע","b":"רב בסקוליע-תקכא."},{"i":54513,"n":"שמואל מסקלאב","b":"רב בסקלאב,קארוב-תק\"ע"},{"i":54514,"n":"שמואל מפאטיק","b":"רב בפאטיק-תריג."},{"i":54515,"n":"שמואל מפדובה","f":"מנחם","b":"רב בפדובה."},{"i":54516,"n":"שמואל מפודהייץ","f":"יוסף יוסקי מפודקמין","dt":"תקמד - בערך","b":"רב בפודהייץ-תקמב."},{"i":54517,"n":"שמואל מפינטשוב","b":"מו\"צ בפינטשוב-תק\"ל"},{"i":54518,"n":"שמואל מפינסק צפת וירושלים","f":"שלום","bp":"פינסק","b":"עלה לארץ-תקץ, השקיע בביה\"ד של ישראל ב\"ק בצפת, והשתתף בהדפסת סדור \"שפת אמת\", איבד את רכושו לאחר פרעות הערבים בצפת-תקצד.. בשליחות-תקצה צפת וירושלים בליטא ופולין."},{"i":54519,"n":"שמואל מפליזא","b":"מגדולי בעלי התוספות בצרפת,מרביץ תורה בפליזא-נורמנדיה-שנת א',השתתף בויכוח הידוע על התלמוד מטעם המלך"},{"i":54520,"n":"שמואל מפפד\"מ","b":"מקובל,מגדולי הדור,רב בפפד\"מ"},{"i":54521,"n":"שמואל מפרג","f":"משה מנדלס","b":"מגדולי חכמי פרג-ת\"ל"},{"i":54522,"n":"שמואל מפרוביזנא","dt":"תצז","b":"רב בפרוביזנא"},{"i":54523,"n":"שמואל מפרובינציא","f":"גרשון מבדרש","b":"מגדולי הראשונים בחכמי פרובינצה-ד'תתק\"פ"},{"i":54524,"n":"שמואל מפרידברג","f":"אליעזר","dt":"שע - ג תשרי","b":"מגדולי חכמי דורו, רב בפפד\"ם על מקום ר אברהם נפתלי הרץ, ור ישעיה בן אברהם הורביץ על מקומו אחריו. השתתף באסיפת רבנים-שסג שהתקיימה בפפד\"מ ובה תוקנו תקנות חשובות - ובהם איסור לפנות לערכאות גויים והקמת 5 בתי דינים אזוריים, הקמת קרן לצרכי צבור - לכלל המדינה, ועוד - היתה הלשנה אודות החלטות אלו."},{"i":54525,"n":"שמואל מפריימדורף","b":"מקובל,איש מופת,מחכמי אייזנשטט"},{"i":54526,"n":"שמואל מפרלברג","bp":"נאוידואהר","b":"שו\"ב בפרלברג, עבר להונגריה והיה גם מוהל. חיבר כת\"י ובו חדושים על הש\"ס, ופנקס מילה."},{"i":54527,"n":"שמואל מפרמישלא","f":"משלם פיבש מקראקא","b":"מקובל, רב בפרמישלא-שנת ת. נזכר ב\"נובלות חכמה\" ליש\"ר מקנדיאה, \"מגלה עמוקות\", הקדמת \"עמק המלך\", ועוד. בנו - ר יחיאל מיכל מפרמישלא, ונכדו ר אריה ליב מלבוב."},{"i":54528,"n":"שמואל מפרשבורג","f":"קלונימוס","b":"דיין בפרשבורג-רמח - במינוי זמני של ר אליקים בן קלונימוס, ודן בענין כתובת אלמנה. אולי אחיו של ר אליקים מפרשבורג"},{"i":54529,"n":"שמואל מפרשבורג","f":"דוד בן ישכר דב","dt":"תקע - ח כסלו","dp":"פרשבורג","b":"נכד ר ישכר בר בעל באר טוב. מחכמי פרשבורג."},{"i":54530,"n":"שמואל מפשוורסק","b":"רב בפשעווארסק(=פשוורסק)-תק\"ל"},{"i":54531,"n":"שמואל מצורטקוב","f":"משה","b":"רב בטשארטקוב,זוואניץ,גליל פודוליע-תק\"פ"},{"i":54532,"n":"שמואל מצפת","f":"שלום","b":"בשליחות קהלת צפת-תקצז בפולין, אשתו ושלשה מילדיו נהרגו ברעש."},{"i":54533,"n":"שמואל מצרפת","b":"מגדולי חכמי צרפת ברומרוג. אביו של ר שמחה מויטרי"},{"i":54534,"n":"שמואל מצרפת","f":"רבינו דוד","b":"מגדולי חכמי צרפת-שנת ס'"},{"i":54535,"n":"שמואל מצרפת","f":"רבינו שמחה מויטרי","b":"מגדולי הפוסקים בדורו בחכמי צרפת"},{"i":54536,"n":"שמואל מקאוולי","b":"רב בקאוולי-תרכ, בנו חורגו של ר' יצחק מנשכיז"},{"i":54537,"n":"שמואל מקאליסק","k":"שמואל מונקעס","b":"תלמיד בעל התניא."},{"i":54538,"n":"שמואל מקאליש","f":"שניאור","b":"חריף,מגיד בקאליש-ת\"צ"},{"i":54539,"n":"שמואל מקארוב וסוקולוב","f":"אברהם ישעיה","k":"אדמור מקארוב","dt":"תקף","dp":"קראקא","b":"תלמיד ר אלימלך מליזנסק והחוזה מלובלין. עבר מניישטאט לכהן כרב בסוקולוב-גליציה ושם פעל למען החסידות. אדמור בקארוב-תקעה, ווענגרוב, קראקא (כך לפי וונדר). היה רבם של אדמורים רבים. מתולדותיו ב\"השביל והדרך\"."},{"i":54540,"n":"שמואל מקאשיבקה - א","k":"ר' שמואל מקאשיבקה","b":"רב בקשיבקה-תק\"נ"},{"i":54541,"n":"שמואל מקאשיבקה - ב","f":"מיכל מקאשיבקה","b":"רב בקאשיבקה-תר\"מ"},{"i":54542,"n":"שמואל מקאשיווקא","f":"מיכל מקאלק","k":"אדמור מקאיווקא","bt":"תקעח","b":"חברו של ר מרדכי מנסכיז ומחותנו. מכתב ממנו לר אשר מסטולין - ב\"בית אהרן\"."},{"i":54543,"n":"שמואל מקוניבלאט","k":"ר' פנחס מקוריץ","b":"חתן ר פנחס שפירא מקוריץ-תלמיד הבעש\"ט. רב בקוניבלאט(=קאלניבלאט)-תקע ובנו ר אהרן על מקומו אחריו."},{"i":54544,"n":"שמואל מקופיטשיניץ","b":"מחכמי קופיטשיניץ. תשובה אליו ב\"דברי יעקב\"."},{"i":54545,"n":"שמואל מקוצק","f":"חיים מלובלין","dt":"תצז - ז סיון","b":"רב בקוצק."},{"i":54546,"n":"שמואל מקלואריה-ליטא","f":"אליעזר","k":"בעל דרכי נעם","bp":"קלוואריה","b":"רב בקאלואריה-[שנות התק..]. חיבר פירוש בדרך פרד\"ס לאגדות בר בר חנא. ישנו חכם נוסף בעל אותו השם מארץ ישראל."},{"i":54547,"n":"שמואל מקמינקא","f":"דוד מרבינו","k":"אדמור מקמינקא","dt":"תקלח","b":"תלמיד הבעשט - אחד מ\"האחים הקדושים מקמינקא\". מתורתו ב\"חסד לאברהם\", \"שני המאורות\"."},{"i":54548,"n":"שמואל מקמינקא","f":"משה אהרן מקמינקא","dt":"תרג - י אייר","b":"תלמיד ר משה צעסיס מטשודנוב, ר לוי יצחק מברדיטשוב, ור אברהם יהושע השל מאפטא. מתורתו ב\"שני המאורות\", ו\"בית שמואל\". בנו ר משה-חתן ר צבי השני מקוריסטשוב-חתנו של ר אהרן מטיטיוב."},{"i":54549,"n":"שמואל מקראקא","f":"רפאל","dt":"תקנט - ז אייר","dp":"קראקא","b":"מחכמי קראקא."},{"i":54550,"n":"שמואל מקראקא - א","b":"רב בקרקא-ש\"ס"},{"i":54551,"n":"שמואל מקראקא - ב","f":"זאב וולף","k":"ר' שמואל מקרקא","b":"רב בקרקא-תע\"ט"},{"i":54552,"n":"שמואל מקרוז'","b":"מחכמי קרוז'. צדיק מופלא שנפטר בגיל 30."},{"i":54553,"n":"שמואל מקרלין","b":"רב בקרלין, אנטיפאליא-תקל. חתנו - ר יעקב יפה בעל גופי הלכות."},{"i":54554,"n":"שמואל מקרמניץ","f":"אפרים פישל לאדמיר","b":"רב בקרמניץ-ת\"צ"},{"i":54555,"n":"שמואל מקרקוביץ","b":"רב בקרקוביץ-ת\"פ"},{"i":54556,"n":"שמואל מראגולי וירושלים","dt":"תרטו - כה אלול","dp":"ירושלים","b":"רבה של ראגולי, עלה לירושלים והיה ראבד קהילת האשכנזים. הניח חדושים בכת\"י, הקים מכספו ביכ\"נ אורחים ומקוה בחצר ה'חורבה' בירושלים. בניו - ר יחזקאל, ר חיים אריה, ר אברהם זונדל (כנראה מפאקראיי-ליטא), נכדו - הגביר ר ליב קליבנסקי."},{"i":54557,"n":"שמואל מרדכי הלוי מחברון","b":"רב בראהטשוב, ראש קהלת חב\"ד בחברון-תקצד."},{"i":54558,"n":"שמואל מרדכי משלוניקי","b":"מגיה בדפוס קלעי ומרדכי נחמן בשלוניקי-שנות ה-תק'."},{"i":54559,"n":"שמואל מרוונא","f":"איסר","b":"רב ברוונא"},{"i":54560,"n":"שמואל מרוסג'וק","f":"אשר","b":"גביר ברוסג'וק-תקסו, והיה מחלוקת כנגדו בקהלה."},{"i":54561,"n":"שמואל מרוש","b":"תלמיד ר חיים חייקא מאמדור, ר שלמה מקרלין, ור אשר מסטולין. רב ברוש."},{"i":54562,"n":"שמואל מרחמנוב","dt":"כ' אדר","b":"רב ברחמנוב"},{"i":54563,"n":"שמואל מריישא","b":"רב ברישא-ת\"נ"},{"i":54564,"n":"שמואל משאדובה","f":"גרשון","b":"רב בשאדובה-תר\"ל"},{"i":54565,"n":"שמואל משה מארטה","b":"דיין בארטה-תעד בענין השליח ר שמשון גומץ פאטו."},{"i":54566,"n":"שמואל משינאווא","k":"בעל רמתים צופים","bt":"תקמה","bp":"שיניבה","dt":"תרלג - ח שבט","b":"בזיוו\"ש חתן ר אברהם מטשכנוב. תלמיד ר שלמה יהודה ליב מבוקובסק (ואחר כך לנטשנא), ר מנחם מנדל מקוסוב, ר שמחה בונם מפשיסחא והיה קרוב אליו, ר שלמה יהודה ליב מלענטשע, ועוד. רב בשינאווא, וולודובה, ברוק, שדליץ, לאויטש, ונשלסק. התקרב לאדמור מקוצק ולחדושי הרי\"מ. חיבר \"רמתים צופים\" ורשא תרמא.","bk":[["רמתיים צופים – תנא דבי אליהו",""]]},{"i":54567,"n":"שמואל משלוניקי","f":"יוסף עוזיאל","b":"רופא בשלוניקי - בשנות הש'."},{"i":54568,"n":"שמואל משלוניקי","f":"יהודה","dt":"תקיח","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":54569,"n":"שמואל משלוניקי וסרייבו","f":"ברוך משלוניקי","dt":"שפח או שצד -רה","dp":"שלוניקי","b":"נכד ר שמואל ברוך משלוניקי. מחכמי שלוניקי, רב בסרייבו. תשובה ממנו-שע לר חיים שבתי ור אשר ן ארדוט משלוניקי.."},{"i":54570,"n":"שמואל ן, שמואל מפטרץ-יוון","b":"מחכמי ספרד והתישב בפטרץ(=פטרא,בדרא)."},{"i":54571,"n":"שמואל נפתלי הרץ","f":"יהודה אריה ליב","b":"רב בבריסק"},{"i":54572,"n":"שמואל סגל ממינסק","f":"יחיאל מיכל","dt":"תקעט - כט כסלו","dp":"מינסק","b":"רב במינסק על מקום ר ישראל מירקש, ור ישראל הלפרין על מקומו אחריו."},{"i":54573,"n":"שמואל עזיאל ראה גם","f":"עוזיאל, שמואל","b":"דיין, ונזכר בשו\"ת ר יוסף טאיטצאק."},{"i":54574,"n":"שמואל עזרא משלוניקי","b":"דיין בשלוניקי-שיט."},{"i":54575,"n":"שמואל פיבוש","b":"מחדושיו ב\"ברכת טוב\"."},{"i":54576,"n":"שמואל פיבוש מזולקוא","dt":"תקפב - כב שבט","b":"רב בזלקווא"},{"i":54577,"n":"שמואל פרץ מקושטא","b":"מחכמי קושטא-שנות ה-ש'."},{"i":54578,"n":"שמואל צבי הרץ מפינטשוב","f":"יואל - הב\"ח","dt":"תי","b":"מגדולי חכמי דורו, רב בפינטשוב-שפט. בנו ר אריה ליב מקראקא ובריסק."},{"i":54579,"n":"שמואל צדוק משלוניקי","dt":"תצז - יז כסלו","dp":"שלוניקי","b":"רב בשלוניקי על מקום ר יוסף דוד-מהרי\"ד בעל \"בית דוד\" - אך נפטר לאחר כשבועיים, ור שאול בן שלמה בר דוד על מקומו אחריו."},{"i":54580,"n":"שמואל ר יעקליש מאוסטרהא","f":"יעקב ר שמואל'ס","dt":"תקז","dp":"אוסטרהא","b":"פרנס וגזבר באוסטרהא ומנהיג הקהלה. בנה את ביהכ\"נ שנקרא ע\"ש (ובזמן כהונת הרב ייבי החלו לקרוא לו ביה\"כ של ר ייב\"י - והיה מחלוקת על כך). נזכר בפנקסי הח\"ק. בכתב הרבנות של ר אברהם כהנא חתם רביעי מתוך 30 החותמים. נזכר בשער הספר \"ברוך מבנים אשר\". חתם הרבה לפני ר מרדכי הלפרין בפנקסים. אחיו של ר מרדכי ר יעקב'ס. בניו: ר יוזפא פרנס ואהלין, ר דב בר חתן ר בצלאל כץ מאוסטרהא, ר יצחק איזיק מראווני וקוריץ, ר שמחה מאוסטרהא, ר אשר מאוסטרהא, ר חיים מאוסטרהא. חתניו: הרב מקלעוואן - נפטר באוסטרהא, ר ישכר בר שנפטר צעיר ובנו נקרא ע\"ש ישכר בר - ואולי הוא הרב בקלעוואן), מנחם מנדל בן שמואל מאוסטרהא."},{"i":54581,"n":"שמואל ראמאנר דרשן מלובלין","k":"בעל דברי עתיקין-כת\"י","b":"דרשן בלובלין. בנו ר בנימין זאב בעל \"עיר בנימין\". נזכר בספר אחיינו ר בנימין זאב וולף מפינטשוב - \"מסגרת השלחן\"."},{"i":54582,"n":"שמואל רובזעויצער מוילנא","b":"מחכמי וילנא. חברו של ר ליבלי רוטשיסקער. בנו - ר דוד."},{"i":54583,"n":"שמואל רכב'ס","f":"מרכובי","b":"מחכמי ירושלים, מוזכר אצל ר משולם מוולטרא כאחד הדיינים."},{"i":54584,"n":"שמואל שאלתיאל משלוניקי","b":"מחכמי שלוניקי-תרף."},{"i":54585,"n":"שמואל שמלקא","f":"יהודה ליב מזקילקוב","b":"מחשובי חסידי החוזה מלובלין. נפטר צעיר."},{"i":54586,"n":"שמואל שמלקא יהודה ליב מפלנטשן","f":"משה מלנצהוט","k":"בעל אמרי זוטרי","dt":"תקסה - יא שבט","b":"רב בפלנטש, פשדבורז, דנביץ(=דעניביץ), אב\"ד גליציה-תקמז, בומלסא-תקנה על מקום ר אליעזר בונדי. חיבר \"אמרי זוטרי\" מצורף ל\"אמרי רברבי\" לזקנו ר יעקב יצחק דוקלא לנדא \"אמרות טהורות\" לובלין תרנה. בנו ר יצחק משה עזריאל ליכט מבלזיץ."},{"i":54587,"n":"שמואל שמלקא כץ הכהן מאוסטרהא","f":"צבי","dt":"תקנט - ד חשון","dp":"אוסטרהא","b":"נכד גדולי אוסטרהא ר יוסף גינצבורג בעל \"לקוטי יוסף\", ומצאצאי ר שמואל שמלקא ז\"ק מאוסטרהא. פרנס באוסטרהא-תקכו, ותורם גדול לצדקה וצרכי ציבור. חתום הרבה בפנקס הח\"ק. חתנו ר מנחם מנדל נהרג עק\"ה בשריפה-תקלז (עד שהתברר כי נרצח נותרה אשתו עגונה ועל כך ב\"מאיר נתיבים\" לר מאיר מרגליות-שהתירה וב\"תפארת צבי\" לר צבי הירש מברוד וגלוגא), ה\"נודע ביהודה\" סירב להתירה (אך גם לא אסרה), בנו ר יעקב שלח תשובה להתירה ובהסכמת כמה גדולים ובהם ר יוסף חיים מהאלשיץ ואוסטרהא. לאחר שהותרה נישאה בזיוו\"ש לר יודיל לנדא - נכד ה\"נודע ביהודה\" ונכד ר חיים לנדא מברוד."},{"i":54588,"n":"שמואל שמלקא כץ מזולקוא","f":"יוסף","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה."},{"i":54589,"n":"שמואל שמלקא מרמישלא","dt":"תצז - כא תמוז","b":"רב ברעמישלא"},{"i":54590,"n":"שמואל שמלקא משענא","b":"רב בשענא"},{"i":54591,"n":"שמואל שמלקי הלוי מאוסטרהא","dt":"תקד - ה סיון","dp":"אוסטרהא","b":"מגדולי אוסטרהא ונרשם בפנקס הח\"ק שקיבל דבש ברגל (בקהילת אוסטרהא נהגו שבכל חג שלחה הח\"ק דבש לכבוד הרבנים וגדולי הקהל). בנו ר נתן נטע ומצאצאיו כנראה המדפיס ר שמואל בן ישכר הלוי."},{"i":54592,"n":"שמואל שמלקי מקראקא","b":"מחכמי קראקא. תשובה אליו בשו\"מ."},{"i":54593,"n":"שמואל ששון מטיריא","b":"רב בטיריא-שנות הש'. היה מחלוקת כנגדו מר שמואל ממגניסיאה, רב ברודוס-שעז."},{"i":54594,"n":"שמואל ששון משלוניקי","b":"רב בשלוניקי-שנות ה-ש'."},{"i":54595,"n":"שמואל-סגל, יצחק איזיק","f":"אליהו","bt":"תרנט","bp":"רוסיה","b":"תלמיד ישיבת מיר, ראדין, סלובודקא, ונודע בכינוי \"האוורוטשער\". נסמך מאת: ר משה מרדכי אפשטין, ר שמואל רבינוביץ ממוסקבה. חתן - ר דוד פיינשטין מסטרבין - והיה גיסו של ר משה פיינשטין מניו יורק. רב בפטרסבורג ויסד שם ישיבה. היגר לארה\"ב-תרפה וכיהן כרב בשיקגו. חבר אגודת הרבנים באמריקה, ופעיל בועד ההצלה."},{"i":54596,"n":"שמואלביץ, אלתר הלוי","dt":"תרעח","b":"מרביץ תורה בשטוצ'ין"},{"i":54597,"n":"שמואלביץ, חיים ממיר וירושלים","k":"בעל שערי חיים","bt":"תרסב","dt":"תשלט","dp":"ירושלים","b":"נכד ה\"סבא\" מנוברדוק. חתן הגרא\"י פינקל ממיר. ניצל מהשואה דרך שנחאי-סין, עלה לארץ וכיהן כראש ישיבת מיר בירושלים. לזכרו \"ספר הזכרון להגר\"ח שמואלביץ\". בנו - ר רפאל - ר\"מ בישיבת מיר בירושלים."},{"i":54598,"n":"שמואלביץ, יצחק","f":"משלם","bt":"1893","bp":"ליפנישוק-ליד לידא","dt":"1941","dp":"קובנא","b":"תלמיד ישיבת לידא, הצטרף לתנועה הציונית. היה נואם מוכשר בעברית. מורה בגימנסיה הריאלית העברית בקובנא, בגימנסיה החרדת בקובנא, ועוד. יסד את \"צעירי מזרח\" בוילנא וממנה התגבשה \"הסתדרות צעירי ישראל\". השתתף בועידות שונות, ממיסדי \"יבנה\", \"אידישער לעבן\" - בטאון היהדות החרדת בליטא, ועוד. נספה בשואה. אשתו אלקה לבית שוורץ מטלז עסקה בהוראה ובחינוך חרדי. מייסדת כתה\"ע \"בית יעקב\" בקובנא באידיש ועברית."},{"i":54599,"n":"שמואלביץ, שלמה","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":54600,"n":"שמואלזון, מנשה מאשמינא","bt":"תרלא","dt":"תרצז - כה תשרי","b":"מו\"צ באשמינא"},{"i":54601,"n":"שמואלי, מ'","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":54602,"n":"שמואלידיס, יהושע משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":54603,"n":"שמויש, מיכאל הכהן מקוברין","f":"שמואל מאיר","bt":"תרמ-ד","dt":"תשג","b":"חתן האב\"ד מוש חדש. דומ\"צ בקוברין-תרסה. נספה בשואה?"},{"i":54604,"n":"שמוקלר, אברהם יהודה מלייפציג","b":"רב בלייפציג בדור שלפני השואה."},{"i":54605,"n":"שמוקלר, יעקב משה","dt":"תשג","b":"רב בשאנץ(ליטא)"},{"i":54606,"n":"שמוקלר, מרדכי מלידא","dt":"תשג","b":"רב בלידא"},{"i":54607,"n":"שמוקלר, משה יעקב מטרשקון","dt":"תש..","b":"רב בטרשקון-ליטא, שאנץ-פרבר קובנה-תרצז. נספה בשואה."},{"i":54608,"n":"שמוקלר, משה שמואל","k":"בעל תולדות הגר\"ח","b":"חתן ר אברהם אבא ז\"ק מאלשאד. חיבר \"תולדות הגר\"ח מוולוזין\"."},{"i":54609,"n":"שמוקלר, נתנאל מוארשא","b":"תלמיד ישיבת \"בית שמואל\" בוארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":54610,"n":"שמושקוביץ, יעקב","bt":"1902","b":"גלה עם הוריו לסיביר, הצטרף לבולשביקים ושירת בצבא. מפקד חיל האויר הרוסי-1940. נרצח בזמן הטיהורים בימי סטלין."},{"i":54611,"n":"שמושקוביץ-ציוני, ברי ניסן","k":"בעל בנין ציון","bt":"תרמו","dt":"תשיג - י אלול","b":"חתן ר משה מאראן. מו\"צ באראן,ארמזוס-תרע\"ה,אמסטיבווה-תרפ\"ב,בנדקי-תרפ\"ד,עלה לקרית חיים-תרצ\"ה,ראב\"ד בחיפה. בניו: ר משה ציוני, ר מנחם ציוני."},{"i":54612,"n":"שמחה אליעזר מאזמיר","k":"בעל שער המלך","b":"מחכמי אזמיר, חתן ר יעקב אלבעלי בעל \"קהילת יעקב\". תלמיד ר יצחק נוניס בילמונטי בעל \"שער המלך\"."},{"i":54613,"n":"שמחה אפרים פישל מירושלים","f":"ראה: גרדשטין, שמחה א"},{"i":54614,"n":"שמחה בונם מאוסטרהא","f":"גרשון","b":"מחכמי אוסטרהא. חתם על שטר מכירת הזכויות על \"עין יעקב\"-סלאויטה למדפיסי דובנא, וחתם על המגילה-תקנב."},{"i":54615,"n":"שמחה בונם מוילנא וקראקא","b":"מחכמי וילנא, עבר לקראקא, חתם-תם על כתב רבנות ר משה בעל \"תפארת למשה\". תשובה ממנו בשו\"ת \"צמח צדק\"."},{"i":54616,"n":"שמחה בונם מלבוב","dt":"תה","b":"דיין בלבוב"},{"i":54617,"n":"שמחה בונם מפיחוביץ","f":"מנחם מנדל או זאב וול","b":"רב בפוחאוויץ(=פוחביץ). בנו - ר בנימין בנדיט מהאלוסק, ונכדו - ר מנחם מנדל משקלוב וירושלים."},{"i":54618,"n":"שמחה בונם מפשיסחא","f":"צבי הירש מואדיסלב","k":"אדמור מפשיסחא","bt":"תקכז","bp":"ואדיסלוב","dt":"תקפז - יב אלול","b":"בן המגיד מואדיסלב בעל \"עשרה למאה\" ו\"ארץ הצבי\". גדל בהונגריה, והיה תלמיד ר ירמיה ממטרסדוף. חסיד החוזה מלובלין, והיהודי הקדוש מפשיסחא. אדמור בפשיסחא אל מקום רבו-תקעד. השתלם גם במדע ורפואה. חיבר \"קול שמחה\" ו\"מדרש שמחה\".","bk":[["קול מבשר – עה\"ת",""],["חדות שמחה – עה\"ת",""],["קול שמחה",""],["קול שמחה , חדות שמחה – עה\"ת",""]]},{"i":54619,"n":"שמחה בונם מקראקא ולבוב","f":"אליעזר","dp":"לבוב?","b":"רב בוילנא, קראקא-שנ, ר\"מ בלבוב. בנו ר ישראל איסר מלבוב."},{"i":54620,"n":"שמחה בונם מרומנוב","b":"רב ברומאנוב-ת\"כ"},{"i":54621,"n":"שמחה בונם משקלוב ווילנא","f":"ברוך בנדט מהלוסק","b":"תלמיד הגר\"א מחכמי וילנא-תקנ. אחיו - ר מנחם מנדל משקלוב."},{"i":54622,"n":"שמחה הכהן מבלגרד","f":"גרשם או גרשון","k":"בעל שמות גיטין","bt":"שפב","bp":"בלגרד","dt":"תיז-אחרי או תכט","dp":"בלגרד","b":"נכד(-אבי אמו) ר שמחה בן חיים פריידמן מבודון. חתן ר אברהם בן חזקיה הס. תלמיד ר יחיאל באסאן, ר יהודה לירמא מבלגרד, ורב בבלגרד-ת' על מקומו אחריו, עבר לאויבן(=בודון)-תכא, קושטא, חזר לעירו (בגלל תקנה בבודון שלא יתמנה לרב מי שיש לו קרובים שם). הו\"ל מכתבי רבו - \"פליטת בית יהודה\" - ונציה תז. חתנו ותלמידו - ר יוסף אלמושנינו - רב בבלגרד על מקומו אחריו. (באוצר הרבנים תאריך פטירתו - תכט)."},{"i":54623,"n":"שמחה הכהן מירושלים","dp":"ירושלים","b":"מחכמי ירושלים-שנות ה-תק'."},{"i":54624,"n":"שמחה הלוי מניו יורק","b":"פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":54625,"n":"שמחה הלוי מרישא","f":"גרשון יצחק","k":"בעל שמחת הלוי","bt":"תרן","bp":"רישא","b":"תלמיד ר יודל לוין אוסטרובצר מקראקא, תלמיד רד\"ד מייזלש בישיבת אויהל. עבר לניו יורק-תרעג ולמד בישיבת ר יצחק אלחנן. רב בניו ג'רזי. חתן הגביר ר אהרן דרייזין ממונטריאול. חיבר \"שמחת הלוי\" ניו יורק תשכז."},{"i":54626,"n":"שמחה יואל הכהן","k":"בעל מקור נפתח","b":"רב בסווירז-ת\"ר"},{"i":54627,"n":"שמחה יואל מפוטיק","b":"מחכמי פוטיק, רב ביזלוביץ(=ייזלביץ). (בשנת תשב-ג היה במחסה אצל טאטומיר - חסיד אומות העולם). מתורתו ב\"אהבת יהונתן\" על תרגום יונתן."},{"i":54628,"n":"שמחה מאובין","f":"חיים","b":"רב באובן-שנות ה-ש'."},{"i":54629,"n":"שמחה מאוסטרהא","f":"יעקב סקלאווער מאוסטר","dt":"תקמ - כב אייר","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":54630,"n":"שמחה מאוסטרהא","f":"שמואל ר יעקב'ס","dt":"תקסח - כא ניסן","dp":"אוסטרהא","b":"פרנס מחכמי אוסטרהא. ישב אצל חותנו ברישא וחזר לאוסטרהא-תקג. חתם בפנקס הח\"ק. היתה לו בת אחת שנישאה לשדה לבן."},{"i":54631,"n":"שמחה מאוסטרובצה","f":"נתן בן יעקב יהושע","b":"נכד הפני יהושע. חתן ר יחזקאל מרגליות מגריידינג ואוסטרובצה. מו\"צ באוסטרווצה(=אוסטרובצה)-תקמ. בנו - ר נתן יחזקאל מקוזניץ."},{"i":54632,"n":"שמחה מאיוניצא","b":"רב באיווניצא-תר\"ך"},{"i":54633,"n":"שמחה מדוברומיל","f":"הרב מאפטא","b":"רב בדוברומיל-תק\"ס"},{"i":54634,"n":"שמחה מוארנע וירושלים","f":"אליהו","dt":"תרכה - טז תמוז","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":54635,"n":"שמחה מויטרי","f":"רבינו שמואל","k":"בעל מחזור ויטרי","dt":"ד'תתסה","b":"מגדולי הפוסקים בחכמי צרפת,מרביץ תורה בויטרי","bk":[["מחזור ויטרי",""]],"e":"ד'תתס\"ה~ [פטירה]"},{"i":54636,"n":"שמחה מוילנא","f":"יהושע השל משקלוב","dt":"תקסה - ו סיון","dp":"וילנא","b":"מצאצאי הב\"ח ומצאצאי גאוני בריסק וקראקא, מחכמי וילנא."},{"i":54637,"n":"שמחה מזבלטוב","b":"שו\"ב בזבלטוב. תשובה אליו ב\"רב טובך\"."},{"i":54638,"n":"שמחה מזלאויץ וצפת","f":"יהושע","k":"בעל אהבת ציון","b":"מ\"מ בזלאוויץ. עלה לצפת מליטא-תקכה. חיבר אהבת ציון - ספורי ארץ הגליל."},{"i":54639,"n":"שמחה מטבריה","f":"שלום הכהן","b":"ממונה \"כולל רייסין\" בטבריה-תרטו."},{"i":54640,"n":"שמחה מטלומטש","b":"רב בטלומטש."},{"i":54641,"n":"שמחה מטרוקי","f":"משה","k":"שמחה טראקער","dt":"תקפח - יח תמוז","dp":"וילנא","b":"חתן ר מרדכי אפשטין מוילנא-(המכונה מרדכי גיטקע טויבעס). מחכמי וילנא, מחותן עם ר אברהם משה מואשלישוק בן ר שלמה דובנא."},{"i":54642,"n":"שמחה מטשכוב","b":"תלמיד ר מנחם מנדל מקוצק. אב\"ד טשכוב."},{"i":54643,"n":"שמחה מישליסק","f":"יעקב","b":"הגיע מישליסק, רב בדוקלא - לפני תרמה."},{"i":54644,"n":"שמחה מלמברג","f":"מהר\"י","b":"דיין בלמברג-תריא אצל ר בנימין אלנברג."},{"i":54645,"n":"שמחה ממזיבוז","f":"נחמן מהורודנקה","bt":"תקי","b":"חתן ר יחיאל אשכנזי-חתן הבעש\"ט. רב במזיבוז-תק\"מ. אביו של ר נחמן מברסלב."},{"i":54646,"n":"שמחה מסטרי","f":"משה יצחק או ליב צינץ","dt":"תנז - ח סיון","dp":"לבוב","b":"נכד ר נפתלי הרץ מוינה. חתן ר יוסף סגל מפרמישלא. רב בסטרי, ר\"מ בלבוב. בנו - ר יהודה משינאווי וקאליש."},{"i":54647,"n":"שמחה מסלונים","f":"יהושע העשל","b":"חתן ר יקותיאל זלמן מדרוהוביטש. רב בסלונים-תקך. לפי אבני בית היוצר היה בנו של ר יקותיאל ולא חתנו והיה רב בסלאמינע."},{"i":54648,"n":"שמחה מסערד-האלי","dt":"תקל - כד אייר","b":"רב בסערדאהעלי"},{"i":54649,"n":"שמחה מסשריטאשיש","b":"רב בויניציאה-תק\"י"},{"i":54650,"n":"שמחה מפרגא","dt":"תקפג - יח תשרי","b":"דיין בפרגה-וורשה"},{"i":54651,"n":"שמחה מצפת","f":"בנימין","dt":"תקעו - לפני","b":"מראשוני העולים תלמידי הגר\"א לצפת, בשנת תקעד גבאי ופרנס הקהלה עם אחיו - ר יעקב קופל."},{"i":54652,"n":"שמחה מקומורן","b":"דומ\"צ בקומורן-תר\"י"},{"i":54653,"n":"שמחה מקלסני","b":"רב בקלסני-תקף. הסכים על \"דברי תורה\" לר יהונתן פרנקל-תאומים - תקצג."},{"i":54654,"n":"שמחה מקשונז","dt":"תרכח","b":"רב בקשונז"},{"i":54655,"n":"שמחה מרדכי מקאלושין","b":"תלמיד ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק. נודע כבעל מופת."},{"i":54656,"n":"שמחה משלוניקי","f":"חיים","b":"רב בשלוניקי-שנות ה-ש'."},{"i":54657,"n":"שמחה משפיירא","k":"בעל סדר עולם","b":"מגדולי חכמי אשכנז,מרביץ תורה בשפירא-ד'תתק\"פ"},{"i":54658,"n":"שמחה סימן טוב","bt":"תריט","dt":"תרצו","dp":"ירושלים","b":"רב בהאראת (אפגניסטן), עלה לירושלים בתרפט."},{"i":54659,"n":"שמחה שמואל מסטויפצי","k":"בעל משרת משה","dp":"מזריטש","b":"רב בסטופצי, מזריטש-תרכ. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. חיבר גם \"שמחת ישרים\"."},{"i":54660,"n":"שמחה, אשר משלוניקי","f":"שמואל","dt":"תרצו","dp":"פאריס","b":"רבה האחרון של הקהלה האשכנזית בשלוניקי. חבר ב\"ועד הרוחני\", בביהמ\"ד לרבנים \"אור החיים\", ועוד מוסדות ציבור. פעל לבניתו מחדש של ביהכ\"נ של ק\"ק אשכנזים שהיה שייך למשפחתו. היה בארץ ישראל-תרצג-תרצד, עבר לפאריס."},{"i":54661,"n":"שמחה, יצחק יוסף משלוניקי","b":"גביר בשלוניקי, שותפו של ר יצחק פלורנטין. תרם לת\"ת של אחיו - ר שמואל שמחה-תרסד."},{"i":54662,"n":"שמחה, שמואל יוסף משלוניקי","k":"בעל דרשות על חברת עץ","bt":"תרב","dt":"תרסב - שבט","dp":"שלוניקי","b":"מהרבנים ה\"מתקדמים\" בשלוניקי. מחותן עם ר יעקב קובו-רבה הראשי של שלוניקי - בנו אשר שמחה היה חתנו של ר יעקב. רב ומנהל הת\"ת בשלוניקי-תרסד. חיבר דרשות על חברת \"עץ חיים\"-תרן. בניו: ר אשר שמחה, שבתי שמחה. חתנו - הגביר מאיר רפאל בנבנישתי. אחיו - הגביר יצחק, וגיסו הגביר יעקב משה פלורנטין - היו שותפים עמו בעסקיו - ואף תרמו לפי המלצתו לבית ספר ת\"ת."},{"i":54663,"n":"שמחון, אברהם ממכנאס","f":"יעקב בן אהרן","b":"מחכמי מכנאס."},{"i":54664,"n":"שמחון, אברהם ממרוקו","b":"מו\"ץ בבגריס-מרוקו, מרביץ תורה בנוף תאפילאלת."},{"i":54665,"n":"שמחון, אהרן מאלגיר","b":"רב בתלמסאן-תפז ונזכר בשטר מכר."},{"i":54666,"n":"שמחון, אהרן מדרעא-מרוקו ותלמסא","f":"סלימאן","b":"מחכמי דרעא, עבר לתלמסאן. חתנו או מחותנו - ר חלפתא ן אליד מדרעא. יצא בדרכו לארץ ישראל יחד עם חבריו ר שמואל אביטבול, ר אהרן בן שלמה מלכא ועם האחים ר יוסף ור חלפתא ן אליד, הגיעו עד תלמסן ולא הגיעו לארץ (האחים ן אליד המשיכו בדרכם)."},{"i":54667,"n":"שמחון, אהרן ממקנאס-מרוקו","k":"בעל בגדי ישע","b":"מחכמי מקנאס, חיבר \"בגדי ישע\", \"אם למקרא\"."},{"i":54668,"n":"שמחון, בנימין","f":"יצחק","b":"חכם שלם-תקל\"ב"},{"i":54669,"n":"שמחון, בנימין ממרוקו","f":"מסעוד","b":"מחכמי מרוקו, חתם על פס\"ד-תץ יחד עם ר שלם אדרעי, ר יהודה הלוי, ר אברהם ן עלאל."},{"i":54670,"n":"שמחון, בנימין מפאס-מרוקו","b":"מראשי קהלת פאס, נאסר-תקן בידי המושל אליזיד יחד עם אחיו, בענין עזבון ר מרדכי אשריקי."},{"i":54671,"n":"שמחון, דוד ממצרים","b":"רב במצרים, הסכים על \"עין יהוסף\" - אזמיר תצה. בביתו מצא ר חיים וינטורה את כתב היד של מהר\"י קורקוס על הרמב\"ם (ועל כך בהקדמתו לספר)."},{"i":54672,"n":"שמחון, דוד מפאס","f":"סלימן","b":"סופר ביה\"ד בפאס-שנות ה-ר'."},{"i":54673,"n":"שמחון, יהודה מפאס","b":"מחכמי פאס, ש\"ץ בזמן עצירת גשמים-תלח."},{"i":54674,"n":"שמחון, יוסף מיפו","b":"מראשי עדת המערבים ביפו. הו\"ל \"יאיר מבין\" לר יוסף ן נון."},{"i":54675,"n":"שמחון, יעקב מאזאווייא-מרוקו","b":"מחכמי כפר אזאווייא וגורש-תיא עם כל הקהלה לפאס יחד עם ר מימון אפללו, ונעזרו בידי ר וידאל הצרפתי שנתן להם מקום לתפילה בפאס."},{"i":54676,"n":"שמחון, יעקב מיפו","dt":"תרנד - א אד\"א","dp":"ירושלים","b":"עבר מירושלים ליפו-אחרי תר, ולמד בישיבת ר אברהם שלוש, חזר לירושלים."},{"i":54677,"n":"שמחון, יעקב ממכנאס","f":"אהרן","b":"מחכמי מכנאס ומלמד תורה."},{"i":54678,"n":"שמחון, יעקב מפאס","k":"בעל בת רבים - כת\"י","dt":"תרטז-יז","b":"תלמיד ר חיים דוד סירירו. מחכמי פאס, חתם עם ר אליהו עטייה. חיבר גם \"משחא דרבותא\"."},{"i":54679,"n":"שמחון, יעקב מתאפילאלת - א","b":"מחכמי סג'למאסא(=תאפילאלת)-מרוקו-שלט, נזכר בתשובה מאת ר אברהם אביטבול."},{"i":54680,"n":"שמחון, יעקב מתאפילאלת - ב","f":"יצחק","b":"מו\"ץ בתאפילאלת-מרוקו-תקמג עם ר מסעוד הכהן ור מכלוף בלזרע. חיבר תוכחה לאומרה כל יום, תשובה אליו מהיעב\"ץ-תקג."},{"i":54681,"n":"שמחון, יצחק מטבריה וצפת","b":"רב בצפת, טבריה. בשנת תקפט חתם על כתב שליחות ר בצלאל בן אריה ליב הכהן. בשליחות טבריה-תקפג - תקצג."},{"i":54682,"n":"שמחון, ישראל מיפו","b":"מנהל פרדס מונטיפיורי ליד יפו-תרל."},{"i":54683,"n":"שמחון, מימון מפאס","b":"מחכמי פאס."},{"i":54684,"n":"שמחון, מרדכי","k":"בעל מירא דכיא"},{"i":54685,"n":"שמחון, משה מיפו","dt":"תרנז - כב אלול","dp":"יפו","b":"מחכמי עדת המערבים ביפו. פרסם מאמרים ב\"המאסף\"."},{"i":54686,"n":"שמחון, משה ממצרים - א","b":"רב במצרים-שנת ת'. תלמיד ר אברהם סכנדרי, חברם של ר זרחיה גוטה, ר יהודה הכהן, ומהר\"י שאראף."},{"i":54687,"n":"שמחון, משה ממצרים - ב","b":"מגדולי חכמי מצרים-ת\"פ"},{"i":54688,"n":"שמחון, משה ממרוקו וטבריה","bp":"מרוקו","b":"מקובל מחכמי מרוקו, עלה לארץ והתישב בטבריה, וצפת. בשליחות צפת-תקף בתורכיה, מרוקו-תקץ ועוד שליחות באיטליה. ר שמואל גירונדי מספר שארחו בהיותו בפדובה. מתורתו ב\"לקוטי שושנים\" לר מרדכי גירונדי, ו\"הלכות פסוקות\" לר שמואל גירונדי."},{"i":54689,"n":"שמחון, משה מפאס וירושלים","bp":"פאס","b":"תלמיד ר שלמה ן דנאן בעל \"אשר לשלמה\". מקובל מחכמי פאס, עלה לירושלים, בשליחות במרוקו ונשאר בפאס, מו\"ץ במוגאדור (מטעם הממשלה)-תרצ'. פרסם מאמרים ב\"המאסף\"."},{"i":54690,"n":"שמחון, רפאל יעקב ממרוקו","f":"מכלוף","k":"בעל בת רבים","dt":"תריז","b":"מקובל מחכמי פאס. תלמיד ר חיים דוד סירירו, ור בצלאל מאנסאנו. חיבר פירוש בדרך הקבלה - בסוף \"בת רבים\" ג'רבא תשטו."},{"i":54691,"n":"שמחון, שלם מפאס","b":"מחכמי פאס-שנות ה-ת', נספד מאת היעב\"ץ."},{"i":54692,"n":"שמחון, שלמה ממרוקו","b":"רב בפאס-תרם."},{"i":54693,"n":"שמיד, חיים מיבלונוב","b":"חתן ר יוסף שמואל גלרנטר מיבלונוב, רב ביבלונוב על מקום חותנו (והיתה מחלוקת על כך), גיסו ר חיים גלרנטר על מקומו אחריו (והיה מחלוקת על כך)."},{"i":54694,"n":"שמיד, ישראל משה מקראקא","dt":"תשב","b":"בוחן בישיבת חכמי לובלין. נספה בשואה."},{"i":54695,"n":"שמיד, משה מקראקא","b":"פרסם מאמרים ב\"אחיאסף\" - סטריזוב תרפט."},{"i":54696,"n":"שמידט, אהרן בנדט הכהן מליטא","bt":"תריט","dt":"תשכה","dp":"תל אביב","b":"רב ברומשישוק, ויזון על מקום ר מאיר אליהו וינר, עלה לארץ והתישב בתל אביב. נפטר בגיל 106."},{"i":54697,"n":"שמידמן, אהרן ממוסטי","f":"מיכאל דוד","dt":"תש..","b":"תלמיד ישיבת הורדנא, וולוזין. רב במוסטי. נספה בשואה."},{"i":54698,"n":"שמידמן, יצחק מארה\"ב","f":"מיכאל דוד","k":"בעל כנור יצחק - כת\"י","bt":"תרנט","bp":"פאהאסט-פלך פינסק","b":"תלמיד ישיבת פאהאסט, סלונים, וולוזין, נוברדוק, ביאלא, סוקולוב, אצל הרבנים ר ישכר ברקובסקי, ר צבי הירש חורגין, ר יעקב שפירא, ר שבתי יגל. נסמך מאת: ר שמחה ולפובסקי מוארשא, ר יוסף יוסלביץ מסובאלק, ר איזיק יעקב קלרקוביץ מדרוהוטשין. חתן ר שמעיה יהודה הלוי אבלאן מסעמיאטיש. ממיסדי תנועת \"תפארת בחורים\" וצעירי מזרחי בפולין. היגר לארה\"ב-תרפו וכיהן כרב בניופורט-רוד איילנד, ר\"מ בישיבת \"תורת חיים\" בניו יורק. חבר אגודת הרבנים באמריקה, ותנועת המזרחי. בניו - ר משה אהרן, מיכאל דוד, יהושע צבי, ר משה אהרן."},{"i":54699,"n":"שמידמן, שמואל מארה\"ב","f":"מיכאל דוד","bt":"תרעה","bp":"פאהאסט(=פוהוסט)","b":"תלמיד ישיבת לומזה, וולוזין, מיר. נסמך מאת ר צבי הירש קאמאי, ר אליעזר יהודה פינקל, ר\"י שפירא מוולוזין. ניצל מהשואה כשעבר עם ישיבת מיר לוילנא וכיהן כרב בקהלת \"אנשי חפץ\", היגר לארה\"ב-תשא וכיהן כרב קהלת \"אוהב צדק\" בניו יורק, קהלת\"קאנארסי\", ר\"מ בישיבת \"תורת חיים\" בניו יורק. חתן ר א\"י גורדון-בן ר אהרן בעל \"אבן מאיר\". חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":54700,"n":"שמילה, רחמים מתונס","b":"דיין באלואד-תונס - בשנות ה-תר'."},{"i":54701,"n":"שמירר, אשר מסקאהל","b":"רב בסקול."},{"i":54702,"n":"שמליצנסקי, משה אהרן","bt":"1851","bp":"קובנא","dt":"1896","dp":"ראשון לציון","b":"גביר בליבאו. רכש קרקעות בראשון לציון וגדרה בשנות ה-80 של המאה ה-19. עלה לארץ. פרסם מאמרים ב\"המליץ\" בנושאי ההתישבות בארץ."},{"i":54703,"n":"שמלנר, אהרן מנבריה","b":"חסיד מהרי\"א מזידיטשוב ואח\"ה מאלסק. רב בנבריה-תרכט. חתן אלמנת ר יעקב קופל צוקרברג מפשמישל."},{"i":54704,"n":"שמלנר, מאיר זידא מדורוהוי ונ\"י","f":"אהרן מנבריה","b":"נכד מהרי\"א מקומרנא. רב בדורוהוי, בוטושן, עבר לארה\"ב-תרפא-ה ונודע כבעל מופת ע\"י רבים אך היה מחלוקת כנגדו מאחרים. ממשתתפי \"אהל מועד\"."},{"i":54705,"n":"שמלצינגר, שמואל שרגא מראדזימין","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":54706,"n":"שמלצר אדוניהו","bt":"1840","dt":"ה'תרנז 1897","bk":[["נפש אדוני’",""]]},{"i":54707,"n":"שמלצר, אדוניה מפעטרואסלע","bt":"תקצט","dt":"תרנח - כב כסלו","b":"דומ\"צ במעדיאסא, פעטרווסעלע. חתנו - ר יהודה קרויס מלקנבך-עורך \"דבר בעתו\". מתורתו ב\"דבר בעתו\" - פאקש תרסט, \"מגד ירחים\" - סיגט תרנח."},{"i":54708,"n":"שמלצר, עקיבא מרזפניק","b":"תלמיד ר אהרן יוסף טמפלר מרזפניק שהזכירו בספרו \"רביד הזהב\"."},{"i":54709,"n":"שמלצר, פנחס מצאנז","b":"פרסם מאמרים ב\"הפרדס\" - צאנז תרצא."},{"i":54710,"n":"שמלקא מאומיאן","b":"רב באומיאן"},{"i":54711,"n":"שמלקס, אהרן","f":"יצחק יהודה","k":"בעל מנחת אהרן","bt":"תרט","dt":"תרלא","b":"תלמיד ר יוסף שאול נתנזון בעל \"שואל ומשיב\". חיבר \"מנחת אהרן\" ונדפס בספר אביו \"בית יצחק\"."},{"i":54712,"n":"שמלקס, אלכסנדר סנדר","f":"שמואל שמלקא מברודי","b":"נכד ה\"תבואות שור\". בניו ר חיים שמואל שמלקא אביו ה\"בית יצחק\", ור ישראל שרגא מזולקוא (תקצב-תרסא)."},{"i":54713,"n":"שמלקס, אלכסנדר סנדר מקראקא","f":"חיים שמואל מקראקא","bt":"תקפג","dt":"תרמט","b":"גביר מחכמי קראקא, אחיו של \"הבית יצחק\". נקבר ליד ר שמעון סופר."},{"i":54714,"n":"שמלקס, גדליה מקולומיאה","f":"מרדכי מפשמישל","k":"בעל אמרי רג\"ש","bt":"תריז","bp":"לבוב","dt":"תרפח - כט טבת","dp":"פשמישל?","b":"נסמך מאת: רבו ודודו ר יצחק שמלקס בעל \"בית יצחק\", ר צבי אורנשטין, ר יצחק אהרן איטינגא, ר שמעון סופר. חתן ר יהושע זילבר מטורנא ועבר לשם. רב בקולומיאה(=קאלאמעא)-תרנח (והיה מחלוקת עם חסידי אטיניא וכן עם המשכילים), פשמישל-תרסד, והיה ממיסדי המזרחי בעירו. חיבר \"אמרי רג\"ש\" פיעטרקוב תרצא, ועוד. לתולדותיו - דברי זכרון מאת אברהם כהנא (אבר\"ך)."},{"i":54715,"n":"שמלקס, זאב הכהן מויטבסק","b":"רב בויטבסק-תר\"מ"},{"i":54716,"n":"שמלקס, יהושע מפרמישלא","f":"שמואל שמלקא מפרג","b":"אבי המשפחה ונקרא בשם אביו - שמלקס. אביו הגביר בפרג - חותנו של המהר\"ל ובנו של ר יעקב מפרג (נפטר שיח)."},{"i":54717,"n":"שמלקס, יצחק יהודה - מהר\"י שמלק","f":"חיים שמואל","k":"בעל בית יצחק","r":"רב דלבוב, אבל בתנובת יהודה (פינק) כתב שנפטר תרס","bt":"תקפח","bp":"למברג","dt":"ה'תרסו","b":"סבו שינה שמו מ\"רוקח\". תלמיד ר מרדכי זאב איטינגא, ר נתן שטרן, ור יוסף שאול נתנזון. חתן הגביר ר אהרן אלרהנד מזורובנא, ובזיוו\"ש חתן ר חיים שמואל בירנבוים בעל \"רחש לבב\". רב בזורובנא-תרטו (והיה שם מחלוקת), רב בבוצאץ על מקום ה\"דעת קדושים\" וקיבל על עצמו להתפלל בטלית בליל שבת כמנהג החסידים, רב בברזן, פרמישלא-תרכט, למברג-תרנב על מקום ר יצחק אהרן איטינגא. חיבר \"בית יצחק\" פרמישלא תרלה, פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - ברלין-קראקא תרנא, \"שערי תורה\" - וארשא תרסג.","bk":[["בית יצחק [שו\"ת]",""],["בית יצחק",""],["דברי יצחק - דרשה להתמנות כרב דלבוב",""],["שיח יצחק - הספד על ר' שלמה קלוגר",""]]},{"i":54718,"n":"שמלקס, משה שאול (מאשל) מקראקא","f":"אלכסנדר סנדר","dt":"תרסו","b":"חסיד צאנז וגביר מחכמי קראקא. אחיינו של ה\"בית יצחק\". פרסם מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":54719,"n":"שמן, יוסף","bt":"תרנח","dt":"תשכא - יב סיון","b":"מגדולי רבני תימן,עלה לא\"י-תש\"ו,רב בתעוז,רב בהרצליה-תשי\"ז"},{"i":54720,"n":"שמן, שלום מתימן","k":"בעל פך השמן","bt":"תר","dt":"תרסה","b":"סגן ראש הישיבה הכללית, ומגדולי המשיבים בדורו. חברו של הראב\"ד ר שלמה צאלח שהתיעץ עמו רבות. חיבר \"פך השמן\" בכת\"י - ורובו אבד. מתשובותיו ב\"חן טוב\" לר יחיא בדיחי ראה הישיבה, וב\"מעשה איש\" להרב יש\"א ברכה."},{"i":54721,"n":"שמסולי, אברהם מליפאנטו-יוון","k":"בעל הצנע לכת","bp":"קשטיליה","b":"מחכמי ספרד, עבר לליסבון-רנב, לאחר הגירוש רנז התישב בליפאנטו-יוון-רנז ור ידידיה הספרדי על מקומו אחריו, עלה לצפת, חיבר ספר \"והאדם ידע\" ובו מספר גם על גירוש ספרד, ספר \"מגיד מישרים\" (כתב היד בספריה הלאומית), \"מלל לאברהם\", ועוד ספרים בכת\"י, בנו ר שם טוב העתיק ספרי אביו."},{"i":54722,"n":"שמסולי, שלמה מטירייא","b":"רב בטיריא-ש'-ת' - בזמן ר גבריאל גליקו. שאלה ממנו לחכמי קושטא."},{"i":54723,"n":"שמסולי, שם טוב מתורכיה","f":"אברהם מליפאנטו","b":"ממשפחה ממגורשי ספרד שהגיעה לתורכיה. העתיק את ספרי אביו וחיבר להם הקדמות ושירים. נזכר ב\"שבט יהודה\"."},{"i":54724,"n":"שמעון","k":"בעל פסקי דינים","b":"תלמיד רש\"י,מגדולי בעלי התוספות-ד'תת\"צ"},{"i":54725,"n":"שמעון","f":"מאיר","k":"בעל שער שמעון","b":"חיבר \"שער שמעון\" ו\"שיח יצחק\" יחד עם ר יצחק."},{"i":54726,"n":"שמעון אליעזר מטורקא","b":"רב בטורקא. תשובה אליו ברמ\"ץ."},{"i":54727,"n":"שמעון בן יעקב אבינו ע\"ה, קבור ליד כפר טייבה","dt":"כד כסלו"},{"i":54728,"n":"שמעון בצלאל שפטל מליובאביץ","k":"רשב\"ץ","b":"משפיע בישיבת \"תומכי תמימים בליובאויץ. תולדותיו בשם \"תולדות הרשב\"ץ\" בתוך - \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":54729,"n":"שמעון דוד","f":"משה יוסף","k":"בעל עונג שבת","b":"חיבר \"עונג שבת\" למברג תרסד, ובתחילה צוואתו באידיש לבניו אברהם מהמבורג וחיים יצחק."},{"i":54730,"n":"שמעון דוד מסערדהאלי","b":"רב בסערדהאלי-תקכא. ישב כנציג קהלת סערדהאלי בבוררות ביערגן-תקכא - בסכסוך שבין קהלות פרשבורג שטמפן וסערדהאלי - יחד עם ר יצחק לנדא מדוקלא ור יצחק איזיק קאליש."},{"i":54731,"n":"שמעון הגדול ממגנצא","f":"רבינו יצחק החסיד","bt":"ד'תשי","b":"מגדולי חכמי מגנצא, פייטן ופיוטיו במחזור האשכנזים (האגדה מספרת על בנו אלחנן שנתפס היה לאפיפיור וחזר בתשובה)."},{"i":54732,"n":"שמעון הדרשן אשכנזי מפפד\"מ ושלו","k":"בעל ילקוט שמעוני","b":"מגדולי ראשוני חכמי פרנקפורט-שנת כ', עבר לשלוניקי? מחבר \"ילקוט שמעוני\". יש המסופקים בכך שהיה חי בפפד\"מ, ועל זמנו דעות חלוקות. בנו - ר אליעזר השמעוני."},{"i":54733,"n":"שמעון הכהן מהדיג'ת-ג'רבה","k":"בעל מטה שמעון","b":"מחמכי הדיג'ת - בשנות ה-תקנ', נזכר ב\"מנוחה ליום כפור\" שבספר \"בני משה\". חיבר \"מעשה חושב - ג'רבא תשג, \"מטה שמעון\" נדפס עם \"בגדי שש\" לר רחמים בוכריץ. חתם עם ר מוסא הכהן במכתב לרבני תונס - אודות המחלוקת בין קהילתם לבני קהילת אלחארה אלכבירה. בנו ר דוד הכהן."},{"i":54734,"n":"שמעון הכהן מירושלים","f":"שאול","k":"שיך אל יהוד","b":"מחכמי ירושלים, בראש הקהלה אחרי ר גדליה קורדובירו, סבל בשנת שפה בפרעות אבן פארוך."},{"i":54735,"n":"שמעון הכהן ממגנצא ופפד\"מ","b":"מגדולי חכמי אשכנז במגנצא,רב בפפד\"מ-רכ על מקום ר נתן אפשטין, ור ישראל ריינבאך על מקומו אחריו. תיקן בפפד\"מ שלא ניתן יהיה לתבוע בני הקהילה זה את זה מחוץ לפפד\"מ, והתיר לעסוק במסחר ביריד בזמן חול המועד בהסכמת מהרי\"ק."},{"i":54736,"n":"שמעון הכהן ממיטאווי","f":"יצחק","k":"בעל שער שמעון","bt":"תריא","bp":"גולדינגן-פלך קורלנד","b":"תלמיד ישיבת וולוזין. מ\"מ בטאלסן, גולדינגן, מטוי(=מיטאוי)."},{"i":54737,"n":"שמעון הכהן ממרוקו","b":"מחכמי מרוקו, חתן ר אברהם ריווח, תלמיד ר רפאל אנקווה. רב ודיין בערים שונות במרוקו, דיין ברבאט אצל ר שאול ן דאנן, עלה לארץ והתישב בחולון, סירב להצעת הרשל\"צ יצחק נסים לשבת בבית הדין הגדול."},{"i":54738,"n":"שמעון הכהן מפפד\"מ","f":"שלמה","b":"מראשי קהילת פפד\"מ - בעל תואר \"מורנו\"."},{"i":54739,"n":"שמעון הכהן מצירוויץ","b":"מו\"צ בציראוויץ-תר\"מ"},{"i":54740,"n":"שמעון הכהן מתימן","f":"יוסף","k":"בעל סגולת השוחטים","bt":"[תר]","bp":"כפר תאלבי-ד'מאר-תימן","b":"תלמיד מרי יוסף יתים מגוראן שבמחוז ירים. נסמך לרבנות ע\"י בית הדין בצנעא, רב בכפר תלאבי-ד'מאר. חיבר ספר בהלכות שחיטה \"סגולת השוחטים\"-תרפג, \"פרי מגדים\" על השו\"ע בדרך סוד, חיבר שירים היתוליים."},{"i":54741,"n":"שמעון הלוי (לם?) מפדובה","f":"משה או משולם","b":"רב בפדובה."},{"i":54742,"n":"שמעון הלוי מברעזי","b":"רב בברעזי-תר\"ל"},{"i":54743,"n":"שמעון הלוי מצישינוב","b":"רב בצישינוב-תרצו."},{"i":54744,"n":"שמעון המעילי","k":"ר' שמעון המעילי","b":"מגדולי חכמי דורו-שנת ש'"},{"i":54745,"n":"שמעון הצדיק, משיירי כנה\"ג, קבור בירושלים","r":"אב\"ד בוטשאטש ומלפנים יאזלוביץ","dt":"כט תשרי"},{"i":54746,"n":"שמעון וולף מברלין","f":"ברוך בראנדעס מפרג","k":"בעל ביאור נבואה של","dt":"תעג - ט אדר","b":"מורה בברלין. בזמן הכתרת המלך פרידריך הראשון בברלין - פרסם \"ביאור סוד הנבואה של מלך דוד\" ובו ביאור ע\"פ צירופי אותיות וגימטריאות על פרק כא בתהלים - המראה בנבואה על מינוי המלך הגרמני, והדבר התפשט בין היהודים ובין הגויים, עד שקם המלומד יבלונצקי בציווי המלך וחקר את הענין."},{"i":54747,"n":"שמעון וולף מדאראהוי","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":54748,"n":"שמעון וולף מחמלניק","k":"בעל כבוד הבית","b":"רב בחמלניק-תס\"ז"},{"i":54749,"n":"שמעון וולף מפינטשוב","b":"מגדולי פינטשוב-ת\"כ","bk":[["כבוד חכמים","אגדות ירושלמי"]]},{"i":54750,"n":"שמעון יונה מקזאל","b":"רב בקזאל - איטליה. תשובה אליו ב\"דבר שמואל\"-תל."},{"i":54751,"n":"שמעון יוסף מאויפאלו","b":"רב באויפאלו"},{"i":54752,"n":"שמעון כץ מזולקוא","f":"יעקב קופל","b":"מחכמי זולקוא, חתם-שפו על תקנה בזולקוא."},{"i":54753,"n":"שמעון מאברשיצק","b":"רב באבערשיצק-תק\"פ"},{"i":54754,"n":"שמעון מאוסטרהא","f":"שמעון","dt":"תקט - י אייר","dp":"אוסטרהא","b":"פרנס באוסטרהא יחד עם ר שמואל ר יעקב'ס, ועם ר מרדכי הלפרין הרופא."},{"i":54755,"n":"שמעון מאלטונא","f":"יונה","dt":"תקנג - יב אייר","dp":"אלטונא","b":"מחכמי אלטונא. (באוצר הרבנים תאריך פטירתו - תקנב)"},{"i":54756,"n":"שמעון מאנקונא הי\"ד","f":"מנחם","dt":"שיו - ג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":54757,"n":"שמעון מארץ ישראל","f":"נחמן מהורודנקא","b":"עלה לארץ עם אביו."},{"i":54758,"n":"שמעון מבירז","b":"מרבני בירז"},{"i":54759,"n":"שמעון מבסקביץ","f":"נפתלי היידא","b":"רב בבסקביץ-ת'."},{"i":54760,"n":"שמעון מברודשין","b":"עבר מברודשין לסיגט-תרלח. תשובה אליו ב\"מנחת יהודה\"."},{"i":54761,"n":"שמעון מבריסק","b":"ראש ישיבה בבריסק-של בזמן ר קלמן קלונימוס שור."},{"i":54762,"n":"שמעון מבריסק","f":"שלמה זלמן","b":"מחכמי בריסק, תשובות ממנו ב\"גבעת שאול\"."},{"i":54763,"n":"שמעון מגיד מישרים מדולינא","b":"מתורתו ב\"ברית אברם\"."},{"i":54764,"n":"שמעון מגריידיץ","f":"משה","b":"דיין בגריידיץ, חתם-תקעב עם ר יצחק מרדכיור יקותיאל בן משה."},{"i":54765,"n":"שמעון מוילנא","dt":"תקסט - ו טבת","b":"מו\"צ בווילנה"},{"i":54766,"n":"שמעון מוילנא","f":"אליהו","dt":"תקעו","dp":"וילנא","b":"מחכמי וילנא."},{"i":54767,"n":"שמעון מוילנא","f":"זאב וולף","dt":"תקץ - ד-כב סיון","dp":"וילנא","b":"מראשי קהילת וילנא. פגש את המלך סטניסלב בזמן הדיון בסיים אודות היהודים. היה מתומכי ר שמואל בן אביגדור-רבה האחרון של וילנא."},{"i":54768,"n":"שמעון מוילנא","f":"יעקב יעקובקי","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה."},{"i":54769,"n":"שמעון מוינה","b":"מגדולי ווינה אייזנשטט,בגירוש עבר לזלקווא-ת\"ל"},{"i":54770,"n":"שמעון מזולקוא","f":"אפרים יהודה","k":"בעל חלק שמשון","b":"ר\"מ בזולקוא. הו\"ל ספר הגלגולים-תמח."},{"i":54771,"n":"שמעון מטוליטולא (טולידו)","f":"הרא\"ש","dt":"קב - יב אלול","b":"מגדולי חכמי דורו,פוסק,מרביץ תורה בטוליטולא"},{"i":54772,"n":"שמעון מיונביל","b":"מגדולי חכמי צרפת,מבעלי התוספות-ד'תתק\"נ"},{"i":54773,"n":"שמעון מיכל מוינה ופרשבורג","b":"סוכנו של ר שמואל אופנהיים בוינה. ראש היהודים של קהלת פרשבורג-תנט (בפרבר שלוסגרונד - בזמן איסור ישיבת היהודים בפרשבורג העיר) והסביבה, מקורב למלכות, עזר ליהודי פרשבורג והסביבה. היה שליח צבור בפרשבורג. בניו: אברהם מראשי קהלת פרג, יחיאל מאנסבך, שמואל, מאיר מפרשבורג - שופט היהודים (במינוי המלך), מיכל לעזר מפרשבורג, וחתניו - ברוך שלזינגר מפרשבורג, לצרוס ון גלדרן מוינה וגרמניה (נכדו - המשורר היינריך היינה)."},{"i":54774,"n":"שמעון מינובא","b":"חתן ר עוזר ממזריטש-ליטא. תלמיד החוזה מלובלין. רב בינובא-ליטא."},{"i":54775,"n":"שמעון מירושלים","f":"יעקב","b":"בשליחות קהלת ירושלים-לפני תע. נזכר ב\"שפת אמת\" לר\"מ חאגיז."},{"i":54776,"n":"שמעון מיריסלוב","dt":"תרי - טז תשרי","b":"מקובל,פועל ישועות,רב ביעריסלוב"},{"i":54777,"n":"שמעון מכלוף","b":"קיבל ספר עם הקדשה מר רחמים פרנקו-רבה של חברון."},{"i":54778,"n":"שמעון מלבוב","f":"מאיר","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה. (יתכן שהיו שני רבנים באותו השם שנהרגו באותו היום)."},{"i":54779,"n":"שמעון מלבוב","f":"יצחק איזיק","dp":"לבוב","b":"מו\"ץ בלבוב."},{"i":54780,"n":"שמעון מלובלין","dt":"תכד - ט אדר","b":"רב בלובלין"},{"i":54781,"n":"שמעון מלמברג","b":"מו\"צ בלבוב"},{"i":54782,"n":"שמעון ממראקש","f":"ישכר","dt":"רכה","dp":"מראקש","b":"מחמכי מראקש הקדומים."},{"i":54783,"n":"שמעון מנדבורנה","dt":"תקסב - יא תמוז","b":"רב בנדבורנא"},{"i":54784,"n":"שמעון מסופקוב","f":"שלמה זלמן","dt":"יב חשון","b":"תלמיד החוזה מלובלין. צדיק נסתר ואיש קדוש. החוזה מלובלין אמר עליו ועל ר שמעון מירוסלב \"יש לי שני שימיליך (כינוי לסוסים לבנים) ואם היה לי שלישי הייתי מביא את המשיח\". נאמר שזכה לגילוי אליהו."},{"i":54785,"n":"שמעון מסלונים","f":"דב בר","k":"בעל מנחה בלולה","b":"חתן ר צבי הירש עטיאש-נכד ר יוסף בעל \"ראש יוסף\" מסעלץ. רב בסלונים-תקפ. חתנו - ר משה אברהם איזנשטט."},{"i":54786,"n":"שמעון מסמרגון ווילנא","f":"שמואל","dt":"תקפב - טז אדר","dp":"וילנא","b":"מחכמי וילנא."},{"i":54787,"n":"שמעון מספרד","f":"אברהם","b":"מגדולי הפוסקים בספרד-שנת ס'"},{"i":54788,"n":"שמעון מסקאהל","b":"רב בסקול-תקעח, זליחוב."},{"i":54789,"n":"שמעון מסקאלא","b":"רב בסקאלא-תרע."},{"i":54790,"n":"שמעון מפוריצק","dt":"תרס","b":"רב בפאריצק-תרמב, וחתנו ר מרדכי צוקר על מקומו אחריו-תרסח."},{"i":54791,"n":"שמעון מפלאצק וארץ ישראל","b":"עלה לארץ לפני תקמו."},{"i":54792,"n":"שמעון מפלוגיאן וירושלים","f":"מנחם נחום","dt":"תרב - בערך","dp":"ירושלים","b":"רב בפלונגיאן, עלה לירושלים-תקפז."},{"i":54793,"n":"שמעון מפלירא-צרפת","b":"מגדולי חכמי צרפת-שנת מ'"},{"i":54794,"n":"שמעון מפרג","f":"זאבלה משנייטוך","b":"מגדולי חכמי פרג"},{"i":54795,"n":"שמעון מפרשבורג","dt":"תלד - כו אלול","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":54796,"n":"שמעון מפרשבורג","f":"דוד","b":"מחכמי פרשבורג, חתם-תקסז על כתב מנוי רבנות לחת\"ס."},{"i":54797,"n":"שמעון מקאסווע","f":"דוד","b":"רב בקאסווע-תק. הניח כתבים עם חדושי תורה ואבדו. אחיו - ר לוי בעל עטרת ראש."},{"i":54798,"n":"שמעון מקידאן","f":"אברהם","b":"דיין בקידאן. חתם-תקעד בערך בענין עגונה."},{"i":54799,"n":"שמעון מקריפטש","dt":"תקלה - ל כסלו","b":"רב בקריפטש"},{"i":54800,"n":"שמעון מקרק (ליד קידאן)","f":"שבתי","dt":"תקפב - ד תמוז","dp":"וילנא","b":"מו\"צ בקרוק מחוז קידאן."},{"i":54801,"n":"שמעון מרדיחוב","b":"רב ברדיחוב-תרל."},{"i":54802,"n":"שמעון מרדכי מניש","f":"רחמים","b":"דיין מחכמי ניש-תקן בערך."},{"i":54803,"n":"שמעון מרוגוזן","b":"רב ברוגוזאן,פרדן-תק\"ע"},{"i":54804,"n":"שמעון מרוהטין","b":"רב ברוהטין. תשובה אליו בנט\"ש."},{"i":54805,"n":"שמעון מרוסצוק","f":"שלמה","k":"בעל מטה שמעון","dt":"תקעט","b":"רב ברוסג'וק. חיבר גם \"מירא דכיא\"."},{"i":54806,"n":"שמעון ן, אברהם","f":"יהודה","k":"בעל סגולות המלכים","b":"חיבר ספר באציטגנינות וחקירות בחכמת המאגיאה בשם \"סגולות המלכים\"."},{"i":54807,"n":"שמעון ן, אהרן מירושלים","dt":"תרנב - ז אב","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":54808,"n":"שמעון ן, אהרן מצפת","f":"שלמה מצפת","bt":"תרל","b":"נכד ר יעקב ן שמעון (שנספה ברעש-תקצז). מחכמי צפת, בשליחות הקהלה, רב בבוכרה, חזר לצפת."},{"i":54809,"n":"שמעון ן, דוד - דב\"ש","f":"שמעון","k":"צוף דבש בעל שער המטר","bt":"תקפד-ו","bp":"ראבאט (מרוקו)","dt":"תרם - יח כסלו","dp":"ירושלים","b":"רב בראבאט, בשנת תריד עלה עם תלמידים וחברים לירושלים - וביניהם ר אליעזר הלוי בן טובו (בעל \"פקודת אליעזר\") ור יוסף ארואץ. בעקבותיו עלו יהודים רבים ממרוקו בשנת תרלב הגיע מספרם לאלף נפש, הם נפרדו מן העדה הספרדית ויסדו עדה לעצמם. ר דוד עמד בראש העדה, הקים בית דין ותלמוד תורה, יסד את שכונת \"מחנה ישראל\"-תרכח השכונה הראשונה מחוץ לחומות. הדפיס \"ספר התקנות והמנהגים\" להרב גאגין והוסיף עליהם. חיבר \"שער החצר\" ירושלים תרכב, \"שער המטרה\" ירושלים תרכו. בניו: ר רפאל אהרן, ר יקותיאל, חיותו ממצרים, ר מסעוד."},{"i":54810,"n":"שמעון ן, יהודה מירושלים","b":"מחכמי ישיבת \"חסד לאברהם\" בירושלים-תקיח."},{"i":54811,"n":"שמעון ן, יקותיאל חיים","f":"דוד - דב\"ש","bt":"תריח","bp":"ירושלים","dt":"תרעד - כב אלול","dp":"מכנאס","b":"מחכמי ירושלים, רבה של עדת המערבים שם-תרן, בשנת תרעד בשליחות במרוקו ושם נפטר. אחיו של ר רפאל אהרן."},{"i":54812,"n":"שמעון ן, מנצור מצפת","f":"יעקב","k":"בעל שמן המאור","bt":"תרעב","bp":"צפת","dt":"תשנח - כ שבט","dp":"ירושלים","b":"לאחר שנתייתם גדל אצל דודו ר אהרן ן שמעון - רבה של צפת. תלמיד ר מאיר רובמן מחיפה, תלמיד בישיבת פורת יוסף אצל ר עזרא עטייה. ראש ישיבת פורת יוסף, ומתלמידיו ר עובדיה יוסף, ר מרדכי אליהו, ועוד רבים. חברו בלמוד קבלה של ר אפרים הכהן מגדולי המקובלים בירושלים. בנו ר מרדכי ן שמעון נספה בחיי אביו."},{"i":54813,"n":"שמעון ן, מסעוד חי ממצרים","f":"דוד - דב\"ש","k":"בעל שערי משפט","bt":"תרכט","bp":"ירושלים","dt":"תרפה - כ ניסן","dp":"קהיר","b":"רב במצרים, חתן אחיו ר רפאל אהרן ן שמעון וכיהן ברבנות אחר פטירת אחיו. חיבר \"שערי משפט\" קהיר תרעז, \"שם חדש\", ועוד. וכן תרגם את השלחן ערוך לערבית. ?? לא באוצר - שערי משפט ??"},{"i":54814,"n":"שמעון ן, מרדכי חזקיה","f":"מנצור","k":"בעל שמן המשחה","r":"ראש כולל נזר אהרן","bt":"תשיג בערך","bp":"ישראל","dt":"תשנד - ב סיון","b":"מקובל מחכמי ארץ ישראל, שהצניע עצמו וברח מרבנות ומפרסום.","bk":[["שמן המשחה - או\"ח, יו\"ד, ואה\"ע, כתובות, קידושין, ותנ\"ך",""]]},{"i":54815,"n":"שמעון ן, משה מספרד","f":"שלמה","b":"מקובל מחכמי בורגוש-ספרד, תלמיד הרמבן בקבלה, ותלמיד ר יעקב הכהן ור יצחק הכהן. מתלמידיו ר יצחק דמן עכו, ור יצחק ן סהולה."},{"i":54816,"n":"שמעון ן, עזריה מפוזנא","b":"מגדולי חכמי פוזנא-שט\"ו"},{"i":54817,"n":"שמעון ן, עמרם ממרוקו","f":"יחיא","k":"בעל אשמח","bt":"תרב","bp":"מוגאדור-מרוקו","dt":"תשכג - א כסלו","dp":"טבריה","b":"רב במוגאדור. עלה לארץ-תשיד והתישב בטבריה ולימד בישיבת ר מאיר ועקנין. חיבר פירוש לתורה בשם \"אשמח\" ירושלים תשנז."},{"i":54818,"n":"שמעון ן, צמח מירושלים","b":"ראש ישיבת \"חסד לאברהם\" בירושלים-תקז בערך. אחיו - ר יהודה מירושלים."},{"i":54819,"n":"שמעון ן, רפאל אהרן מירושלים","f":"דוד - דב\"ש","k":"בעל נהר מצרים","bt":"תרח","bp":"ראבאט","dt":"תרפט - יב חשון","dp":"תל אביב","b":"עלה לירושלים עם אביו, שימש ראש ישיבה בירושלים. רב יוצאי המגרב בירושלים לצדו של אביו ועל מקומו אחריו. בשליחות במרוקו-תרמז ויסד בפאס חברת \"דובבי שפתי ישנים\" במטרה להוציא לאור כתבי יד עתיקים של חכמי המערב. בהיותו בצפרו-תרן ניצל מהשיטפון שהביא אסון כבד על הקהלה, וסיפר על כך בהקדמה שכתב ל\"עת לכל חפץ\" לר יעקב ן צור. רב ראשי במצרים-תרנא על מקום ר יום טוב ישראל - שעלה לארץ - והפציר בו למלא את מקומו במצרים, אחיו ר מסעוד חי היה גם חתנו ורב ל לצדו במצרים, ועל מקומו לאחר שחזר לארץ. בסוף ימיו-תרפא חזר לארץ והשתקע ביפו, ותל אביב. חיבר \"נהר מצרים\" אלכסנדריה תרסח, \"נהר פקוד\", \"טוב מצרים\", ועוד. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":54820,"n":"שמעון ן, רפאל צמח מירושלים","f":"דוד","dt":"תקם - כג סיון","dp":"ירושלים","b":"מחכמי ירושלים בזמן ר יום טוב אלגזי ור שלום שרעבי, וחתם עמם בפסקיהם. ראש ישיבת \"חסד לאברהם\"-תקיח."},{"i":54821,"n":"שמעון ניישטעדל","f":"פיבל","b":"חיבר לוח לקורות עם ישראל בסדר לוח השנה-תקצז בשם \"באר לחי רואי\"."},{"i":54822,"n":"שמעון עקיבא בער מאופיבך ווינה","k":"בעל עבודת הבורא","b":"מקובל, רב בוינה-תמ. חיבר \"עבודת הבורא\"."},{"i":54823,"n":"שמעון פיבל","dt":"שצז - כג ניסן","b":"רב בפרעמיסלא"},{"i":54824,"n":"שמעון פנחס מאדרינופול","b":"רב באדרינופול-שנות ה-ת'."},{"i":54825,"n":"שמעון ראובן מצידון","b":"דיין בצידון-תל בערך אצל ר שלמה בן בנימין הלוי עם ר יצחק נחמיה."},{"i":54826,"n":"שמעון שבתי מצפת","b":"מחכמי צפת, בשליחות במרוקו-תרסג."},{"i":54827,"n":"שמעון שלמה המגיד מסאווראן","f":"אברהם הרופא מסטאמבול","dt":"תקסב - כא אייר","b":"תלמיד ר דב בער ממזריטש. נשבה ע\"י ההידמקים ונמכר לעבד בסוריה, נפדה לאחר 15 שנה ע\"י יהודי אשכנזי שלקחו כחתן לבתו - וויטא. חזר לסאווראן ונתקבל למגיד מישרים. מתורתו בספר בנו \"לקוטי שושנים השלם\". תולדותיו ב\"צבי לצדיק\"."},{"i":54828,"n":"שמעון שלמה משלוניקי","b":"דיין בשלוניקי-תקלד."},{"i":54829,"n":"שמעון שלמה משלוניקי - הרופא","dt":"תקמא - אייר","dp":"שלוניקי","b":"רופא בשלוניקי, נפטר במגפה הגדולה-תקמא."},{"i":54830,"n":"שמעון שרגא מראגולה","b":"רב בראגולע-תר\"מ"},{"i":54831,"n":"שמעונוביץ, בנימין ממינסק","b":"ר\"מ במינסק-תר\"פ"},{"i":54832,"n":"שמעונוביץ, יוסף בנימין מירושלי","f":"יהודה צבי","k":"בעל ימין יוסף","dt":"תרפז - ה סיון","dp":"ירושלים","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבאלאש יארמוט. חתן אחי רבות - ר שמעון דייטש מירושלים. עלה לירושלים-תרלב והיה ראש השוחטים שם ור\"מ בישיבת חתם סופר בירושלים. פרסם מאמרים ב\"ועד חכמים\" - ירושלים תרפג."},{"i":54833,"n":"שמעונוביץ, ישעיה","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תורה אור\" - שנחאי תשו."},{"i":54834,"n":"שמעונוביץ, נח מזכרון יעקב","f":"בנימין שמעונוביץ","dt":"תשטו - ד אייר","b":"רב פעלים,מרביץ תורה בישיבת כנסת יחזקיה בזכרון יעקב"},{"i":54835,"n":"שמעוני, אליהו","b":"רב העיר גפצא"},{"i":54836,"n":"שמעוני, שלום מתונס","f":"אליהו","k":"בעל גנזי שלום","bt":"תקמג","bp":"גפצא-תונס","dt":"תרכד","b":"מחכמי תונס, תלמיד ר משה שלום בעל \"ישמח משה\". חברם של ר ישועה בסיס, ר אברהם הכהן יצחקי בעל \"משמרות כהונה\". רב ודיין בגפצא, רופא ובקי בקמיעות, ונחשב לבעל נס."},{"i":54837,"n":"שמעיה אבטליון מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":54838,"n":"שמעיה גאון מעכו ארץ ישראל","b":"גאון ארץ ישראל וראש הישיבה בעכו בזמן רב שרירא גאון."},{"i":54839,"n":"שמעיה הכהן ממרוקו","f":"יוסף","b":"רב בדברו-מרוקו, חתם-תקמז עם ר דוד ן חסין, ור משה אלמליח."},{"i":54840,"n":"שמעיה הכהן ממרוקו","f":"יוסף","b":"מחכמי דבדו-מרוקו. חתם-תקצו עם ר שמואל הכהן."},{"i":54841,"n":"שמעיה ואבטליון, קבורים בגוש חלב","r":"אב\"ד סקידל ואיישישוק וראייסין","dt":"א אלול"},{"i":54842,"n":"שמעיה מאיר הלוי מאלטונא","f":"נתן","dt":"תרמז - טו סיון","dp":"אלטונא","b":"תלמיד ר יעקב עטלינגר. הגיע מקרלסרוהא עם חברו ר געטשליק שלזינגר ועם ר יעקב עטלינגר, דרשן בואנדסבק, מחכמי הקלויז הספרדי \"זומביל ישיבה\" באלטונא."},{"i":54843,"n":"שמעיה מברלין","f":"אברהם ישכר בר","dt":"תסט - כא ניסן","dp":"ברלין","b":"רב בפפד\"מ-תמז וגליל הקוהרמק וגם על ברלין, עבר לברלין-תנב. תיקן תקנות בעיקר בענין שחיטות ונזכר ב\"ברית מטה משה\". מתלמידיו ר מנחם מנדל בן צבי הירש בעל \"צנצנת מנחם\". תשובה ממנו גם ב\"אבני שהם\". חתנו ר יהודה ליב דרשן מפרג."},{"i":54844,"n":"שמעיה מווילהן","dt":"תצה - א שבט","b":"רב בווילהן"},{"i":54845,"n":"שמעיה מטומשוב","f":"יהונתן","k":"בעל סייעתא דשמיא","b":"רב בטאמשוב-תק\"ך. חיבר \"סיעתא דשמיא\" דירנפורט תקנד."},{"i":54846,"n":"שמעיה משלוניקי","f":"אליקים","dt":"שח - כט תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":54847,"n":"שמעיה רץ אשכנזי משלוניקי","f":"אליעזר ליברמן רוייו","dt":"רסח - ד כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי בן עדת אשכנז."},{"i":54848,"n":"שמעיה תלמיד רשי","k":"רבינו שמעיה","b":"תלמיד רש\"י. מחכמי צרפת, רב בטרוייש-ד'תתק\"ב, חותן הרשב\"ם. בנו - ר משה"},{"i":54849,"n":"שמ\"ר, אברהם מארה\"ב","f":"נחום מאיר שייקביץ","bp":"פינסק","b":"סופר ועו\"ד בארה\"ב"},{"i":54850,"n":"שמריה","f":"שמחה","k":"בעל כל בו","b":"מגדולי הפוסקים-שנת ס'"},{"i":54851,"n":"שמריה האיקריטי","b":"פירושו על מזמור קיט ב\"מדרש שוחר טוב\". ר שלמה הלוי אלקבץ הזכיר את פירושיו."},{"i":54852,"n":"שמריה הלוי מקושטא","b":"מראשי הקהלה האשכנזית בקושטא-שנה, עם ר יוסף נתנאל."},{"i":54853,"n":"שמריה הלוי מתימן","f":"עזרא","b":"רב בתימן-קן, ועסק בעניני לוחות עיבור השנה."},{"i":54854,"n":"שמריה הפייטן","f":"אלקנה","b":"פייטן מחכמי יוון-ק', והיה שם גם פייטן בשם ר אלקנה בן שמריה - כנראה בנו או אביו."},{"i":54855,"n":"שמריה זלמן מלייפניק","f":"יעקב אברהם","k":"בעל אבני שהם","b":"ראש ומנהיג בלייפניק,דורש טוב בלונדון-תפ\"ד"},{"i":54856,"n":"שמריה מארץ ישראל","f":"יצחק","b":"בשליחות קהילת החסידים ברומניה. הסכים-תקנז על \"יסוד האמונה\" לר ברוך מקוסוב. בתו היתה חמותו של ר יצחק מייזלש."},{"i":54857,"n":"שמריה מבוצאץ","b":"מחכמי בוצאץ. תשובה אליו ב\"זכר לישעיהו\"-תקצא."},{"i":54858,"n":"שמריה מהרמילוב וירושלים","f":"יעקב","k":"בעל ראש פנה","dt":"תריז - כב טבת","dp":"ירושלים","b":"תלמיד ר אפרים זלמן מרגליות, ומוזכר בספרי ר שלמה קלוגר. רב ברימלוב(=הרמילוב). עלה לירושלים. חיבר \"ראש פנה\", ואולי הוא החכם מחבר \"קהלות יעקב\" למברג תריב, ועוד."},{"i":54859,"n":"שמריה מויסוקי","b":"רב בוויסאקי-תק\"י"},{"i":54860,"n":"שמריה מכרתים","f":"אליהו הפרנס","b":"גדול בתורה חכמה ומדעים,מקורב למלכות,מחכמי כרתים-ס\"ה,עבר לספרד-קי\"ב"},{"i":54861,"n":"שמריה מלבוב","f":"אליעזר","dt":"תט - כז טבת","dp":"לבוב","b":"מרביץ תורה בלבוב"},{"i":54862,"n":"שמריה מלכוויץ","dt":"תקכ","dp":"המבורג","b":"רב בלכוויץ"},{"i":54863,"n":"שמריה ממצרים","f":"אלחנן","b":"רב במצרים בזמן רב שרירא גאון ורב האי גאון."},{"i":54864,"n":"שמריה מנעשויז ולכוביץ","f":"אפרים פישל מנעשויז","dt":"תקך","dp":"המבורג","b":"אב\"ד נעשויז."},{"i":54865,"n":"שמריה מפוסטאט","f":"רבינו אלחנן","k":"רבינו שמריהו","dt":"ד'תשעג","b":"מגדולי הראשונים,ראב\"ד בפוסטט שבקהיר"},{"i":54866,"n":"שמריה מקוברין ולובאשוב","b":"רב בקוברין, לובאשוב(=ליובישוב). בנו - ר אברהם יוסף אבא מסורוקה ודינאווא."},{"i":54867,"n":"שמריה מקראקינוב וירושלים","f":"בצלאל","dt":"תרך - יב אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":54868,"n":"שמריה משטיפי","f":"פרנס","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":54869,"n":"שמריה משפיירא","b":"מגדולי חכמי אשכנז בבעלי התוספות,מרביץ תורה בשפירא-ד'תתק\"פ"},{"i":54870,"n":"שמריה שמרל הכהן מלבוב","b":"חתם-תן בקוליקוב על תקנת קהלת זולקוא."},{"i":54871,"n":"שמריה, דוד","f":"אברהם","k":"בעל תורה אחת","b":"מקובל, מחכמי טורקיה, מרבני שלוניקי, חיבר הגהות לקיצור הזוהר \"תורה אחת\" \"בשם דוד הקטן\"-שסד. ?? לא באוצר ??"},{"i":54872,"n":"שמריה, יעקב משלוניקי","dt":"שפט - טו אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":54873,"n":"שמריה, נעמן משלוניקי","f":"אברהם","dt":"רצו - חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":54874,"n":"שמרינר, פנחס","b":"רב-שנת ת\"ק"},{"i":54875,"n":"שמרל מבורכובקה","dt":"תקמה - א כסלו","b":"רב בבורוכובקה"},{"i":54876,"n":"שמרל מווארחיבקא","dt":"תקלו - ב כסלו","b":"רב בוואחיבקה. תלמיד הבעשט, רב בסאווראן, מנהיג עדת חסידים. בניו ר יוסף פרידל, ור דוד דניאל מטשיטשלניק."},{"i":54877,"n":"שמרל מלומבעלע","b":"רב בלומבעלא"},{"i":54878,"n":"שמרלינג, פסח פתחיה מרוזדוביץ","b":"שו\"ב ברוזדוביץ. תלמיד ר דוד רייז שהזכירו בספרו \"שושנים לדוד\"."},{"i":54879,"n":"שמרלינג, שמואל משקלוב וחברון","b":"מחסידי חב\"ד הראשונים בחברון."},{"i":54880,"n":"שמרלינגר, מאיר הלוי","f":"משלם זלמן","b":"רב-שנת ת\"ק"},{"i":54881,"n":"שמרלר, אליהו צבי מברודשין","f":"ישראל מברודשין","k":"בעל תולדות הראבד","bt":"תרלג","bp":"ברודשין","dt":"תרץ","b":"תלמיד ביהמד\"ר בוינה. עבר לארה\"ב-תרס. פרסם מאמרים ושירים בכתבי עת ביאס ובאמריקה, וחיבר גם בגרמנית. חיבר \"תולדות הראב\"ד\" למברג תרן, ועוד."},{"i":54882,"n":"שמרלר, אליהו שמואל מוינה","f":"יעקב ישראל","k":"בעל דברי אליהו","b":"עלה לארץ, תלמיד רד\"ב מטשבין, ולמד עם ר גרשון לפידות. חסיד קלויזנבורג וראש ישיבת צאנז בנתניה. חתן ר מנחם מנדל גפנר. חיבר \"דברי אליהו\" - קובץ שיעוריו בישיבה."},{"i":54883,"n":"שמרלר, אפרים מרדכי","f":"מרדכי ממיקולייב","bt":"תרכד","dt":"תרצט","b":"חתן ר מאיר חיים אוירבך ממנוסטרישץ. שו\"ב במנוסטרישץ. עלה לארץ, בנו ר נפתלי צבי מוינה."},{"i":54884,"n":"שמרלר, בנימין מסטניסלב","f":"ישראל מברודשין","k":"בעל אהבת יהונתן","bt":"תרם","bp":"ברודשין","dt":"תש","b":"חתן ר יהושע העסל מדולינא. חיבר גם \"אמרי בנימין\". הוציא לאור ספרים מכתבי יד. חיבר \"אהבת יהונתן\" בילגוריא תרצב. פרסם מאמרים ב\"כתר תורה\" - גרבה תרצח."},{"i":54885,"n":"שמרלר, יוסף מסלטוינה","b":"עבר מסלטוינה לארה\"ב. חיבר אילן יוחסין למשפחתו."},{"i":54886,"n":"שמרלר, יעקב ישראל","f":"משה מאיר מליטוביסק","bt":"תרמב","dt":"תשי","dp":"ירושלים","b":"חסיד צאנז ובובוב. חתן ר אליהו שמואל וין מבוברקא."},{"i":54887,"n":"שמרלר, יעקב שלמה מגורא הומורא","f":"מרדכי ממיקולייב","k":"אדמור מגורא הומורא","dt":"תרפח","b":"תלמיד ר יעקב הורביץ מדלטין. חתן ר יואל מושקוביץ משאץ. רב בווסלי, אדמור בגורא הומורא-תרסא. בנו ר מאיר על מקומו אחריו כאדמור."},{"i":54888,"n":"שמרלר, מאיר מגורא הומורא","f":"יעקב שלמה מגורא הומ'","k":"אדמור מגורא הומורא","b":"חתן ר אלימלך רובין מיברוב ונכדתו של השר שלום. אדמור מפרימישלן בגורא הומורא על מקום אביו (והיה מחלוקת עם הרב יעקב משולם גינצבורג וגיסו הרב אברהם משה באבד). בנו ר נפתלי מרדכי אדמור מפרימישלן בעכו, בנו ר שלום אדמור מפרימישלן בחיפה."},{"i":54889,"n":"שמרלר, מרדכי ממיקולייב","f":"נפתלי צבי מברודשין","k":"אדמור ממיקולייב","dt":"תרכד - ו אב","dp":"סלטוינה או צפת","b":"אדמור במיקולייב. חתן ר אברהם חיים רדליך ממיקולייב (חתנו של ר מאיר מפרימישלן). בנו ר יעקב שלמה אדמור מפרימישלן בגורא הומורא. ממשפחת אדמורי פרמישלן. אדמור במיקולייב על מקום חותנו. עזב את האדמורות ועלה לצפת."},{"i":54890,"n":"שמרלר, מרדכי צבי הרש מצפת","f":"משה מאיר מבוברקא","bt":"תרמז","bp":"צפת","dt":"תשכד","b":"ביקר עם אביו אצל האדמור משיניבה-תרנה. תלמיד ר אברהם פודהוריץ בצפת. ביקר אצל אדמורים באירופה. עבר לירושלים והיה מקורב לצדיקי ירושלים. חתן ר יעקב מרדכי אלבוים מצפת, ובזיוו\"ש חתן ר בנימין יהודה ליב ברנשטין (אלמנת יצחק מושקין הי\"ד)."},{"i":54891,"n":"שמרלר, משה חיים מציריך","f":"נפתלי צבי מוינה","b":"רב בציריך."},{"i":54892,"n":"שמרלר, משה מאיר מצפת","f":"מרדכי ממיקולייב","dt":"תרעט","dp":"קושטא","b":"חתן ר נפתלי בער מליטוביסק ועבר לשם, ישב אצל הדברי חיים כ-8 שנים. עלה לצפת-תרם והיה מראשי חסידי צאנז. בתרעח בשליחות קהילת צפת ונפטר בדרכו."},{"i":54893,"n":"שמרלר, נפתלי מרדכי משאץ","f":"מאיר מגורא הומורא","bp":"גורא הומורא","b":"חתן ר מאיר מושקוביץ האדמור משאץ."},{"i":54894,"n":"שמרלר, נפתלי צבי מוינה","f":"אפרים מרד' מנוסטרישץ","bt":"תרמח","dt":"תשח","b":"חסיד צורטקוב. נכד ר משה חיים בירנבוים הרב במנוסטרישץ. רב בוינה ור\"מ בישיבה שם. ובין תלמידיו ר יעקב הורנשטין מנייטרא, ר ישראל השל בן האדמור מקופיטשיניץ. חתן ר יעקב מאיר בלייך.","bk":[["אמרי נפתלי",""]]},{"i":54895,"n":"שמרלר, צבי","b":"רב ור\"מ בווינה,עלה לא\"י-תרצ\"ח"},{"i":54896,"n":"שמרלר, שלום מגורא הומורא","f":"מאיר מגורא הומורא","bt":"תרסט","bp":"גורא הומורא","dt":"תשמד","dp":"ירושלים","b":"חתן ר לוי יצחק לייפר האדמור מנדבורנה. עלה לארץ וכיהן כאדמור בחיפה."},{"i":54897,"n":"שמרת, אברהם יעקב מקראקא","f":"מנשה","bt":"תרל","bp":"קראקא","dt":"תשב","b":"נשלח ע\"י האדמור משיניבה ללמוד בישיבת בובוב והיה שם תלמיד ר פנחס דמביצר ור שבתי ברטרם. (האדמור שלח חלק מחסידיו לבובוב וחלק לציעשינוב). חתן ר דוד קגיל מוישניצה. נספה בשואה."},{"i":54898,"n":"שמרת, יצחק","b":"חתן ר יוסף הלל צוקר."},{"i":54899,"n":"שמרת, ישראל מקראקא","b":"גביר מחכמי קראקא. כשהגיע ר שמעון סופר לכהן בקראקא ופגש את ר ישראל אמר כי אם כך נראים הסוחרים איך נראים התלמידי חכמים."},{"i":54900,"n":"שמש, דוד מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקך, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\"."},{"i":54901,"n":"שמש, זליגמן מפפד\"מ","b":"מחכמי פפד\"מ, מומחה לדקדוק, ידידו של ר וולף הידנהיים שנעזר בו בחיבור ספריו."},{"i":54902,"n":"שמש, יעקב מפפד\"מ","f":"טבלי","dt":"תקמה - ז ניסן","dp":"פפד\"מ","b":"מגדולי חכמי פפד\"מ, נבחר לרב המדינה בוירצבורג אך נשאר בפפד\"מ כראש ישיבה ודיין בקלויז ורטהיימר-תקכג (נתמנה ע\"י וולף ורטהימר) על מקום ר משה קן, לפני בואו של ר פנחס בעל ההפלאה. מרבותיו של החת\"ס המזכירו בחיבוריו כ\"מורי ורבי\". נספד ע\"י ר דוד דיסבק בעל \"פרדס דוד\". (ב\"אבני זכרון\" מופיע תאריך פטירתו תקמח - והוא טעות). חתנו - ר משה אופנהיים."},{"i":54903,"n":"שמש, משה מבגדד","b":"רב בבגדד-תרסח."},{"i":54904,"n":"שמש, שמלקא","k":"בעל שום שכל","b":"מגיד,דרשן,מגדולי חכמי פרג"},{"i":54905,"n":"שמשון","f":"צדוק","k":"בעל התשב\"ץ","b":"מגדולי הפוסקים בחכמי אשכנז,כתב את פסקיו של מהר\"ם מרוטנבורג כשהיה עצור במגדל ווסרבורג-שנת מ'"},{"i":54906,"n":"שמשון","f":"אליעזר","k":"בעל ברוך שאמר","b":"חיבר הגהות על תיקון תפילין ומזוזות לר אברהם מזשנהיים בשם \"ברוך שאמר\"."},{"i":54907,"n":"שמשון (בוכנר) מלבוב","f":"יצחק","dt":"תג - ב טבת","dp":"לבוב","b":"ר\"מ בלבוב, נזכר בשו\"ת מהר\"ם מלובלין שהסכים על הגט הידוע שסידר בעל הסמ\"ע, חתם-שעד על החרם בירוסלב שלא להדפיס את הסמ\"ע במשך 10 שנים. בספר מים חיים לר חיים רפפורט מביא שהוא ר שמשון באך שנפטר בשנת שצו - לדעת בובר המדובר בחכם אחר (מאמר בענין זה מאת סוקולוב ב\"האסיף ו')."},{"i":54908,"n":"שמשון אהרן מקיוב","f":"חיים מאיר משדה לבן","b":"בנו - ר חיים מאיר חתן ר ליבר מקודינוב."},{"i":54909,"n":"שמשון הזקן מפליזא","b":"עק\"ה,מראשוני בעלי התוספות,פוסק,מפרש,מרביץ תורה בפליזא-ד'תתק\"ל"},{"i":54910,"n":"שמשון הכהן בעל התוספות","b":"מגדולי בעלי התוספות-ד'תתק\"נ"},{"i":54911,"n":"שמשון הכהן מלסלוי","f":"חיים הכהן","b":"רב בלעסלוי-ת\"כ"},{"i":54912,"n":"שמשון הכהן מניקלשבורג","f":"עקיבא הכהן","k":"חתן המהר\"ל מפרג","b":"מגדולי חכמי דורו,רב בניקלסבורג,רב בקרמזיר-ש\"ל"},{"i":54913,"n":"שמשון הכהן מקראקא","b":"מגדולי חכמי קרקא-ת\"ל"},{"i":54914,"n":"שמשון זאב הלוי מאוסטרהא","f":"ישראל יעקב בן משה יה","dt":"תרב - כח שבט","dp":"אוסטרהא","b":"אביו היה דיין באוסטרהא. מחכמי אוסטרהא ועסק בצרכי צבור וגמילות חסד."},{"i":54915,"n":"שמשון זאב מקראקא","dt":"תז - יג תשרי","b":"דיין בקרקא"},{"i":54916,"n":"שמשון זליג הלוי מרדזין","k":"בעל מנחת האומר","b":"רב בראדזין,לקובה-תק\"מ"},{"i":54917,"n":"שמשון ירושלמי","f":"שמואל","k":"בעל יריעות עזים","b":"מחכמי ירושלים, בשנת קיא חיבר \"יריעות עזים\" ונציה שנז."},{"i":54918,"n":"שמשון מאוסטרהא","f":"אשר מאוסטרהא","dt":"תקמו - כה אלול","dp":"אוסטרהא","b":"רב באוסטרהא. הסכים על \"עץ חיים\" ו\"פרי עץ חיים\" יחד עם רב ייב\"י. חתם ראשון-תקמד על תקנה גדולה."},{"i":54919,"n":"שמשון מאוסטרופולי","f":"פסח קוריצר","k":"בעל דן ידין","r":"ראב\"ד לבוב","bt":"1600","bp":"קוריץ","dt":"תח - ג אב","dp":"פולונה","b":"נהרג עק\"ה בגזירת ת\"ח בקרב יהודים עטופי טלית ותפילין. מקובל, רב בפודוליה. בניו - ר שמואל, ר פסח, ונכדו ר שמשון. גיסו - ר יצחק מזאסלב וזולקוא שבנו ר פסח מזולקוא הו\"ל את ספרו דן ידין על ספר קרניים.","bk":[["איגרת הקודש [לער\"פ]",""],["דן ידין",""],["קרניים",""],["לקוטי שושנים",""],["לקוטים",""],["סדר הגדה של פסח עם פירוש ר' שמשון מאוסטרופולי",""],["סדר הגדה של פסח מר דרור מפענח קץ הגאולה",""],["דן ידין – קרנים",""],["כתבים של הקדוש מוהרר\"ש",""],["מחנה דן",""],["ספר ליקוטים",""],["אגרת הקודש - רבי שמשון מאוסטרופולי",""]],"e":"ש\"ס-ת\"ח","rb":"אוסטרפול","co":{"a":"49.805853,27.556910","d":"50.125556,27.510833","b":"50.6167,27.1667"}},{"i":54920,"n":"שמשון מאניפולי","b":"תלמיד הבעש\"ט-תקי. מכתבים ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":54921,"n":"שמשון מאפטא","k":"ר' שמשון מאוזרוב","dt":"תרעג - ז חשון","b":"אדמו\"ר באפטא"},{"i":54922,"n":"שמשון מבוצאץ","f":"פישל מקולומיא","b":"נינו של ר משלם מקולומיא. רב בבוצאץ-תקי. אביו של ר משלם איגרא מטיסמניץ ופרשבורג."},{"i":54923,"n":"שמשון מוויסוקה","b":"רב בוויסוקה-תרמ\"ה"},{"i":54924,"n":"שמשון מויזון","f":"יוסף יצחק","dp":"ירושלים","b":"מחכמי וילנא בשנים תל - תנד ואולי היה אבד אחרי פטירת ר משה קרמר, עלה לירושלים. חתם בספר התקנות לפני ר בצלאל אשכנזי ו יעקב קשטרו. נזכר ב\"דרוש שמואל\"."},{"i":54925,"n":"שמשון מוילנא","b":"רב בווילנה-ת\"מ,עלה לירושלים"},{"i":54926,"n":"שמשון מוילנא","b":"אב\"ד וילנא על מקום ר משה בעל \"חלקת מחוקק\" או אחרי ר יצחק מפוזנן. תיקן סדר תפלות לח\"ק - לפני תל."},{"i":54927,"n":"שמשון מוילנא","f":"אברהם מוזויהל","dt":"תקפד - טז חשון","dp":"וילנא","b":"חתן הגביר ר אליהו דיקער. גביר מחכמי וילנא, יסד את הבנק הראשון בוילנא. הסכים על חומשי רש\"ד-תקמג. חתם-תקסט על מכתב התמיכה בישיבת וולוזין."},{"i":54928,"n":"שמשון מזוואלין","dt":"תרז - ב אלול","b":"תלמיד היהודי הקדוש מפשיסחא וכותב דברי תורתו. רב בזוואלין. חתנו ר אריה מרדכי מפוריסוב-ירושלים. באוצר מופיע תאריך הפטירה - תקז."},{"i":54929,"n":"שמשון מזוואלין","f":"שלמה","dt":"תקז - ג אלול","dp":"קראקא","b":"אב\"ד זוואלין."},{"i":54930,"n":"שמשון מזולקוא","f":"אברהם","b":"חתם-תסה על תקנת קהלת זולקוא."},{"i":54931,"n":"שמשון מזולקוא","f":"מנחם מאניס","dt":"תצד - כא תשרי","dp":"זולקוא","b":"נכד(-אבי אמו) בעל הש\"ך. חתם-תסד על תקנת קהלת זולקוא."},{"i":54932,"n":"שמשון מזולקוא ופלאצק","f":"אברהם אבא מארי מנובר","b":"נכד(-אבי אמו) ר ישראל איסר. גדל אצל דודו ר מרדכי ר ליבוש'ס. רב בפלוצק, פרנס בלבוב-תצ. חתם בפנקס זולקוא-תעד וב-תעו."},{"i":54933,"n":"שמשון מטרניגרד","f":"חיים ר מעשיל מלובלין","b":"חתן ר פיבש מרגליות. דיין בטרניגרד-תפ. בנו - ר אריה ליב."},{"i":54934,"n":"שמשון מלבוב","f":"קלונימוס קלמן","dt":"תה - יג אדר","dp":"לבוב","b":"ראב\"ד בלבוב. חתם-שעז על העתק תקנות ועד ארבע ארצות, חתם על פס\"ד-שצט, עם ר יוסף בן נתן הלר, ר משה מייזיס, ועוד."},{"i":54935,"n":"שמשון מלבוב","f":"מאיר","dt":"תכד - ח אייר","dp":"לבוב","b":"רב בכמה קהילות. נהרג עק\"ה."},{"i":54936,"n":"שמשון מלבוב","f":"בצלאל","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ בלבוב ואב\"ד בכמה קהלות. נהרג עק\"ה."},{"i":54937,"n":"שמשון מלבוב","f":"שלמה","b":"מראשי קהלת לבוב, חתם-תנה על פס\"ד עם ר פנחס משה חריף."},{"i":54938,"n":"שמשון מנווידוור","b":"רב בנאווי-דוואר"},{"i":54939,"n":"שמשון מסאראקה","f":"פסח","b":"רב בסאראקא"},{"i":54940,"n":"שמשון מסלונים","dt":"תקנד - יא אייר","b":"גיסו של בעל הפרדס. רב בסלונים, קניגסברג. מצאצאיו - ה\"חזון איש\"."},{"i":54941,"n":"שמשון מסמניץ","b":"רב בסמניץ-תקצ\"ג"},{"i":54942,"n":"שמשון מספרד","f":"אבטליון","b":"מגדולי הראשונים והפוסקים בספרד-שנת ס'"},{"i":54943,"n":"שמשון מספרד","f":"מאיר","b":"מחכמי ברצלונה, תלמיד הרשב\"א, והיה שליחו של הרשב\"א לעזרת הנגיד ר דוד ממצרים שנאלץ לברוח ממצרים לעכו."},{"i":54944,"n":"שמשון מפרג ושנייטוך","b":"מגדולי חכמי דורו,רב בשנייטוך-ת\"ך"},{"i":54945,"n":"שמשון מצפת","f":"פיבל","b":"ראב\"ד בצפת-תרנא."},{"i":54946,"n":"שמשון מצרפת","k":"השר מקוצי","b":"מגדולי בעלי התוספות,מחכמי צרפת-ד'תתק\"צ"},{"i":54947,"n":"שמשון מקינון","f":"יצחק","k":"בעל ספר הכריתות","dt":"קי (1310)","b":"מבעלי התוספות האחרונים, מגדולי דורו, רב בצרפת, מרביץ תורה במרסילא. עבר לספרד אחר גירוש יהודי צרפת-סו. חיבר ספר הכריתות."},{"i":54948,"n":"שמשון מקרמניץ","f":"בצלאל מוורמייזא","b":"רב בקרמניץ-שמ. אחיו של המהר\"ל."},{"i":54949,"n":"שמשון משאנץ","f":"אברהם","bt":"ד'תתקי","dt":"ד'תתקץ","dp":"עכו","b":"מחמכי אשכנז בעלי התוספות, תלמיד רבינו תם ורי הזקן, עלה בשיירת בעלי התוספות בשנת ד'תתקעא והתיישב בעכו, בנו ר יעקב תלמיד הרמבן בעל \"תוצאות ארץ ישראל\".","bk":[["תוס' שאנץ",""],["תוס' שאנץ (רשב\"א",""],["ר\"ש משאנץ)",""]]},{"i":54950,"n":"שמשון ן, יעקב ממישטרי וארץ ישר","b":"מגדולי חכמי אשכנז,רב במיישטרי-רכ\"ז,עלה לא\"י"},{"i":54951,"n":"שמשון נפתלי מאויפאלו","b":"רב באויפאלו-ת\"ר"},{"i":54952,"n":"שמשון קלמן הכהן מבלטמרנץ","f":"חנניה הכהן","b":"בעל חסד,רב בבלטמרנץ-תר\"ך"},{"i":54953,"n":"שנאטיך, יוסף"},{"i":54954,"n":"שנאטיך, נתן נטע מפיורדא","dt":"תרח","b":"תלמיד רבנימין וולף המבורגר בעל שער הזקנים. דיין בפיורדא. תשובה אליו מרבו."},{"i":54955,"n":"שנאפר, אברהם מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקכה."},{"i":54956,"n":"שנאפר, יהודה ליב מברלין","f":"מרדכי גימפל שנאפר","b":"דיין בברלין-ת\"ק"},{"i":54957,"n":"שנאפר, ישראל מרדכי גימפל מאה\"ו","f":"יעקב אשר אנשל","dt":"תעט - יד ניסן","dp":"אלטונא","b":"חתן ר אליהו סגל וינר, ובזיוו\"ש חתן ר יוסף מאיר פרידבורג מהנובר. מקובל,דיין בהמבורג-אלטונה. נכדו - ר מרדכי גומפל המכונה פרופ' לויזון."},{"i":54958,"n":"שנאפר, מרדכי גימפל מברלין - נכ","f":"יהודה ליב מברלין","k":"בעל מאמר התורה והחכמ","bp":"ברלין","dt":"תקנז","dp":"אלטונא","b":"רופא ומכונה פרופסור לויזון. תלמיד ר דוד פרנקל בעל \"קרבן העדה\". עבר ללונדון, שטוקהולם. חיבר \"מאמר התורה והחכמה\" - לונדון תקכא, ובו קורא להעמיק את ידיעת השפה העברית, \"סולת מנחה בלולה\"."},{"i":54959,"n":"שנבוים, אריה מירושלים","b":"מדפיס בירושלים. הדפיס \"המאסף\" ירושלים תרעד."},{"i":54960,"n":"שנבוים, יצחק יעקב","dt":"תרצד - שבט","b":"רב בראדוויא"},{"i":54961,"n":"שנבוים, ישראל אריה מדוקלא","b":"מחכמי דוקלא. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":54962,"n":"שנבוים, ישראל חיים מירושלים","f":"מאיר מירושלים","dt":"תרמז - ניסן","dp":"ירושלים","b":"נהרג עק\"ה בפרעות ב\"מאה שערים\"."},{"i":54963,"n":"שנבוים, מאיר מירושלים","f":"יצחק","dt":"תרן - ד סיון","dp":"ירושלים","b":"עלה לירושלים-תר. חתן ר פנחס שלמה - השו\"ב הראשון באה\"ק. ממיסידי שכונת \"בתי מחסה\", וגבאי שם. מבניו - ר ישראל חיים הי\"ד."},{"i":54964,"n":"שנבלום, אברהם אבא משצריץ","f":"בנימין זאב וולף","k":"אדמור משצריץ","bt":"תקץ","dt":"תרנח - ח חשון","b":"חתן ר יהושע השל פרנקל-תאומים מקומרנא. רב ואדמור בשטשריץ-ליד לבוב-תרלג, מתלמידיו שם - ר זאב וולף מישל מקומפלונג. בנו ר משה נפטר בחיי אביו, ונכדו ר בנימין וולף על מקומו אחריו בשטשריץ."},{"i":54965,"n":"שנבלום, בנימין זאב וולף מלמברג","f":"צבי הירש מלמברג","k":"אדמור סטרליסק בלמברג","bt":"תקם","dt":"תר-י - כו אלול","b":"חתן ר יוסל לנדא מברודי. גביר מחסידי השרף מסטרליסק ורשם את תורתו ב\"אמרי קדוש\", היה הגביר היחיד בין חסידי השרף. ולאחר פטירתו של השרף כיהן כאדמור לקהילת חסידי סטרליסק בלמברג, ובתר\"ג נוסד עבורו קלויז מיוחד שנקרא ע\"ש והתקיים עד השואה."},{"i":54966,"n":"שנבלום, בנימין זאב וולף משצריץ","f":"משה משצריץ","dt":"תש..","b":"רב בצשינוב, שצריץ(=שטשעריץ)-תרנח על מקום זקנו. נספה בשואה. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"המפלפל\" - קראקא תרעג."},{"i":54967,"n":"שנבלום, זאב וולף","f":"יוסף מרישא","b":"תרגם ספר \"חוקי האישות\" לזקנו הנודע ביהודה והוסיף הקדמה - מונקטש תרסג."},{"i":54968,"n":"שנבלום, יוסף מלמברג","f":"שמואל מרישא","bt":"תריח","bp":"רישא","dt":"תרפח","b":"חתן הגביר ר יעקב כגן מקמניץ-פודולסק ועבר אל חותנו באודסה, חזר לרישא וללמברג והיה גביר נדבן ועסקן ציבור."},{"i":54969,"n":"שנבלום, יצחק","b":"פרסם ב\"הבונה\" - לבוב תרסד - סיפור מחיי ר ברוך פרנקל בעל \"ברוך טעם\"."},{"i":54970,"n":"שנבלום, יצחק יעקב מטרספול","f":"אהרן צבי","bt":"תרז","b":"חתן ר יהודה ליב אפשטין מיאלסטוואגראד. מו\"צ ביאלסטווגרד-תרלד אצל חותנו, ווישניץ-פלך שדליץ-תרנא, טרספול(=טערעספאליע)-תרסו."},{"i":54971,"n":"שנבלום, משה","f":"אברהם אבלי משצריץ","b":"מחכמי רישא - נפטר בחיי אביו."},{"i":54972,"n":"שנבלום, שמואל מלמברג","f":"בנימין זאב וולף","bt":"תקצג","bp":"למברג","dt":"תרס","b":"סוחר בספרים עתיקים וביבליוגרף שעמד בקשרים עם שד\"ל. הוציא לאור \"רב פעלים\" לר יצחק ן לטיף - תרמה, ועוד."},{"i":54973,"n":"שנבלום, שמואל מרישא","dt":"תרס","b":"נכד ר יוסף מפוזנא. גביר וראש הקהל ברישא."},{"i":54974,"n":"שנברון, מנחם הכהן מקליבלנד","k":"בעל מנחת סופר","b":"רב בקליבלנד-תרסו."},{"i":54975,"n":"שנגוט, יחיאל מיכל הלוי מביליץ","bt":"תקע","dt":"תרמב","b":"רב בביליץ-תרך. תלמידו - ר פנחס יוזפסטל."},{"i":54976,"n":"שנדוך, ששון מבבל והודו","f":"מרדכי","k":"בעל מזמור לאסף","bt":"תקז","dt":"תקץ - ו טבת","dp":"בגדד","b":"מקובל מחכמי בבל, רב בבומבי. חיבר גם \"דבר בעתו\", \"אמרי ששון\", \"תהלה לדוד\", \"קול ששון\", ועוד. נזכר ב\"בן יהוידע\" אודות מעשה שעשה בכח הקבלה בקבר \"אבו סיפ'ין\".","bk":[["אמרי ששון - מוסר",""],["דבר בעתו – סדר עבודה",""],["מזמור לאסף – תפילה",""],["קול ששון – מוסר בדרך שיר וכו'",""],["שדה לבן – תהלים",""],["תהילה לדוד – תהילה לדוד",""]]},{"i":54977,"n":"שנדורף, אשר ישעיה","f":"יצחק איזיק מצאנז","b":"חתן ר צבי יחזקאל וייץ מגורליץ ועבר לשם."},{"i":54978,"n":"שנדורף, חיים שאול מגורליץ","f":"אשר ישעיה מגורליץ","bt":"תרך","bp":"גורליץ","dt":"תרצד","b":"חסיד צאנז. תלמיד ר נפתלי מילר מגורליץ ורשם את חדושיו. חתן ר חיים גרונר מברדיוב (גיסו של הדברי חיים) ועבר לשם. חסיד האדמור ר ברוך מגורליץ. עבר לנירנברג-תרסח. סדר הדורות למשפחתו ע\"י נכדו ר אהרן יוסף רוזן - \"תכתב זאת לדור אחרון\" - ניו יורק תשמה."},{"i":54979,"n":"שנדורף, יצחק איזיק מראפע","b":"חסיד צאנז. חתן ר יוסף צימר מראפע (ליד צאנז) ועבר לשם."},{"i":54980,"n":"שנדורף, שאול סגל","b":"רב בטירטש-תר\"מ"},{"i":54981,"n":"שנדורף, שמואל מקשנוב","b":"מחכמי קשנוב-תרץ. תלמיד ר צבי הירש מיזלש שהזכירו בספרו \"בנין צבי\"."},{"i":54982,"n":"שנדזול, יונה מליטא","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":54983,"n":"שנה טובה, יעקב","k":"יב\"ש","b":"מגדולי חכמי איטליה במודנא"},{"i":54984,"n":"שנהוט, דוד מיזירנה","b":"עבר מיזירנה לניו יורק-תרסז."},{"i":54985,"n":"שנון, שמעון מקריזבורג","b":"רב בקריזבורג. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":54986,"n":"שנור, אברהם אבלי מאושפיצין","bt":"תריח","dt":"תרעו","dp":"וינה","b":"נכד ר ישראל רפפורט מטרנוב. רב באושפיצין-תרם, קראקא, טרנוב-תרנט על מקום זקנו (לעומת המועמד קרובו - ר שאול רפפורט). נחשב לאחד מטובי הנואמים באוסטריה בשפה הגרמנית, והיה בקשרים טובים עם השלטונות - וניצל זאת לעזרה ליהודים. הסכים על \"פרי מרדכי מרדכי אברהם\"-תרנה."},{"i":54987,"n":"שנור, חיים מגריידינג","f":"ברהם אביש","k":"בעל מעיין חיים","b":"חסיד רוזין. תלמיד מהר\"ם שפירא בסנוק. עלה לארץ-תרצד והיה ממקימי קיבוץ מחנה ישראל של אגו\"י. חתן ר יצחק משה רוט מלמברג. חיבר \"מעיין חיים\" תל אביב תשלט."},{"i":54988,"n":"שנור, נתנאל","k":"בעל הקריב נתנאל","dt":"תרפ - יז כסלו","b":"דרשן,מגיד בזאמוטשט"},{"i":54989,"n":"שנור, שמואל אלתר","f":"יצחק מבייטש","bt":"תרעא","bp":"בייטש","dt":"תשד","b":"גדל אצל זקנו ר חיים שמואל איצינגר מבייטש. תלמיד ר מאיר ארק בטורנא, עבר ללודז. פרסם שירים ומאמרים בעתונים שונים ונחשב בין טובי הסופרים והמשוררים החרדים. המשיך להוציא עתון \"המספר\" גם בגיטו. נספה בשואה."},{"i":54990,"n":"שני, יעקב משלוניקי","dt":"רעב - ב אב","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":54991,"n":"שני, יצחק מקושטא","b":"תלמיד ר אברהם מיוחס. רב בקושטא-תצב, כיהן כממונה על איסור והיתר-תקב, חתם על הסכמה ב-תצב, ועל פסק נגד מלבושים יקרים בירושלים-תקח."},{"i":54992,"n":"שני, יצחק משלוניקי","f":"אליהו","k":"בעל מאה שערים","b":"מקובל מחכמי שלוניקי-ש'."},{"i":54993,"n":"שניאור","f":"יהודה","b":"מגדולי חכמי איטליה-שנת ל'"},{"i":54994,"n":"שניאור הלל'ס מבירז","dt":"תרסו","b":"חתן ר מרדכי בן יקותיאל זלמן משימבורג ויאקובשטט. מלמד מחכמי בירז. הניח חדושים - בכת\"י."},{"i":54995,"n":"שניאור זלמן מליאדי (ברוכזון)","f":"ישראל ברוך מליאזני","k":"בעל התניא","r":"תקע\"ב קבור ברוסיה","bt":"תקה-ו","dt":"תקעג - כד טבת","b":"תלמיד המגיד ממזריטש, ר מנחם מנדל מויבסק. חתן ר יהודה ליב סגל. אדמור ברוסיה הלבנה ויסד את חסידות חב\"ד. חיבר גם \"שלחן ערוך הרב\", ועוד. נאסר בגלל הלשנה פעמיים ויום שחרורו יט כסלו תקצז היה לחג הגאולה אצל החסידים. חתניו - ר אליהו-אביו של ר אהרן מקרמנצוג, ר שלום שכנא.","bk":[["שולחן ערוך הרב","מפרשי שו\"ע"],["ליקוטי תורה",""],["סידור הרב",""],["שלחן ערוך הרב",""],["תורה אור",""],["תניא – ליקוטי אמרים",""],["תניא – ליקוטי אמרים , ליקוטי תורה, סידור הרב , שלחן ערוך הרב , תורה אור",""],["ליקוטי אמרים - תניא",""],["האדמו\"ר הזקן","שו\"ת - אחרונים"],["תניא","חסידות"]],"e":"תק\"ה~-תקע\"ג"},{"i":54996,"n":"שניאור מאיטליה","dt":"תנט - כז סיון","b":"חריף,מקובל,רב ברישא"},{"i":54997,"n":"שניאור מפאסטוב","b":"תלמיד ר זאב וולף מזיטומיר."},{"i":54998,"n":"שניאור מפפד\"מ","f":"שמואל","b":"מחכמי פפד\"מ-שכה, חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ."},{"i":54999,"n":"שניאור מרישא ולבוב","b":"ר\"מ בלבוב-תקך, ב\"זכר חיים\" לר חיים רפפורט מביא תשובה אליו מאת ר אהרן הלוי אשכנזי."},{"i":55000,"n":"שניאור פיבוש מוואנילוב","f":"דוד הי\"ד","b":"רב בואנילוב(=וואניליב), חתם-תלג בפנקס קהלת לבוב עם ר אהרן בן צבי הירש ור מנחם בן צבי כץ."},{"i":55001,"n":"שניאור פיבוש מויטצענהויזן","b":"אבי משפחת רייק. אב\"ד ויטצענהויזן-תצו. הסכים על \"שער אפרים\"-תצו. בנו ר יהודה פו\"מ בברלין ונקרא בשם פייט - רייק (על שם אביו) וצאצאיו נקראו רייק."},{"i":55002,"n":"שניאור, אברהם המומר מספרד","b":"רב הכולל בספרד עד הגירוש-רנב, התנצר עם בניו וחתנו - רב ממשפחת גבאי, ורבים נמשכו אחריו והמירו דתם עמו. אחיו ר שלמה גלה עם אחיו."},{"i":55003,"n":"שניאור, אהרן משה","f":"יוסף יצחק שניאור","b":"שנת תר\"מ"},{"i":55004,"n":"שניאור, אפרים מקולומיאה","f":"דוד טעביל","bt":"תרלד","bp":"קולומיאה","dt":"תש","b":"ממשפחת ר דוד טבלי מליסא בעל \"נפש דוד\". תלמיד ר שרגא פיבל שרייער בברודשין. רב בבולשאויטץ, קומפלונג, היגר לארה\"ב וכיהן כרב קהילת אנשי וארשא ובניו יורק. שלח לרש\"א טיקטין את תולדותיו-תרצד. ממשתתפי \"ועד חכמים\"."},{"i":55005,"n":"שניאור, זלמן מיוזיל-היסאר","b":"מראשי קהלת יוזיל-היסאר-ליד אזמיר-שנות ה-ת'."},{"i":55006,"n":"שניאור, מנחם מנדל מביאלא","b":"רב בביאלא גדול. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":55007,"n":"שניאור, משה מאלגיר","f":"חיים","b":"מחכמי בג'איה(=בוג'י)-אלגיר. היה במחלוקת עם הרשב\"ש בעניני הלכה. היתה מחלוקת בינו ובין תלמידי הרשב\"ש בבג'איה - ר דוד הכהן בקרי ור יוסף זמרון - ונידו זה את זה. ממשפחת אברהם שניאור - רבה של ספרד שהמיר דתו-רנב."},{"i":55008,"n":"שניאור, משה מצרפת","k":"בעל על הכל","b":"מגדולי חכמי צרפת,מרביץ תורה באיבורא(נורמנדיה)-שנת ס'"},{"i":55009,"n":"שניאור, נחום זלמן מטשרקס","f":"אהרן משה שניאור","dt":"תרעו - טו ניסן","b":"רב בטשרקס"},{"i":55010,"n":"שניאור-שנייער, מרדכי מיזלוביץ","bt":"תקכג","dt":"תרלג","b":"רב ביזלוביץ-תקעג במשך כ-60 שנה. המהרש\"ם שהיה רבה של פוטיק הסמוכה בא להספידו ואז נתמנה לרב על מקומו."},{"i":55011,"n":"שניאורסאהן מנחם מענדל בן לוי יצחק (אדמו\"ר מליובאוויטש)","bk":[["שיחות קודש",""]]},{"i":55012,"n":"שניאורסון ברוך שמעון בן יוסף משה","bt":"1913","dt":"ה'תשסא 2001","bk":[["ברכת שמעון ב\"ק וב\"מ",""],["ברכת שמעון שבת ופסחים",""]]},{"i":55013,"n":"שניאורסון שלום דב בר בן שמואל","bt":"1860","dt":"ה'תרפ 1920","bk":[["אגרות קודש אדמו\"ר מוהרש\"ב א",""],["אגרות קודש אדמו\"ר מוהרש\"ב ב",""],["אגרות קודש אדמו\"ר מוהרש\"ב ג",""],["אגרות קודש אדמו\"ר מוהרש\"ב ד",""],["אגרות קודש אדמו\"ר מוהרש\"ב ה",""],["בשעה שהקדימו תערב",""],["בשעה שהקדימו תערב ב",""],["בשעה שהקדימו תערב ג",""],["ספר המאמרים תר\"ן",""],["ספר המאמרים תרמ\"ג",""],["ספר המאמרים תרמ\"ד",""],["ספר המאמרים תרמ\"ה",""],["ספר המאמרים תרמ\"ו",""],["ספר המאמרים תרמ\"ז",""],["ספר המאמרים תרמ\"ח",""],["ספר המאמרים תרמ\"ט",""],["ספר המאמרים תרנ\"ה",""],["ספר המאמרים תרנ\"ו",""],["ספר המאמרים תרע\"ב",""]]},{"i":55014,"n":"שניאורסון, אריה ליב","b":"אחיו של האדמור מוהרי\"ץ."},{"i":55015,"n":"שניאורסון, ברוך","f":"דוב בער שניאורסון"},{"i":55016,"n":"שניאורסון, ברוך שלום","f":"מנחם מנדל-צמח צדק","bt":"תקסז","dt":"תרכט - טז שבט","b":"נכד בעל התניא. לא כיהן כאדמור אך נחשב מאוד בעיני החסידים. בניו ר לוי יצחק מפודברונקא, ר מרדכי מויבסק, ור יהודה ליב."},{"i":55017,"n":"שניאורסון, ברוך שמעון מקראקא","f":"יוסף משה","k":"בעל ברכת שמעון","r":"ראש ישיבת טשיבין","bt":"תרעג","bp":"קראקא","dt":"ה'תשסא","b":"מצאצאי הצמח צדק. תלמיד בישיבת חכמי לובלין. ניצל מהשואה - גלה לסיביר. חתן רבו ר דב בריש וידנפלד מטשבין. עלה לארץ-תשיז וכיהן כראש ישיבת חבד בלוד, ובין תלמידיו ר משה לנדא אב\"ד בני ברק. ראש ישיבת \"כוכב מיעקב\" טשבין בירושלים. חיבר \"ברכת שמעון\" כפר חבד תשכב, ועוד.","bk":[["ברכת שמעון [עה\"ת",""],["עהש\"ס",""],["על המועדים]",""],["ברכת שמעון - תורה, ומועדים, שבת, פסחים, קידושין, ב\"ב",""]]},{"i":55018,"n":"שניאורסון, דב בר","f":"חיים אברהם מלובאויטץ","b":"נכד בעל התניא."},{"i":55019,"n":"שניאורסון, דב בר מליובאויטש","f":"שניאור זלמן - התניא","k":"אדמור האמצעי","r":"נאמר לפני ר' עקיבא איגר בפוזנא תקפה","bt":"תקלד","dt":"תקפח - ט כסלו","b":"עבר מליאדי לליובאויטש שהפכה למרכז חסידות חבד עד תרעו. הקים את המרכז החסידי בחברון. נאסר בגלל הלשנה ושוחרר-י כסלו תקפז. חיבר \"תורת חיים\"., אמרי בינה, ועוד. חתניו ר יקותיאל זלמן ואלס-נכד ר לוי יצחק מברדיטשוב, ר אהרן אלכסנדרוב משקלוב, ר יעקב מסלונים.","bk":[["אמרי בינה",""],["בד קודש",""],["ביאורי הזוהר",""],["דרושי חתונה וקונטרסים",""],["דרך חיים",""],["מאמרי אדמו\"ר האמצעי – תנ\"ך",""],["נר מצוה ותורה אור \\ שער האמונה והיחוד",""],["עטרת ראש",""],["פוקח עיוורים",""],["פירוש המילות",""],["פסקי דינים לשלחן ערוך יורה דעה",""],["קונטרס ההתפעלות",""],["שער התשובה והתפילה",""],["שערי אורה",""],["שערי תשובה",""],["תורת חיים",""],["מאמר אל תצר את מואב",""],["קונטרס קטן בעניני בחירה",""]]},{"i":55020,"n":"שניאורסון, דוב מויטבסק","f":"מנחם מנדל","b":"רב בויטבסק-תר\"מ"},{"i":55021,"n":"שניאורסון, דובער יצחק מלודז","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":55022,"n":"שניאורסון, זלמן מרדכי מזיטומיר","f":"יוסף יצחק מאווריטש","b":"נכד הצמח צדק. רב בזיטומיר-תרם."},{"i":55023,"n":"שניאורסון, חיים אברהם","f":"שניאור זלמן-התניא","dt":"תרח","b":"סירב לכהן כאדמור על מקום אחיו ר דב בער-אדמור האמצעי. חיבר הקדמה ל\"שלחן ערוך הרב\" לאביו. בנו - ר דב בר, חתנו - ר נחמיה גינצבורג."},{"i":55024,"n":"שניאורסון, חיים ישעיה מפריטש","f":"שלום דובער מרציצא","bt":"תרכה","dt":"תרפא - טז כסלו","b":"נין הצמח צדק. חתן ר מרדכי דב מהורנוסטיפול (אניפולי). רב בפאריטש-פלך מינסק-תרנד, ראמען(=ראמני)-פלך פולטובה-תרסא. חיבר שו\"ת - בכת\"י. אחיו - ר זלמן מהאמילע."},{"i":55025,"n":"שניאורסון, חיים צבי","k":"בעל פלשתינה ורמניה","b":"חיבר ספר באנגלית פלשתינה ורומניה - ניו יורק תרלב."},{"i":55026,"n":"שניאורסון, חיים צבי מחברון","f":"נחום יוסף","bt":"תקצד","dt":"תרמב","b":"נכד(-אבי אמו) משה בנו של בעל התניא. אחיו - ר שניאור זלמן בעל נימוקי שזבנ\"י, ור פנחס אליהו מחברון."},{"i":55027,"n":"שניאורסון, יהודה ליב מהומל","f":"שלום דובער מרציצא","b":"נכד הצמח צדק. רב בהאמיל(=האמלע), סירוטני(=סיראצעני), מו\"ץ בויטבסק-תרסו."},{"i":55028,"n":"שניאורסון, יהודה ליב מוויליז","b":"רב בוויליז"},{"i":55029,"n":"שניאורסון, יהודה ליב מסירצנא","f":"יצחק שניאורזון","b":"רב בסירצנע,הומיל-תרס\"ו"},{"i":55030,"n":"שניאורסון, יהודה ליב מקפוסט","f":"מנחם מנדל - הצמח צדק","k":"אדמור מקפוסט לובביטש","bt":"תקעא","dt":"תרכז - ג חשון","b":"חתן ר שלמה פריידש משקלוב-תלמיד בעל התניא ובנו. נהג אדמורות בחיי אביו, ואחריו כיהן כאדמור בקפוסט. בנו - ר שניאור זלמן מקפוסט(=קאפוסט)."},{"i":55031,"n":"שניאורסון, יוסף יצחק מאווריטש","f":"מנחם מנדל - הצמח צדק","bt":"תקפב","dt":"תרלז - יח כסלו","b":"חתן דודו ר יעקב ישראל מטשרקאס (טשרנוביל). רב ואדמור באווריטש(=אברושט) - ונהג כדרך צדיקי טשרנוביל ולא כמנהגי אביו. בנו ר זלמן מרדכי - רב בזיטומיר."},{"i":55032,"n":"שניאורסון, יוסף יצחק מארה\"ב","f":"שלום דוב מליובאויטש","k":"אדמור מהריי\"ץ","r":"ראש ישיבת סלבודקא שבבני ברק, חתנו של ה'סבא' מסלבודקא","bt":"תרמ","dt":"תשי - י שבט","b":"אדמור חסידי חב\"ד-תרף על מקום אביו. רב פעלים לחזוק היהדות במסירות נפש ברוסיה ובארה\"ב, חתן ר אברהם בן ישראל נח מניעזין. נאסר ע\"י הקומוניסטים וניצל-תרפז. עבר לריגה, וארשא-תרצד, ניו יורק-תש. ביקר בארץ-תרפז ויסד את כפר חב\"ד. חתנו ר מנחם מנדל מליובאויטש על מקומו אחריו כאדמור. חיבר ספר המאמרים, ועוד.","bk":[["אגרות קודש אדמו\"ר מוהריי\"צ א",""],["אגרות קודש אדמו\"ר מוהריי\"צ ב",""],["אגרות קודש אדמו\"ר מוהריי\"צ ג",""],["אגרות קודש אדמו\"ר מוהריי\"צ ד",""],["אגרות קודש אדמו\"ר מוהריי\"צ ה",""],["אגרות קודש אדמו\"ר מוהריי\"צ ו",""],["אגרות קודש אדמו\"ר מוהריי\"צ ז",""],["אגרות קודש אדמו\"ר מוהריי\"צ ח",""],["אגרות קודש אדמו\"ר מוהריי\"צ ט",""],["אגרות קודש אדמו\"ר מוהריי\"צ י",""],["אגרות קודש אדמו\"ר מוהריי\"צ יא",""],["אגרות קודש אדמו\"ר מוהריי\"צ יב",""],["אגרות קודש אדמו\"ר מוהריי\"צ יג",""],["אגרות קודש אדמו\"ר מוהריי\"צ יד",""],["אדמו\"ר הצמח צדק ותנועת ההשכלה",""],["אין הקב\"ה בא בטרוניא",""],["די רייד פון ליובאוויטשער רבי’ן",""],["דרושי חתונה",""],["כי מנסה",""],["לקוטי דבורים",""],["מאמר קנין החיים",""],["ספר המאמרים ה'תש\"ה",""],["ספר המאמרים ה'תש\"ז",""],["ספר המאמרים תרפ\"ה",""],["ספר המאמרים תרצ\"ב",""],["ספר המאמרים תרצ\"ג",""],["ספר המאמרים תרצ\"ו",""],["ספר המאמרים תרצ\"ז",""],["ספר המאמרים תש\"א",""],["ספר המאמרים תש\"ב",""],["ספר המאמרים תש\"ג",""],["ספר המאמרים תש\"ד",""],["ספר המאמרים תש\"ו",""],["ספר המאמרים תש\"ח",""],["ספר המאמרים תש\"ט",""],["ספר המאמרים תש\"י",""],["ספר המאמרים תשי\"א",""],["קונטרס ח״י אלול ה׳תש״ג",""],["קונטרס חג השבועות ה׳תש״ח",""],["קונטרס חודש תשרי",""],["שיחה של אדמו\"ר מליובאוויטש",""],["תהלים אהל יוסף יצחק",""],["ספר המאמרים",""],["קונטרס ב' ניסן",""],["קונטרס יב – יג תמוז",""],["קונטרס מאמרים",""],["קונטרס מאמרים, ספר המאמרים , קונטרס ב' ניסן , קונטרס יב – יג תמוז",""]]},{"i":55033,"n":"שניאורסון, יעקב מאוארשא","f":"מנחם מנדל - הצמח צדק","b":"חתן ר ברוך בן אליהו זסלבסקי מקרמנצוג-חתן ר שניאור זלמן מליאדי. נפטר בחיי אביו."},{"i":55034,"n":"שניאורסון, יצחק דובער מליאדי","f":"חיים שניאור זלמן ש'","k":"אדמור מליאדי-מהרי\"ד","bt":"תקצה","dt":"תרע - כ ניסן","b":"נכד הצמח צדק. אדמו\"ר בליאדי-תרמ. חיבר \"סידור מהרי\"ד\". אדמו\"ר בליאדי-תר\"מ"},{"i":55035,"n":"שניאורסון, ישראל אריה ליב","f":"לוי יצחק מיקטרינסלב","b":"אחיו של האדמור האחרון."},{"i":55036,"n":"שניאורסון, ישראל נח מניעזין","f":"מנחם מנדל - הצמח צדק","k":"אדמור מליובאויטש","bt":"תקעה","dt":"תרמג - יז ניסן","b":"חתן דודו ר יקותיאל זלמן ואלס, ובזיוו\"ש חתן דודו ר מנחם נחום מניעזין. השיב תשובות בהלכה בשם אביו. אדמור בליובאויטש, עבר לניעזין-תרכח."},{"i":55037,"n":"שניאורסון, לוי יצחק מיקטרינסלב","f":"ברוך שניאור","k":"בעל לקוטי לוי יצחק","r":"רב ביקטורניסלב ואביו של האדמו\"ר האחרון מחב\"ד","bt":"תרלח","dt":"תשד - כ אב","dp":"סיביר","b":"נכד ר לוי יצחק מפודברונקה בן ר ברוך שלום בן הצמח צדק. חתן ר מאיר שלמה הלוי ינובסקי. רב ביקטרינסולב-תרסט, גלה לסיביר-תרצט ונפטר שם. חיבר גם \"לקוטי לוי יצחק\".","bk":[["תורת לוי יצחק",""],["ליקוטים על הזוהר",""]]},{"i":55038,"n":"שניאורסון, לוי יצחק מפודברונקא","f":"ברוך שלום-נכד התניא","bt":"תקצד","dt":"תרלח","b":"נכד הצמח צדק. רב בפודברונקא, יישנקוביץ."},{"i":55039,"n":"שניאורסון, מנחם מנדל","f":"שמואל - אדמור מוהר\"ש","r":"האדמו\"ר מחב\"ד","bt":"1789","dt":"יג ניסן תרכ \\ תרכו","b":"חתן ר ישראל דוד שמחה בונם סופר בן ר שמעון מקראקא בעל \"מכתב סופר\", ובזיוו\"ש חתן ר נחום דובר מאווריטש.","bk":[["צמח צדק [לובאוויטש]","שו\"ת - אחרונים"],["דרך אמונה – חידוש העולם",""],["דרך מצוותיך",""],["יהל אור – תהלים",""],["מאה שערים",""],["ספר הליקוטים",""],["אור התורה - מאמרים ודרושים על פרשת השבוע וחגים",""],["ביאורי הזוהר - ביאורים ודרושים על הזוהר",""],["מאמרי אדמו\"ר הצ\"צ - מאמרים בחסידות",""],["ספר החקירה - הוכחות על חידוש העולם בדרך המחקר הקבלה והחסידות",""],["צמח צדק – שו\"ת וש\"ס",""],["רשימת מאמרי דא\"ח",""],["תהילים אהל יוסף יצחק - ביאור על התהילים",""]]},{"i":55040,"n":"שניאורסון, מנחם מנדל מלויבויטש","f":"לוי יצחק מיקטרינסלב","k":"אדמור מליובאויטש נ\"י","r":"האדמו\"ר מחב\"ד - ליובביטש","bt":"תרסב","dt":"ג' תמוז תשנד","dp":"ניו יורק","b":"חתן ר יוסף יצחק-אדמור מהריי\"צ, אדמור חסידי חב\"ד על מקום חותנו.","bk":[["אגרות קודש",""],["אגרת חינוך - חינוך",""],["היום יום - לוח לחסידי חב\"ד",""],["הצנע לכת - צניעות",""],["ליקוטי שיחות",""],["ספר השיחות",""],["שיחות קודש",""],["תורת מנחם",""],["די רייד פון אדמו\"ר שליט\"א מליובאוויטש",""],["דער רבי רעדט צו קינדער",""],["ימי בראשית",""],["כללי רמבם",""],["כללי רש\"י",""],["מגילת אסתר עם ליקוטי ביאורים מכ''ק אדמו''ר מליובאוויטש",""],["מפתח ספרי מאמרי ודרושי אדמו\"ר מהורש\"ב",""],["מפתחות והערות לספר תורה אור",""],["ספר השיחות תשנ''ב",""],["שלחן המלך",""],["תורת מנחם התוועדויות",""],["תורת מנחם התוועדויות תשמ''ג",""]]},{"i":55041,"n":"שניאורסון, מנחם מנדל מליובויטש","f":"שלום שכנא אלטשולר","k":"בעל צמח צדק","bt":"תקמט","dt":"תרכו - יג ניסן","b":"נכד בעל התניא. מגדולי דורו. חתן דודו ר דב בער מליובאויטש ועל מקומו אחריו כאדמור בליובאויטש. חתנו ר לוי יצחק ואלס בן גיסו ר יקותיאל זלמן מוויליז'.","bk":[["צמח צדק (ליובאוויטש)",""]]},{"i":55042,"n":"שניאורסון, מנחם נחום מניעזין","f":"דב בער מליובאויטש","bt":"תקמח","dp":"ניעזין","b":"חתן ר זלמן ריבלין משקלוב-תלמיד זקנו-בעל התניא, ובזיוו\"ש חתן גיסו ר יעקב ישראל מטשרקאס. עבר מליובאויטש לניעזין אחר פטירת אביו."},{"i":55043,"n":"שניאורסון, מרדכי מויטבסק","f":"ברוך שלום-נכד התניא","b":"נכד הצמח צדק. רב בויטבסק."},{"i":55044,"n":"שניאורסון, נחום דובער מאווריטש","f":"יוסף יצחק מאווריטש","dt":"תרנו - ח כסלו","b":"נכד הצמח צדק. חתן ר דב משה בן ר שלמה חיים מקוידנוב. חתנו - ר נח יוסף בועז פרלוב מאווריטש."},{"i":55045,"n":"שניאורסון, פנחס אליהו מחברון","f":"נחום יוסף","bt":"תרו","bp":"חברון","b":"בן לשרה רבקה ונכד למשה-בנו של בעל התניא. לאחר ה'נפילה' של משה שלח-תרג האדמו\"ר בעל צמח צדק לחברון את אשתו הרבנית שפרה עם בנותיה רחל ושרה רבקה ובניהם ר חיים צבי ור שניאור זלמן בעל נימוקי שזבנ\"י."},{"i":55046,"n":"שניאורסון, שטערנא שרה","b":"אשת האדמור מוהרש\"ב."},{"i":55047,"n":"שניאורסון, שלום דובער מלובויטש","f":"שמואל מליובאויטש","k":"אדמור מוהרש\"ב","bt":"תרכא","dt":"תרף - ב ניסן","dp":"רוסטוב","b":"נשיא חסידי חב\"ד בליובאוויטש-פלך מוהילוב-תרמג, מראשי היהדות ברוסיה. חתן דודו ר יוסף יצחק מאווריטש. מייסד ישיבות \"תומכי תמימים\". במלחה\"ע ה-I עבר לרוסטוב. מתורתו ב\"ספר המאמרים\", \"אגרות קודש\", ועוד. חיבר \"חנוך לנר\". בנו - ר יוסף יצחק.","bk":[["אגרות קודש",""],["בשעה שהקדימו ישראל תרעב",""],["יום טוב של ר\"ה תרסו",""],["ספר המאמרים",""],["קונטרס התפילה",""]]},{"i":55048,"n":"שניאורסון, שלום דובער מרציצא","f":"יהודה ליב מקפוסט","k":"אדמור מלובויטש ברציצ","dt":"תרסט - טז תשרי","b":"חתן ר יעקב יוסף מאוריזסטשוב (אוסטרהא). אדמור מליובאויטש ברציצא(=רעציצע)-תרם. בניו ר שניאור זלמן מרעפקא, ר חיים ישעיה מפאיטש, ר יהודה ליב מהאמיל, ור משה."},{"i":55049,"n":"שניאורסון, שלמה זלמן מקפוסט","f":"יהודה ליב מקפוסט","k":"אדמור מלובויטש קפוסט","bt":"תקצ","dt":"תרס - כז אייר","b":"חתן ר יעקב אריה ליב לוריא מליעפלי. אדמור מליובאויטש בקפוסט-תרכז ורוב חסידי חב\"ד היו חסידיו. חיבר \"מגן אבות\".","bk":[["מגן אבות",""],["מגן אבות - עה\"ת והוספות",""]]},{"i":55050,"n":"שניאורסון, שמואל דב מבוריסוב","k":"הרשמ\"ם","bt":"תקסח","dt":"תרמט","b":"תלמיד ר דב בר מליבאויטש, בנו ר שמואל, ונכדו ר שלום דובער. כיהן כ\"משפיע\" בבוריסוב. חיבר ביאור ל\"פוקח עורים\" ונדפס."},{"i":55051,"n":"שניאורסון, שמואל מליובאויטש","f":"מנחם מנדל - הצמח צדק","k":"אדמור מוהר\"ש","bt":"תקצד","dt":"תרמג - יג תשרי","b":"חתן אחיו ר חיים שניאור זלמן מליאדי, ובזיוו\"ש חתן דודו ר אהרן אלכסנדרוב משקלוב. אדמור בליובאויטש על מקום אביו. מתורתו ב\"לקוטי תורה - תורת שמואל\". מבניו ר שניאור זלמן אהרן, ר מנחם מנדל, הרש\"ב. חיבר \"מים רבים\". מתורתו ב\"לקוטי תורה - תורת שמואל\".","bk":[["אגרות קודש",""],["לקוטי תורה \\ תורת שמואל",""],["שו\"ת אדמו\"ר המהר\"ש",""],["שו\"ת אדמו\"ר המהר\"ש, אגרות קודש, לקוטי תורה \\ תורת שמואל",""]]},{"i":55052,"n":"שניאורסון, שמריהו נח מבוברויסק","f":"יהודה ליב מקפוסט","k":"אדמור מבוברויסק","r":"אדמו\"ר מחב\"ד בויבורסק","bt":"תרז","bp":"לובאביץ","dt":"תרפג - טז טבת","b":"נכד ה\"צמח צדק\". חתן דודו ר ישראל נח מניעזין. רב בבוברויסק-תרל, הקים ישיבה-תרסא. אדמור בבבורויסק על מקום אחיו ר שלמה זלמן מקפוסט. חיבר \"שמן למאור\". הסכים על תשובה לר מנחם מנדל פנחס פערעוואזניק מרעסיצא ב\"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["שמן למאור - על התורה",""]]},{"i":55053,"n":"שניאורסון, שניאור זלמן אהרן","f":"שמואל - אדמור מוהר\"ש","bt":"תריט","dt":"תרסט - יא אב","b":"חתן דודו ר ישראל נח מניעזין."},{"i":55054,"n":"שניאורסון, שניאור זלמן מטשכנוב","b":"רב בטשכנובצי-תרנ\"ח"},{"i":55055,"n":"שניאורסון, שניאור זלמן מירושל","f":"מנחם מנדל - הצמח צדק","k":"הו\"ל קול אריה","bt":"תקעד","dt":"תרמ - ד טבת","b":"חתן ר ישעיה הלוי מהאמיל. רב בלאדי(=ליאדי), עלה לירושלים-תקץ (בערך) והיה מראשוני חסידי חב\"ד בירושלים, תלמיד ר חיים הורביץ בעל \"חבת ירושלים\" ועזר לו בחבור ספרו. עמד בראש כולל חב\"ד. בשליחות בארצות רבות ובהם בעיר והודו-תריח וגייס תמיכה ממשפחת ששון לבנית בית כנסת חבד בחברון ובירושלים - בעיר העתיקה ברח' הנקרא רח' חב\"ד, בשליחות באירופה ובמזרח-תרכג. הו\"ל \"קול אריה\" לזקנו ר אריה ליב חריף, \"אם למסורה\", \"זכרון ירושלים\", ועוד."},{"i":55056,"n":"שניאורסון, שניאור זלמן מירושלי","f":"נחום יוסף","k":"בעל נמוקי שזבנ\"י","dt":"תרמב","b":"נכד(-אבי אמו) משה בנו של בעל התניא. מראשי חסידי חבד בירושלים, בשנת תרט חתם על אגרת אנשי חבד למונטיפיורי, חיבר \"נמוקי שזבני\" ירושלים תרלו."},{"i":55057,"n":"שניאורסון, שניאור זלמן מסטרודב","f":"צבי דוב לטקר","dt":"תרפח - כב סיון","b":"רב פעלים,רב בסטרודוב-תרס\"ז,רב ואדמו\"ר בהומל-תרס\"ט"},{"i":55058,"n":"שניאורסון, שניאור זלמן מקראקינ","dt":"תרמה","b":"רב בקראקינובה."},{"i":55059,"n":"שניאורסון, שניאור זלמן מרעפקא","f":"שלום דובער מרציצא","b":"נכד הצמח צדק. רב ברעפקא, טסראדוב."},{"i":55060,"n":"שניאורסון-טברסקי, מרדכי דב","f":"מנחם נחום מניעזין","k":"אדמור מטומשפיל","dt":"תרף - טז ניסן","b":"נכד אדמור האמצעי, ונכד ר יעקב ישראל טברסקי מטשרקאס מצד אמו - ומכאן שמו \"טברסקי\". חתן ר לוי יצחק משיטאווא (ברדיטשוב). רב בוארטיזשען, רב ואדמור בטומאשפיל(=טומפשיל)."},{"i":55061,"n":"שניאורסון-טברסקי, משה","f":"מרדכי דוב מטומשפיל","k":"אדמור מקוידנוב נ\"י","bp":"טשרקס","b":"נסמך מאת: ר דוד מקרלין, ר משה נחום ירושלמסקי. חתן האדמור ר יוסף בן אהרן מקוידנוב, וסייע לחותנו בניהול החצר, ויסד ישיבה. היגר לארה\"ב-תרפד וכיהן כאדמו\"ר בברוקלין."},{"i":55062,"n":"שניאורסון-פרלוב, יוסף יצחק","dt":"תשג","b":"רב בקיעלץ"},{"i":55063,"n":"שניאורסון-פרלוב, נח יוסף בועז","f":"יצחק פרלוב מוילקא","dt":"תרפו","b":"רב בקעליצא. חתן האדמור ר נחום בר שניאורסון מאווריטש-נכד הצמח צדק."},{"i":55064,"n":"שניבלג, דוד צבי","f":"מאיר מאמשטרדם","b":"האב ר מאיר עלה לארץ עם ר מנחם מנדל מויטבסק - חלה באמצע הדרך והתישב באמשטרדם שם כיהן כרב. נכד ר שאול ואהל. בנו ר חיים פאלאך מקולומיאה - רבו של האדמור מקוסוב."},{"i":55065,"n":"שניבלג, דוד צבי מויזניץ","f":"חיים מקולומיאה","bt":"תרנג","bp":"קולומיאה","dt":"תשכח","b":"חסיד ר משה מקוסוב, והאדמור מויזניץ. תלמיד ר דוד רייז, ור אשר אנשיל. חתן ר יצחק איזיק פרידלנדר מגרוסורדין ונכדתו של ר פנחס הורביץ מקוסוב בעל \"פתחא זוטא\". רב בוילחוביץ אצל ר חיים מאיר הגר, רב ור\"מ בויזניץ. ניצל מהשואה. דיין לעניני עגונות בדזורין, רב בגרוסורדין, העלמעץ, עבר לאנגליה-תשח וכיהן כרב במנצסטר, עלה לארץ-תשכד. בנו ר מנחם מנדל על מקומו אחריו במנצסטר."},{"i":55066,"n":"שניבלג, חיים מויזניץ","f":"דוד צבי מויזניץ","k":"בעל חשרת מים","bt":"תרצט","bp":"ויזניץ","dt":"תשמט","b":"עלה לארץ, חתן ר יצחק הלוי גרומן מאנגליה. סוחר בספרים נדירים ובעתיקות. חסיד סטמר. ממנו \"חשרת מים\" ניו יורק תשנב."},{"i":55067,"n":"שניבלג, חיים פאלאך מקולומיאה","f":"מאיר (שנבלג)","b":"רבו של האדמור מקוסוב. חתן ר שרגא פייוויש שנפלד מקולומיאה. בנו ר שמואל רב בקוסוב. ר מנשה אדמור בקוסוב."},{"i":55068,"n":"שניבלג, ישעיה","f":"דוד צבי מויזניץ","bt":"תרפ","bp":"מרגרטן","b":"תלמיד ישיבת ויזניץ. עלה לארץ אחרי השואה, רב שכונה בתל אביב, רב בבני ראם, חבר בבד\"צ בלז. חתן ר שלום איכנשטין מזידיטשוב, ובזיוו\"ש חתן ר דוד שפירא בעל \"בני ציון\"."},{"i":55069,"n":"שניבלג, מנחם מנדל","f":"דוד צבי מויזניץ","k":"בעל כה תאמר","bp":"ויזניץ","b":"ניצל מהשואה, ואחריה רב במחנות לנדסברג ווסרעלפינגן. רב במנצסטר על מקום אביו. חתן ר משה יהודה ערנרייך משאמשאג, ובזיוו\"ש חתן ר שרגא פאוויל וייס מבוארשא. חיבר \"כה תאמר\" ניו יורק תשמב, ועוד."},{"i":55070,"n":"שניבלג, שרגא פיביש","f":"דוד צבי מויזניץ","k":"בעל שרגא המאיר","b":"רב בלונדון. חתן ר משה מונד ממיקולייב. חיבר \"שרגא המאיר\" בני ברק תשלב, ועוד."},{"i":55071,"n":"שניד, יוסף מריבטיטש","b":"נכד ר יהושע מדינוב, עבר מריבטיטש לפרמשילא ועסק שם במסחר ספרים. הדפיס \"נפלאות ר יהושע מדינאוו\" - תרצז."},{"i":55072,"n":"שנידר, אריה ליב מזיימל","dt":"תשג","b":"רב בציימל(=זיימל). נספה בשואה."},{"i":55073,"n":"שנידר, ירוחם יעקב מבוברקא","b":"מחכמי בוברקא - מכתבים ממנו באוסף ר משולם ראטה."},{"i":55074,"n":"שנידר, ליב","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":55075,"n":"שנידר, מרדכי בצלאל","k":"בעל תורת הדקדוק","bt":"1871","bp":"ליגום","dt":"1941","dp":"וילנא","b":"למד שפות. חיבר ספרי לימוד בלשון. חיבר גם \"תורת הלשון העברית\" שחלקו השני נדפס-תש ואז פרצה המלחמה והספר לא הופץ. ערך קובץ \"מחקרי לשון\". נספה בשואה."},{"i":55076,"n":"שנידר, משה יהודה","bt":"תרמה","bp":"דזיווענישק","dt":"תשטו - כד כסלו","b":"תלמיד החפץ חיים ומקורבו. חתן היתומה שגדלה בבית החפץ חיים. שינה שמו לשניידר מאימת הצבא. הקים ישיבה בממל. עבר לפרנקפורט והקים בה ישיבה. ובהמשך ישיבות נוספות בגרמניה. עבר ללונדון-תרצ\"ח והקים את ישיבת \"תורת אמת\" המכונה \"שנידר\". חתנו - ר זיידל סמיאטיצקי לצדו בראשות הישיבה."},{"i":55077,"n":"שנידר, ניסן כץ מקראקא","b":"דיין בקראקא עם ר משה שמואל בלייכר ור מרדכי צבי כהנא שפירא."},{"i":55078,"n":"שנידר, צבי מסלובודקא","b":"ר\"מ בסלובודקה. פעיל בועד הישיבות ואגודת הרבנים לצדו של ר נחום ברוך גינצבורג. נספה בשואה."},{"i":55079,"n":"שנידר, שלמה מויליצקה","b":"מחכמי ויליצקה - מתורתו ב\"ועד חכמים\"."},{"i":55080,"n":"שנידר-שנפלד, משה חיים מסן פאול","f":"יקותיאל יהודה שנפלד","bt":"תרעו","bp":"סערענטש","dt":"תשלז - כד כסלו","dp":"זהרי חמה","b":"תלמיד הדעת סופר. חתן ר דוד לנדא ממישקולץ. ניצל מהשואה. רב בסן פאולו-תשי."},{"i":55081,"n":"שנידרמסר, מ' מלובלין","b":"מדפיס בלובלין. הדפיס \"הפרדס\" - תרצט."},{"i":55082,"n":"שניויס, יוסף הכהן מבוליחוב","b":"התגורר ברישא-תרם, רב בבוליחוב. סידר לדפוס \"נחלת יהושע\"."},{"i":55083,"n":"שניידמן, יעקב מבני ברק","k":"בעל גוילין ניצולין","bt":"תרסח","bp":"דוברובק-רוסיה","dt":"תשנה - כו שבט","dp":"בני ברק","b":"תלמיד ישיבות נוברדוק בקיוב ובמזריטש אצל תלמידי הסבא מנוברדוק. עלה לארץ-תרצב ולמד בישיבת \"בית יוסף\" - נוברדוק. ממקורבי החזון איש, יסד ישיבת \"תפארת ציון\" בהוראת החזון איש. חיבר \"גוילין ניצולין\" ובו שמועות מגדולי ישראל."},{"i":55084,"n":"שניידמן, יצחק מארה\"ב","f":"יעקב בן יונה","bt":"תרסה","bp":"פלשצניץ-פלך מינסק","b":"תלמיד ישיבת ליובאביץ, סלובודקא. נסמך מאת: ר שלמה דוד כהנא מוארשא, ר יהודה ליב הוטנר מוארשא, ר שמואל פריד מוילנא. חתן ר מנחם נחום. היגר לארה\"ב-תרפו וכיהן כרב קהלת אנשי בוברויסק בניו יורק, קהלת \"צמח צדק\". חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":55085,"n":"שניידר, יוסף זליג יודלביץ מויל","k":"בעל מקל נועם","b":"מחכמי פוניבז. חיבר ספרים נוספים."},{"i":55086,"n":"שניידרמן, בן ציון מלונדון","b":"רב בלונדון-תרע."},{"i":55087,"n":"שניידרמן, יעקב מבני ברק","b":"מנהל ישיבת \"תפארת ציון\" בבני ברק-תרצז."},{"i":55088,"n":"שניידרמן, שלום צבי מארה\"ב","f":"מאיר","bt":"תרנא","bp":"נעוועל-פלך ויטבסק","b":"תלמיד ישיבת \"תומכי תמימים\" בליובאביטש. חתן ר זלמן מלר. רב בקהלת \"דורשי שלום\" בפילדלפיה."},{"i":55089,"n":"שנייטוך, יוסף מאיר","f":"מאיר","k":"בעל שות ריבם שנייטוך","b":"אחיו של ר נתן מירושלים. רב בשנייטוך,פרידנטל-תקע."},{"i":55090,"n":"שנייטוך, משה מירושלים","f":"נתן מאיר שנייטוך","dt":"תרכא","dp":"ירושלים","b":"חתן ר יוסף בן משה מגיד. מחכמי ירושלים. חתניו - ר יעקב אורנשטין, ר יוסף בן בן ציון ליאון."},{"i":55091,"n":"שנייטוך, נפתלי","b":"רב בהענא-ת\"כ"},{"i":55092,"n":"שנייטוך, נתן מאיר מפיורדא","f":"מאיר","b":"תלמיד ר וולף המבורג, ודיין אצלו בפיורדא, דומ\"צ בשנייטוך-תקע. אחיו של ר יוסף מאיר שניטוך. בנו - ר משה יהודה מירושלים."},{"i":55093,"n":"שניפישוק-קהילה","b":"פרבר של וילנא. היתה כפופה לאב\"ד וילנא עד פטירת האב\"ד האחרון ר שמואל, ומאז מינתה מו\"ץ לעצמה. רבנים: ר משה בן יוסף הלוי-נפטר תקעט, ואחריו ר פנחס בן יהודה - דער פאלאצקער מגיד בעל \"מגיד צדק\"-נפטר תקפג, ואחריו ר דוד יהודה ליב טיללעס בן דב בר מאטאקאליע-נפטר תקצה, ואחריו ר אליעזר אליהו דייכס-שעבר לוילנא ואחריו ר בנימין מרדכי טיללעס בן הרד\"ל, ואחריו-תרלו ר שמואל מרדכי ראשקעס בן צבי הירש."},{"i":55094,"n":"שניפישקי, שמואל","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":55095,"n":"שניץ, זאב וולף","b":"תשובה אליו בשו\"מ."},{"i":55096,"n":"שניצלר, שלום מלונדון","f":"שמואל שרגא מטשאבא","dt":"תשמט - כא אדר","dp":"לונדון","b":"אב\"ד קהילת טשאבא בלונדון."},{"i":55097,"n":"שניצלר, שמואל שרגא מטשאבא","k":"אדמור מטשאבא","dt":"תשב - כז תשרי","b":"אדמור מטשאבא, ונהג במנהגי החת\"ס. נספה בשואה. חיבר \"ברכת שמואל\". בנו ר שלום מלונדון."},{"i":55098,"n":"שניצר, אברהם מורז'אן","b":"רב בורז'אן על מקום ר אברהם אבא, ור יוסף אביגדור קסלר על מקומו אחריו."},{"i":55099,"n":"שניצר, אברהם מראסיין וראזאליא","f":"יעקב מראסיין וירושלי","dt":"תרעא - יד תמוז","b":"אב\"ד ראזאליא, וארזאן-פלך קובנא. הניח חבור על שו\"ת - בכת\"י. בנו - ר משה מלאקובה, ר מאיר מענדינגן-שוייץ, ר דב בער משאדובה. אחיו מאמו - ר משה זאב ברוידא מואקשנא."},{"i":55100,"n":"שניצר, אריה יהודה מקריליב","b":"רב בקריליב-תרצה."},{"i":55101,"n":"שניצר, דובער מסימנא","dt":"תשג","b":"רב בקובארסק, רבה האחרון של סימנה(=סימנע). נספה בשואה."},{"i":55102,"n":"שניצר, זליג מוארשא","b":"ר\"מ בישיבת \"בית אברהם\" - וארשא תרצד (סוכצ'וב). עורך כתב העת \"בית אברהם\" - וארשא תרצד כנראה ביחד עם ר ליבל אלבינגר. כתב העת נוסד ע\"י תלמידי ר אברהם מסוכטשוב בעל \"אבני נזר\"."},{"i":55103,"n":"שניצר, חיים הלוי מהורודנקה","f":"מרדכי זאב מקיטוב","bt":"תרל","bp":"הורודונקה","dt":"תשד","b":"מצאצאי ר משה מקיטוב. חתן ר אלימלך אשכנזי מהורודנקה. סירב לרבנות העיר, העמיד תלמידים רבים."},{"i":55104,"n":"שניצר, יעקב מקרילוב","b":"פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":55105,"n":"שניצר, מאיר מענדינגן","f":"אברהם מראסיין וראזאל","b":"רב בענדינגן-שוייץ. אחיו - ר משה מלאקובה, ר דובער משאדובה."},{"i":55106,"n":"שניצר, מרדכי מירושלים","f":"שמואל","k":"מרדכי פתח - מחוקק","dt":"תרכו - יא חשון","dp":"ירושלים","b":"נמנה על עשרת העולים האשכנזים הראשונים לירושלים, אומן מוכשר (ומכאן כינויו \"פתח\" ו\"מחוקק\"), מחכמי ירושלים, ובקי בקבלה. ראש משפחת שניצר בירושלים. נפטר במגפת הכולירה בירושלים-תרכו."},{"i":55107,"n":"שניצר, צבי מירושלים","f":"מרדכי","dt":"תרסא - טו סיון","dp":"ירושלים","b":"מחברי החברא קדישא בהר הזיתים בירושלים."},{"i":55108,"n":"שנירר, ניסן מזקליטשין","f":"אברהם הכהן","bt":"תרך","dt":"תרצד","b":"חסיד בובוב. בן דודה של שרה שנירר (מיסדת \"בית יעקב\"). תלמיד ר משה יהודה אפטר מטורנא. רב בזקליטשין-תרנא, קראקא. בנו ר משה על מקומו אחריו בזקליטשין."},{"i":55109,"n":"שנירר, שרה","bt":"תרמג","bp":"קראקא","dt":"תרצח","dp":"קראקא","b":"מיסדת בית הספר \"בית יעקב\" בפולין."},{"i":55110,"n":"שנעה, אברהם מסקאהל","b":"חסיד בלז מחכמי סקול. חתן ר אברהם אבלי שנבלום משצריץ. בנו ר אהרן רבה של טויסט."},{"i":55111,"n":"שנעה, אהרן","f":"אברהם מסקול","b":"גביר חסיד בלז מחכמי סקול בזמן מהר\"א מבלז. חתן \"החבצלת\". אחיו של ר אריה ליבוש."},{"i":55112,"n":"שנעלנקער, יצחק צבי מירושלים","b":"מראשי כולל הו\"ד בירושלים."},{"i":55113,"n":"שנעפ, צבי יצחק","k":"בעל עולת יצחק","bt":"תקעב","bp":"דרוהוביטש","dt":"תרמה","b":"תלמיד מהריא\"ז. סירב לרבנות. חיבר \"עולת יצחק\" דרוהוביטש תרנט."},{"i":55114,"n":"שנפלד משה בן נחום","bt":"1910","dt":"ה'תשלה 1975","bk":[["ילדי טהרן מאשימים",""],["למען דעת",""]]},{"i":55115,"n":"שנפלד, אביגדור מפרשבורג ולונדו","f":"יעקב","bt":"תרמ","bp":"פרשבורג","dt":"תרצ - א טבת","b":"תלמיד ישיבת ר יצחק שויגר בגורס טופאלצן, השב\"ס בפרשבורג. נסמך מאת: ר יצחק שויגר, ר עקיבא סופר מפרשבורג. מראשי \"אהבת ציון\" בפרשבורג, רב בלונדון-תרסח, עלה לארץ והיה מפקח על חינוך ה\"מזרחי\" בארץ ישראל. פרסם מאמרים בכתבי עת."},{"i":55116,"n":"שנפלד, אברהם מאיוד","dp":"ירושלים","b":"רב באיוד(=נאג'-אניד)-תרף. ניצל מהשואה, ואחריה רב בקלויזנבורג-תשו, עלה לארץ-תשיט והתישב בירושלים."},{"i":55117,"n":"שנפלד, אברהם מלונדון","bt":"תרמ","b":"רב בלונדון תרס\"ט"},{"i":55118,"n":"שנפלד, אברהם ממיהאי-פאלוא","f":"משה יוחנן שנפלד","dt":"תרפז - כח חשון","b":"דומ\"צ במיהאי-פאלווה(=ערמיהאליפאיוא)-תרם."},{"i":55119,"n":"שנפלד, אברהם מעניעד וירושלים","f":"אהרן דוד","k":"בעל שארית אברהם-תשל","dt":"תשכח - כג שבט","dp":"ירושלים","b":"תלמיד השב\"ס. חתן ר חיים יהודה הלוי(=לעווי) מטימשואר. רב בעניעד-תרפה. ניצל מהשואה, ואחריה רב בקלויזנבורג. עלה לארץ-תשך וכיהן כרב בשכונת גבעת מרדכי בירושלים. בנו ר משה יוחנן הו\"ל את ספר אביו \"שארית אברהם\" ירושלים תשל, עם הקדמה מחתנו ר אלישע מיכאל פרידמן ובה מתולדות המחבר."},{"i":55120,"n":"שנפלד, אליעזר מקרולי ונ\"י","f":"משה מפעטראווסלע","bt":"תרמ-א","bp":"באטש או פעטראווסלע","dt":"תשלד - ט שבט","dp":"ניו יורק","b":"תלמיד השב\"ס, ור יהודה גרינולד בשוראן, ר אליעזר דייטש. מפעילי אגודת \"אהבת ציון\" בפרשבורג. חתן ר אפרים פירטה מקראלי. רב בפאקראץ-תרסז, וינקוועצי-תרע, קראלי על מקום חותנו-תרעג, היגר לארה\"ב-תרפב וכיהן כרב בניו יורק-תרפה. בזיוו\"ש חתן ר צבי בלוי. (מקום לידתו לדעת אחרים - באטשקא-הונגריה)."},{"i":55121,"n":"שנפלד, אלעזר מצאנז","b":"מחכמי צאנז. תשובה אליו ב\"הרי בשמים\"-תרם."},{"i":55122,"n":"שנפלד, בנימין ממיהאלפאלוא הנכד","f":"משה יוחנן ממיהאיפאלו","bt":"תרלב","bp":"מיאהאי-פאלווא","dt":"תש..","b":"תלמיד הקדושת יו\"ט בסיגט. חתן הגביר ר מרדכי פריינד מסטמר. רבה האחרון של מיהאי-פאלווא(=ערמיהאלפלווא)-תרעג על מקום אביו. נספה בשואה."},{"i":55123,"n":"שנפלד, בנימין ממיהאלפאלוא הסבא","b":"בנו ר משה יוחנן - רב במיהלאפאלוא, ונכדו ר בנימין רב שם."},{"i":55124,"n":"שנפלד, ברוך מטיסמניץ","k":"בעל צרור פרחים","b":"סופר-תר. חיבר גם \"שלמי תודה\" לכבוד ר גבריאל ריסר, \"ענף עץ אבות\", \"מנחה בלולה\"."},{"i":55125,"n":"שנפלד, דובער מראסיין","f":"אהרן","k":"ר בערציק מאירמ'ס","dt":"תרסז - כא טבת","dp":"ראסיין","b":"נכד ר צבי הירש מצייקישוק-פלך קובנא. ר\"מ בראייסן. בנו - ר צבי נתן קפלן מראסיין וקארקלאן."},{"i":55126,"n":"שנפלד, דוד צבי מבוקרשט","f":"יצחק איזיק מברודי","bt":"תרכה","dt":"תרצו","b":"חסיד רח\"ה מאלסק, ורבי ישראל מויזניץ. חתן ר יצחק איזיק שור מבוקרשט. רב ברומן-תרמח, זלישטשיק-תרנה על מקום חותנו וגיסו, רב בבוקרשט תחת גיסו ר חיים שמואל שור. רוב כתביו אבדו בשואה."},{"i":55127,"n":"שנפלד, חיים אביגדור מלונדון","f":"יעקב","bt":"תרמ","bp":"שוטו","dt":"תרץ - א טבת","dp":"לונדון","b":"תלמיד השב\"ס, ור יצחק שווייגר מטאפלטשן. חתן ר יוסף שטרנברג מבודפשט. רב בוינה, לונדון-תרסט ובנו ר שלמה על מקומו אחריו. מייסד אגודת הרבנים האורטודוקסים בבריטניה."},{"i":55128,"n":"שנפלד, חיים יהודה מקילץ אנגל","f":"חנוך הניך","k":"אדמור מקילץ באנגליה","dt":"תשכח - יג אלול","b":"חתן ר אלימלך יעקב יצחק מסוכידניוב. היגר לאנגליה-לפני השואה, וכיהן כאדמור מקילץ באנגליה. עלה לארץ."},{"i":55129,"n":"שנפלד, יוסף הכהן מטיסא רפפורט","f":"יצחק שנפלד-רפפורט","k":"בעל כסף ישיב","bt":"תרלח","dt":"תרצג - יב שבט","dp":"סעליש","b":"תלמיד השב\"ס. חתן ר פנחס חיים קליין מסעליש. דיין בטיסא-אוילאק-תרסב, סעליש. בנו ר שלמה יצחק רב בטיסא-אוילאק."},{"i":55130,"n":"שנפלד, יוסף שאול מניר-אדאני","f":"משה יוחנן שנפלד","dt":"תשד","b":"רב בניר-אדאני"},{"i":55131,"n":"שנפלד, יחזקאל ממיהאליפלווא","dt":"תשד","b":"רב במיהאליפלווא"},{"i":55132,"n":"שנפלד, יחיאל מיכל צבי מוארול","k":"בעל מימי צבי-תרצו","dt":"תרמה-ח","dp":"ירושלים","b":"רב בואראהל(וארול)-תרי, עלה לירושלים-תרמד וכיהן כדיין. חתנו ר יצחק ישכר פרידמן הו\"ל את ספרו."},{"i":55133,"n":"שנפלד, יעקב בער מסיקסא","dt":"תקע","b":"רב בסיקסא-תק\"ל"},{"i":55134,"n":"שנפלד, יעקב מאיר מבריסטד","f":"פסח אברהם מקורימה","bt":"תרל","dt":"תשד","b":"רב בקורימא, חתן הגביר ר שלמה הלוי אדלר מבריסטד וכיהן כרב בבריסטד. נספה בשואה."},{"i":55135,"n":"שנפלד, יצחק איזיק מברוד","bt":"תקפג","bp":"ברודי","dt":"תרף","b":"תלמיד דודו ר יוסף חנניא מייזליש מפרמישלא שהזכירו בספרו \"תפארת יוסף\". חתן הגביר ר יעקב וייס (לאחר שאביו בתשובה להצעת המהרש\"ק דרש נדוניה שהמרש\"ק לא יכל לעמוד בה). רב בברודי על מקום ר יצחק חיות."},{"i":55136,"n":"שנפלד, יצחק מאסאד","dt":"תרכד - כ סיון","b":"רב באסאד"},{"i":55137,"n":"שנפלד, יקותיאל יהודה מראצפרט","f":"יצחק שנפלד-רפפורט","dt":"תשד","b":"דומ\"צ בראצפערט"},{"i":55138,"n":"שנפלד, מיקלוש מאראד","b":"רב בקהילה הניאולוגית באראד. עלה לארץ והתישב בקרית מוצקין."},{"i":55139,"n":"שנפלד, מרדכי ממיהאי-פאלווא","f":"אברהם ממיהאיפאלווא","b":"דיין במיהאי-פאלווא-תרפט על מקום אביו. נספה בשואה."},{"i":55140,"n":"שנפלד, מרדכי מערמיהאליפאלווא","dt":"תשד","b":"רב בערמיהאליפאלווא"},{"i":55141,"n":"שנפלד, מרדכי משימונדא","b":"רב בשימונדא (הונגריה)."},{"i":55142,"n":"שנפלד, משה יוחנן ממיהאי-פאלוא","f":"בנימין ממיהאלפאלאוא","k":"בעל נחלי מים","r":"אב\"ד ור\"מ דק\"ק מיהאי-פאלווא","bt":"תרט או תריח","dt":"תרעג - כ סיון","dp":"מיהלאפאלוא","b":"נכד ר יוחנן רוזנברג ממיהאי פאלווא. חסיד ה\"דברי חיים\" מצאנז ו\"הייטב לב\" מסיגט. תלמיד הכת\"ס. חתן הגביר ר מרדכי מארקל פרידמן מכפר מיקולא-ליד סטמר ועבר לשם. רב במיהאי פאלווא(=מיהאלפאלווא)-תרנא ובנו ר בנימין על מקומו אחריו. מחותן עם ר שמעון סופר מערלוי, ונכדו ר יוחנן סופר האדמור מערלוי(=אויהל) בירושלים. פרסם מאמרים ב\"תל תלפיות\".","bk":[["נחלי מים - חידושי סוגיות",""]]},{"i":55143,"n":"שנפלד, משה מלוקב","bt":"תרלא","dt":"תרצה - טו ניסן","b":"רב בלוקב-תרע\"ד"},{"i":55144,"n":"שנפלד, משה ממדזילברץ","f":"אליעזר","bt":"תקע","dt":"תרמד","b":"מחכמי מדזילברץ (סלובקיה). חתן רצ\"א מדינוב בעל \"בני יששכר\". אחיינו ר מאיר יהודה שפירא על מקומו אחריו באופן זמני עד שיגדל בנו ר צבי אלימלך."},{"i":55145,"n":"שנפלד, משה מפעטראווסלע","b":"חתן ר יצחק צבי רוטר מנאדי-סנט מיקלוש. בנו - ר אליעזר מקראלי וניו יורק."},{"i":55146,"n":"שנפלד, משה מרדכי משימנדי","f":"יעקב בער מסיקס","k":"בעל תוספת מרדכי","bt":"תקן","dt":"תרכח - כד תשרי","b":"רב בטיסא-פירד, שארקאד, שימאנדא(=שימנדי)-תרה. נזכר ב\"שואל ומשיב\"."},{"i":55147,"n":"שנפלד, פסח אברהם מקורימה","f":"משה ממדזילברץ","bt":"תקפא","dt":"תרנח או תרסו","b":"נכד הבני\"ש. חתן ר עזריאל גרין ממונקטש בעל \"נחלת עזריאל\". רב בכמה קהליות ואחריהם בקורימה (מחוז שאראש בהונגריה)-תרח. חתנו ר יעקב וייס על מקומו אחריו."},{"i":55148,"n":"שנפלד, צבי אלימלך","f":"יעקב מאיר מבריסטר","k":"בעל תורת חסד","b":"חתן ר אהרן מתתיהו. ניצל מהשואה. בזיוו\"ש חתן ר נפתלי שכטמן. עלה לארץ-תשלה וכיהן כרב בירושלים. חיבר \"תורת חסד\" ירושלים תשלז."},{"i":55149,"n":"שנפלד, צבי אלימלך ממדזילברץ","f":"משה","bt":"תרי","dt":"תרפז","b":"נכד הבני\"ש. חתן ר משולם דב קליש ממונקטש. רב במדזילברץ-תרמב (רבים מתושבי העיר היו מנכדי הבני\"ש). נכדו - ר משה רוטנברג מנבלעצקע, שהיה מועמד לרב אחריו ולא נבחר קיבל פיצוי מהקהלה."},{"i":55150,"n":"שנפלד, שלמה יצחק הכהן","f":"יוסף מטיסא-אוילק","dt":"תשד","b":"רב בטיסא-אוילאק"},{"i":55151,"n":"שנפלד, שלמה יצחק ממילווקי-ארהב","bt":"תרך","bp":"שקודוויל","dt":"תשג","dp":"מילווקי","b":"תלמיד ישיבת קובנא. היגר לארה\"ב-תרנא וכיהן כרב במילווקי בקהילת \"בית ישראל\". יו\"ר הסתדרות ציוני אמריקה."},{"i":55152,"n":"שנפלד, שלמה מלונדון","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":55153,"n":"שנפלד, שמואל מנביליץ","bt":"תרך","dt":"תרץ","b":"רב בניליץ (ליד סטריזוב)-תרנט. חתנו ר משה רוטנברג על מקומו אחריו-תרץ (ולא על מקום זקנו ר צבי אלימלך שינפלד)."},{"i":55154,"n":"שנפלד, שמואל מקשוי","f":"משה יוחנן שנפלד","b":"רב בקאשוי-תר\"פ"},{"i":55155,"n":"שנפלד-רפפורט, יצחק הכהן מסטמר","b":"אביו של ר יוסף הכהן שנפלד מטיסא-אוילאק וסעליש."},{"i":55156,"n":"שנצר, אהרן ממילובקה","dt":"תשג","b":"רב במילובקה-תרפב. נספה בשואה. חתנו שניצל, היה ר אשר זליג ערליך. (אולי בנו הוא ר זאב שנצר שנרשם אף הוא כרב במילובקה)."},{"i":55157,"n":"שנצר, דב בר מדעש","b":"דיין בדעש תרפ\"ו"},{"i":55158,"n":"שנצר, מנחם ישכר דוב מדעש","bt":"תרמו","bp":"הוניאד","dt":"תשד","dp":"אושוויץ","b":"חתן נכדת ר יצחק ורצברגר מדעש. דומ\"צ בדעש על מקום חותנו זקנו. נספה בשואה. מתורתו ב\"קרבן משה\" לר משה זאב פרידמן - יפו תשמו. פרסם מאמרים ב\"עמוד התורה\" - דעש תרצב."},{"i":55159,"n":"שנצר, נתן הכהן מצאנז","b":"רב בצאנז. פרסם מאמרים ב\"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא."},{"i":55160,"n":"שנצר, שמחה","b":"תשובה אליו ב\"כנף רננה\"-תרמד."},{"i":55161,"n":"שנק, צבי הרש מוינה","f":"יהודה מטאפלטשן","bt":"תרלו","bp":"טאפלטשאן","dt":"תשה - כ תשרי","dp":"ירושלים","b":"תלמיד השב\"ס. חתן ר גבריאל פישר מוינה, ועבר לשם. רב בוינה. עלה לירושלים-תש."},{"i":55162,"n":"שנקל אלעזר בן יעקב","bt":"1865","dt":"ה'תש 1940","bk":[["ארובות השמים",""],["מעשיות מצדיקי יסודי עולם",""],["מעשיות נוראים ונפלאים",""],["מעשיות פליאות",""],["מעשים טובים",""],["נוראות אנשי מעשה",""],["נפלאות גדולות",""]]},{"i":55163,"n":"שנקל, אליהו","f":"זאב דב מגיד מטורנא","b":"מחכמי טורנא. תשובה אליו מבן דודו ר יעקב שור ב\"דברי יעקב\"."},{"i":55164,"n":"שנקל, אליעזר","f":"יעקב","k":"בעל מעשיות פליאות","bt":"תרכה","dt":"תש","b":"מו\"ל וסוחר ספרים בטרנוב. חיבר \"מעשיות פליאות נוראים ונפלאים\" למברג תרמג, ועוד."},{"i":55165,"n":"שנקל, זאב דב מטרנוב","k":"בעל מגיד צדק","bt":"תקע","dt":"תרלח - כה סיון","b":"נכד ר השל. תלמיד החתם סופר, ור יעקב אורנשטין מלמברג, ור אריה הלר בעל הקצות והדברי חיים מצאנז ועוד. רב בטרנוב(=טורנא)-תרך ומתלמידיו - ר אברהם אביש ריינהולד מטורנא, ור יצחק איזיק בוימגרטן מקורטשין. בנו ר יעקב על מקומו אחריו. חיבר \"מגיד צדק\" קראקא תרנד."},{"i":55166,"n":"שנקל, יעקב","f":"זאב דב מטרנוב","k":"בעל תפלה ליעקב","b":"מו\"ל וסוחר ספרים, רב בטרנוב על מקום אביו. חיבר \"תפלה ליעקב\" פודגורזע תרס, ועוד."},{"i":55167,"n":"שנקמן, ישראל","b":"רב באטלנטיק-סיטי,עלה לירושלים-תרצ\"ב"},{"i":55168,"n":"שנקר - שיינקער - משפחה","b":"מקור השם \"מוזג\" ומוצא המשפחה מרגשבורג, אחרי גירוש רעט."},{"i":55169,"n":"שנקר, אברהם","b":"מאמרים ממנו ב\"תבונה\" - ירושלים תשא וכן מכתבים ששלח אליו ר שמחה זיסל זיו מקעלם."},{"i":55170,"n":"שנקר, אברהם תניס","f":"אהרן","k":"אברהמצ'יק תניס","bt":"תרו","bp":"סלובודקה","dt":"תרמד","dp":"מיהראן","b":"תלמיד ר ישראל סלנטר. חתן ר תנחום ונקרא ע\"ש \"תניס\". יסד את \"כולל הפרושים\" בסלובדקה וקובנא, יחד עם ר נ\"צ פינקל, היה אצל הברון שמעון זאב רוטשילד בפרנקפורט וקבל ממנו קצבה גדולה עברו הכולל - שפעל להפצת תורת המוסר. היה שותף להקמת ישיבת \"כנסת ישראל\" בסלובודקה והגיד שם שיעורים. בסוף ימיו רב באלקסוט."},{"i":55171,"n":"שנקר, בנימין מקשנוב","f":"חיים מאושפיצין","bt":"תריא","dt":"תרפח","b":"גביר וסוחר יערות בקשנוב. חתן ר שבתי בורנשטין. עסקן ציבור ועמד בראש מוסדות תורה וחסד."},{"i":55172,"n":"שנקר, זוסמן מקראקא","bt":"תקסט","dt":"תרסא","b":"תלמיד ה\"ברוך טעם\", גביר בקראקא ממיסדי ביהמ\"ד הגדול."},{"i":55173,"n":"שנקר, חיים מאושפיצין","f":"דוד מטשבין","k":"בעל תולדות חיים","b":"חסיד צאנז מקשנוב, וסוכא. בזיוו\"ש שני חתן נכדת המג\"ע. בעל אחוזה (בעצת הדברי חיים) ועשיר מופלג, מראשי קהילת אושפיצין. נכדו ר דוד יעקובוביץ חיבר \"תולדות חיים\" על משפחתו ותולדותיו עם פירוט הצאצאים."},{"i":55174,"n":"שנקר, יהושע ליב מירושלים ארה\"ב","f":"שמואל הלל","bt":"תרע","bp":"ירושלים","b":"נכד ר אברהם טאניס מסלובודקא ודאלעקסאט, ונכד(-אבי אמו) ר יוסף חיים זוננפלד. תלמיד ישיבת \"עץ חיים\" בירושלים, ישיבת חברון. נסמך מאת: ר יחזקאל סרנא, ר יעקב משה חרלפ, ר מיכל הורביץ. חתן ר צבי אריה לוי (נכדת - ר שמואל לוי המכונה שמואל אמריקנר). הגיע לארה\"ב-תשב וכיהן כרב קהלת \"אנשי אמונה\" בבולטימור, קהלת \"רבנו יוסף חיים\"-תשו."},{"i":55175,"n":"שנקר, יצחק אהרן","f":"חיים מאושפיצין","bt":"תרח","dt":"תרצב","b":"גביר בעל נכסים ותלמיד חכם מכפר זמבזיצה (מחוז ודוביץ), עבר לקראקא-תרף. בזיוו\"ש חתן ר נפתלי יער מברודי."},{"i":55176,"n":"שנקר, יצחק ישעיה מלמברג","b":"בחור תלמיד חכם מלמברג - תשובות אליו ב\"משיב לשום\"-תרפט, ועוד. פרסם מאמרים ב\"אור תורה\" - לבוב תרפו. עורך \"יבנה\" - לבוב תרפט."},{"i":55177,"n":"שנקר, מיכאל מהלובאקע","b":"גביר תלמיד חכם בהאלובאקע. מחותן עם ר בנימין לוין מויאזמא."},{"i":55178,"n":"שנקר, צבי הירש מבלז","dt":"תש..","b":"רב בשברשין, בלז. נספה בשואה."},{"i":55179,"n":"שנקר, שמואל הלל","f":"אברהם טאניס","b":"חתן ר יוסף חיים זוננפלד. רב בירושלים-תרע. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז. בנו - ר יהושע ליב מארה\"ב."},{"i":55180,"n":"שנקר, שמואל יהודה","f":"חיים מאושפיצין","bt":"תריב","dt":"תרפז","b":"חסיד צאנז. גביר ונשיא כולל גליציה (ופעל להגדלת ההכנסות גם בזמן המלחמה). חתן ר גצל מרגליות מקראקא (בהוראת הדב\"ח שהורה לא לבטל השידוך אף שהמחותן לא יכל לסלק הנדוניה). נפטר ללא ילדים."},{"i":55181,"n":"שנקר, שמעון זאב מירושלים","b":"נכד ר יוסף חיים זוננפלד. חתנו - ר יצחק צבי ברנפלד מגענף - בני ברק."},{"i":55182,"n":"ש\"ס, אברהם חיים","f":"שמואל","bt":"תריח","bp":"בוגוסלוישוק-ליד וילקומיר","dp":"ז'וסלי","b":"נכד ר דוד-רבה של ז'וסלי בן יצחק בן שלמה זלמן מוילנא. חתן ר ידידיה גינצבורג מז'אזמיר. רב בדרשונישוק-תרמז, ז'וסלי(=זאסלי)-פלך וילנא-תרמח. הניח חדושים בכת\"י."},{"i":55183,"n":"ש\"ס, חיים אברהם מדרשונישוק","b":"רב בדרשונישוק-תרמז על מקום ר חיים ירמיהו פלנסברג, זאסלו(=ז'וסלי)-תרמו."},{"i":55184,"n":"ש\"ס, שמשון מז'וסלי","bp":"ז'וסלי","b":"מגיד בליטא."},{"i":55185,"n":"שסקין, ישעיה משה מסמילישוק","dt":"תשג","b":"רבה האחרון של סמילישוק(=סומלישאק). נספה בשואה."},{"i":55186,"n":"שעברשין מפרג","k":"בעל קטורת סמים","b":"רב בפרג בזמן בעל עוללות אפרים. חיבר \"קטורת סמים\" - פרג שסט."},{"i":55187,"n":"שעדיה, משה אשר מיוזיל-היסאר","b":"דיין ביוזיל-היסאר-שנות ה-ת', אצל ר אברהם רולו."},{"i":55188,"n":"שעוועלאוו","bt":"תרו","dt":"תרפד - ב סיון","b":"רב בסויסלוביץ"},{"i":55189,"n":"שעיא ן, יהודה מאלגיר","bt":"תקע","dt":"תרם - בערך","b":"רב בווהראן. נזכר ב\"פרקי אבות\" ברלין תרח, ו\"זבחים שלמים\"."},{"i":55190,"n":"שעיא ן, יעקב מסאלי","b":"רב בסאלי-מרוקו, נזכר ב\"משפט וצבי\" בענין אורז בפסח. יתכן והוא ר יעקב אחרפי ן שעיא."},{"i":55191,"n":"שעיא ן, שלמה מאלגיר","bt":"תץ - בערך","dt":"תקס - בערך","b":"רב במסתגאנם. תשובות אליו ב\"זרע יעקב\" לר שלמה בן שעיא."},{"i":55192,"n":"שעיה ן, סעדיה ממראקש","b":"מחכמי כפר באזור מראקש, חתם-תקו עם רבני מראקש."},{"i":55193,"n":"שעיה, ישראל מראבאט וגיברלטר","b":"מחכמי ארבאט(=ראבאט), כנראה שהיה מו\"ץ בגיברלטר-תקצד, חתם על פס\"ד-תקץ עם ר אליהו ביבאס, ר שמעיה רופא."},{"i":55194,"n":"שעיו, אדמון","bt":"תרץ-יג אייר","bp":"חלב","dt":"תשנח - ט טבת","dp":"ירושלים","b":"עלה לא\"י, מקובל, רב בירושלים"},{"i":55195,"n":"שעיו, עזרא","f":"יוסף","bt":"תרפג","dt":"תשמו - כד אב","dp":"ירושלים","b":"עלה לירושלים. ר\"מ ב\"פורת יוסף\", והמקובל ר מרדכי שרעבי היה שולח אליו תלמידים והעיד עליו שהוא אחד הידחים שיודע ללמד צעירים. סופר סתם וש\"ץ בביהכ\"נ עדס."},{"i":55196,"n":"שעפס, שמחה אברהם מארה\"ב","k":"בעל המתיבתא","b":"ר\"מ בישיבת \"תורה ודעת\" ניו יורק-תשג. עורך הירחון \"המתיבתא\" - נ\"י תשג, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":55197,"n":"שעק, הלל מברימליא","f":"צבי","bt":"תרלח","b":"נכד ר הלל שליט מהרובשוב. רב באלקסניץ-מחוז קרמניץ-תרס, בערימלה(=בערימליא)-ווהלין-תרסה."},{"i":55198,"n":"שער אריה, אברהם (פורטלאוני)","f":"דוד הרופא בן אלעזר","k":"בעל שלטי הגבורים","bt":"שב","dt":"שעב - כט תמוז","b":"תלמיד ר מאיר מפדובה, ר יוסף זרקא, ר יוסף סיני, ר יעקב מפאנו בבולוניה, ר יהודה פרובינצאלו ור אברהם פרובינצאלו . רב ורופא במנטובה בזמן הרמ\"ע מפאנו. חיבר \"שלטי הגבורים\" מנטובה שעב."},{"i":55199,"n":"שער אריה, דוד מאיטליה","f":"משה","b":"חתן ר יחיאל מילי. הו\"ל את ספר חותנו \"תפוחי זהב\" - מנטובה שפג."},{"i":55200,"n":"שער אריה, שלמה ממנטובה","k":"בעל פירוש ליו\"ד","b":"רב במנטובה. אחיו של ר שמואל שער אריה. חיבר פירוש ליו\"ד."},{"i":55201,"n":"שער אריה, שמואל מאיטליה","k":"בעל תקון הנפש","b":"רב באיטליה בכמה קהילות, בזמן רמ\"ע מפאנו, ור נתנאל טרבוט. חיבר ספרים רבים בכת\"י, ומהם \"חדושי שמואל\" על \"בית יוסף\". היה חדשן בהלכה ושנוי במחלוקת."},{"i":55202,"n":"שערבעל, משה","f":"מאיר","k":"בעל דער אונשטערבליכק","dt":"תרסג - כו כסלו","dp":"המבורג","b":"דרשן בברעסקאוו, שמיגעל, רייזען, גומבינען-אסט פרייסען-תרלח, בסוף ימיו עבר להמבורג. פרסם מאמרים בגרמנית."},{"i":55203,"n":"שערהיי, יואל שלום","b":"רב בריטאווע-תר\"ל"},{"i":55204,"n":"שערית, משה מפרס","f":"אהרן","b":"מחכמי פרס-רן, חיבור ממנו בכת\"י."},{"i":55205,"n":"שף, ישראל","k":"בעל עכסה בת כלב","bt":"1864","bp":"שקוד","dt":"1938","dp":"ליבאו","b":"תלמיד ישיבות ליטא, בקי בשפות. ישב בוארשא ופגש את י.ל. פרץ וחבורת ספורי האידיש סביבו, אך הוא נשאר נאמן לעברית. חיבר שירים, סיפורים היסטוריים ומחזות ותרגומים. חיבר גם \"הגאון מוילנא\" - וארשא תרסו. פעיל בתנועה הציונית."},{"i":55206,"n":"שפהויזן, מנחם מנדל כץ","b":"חיבר לוח בגרמניה-תקפה עבור אברהם בן יהודה מבלברן."},{"i":55207,"n":"שפוצ'ניק, יוסף מלונדון","f":"יהודה ליב","k":"בעל ברכת יוסף","bt":"תרמב","bp":"קישינוב","b":"נסמך מאת המהרש\"ם. היגר ללונדון-תרעג. התכתב עם חכמי דורו בענין תכניות להדפס הש\"ס, ועוד. הו\"ל ספרים ומאספים ובהם 'ראשי אלפי ישראל'-לונדון תרעה-ח, 'תקופה חדשה בישראל', ועוד. היה מחלוקת כנגדו לאחר שפרסם את 'לקרא לאסורים דרור', ו'חרות עולם' ובהם ביקש להתיר 40,000 נשים עגונות ממלחמת העולם הראשונה."},{"i":55208,"n":"שפיגל, אברהם דוד מרוהטין","f":"יצחק","bt":"תרמו","bp":"רוהטין","dt":"תשב","b":"חסיד צורטקוב. חתן ר אלישע אהרן קלרנט ונכדת הרח\"כ, ובזיוו\"ש חתן ר משה ראובן גינצבורג מחודרוב. רב ברוהטין-תרע. (דור שישי לר אברהם דוד משה אשכנזי רבה של רוהטין), לצד ר מאיר שמואל הענא ואח\"כ רב ראשי. תלמיד ר יעקב קאווי שיין הדיין ברוהטין. לאחר מלחמת העולם ה-I כשחרבה עירו כיהן זמן קצר בסטרי ואחר חזר לרוהטין וכיהן תחת ר מרדכי ליפא תאומים. נספה בשואה - ויומן שניהל בזמן השואה אבד."},{"i":55209,"n":"שפיגל, אברהם דוד משה מרוהטין","f":"צדוק","k":"אדם בעל שם","b":"נפגש עם הבעשט. לוחם בשבתאים ובפרנקיסטים. רב ברוהטין. חיבר \"מרכבת המשנה\" למברג תרנה, \"תולדות אדם\" - פירוש על ספרי - ירושלים תשלב."},{"i":55210,"n":"שפיגל, אברהם חיים מקלוש","b":"דיין בקלוש - לפני מלחמת העולם ה-I."},{"i":55211,"n":"שפיגל, אברהם חיים מקראקא","f":"ראובן ישכר","bp":"מיעכוב (פולין)","b":"תלמיד ר ישעיה שנפרוכט. עבר לקראקא ולימד בביהמ\"ד של ר ישראל מייזל לפרחי חסידים מכל האדמורים. חסיד צורטקוב."},{"i":55212,"n":"שפיגל, אלחנן יוחנן מארה\"ב","f":"נפתלי אריה האדמור מא","bp":"ואנגרוב","b":"תלמיד ר מנחם מנדל גוטרמן מרדזימין. נסמך מאת: ר אריה מרדכי רבינוביץ מקארוב, ר יוסף ויינריב מטורונטו. חתן ר ישראל אלעזר ואלגלרנטר. רב בניו יורק. פרסם מאמרים ב\"הבאר\". חבר אגודת הרבנים באמריקה."},{"i":55213,"n":"שפיגל, אליהו מדזיקוב","b":"רב בדזיקוב. תלמיד החוזה. על מקומו בחייו (קנה ממנו את זכות הרבנות) - ר אליעזר הורביץ."},{"i":55214,"n":"שפיגל, אלכסנדר מפמורן","b":"מחכמי פמורן. תשובה אליו ב\"בית דוד\"-תרעג."},{"i":55215,"n":"שפיגל, דוד מאלטונא","f":"טוביה מפעטשי-ניידארף","bt":"תרכט","dt":"תרפט - ז שבט","dp":"אלוטנא","b":"תלמיד השב\"ס. חתן ר אהרן יהודה ליב ב\"ר ישראל הכהן שו\"ב בוינה. רב באלטונא."},{"i":55216,"n":"שפיגל, טוביה מפעטשי-ניידארף","b":"חתן ר פנחס צבי (זליג הרש) פישהוץ מגאלאנטא. רב בפעטשי-ניידארף, וינה."},{"i":55217,"n":"שפיגל, יהושע מהומנא","f":"משה צבי מהומנא","k":"בעל פני שעשועים","bt":"תקצא","dt":"תרס","dp":"הומנא","b":"תלמיד הכת\"ס, ור שלמה גנצפריד מאונגוואר. מחכמי הומנא."},{"i":55218,"n":"שפיגל, יצחק נפתלי הרץ מצעהלים","f":"יחיאל מצעהלים","bt":"תרא","b":"תלמיד הכת\"ס. ראש הקהלה בצעהלים. מראשי הלשכה האורטודוכסית בהונגריה."},{"i":55219,"n":"שפיגל, ישכר מזידיטשוב","dt":"תרן","b":"נכד אב\"ד אטיניא בעל מופת. רב בזידיטשוב אצל המהרי\"א."},{"i":55220,"n":"שפיגל, ישעיה מארה\"ב","f":"יהודה אריה","bt":"תרסב","bp":"שניאדובה-פלך לומזה","b":"תלמיד ישיבת לומזה, סלובודקא. נסמך מאת: ר יצחק אייזיק שער מסלובודקא, ר בן ציון יהודה ליב זקש מנעמקשט, ר שלמה הלוי פיינזילבר מקידאן, ר שפטל קרמר מסלוצק, ר יעקב יצחק רודרמן מבולטימור. רב בקליבלנד-תרצג, ניו יורק. חבר אגודת הרבנים באמריקה."},{"i":55221,"n":"שפיגל, מרדכי שמואל","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":55222,"n":"שפיגל, משה","b":"רב-שנת תר\"נ"},{"i":55223,"n":"שפיגל, משה יוסף מקאפיש","b":"גביר בקאפיש, סייע-תשב בהדפסת אנשי מופת לברוין."},{"i":55224,"n":"שפיגל, נפתלי אריה מאוסטרובא","f":"משה-חתן יעקב יצחק","k":"אדמור מאוסטרובא","bt":"תרכט","bp":"לובלין","dt":"תשט - כ תשרי","b":"נכד האדמור ר יעקב יצחק אונגר מקאלושין. רב בטשכוב, מאנקאביד, אדמור באוסטרובה, קאלושין. היגר לארה\"ב-תרפו. בנו - ר אלחנן יוחנן מניו יורק."},{"i":55225,"n":"שפיגל, שמואל בנימין וולף","f":"יצחק נפתלי מצעהלים","b":"מחכמי וויצען. חתנו - ר ישראל וועלץ מבודפשט - ירושלים."},{"i":55226,"n":"שפיגל, שמעון מירוסלב","f":"אברהם שלמה","bt":"תרלב","bp":"זולקוא","dt":"תרצז","b":"הקים בירוסלב חברה \"שפה ברורה\" ללימוד עברית, ויו\"ר המזרחי בעיר. עלה לארץ-תרצה והתגורר בחיפה. (בנו שמואל פעיל בעסקי סרטים בהוליבוד). פרסם מאמר בכתב העת \"רוח הזמן\" - קראקא תרנא."},{"i":55227,"n":"שפיגל-גלס, נתן מוארשא","k":"בעל מאורות נתן","b":"עשיר, דיין בוארשא, ראב\"ד שם-תרל, ראש ישיבת \"עמק הלכה\"-תרצו. פרסם מאמרים ב\"עמק הלכה\" - וארשא תרפו."},{"i":55228,"n":"שפיגלמן, אהרן מטשערושזע","f":"יהושע","bt":"תרלד","b":"מצאצאי בעל \"מאיר נתיבים\". רב בטשעראזא(=טשעראשזע)-פלך קיוב-תרס."},{"i":55229,"n":"שפיגלמן, מנחם יצחק מסלאווקוב","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":55230,"n":"שפיגלר, דוד","dt":"תרנח - יח אלול","b":"רב בדינדיש"},{"i":55231,"n":"שפיגלר, חיים שלמה ממושציסק","b":"מחכמי מושציסק - תשובה אליו ב\"אבן יקרה\"."},{"i":55232,"n":"שפיטלביץ, ירוחם פישל","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":55233,"n":"שפייר, ברמן מאשכנז","b":"גביר באשכנז-תקיז, תרם לקהלת האשכנזים בארץ ישראל."},{"i":55234,"n":"שפייר, יחיאל מיכל מהמבורג","dt":"תקפב","dp":"אה\"ו","b":"בזיוו\"ש חתן ר רפאל הכהן מהמבורג (אלמנת ר צבי הירש יאנובר מפיורדא). רב בגאלהויזן(=געלנהויזן), מדינת מרהולץ(=מעהרהאלץ), דעסוי, דיין בהמבורג. פעל נגד הריפורמים-תקעט - למרות שהיה גיסו של ראש הטמפל הריפורמי - אליעזר ריסר. מתורתו ב\"שאלת כהנים\" לחותנו, וב\"מרפא לנפש\". הסכים על \"דמשק אליעזר\"."},{"i":55235,"n":"שפייר, יעקב מלונדון","b":"דיין בוילקוביסק, לונדון."},{"i":55236,"n":"שפייר, יצחק איצק מברלין","f":"יעקב מפפד\"מ","dt":"תקמה - י שבט","dp":"ברלין","b":"חתן ר דוד פרנקל בעל \"קרבן העדה\". מדפיס בברלין. נפטר ללא ילדים."},{"i":55237,"n":"שפייר, יצחק מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקן, השתתף במשלחת אל הקיסר ליאופולד, עם חבריו ר יוסף גונדרשהיים, ור שלמה האז. השתתפו גם במשלחת אל הקיסר פרנץ השני-תקנב."},{"i":55238,"n":"שפייר, ירמיה מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט, ועל מינו ר יעקב יהושע בעל \"פני יהושע\"-תץ."},{"i":55239,"n":"שפייר, מיכאל מדעסוי","b":"רב בדעסוי-תק\"פ"},{"i":55240,"n":"שפייר, מיכאל מפפד\"מ","dt":"תנב","b":"סירב לרבנות הנאו, דיין ופרנס בפפד\"מ, ועמד בראש הועדה שניסחה את תקנות הקהילה בזמן כהונת ר ישעיה הורביץ-נכד השל\"ה כרב בפפד\"א. ישב בדין-תפה עם ר יעקב פופרש-רבה של פפד\"מ, ור מיכאל שפייר והחרימו כתבים שבתאים מהשליח השבתאי משה מאיר."},{"i":55241,"n":"שפייר, משה מפפד\"מ","b":"דיין מחכמי פפד\"מ-תע."},{"i":55242,"n":"שפייר, שמואל מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":55243,"n":"שפילברג, מרדכי דוב","b":"מו\"צ בזשוריק"},{"i":55244,"n":"שפילברג, שלמה מבוהוש","k":"אדמור מבוהוש","b":"הסכים על \"בית ועד לחכמים\" - יאסי תרסט."},{"i":55245,"n":"שפילמן, יוסף יוזפא מארה\"ב","k":"בעל לקוטי יוסף","b":"רב בארה\"ב-תרצז"},{"i":55246,"n":"שפילמן, יעקב מאיר מבוקרשט","f":"אליהו מרופשיץ","k":"בעל נחלת יעקב","bt":"תקעג","bp":"רופשיץ","dt":"תרמח","b":"תלמיד ר נפתלי צבי מרופשיץ, ר שלמה זלמן פרנקל מויליפולי המזכירו בספרו \"עדות ביעקב\". חתן ר אהרן דוד בן הצדיק ר שלמה ארי המרישא. רב בקריובה(=קראיווה)-רומניה, בוקרשט-תרט (והיה מחלוקת בינו לרב השני ר לוי יצחק פרנקל), ואח\"כ נדד בערי רומניה, טורקיה, יון, צפון אפריקה, ורוסיה. חזר לבוקרשט-תרכה. חיבר גם \"טל אורות\", ועוד."},{"i":55247,"n":"שפילמן, מרדכי","f":"משה שמשון","b":"תלמיד המנח\"א ור נטע שלמה שליסל ור ישראל צבי רוטנברג. ניצל מהשואה ועבר לארה\"ב. עסק בפענוח כתבי ה\"צפנת פענח\". חתן ר אברהם יצחק הכהן מאונגוואר."},{"i":55248,"n":"שפילמן, משה שמשון מסקוליע","k":"בעל ציון לנפש צבי","b":"תלמיד ר צבי הירש מזידיטשוב. מקובל בסקוליע. חיבר \"ציון לנפש צבי\" ניו יורק תשלז."},{"i":55249,"n":"שפינדל, שלמה","b":"מראשי חסידות צורטקוב, חתם-תרצד על מכתב בקשת עזרה של ראשי החסידות עם ר נתן נטע לייטר, ר מרדכי שלמה שכטר מזלישטשיק, ר יוסף בנימין הורן."},{"i":55250,"n":"שפינוזה, ברוך מאמשטרדם","bt":"שצב","bp":"אמשטרדם","dt":"1677","b":"פילוסוף."},{"i":55251,"n":"שפיץ (שפיצר), יוחנן הלוי מטאב","f":"בנימין זאב מאויבן","k":"בעל בן זכאי","bt":"תקס","bp":"אויבן","dt":"תרל - טו תמוז","dp":"טאב","b":"רב בטאב-תקצז על מקום ר יוסף יצחק מינץ. נזכר בשו\"ת \"בית נאמן\" לר משה פרלס מבאניהאד."},{"i":55252,"n":"שפיץ, אברהם משפיץ","f":"משה","bt":"תטז","bp":"שפיץ","dt":"תקא - א אייר","dp":"וינה","b":"גביר, פרנס, סייע בהקמת ביהכ\"נ באייזנשטט, בפדיון שבויים באובין-תמד, שתדלן אצל המלכות. אחיו - הקדוש ר רפאל מוילנא."},{"i":55253,"n":"שפיץ, אברהם נפתלי הירש מאשכנז","f":"משה","k":"בעל ברכת נפתלי","dt":"תעב - טו אלול","dp":"ורמייזא","b":"רב בדרזניץ, רושיץ, ראב\"ד בניקלשבורג, רב בוורמייזא-תסד. חיבר גם \"מלא רצון\", \"שבע רצון\", ועוד."},{"i":55254,"n":"שפיץ, אהרן - מפרוסניץ","bt":"תקכט","dt":"תקעז - כא תשרי","b":"חתן ר יצחק חיות מאונסדורף. רב בפרוסניץ(=פרוסטיץ)-תקנט, טרנטשין-תקעא, האליטש. נכדו - ר יחזקאל הלוי בעל \"תורת יחזקאל\"."},{"i":55255,"n":"שפיץ, אהרן מניקלשבורג - ב","b":"דיין בניקלסבורג,רב בפרוסניץ-תק\"צ"},{"i":55256,"n":"שפיץ, אליעזר מאויבן","f":"שמשון שפיץ","dt":"א אדר","b":"רב באויבן ישן"},{"i":55257,"n":"שפיץ, אלעזר מטשאטה","b":"דרשן,רב בטשאטה-תק\"צ"},{"i":55258,"n":"שפיץ, בנימין זאב הלוי מאלשא","b":"רב באלשא-דאבאש. חתנו - ר יהודה ליב וייס מגירבא."},{"i":55259,"n":"שפיץ, בנימין זאב וולף","f":"יוחנן שפיץ","b":"רב באדאנד-תר\"מ"},{"i":55260,"n":"שפיץ, גבריאל מניקלשבורג","f":"חיים סינש","bt":"שמד","dt":"שפא","b":"רב המדינה בניקלסבורג"},{"i":55261,"n":"שפיץ, דוד מניו יורק","b":"חתן ר ר יקותיאל יהודה גרינוולד מיארע. מחכמי ניו יורק."},{"i":55262,"n":"שפיץ, זלמן מאיזנשטט","b":"ראב\"ד באייזנשטדט-ת\"ס"},{"i":55263,"n":"שפיץ, חיים משטמפן","f":"מרדכי","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן."},{"i":55264,"n":"שפיץ, חיים צבי מנאדי טארנא","b":"חתן ר שלום קליין מהאלמין. חתניו - ר בנציון פיליפ מסטמר, ר אברהם אליעזר ציטרון מהאידו-דאראג."},{"i":55265,"n":"שפיץ, יהודה מפרשבורג","f":"נתן נטע מגרוסורדין","k":"בעל מדרש יהודה-תרכו","bp":"גרוסורדין","b":"מחכמי פרשבורג. ?? לא באוצר ??"},{"i":55266,"n":"שפיץ, יום טוב מפרג","f":"יצחק מפרג","k":"בעל אלון בכות","dt":"תרכז - אחרי","b":"רב בבומסלא-תקף, מלמד תורה בפרג. חיבר \"אלון בכות\", \"זכרון אלעזר\" - הספד ותולדות זקנו ר אלעזר פלקלש,"},{"i":55267,"n":"שפיץ, יחיאל מיכל הלוי","f":"יצחק זעקל שפיץ","k":"בעל פרי העץ","b":"רב בהעדיעס-תק\"מ"},{"i":55268,"n":"שפיץ, יצחק הלוי מקעסטהאלי ופרג","f":"מיכל אהרן מאיזנשטט","dt":"תרט - יח טבת","b":"תלמיד החת\"ס. ולמד גם בשליינינג. חתן ר אלעזר פלקלש מפרג (ויש אומרים חתן ר ברוך שיק ראש מדינה במהרן). רב בקעסטהלי-תקצו."},{"i":55269,"n":"שפיץ, יצחק זעקל מבאניהאד","k":"בעל ברכת יצחק","dt":"תקכד-ח - ט אב","b":"רבה הראשון של בוניהאד(=בניהאד)-תקי, ובנו ר יחיאל מיכל מהוגיאס על מקומו אחריו, והו\"ל את ספר אביו \"באור יצחק\"."},{"i":55270,"n":"שפיץ, יקותיאל הלוי מאיזנשטט","f":"גבריאל שפיץ","b":"רב באייזנשטט-ת\"י"},{"i":55271,"n":"שפיץ, ירמיה מארה\"ב","f":"אפרים הי\"ד","bt":"תרנה","bp":"אונגואר","b":"תלמיד ישיבת מאדא, אויוואראש אצל בעל \"פני מבין\", סעמיהאלי. נסמך מאת: ר דוד יהודה זילברשטין מוייצען, ר ישראל יונגרייז מנדאודוואר, ר שמעון קרויס מאטש. רב בקאסל-תרפח, רקושהעד-ליד בודפשט, שארווד-תרצב, היגר לארה\"ב-תרצז וכיהן כרב בסקרנטון-תש, פרש מהרבנות-תשג."},{"i":55272,"n":"שפיץ, ישעיה מכפר טארנא","k":"בעל צוה ישועות יעקב","dt":"תש..","b":"תלמיד ר יואל צבי רוט בעל \"בית היוצר\", ור יהודה גרינוולד. נספה בשואה. חיבר \"צוה ישועות יעקב\" כנגד הרעיון הציוני - סטמר תרצו."},{"i":55273,"n":"שפיץ, לוי צבי מליטא","bt":"תרמז","bp":"קול-ליטא","dt":"תשא-ג - תמוז","b":"מחשובי רבני ליטא בדור השואה. תלמיד ישיבת טלז, רב בפלונגיאן-תרפה, וורנה על מקום ר יעקב אברמוביץ, רבה האחרון של טאווריג. נספה בשואה."},{"i":55274,"n":"שפיץ, ליב הירש מאויבן","b":"רב באויבן-תקצח. בנו - ר שלמה זלמן שפיצר מוינה-חתן החת\"ס."},{"i":55275,"n":"שפיץ, ליב מנורבא","b":"חתן ר אליעזר שפיץ מאויבן. רב בנורבא-תק\"צ"},{"i":55276,"n":"שפיץ, מאיר - מהר\"ם שפיץ","k":"בעל כתית למאור","b":"חתן ר משה אריה פילבוגן. רב דגליל באראניא-הונגריה-תקל. חיבר \"כתית ושמן למאור\"."},{"i":55277,"n":"שפיץ, מאיר מביסטריץ","f":"טוביה","bt":"תרמט","bp":"פהר-ג'ארמאט","dt":"תשד - יז סיון","dp":"אושוויץ","b":"תלמיד \"ערוגת הבשם\" בחוסט, ר משה הרש פוקס בגרוסורדין. חתן ר שלמה זלמן אולמן מביסטריץ. רב בספרמזאו(=שפירמאזה)-תרעב אך התגורר בביסטריץ וניהל שם את הישיבה-תרצא לצד חותנו ורב על מקומו אחריו, והצליח ללכד בקהילה חסידים ומתנגדים ביחד. בקי במדעים ובחישובי תקופות. נספה בשואה. רוב כתביו אבדו בשואה. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד."},{"i":55278,"n":"שפיץ, מיכל מבייאה","b":"רב בבייאה(=ביאה)-תקך ור פישל על מקומו אחריו."},{"i":55279,"n":"שפיץ, משה מטשענגר","f":"אליעזר שפיץ","bt":"תקכה","dt":"תקפב - כה תמוז","b":"חתן ר משה אריה אסטריכר מקארולי. רב בטשענגר-תקנו."},{"i":55280,"n":"שפיץ, נתן נטע מאלמאשד","f":"יצחק","dt":"תרלז - ח טבת","b":"רב באלמאשד, עבר לגרוסורדין-תרל ולא כיהן כרב."},{"i":55281,"n":"שפיץ, עקיבא מטאב","f":"יוחנן הלוי מטאב","bt":"תקץ","dt":"תרסז - כג שבט","b":"תלמיד הכת\"ס, חתן יתומה שגדלה בבית הגביר ר זלמן קדלבורג מפרשבורג, וישב אצלו. מחכמי טאב. הכין לדפוס ספר אביו \"בן זכאי\"."},{"i":55282,"n":"שפיץ, צבי הירש","k":"בעל דברי חכמים וחידו","b":"חיבר \"דברי חכמים וחידותם\" על אגדות חז\"ל."},{"i":55283,"n":"שפיץ, רפאל מוילנא הקדוש","f":"משה","b":"חתן ר אליקום געץ מהילדסהיים בעל אבן השוהם. גביר מחכמי וילנא, נזכר בפנקס הקהלה. חתנו - ר יוסף בן אברהם מגלוגא בעל זרע אברהם. נהרג עק\"ה."},{"i":55284,"n":"שפיץ, שמואל","f":"יצחק שפיץ","b":"רב בסענטעש-תר\"ל"},{"i":55285,"n":"שפיץ, שמעון צבי","f":"משה שפיץ","b":"רב באויפאלו-ת\"ר"},{"i":55286,"n":"שפיץ, שמשון הלוי","f":"יקותיאל שפיץ","b":"רב באייזנשטט-ת\"נ"},{"i":55287,"n":"שפיצר, [חייא] דוד הלוי מפרשבור","k":"בעל הנברשת","b":"מחכמי פרשבורג, וינה. עלה לירושלים-תרלג. וחיבר ספר \"הנברשת\" אודות זמני הנץ החמה."},{"i":55288,"n":"שפיצר, אברהם חיים מניו יורק","k":"בעל חיי אברהם","b":"רב ק\"ק וינה בניו יורק-תשלז."},{"i":55289,"n":"שפיצר, אברהם שמואל בנימין","f":"משה","bt":"תרלב","bp":"הונגריה","dt":"תרצד - טו סיון","b":"תלמיד השב\"ס, ור יוסף ישראל דייטש מבאלאש-ירמוט, ור שלמה זלמן ברייער מפפדמ. חתן ר משה מרדכי פשרהופר מסערעד, ובזיוו\"ש חתן ר נתן רכניצר. רב בהאלאש(=קיש-קינהאלאש)-תרנח, מישקולץ-תרסח, המבורג-תרעא."},{"i":55290,"n":"שפיצר, איצק משטמפן","b":"חתם-תרב עם ר משה מרדכי בנט. חתם-תריב על מינוי ר אליעזר וינטר."},{"i":55291,"n":"שפיצר, אשר לעמל מקירכדורף","f":"יחיאל הלוי מוערבא","k":"בעל כתר תורה","bt":"תרלב","bp":"וערבא - הונגריה","dt":"תשה - יט תשרי","dp":"אושוויץ","b":"תלמיד השב\"ס, ר יעקב קופל רייך מוערבא, ור ישעיה זילברשטין מוויצען ור שמואל רוזנברג מאונסדורף. מלמד מבגנדורף. מחכמי גאלאנטא-תרנד, רב בפאפא-תרנה, קירכדורף-תרסט. בשליחות \"אגודת ישראל\" בארה\"ב-תרפא עם בעל \"כלי חמדה\" לפקח על מצב הדת ולרוממה. התוכח עם המתנגדים לאגודת ישראל, אולם לבסוף פרש בעצמו מאגו\"י. נספה בשואה. תשובות ממנו ב\"טהרת יו\"ט\", וב\"מקדשי השם\". נזכר ב\"דעת סופר\". פרסם מאמרים ב\"המעין\" - פרשבורג תרצד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":55292,"n":"שפיצר, בנימין זאב וולף מפעצעל","b":"רב בפעצעל-תקס\"א"},{"i":55293,"n":"שפיצר, בנימין שלמה זלמן מוינה","f":"יעקב דוד מאויבן","k":"בעל שמלת בנימין","bt":"תקפא-ו","bp":"אויבן","dt":"תרנד - כו כסלו","dp":"פרשבורג","b":"יש אומרים כי אביו היה ליב הירש שפיץ מאויבן. תלמיד הכת\"ס, ומהרם שיק, ור מאיר א\"ש מאונגוואר. חתן החת\"ס - נשא את אלמנת ר אליהו קורניצר - בת החת\"ס, ובזיוו\"ש חתן ר משה טוביה לעהמן - נכדת החת\"ס. מחכמי פרשבורג. רב בוינה-תריב - בקהילת קהל חרדים יוצאי הונגריה, ובהמשך רב\"ד תחת ר אלעזר הלוי הורביץ בוינה. חיבר \"שמלת בנימין\". מתורתו ב\"וילקט יוסף\" - מונקטש תרס. חתניו - ר שמען סופר בן הכת\"ס מערלוי, ר יוסף דב כהן. גיסו של ר פייש פישמן מפרשבורג. הספיד את הכת\"ס."},{"i":55294,"n":"שפיצר, דב בר מקלינורדין","f":"יואל מדעש","k":"בעל תולדות קול אריה","bt":"תרע","bp":"דעש","dt":"תשמא - ו אייר","b":"תלמיד ישיבת דעש, בישיבת בעל \"קרן לדוד\" בסטמר, ואצל ר חיים אלעזר שפירא במונקטש. חתן ר חיים צבי ארנרייך ממאד. רב באגארד-תרצג והתגורר בקלינורדין. ניצל מהשואה, ואחריה רב בדעש. בזיוו\"ש חתן האדמור מברודי בקלוזינבורג. היגר לניו יורק. הו\"ל ספר רבו יעקב אלימלך \"זכרון יעקב\". עלה לארץ-תשל והתישב בבני ברק."},{"i":55295,"n":"שפיצר, משה מאיר ממונטריאול","b":"רב במונטריאול, ניו יורק. חתן ר הלל אונסדורפר מלאשאנץ. פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה. עורך \"הפלפול\" - שאפראן תרצח."},{"i":55296,"n":"שפיצר, משה ממונקטש","bt":"תרכא","dt":"תרצג - ה טבת","b":"דומ\"צ במונקאטש-תרנה-ח. נסמך מבעל \"קול אריה\"."},{"i":55297,"n":"שפיצר, נחום מרדכי מנ\"י","b":"רב מחסידי סטמר, ניצל מהשואה ואחריה היגר לארה\"ב. נתן סידור מיוחד לאדמור מסטמר שהשתמש בו והכיר לו טובה."},{"i":55298,"n":"שפיצר, נתנאל מאיזנשטט","b":"דיין באיזנשטט. חתן ר עזריאל אקשטין מאנטורפן."},{"i":55299,"n":"שפיצר, פייש מיארמי","b":"אב\"ד יארמי. נזכר אצל ברוין - מעשה שסיפר על ר אשר יונגרייז בעל מנחת אשר."},{"i":55300,"n":"שפיצר, קלמן משימאנדא","bp":"כפר וורביי","b":"רב בשימאנדא(=שימאנדי)-תרכח."},{"i":55301,"n":"שפיצר, שלמה מטיסא-בוגדאן","dt":"תשז","b":"רב בטיסאבוגדאן"},{"i":55302,"n":"שפיצר, שמואל משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":55303,"n":"שפיצר, שמעון מוינה","b":"מאמר ממנו ב\"תל תלפיות\" - וייצען תרנב-תרעד."},{"i":55304,"n":"שפיר, ישראל אשר מתל אביב","b":"חסיד גור בתל אביב, חתם-תש בערך על הכתרת ר שמואל אליהו טאוב כרב שכונה בתל אביב. מיסד התחנה המרכזית בתל אביב."},{"i":55305,"n":"שפיר, משה","b":"שליח ארץ ישראל. נזכר ב\"תהלה לדוד\" שם מופיע שיר לכבודו מר דוד ן חסין."},{"i":55306,"n":"שפיר, משה מאזמיר","b":"רב באזמיר. תלמיד ר חיים פלאג'י. חיבר הכהות ל\"נוה צדק\" לר סעדיה מירקאדו."},{"i":55307,"n":"שפיר, צבי הירש","bp":"סויסלאץ","dt":"תרי טז אדר","b":"עזב את אשתו וילדיו בביאליסטוק ועבר ללמוד בפרישות בוילנא. נסמך להוראה ע\"י בעל \"פתחי תשובה\". סירב לרבנות. מחכמי וילנא. הניח חבורים בכת\"י ואבדו."},{"i":55308,"n":"שפירא אברהם דב בר","bt":"1870","dt":"ה'תשג 1943","bk":[["דבר אברהם",""],["פארטראג איבער טהרת־המשפחה",""]]},{"i":55309,"n":"שפירא חזקיהו משה שמואל בן אריה","bt":"1917","dt":"ה'תשסו 2006","bk":[["קונטרס הביאורים",""]]},{"i":55310,"n":"שפירא פינחס בן אברהם אבא מקורץ","bt":"1726","dt":"ה'תקנ 1790","bk":[["בית פנחס",""],["דברים נחמדים",""],["חכם הרזים",""],["ליקוטי שושנים",""],["לקוטים מהרב ר' פנחס מקאריץ",""],["מדרש פנחס",""],["נופת צופים",""],["תוספתא למדרש פנחס",""],["תקון המדות",""]]},{"i":55311,"n":"שפירא צבי הירש בן שלמה","bt":"1850","dt":"ה'תרעג 1913","bk":[["דרכי אמונה",""],["דרכי תשובה",""],["צבי תפארת",""]]},{"i":55312,"n":"שפירא, אבא אריה ליב מיאזנה","f":"שמואל משה מבוברויסק","bt":"תרכב","bp":"אניקשט","dt":"תרעה","b":"רב ביאזנא-תרמו (בהמלצת ר יצחק אלחנן מקובנא), שארשוב-תרמח, ויטבסק-תרסח - קהלת האשכנזים. דודו-אחי אביו - ר רפאל שפירא מוולוזין. חתנו - ר ברוך רבינוביץ מזורויץ. חיבר חדושים על הש\"ס ושו\"ת ודרושים - בכת\"י."},{"i":55313,"n":"שפירא, אבא קונסטנטין","k":"בעל שבט לגו כסילים","bt":"1840","bp":"גרודנא","dt":"1900","dp":"פטרבורג","b":"למד בוינה, חזר לרוסיה והתישב בפטרבורג, והתנצר. חיבר שירים \"מחזיונות בת עמי\", חיבר גם \"לפני הפרגוד\" להגנת יל\"ג מפני התקפת מרדכי בן הלל הכהן. חזר ליהדות התקרב לציונית והתכונן לעלות לארץ - אך נפטר לפני שהספיק. הוריש את ספרייתו העשירה ל\"מדרש אברבנאל\" בירושלים."},{"i":55314,"n":"שפירא, אבי עזרי זליג אלעזר מק","f":"יעקב יצחק שפירא","k":"אדמור מקוזניץ","bt":"תר","dt":"תרסו - ז אייר","b":"מצאצאי המגיד מקוזניץ. חתן ר אלעזר מבעלז. אדמור בקוזניץ. נודע בסגולותיו וקמיעותיו. נקבר ליד המגיד מקוזניץ. בנו ר יוסף דיין בקוזניץ."},{"i":55315,"n":"שפירא, אבי עזרי זליג מגרעניץ","f":"משה יצחק","k":"אדמור מגרניץ","dt":"תקצה-ך","b":"מצאצאי ר נתן שפירא בעל \"מגלה עמוקות\". תלמיד וחתן ר ישראל המגיד מקוזניץ. אדמו\"ר בגניווישוב, גרייניץ, מגלניצא"},{"i":55316,"n":"שפירא, אבי עזרי זליג מדרוהוביט","f":"יצחק מרדכי מגוואדזיץ","k":"אדמור מדרוהוביטש","dt":"תשד - יט תשרי","b":"מצאצאי המגיד מקוזניץ. חתן דודו ר חיים מאיר יחיאל מדרוהוביטש. בנו ר שלמה ונכדו ר אביעזר רב ביהמ\"ד דרוהוביטש בירושלים."},{"i":55317,"n":"שפירא, אבי עזרי זליג ממוגלניצא","f":"אברהם יהושע השל","k":"אדמור ממוגלניצא","dt":"תרעו - כח אב","dp":"וארשא","b":"מצאצאי המגיד מקוזניץ. חתן ר יצחק ממנוסטרישץ (ברדיטשוב). רב ואדמור במוגלניצא על מקום אביו. ברח לוארשא-במלחה\"ע ה-I."},{"i":55318,"n":"שפירא, אביגדור מטשנסטחוב","f":"שלום מפשיטיק","k":"אדמור מצנסטחוב","bt":"תרם","dt":"תרפז-ח - יח אדר","dp":"צנסטחוב - ניו יורק","b":"מצאצאי המגיד מקוזניץ, נכד ר דוד הלברשטם מקשנוב, חתן ר קלונימוס בער מוויאדמה, חתנו האדמור ר יואל טיטלבוים מסטמר בעל \"ויואל משה\". בשנת תשלא הועבר ארונו לאמריקה לבית העלמין של סטמר (זהו המקרה הראשון שהועבר קבר של צדיק לאמריקה)."},{"i":55319,"n":"שפירא, אביעזר זליג מגווזדיץ","f":"יצחק מרדכי מגזוודיץ","bt":"תרנה","dt":"תשד","dp":"ירושלים","b":"חתן דודו ר חיים מאיר יחיאל מדרוהוביטש, עלה לארץ."},{"i":55320,"n":"שפירא, אביעזר זליג מדרוהוביטש","f":"חיים מאיר יחיאל","bt":"תרמח","dt":"תשכה","b":"חתן דודו ר משה יהודה ליב פרידמן מפשקן. סירב לאדמורות"},{"i":55321,"n":"שפירא, אביעזרי זליג מסטרי","f":"חיים מאיר יחיאל ממוג","k":"אדמור מסטרי","bt":"תקצו","dt":"תרמה - יט אב","b":"מצאצאי המגיד מקוזניץ. בן השרף ממוגילניצה. חתן האדמור ר אברהם יעקב פרידמן מסדיגורא ועבר אליו. אדמור בסטרי ולאחר פטירתו המשיכה אלמנתו הדסה פייגלא לקבל פתקאות מאדמורי רוזין, ועלתה לירושלים-תרפב עם בנה, נפטרה-תרצו בגיל 97 וקבלה חסידים ונתנה ברכות לכלות."},{"i":55322,"n":"שפירא, אברהם אבא","f":"פנחס משקלוב","b":"בנו של ר פנחס המגיד משקלוב. תלמיד הבעשט. אביו של ר פנחס מקוריץ. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":55323,"n":"שפירא, אברהם אביש אריה מהומנא","f":"יעקב מהומנא","bt":"תקן","dt":"תרלג - כב תשרי","b":"רב בהומנא על מקום אביו. הסכים על \"עקדת יצחק\"-תרח."},{"i":55324,"n":"שפירא, אברהם אליהו מסוויר","dt":"תקעב-ג - כ שבט","dp":"וילנא","b":"חתן ר שמעון מוילנא. רב בסוויר, מו\"צ בוילנא. בנו - ר אליעזר רבינוביץ שפירא מוילנא."},{"i":55325,"n":"שפירא, אברהם אלימלך מגרודזיסק","f":"ישראל מגרודזיסק","k":"אדמור מגרודזיסק בי-ם","bt":"תרנו","dt":"תשכז - כג כסלו","b":"מצאצאי המגיד מקוזניץ. חתן ר ירחמיאל משה מקוזניץ - ואשתו היא הסופרת מלכה שפירא. עלה לארץ-תרפח והתפרנס ממלאכה. לאחר השואה כיהן כאדמור גרודזיסק בירושלים. חיבר \"שיחות קודש\" ונדפס עם ספר אביו \"אמונת ישראל\". מתלמידיו ר אשר פריינד."},{"i":55326,"n":"שפירא, אברהם דב בעל דבר אברהם","f":"ראה: כהנא-שפירא"},{"i":55327,"n":"שפירא, אברהם הכהן מטריטש","b":"רב בטריטש-תק ור לוי פולק על מקומו אחריו. בנו - ר יוסף הו\"ל את ספר החנוך - ברין תקנח."},{"i":55328,"n":"שפירא, אברהם חיים הלוי מברזן","b":"נכד בעל \"ברית אברם\". מחכמי ברזן, וחברו של ר יצחק שמלקיס. גיסו של ר שמואל וילנר מהליטש. בנו ר שמואל רב בדוברומיל וזלוטשוב."},{"i":55329,"n":"שפירא, אברהם חיים מאברטין","f":"שמואל הלוי מדוברומיל","b":"רב באברטין. חתנו - ר ראובן דוד באבד - רבה של פודוולוטשיסק. נספה בשואה."},{"i":55330,"n":"שפירא, אברהם חיים מסמרגן","f":"ליבלי שפירא","dt":"תרמד - ד אייר","b":"רב בסמרגן"},{"i":55331,"n":"שפירא, אברהם יהושע השל ממוגלני","f":"חיים מאיר יחיאל ממוג","k":"אדמור ממוגלניצא","dt":"תרלח - כו סיון","b":"מצאצאי המגיד מקוזניץ. חתן ר ישראל יצחק מראדושיץ. אדמור במוגלניצא על מקום אביו. נפטר צעיר. בנו - ר דוד אלעזר סופר-אורנשטין בעל \"יסוד הדעת\", ו\"מפענח נעלמים\"."},{"i":55332,"n":"שפירא, אברהם יעקב מגווזדיץ","f":"יצחק מרדכי מגווזדיץ","k":"אדמור מגווזדיץ","dt":"תשא-ב - כט אלול","dp":"סטולין","b":"מצאצאי המגיד מקוזניץ. נכד ר יעקב קופל בעל \"שערי ג\"ע\". רב בקרסטשוב-פלך קיוב-תרנה, אדמור מגווזדיץ על מקום אביו. חתן ר ישראל פרלוב מסטולין. נספה בשואה."},{"i":55333,"n":"שפירא, אברהם יעקב מדרוהוביטש","f":"חיים מאיר יחיאל","k":"האדמור הצייר-נתיבות","bt":"תרמד","bp":"סדיגורא","dt":"תשכב -כב-ד אד\"ב","b":"מצאצאי המגיד מקוזניץ. עבר עם אביו ואחר כך לדרוהוביטש שם נעשה אביו אדמור. עלה לארץ עם אביו ובשנת תרפד אדמור על מקום אביו בירושלים. היה בעל כשרון לציור ונקרא משום כך האדמור הצייר. חתן ר נתן דוד מפרצוב (פשיסחא), ובזיוו\"ש חתן ר ישראל פרידמן מבויאן-לייפציג. היה צייר בעל שם. חיבר \"נתיבות שלום\" ירושלים תרפח, \"ציורי האדמור א.י. שפירא\" ירושלים תשכו."},{"i":55334,"n":"שפירא, אברהם מאברטין","b":"רב באברטין-תר\"צ"},{"i":55335,"n":"שפירא, אברהם מארה\"ב","bt":"1884","bp":"ראקישוק","dt":"1949","dp":"הוליבוד","b":"היגר לארה\"ב-1907. ממיסדי האוני' ע\"ש ברנדייס. פעיל בחיי הציבור היהודי."},{"i":55336,"n":"שפירא, אברהם מארה\"ב","b":"רב ביוטיקא-ארה\"ב. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":55337,"n":"שפירא, אברהם מארה\"ב","f":"זלמן מרדכי","k":"בעל אוצר לדרשנים","b":"תלמיד ר מאיר שמחה הכהן מדוינסק ונסמך ממנו, היגר לארה\"ב-תרסג, תלמיד ישיבת רבי יצחק אלחנן. רב בקנטון-אוהיו. אחיהם של ר דניאל ור ברוך."},{"i":55338,"n":"שפירא, אברהם מבנילוב","f":"ישכר דב ברצי מבנילוב","k":"בעל רשפי אש","dt":"תש..","b":"\"ברב בבנילוב-בוקובינה-תרנג על מקום אביו, לאחר מלחה\"ע ה-I נדד במקומות שונים ובהם גאלנטה. נספה בשואה. חיבר גם \"ברכת אברהם\", \"חסד לאברהם\", \"דברי אברהם\", \"באר אברהם\"."},{"i":55339,"n":"שפירא, אברהם מוארנוב","f":"יעקב מהומנא","bt":"תקם","dt":"תרכה - כח טבת","b":"רב בוורנוב(=וארנוב)-תקפה. הסכים על \"עקידת יצחק\" - פרשבורג תרח."},{"i":55340,"n":"שפירא, אברהם מוילנא","dt":"תשג","b":"רב בווילנה-דרוהביטש"},{"i":55341,"n":"שפירא, אברהם מטלוסט","f":"יעקב שמשון משאץ","k":"אדמור מטלוסט","bt":"תרמח","dt":"תשלב - כג אב","b":"מצאצאי ר פנחס מקוריץ. אחיו של מהר\"ם שפירא מלובלין. תלמיד ר שלום מוקשוביץ. ניצל מהשואה ועבר לארה\"ב ושם כיהן כאדמור מטלוסט בניו יורק. חתן רנ\"ה הורניק מטלוסט שהיה מגזע הבעשט. בנו ר אהרן לבוול מאיסטריק היה מנהלה האחרון של ישיבת חכמי לובלין. הו\"ל \"אור המאיר\" - נ\"י תשח - קובץ תורני המוקדש לאוהביו ותלמידיו של ר מאיר שפירא מלובלין."},{"i":55342,"n":"שפירא, אברהם מטלז","f":"אברהם חיים","bt":"תרסד","b":"מחסידי צורטקוב בקראקא, עלה לירושלים-תרפו דרך וינה. חתן ר מרדכי דוד ויינשטוק. היה נציג אדמורי צורטקוב בירושלים."},{"i":55343,"n":"שפירא, אברהם מטלז","f":"אליהו","k":"אברהם שוועקשנער","b":"אב\"ד טלז-שנות ה-תק' על מקום ר יהודה ליב זיו, ובנו ר לייב על מקומו אחריו. מצאצאי בעל \"מגלה עמוקות\". בניו - ר צמח מקידאן, ר משה מקרוז, ר שמעון מערקיל מבירז, ר שמואל מפוניבז וטלז. אחיו - ר דוד מראסיין."},{"i":55344,"n":"שפירא, אברהם מלמברג","b":"דיין בלמברג אצל ר בנימין אלנברג."},{"i":55345,"n":"שפירא, אברהם מנחם מנדל","f":"משה ישעיה","bt":"תריד","b":"רב בשרקושצינא(=שארקישצינא)-מחוז דיסנא, חלאפניטש-פלך מינסק."},{"i":55346,"n":"שפירא, אברהם מניו ג'ורגיה-ארהב","bt":"תרמו","dt":"תרצד - כ חשון","b":"רב בניו-גורג'י(ארה\"ב)-תרצ\"א"},{"i":55347,"n":"שפירא, אברהם מניו יורק","f":"מרדכי בן איזל חריף","b":"נכד ר איזל חריף בעל \"עמק יהושע\". היגר לארה\"ב-תרסב וכיהן כרב בניו יורק. הו\"ל ספר זקנו \"עמק יהושע\" - ירושלים תרפה. בנו - יצחק מאיר, בתו - פולין סטביסקי."},{"i":55348,"n":"שפירא, אברהם מפודקמין","b":"מחכמי פודקמין - תשובה אליו ב\"בית ישראל\"."},{"i":55349,"n":"שפירא, אברהם משידלובה","bt":"תקעח","dt":"תרסג - טו שבט","b":"רב בשידלובה-תרכ\"ג"},{"i":55350,"n":"שפירא, אברהם נתן מקראקא","f":"שלמה מסטנוב","dp":"קראקא","b":"נכד ר נתן בעל \"מגלה עמוקות\". מחכמי קראקא."},{"i":55351,"n":"שפירא, אברהם שוועקשנער מטלז","f":"אליהו","b":"אב\"ד טלז-תקן בערך."},{"i":55352,"n":"שפירא, אברהם שלמה זלמן מירוש","f":"מנחם מנדל","dt":"תקפט - בערך","dp":"ירושלים","b":"נכדו של בעל \"מגלה עמוקות\" ובעל \"תוספות יום טוב\", למד בישיבת וולוזין אצל ר חיים מוולוזין. היה חותנו של ר אריה ליב בן ירחמיאל נאמן. עלה לירושלים. בשליחות בקושטא-תקף עם ר ברוך בקובנא בענין חוב הקהלה האשכנזית. היה באיטליה והביא את מכתב רבני ירושלים."},{"i":55353,"n":"שפירא, אהרן יהושע מביאליסטוק","b":"חתן ר הלל בישקא מקיידן. גביר בביאליסטוק ומתומכי 'חובבי ציון'. מכתב כנגדו מר יעקב ליפשיץ מקובנא המכנהו בשם 'עזרא הכוזב' מביאליסטוק."},{"i":55354,"n":"שפירא, אהרן יוסף מאונסדורף","b":"רב באונסדורף-תק\"נ"},{"i":55355,"n":"שפירא, אהרן יחיאל מיכל מפרג","f":"בנימין וולף","k":"בעל מים קדושים","dt":"תקד - ט תשרי","dp":"פרג","b":"רב בביה\"כ \"נייא שול\" בפרג."},{"i":55356,"n":"שפירא, אהרן ישעיה מארה\"ב","b":"פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":55357,"n":"שפירא, אהרן מפרשבורג","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":55358,"n":"שפירא, אהרן משה מירושלים","b":"מראשי כולל קרלין בירושלים, חתם-תרמב עם ר אשר קאלמאנוב."},{"i":55359,"n":"שפירא, אהרן שמעון מפרג","f":"בנימין וולף מפרג","k":"בעל מראה יחזקאל","bt":"שס","bp":"פרג","dt":"תמ - כט כסלו","dp":"פרג","b":"מגדולי חכמי דורו, רב בפפד\"מ, לבוב, לובלין-תטז, קראקא, וינה, פרג-ת' ומדינת בוהמיה כ-40 שנה ובנו ר בנימין זאב על מקומו אחריו. לאחר שנרדף רבות קיבל אגרת בטוחות (פרייא בריעף) מהקיסר ליאופולד. בזמן גזירות תט תיקן סליחות מיוחדות בפרג ונדפסו. בנו - ר בנימין וולף - רב ראשי בבוהמיה."},{"i":55360,"n":"שפירא, אורי מדרוהוביטש","b":"מחכמי דרוהוביטש. חתן ר אלעזר רוקח."},{"i":55361,"n":"שפירא, אורי מהובישוב","dt":"תשג","b":"רב בהובישוב"},{"i":55362,"n":"שפירא, אורי מטבריה","b":"עלה בשיירת החסידים-תקכד. בנו ר משה יצחק עלה עמו. ר מנחם מנדל מויטבסק העיד עליו כי \"מתאווה לעבוד את ה' באמת\"."},{"i":55363,"n":"שפירא, אליהו אלתר מנפולומיץ","b":"מחכמי נפולומיץ-תרפז."},{"i":55364,"n":"שפירא, אליהו מוישנביץ","f":"פנחס מקוריץ","b":"חתן ר לייב מוישנוביץ. נפטר צעיר."},{"i":55365,"n":"שפירא, אליהו מטשרניקוב","f":"יוסף יאסקי מלעסלא","k":"בעל לקט אליהו","bt":"תקסה","bp":"צילץ","dt":"תרטו","b":"רב בטשרניקוב(=טשארלניקאוי)-ליד פוזנא. עמד בקשרי שו\"ת עם ר עקיבא איגר."},{"i":55366,"n":"שפירא, אליהו מממל","b":"רב בממל"},{"i":55367,"n":"שפירא, אליהו מקלטשין","b":"רב בקאלטשין-תק\"כ,ברח לאיטליה,הולנד וטוניס"},{"i":55368,"n":"שפירא, אליהו מקעלין","f":"בנימין וולף בן אהרן","k":"בעל אליהו רבא","bt":"תכ","bp":"פרג","dt":"תעב - ח ניסן","b":"נכד ותלמיד ר אהרן שמעון שפירא מפרג. רב בקעלין, טיקטין, דרשן וראש ישיבה בפרג. חיבר גם \"אליהו זוטא\", ועוד - רבים מכתביו נשרפו בשריפה הגדולה בפרג-תקיד. נפטר בחיי אביו.","bk":[["אליה זוטא",""],["אליה רבה",""],["דברי אליה - תהילים (כת\"י?)",""],["אליה רבה - אליה זוטא",""]],"e":"ת\"כ-תע\"ב"},{"i":55369,"n":"שפירא, אליהו פנחס","b":"פרסם מאמרים ב\"חידושי תורה\" - לודז תרצו - קובץ חבורת בני ישיבת מיר בלודז."},{"i":55370,"n":"שפירא, אלימלך בן ציון","f":"קלונימוס קלמיש מפיסצ","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. חתן ר שלמה חיים מבולחוב (נסכיז). נספה בשואה."},{"i":55371,"n":"שפירא, אלימלך מבנדין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":55372,"n":"שפירא, אלימלך מגלובנה","dt":"תשג","b":"רב בגלובנה"},{"i":55373,"n":"שפירא, אלימלך מגרודזיסק","f":"חיים מאיר יחיאל ממוג","k":"אדמור מגרודזיסק","bt":"תקפד","dt":"תרנב - א ניסן","b":"מצאצאי המגיד מקוזניץ. רב בגרודזיסק. מגדולי האדמורים בדורו. חתן ר ירחמיאל מפשיחסא, ובזיוו\"ש חתן ר חיים שמואל מחנטשין (לובלין). חיבר \"אמרי אלימלך\", \"דברי אלימלך\". מבניו ר ישעיה - האדמור החלוץ, ר קלונימוס קלמן האדמו\"ר מפיאסצנא בעל \"חובת התלמידים\"."},{"i":55374,"n":"שפירא, אלימלך מגרודזיסק","f":"ישעיה בן אלימלך","k":"אדמור מגרודזיסק","b":"מצאצאי המגיד מקוזניץ. נכד ר אלימלך מגרודזיסק. ניצל מהשואה ואחריה אדמור מפיסצנא על מקום דודו ר קלונימוס שנספה בשואה, ובהמשך אדמור מגרודזיסק."},{"i":55375,"n":"שפירא, אלימלך מלונדון","f":"יעקב יוסף מלונדון","bp":"טרנוב","dt":"תשמב","dp":"ירושלים","b":"נסמך בביה\"ד בקראקא. רב בלונדון. היה המלמד של רופא חצר המלכות בלונדון - וניצל את קשריו בזמן השואה להצלת יהודים. חתן ר יעקב אריה טברסקי האדמור מטריסק בלונדון. עלה לירושלים-תשל."},{"i":55376,"n":"שפירא, אלימלך מקוזניץ וארשא","f":"יוסף מנחם מפרגה קוז","k":"אדמור מקוזניץ","bt":"תרכד","dt":"תשב","dp":"וארשא","b":"מצאצאי המגיד מקוזניץ. חתן דודו ר שלום מפשיטיק. אדמור בקוזניץ, ראדום, וארשא. נספה בשואה. בנו ר יעקב יצחק מאוטואצק."},{"i":55377,"n":"שפירא, אלימלך מקוזניץ וארשא","f":"אבי עזרי זליג אלעזר","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. נספה בשואה. בניו ר שלום מלודז בעל \"אוהב שלום\", ור יעקב יצחק שנפטר בחיי אביו."},{"i":55378,"n":"שפירא, אלימלך מקראשניק","b":"אב\"ד קראשניק. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":55379,"n":"שפירא, אליעזר","f":"נתן נטע שפירא"},{"i":55380,"n":"שפירא, אליעזר - אי\"ש","f":"יצחק","k":"בעל הפודה ומציל","bt":"1836","bp":"סארהיי","b":"מו\"ס ומו\"ל. פרסם ב\"היום אצל י.ל. קנטור. תרגם \"הגאוה או הנסיכה\", ועוד."},{"i":55381,"n":"שפירא, אליעזר יהושע מניישטט","f":"יעקב","bt":"תקצח או תרא","dt":"תרפח - א טבת","b":"מצאצאי ר אליעזר ניישטאדטער. תלמיד ר יואל יצחק קצנלנבוגן מניישטט רב בניישטט-טאווריג(=סוגינט, סוגינד)-פלך קובנא על מקום רבו, וחתנו ר יעקב משה לסין(=ליאסין) על מקומו אחריו. הניח חיבור בהלכה ודרוש - בכת\"י."},{"i":55382,"n":"שפירא, אליעזר ליפא מוילשנה","f":"אריה יהודה","bt":"תריט","b":"רב בווילשנא-פלך קיוב-תרנב."},{"i":55383,"n":"שפירא, אליעזר מבנדין","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":55384,"n":"שפירא, אליעזר מלויביטש","f":"אריה ליב -נחלת אריאל","b":"אב\"ד לויביטש(=לוביץ). חתנו - ר מנחם זונדל, ונכדו - ר אריה ליב שפירא מקובנא (שגדל אצלו אחר פטירת אביו)."},{"i":55385,"n":"שפירא, אליעזר מקיויאשד","f":"מרדכי מברשט","k":"בעל שאר ישוב","bt":"תרמח-ט","dt":"תשלג - כד אייר","dp":"ניו יורק","b":"רב בקיויאשד-סלובקיה. ניצל מהשואה (בעזרת ר יואל ב\"ר אברהם קליין ור משה מרדכי גליק ב\"ר אלכסנדר זישא הכהן), עבר לארה\"ב וכיהן כרב בניו יורק ואף הקים שם ישיבה. חתן ר חיים זיידא הגר מרדיויץ, בזיוו\"ש חתן ר יוסף איכנשטין מטרנופול. גיסו ר צבי אלימלך רוקח מבערטש. חיבר \"שאר ישוב\" ניו יורק תשמה."},{"i":55386,"n":"שפירא, אליעזר מריבטיטש","f":"יהושע מריבטיטש","k":"אדמור מריבטיטש","bt":"תרמה","dt":"תשא","dp":"דוברומיל","b":"רב ואדמור-תרצב בריבטיטש על מקום אביו. חתן ר אפרים הורביץ מרוזוודוב. נספה בשואה."},{"i":55387,"n":"שפירא, אליקים שלמה מהורדנא","f":"חיים","bp":"וילנא","dt":"תרסח","dp":"ירושלים","b":"רב באיישישוק, נוברדוק, איוואניץ, הורדנא, עלה לירושלים-תרסה. קרוב משפחתם של ר אריה ליב שפירא מקובנא ושל ר אליהו חיים מייזל מלודז. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":55388,"n":"שפירא, אלעזר (אליעזר) מהורדנא","f":"אשר","dt":"תריב-ד -יב ניסן","dp":"הורדנא","b":"דיין בהורדנא"},{"i":55389,"n":"שפירא, אלעזר מאוזירן ולנצהוט","f":"שמחה מלנצהוט","k":"אדמור מאוזיראן-לנצהו","bt":"תרכה","dt":"תרצח - יט תמוז","b":"חתן ר בנימין זאב וולף גוטסמן מאוזירן ועבר לשם - כיהן כרב-תרסו ואדמור בסגנון בלז-רופשיץ (למרות שרוב הקהל היו חסידי רוזין). חסיד צורטקוב. חתן ר יצחק ויליצקר אשכנזי. רב בלנצהוט-תרעג על מקום אביו (יחד עם אחיו - ר צבי אלימלך והיו במחלוקת על ירושת אביהם), במלחה\"ע ה-I ברח לוינה וחזר ללנצהוט וחתנו ר דוד פיהרר על מקומו אחריו בלנצהוט. בנו ר חיים נספה בשואה."},{"i":55390,"n":"שפירא, אלעזר מדוברומיל","dt":"תשג","b":"רב בדוברומיל"},{"i":55391,"n":"שפירא, אלעזר מלנצהוט","f":"צבי אלימלך מדינוב","k":"אדמור מסטריזוב","bt":"תקסח","dt":"תרכה - יב אלול","dp":"וינה","b":"מקורב לגדולי האדמורים בדורו, תלמיד ר צבי הירש מזידיטשוב. חתן הגביר ר יהושע הלש הולס מדוקלא. רב בריבטיטש-תקפט על מקום אביו שעבר לדינוב, סטריזוב(=סטריזשוב)-תקצח ואדמור-תרא שם, לנצהוט(=לאנצוט)-תריז. נפטר בוינה ונקבר בלנצהוט (לפי צוואתו - והיה השתדלות גדולה לצורך כך - ובין המסייעים - רוטשילד). בניו ר מנחם מנדל פנחס ור שמחה על מקומו אחריו בלנצהוט, בנו ר שלמה על מקומו אחריו בסטריזוב. חיבר \"יודעי בינה\" - בכתב יד."},{"i":55392,"n":"שפירא, אלעזר מסנוק","f":"דוד האדמור מדינוב","k":"אדמור מדינוב בסנוק","bt":"תרס","dt":"תש..","b":"אדמור מדינוב בסנוק-תרצד על מקום אביו. חתן הרב הורביץ מרידניק האדמור מדזיקוב-סוקולוב. נספה בשואה."},{"i":55393,"n":"שפירא, אלעזר מסנוק","f":"משה ב\"ר שמואל","bt":"תרלז","bp":"סנוק","b":"אביו אדמור דינוב בסנוק. היגר לארה\"ב-תרף, סירב להצעת מהר\"ם שפירא - שפגשו בארה\"ב וביקשו לעמוד בראש עדת החסידים בברוקלין. עלה לארץ-תשיט."},{"i":55394,"n":"שפירא, אלעזר מריבטיטץ","dt":"תשג","b":"רב בריבאטיטץ"},{"i":55395,"n":"שפירא, אלתר אליקים שרגא מויקנא","f":"חיים שמעון מטלוסט","k":"בעל שם משמעון","r":"רב בויקנא וראב\"ד טשרנוביץ","bt":"תרטו","bp":"טלוסט","dt":"תרצו - ח אלול","b":"חתן ר ישראל הלוי מבקוי (רומניה) ועבר לשם, רב בויקנא, רב בטשרנוביץ גיסו של ר לוי יצחק אב\"ד הוש. חיבר \"שם משמעון\" זלישטשיק תרסה, ועוד.","bk":[["שם משמעון - עה\"ת",""],["בית יהודה - עה\"ת",""],["בית ישראל - עה\"ת",""],["מקור חיים - שבת ומועדים וחידושי אגדה על הש\"ס",""],["קול יהודה - שו\"ת",""],["קול יהודה - שו\"ת , שם משמעון - עה\"ת , בית יהודה - עה\"ת , בית ישראל - עה\"ת , מקור חיים - שבת ומועדים וחידושי אגדה על הש\"ס",""]]},{"i":55396,"n":"שפירא, אלתר חיים מלודז","b":"מרבני ישיבת חכמי לובלין"},{"i":55397,"n":"שפירא, אלתר משה","f":"צבי הירש שפירא"},{"i":55398,"n":"שפירא, אלתר ראובן מבוקובסק","f":"דוד האדמור מבוקובסק","k":"אדמור מבוקובסק בסנוק","bt":"תרסד-ע","bp":"סנוק","dt":"תשב - יח אייר","dp":"סמבור","b":"אחיו התאום של ר צבי אלימלך. אדמור מבוקובסק בסנוק על מקום אביו (בהוראת מהר\"ם שפירא בהיותו בן 19). חתן דודו ר פנחס יוסף קנר מזגורז. רב בפלשטין והקים שם ישיבה. רב בסמבור נספה בשואה."},{"i":55399,"n":"שפירא, אפרים פישל מבלוינא","b":"אב\"ד בלוינא. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":55400,"n":"שפירא, אריה ליב מיפו","f":"רפאל מוולוזין","b":"רב-שנת תרס, עלה לארץ עם אחיו ר ישראל איסר."},{"i":55401,"n":"שפירא, אריה ליב מלייפן","f":"אליהו שפירא","dt":"תעב - כו שבט","b":"רב בלייפן"},{"i":55402,"n":"שפירא, אריה ליב מלמברג","f":"יצחק","k":"בעל נחלת אריאל","r":"ספרא ודיינא בוילנא","bt":"תסא","bp":"וילנא","dt":"תקכא - טו אייר","dp":"וילנא","b":"חתן ר מרדכי עזריאל בן אברהם מוילנא. דיין בלבוב, סו\"ד(=ספרא ודיינא) בוילנא. אביו של ר מנחם זונדל מליובאויטש (בעיר וילנא - של ר אליעזר מליובטש), וזקנו של ר אריה ליב מקובנא. חיבר נוסח אל מלא רחמים על קדושי לבוב - ר חיים ור יהושע רייצעס שנהרגו עק\"ה ערב שבועות-תפח. חתנו ר אהרן מהורדנא, וחתנו בזיוו\"ש (של בתו) ר משה אב\"ד דאלהינוב בן בעל \"סדר הדורות\".","bk":[["מעון אריות - מסכת סופרים",""],["נחלת אריאל - מסכת סופרים",""]]},{"i":55403,"n":"שפירא, אריה ליב מסלויטה","f":"שמואל אבא שפירא","b":"מדפיס בסלאוויטא-תר\"י"},{"i":55404,"n":"שפירא, אריה ליב מקובנא","f":"מנחם זונדל מאיוואניץ","k":"ליבלי קובנר","bt":"תקמט","dt":"תריד - יז-ח שבט","b":"תלמיד ונכד-אבי אמו ר אליעזר שפירא מליובטש-בן ר אריה ליב בעל \"נחלת אריאל\" - ומכאן שמו - שפירא, תלמיד ר מנשה מאיליא - וקיבל ממנו את דרך הלימוד של הגר\"א. רב בואסילישוק, אילייה(=איליא), סמרגון - בהמלצת רבו וחותנו, קלווריה, רבה הראשון של קובנא - היה הראשון שנקרא אב\"ד - לפניו נקראו רבני קובנא בשם מו\"צ ורק רבני סלובודקה נקראו אב\"ד. התנגד לתנועת המוסר. נזכר במשנה ברורה שביטל המנהג לעמוד בקריאת עשרת הדברות, מתשובותיו ב\"אפריון דוד\". ששת בניו היו רבנים מפורסמים והם: ר מנחם זונדל - רב באילייה, ר שלמה - אב\"ד פירם, ר נח חיים אברהם על מקומו אחריו בסמרגון, ר לוי בעל \"בית לוי\" - אב\"ד טרישקי, ר רפאל מוולוזין- חתן הנצי\"ב, ר שמואל משה - רב בראמיגולה ועוד. חתניו - ר גרשון מקאלווריה, ר משה שלמה מאיליא. נספד ב\"ציון לנפש\" תרטז, \"שמע יעקב\" ליק תרך. מתלמידיו: ר ראובן לוין בעל \"ראש לראובני\", ר אריה רבינוביץ בעל \"באר היטב\" - המביא מתורת רבו בספריו, ר אלכסנדר ואלק, אחיינו - ר מרדכי סלומונוב מאיויניץ שגדל אצלו לאחר שנתייתם."},{"i":55405,"n":"שפירא, אריה ליב מקוטנא","f":"שלום מפשיטיק","k":"אדמור מקוטנא","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. חתן ר גרשון משדליץ (לובלין). אדמור בקוטנא, עבר ללובלין. נספה בשואה. פרסם מאמרים ב\"אוצר החיים\" - זאמושט תרצז."},{"i":55406,"n":"שפירא, אשר אלימלך מקוזניץ","f":"ירחמיאל משה מקוזניץ","dt":"תרצו - ב אלול","dp":"פאריז - קוזניץ","b":"מצאצאי המגיד מקוזניץ. חתן ר ברכיה בן ר משה יוסף מאיהל. רב בריקא, לובלין, קוזניץ וחתנו ר נחום שלמה בן ר משה מסטולין על מקומו אחריו."},{"i":55407,"n":"שפירא, אשר אלימלך מריקי","dt":"תשג","b":"רב בריקי"},{"i":55408,"n":"שפירא, אשר אנשיל מגלנטה","b":"רב בגאלאנטא-תקל\"ב"},{"i":55409,"n":"שפירא, אשר אנשיל מניישטט","f":"שמשון מפוזנא","b":"אולי אחיו של ר נתן בעל \"אמרי שפר\" ו\"מבוא שערים\"."},{"i":55410,"n":"שפירא, בן ציון מזלוטשוב","f":"שמואל מזלוטשוב","k":"בעל אבלת ציון","bt":"תרס","dt":"תשא","b":"רב בליסעץ, זלוטשוב-תרפח על מקום אביו. נספה בשואה על קדוש השם. חיבר \"אבלת ציון\" זלוטשוב תרפט. ?? לא באוצר ??"},{"i":55411,"n":"שפירא, בן ציון מסאהל","b":"חתן ר נח וינר מנובוגרד ועבר לשם, נסמך להוראה אך סירב לרבנות."},{"i":55412,"n":"שפירא, בן ציון מפטשניזין","b":"רב בפטשניזין לפני השואה. חתן ר דוד רייז מקולומיאה."},{"i":55413,"n":"שפירא, בנימין וולף מפרג","f":"אהרן שמעון שפירא","dt":"תעה - ז שבט","dp":"פרג","b":"רב בפרג ומדינת בוהמיה על מקום אביו-תם ור דוד אופנהיים על מקומו אחריו, רב המדינה-תסב. חתנו - ר יעקב ריישר."},{"i":55414,"n":"שפירא, בנימין וולף מפרג","f":"יחיאל","dt":"שצא - ז חשון","dp":"פרג","b":"דיין בפרג-שס. בנו - ר אהרן שמעון שפירא."},{"i":55415,"n":"שפירא, ברוך מזירביץ","b":"חתן ר אבא ליב שפירא מויטבסק. אב\"ד זירביץ-פלך מוהילוב."},{"i":55416,"n":"שפירא, ברוך מזלוטשוב","k":"אדמור מזלוטשוב","b":"אדמור בזלוטשוב. נכד האדמורים מנשכיז וקובל. ממשתתפי \"אסיפת חכמים\" תרעד."},{"i":55417,"n":"שפירא, ברוך מטשיזעוו","f":"יעקב יהושע","k":"אדמור מסטוטשין טשיזע","bt":"תקנז","dt":"תרלז - כב אב","dp":"וארשא","b":"מגדולי תלמידי ר יוסף מטורטשין (שושלת לובלין), ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק, ר יצחק מאיר מגור, ור יצחק מנסכיז. אדמור בסטוטשין-ליטא-תרכח, עבר לטשיזעוו. על קברו נבנה \"אוהל\". בניו: ר נתן מפילץ, ר זושא מסטאויסק."},{"i":55418,"n":"שפירא, ברכיה ברך מקראקא","k":"בעל זרע בירך","dt":"תכו - יט אלול","b":"מקובל,דרשן,דיין בקרקא. חיבר \"זרע בירך\". נכדו ר ברכיה ברוך הדפיס \"זרע בירך\" אמשטרדם.","bk":[["זרע ברך [עה\"ת]",""]]},{"i":55419,"n":"שפירא, דב בר מטימישואר","f":"אלתר אליקים שרגא","dt":"תשם","dp":"בני ברק","b":"מהדיר ספרי אביו. ניצל מהשואה - עסק בהצלה עם ר אליעזר הגר. חתן ר יעקב טירהויז בעל \"עקבי יעקב\". עלה לארץ-תשז."},{"i":55420,"n":"שפירא, דב בר מירושלים","b":"נאמן ביתו, ובעל קורא של ר שניאור זלמן פרדקין מלובלין וירושלים. חיבר זכרונות על רבו ונדפסו בחלקם בתוך \"הגאון מלובלין\"."},{"i":55421,"n":"שפירא, דב בר מנולב","dt":"תרנג - כז תמוז","b":"מצאצאי ר פנחס מקוריץ ובעל קדושת לוי. רב בנולב(=בנילוב), ובנו ר אברהם על מקומו אחריו."},{"i":55422,"n":"שפירא, דב בר משפיטיבקה","f":"יהודה מאיר משפיטיבקה","k":"אדמור משפיטיבקה","dt":"תרי - כו אדר","dp":"טלוסט","b":"נכד ר פנחס מקוריץ. שמו נבחר ע\"י הסנדק - ר זושא מאניפולי ע\"ש המגיד ממזריטש. חתן ר נפתלי הירץ מזינקוב, ובזיוו\"ש חתן ר צבי הירש מזידיטשוב. רב בסקאלא, רב ואדמור בשפיטיבקה(=שפיובקא)-תקפט על מקום אביו, טלוסט (בהשפעת גיסו ר חיים מקוסוב). מקורב לר לוי יצחק מברדיטשוב. מחותן עם ר ישראל מרוזין."},{"i":55423,"n":"שפירא, דב ברצי מטלוסט","f":"חיים שמעון מטלוסט","dt":"תרצב","b":"חתן הנגיד ר יצחק איזיק פוגל מדיבווה (במארמרוש). בנו ר משה מחשובי חסידי ויזניץ."},{"i":55424,"n":"שפירא, דב מלד-בנילא","b":"רב בלד-בנילא (בוקובינה). חתן ר לוי יצחק סגל אב\"ד הוש."},{"i":55425,"n":"שפירא, דב נחמן ממזריטש","f":"ישראל איסר","bt":"תרכא","dt":"תרצא","b":"רב בקונסטנטין-פלך שדליץ-תרנג, מזריטש-פלך שדליץ-תרס. הסכים על חובת אדם לר אהרן למדן."},{"i":55426,"n":"שפירא, דוד טעבל"},{"i":55427,"n":"שפירא, דוד מאלטונה","f":"יהודה או בנימין וולף","dt":"תלו - ג טבת","dp":"אלטונא","b":"דיין באלטונא. אחיו של ר שמעון אב\"ד פרג. חתנו - ר משה וינער ממגורשי וינה."},{"i":55428,"n":"שפירא, דוד מבוקובסק","f":"מאיר יהודה מבוקובסק","k":"אדמור מבוקובסק-דינוב","bt":"תרלז-ח","bp":"בוקובסק","dt":"תרפד - כט שבט","dp":"סנוק","b":"חתן האדמור יהושע הורביץ מדזיקוב בעל \"עטרת ישועה\", ובזיוו\"ש חתן האדמור חנניה יו\"ט ליפא טיטלבוים מסיגט בעל \"קדושת יו\"ט\". אדמור מבוקובסק-דינוב על מקום אביו-תרסט, היה באמריקה אחרי מלחמת העולם ה-I, וחזר לסנוק. בנו ר אלתר ראובן על מקומו אחריו בסנוק. מצאצאי ר צבי אלימלך שפירא בעל \"בני יששכר\". אחר מלחמת העולם ה-I וחורבן בוקובסק - עבר ללינסק, לארה\"ב וחזר והתישב בסנוק - שם ישב גיסו ר דוד שפירא האדמור מדינוב. ידיד נפש למהר\"ם שפירא - שבהלויתו הכתיר את בנו ר אלתר ראובן על מקום אביו (אחיו התאום ר צבי אלימלך שעלה לתל אביב)."},{"i":55429,"n":"שפירא, דוד מגרנוב","f":"מאיר","bt":"תרו-י","b":"רב בגראנוב-פודוליה-תרם."},{"i":55430,"n":"שפירא, דוד מדינוב","f":"צבי אלימלך מדינוב","k":"אדמור מדינוב","bt":"תקסד או תקפב","bp":"סטריזוב","dt":"תרלד - יד-ט אדר","b":"בנו של הבני\"ש. נקרא ע\"ש החסיד ר דוד מליזנסק ואביו הורה לו להוסיף י על שמו ולכן חתם - דויד. מקורב לגדולי האדמורים. רב ואדמור בדינוב-תרא לאחר שאחיו ר שמואל ויתר לו על הרבנות. מחסידיו ר אליעזר צבי מקומרנא. בנו ר ישעיה נפתלי הירץ על מקומו בדינוב, ר צבי אלימלך בבלוזוב, ור מאיר יהודה בבוקובסק. חיבר \"צמח דוד\" פרמישלא תרלט."},{"i":55431,"n":"שפירא, דוד מדינוב וסנוק","f":"יוסף מדינוב","k":"אדמור מדינוב בסנוק","bt":"תרלז-ח","bp":"דינוב","dt":"תרצג-ד -כו תשרי","b":"מצאצאי הבני\"ש. חתן ר מאיר יהודה שפירא מבוקובסק. אדמור מדינוב בסנוק (עוד בחיי אביו), מוכשר בנגינה ושחזר ניגונים עתיקים. לאחר מלחה\"ע ה-I הגיע לארה\"ב עם בנו ר אלעזר - וחזרו לאירופה. רב בדינוב-תרצב על מקום אביו. בנו ר מנחם מנדל על מקומו כרב בדינוב. בנו ר אלעזר על מקומו כאדמור בסנוק. השאיר כתבים רבים - חסידו ר דוד גרטנברג הדפיסם בבליגורי תרצט, הדפוס עם כל הספרים נשמדו בשואה. מבניו: ר מנחם מנדל מדינוב, ור ישראל - נספו בשואה."},{"i":55432,"n":"שפירא, דוד מילביסטגראד","f":"פנחס יהודה ליב מסלאו","k":"אדמור מיילביסטגרד","dt":"תרצד - ג אב","dp":"ישראל","b":"מצאצאי ר זושא מאניפולי. חתן ר אברהם לנדמן משפיטובקא (סטרליסק). אדמור ביילביסטגראד. עלה לארץ-תרצג."},{"i":55433,"n":"שפירא, דוד מקובנה","f":"חיים יעקב שפירא","k":"בעל בגדי שרד","bt":"תריד","dt":"תרצז - ד אייר","b":"רב פעלים,רב בקובנה-תרמ\"ז"},{"i":55434,"n":"שפירא, דוד מראסיין","f":"אליהו","dt":"תקס - ח אייר","dp":"ראסיין","b":"רב בראסיין. חתניו - ר רפאל מראסיין, ר צבי הירש מראסיין, ר יהודה ליב מראסיין. אחיו - ר אברהם שוועקשנער-אב\"ד טלז."},{"i":55435,"n":"שפירא, דוד מרדומסק","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":55436,"n":"שפירא, דוד משה מגווזדיץ וני\"י","f":"יצחק מרדכי מגווזדיץ","k":"אדמור מגווזדיץ-ס\"ג","bt":"תרסד","bp":"גווזדיץ","dt":"תשמח - טו אייר","b":"נקרא ע\"ש האדמור מצורטקוב. ברח בתרעד לוינה והתסופף בצל אדמורי רוזין שם. תלמיד ר מאיר ארק ואחיו ר ירוחם פישל. חתן ר שלמה חיים פרלוב מבוליחוב, ובזיוו\"ש חתן ר שרגא פייביש הגר מזישטשיק. רב בוינה על מקום אביו, ניצל מהשואה - ברח לאנגליה-תרצט, עבר לארה\"ב-תשא וכיהן כאדמור מגווזדיץ-סדיגורה בניו יורק. חיבר \"דודאים של משה\" ניו יורק תשנב."},{"i":55437,"n":"שפירא, דוד משה מזלוטשוב","f":"שמואל מדוברומיל","bt":"תרסד","b":"רב בזלוטשוב, דיין בבוליחוב. חתן ר חיים גרינברג מגלינא. גיסו של אורי צבי גרינברג."},{"i":55438,"n":"שפירא, דוד פנחס יחזקאל מסוסנוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":55439,"n":"שפירא, היינריך מפטרבורג","f":"אהרן","bt":"1852","bp":"גרודנא","dt":"1901","b":"רופא בפטרבורג."},{"i":55440,"n":"שפירא, הירש מפרשבורג","b":"מראשי קהלת פרשבורג-תקסז, אחד מאנשי המשלחת אל החת\"ס במטרסדורף להציע לו את רבנות פרשבורג."},{"i":55441,"n":"שפירא, זאב","f":"משה מזלטופול","b":"חתן ר חיים מטראספול(=טרספול)."},{"i":55442,"n":"שפירא, זאב מטרנופול","f":"יהודה שמשון","b":"רב בטרנופול. הביא לדפוס \"ברית מנוחה\" -ברדיטשוב תקסז."},{"i":55443,"n":"שפירא, זאב מלנצהוט","dt":"תשג","b":"רב בלנצהוט"},{"i":55444,"n":"שפירא, זושא מסטאויסק","f":"ברוך מטשיזעוו","b":"רב בסטאויסק."},{"i":55445,"n":"שפירא, זכריה מדורוג","f":"נתן שפירא","dt":"תרנג","b":"רב בדורוג,ווראנא"},{"i":55446,"n":"שפירא, זכריה מוארנוב","b":"רב בוורנוב-תרלח."},{"i":55447,"n":"שפירא, זכריה מנדל מטרנוב","b":"מזכיר חברת \"ציון\" בטרנוב. הוציא כתב עת \"אהבת ציון\" - קראקא תרנה - ובה דברי עידוד ליוצאי מוינשט (רומניה) שהתישבו בראש פינה."},{"i":55448,"n":"שפירא, זכריה מנדל מפרג","dt":"תע - טז אב","b":"דיין בפרג-תסד, אחד מ-5 הדיינים הנקראים אפלנטים בפרג. חתן ר יוסף גינצבורג מפרג, וצאצאיו כינו עצמם גינצבורג שפירא. הסכים על \"אבן השהם\" לר אליקים געץ דירנפורט תצג. בנו - ר צבי הירש, ונכדו ר משה דיין בפרג-תקכד."},{"i":55449,"n":"שפירא, זליג","b":"רב-שנת תר\"ס"},{"i":55450,"n":"שפירא, חיים","f":"יוסף מקשאנוב","dt":"תשא","b":"מקורב לאדמורי דורו. חתן ר אליעזר דוד דרשביץ משיניבה, בנו ר יוסף מנכבדי בני ברק."},{"i":55451,"n":"שפירא, חיים אלעזר ממונקטש","f":"צבי הירש ממונקטש","k":"אדמור ממונקטש-מנחת א","r":"ראב\"ד מונקאטש","bt":"תרלב","bp":"סטריזוב","dt":"תרצז - ב סיון","b":"הדב\"ח העיד עליו שאחד כזה יורד לעולם פעם בכמה דורות. חתן ר שרגא יאיר רבינוביץ מביאליברזיג (נכד היהודי הקדוש מפשיסחה), ובזיוו\"ש חתן ר יעקב משה ספרין מקומרנא. חתנו ר ברוך יהושע ירחמיאל רבינוביץ על מקומו אחריו-תרצז והוציא לאור את ספרו. מקורב לגדולי האדמורים. רב בטשנידיוב (ליד מונקטש)-תרסד, רב במונקטש-לצד אביו על מקום המהרש\"ג ואחר פטירת אביו על מקומו אחריו-תרעד כרב ואדמור. ביקר בארץ-תרץ לפגוש את ידידו רש\"א אלפנדרי, והקים בה שכונה. היה מיודד עם הגרף ההונגרי שינבורן שהיה לו לעזר בסיוע ליהודים. חיבר \"מנחת אליעזר\" מונקטש תרסב, ועוד. פרסם מאמרים ב\"הכוכב\" - מונקטש תרצה, \"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב, \"הנשר\" - טירנוי תרצג-תשד, \"תורה מציון\" - ירושלים תרנה-תרסה, \"תל תלפיות\" - וייצען תרנב-תרעד.","bk":[["מנחת אלעזר","שו\"ת - אחרונים"],["אות חיים ושלום – מילה ותפילין",""],["דברי תורה",""],["דרכי תשובה - מקוואות",""],["הגהות הירושלמי",""],["חיים ושלום - עה\"ת",""],["חמשה מאמרות",""],["מנחת אלעזר – שו\"ת",""],["נמוקי אורח חיים",""],["עולת תמיד",""],["שער יששכר",""],["שערי יששכר – מועדים",""],["מנחת אלעזר (מונקאטש)",""],["מנח' אלעזר",""]]},{"i":55452,"n":"שפירא, חיים חייקל מצפת","f":"יוסף יהודה ליב מרחמי","b":"מראשי כולל ווהלין בטבריה וצפת."},{"i":55453,"n":"שפירא, חיים יעקב מקובנה וירושל","f":"יצחק מנחם זונדל מאיל","dt":"תרסח","dp":"ירושלים","b":"אביו היה רבה של איליא ונפטר צעיר, וגדל אצל זקנו - ר אריה ליב שפירא רבה של קובנא. ד\"צ על ה\"הר הירוק\", דיין אצל ר יצחק אלחנן בקובנא. בשנת תרנא עלה לירושלים, ור שמואל סלנט מינהו לבית דינו, ונכדתו שעלתה עמו נישאה לר צבי פסח פרנק רבה של ירושלים. מראשי כולל קרלין-פינסק בירושלים. בנו - ר דוד בעל \"כנויי שרד\". חתנו - ר חיים יעקב שפירא מקובנא, ונכדו ר דוד שפירא בעל \"כנויי שרד\"."},{"i":55454,"n":"שפירא, חיים מאוסטרהא","f":"יחזקאל מאוסטרהא","k":"אדמור מאוסטרהא"},{"i":55455,"n":"שפירא, חיים מאיר יחיאל מגרודז'","f":"אלימלך שפירא","dt":"תרלג - ב אלול","b":"אדמו\"ר בגראדזינסק"},{"i":55456,"n":"שפירא, חיים מאיר יחיאל מדרוהוב","f":"אביעזרי זליג מסטמר","k":"אדמור מדרוהוביטש","bt":"תרכד","bp":"סדיגורא","dt":"תרפד - ל ניסן","dp":"ארץ ישראל","b":"מצאצאי המגיד מקוזניץ, נכד השרף ממוגילניצה ונכד האדמור ר אברהם יעקב מסדיגורא. חתן ר יצחק מבוהוש (ור יצחק רובין מברודי). אדמור מסדיגורא בדרוהוביטש-תרמה בסגנון בית רוזין. פעיל מסור למען ישוב ארץ ישראל (לאחר שפגש בילדותו את סיר אוליפנט - בביקורו אצל זקנו בסדיגורא), ממייסדי \"אגודת ישוב ארץ ישראל\". הקים ישיבה ובראשה האחים קיטיגרודסקי. עבר לוינה במלחה\"ע ה-I, עלה לירושלים-תרפב עם אמו ועם כ-30 משפחות מחסידיו, ובנה בית מדרש. עודד את בניו להתפרנס מעבודת כפיים. בניו - ר אברהם יעקב האדמור הצייר, ר אביעזרי, ר יצחק-חתן ר יוסף פנצר. חיבר \"השלום והאחדות\" דרוהוביטש תרעד.","bk":[["השלום והאחדות (דרוהוביטש)",""]]},{"i":55457,"n":"שפירא, חיים מאיר יחיאל ממוגלנ","f":"אביעזרי זליג מגריניץ","k":"השרף ממוגילניצה","bt":"תקמט","dt":"תרט - טו אייר","dp":"וארשא","b":"תלמיד זקנו המגיד מקוזניץ, החוזה מלובלין, ר אברהם יהושע השל מאפטא, וחברו של היהודי הקדוש מפשיסחא. חתן ר אלעזר מליזנסק. רב בגריצא, מוגלניצא ונקרא ה\"שרף\", אדמור-תקפח לאלפי חסידים ולעשרות אדמורים, ומשנת תרג אדמור לחסידי רדושיץ על מקום רבו וחברו ר ישכר בער מרדושיץ. ביקש לשרוף את כל כתביו לפני פטירתו. מתורתו ב\"תפארת חיים\", \"שיחות חיים\", \"תולדות הנפלאות\". בניו - ר יעקב יצחק מבלנדוב, ר אלימלך מגרודזיסק, ר משה יוסף מגריצא, ראי\"ה ממוגילניצה. חתנו ר יהודה הורביץ האדמור ממעליץ. מתורתו ב\"התפוח\" - בנדין תרפח."},{"i":55458,"n":"שפירא, חיים מאיר יחיאל מנרול","f":"דב בריש ריינמן מנרול","k":"אדמור מנרול","bt":"תרסז","bp":"נרול","b":"קיבל את שם זקנו מצד אמו \"שפירא\". לאחר שנתייתם גדל אצל זקנו - ר שלום ריינמן, ועבר עמו לקאשוי. חתן ר משלם זלמן יוסף זילברפרב מטופורוב (שושלת לכוביץ). רב ואדמור בנרול-תרפט על מקום אביו (לאחר מחלוקת שהוכרעה בדין תורה). ניצל מהשואה - ברח לסמרקנד, חזר ללודז, פרג, רב באנטורפן-תשז, ניו יורק-תשי, עלה לארץ-תשלב וכיהן כאדמור בבני ברק. בנו ר דב בעריש רבם של חסידי נארול בניו יורק."},{"i":55459,"n":"שפירא, חיים מאיר מרדיחוב","f":"אביעזרי זליג מרדיחוב","k":"אדמור מרדיחוב","bt":"תריג","bp":"בלז","dt":"תרסה","b":"נכד לשר שלום מבלז והשרף ממוגילניצה. אביו - האדמור מקאלושין. רב ואדמור ברדיחוב-תרל, סירב למלא מקום אביו בקאלושין. בנו ר יצחק על מקומו ברדיחוב."},{"i":55460,"n":"שפירא, חיים מבוקובסק","f":"אלעזר מלנצהוט","bt":"תרנא","bp":"בוקובסק","b":"חתן דודו ר אלימלך שפירא. סירב לרבנות לנצהוט ומסרה לגיסו."},{"i":55461,"n":"שפירא, חיים מברזיסק","dt":"תרצד - יז תמוז","b":"רב בברויסק"},{"i":55462,"n":"שפירא, חיים מהלסקוב","f":"יעקב אליהו מהלסקוב","bt":"תרכז","b":"חתן אב\"ד האצילע-פלך חרסון (מי זה?!). מו\"ץ בהלסקוב אצל אביו-תרמו, ורב-תרסט על מקומו אחריו."},{"i":55463,"n":"שפירא, חיים מטרספול","f":"מאיר","bt":"תרכא","b":"מצאצאי ר פנחס מקוריץ, נכד ר יעקב שמשון משפיטובקא. רב בטירספול(=טראספאל)-פלך חרסון-תרנב. בנו - ר מאיר. חתניו: ר דב בר זידמן, ר זאב דוד בן ר משה מזלטיפול."},{"i":55464,"n":"שפירא, חיים מסלאויטה","f":"יצחק גדליה מסלאויטה","b":"מצאצאי ר זושא מאניפולי. רב בסלאויטה על מקום אביו."},{"i":55465,"n":"שפירא, חיים מפלאצק","f":"שלום מפשיטיק","bt":"תרלט","dt":"תרפ - יג אלול","b":"מצאצאי המגיד מקוזניץ. חתן ר אלימלך מסטאשוב (ליזנסק). נהרג עק\"ה ע\"י הפולנים-תרף שהאשימוהו בריגול לטובת הרוסים."},{"i":55466,"n":"שפירא, חיים נח מסאהל","f":"[יצחק שו\"ב פידבוש]","dt":"תרצד","b":"חתן ר יעקב קופל מרילוס מליטוביסק. חסיד צורטקוב. שו\"ב בסאהל, פידבוש על מקום חותנו."},{"i":55467,"n":"שפירא, חיים נחמן","f":"אברהם דובער מקובנא","k":"בעל תולדות הספרות הע","bt":"1895","bp":"מינסק","dt":"תשד - ה כסלו","b":"אביו היה רבה של קובנא. נכד \"הגדול\" ממינסק. למד באוני' ברלין. פרפו' לשפות שמיות בקובנא. פרסם מאמרים בנושאים שונים בעברית, אידיש, גרמנית, וליטאית. חבר המרכז הציוני, וחבר נשיאות \"תרבות\", ועוד. בזמן השואה היה מנהל הפעילות החינוכית בגיטו סלובודקה. נספה בשואה. כמה מחבוריו אבדו בשואה. פרסם בליטאית ספרים על אברהם מאפו ועל לייב ניידוס."},{"i":55468,"n":"שפירא, חיים נפתלי צבי מקאלוש","f":"אברהם ישכר דב אביגדו","k":"אדמור מקאלושין","bt":"תרכב","dt":"תש או תשב","dp":"מינסק מזוביצק","b":"בן האדמור מקאלושין. נכד - מצד אמו - ר מנחם מנדל מלינסק (שושלת רופשיץ). חתן ר אבי עזרי זליג אלעזר מקאלושין. נספה בשואה."},{"i":55469,"n":"שפירא, חיים צבי מלפיטש","f":"שמואל משה מרמיגולה","bt":"תרלג","b":"רב בלאפיטש(=לאפיץ)-פלך מינסק-תרס."},{"i":55470,"n":"שפירא, חיים שלום מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":55471,"n":"שפירא, חיים שמעון מטלוסט","f":"דב בר מטלוסט","bt":"תקצז","dt":"תרסא - יד-ז שבט","b":"סירב למלא מקום אביו בסלוסט. חתן ר אליהו אריה מטלוסט (מצאצאי ר אברהם הורניק - תלמיד הבעשט). בניו ר אלתר מויקנא וטשרנוביץ בעל \"אהלי צדיקים\" ור דב בערצי."},{"i":55472,"n":"שפירא, חייקל מקלינבלט","b":"רב בקלינבלט"},{"i":55473,"n":"שפירא, טוביה","f":"משה מפשמישל","b":"נכד ר שמואל בנו של ה\"בני ישכר\"."},{"i":55474,"n":"שפירא, טוביה פסח - ט\"ף","k":"בעל משלי אב","bt":"1845","bp":"סייני","dt":"1924","dp":"קאלואירה","b":"למד בארה\"ב וחזר לסייני. מורה בלודז. חיבר גם \"משל הקדמוני\", ועוד. תרגם לעברית \"שפינוזה\" לברתולד אוירבך."},{"i":55475,"n":"שפירא, יהודה ליב מלבוב","f":"נתן נטע","b":"מראשי קהלת לבוב, חתם-תקד בפנקס הקהלה."},{"i":55476,"n":"שפירא, יהודה מאיר מלובלין","f":"יעקב שמשון משאץ","k":"מהר\"ם מלובלין","r":"הרב מלובלין","bt":"תרמז","bp":"שאץ","dt":"תרצד - ז חשון","b":"נכד ה\"מנחת שי\" שאצלו למד. חתן הנגיד ר דוד יעקב ברייטמן מטרנופול. חסיד צורטקוב, רב גלינא-תרעא על מקום ר אליעזר גרינברג ויסד שם ישיבה. יו\"ר ועדת החינוך של אגו\"י. רב בסנוק-תרפא והקים שם ישיבה. נאם בועידת רבני פולין-תרפב, רב בפיעטרקוב-תרפב. נשיא אגו\"י בפולין לבקשת האדמור מגור ונבחר לסיים הפולני. חידש את לימוד הדף היומי. רב בלובלין-תרץ על מקום ר אליהו קלצקין, והקים בה את ישיבת חכמי לובלין - ולצורך כך נסע בשליחות ברחבי אירופה. רב בלודז-תרצד (לאחר שהתחייבו לפרוע את חובות הישיבה). תלמידו ר שמואל ווזנר הקים בבני ברק את ישיבת חכמי לובלין. חיבר \"אור המאיר\" פיעטרקוב תרפו, ועוד.","bk":[["אור המאיר [שו\"ת",""],["הגדש\"פ]",""],["אמרי דעת",""],["מרגניתא דרבי מאיר",""],["רבי מאיר שפירא – במשנה באומר ובמעש",""],["רבי מאיר שפירא – במשנה באומר ובמעש, אור המאיר - שו\"ת , אמרי דעת , מרגניתא דרבי מאיר",""]]},{"i":55477,"n":"שפירא, יהודה מאיר משפיטיבקה","f":"פנחס מקוריץ","k":"אדמור משפיטובקא","bt":"תקכ","dt":"תקפט -כט ניסן","dp":"שפטיבקה","b":"חתן ר יעקב שמשון משפיטיבקה ורב שם על מקומו אחריו. (היה מהחולקים על דרכו של ר ברוך ממזבוב). תלמיד ר חיים מקרוסנא שהכתירו כאדמור על מקום אביו-תקן."},{"i":55478,"n":"שפירא, יהודה מבוצאץ","b":"ממשפחת הדיין בינשטוק מפודקמין. מחכמי בוצאץ-תרנג, רב בפודקמין."},{"i":55479,"n":"שפירא, יהודה משאוולי","b":"ר\"מ בישיבת שאוולי אצל ר יצחק מאיר יודלביץ."},{"i":55480,"n":"שפירא, יהושע איזיק חריף מסלוני","f":"יחיאל","k":"איזל חריף -עמק יהושע","bt":"תקסא","bp":"גלובקי-פלך וילנא","dt":"תרלג - ד טבת","dp":"סלונים","b":"נכד בעל סדר הדורות. בילדותו למד בביהמ\"ד \"בלומקה\" במינסק בהשגחת ר אברהם דבוריצר וכונה \"העילוי מגלובוק\". חתן הגביר ר יצחק פיין. מגדולי חכמי דורו, רב בקאלואריה, קוטנא, טיקטין, סלונים. הצטיין בחריפות ובשנינות ואמרותיו השנונות שגורות בפי רבים. חיבר גם \"נועם ירושלמי, ועוד. בניו: ר בערוש מאוסטרוב, ר משה מוילקומיר בעל פני משה, ר מרדכי (נפטר צעיר - ובנו ר אברהם - רב בניו יורק). חתנו ר יוסף שלופר בעל \"פורת יוסף\". פגש את הגדול ממינסק בצעירותו בביקורו בבריסק והתפעל ממנו. נספד מאת ר בנימין רייגראד ב\"אבל כבד\" ירושלים תרלה. (ר איזל אמר שמקור שמו חריף הוא ר\"ת - חתן ר יצחק פיין).","bk":[["אבי הנחל – דרוש",""],["מרבה עצה – מאמרי רבב\"ח",""],["מרבה תבונה - מוסר",""],["נועם ירושלמי – ירושלמי",""],["נחלת יהושע – שו\"ת",""],["עמק יהושע – שו\"ת",""],["עצת יהושע – סבי דבי אתונא",""],["שפת הנחל – דרוש",""],["נועם ירושלמי [על הירושלמי]",""]]},{"i":55481,"n":"שפירא, יהושע השל מזיטומיר","f":"פנחס מסלאויטה","b":"מדפיס בזיטומיר. חתן ר מיכל מוישנוביץ."},{"i":55482,"n":"שפירא, יהושע מזאבלודוב","k":"בעל פנים מסבירות","b":"רב בזאבלודאווי(=זאבלודוב), ביאליסטוק, שווערין ומדינת מקלנבורג-תקכ. חיבר גם קונטרס הר\"י שפירא - ברלין תקיז."},{"i":55483,"n":"שפירא, יהושע מסעלץ","b":"מחכמי סעלץ-תרכג בזמן הגדול ממינסק."},{"i":55484,"n":"שפירא, יהושע מריבטיטש","f":"צבי אלימלך מבלוזוב","k":"אדמור מרישא","bt":"תרכב","dt":"תרצב - יא אד\"א","b":"נכד האדמור מדינוב בעל \"בני ישכר\". חתן דודו ר מנחם מנדל מרילס מרופשיץ, ובזיוו\"ש חתן ר יעקב דכנר מדלטין. רב בבלוזוב-תרמב לצד אביו, רב בריביטש-תרנו, רב ואדמור ברישא-תרפה. בנו ר מאיר רב בבלוזוב. ובנו ר ישראל אדמור בבלוזוב. בנו ר אליעזר על מקומו אחריו בריבטיטש. חיבר \"קרן ישועה(יהושע)\" בילגוריא תרצז."},{"i":55485,"n":"שפירא, יהושע צבי מיכל מירושלים","f":"יעקב קאפל","k":"בעל ציץ הקדש","bt":"תר","bp":"חברון","dt":"תרסו - יב אלול","dp":"ירושלים","b":"נכד ר זאב ועלוויל חריף מטיקטין. תלמיד ר משה יהודה ליב מקוטנא, ר יוסף שטיינהרט מסמארגאן-שהיה מבאי ביתו של ר חיים מוולוזין, תלמיד חבר למהרי\"ל דיסקין בירושלים. חתן ר נחמן נתן קורנל, עבר לירושלים-תריז. חיבר גם \"צבי לצדיק\" תרסז, ועוד. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז. מתלמידיו: הגרי\"מ חרל\"פ, הגר\"מ הלר סעמינצר. בנו - ר אברהם בן ציון.","bk":[["אמרות טהורות",""],["התרגשות הלב",""],["צבי לצדיק",""],["ציץ הקדש",""],["בעון מחלוקת וסייגיו",""],["צבי לצדיק - מכתבים",""],["ציץ הקודש - שו\"ת באו\"ח ומצוות התלויות בארץ",""],["צבי לצדיק - מכתבים, בעון מחלוקת וסייגיו",""]]},{"i":55486,"n":"שפירא, יוסף אהרן מאונסדורף","b":"רב באונסדורף-תק\"נ"},{"i":55487,"n":"שפירא, יוסף אהרן מיגולניצה","f":"קמואל","dt":"תקעב","b":"צדיק ביגולניצה. חותנו של ר יצחק קוך קוסובר. נכדו - ר אליהו רוזן מאושפיצין."},{"i":55488,"n":"שפירא, יוסף ברוך מצנסטכוב","f":"אביגדור מצנסטכוב","k":"אדמור מצנסטחוב","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. אדמור בצנסטכוב על מקום אביו. נספה בשואה."},{"i":55489,"n":"שפירא, יוסף הכהן","b":"רב-שנת ת\"כ"},{"i":55490,"n":"שפירא, יוסף חיים מהלסקוב","f":"ליבלי יאניוור","b":"רב בהלסקוב(=האלאסקוב)-פודוליה-תיב ובנו ר יוסף חיים על מקומו אחריו."},{"i":55491,"n":"שפירא, יוסף יאסקי מלעסלא","k":"בעל חידושי מהר\"י שפי","b":"רב בלעסלא. בנו - ר אליהו מטשרניקוב."},{"i":55492,"n":"שפירא, יוסף יהודה ליב מבילצור'","b":"רב בבילוצרקוב,מגיד בבאלטה-תק\"כ,בזזין"},{"i":55493,"n":"שפירא, יוסף יהודה ליב מרחמיסט'","f":"חיים חייקל","b":"רב ברחמסטריבקה, עלה לארץ, ראש הכולל בצפת. בנו - ר חיים חייקל מצפת. בנו - ר חיים חייקל מצפת על מקומו אחריו."},{"i":55494,"n":"שפירא, יוסף יוסקא משפיטובקא","f":"יהודה מאיר משפיטיבקה","dt":"תקסז - כג אדר","b":"נכד ר פנחס מקוריץ. חתן ר יצחק מקאליס בנו של מר משה חיים אפרים מסדילקוב בעל \"מחנה אפרים\"-נכד הבעשט."},{"i":55495,"n":"שפירא, יוסף מאוגוסטוב","dt":"תרח - יג תמוז","b":"רב באוגוסטוב"},{"i":55496,"n":"שפירא, יוסף מארה\"ב","f":"אברהם מרדכי","bt":"תרסו","bp":"מנצסטר-אנגליה","b":"תלמיד ישיבה במונטריאול, ישיבת רבי יצחק אלחנן בניויורק. חתן ר אהרן יצחק בגמן. רב ברדינג-ליד פיטסבורג-תרפט, קהלת \"פועלי צדק\" בפיטסבורג-תרצג. חבר אגודת הרבנים באמריקה, ותנועת המזרחי. ממיסדי הישיבה \"הלל אקאדמי\" בפיטסבורג."},{"i":55497,"n":"שפירא, יוסף מבלוזוב","f":"מאיר מבלוזוב","k":"אדמור מרישא","dt":"תש..","b":"רב בבלוזוב לצד אביו. הוציא לאור \"קרן יהושע\" לזקנו. חתן ר אליהו בומבך מאושפיצין. אדמור ברישא-תרצב בחיי אביו. נספה בשואה."},{"i":55498,"n":"שפירא, יוסף מברעזי","f":"יהושע","b":"מצאצאי בעל \"מגלה עמוקות\". רב בברעזי."},{"i":55499,"n":"שפירא, יוסף מגרשקוביץ","dt":"תשג","b":"רב בגרשקוביץ"},{"i":55500,"n":"שפירא, יוסף מדינוב","f":"צבי אלימלך מבלוזוב","bt":"תרכח","dt":"תרן","b":"החליף שו\"ת עם גדולי דורו. נספה במגפה בצעירותו."},{"i":55501,"n":"שפירא, יוסף מדינוב","f":"צבי אלימלך מברטש","k":"אדמור מדינוב","bt":"תרך","dt":"תרצב - יז אד\"א","b":"נכד ר אלעזר מלנצהוט. חתן ר ישעיה נפתלי הירץ שפירא האדמור מדינוב, רב ואדמור בדינוב-תרמה על מקום חותנו. בנו ר דוד האדמור מדינוב בסנוק. מתורתו ב\"תורות בית דינוב\"."},{"i":55502,"n":"שפירא, יוסף מויניצא","f":"יעקב מטומאשפיל","k":"בעל אבני זכרון","b":"רב בויניצא-תרנב על מקום אביו. פרסם מאמרים ב\"המאור\" - תל אביב תרצה. חיבר גם \"שלום המלכות\", \"שי למורה\", ועוד."},{"i":55503,"n":"שפירא, יוסף מנחם מפרגא","f":"יעקב יצחק מבלנדוב","dt":"תרפז - יז אב","b":"רב בבלנדוב-תרמב. מצאצאי המגיד מקוזניץ. חתן ר שמעלקא מקוזניץ (בעלז)."},{"i":55504,"n":"שפירא, יוסף מנסכיז","f":"יעקב אריה מנסכיז","bt":"תרלג-ו","b":"מצאצאי ר השל מקראקא, נכד ר מרדכי מנסכיז. רב בנסכיז(=נעסכאיז)-ווהלין-תרס."},{"i":55505,"n":"שפירא, יוסף מסטרי","f":"שמעון מדואץ","dt":"תרצד","dp":"וינה","b":"מחכמי סטרי. נקבר בוינה לצד האדמור מצורטקוב."},{"i":55506,"n":"שפירא, יוסף מקאמין","f":"לוי יצחק מקאמין","b":"מצאצי ר יצחק מנסכיז. חתן ר אברהם מאוסטרהא."},{"i":55507,"n":"שפירא, יוסף מקוזניץ","f":"יעקב יצחק שפירא","b":"אדמו\"ר בקוזניץ-תר\"מ"},{"i":55508,"n":"שפירא, יוסף מקראקא","b":"מגדולי חכמי קרקא-שנת ש'"},{"i":55509,"n":"שפירא, יוסף מקשאנוב","dt":"תרסג","dp":"קשאנוב","b":"מצאצאי ר פנחס מקוריץ. חסיד צאנז. מראשי הקהל בקשאנוב. הביא את ר דוד הלברשטם (בן הדברי חיים) לכהן כרב-תריא - ולשם כך אחסן בביתו 6 שבועות את הדברי חיים. ידידו של ר שלמה מבובוב."},{"i":55510,"n":"שפירא, יוסף מרישא","dt":"תשג","b":"רב ברישא"},{"i":55511,"n":"שפירא, יוסף משה מזלוזיץ","f":"אלקנה","k":"בעל באר מים","bt":"תצה","dt":"תקעה - כג אלול","b":"מראשוני גדולי החסידות. תלמיד המגיד ממזריטש והמגיד מזלוטשוב. מגיד בזבורוב, זאלוזיץ(=זלאזיטש). חיבר \"באר מים\" מזבוז תקעד, \"ברית אברם\", ועוד."},{"i":55512,"n":"שפירא, יוסף משה מירושלים","b":"מראשי כולל וארשא בירושלים-תרסא."},{"i":55513,"n":"שפירא, יחזקאל מאוסטרהא","f":"פנחס מקוריץ","k":"אדמור מאוסטרהא","dt":"י תשרי","b":"חתן ר יוסף מאוסטרהא. רב באוסטרהא-תקס. הוציא לאור זוהר חדש. חתן ר יוסף הסוחר מפולנאה. (הסתיר את יחוסו לאחר שבאחד ממסעות העסקים גילה שם אביו - והיה שם רעש גדול)."},{"i":55514,"n":"שפירא, יחזקאל מוידוקלא","f":"צמח מקידאן","b":"רב בוידוקלא-פלך ראסיין."},{"i":55515,"n":"שפירא, יחיאל יוסף","f":"משה מריגה-פני משה","b":"נכד ר איזל חריף בעל \"עמק יהושע\". נזכר בספרי אביו."},{"i":55516,"n":"שפירא, יחיאל מאיר מבנדין","f":"שלום מפשיטיק","k":"אדמור מנריקווא","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. נספה בשואה."},{"i":55517,"n":"שפירא, יחיאל מגלובקי","f":"מרדכי","b":"מחכמי גלובקי-תקס, פנה לחסידות והיה מחסידי בעל התניא ולאחר פטירתו התקרב לר אהרן הורביץ מסטרוסילה. בנו - ר איזל חריף בעל \"עמק יהושע\"."},{"i":55518,"n":"שפירא, יחיאל מזמיגרוד","f":"אברהם","b":"רב בזמיגרוד לפני השואה."},{"i":55519,"n":"שפירא, יחיאל מיכל","k":"בעל דעת לנבונים","b":"תשובה ממנו ב\"קהלת אשר\" - אושפיצין תרפג."},{"i":55520,"n":"שפירא, יחיאל מפרג","b":"רב בפרג-ת\"כ"},{"i":55521,"n":"שפירא, יעקב","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":55522,"n":"שפירא, יעקב אליהו מהלסקוב","f":"יוסף חיים מהלסקוב","dt":"תרסח","b":"רב בהאלאסקוב על מקום אביו, ובנו ר חיים על מקומו אחריו."},{"i":55523,"n":"שפירא, יעקב אריה מנסכיז","f":"מרדכי מסטביחוב","k":"אדמור מנסכיז","dt":"תרסח - ט כסלו","dp":"קאוולי","b":"מצאצאי ר יצחק מנסכיז. חתן ר יחיאל אלתר פראלגער מאיוונצק-חתן ר יעקב מאפטא (ללוב)."},{"i":55524,"n":"שפירא, יעקב אריה מקאוולי","f":"מרדכי מנשכיז","k":"אדמור מנסכיז קאוולי","bt":"תקם","dt":"תקצז-ח -כז אלול","b":"חתן ר יצחק מליבאוונא-תלמיד אביו. רב בקאוולי, נסכיז, טריסק."},{"i":55525,"n":"שפירא, יעקב ברוך מלינדוב","dt":"תש","b":"רב בלינדוב"},{"i":55526,"n":"שפירא, יעקב הלוי מטרצל","dt":"תרסו - יב טבת","b":"תלמיד הדברי חיים מצאנז. רב בטערצל-תרלו."},{"i":55527,"n":"שפירא, יעקב יוסף זידא מהורודנק","f":"משה מהורודנקה","k":"בעל עצמות יוסף","bt":"תרו","dt":"תרסג","b":"רב בהורודנקא אצל ר משה תאומים. חיבר \"עצמות יוסף\" הוסיאטין תרסה. ?? לא באוצר ??"},{"i":55528,"n":"שפירא, יעקב יוסף מלונדון","f":"שמואל מרעדים","k":"בעל מילא דהספדא","b":"רב בלונדון. חתן ר חיים אליעזר אונגר מרדלוב. בנו ר אלימלך מלונדון. חיבר \"מילא דהספדא\" לונדון תרפז, ועוד."},{"i":55529,"n":"שפירא, יעקב יוסף מפמורן","b":"מחכמי פמורן, בורשטטוב-תריב, בוצאץ-תרמד."},{"i":55530,"n":"שפירא, יעקב יצחק מבלנדוב","f":"חיים מאיר יחיאל ממוג","k":"בעל אמת ליעקב","dt":"תרמב - כד סיון","dp":"וארשא","b":"אדמו\"ר בבלנדוב. מצאצאי המגיד מקוזניץ. בן השרף ממוגלניצא. חתן ר אריה ליב נייהויז מטומשוב (חלם). מתורתו ב\"אמת ליעקב\"."},{"i":55531,"n":"שפירא, יעקב יצחק מבלנדוב וארשא","f":"יוסף מנחם מפרגה","k":"אדמור מבלנדוב בוארשא","b":"מצאצאי המגיד מקוזניץ. חתן ר מנחם מנדל מדינוב. אדמור בוארשא."},{"i":55532,"n":"שפירא, יעקב יצחק מבערטש","f":"דב בער אונגר מסטרטין","b":"שינה שמו מאונגר לשפירא. נכד האדמור ר יהודה צבי לנגנר מסטרטין. אב\"ד בירטש. מאמר ממנו ב\"תצא תורה\" - קריניצה תרצא. בנו ר צבי אלימלך - עורך \"תצא תורה\"."},{"i":55533,"n":"שפירא, יעקב יצחק מגורשקוביץ","f":"אביגדור מצנסטכוב","k":"אדמור מגורשקוביץ","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. רב ואדמור בגורשקוביץ. נספה בשואה."},{"i":55534,"n":"שפירא, יעקב יצחק מלודז","f":"שלום מפשיטיק","b":"מצאצאי המגיד מקוזניץ. חתן ר צבי מרידניק (צאנז)."},{"i":55535,"n":"שפירא, יעקב ישראל מחמלניק","k":"אדמור מחמלניק וסלחוב","b":"חתן ר נחום מחירוב. אדמור מסמבור בחמלניק וסלחוב."},{"i":55536,"n":"שפירא, יעקב ישראל מסלויטה ולוב","f":"מאיר אלתר","bt":"תרמח","b":"רב בלובען-מחוז פולטובה-תרסט על מקום אביו."},{"i":55537,"n":"שפירא, יעקב כץ מקראקא","f":"יצחק מקראקא","k":"בעל באר מים חיים","b":"מחכמי קראקא-שנ, חתם על התקנה שלא לקנות הרבנות. נהרג עק\"ה. בנו - ר יוסף מזולקוא. גיסו - המהר\"ם מלובלין."},{"i":55538,"n":"שפירא, יעקב מהומנא","f":"אברהם דראניס מצאנז","dt":"תקפח - ב ניסן","b":"מצאצאי בעל ה\"מגלה עמוקות\". תלמיד ר מנחם מנדל מרימנוב, וידידו של הבני\"ש. רב בהומנא כיובל שנים, ודיין אצלו ר פישל הורביץ (שעבר לכהן אצל ה\"ישמח משה\"). חיבר ספר על מסכת כתובות וגנזו לאחר שיצא ספר \"הפלאה\". בנו ר אביש אריה על מקומו אחריו, ובנו ר אברהם אב\"ד וראנוב. תולדותיו ומתורתו יצא לאור ע\"י נכדו ר אהרן שפירא מתוך \"שופריה דיעקב\" בני ברק תשנד."},{"i":55539,"n":"שפירא, יעקב מוולוזין","f":"רפאל מוולוזין","k":"בעל גאון יעקב","bt":"תרלג-ד","bp":"וולוזין","dt":"תרצו - ט אדר","dp":"וארשא - וולוזין","b":"נכד הנצי\"ב מוולוזין. התגורר בילדותו באזארני(=נובו-אלכסנדרובסק) ושלח משם לזקנו קונטרס חדושים - בגיל 12. תלמיד ישיבת וולוזין ומקורב לגיסו ר חיים סולוביציק. רב בריבינישוק(=ריבינישיק)-פלך ויטבסק-ליד דוינסק-תרסג, ר\"מ ורב בוולוזין לצד אביו. בזמן מלחה\"ע ה-I עבר למינסק והקים שם קיבוץ תלמידים. יורש אביו כראש הישיבה בוולוזין-תרפא - תחת השלטון הקומוניסטי והצליח לפתוח את הישיבה תוך קשיים מרובים. חתנו ר שמעון לנגברט פתח בבני ברק ישיבת וולוזין והדפיס מתורת חותנו. מאמר ממנו ב\"בית מדרש\" - תל אביב תשא. מאמר לתולדותיו ב\"היהודי\" - נ\"י תרצו."},{"i":55540,"n":"שפירא, יעקב מזלוטשוב","b":"מחכמי זלוטשוב - תשובה אליו ב\"שנות חיים\"."},{"i":55541,"n":"שפירא, יעקב מטויסט","f":"שמואל הלוי מדוברומיל","bt":"תרסב","dt":"תשא","b":"רב בטויסט (ליד הרימלוב). נואם, סופר ומנגן ומחבר שירים. הספדו על אביו בתוך \"אבלת ציון\". פעיל במזרחי. נספה בשואה."},{"i":55542,"n":"שפירא, יעקב מטומשפיל","f":"יצחק אייזיק שפירא","dt":"תרנב - ב חשון","b":"רב בטאמשפיל, ויניצה(=וויניצא)-פודוליה על מקום אביו, ובנו ר יוסף על מקומו אחריו."},{"i":55543,"n":"שפירא, יעקב ממזריטש","b":"היסטוריון וחוקר. ממתנגדי החסידות, חיבר תולדות חסידות חב\"ד - ואבד."},{"i":55544,"n":"שפירא, יעקב מקוזניץ","f":"אבי עזרי זליג אלעזר","k":"אדמור מקוזניץ","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. האדמור האחרון מצאצאי המגיד שישב בקוזניץ. נספה בשואה."},{"i":55545,"n":"שפירא, יעקב משאוולי","f":"יוסף","b":"רב בשאוולי-עד תקפח."},{"i":55546,"n":"שפירא, יעקב צבי מאוסטרין","k":"בעל תפארת יעקב","b":"מצאצאי ר בנימין ראבד מהורדנא. רב באוסטרין-תרם, וחתנו ר יעקב טבשונסקי על מקומו אחריו."},{"i":55547,"n":"שפירא, יעקב קופל מחברון","f":"זאב מטיקטין","b":"מחכמי חברון-ת\"ר"},{"i":55548,"n":"שפירא, יעקב שמעון מזסלב","f":"פנחס מקוריץ","k":"אדמור מזסלב","bt":"תקלב","dt":"תקסח - יג שבט","b":"חתן ר ישכר דב בער מזסלב - תלמיד הבעשט. בנו ר אליעזר מפולנאה. אדמור בזסלב על מקום חותנו. (י\"א שנפטר תקצא)."},{"i":55549,"n":"שפירא, יעקב שמשון מסלויטה","f":"יצחק שפירא","dt":"תקסא - ג סיון","b":"דרשן,רב בסלאוויטא,שפיטובקה,אחימן,באר,עלה לטבריה"},{"i":55550,"n":"שפירא, יעקב שמשון משאץ","f":"יהודה מאיר משאץ","bt":"תרכא","dt":"תשח","b":"רב ברומן, התגורר בשאץ. חתן ר שמואל יצחק שור ממנוסטרישטש. בנו ר אברהם מטלוסט הדפיס את חדושי אביו בסוף מנחת שי - תשכו."},{"i":55551,"n":"שפירא, יצחק","f":"מהר\"מ מלובלין","b":"גדול בדורו-ש\"פ"},{"i":55552,"n":"שפירא, יצחק","f":"סנדר שפירא"},{"i":55553,"n":"שפירא, יצחק איזיק מויניצא","b":"רב בויניצא-ת\"ר"},{"i":55554,"n":"שפירא, יצחק איזיק מניו יורק","dt":"תשכה - ו אד\"ב","b":"רב בניו יורק-תרפ\"א"},{"i":55555,"n":"שפירא, יצחק אלימלך מבלוינא","b":"אב\"ד בלוינא. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":55556,"n":"שפירא, יצחק גדליה מסלאויטה","f":"פנחס מטשרני אוסטרהא","dt":"תרמג","b":"חתן ר חיים מסטנוב (זלוטשוב). רב בטשרני אוסטרהא על מקום אביו כ-18 שנה, רב בסלאויטה על מקום זקנו כ26 שנה."},{"i":55557,"n":"שפירא, יצחק דוד מאיוונציק","f":"יעקב אריה מנסכיז","bt":"תרלב-ד","dt":"תרעד - ב שבט","b":"מצאצאי אדמורי נסכיז, ר השל מקראקא, המגיד מזלוטשוב, ור פנחס מקוריץ ומצד אמו מצאצאי האדמור מללוב, אפטא. רב באיוונציק(=איוואנצק)-תרנז על מקום זקנו. חיבר ספר דרושים - בכת\"י."},{"i":55558,"n":"שפירא, יצחק הכהן כץ מקראקא","f":"דוד או יוסף","k":"חתן המהר\"ל מפרג?","dt":"שמב - יז אלול","dp":"קראקא","b":"מגדולי חכמי דורו, רב בקרמניץ, קראקא. חתנו - מהר\"ם מלובלין, בנו - ר יעקב בעל \"באר מים חיים\". מתלמידיו - ר משה מקרמניץ בעל ביאור על הסמ\"ג. (תאריך פטירתו לדעת ברי\"ל - שנז). בקריה נאמנה נרשם - חתן המהר\"ל מפרג (אך במצבת קדש מוכיח כי הדבר לא יתכן)."},{"i":55559,"n":"שפירא, יצחק זכריה ממעליץ","b":"מחכמי מעליץ - ממשתתפי \"אהל מועד\"."},{"i":55560,"n":"שפירא, יצחק יחיאל מיכל מקראקא","f":"שלמה שפירא","dt":"תכד","b":"דיין בקרקא-ת\"י,רב בפינטשוב"},{"i":55561,"n":"שפירא, יצחק מגאלאץ","f":"ירוחם פישל","k":"בעל תשורת יצחק","b":"רב בגלץ(=גאלאץ). חיבר \"תשורת יצחק\" טשרנוביץ תרצח. הקדשה ממנו - כ סיון תשג (בזמן השואה)."},{"i":55562,"n":"שפירא, יצחק מהורדניצה","f":"נח","k":"בעל ספר הזכרון","b":"נכד ר יצחק בן נטע מלובלין. תלמיד ר חיים בן שמואל מקרמניץ. רב בהורדניצה, ערזניצה, מזריטש. חיבר ספר הזכרון-תג, \"הרחבת הלב\"."},{"i":55563,"n":"שפירא, יצחק מטמשוב","b":"רב בטאמשוב-תל\"ח"},{"i":55564,"n":"שפירא, יצחק מלבוב","f":"אליעזר שפירא","k":"בעל אלף המגן","dt":"תעא - כה אדר","b":"רב בלבוב. בניו - ר נטע שהו\"ל את ספר אביו, ר אריה ליב בעל \"נחלת אריאל\"."},{"i":55565,"n":"שפירא, יצחק מלובלין","f":"נתן נטע מלובלין","k":"בעל סדר גיטין","dt":"שפג או שנו","dp":"לובלין","b":"נקרא בשם ר יצחק ר בנמש וגם - ר יצחק ר נטעש (אצל ר שמחה הכהן בעל ספר השמות). רב בלובלין. חתם על כרוז ועד ד ארצות-שי - שלא לקנות רבנות בכסף. חיבר \"סדר גיטין\" ונזכר ב\"ספר השמות\" לר שמחה רפפורט. נכדו ר יצחק בן נח בעל ספר זכרון אומר כי נהרג עק\"ה-שנו ליד העיר לוקבא אך בנוסח מצבתו נזכר - שפג וכן מספר אחיינו בעל \"מגלה עמוקות\"."},{"i":55566,"n":"שפירא, יצחק מנסכיז","f":"מרדכי מנסכיז","k":"בעל תולדות יצחק","bt":"תקמט","dt":"תרכח - כא שבט","b":"תלמיד ר ברוך ממזבוז, והחוזה מלובלין, ור לוי יצחק מברדיטשוב. חתן ר מאיר בן ר לוי יצחק מברדיטשוב, ובזיוו\"ש חתן ר יחיאל מיכל מקאשיווקא. נפטר ללא בנים. מתורתו ב\"תולדות יצחק\", ותולדותיו ב\"זכרון טוב\".","bk":[["זכרון טוב – הנהגות ותולדות",""],["תולדות \\ תולדת יצחק – עה\"ת",""]]},{"i":55567,"n":"שפירא, יצחק מסלויטה","b":"רב בסלאוויטא,שפיטובקה,אוהימן,באר-תק\"ל"},{"i":55568,"n":"שפירא, יצחק מפפד\"מ","f":"טודרוס","b":"מחכמי פפד\"מ-שכה, חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ."},{"i":55569,"n":"שפירא, יצחק מצפת","f":"צבי הירש","b":"נמנה בין העולים לצפת עם ר מנחם מנדל משקלוב, וחתם-תקעג בענין ר יוסף יעקבקא פרנקל מברסלוי."},{"i":55570,"n":"שפירא, יצחק מקובלה","f":"נתן מגרודנא","b":"ר\"מ בקובלה - בשנות ה-ש'."},{"i":55571,"n":"שפירא, יצחק מקראקא","f":"המגלה עמוקות","dt":"תט - א שבט","b":"רב בקרקא"},{"i":55572,"n":"שפירא, יצחק מרדיחוב","f":"חיים מאיר יחיאל","dt":"תרפה","b":"רב ברדיחוב על מקום אביו. חתן ר נטע ליב מגורליץ. חתנו ר אשר ישעיה רובין על מקומו ברדיחוב (מאחר שהבן חיים מאיר יחיאל היה צעיר מדי לרבנות)."},{"i":55573,"n":"שפירא, יצחק מרדכי מגוואדיץ","f":"אבי עזרי מסטרי","k":"אדמור מגוואדיץ","bt":"תרכז","bp":"סדיגורא","dt":"תרץ - ג תמוז","dp":"וינה","b":"ענכד ר חיים מאיר יחיאל ממוגלוניצא, ונכד(-אבי אמו) ר אברהם יעקב פרידמן מסדיגורא. חתן דודו - ר ישראל פרידמן מסדיגורא. אדמור בגוואדיץ על מקום אביו - יחד עם אחיו - ר חיים מאיר יחיאל מדרוהוביץ. ברח לוינה בזמן מלחה\"ע ה-I. בניו - ר ר אבי עזרא זליג אדמור מדרוהוביץ בירושלים, ר אברהם יעקב שפירא-נספה בשואה, ר דוד משה מגוואדזיץ-סדיגורא בניו יורק, ר שלום יוסף מכפר חסידים."},{"i":55574,"n":"שפירא, יצחק מרדכי מגוודיץ","f":"אבי עזרא זליג","k":"אדמור מגווזדיץ","bt":"תרכט","bp":"סדיגורא","dt":"תרץ - ג תמוז","dp":"וינה","b":"מצאצאי המגיד מקוזניץ. נכד האדמור ר אברהם יעקב מסדיגורא ואצלו נתגדל. חתן דודו ר ישראל מסדיגורא. רב ואדמור בגווזדיץ-תרמה. עבר לוינה-תרעד."},{"i":55575,"n":"שפירא, יצחק שלום מבנדין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":55576,"n":"שפירא, יצחק שלמה מסובוקוב","f":"שלום מפשיטיק","k":"אדמור מסובוקוב","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. חתן ר חיים שמואל מחנטשין (לובלין). נספה בשואה. אדמור בסובוקוב, וישב בעיקר ביענדיזוב. בנו ר שלום עלה לארץ-תרף ונרצח עק\"ה בידי ערבים."},{"i":55577,"n":"שפירא, יקו' יעקב יצחק מבלדנוב","dt":"תשג","b":"רב בבלנדוב-ווארשה"},{"i":55578,"n":"שפירא, ישכר בער מאוסטרוב","f":"יהושע איזיק-עמק יהוש","dt":"תרסב - י אדר","b":"חתן זיסל מונטליאק מנובידוואהר, ובזיוו\"ש חתן משפחת ברומברג מאוסטרוב (משפחה עשירה בראשות האישה פייגה זיסל). רב המתנגדים באוסטרוב, לצדו של ר בן ציון רבינוביץ-רבם של החסידים. נמנה על חבורת טו\"ת (שהיו עטופים טלית ותפילין במשך כל היום). עלה לירושלים-תרלו בערך וחזר לאוסטרוב בעקבות מלחמת רוסיה ותורכיה. חיבר ספר בגימטריות - הספר אבד. מתורתו בספר אביו \"עמק יהושע\" שהו\"ל אחיו - ר משה-תרנו. בנו - יחיאל."},{"i":55579,"n":"שפירא, ישכר בער מועריש","f":"חיים מאיר יחיאל","b":"בנו של הרב ברדיחוב. רב בועריש, ובנו ר משה רב שם - נספה בשואה."},{"i":55580,"n":"שפירא, ישכר בער מקעכניא","f":"פנחס מקעכניא הי\"ד","k":"אדמור מקעכניא בארה\"ב","bt":"תרס","bp":"קעכניא","b":"חתן דודו ר מאיר איתמר רוזנבוים מטשרנוביץ-האדמור מנדבורנא. אדמור בנאויסעליץ-בסרביה, עלה לירושלים-תרצה, עבר לארה\"ב וכיהן כאדמו\"ר מקעכניא בניו יורק."},{"i":55581,"n":"שפירא, ישכר בר אביגדור מטרווא","b":"חתן ר מנחם מנדל מלנסק"},{"i":55582,"n":"שפירא, ישכר דב בר מזסלב","f":"יעקב שמעון מזסלב","b":"חתן דודו ר יוסף יוסקא משפיטיבקה. רב ואדמור בזסלב על מקום אביו. בנו ר פנחס יוסף דכנר (שינה שמו) רב בדלטין."},{"i":55583,"n":"שפירא, ישכר מפינסק","f":"נתן מגרודנא","b":"ר\"מ בפינסק, וורמייזא-שסג."},{"i":55584,"n":"שפירא, ישעיה כץ מלבוב","b":"ראב\"ד בלבוב, חתם-תנא."},{"i":55585,"n":"שפירא, ישעיה מאיר מצורטקוב","b":"רב בצורטקוב-תר\"ע"},{"i":55586,"n":"שפירא, ישעיה מכפר חסידים","f":"אלימלך מגרדינסק","k":"האדמור החלוץ","bt":"תרנה","dt":"תשה","b":"חסיד,חלוץ עלה לארץ-תרפו, פעיל בישוב א\"י בכפר חסידים והתישב בכפר פינס. האחיו האדמו\"ר מפיאסצנה בעל \"חובת התלמידים\". גיסו - האדמו\"ר ר חנוך בורשטין מסוכצ'וב."},{"i":55587,"n":"שפירא, ישעיה מלודז","f":"יעקב יצחק מבלנדוב","k":"אדמור מגריצא ולודז'","dt":"תרעז - טו אדר","b":"מצאצאי המגיד מקוזניץ."},{"i":55588,"n":"שפירא, ישעיה נפתלי הרץ מדוקלא","f":"נחמיה מסטריזוב","dt":"תש..","b":"חתן ר מנחם מנדל הלפרין מדוקלא וכיהן שם כרב. נספה בשואה."},{"i":55589,"n":"שפירא, ישעיה נפתלי הרץ מדינוב","f":"דוד מדינוב","k":"אדמור מדינוב - רינ\"ה","r":"אדמו\"ר מקאמרנא","bt":"תקצח","dt":"תרמה - ד סיון","b":"נכד הבני\"ש. חתן דודו ר אלעזר מלנצהוט, רב ואדמור בדינוב-תרלד על מקום אביו. חתנו ר יוסף שפירא על מקומו אחריו. חיבר \"הנותן אמרי שפרא\" פרמישלא תרמח\".","bk":[["הנותן אמרי שפר",""],["הנותן אמרי שפר (דינוב)",""]]},{"i":55590,"n":"שפירא, ישראל איסר מיפו","f":"רפאל מוולוזין","bt":"תרמז","bp":"ברויסק","dt":"תשלא - ח טבת","b":"אב\"ד לאפיץ(=לאפטש)-תרעז, עלה לארץ-תרץ. ר\"מ בישיבת \"שערי תורה\" ביפו-תשז (אולי עם אחיו - ר אריה ליב), העביר את הישיבה לתל אביב-תשח."},{"i":55591,"n":"שפירא, ישראל איסר ממזריטש","k":"בעל עזרת ישראל","dp":"מזריטש","b":"רב באוגוסטוב, מזריטש-תרמ. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה תרנג, \"מכילתא דרבנן\" - אודסה תרמו, \"תורה מציון\" - ירושלים תרנה-תרסה. מתלמידיו - ר מאיר הלפרין מחבר \"הגדול ממינסק\"."},{"i":55592,"n":"שפירא, ישראל אלעזר מקוזניץ","f":"ירחמיאל משה מקוזניץ","k":"בעל עבודת אלעזר","dt":"תשכו - כט אב","dp":"ירושלים","b":"מצאצאי המגיד מקוזניץ. חתן ר מרדכי יוסף מזלאטיפולא (טשרנוביל). הקים \"אגודת עבודת ישראל\", עלה לארץ והיה ממיסדי כפר חסידים וכפר אתא. יצא לצרכי ריפוי לפאריז, ניצה וארה\"ב. עלה לארץ-תשכה."},{"i":55593,"n":"שפירא, ישראל דרשן מקליש","f":"נתן מלובלין","k":"בעל זרע ישראל","b":"חתן ר ישראל איסר לוריא - נכד המהרש\"ל. רב בקאליש-תל. חיבר הקדמה ל\"עמודי שבעה\" לר אהרן זליג מזולקווא. הסכים על \"לב ארי\", \"מגן אברהם\" - דירנפורט."},{"i":55594,"n":"שפירא, ישראל חיים מברטש","f":"מרדכי מברטש","dt":"תשב","b":"חסיד סדיגורא. רב בברטש על מקום אביו, וגבאי א\"י שם-תרץ. חתן רמי\"ל שפירא מסטריזוב. נספה בשואה."},{"i":55595,"n":"שפירא, ישראל יהודה","b":"תשובה אליו - \"בית דוד\"-תרסט."},{"i":55596,"n":"שפירא, ישראל יעקב מבוסק","b":"מחכמי בוסק, אחיין ר שלמה קלוגר - תשובה אליו ב\"חדושי אנשי שם\" - לנכד אחי."},{"i":55597,"n":"שפירא, ישראל יששכר מוורמייזא","f":"נתן שפירא","b":"רב בוורמייזא"},{"i":55598,"n":"שפירא, ישראל מארה\"ב","f":"טוביה פסח - ט\"ף","k":"בעל אוצר תרגומים","bt":"1882","bp":"סייני","dt":"1957","b":"תלמיד ישיבת טלז. למד באוני' ברלין ושטרסבורג, וביהמ\"ד לחכמת ישראל בברלין. מורה בביהמ\"ד למורים בירושלים, היגר לארה\"ב-1910 וערך את \"הדור\" עם ר. בריינין. חיבר מחקרים בספרות עברית. ראש המחלקה השמית בספריית הקונגרס בוושינגטון, ופרו' באוני' שם. חיבר גם \"פירוש המשניות לרמב\"ם\" - מהדורה מדעית, ועוד."},{"i":55599,"n":"שפירא, ישראל מבלוזוב","f":"יהושע מריבטיטש","k":"אדמור מבלוזוב","bt":"תרן","bp":"רישא","dt":"תשן - א חשון","b":"חתן ר שלום דב אונגר מזבנא ובזיוו\"ש חתן ר משה מנחם מלכיור מרדומסק. רב בפרוכניק, ולאחר פטירת אביו ויתר על רבנות אביו בבלוזוב לטובת אחיו והתישב באיסטריק-תרצב שם כיהן כאדמור מבלוזוב. הביא לדפוס ספר זקנו \"צבי לצדיק\" - תרצו - עם הערותיו. ניצל מהשואה. כיהן כרב בגריידינג-תשב (בהוראת הנאצים), ברח ממחנה בלזיץ והציל אתו את הילד שרגא פיבל פרלברגר מויליצקה. לאחר השואה עבר לבריסל, ולארה\"ב וכיהן כרב בניו יורק, וכל ימיו דיבר על השואה ולא הסיח דעתו ממנה. בנו חורגו ר צבי יהודה על מקומו אחריו. חיבר הגהות על \"צבי לצדיק\" לזקנו ר צבי אלימלך מבלוזוב."},{"i":55600,"n":"שפירא, ישראל מגרודזינסק","f":"חיים מאיר יחיאל","k":"בעל אמונת ישראל","bt":"תרלד","bp":"גרודזיסק","dt":"תשב - אלול","dp":"טרבלינקה","b":"מצאצאי המגיד מקוזניץ. תלמיד זקניו ר אלימלך מגרודזיסק והאדמור מבוהוש - מצד אמו. חתן ר אשר פרלוב מקרלין. רב בגרודזינסק, וארשא. נספה בשואה. חיבר \"אמונת ישראל\", ו\"בינת ישראל\"."},{"i":55601,"n":"שפירא, ישראל מיגלוניצה","f":"צבי שפירא","b":"רב ביאגלניצא"},{"i":55602,"n":"שפירא, ישראל מניו יורק","f":"יהושע שפירא","b":"אדמור בארה\"ב"},{"i":55603,"n":"שפירא, ישראל מסכויטוב","f":"יעקב אריה מקאוולי","dt":"תרמא - ד תמוז","b":"נכד האדמור ר מרדכי שפירא מנסכיז. חתן ר יחיאל מיכל מווישנוביץ (זלוטשוב). רב ואדמור בסטביכוב."},{"i":55604,"n":"שפירא, ישראל מפשיטיק","dt":"תשג","b":"חתן ר שלום שפירא מפשיטיק. רב בפשיטיק"},{"i":55605,"n":"שפירא, ישראל ראה דכנר","f":"פנחס יוסף שפירא דכנר","b":"רב ברוסיה"},{"i":55606,"n":"שפירא, לוי יצחק מבוקרשט","b":"רב בבוקרשט-תרלד."},{"i":55607,"n":"שפירא, לוי יצחק מקאמין","f":"יעקב אריה מקאוולי","k":"אדמור מנסכיז קאמין","b":"רב בקאמין-תר. נכד האדמור ר מרדכי שפירא מנסכיז. חתן דודו ר יוסף קצנלנבוגן מאוסטילא."},{"i":55608,"n":"שפירא, לוי מטריסק","f":"אריה ליב מקובנא","k":"בעל בית לוי","dt":"תרם","b":"נקרא \"העילוי מדוקשט\". רב בטריסק(=טרישקי), אז'רני=נובו אלכסנדרובסק-תרלד."},{"i":55609,"n":"שפירא, ליבוש מפשיטיק","dt":"תשג","b":"רב בפשיטיק,לובלין"},{"i":55610,"n":"שפירא, לייב מטלז","f":"אברהם מטלז","b":"רב בטלז על מקום אביו, ור שמואל שפירא בעל \"מעיל שמואל\" על מקומו אחריו."},{"i":55611,"n":"שפירא, לייבל מיאנוב","b":"רב ביאנוב-תקף. תלמיד ר ישעיה מיאנוב-דינוביץ. צדיק מפורסם וצאצאיו כיהנו כרבני העיר האלאסקאוו-פודוליה."},{"i":55612,"n":"שפירא, לצרוס מפרשבורג","b":"מראשי קהלת פרשבורג-תף, בזמן הראב\"ד ר זאב יאקרלס."},{"i":55613,"n":"שפירא, מאדיל מפוטיק","b":"מחכמי פוטיק - תשובה אליו \"דבר משה\"."},{"i":55614,"n":"שפירא, מאיר","f":"ברצי שפירא","b":"רב-שנת תר\"ל"},{"i":55615,"n":"שפירא, מאיר אלתר הלוי מלובן","dt":"תרסט - בערך","b":"רב בלובען-מחוז פולטובה-תרמה, ובנו ר יעקב ישראל על מקומו אחריו-תרסט."},{"i":55616,"n":"שפירא, מאיר יהודה מבוקובסק","f":"דוד מדינוב","k":"אדמור מבוקובסק","bt":"תרו","dt":"תרסט - יט תשרי","b":"נכד הבני\"ש. חתן ר יוסף אלתר הגר מרדיויץ, ובזיוו\"ש חתן ר ישראל (חתן ר\"ח מקוסוב). רב במדזילברץ על מקום דודו ר משה שנפלד (עד שיגדל בנו ר צבי אלימלך). רב ואדמור בבוקובסק. בנו ר דוד על מקומו אחריו. חסידיו בטחו בו במיוחד - רשם להם תרופות ונתנו לו את דמי הביטוח (כי בטחו בזכותו שלא יארע להם רע). חיבר \"אור למאיר\" פשעמישל תרעג."},{"i":55617,"n":"שפירא, מאיר מארץ ישראל","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":55618,"n":"שפירא, מאיר מבלוזוב","f":"יהושע מריבטיטש","k":"אדמור מבלוזוב","dt":"תשב","b":"רב בבלוזוב ומתרצב גם אדמור. חתן דודו ר יוסף שפירא, וגיסו (בעל אחותה) האדמור מקלויזנבורג. נספה בשואה, הפקיד אצל שכן גוי את כתבי זקנו ר צבי אלימלך מבלוזוב - פדאום אחרי המלחמה - ונדפסו בניו יורק בשם \"צבי לצדיק\" ובסופם \"זכרון מאיר\" מחדושיו. חיבר \"זכרון מאיר\" ירושלים תשנט."},{"i":55619,"n":"שפירא, מאיר מהורודנקה","b":"רב בהורודנקה, בנו ר משה מזלוטשוב על מקומו אחריו. מובא ב\"קהלות יעקב\"-תקט."},{"i":55620,"n":"שפירא, מאיר מזברז","b":"רב בזברז-תרס."},{"i":55621,"n":"שפירא, מאיר מפיעטרקוב","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":55622,"n":"שפירא, מאיר משלם מלנצהוט","f":"שמואל מדינוב","dt":"תרף","b":"נכד ר צבי אלימלך מדינוב, לאחר שנתייתם גדל אצל דודיו ר דוד ורינ\"ה. חתן ר פסח אייזנברג מאולינוב. התיישב בלנצהוט שם כיהן דודו כאדמור והתידד עם ר שמחה מלמד שנחשב לאחד מל\"ו צדיקים. עסק בהדפסת ספרי זקנו הבני\"ש וההדיר מכתבי יד שונים והדפיסם ביניהם \"אגרא דכלה\" ועוד. נכדו היה האדמור מקלויזנבורג."},{"i":55623,"n":"שפירא, מנדל מקלבסוב","dt":"תשג","b":"רב בקלבסוב"},{"i":55624,"n":"שפירא, מנחם זונדל מאיליא","f":"אריה ליב מקובנא","b":"נכד ר מנחם זונדל מליובאויטש-חתן ר אליעזר מלובטש. רב באילייה(=איליא). (אחד משישה אחים - כלם רבנים). בנו - ר חיים יעקב מקובנא (גדל אצל זקנו לאחר פטירת אביו)."},{"i":55625,"n":"שפירא, מנחם מנדל מדינוב","f":"דוד האדמור מדינוב","bt":"תרנח","dt":"תשב","b":"חתן ר יצחק ליפשיץ מטשרני. רב בדינוב-תרצג. נספה בשואה."},{"i":55626,"n":"שפירא, מנחם מנדל מדרוגמרש","f":"משה ישעיה מעטשעד","k":"בעל מאזני צדק-תרעב","bt":"תרכג","bp":"קלינורדין","dt":"תש - כט ניסן","b":"תלמיד זקנו ר אברהם יצחק וינברגר מקליינורדין, ובעל \"ייטב לב\" בסיגט. חתן הגביר ר יוסף מרדכי כהנא מדרגמירשט, ועבר לשם. רב גליל דגאגמירטש-תרעא. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא תרע, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":55627,"n":"שפירא, מנחם מנדל מיגולניצה","f":"משלם פייביש","bt":"תרלג","dt":"תשב","b":"רב ביגולניצה-תרנד על מקום אביו, רב בהורודנקה-תרסג. חסיד צורטקוב. חתן הגביר ר נחמן צבי זיידא רוזן מיגולניצה."},{"i":55628,"n":"שפירא, מנחם מנדל פנחס מלנצהוט","f":"אלעזר מלנצהוט","dt":"תרע","b":"רב בלנצהוט-תרנט על מקום אביו (לאחר מחלוקת עם אחיו). חסיד של אחיו - ר שלמה ממונקטש."},{"i":55629,"n":"שפירא, מנחם מנדל ראה דכנר","f":"פנחס יוסף שפירא דכנר","bt":"תריג","dt":"תרפד - יח חשון","b":"חתן ר טוביה ליפשיץ מבריגל. רב בבערהאמעט-בוקובינה - תרמד."},{"i":55630,"n":"שפירא, מנחם משאט (אולי נחום?)","k":"העילוי מדאקשיץ","b":"רב בשאט-תר\"מ"},{"i":55631,"n":"שפירא, מרדכי","f":"משה שפירא","b":"מחכמי וילנא, וולוזין, רב בגלוסק, גלובקי. בנו - ר יחיאל מגלובקי ונכדו - ר איזל חריף בעל \"עמק יהושע\". (עליו בהקדמת נינו ר משה שפירא בספרו \"ברכת משה\")."},{"i":55632,"n":"שפירא, מרדכי ז\"ק מקולומיאה","b":"חתן ר דוד רייז מקולומיאה. וכיהן כרב שם."},{"i":55633,"n":"שפירא, מרדכי מבורדוזן","f":"פנחס","bt":"תרך-כב","b":"תלמיד ר יהושע פאלק מפאלטשן. רב בבורדוזן(=בארדזען)-רומניה-תרנב."},{"i":55634,"n":"שפירא, מרדכי מברטש","f":"צבי אלימלך מברטש","bt":"תרל","dt":"תשד - ג סיון","b":"רב בברטש-תרע על מקום אביו. חתן ר אברהם שמחה הורביץ מברנוב. עוד מבניו ר ישראל חיים על מקומו אחריו, בנו ר אלעזר רב בקיויאשד, ר משה ור שלמה. מתורתו ב\"מצבת אבן\" הביא לדפוס נכדו ר זלמן ליב איכנשטין - תשנד (נדפס כמזכרת בשמחת נשואי צבי אלימלך רוקח עם שרה טויב ממודזיץ)."},{"i":55635,"n":"שפירא, מרדכי מגלובקי","b":"רב בגלובאקי,הלוסק"},{"i":55636,"n":"שפירא, מרדכי מנסכיז ולעשנוב","f":"דב בר מטולטשין","k":"אדמור מנסכיז","bt":"תקב-ח","bp":"נשכיז","dt":"תקס - ח ניסן","b":"תלמיד ר יחיאל מיכל המגיד מזלוטשוב. חתן ר יוסף קצנלנבוגן מלעשנוב. רב בלעשנוב, קובל(=קאוולי), לודמיר, נסכיז-תקמט וכיהן שם כאדמור. מתורתו ב\"רשפי אש\" ובסופו לקוטי שבחי מוהר\"מ מאת רנ\"נ הכהן דונר. מבניו: ר יוסף קצנלנבוגן מאוסטילא.","bk":[["רשפי אש",""]]},{"i":55637,"n":"שפירא, מרדכי מסטביחוב","f":"ישראל מסטביחוב","dt":"תרמה - כו תמוז","b":"מצאצי ר יצחק מנסכיז. חתן ר שמואל יחיאל מבוטשאן (זלוטשוב)."},{"i":55638,"n":"שפירא, מרדכי מפיסצניא","f":"צבי","bp":"פולין","dt":"תרנב","dp":"ירושלים","b":"רב בפיסעצני וטארנוגורד, עלה לירושלים."},{"i":55639,"n":"שפירא, מרדכי מקולנקוביץ","f":"שלמה","bt":"תרלב","b":"תלמיד ישיבת וולוזין. רב בקולנקוביץ(=קאלענקאוויץ)-פלך מינסק-תרסה על מקום אביו. נסמך מאת: ר רפאל שפירא מוולוזין, ואחיו ר שמואל משה מבוברויסק."},{"i":55640,"n":"שפירא, מרדכי מקוריץ","f":"פנחס מקוריץ","b":"רב בקוריץ,דובנקי-תק\"פ"},{"i":55641,"n":"שפירא, מרדכי מקמינקא","f":"שלמה דב מברשיבקא","dt":"תשז - א סיון","b":"חתן ר שלום יוסף מקרוסנא. רב בברשיבקא על מקום אביו, עבר לקמינקא. היגר לארה\"ב-תרפג, וכיהן כאדמו\"ר מקמינקא-קוריץ בארה\"ב."},{"i":55642,"n":"שפירא, מרדכי משפיטיבקה","f":"משה מסלאויטא","k":"אדמור משפיטובקא","dt":"תרכז-ט -כז ניסן","dp":"שפיטובקא","b":"תאומו של ר פנחס. חתן ר יהושע אלעזר מברדיטשוב (אבי משפחת חודורוב)."},{"i":55643,"n":"שפירא, מרדכי צבי מבוברקא","f":"יוסף אביגדור","bt":"תקץ","dt":"תרך","b":"אביו שהגיע מליטא - שינה שם משפחתו למאנטל (כדי שלא יוסגר לרוסים). רב בבוברקא וויתר לטובת גיסו רח\"ש ויטלש."},{"i":55644,"n":"שפירא, משה אריה ליב מירושלים","b":"ר\"מ בישיבת \"תורת אמת\" בירושלים. פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפו, \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":55645,"n":"שפירא, משה דוד מאברטין","b":"מלמד באברטין - תשובה אליו - סת\"ם."},{"i":55646,"n":"שפירא, משה דוד מבוהוש","f":"שבתי מפשמישל","dt":"תרן","b":"רב בבוהוש, דורוהוי, גלעץ-תרכה. נחשב לראש הדרשנים ברומניה. בנו ר ישעיה נועד לשבת על כסאו אחריו. חתנו - ר שלמה מעהר מבראילוב."},{"i":55647,"n":"שפירא, משה חיים","f":"זלמן","bt":"1902","bp":"גרודנא","b":"תלמיד ביהמ\"ד לרבנים בברלין. ארגן קבוצה של צעירי \"מזרחי\" והיו גרעין לתנועת הנוער הדתי לאומי בליטא. מורה בביה\"ס אחיעזר בוילנא, ופעיל בעליית חלוצים דתיים לארץ. ציר בקונגרס הציוני. עלה לארץ-1925 והיה מראשי תנועת \"המזרחי\". שר בממשלת ישראל. פרסם מאמרים שונים."},{"i":55648,"n":"שפירא, משה יהודה ליב מבייטש","f":"שלמה מסטריזוב מונקטש","bt":"תרי-יג","dt":"תרעז - ב חשון","dp":"וינה","b":"חתן ר ברוך הלברשטם מגורליץ. חסיד הדברי חיים - חותנו זקנו - וישב אצלו חמש שנים, רב בביייטש(=ביעטש), סאסוב על מקום זקנו (ועזב בגלל מחלוקת), רב בסטריזוב (והיה מחלוקת עם הרב אלתר זאב הורביץ משנדישוב - רבני גליציה תמכו בר אלתר בעוד רבני הונגריה תמכו בר משה - ועל כך ב\"בית יצחק ו\"מנחת אלעזר\" ועוד). ציווה שלא להדפיס את כתביו. בנו ר נחמיה על מקומו אחריו בסאסוב ובסטריזוב."},{"i":55649,"n":"שפירא, משה יהודה מזלוטשוב","b":"מחכמי זלוטשוב - תשובה אליו במהרש\"ם."},{"i":55650,"n":"שפירא, משה יוסף הכהן מטריטש","f":"אברהם מטריטש","b":"דיין בטריטש אצל ר לוי פולק. הו\"ל ספר החינוך - ברין תקנח, עם הסכמה מר לוי פולק."},{"i":55651,"n":"שפירא, משה יוסף מגריצא","f":"חיים מאיר יחיאל ממוג","dt":"תרמח","b":"מצאצאי המגיד מקוזניץ. רב בגריצא-תרל."},{"i":55652,"n":"שפירא, משה יצחק","b":"רב-שנת תק\"ל"},{"i":55653,"n":"שפירא, משה יצחק מבומסלא","f":"אהרן יחיאל מיכל","k":"בעל באר לחי רואי","dt":"תקז - יז טבת","b":"חתן ר מרדכי הכהן מאה\"ו. מגדולי חכמי דורו,רב בבומסלא,פרג-תצ\"ז. חתנו - ר יונתן איבשיץ,"},{"i":55654,"n":"שפירא, משה יצחק מטבריה","f":"אורי","b":"מותיקי החסידים בארץ - אביו עלה בשנת תקכד. חתן ר\"ש סגל (ר שמואל סגל מפלאצק?). חתם על אגרות שליחות בשנים תקמט-תקנה."},{"i":55655,"n":"שפירא, משה ישראל הכהן מניו יור","b":"רב קהלת פועלי צדק אנשי וילנא בניו יורק, ראש ישיבת רבי יצחק אלחנן בניו יורק."},{"i":55656,"n":"שפירא, משה מארה\"ב","f":"בן ציון מירושלים","bp":"ירושלים","b":"נכד ר יהושע צבי מיכל מירושלים. רב באטלנטיק-ארה\"ב."},{"i":55657,"n":"שפירא, משה מאשכנז","k":"בעל תוספות טוך","b":"מגדולי הראשונים,ממחברי תוספות טוך-ד'תתק\"פ"},{"i":55658,"n":"שפירא, משה מבלנדוב-ביאלא","f":"יעקב יצחק מבלנדוב","k":"אדמור מבלנדוב-ביאלא","dt":"תרפז - יז אב","b":"מצאצאי המגיד מקוזניץ. חתן דודו ר אלימלך מגרודזיסק. רב בגראווילין, בלנדוב-ביאלא."},{"i":55659,"n":"שפירא, משה מגרוזד","f":"ישעיהו רפאל","b":"רב בגרוזד-ליטא."},{"i":55660,"n":"שפירא, משה מדוברומיל","b":"רב בדוברומיל - תשובה אליו מהרש\"ם."},{"i":55661,"n":"שפירא, משה מהוסיאטין","b":"מחכמי הוסיאטין - פרסם ב\"ועד חכמים\"."},{"i":55662,"n":"שפירא, משה מהורודנקה","f":"שמואל זאב מיגולניצה","b":"רב בהורודנקה, בנו ר יעקב יוסף זידא על מקומו אחריו."},{"i":55663,"n":"שפירא, משה מואקשנה-ליטא","b":"רב בואקשנה על מקום ר יקותיאל זלמן-אחרי תרח."},{"i":55664,"n":"שפירא, משה מוילנא","f":"נתן - המגלה עמוקות","b":"חתן הגביר ר ליזר ש\"ץ מוילנא. מקובל, דיין בוילנא, רב בהורדנא-שנת ת'. חיבר הקדמה לספר אביו מגלה עמוקות על ואתחנן."},{"i":55665,"n":"שפירא, משה מוילקומיר","f":"יהושע איזיק-עמק יהוש","k":"בעל פני משה","bt":"תקצה","bp":"קאלוואריה","dt":"תרעא - ד טבת","b":"חתן ר יוסף יפה מואקשנה. רב בואקשנה, וילקומיר, ריגה-תרמב. חיבר גם \"ברכת משה\", \"דרשות מהר\"מ\", ועוד. עסק בצרכי ציבור. הו\"ל ספר אביו - \"עמק יהושע\"-תרנו עם פירוש ממנו בשם \"שפת העמק\", ועם הוספות מאחיו ר ישכר בעריש. בניו - ר שבתי אהרן מגורזיד, ר יחיאל יוסף, ישראל (שהיה צייר), חתניו - ר שלום מנדל אווין על מקומו אחריו בריגה, אליעזר חנוך קולפניצקי מוילנא."},{"i":55666,"n":"שפירא, משה מוירונה","b":"מגדולי חכמי איטליה בוירונה-שנת ר',הגן בעוז על אנוסי ספרד ופורטוגל"},{"i":55667,"n":"שפירא, משה מזלטופול","f":"פנחס בן מרדכי","bt":"תרי","b":"מצאצאי ר משה מסלויטא, ור פנחס מקוריץ. רב בזלאטופול(=זלאטאפאליע)-תרם. בנו - ר זאב דוד. חתנו - ר אברהם בן שמואל רבינוביץ מקראסנע."},{"i":55668,"n":"שפירא, משה מירושלים","dt":"תקי - כה אייר","dp":"אזמיר","b":"מחכמי ארץ ישראל, בשליחות בצפון אפריקה יחד עם ר יצחק פרגי, נפטר בשובו משליחותו באזמיר."},{"i":55669,"n":"שפירא, משה מירושלים","b":"מראשי כולל וארשא בירושלים-תרסא."},{"i":55670,"n":"שפירא, משה מישל שמואל מרגוזה","f":"יוסף בן שאול","k":"בעל הארות השמש","bt":"תרטו","dt":"תרצג - אחרי","b":"נכד ר שאול מפוניבז בעל \"חמדת שאול\", ונכד ר מנחם מנדל מקרטינגען. חתן ר מרדכי רבינוביץ מראגאווא ופוסוואל. רב בפוניבז-תרלט, זופרן-פלך וילנא-תרמב, ראגובה(=ראגאווא)-פלך קובנא-תרמה - עד תרצג. חיבר גם \"שכיות החמדה\", \"תולדות משפחת שפירא\", ועוד. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. תשובות ממנו ב\"שדי חמד\", ובקובץ \"יגדיל תורה\", ועוד. חתניו: ר בנימין משובאט, ר אליהו סובול מטאוויאן, ר חיים פדרובסקי."},{"i":55671,"n":"שפירא, משה ממינסק","dt":"תשג","b":"רב במינסק"},{"i":55672,"n":"שפירא, משה ממירוסלאוו","b":"רב במירוסלאוו-ליטא."},{"i":55673,"n":"שפירא, משה מסלאויטה","f":"פנחס מקוריץ","bt":"תקכב","dt":"תר - ט כסלו","b":"חתן ר יצחק הדיין מפולנאה, וגיסו של ר גדליה מליניץ. רב בסלאויטה ומיסד דפוס סלאויטה. נאשם בעלילת דם-תקצו."},{"i":55674,"n":"שפירא, משה מסלובודקא","f":"יהואש הייבוש","bt":"תרכה","dt":"תרצ","b":"רב בסלובודקא-פלך סובאלק-תרן, ז'אזמיר(=זעזמר)-תרנז-תרץ."},{"i":55675,"n":"שפירא, משה מקרוז","f":"אברהם מטלז","b":"אב\"ד בירז. אחיו - ר שמעון מבירז, ר שמואל מפוניבז וטלז, ר צמח מקידאן."},{"i":55676,"n":"שפירא, משה מראגובה","dt":"תשג","b":"רבה האחרון של ראגאווע(=ראגובה) - (ב\"יהדות ליטא\" - הרב האחרון ר ישראל מל)."},{"i":55677,"n":"שפירא, משה מריגא","f":"אייזיק חריף","b":"רב בריגא-תר\"ס"},{"i":55678,"n":"שפירא, משה נתן נטע מאלמאשד","f":"אהרן יוסף מאונסודרף","dt":"תקצב-ג - ו אב","dp":"אלמאשד","b":"מצאצאי בעל מגלה עמוקות. תלמיד ר יצחק משה פערילס מבאניהאד. חתן ר אשר אנשל וינר ממישקולץ. רב באלמאשד-תקסג, טאקאי. נזכר בשו\"ת החת\"ס. הסכים על \"בית יצחק\". נכדו - ר ישראל אפרים פישל סופר מנאנאש."},{"i":55679,"n":"שפירא, משה נתנאל ממינסק","dt":"תשג","b":"רב במינסק"},{"i":55680,"n":"שפירא, משה שמואל מבאר יעקב","f":"אריה בן בעלתורת רפאל","b":"חתן ר אהרן וינשטין בעל \"דרכי אהרן\". ראש ישיבת באר יעקב-תשט. פרסם מאמרים ב\"שמוש חכמים\" - בני ברק תשז."},{"i":55681,"n":"שפירא, משה שמואל מניו יורק","k":"בעל תולדות ר חיים","bt":"תרמ","bp":"וולוזין","dt":"תשכג","dp":"ניו יורק","b":"תלמיד ישיבת וולוזין, קיבוץ פוניבז. רב בלאסיאד. היגר לארה\"ב וכיהן כר\"מ בישיבת ר חיים ברלין בניו יורק כ-25 שנה. פרסם מאמרים על גדולי התורה. חיבר \"תולדות ר חיים מוולוזין\". עליו ומתורתו ב\"ר משה שמואל ודורו\". פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח, \"המסלה\" - נ\"י תרצו."},{"i":55682,"n":"שפירא, משלם זושא מדינוב","f":"צבי אלימלך שפירא","b":"רב בדינוב-תר\"כ"},{"i":55683,"n":"שפירא, משלם פיבוש מיגלניצה","f":"צבי שפירא","dt":"תרנד","b":"רב ביגלניצא"},{"i":55684,"n":"שפירא, נח","f":"אברהם דובער","bt":"1900","bp":"סמולוביץ","dt":"1964","dp":"תל אביב","b":"למד כימיה באונ' ברלין. מרצה לכימיה באונ' קובנא. מנהל הגימנסיה העברית במאריאמפול. עלה לארץ-1935 ועסק בהוראה. חיבר מאמרים בנושאי מדע ועל חלקם של היהודים בהתפתחות המדעים."},{"i":55685,"n":"שפירא, נח חיים אברהם מסמרגון","f":"אריה ליב מקובנא","bt":"תקפא","dt":"תרמד - ד אייר","b":"רב בסמרגון על מקום אביו כ-32 שנה, עשיר ובעל צדקה. חתניו - ר מאיר בן יוסף מסלוצק, ר מנשה יוסף מסמרגון, ר גרשון תנחום מיאשינקוב. אחיו - ר רפאל מוולוזין, ר לוי מנובו אלכסנדרובסק, ועוד."},{"i":55686,"n":"שפירא, נחום משאט","k":"העילוי מדוקשיץ","bt":"תקעח","bp":"דוקשביץ-פלך מינסק","dt":"תרסב","dp":"שאט","b":"תלמיד ישיבת מינסק, מאברכי הכולל בקובנא ומקורב לר ישראל סלנטר בקובנא. רב בפוקרוי, ליגום, אגאר(=ואגר), טרישקי, שאט-תרנ. הניח כת\"י רבים. היה שותף בספר \"אור ישראל\" לתולדות ר ישראל סלנטר - כאשר חלק גדול מהשמועות והמעשים הגיעו ממנו. חתנו ר יוסף זונדל רבינזון."},{"i":55687,"n":"שפירא, נחמיה מסאסוב","bt":"תקכ","dt":"תרי - ג כסלו","b":"רב בסאסוב"},{"i":55688,"n":"שפירא, נחמיה מסאסוב","f":"משה יהודה מסאסוב","k":"אדמור מסטריזוב","bt":"תרלד","dt":"תשב","dp":"סטריזוב-רישא","b":"חתן ר ישעיה נפתלי הירץ מדינוב. תלמיד דודו בעל \"דרכי תשובה\" ממונקטש. רב בסאסוב על מקום אביו שעבר לסטריזוב, וינה, סטריזוב על מקום אביו (והיה מחלוקת עם ר קלמן הורביץ בן הרב הקודם). נספה בשואה בדרך בין סטריזוב לרישא. הו\"ל \"חדושי הרמ\"ל\" לזקנו ר משה יהודה מסאסוב, עם הערות ממנו."},{"i":55689,"n":"שפירא, נחמיה מסטריזוב","f":"משה ליב מסטריזוב","dt":"תשג","b":"רב בסטריזשוב-תרע\"ז"},{"i":55690,"n":"שפירא, ניסן מוילקובישק","b":"רב בווילקובישק"},{"i":55691,"n":"שפירא, נפתלי","f":"אבי עזרי זליג אלעזר","b":"מצאצאי המגיד מקוזניץ. סירב לאדמורות, והתישב בוארשא, והיה גבאי צדקה לעניים, ורבים בקשו את ברכתו."},{"i":55692,"n":"שפירא, נתן מבריסק","f":"משה","dt":"תרלה - כו אלול","dp":"בריסק","b":"דיין בבריסק-תקצה"},{"i":55693,"n":"שפירא, נתן מפוזנא","f":"פרץ","b":"רב בפוזנא-ר\"ס"},{"i":55694,"n":"שפירא, נתן מפילץ","f":"ברוך מטשיזעוו","b":"חתן ר ליב הירשברג מפילץ. רב בפילץ."},{"i":55695,"n":"שפירא, נתן מצצנוביץ וטאקאי","k":"בעל טללי שנה","dt":"תרה","b":"אב\"ד צצנוביץ-הונגריה, טאקאי, משצעצוויל."},{"i":55696,"n":"שפירא, נתן מקראקא","f":"שלמה בן נתן","k":"בעל מגלה עמוקות","bt":"שמה","dt":"שצג - יג אב","b":"חתן ר משה ר יעקליש מקראקא (שהיה מחותנו של ר אברהם רפפורט בעל איתן האזרחי). עשיר, מקובל, מגדולי חכמי דורו, ראש ישיבה בקראקא-שעז על מקום ר משה מרדכי מרגליות. מבניו: ר יצחק מלובלין בעל \"סדר גיטין\", ר שלמה מסאטנוב, ר משה. חתניו - ר מנחם מנדל בן בנימין מקראקא, ר ישראל הלפרין, ר ישעיה מהילדסהיים, ר בנימין, ר אברהם לבוב, ר צבי בן חיים שור, ר אברהם ז\"ק מבאר (בזיוו\"ש).","bk":[["מגלה עמוקות",""]],"e":"שמ\"ה-שצ\"ג"},{"i":55697,"n":"שפירא, נתן נטע מהורדנא - הזקן","f":"שמשון מפוזנא","k":"בעל מבוא שערים","dt":"שלז - א אייר","b":"רב בהורדנא ור מרדכי יפה בעל הלבוש על מקומו אחריו, פוזנא. תולדותיו ב\"מרגניתא שפירא\" מאת ר חיים דב בר פרידברג. בניו: ר יצחק מקובלה - אביו של ר נתן מלובלין, ר ישכר מפינסק וורמייזא, ר שלמה אביו של ר נתן שפירא מקראקא בעל \"מגלה עמוקות\"."},{"i":55698,"n":"שפירא, נתן נטע מטורבין","f":"שלמה","b":"רב בטורבין-תר\"כ"},{"i":55699,"n":"שפירא, נתן נטע מירושלים","f":"ראובן דוד טבלי","k":"בעל טוב הארץ","bp":"קראקא","dt":"תכד-ו - א אייר","dp":"ריגיו","b":"מחכמי פולין, אביו היה דיין בקראקא, ואף הוא שימש ברבנות בפולין. עלה לירושלים וכיהן כרב קהלת האשכנזים. נשא 2 נשים כמנהג הספרדים. יצא לשליחות אחר פרעות תח ותט שרוששו את הקהלה האשכנזית בירושלים, הגיע לאיטליה ופגש את ר משה זכות שעודדו להדפיס את ספרו. הצליח בשליחותו, ונשאר לכהן כרב בריגייו. חתניו - ר יחיאל פואה, ר נתנאל פואה מריגייו. חיבר \"טוב הארץ\" ונציה תטז, \"מצת שמורים\", \"יין המשומר\" ועוד בנדפס ובכת\"י."},{"i":55700,"n":"שפירא, נתן נטע מלובלין - הנכד","f":"יצחק","dt":"תיב - יז אלול","dp":"לובלין","b":"נכד ר נתן בעל \"מבוא שערים\". רב ודרשן בלובלין. נזכר ב\"ברכת המים\" לר מיכל בן יוזפא, ו\"טוב גטין\" לר זלמן מרגליות. בנו ר ישראל מקאליש בעל \"זרע ישראל\". הו\"ל זהר - לובלין."},{"i":55701,"n":"שפירא, סנדר מבריסק","f":"מאיר","b":"מגדולי חכמי בריסק-שנת ת'"},{"i":55702,"n":"שפירא, עובדיה","b":"תשובה אליו בחסל\"א-תרכו."},{"i":55703,"n":"שפירא, עזריאל מדוניוב","b":"רב בדוניוב-תרלג, זלוזיץ-לפני תרמט וחתם עם הראב\"ד ר אשר קוטן."},{"i":55704,"n":"שפירא, פישל מסריקוב","f":"יוסף יהודה שפירא","bt":"תקג","dt":"תקפה - יז טבת","b":"רב בסטריקוב"},{"i":55705,"n":"שפירא, פנחס","f":"יהודה מאיר משפיטיבקה","dt":"תקפו - כא אדר","b":"נכד ר פנחס מקוריץ. חמיו של ר אברהם שמואל הלר מבוזנוב."},{"i":55706,"n":"שפירא, פנחס יהודה ליב מסלאויטה","f":"יצחק גדליה מסלאויטה","dt":"תרסח - כא שבט","b":"מצאצאי ר זושא מאניפולי. חתן ר נחמן מסקאליט (זלוטשוב), ובזיוו\"ש חתן ר דוד הלוי קימלפלד מואסיקלוב."},{"i":55707,"n":"שפירא, פנחס מטימישואר","f":"אלתר אליקים שרגא","dt":"תשיז","b":"למד עם בן דודו - מהר\"ם שפירא. סירב לרבנות. חתן הגביר ר אלימלך שרגא בקנרוט מדרוהוביטש. עבר לטימישואר. עסק עם אחיו בהצלה בזמן השואה. ניצל מהשואה. עלה לארץ-תשי."},{"i":55708,"n":"שפירא, פנחס מטשרני אוסטרהא","f":"ישראל אברהם מאניפולי","k":"אדמור מטשרני אוסטרהא","b":"חתן ר משה מסלאויטא (קוריץ). מבניו ר ישראל אברהם - אביו של ר יוסף אהרן קוטן מלעשנוב."},{"i":55709,"n":"שפירא, פנחס מסלאויטה","f":"משה מסלאויטה","bt":"תקנא","dt":"תרלב - יד תמוז","b":"נכד ר פנחס מקוריץ. חתן ר יהושע השל בן ר יעקב שמשון משפיטובקא. עסק עם אביו ואחיו בדפוס בסלאויטה, נאסר עם אחיו בעלילה-תקצה. בנו ר יהושע השל (העסיא) מדפיס בסלאויטא - חתן ר יחיאל מיכל מוישנוביץ (זלוטוב) בן ר יעקב שמשון משפיטיבקה.."},{"i":55710,"n":"שפירא, פנחס מפולטושאן","b":"רב בפולטושאן-תרכו."},{"i":55711,"n":"שפירא, פנחס מקוריץ (קארצער)","f":"אברהם אבא משקלוב","k":"בעל לקוטי שושנים","r":"רב ואב\"ד התאחדות קהילות החרדים בסאן פאולו ואח\"כ אב\"ד מלבורן באוסטרליה","bt":"תפו-ח","bp":"שקלוב","dt":"תקנא - י אלול","dp":"שפיטיבקה","b":"מצאצאי בעל הטורים והראב\"ן, ו\"המגלה עמוקות\". תלמיד חבר לבעש\"ט ונחשב לאחד מגדולי האדמורים אחריו. עבר משקלוב למירופול, לקוריץ (והיה שם מחלוקת עם ר שלמה מלוצק-תלמיד המגיד ממזריטש), עבר לסלאויטה, אוסטרהא כ-20 שנה (רבני העיר - ר ייבי ור אשר צבי בעל \"מעין החכמה\" היו הולכים אצלו בשבת - ומנהגי ביה\"כ של ר יוזפא היו מאז על פיו). עלה לירושלים-תקנא אך נפטר בדרכו. בזיוו\"ש חתן ר יונה וייל מסלאויטה. חיבר \"ליקוטי שושנים\" טשרנוביץ תריח, מתורתו ב\"מדרש פנחס\". ובספר נכדו ר מתתיהו יחזקאל גוטמן בשם \"תורת רבינו פנחס מקוריץ\" בילגוריא תרצא. בניו: ר יהודה מאיר משפטיווקא, ר יעקב שמשון מזסלב, ר משה מסלאויטה, ר יחזקאל מאוסטרהא - שהעלים שם אביו מפני ענווה. חתנו ר שמואל מקלניבלטא וזונוראדקע.","bk":[["אמרי פנחס – עה\"ת",""],["גבעת פנחס",""],["ליקוטי שושנים",""],["לקוטים יקרים",""],["מדרש פנחס \\ חכם הרזים - עה\"ת",""]]},{"i":55712,"n":"שפירא, פנחס משקלוב","b":"מגיד בשקלאב"},{"i":55713,"n":"שפירא, פרץ מקושטנץ","f":"שלמה שפירא","b":"רב בקושטנץ בנסיכות באדן-ר\"כ"},{"i":55714,"n":"שפירא, צבי","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":55715,"n":"שפירא, צבי אלימלך ברנדויין","f":"יעקב יצחק מבערטש","bt":"תרסו","dt":"תשב-ג","b":"מצאצאי ה\"נועם אלימלך\" וה\"בני ישכר\". רב בקרעניץ, ראש ישיבה במונקאטש, רב בבירטש-ברדיוב על מקום אביו. עורך \"תצא תורה\" - קריניצה תרצא. נספה בשואה."},{"i":55716,"n":"שפירא, צבי אלימלך מבלוזוב","f":"דוד מדינוב - צמח דוד","k":"בעל צבי לצדיק","r":"אדמו\"ר מבלאז'וב","bt":"תרא","dt":"תרפד - ה ניסן","b":"נכד הבני\"ש ונקרא על שמו. חתן ר משה מרוזוודוב. רב בריבטיטש, בלוזוב-תרכג ואדמור-תרלד אחר פטירת אביו, אחר פטירת אחיו רינ\"ה מדינוב עברו אליו חסידיו. עבר ליבורניק-פולסקי(=יאווארניק)-תרע שבה נושל הבני\"ש, אחר המלחמה (שהה בוינה ובודפשט) עבר לרישא-תרפג, ופשמישל. חיבר \"צבי לצדיק\" קראקא תרפה. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד.","bk":[["ביאור על ספר העיקרים (כת\"י)",""],["צבי לצדיק - על התורה מועדים ושו\"ת",""],["צבי לצדיק - על התורה מועדים ושו\"ת, ביאור על ספר העיקרים (כת\"י)",""],["צבי לצדיק (שו\"ת)",""]],"e":"תר\"א~-תרפ\"ד"},{"i":55717,"n":"שפירא, צבי אלימלך מברטש","f":"אלעזר מלנצהוט","k":"אדמור מברטש","bt":"תרא","dt":"תרסד","b":"נכד הבני\"ש ונקרא ע\"ש. רב ואדמור בברטש-תרכו. חתן ר יהודה הורביץ ממעליץ, ובזיוו\"ש חתן ר יהושע אלעזר חודרוב (שבתו חברה ספר באידיש על הלכות נדה - לא נדפס). מתורתו ב\"חדושי בני ישכר\". בנו ר מרדכי על מקומו אחריו. בנו ר יוסף רב בדינוב."},{"i":55718,"n":"שפירא, צבי אלימלך מדינוב","f":"פסח דוד לנגזם מיאנוב","k":"אדמור מדינוב -בני\"ש","r":"האדמו\"ר מדינוב","bt":"תקמג","bp":"דינוב","dt":"תרא - יח טבת","dp":"דינוב","b":"שינה שמו מלנגזם לשפירא. נכד ר בן ציון יצחק מקאטשיגא-גיסם של ר אלימלך מליזנסק ור זושא מאניפולי. תלמיד גדולי האדמורים ובהם החוזה מלובלין. רב בדינוב-תקנט אצל ר יהושע מדינוב, ריבטיטש-תקע, שוב בדינוב על מקום בעל \"מלוא הרועים\", מונקטש-תקפה על מקום ר צבי אביגדור אשכנזי, סטריזוב ובנו ר אלעזר על מקומו אחריו, לנצוט, קולומיאה, הולשיץ-תקף, ברטשש, מדזילברץ, דובצק. אדמור מדינוב-תקעה. בנו ר דוד על מקומו כאדמור מדינוב. ספרי זכרון שונים לתולדות המשפחה. חיבר \"בני יששכר\" זולקוא תרו, ועוד. מתורתו ב\"קובץ מפרשי התורה\" - מארגרטן תרצג. חדושים ורמזים ושתי תשובות (במהדורת ירושלים תשי\"ז בלבד). ר' צבי אלימלך שפירא, אדמו\"ר ואב\"ד מונקאטש ודינוב. נפטר תר\"א. חיבר גם: בני יששכר. דרך פקודיך, ועוד.","bk":[["דרך פקודיך","ספרי מצוות"],["בני יששכר (דינוב)",""],["אגרא דכלה – עה\"ת",""],["אגרא דפרקא",""],["בני יששכר",""],["ברכה משולשת – משניות",""],["דברים נחמדים",""],["דרך עדותיך",""],["דרך פיקודיך – תרי\"ג מצוות",""],["הגהות מהרצ\"א - זוהר",""],["והיה ברכה – משניות וגמ' ושו\"ת",""],["חדושי בני יששכר",""],["חדושי מהרצ\"א - חנוכה",""],["כלי הרואים",""],["ליקוטי מהרצ\"א – תנ\"ך",""],["מגיד תעלומה – ברכות",""],["מעין גנים",""],["רגל ישרה",""],["ריח דודאים - מגילה",""],["תוספת חיים - תהילים",""],["תמכין דאורייתא – תקנות",""],["מגיד תעלומה [מהדו\"ח]","ברכות"],["דברים נחמדים","מפרשי רמב\"ם"],["בני יששכר","חסידות"],["אגרא דפרקא","חסידות"],["אגרא דכלה","חסידות"]],"e":"תקמ\"ג~-תר\"א","rb":"דינוב","co":{"a":"49.813742,22.233350","d":"49.813742,22.233350","b":"49.813742,22.233350"}},{"i":55719,"n":"שפירא, צבי אלימלך מלנצהוט","f":"שמחה מלנצהוט","k":"אדמור מלנצהוט","b":"אדמור בלנצהוט. חתן ר יצחק קוטן מטיסמניץ."},{"i":55720,"n":"שפירא, צבי הירש ממונקטש","f":"שלמה מסטריזוב-שם שלמ","k":"אדמור ממונקטש-דרכי ת","r":"רב ואב\"ד מונקאטש והגליל","bt":"תרי או תרה","bp":"סטריזוב","dt":"תרעד - טז תשרי","b":"נכד הבני\"ש. חתן ר חנינא הורביץ מאולינוב. תלמיד ה\"דברי חיים\" מצאנז ובנו רי\"ש משיניבה בעל \"דברי יחזקאל\". רב בסטריזוב לצד אביו, ועבר עמו למונקטש-תרמב ורב ואדמור במונקטש על מקומו אחריו-תרנג. יסד את כולל מונקטש בירושלים ובזמנו נבנתה שכונת בתי מונקטש (והיה מחלוקת עם כולל גליציה). בנו ר חיים אלעזר על מקומו אחריו כאדמור ממונקטש. חיבר \"דרכי תשובה\" וילנא תרנג (עם הסכמת גדולי ליטא), ועוד.","bk":[["דרכי תשובה","מפרשי שו\"ע"],["דרכי תשובה [על שו\"ע יו\"ד] (מונקאטש)",""],["באר לחי רואי - זוהר הקדוש",""],["דרכי אמונה - חנוכה",""],["דרכי תשובה - יורה דעה",""],["צבי תפארת - שו\"ת",""],["תפארת בנים - תורה ומועדים והגדה של פסח",""],["באר לחי רואי",""]],"e":"תר\"י-תרע\"ד"},{"i":55721,"n":"שפירא, צבי הירש מפרשבורג","dt":"תפז - א אדר","dp":"פרשבורג","b":"גביר מראשי קהלת פרשבורג-תסט."},{"i":55722,"n":"שפירא, צבי הירש מפרשבורג","f":"נתן נטע","dt":"תקך - ג אב","dp":"פרשבורג","b":"מחכמי פרשבורג, נפטר צעיר."},{"i":55723,"n":"שפירא, צבי הירש מרדואץ","dt":"תרמח","dp":"ירושלים","b":"רב ברדואץ(=ראדיץ)-בוקובינה, עלה לירושלים-תרמב. בנו ר שמשון מסאניוואץ."},{"i":55724,"n":"שפירא, צבי הרמן","k":"בעל כתבים ציוניים","bt":"1840","bp":"ארז'ווליקי-ליד טאווריג","dt":"1898","dp":"קלן - ישראל","b":"תלמיד ישיבות ליטא והתכונן לכהן כרב, (חברו של ר אריה ליב פרומקין). בזמן שהיה מלמד בקובנא נתקל בספר עברי במתמטיקה ופנה ללימוד מתמטיקה בברלין ובהיידלברג. התקרב לחוגי הסטודנטים היהודים מרוסיה. פרסם מאמרים ב\"המליץ\" ובהם הציע להקים אוניברסיטה עברית בארץ. יסד בהיידלברג את המועדין הציוני הראשון בגרמניה לטיפוח הדיבור העברי, לעזרת המתיישבים בארץ ולרכישת קרקעות בארץ. ציר בקונגרס הציוני הראשון והיה בין חמשת החברים שנבחרו לנסח את תכנית בזל. הביא לקונגרס את תוכניתו להקמת קק\"ל."},{"i":55725,"n":"שפירא, צבי יהודה מבלוזוב","f":"ישראל מבלוזוב - חורג","k":"אדמור מבלוזוב","b":"בנו חורגו של ר ישראל מבלוזוב. אדמור בבלוזוב ע\"פ צוואת אביו חורגו."},{"i":55726,"n":"שפירא, צבי מיגולניצה","b":"רב ביגולניצה, ובמשך מאה שנה שמשו צאצאיו רבנים שם. בנו ר ישראל על מקומו אחריו (בברכת הבעשט)."},{"i":55727,"n":"שפירא, צבי מיגלוניצה","f":"שמואל זאב שפירא","b":"רב ביאגלניצא-תר\"י. בנו - ר משלם פיבש שפירא מיגלניצה."},{"i":55728,"n":"שפירא, צמח מקידאן","f":"אברהם מטלז","b":"מחכמי קידאן-שנות ה-תר'. בנו - ר יחזקאל מוידוקלא. אחיו - ר משה מקרוז, ר שמעון מבירז, ר שמואל מפוניבז וטלז."},{"i":55729,"n":"שפירא, קלונימוס קלמיש מפיאסצנא","f":"אלימלך מגרודזיסק","k":"אדמור מפיאסצנא-אש קד","r":"האדמו\"ר מפיאסצנא","bt":"תרמט","bp":"גרודז'יסק מזובייצקי","dt":"תשד - ד חשון","dp":"טרווניקי","b":"מצאצאי המגיד מקוזניץ. חתן אחיינו ר יחמיאל משה מקוזניץ. אדמור בגיל 19, והקים ישיבה בגרודזיסק, פיאסצנא, וארשא. נספה בשואה. חיבר \"חובת התלמידים\", \"הכשרת האברכים\", ועוד. חלק מספריו נכתבו בימי השואה. בנו ר אלימלך בן ציון-נספה בשואה. פעל להוצאת \"הכרם\" - וארשא תרצא - כתב עת של תלמידי ישיבת \"דעת משה\".","bk":[["אש קודש – דרשות למועדים",""],["בני מחשבה טובה",""],["דרך המלך - דרשות על התורה ומועדים",""],["דרשה",""],["הכשרת האברכים",""],["חובת האברכים - מוסר (נכתבה רק ההקדמה",""],["חובת התלמידים – מוסר",""],["מבא השערים לחובת האברכים - חסידות מהי",""],["צו וזירוז - מוסר",""],["שלושה מאמרים - א. איך להגות בספרי חסידות ב. תורה תפילה ושירה להשם ג. קצת מעניני שבת קודש",""],["חובת התלמידים",""],["אש קודש",""],["הכשרת אברכים",""]],"e":"תרמ\"ט-תש\"ד","rb":"פיאסצנו","co":{"a":"52.066667,21.016667","d":"51.139267,22.993139","b":"52.1,20.616667"}},{"i":55730,"n":"שפירא, קמואל מבוצאץ","b":"מחכמי בוצאץ-תרסו. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":55731,"n":"שפירא, ראובן מקראקא","b":"מגדולי חכמי דורו,דיין בקרקא-ש\"צ"},{"i":55732,"n":"שפירא, רפאל מוולוזין","f":"אריה ליב מקובנא","bt":"תקצז","bp":"סמרגון","dt":"תרפא - כג אד\"ב","dp":"מינסק","b":"חתן הנציב מוולוזין. מגדולי מרביצי התורה, ר\"מ בוולוזין-תרך-תרמא, נובו-אלכסנדרובסק-תרמא, בוברויסק-תרמו, אב\"ד ור\"מ בוולוזין-תרנט. בזמן מלחה\"ע ה-I עבר למינסק, ובנו ר יעקב על מקומו אחריו, בניו גם - ר ישראל איסר ור אריה ליב - שעלו לארץ, ר יצחק. חתנו - ר חיים סולוביציק. מאמר ממנו ב\"בית מדרש\" - תל אביב תשא, \"המאור\" - תל אביב תרצה.","bk":[["תורת רפאל - או\"ח (שו\"ת)",""]],"e":"תקצ\"ז-תרפ\"א"},{"i":55733,"n":"שפירא, ש' ח'","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":55734,"n":"שפירא, שאול הכהן מוודיסלוב","b":"רב בוודיסלב-תק\"פ"},{"i":55735,"n":"שפירא, שאול מהורודנקה","f":"מאיר מהורודנקה","b":"רב בזלוטשוב, הורודנקה על מקום אביו - והסכים משם על שפת אמת -למברג תקכה, דיין בלבוב אצל ר צבי הירש רוזניס והסכים עמו על קצות החושן."},{"i":55736,"n":"שפירא, שאול מסופטקין","f":"אברהם","bt":"תקסט","bp":"ראצק","dt":"תרמז - ז אלול","b":"תלמיד ר\"י בכרך בעל נמוקי הגרי\"ב. עבר אל חותנו בסייני. רב בסופוצקין-תרטו-פלך סובלק(=סובאלק). היה בקשרי מכתבים עם ר יחיאל הלר ונזכר ב\"עמודי אור\"."},{"i":55737,"n":"שפירא, שאול מפומפיאן","f":"דב","b":"רב בפומפיאן-ליטא."},{"i":55738,"n":"שפירא, שאול מפוניבז","f":"דב בער משאוויל","k":"בעל חמדת שאול","bt":"תקנז","dt":"תריט","b":"דור תשיעי לאר\"י מצפת. גדל אצל דודו ר משה משיל לוריא מקראקינובה. תלמיד ישיבת פוניבז, רב בפוניבז אצל האב\"ד ר יעקב בן יצחק הלוי, שאדובה-תריג. הניח שו\"ת, דרשות וחדושים - בכת\"י. נכדו ר משה משיל שפירא הו\"ל את ספרו \"חמדת שאול\". חתנו - ר אברהם בנימין טייץ-רבינוביץ."},{"i":55739,"n":"שפירא, שבתי אהרן מגורזד","f":"משה מריגה-פני משה","dt":"תרצד - יח אב","b":"נכד ר איזל חריף בעל \"עמק יהושע\". רב בגורזד-תרנד על מקום ר יצחק איזיק פרידמן, ור מאיר לוין על מקומו אחריו. גיסו - ר יחזקאל ליפשיץ בעל \"המדרש והמעשה\"."},{"i":55740,"n":"שפירא, שלום יוסף מבלנדוב","f":"משה מבלנדוב","b":"מצאצאי המגיד מקוזניץ. מתורתו ב\"ויען יוסף\"."},{"i":55741,"n":"שפירא, שלום יוסף מכפר חסידים","f":"יצחק מרדכי מגווזדיץ","b":"חתן ר ירחמיאל משה מקוזניץ. עלה לארץ והיה ממיסדי כפר חסידים."},{"i":55742,"n":"שפירא, שלום ישכר בער מנובוסלי","f":"פנחס מלנטשין","k":"אדמור מקכניא נובוסלי","bt":"תרס","dt":"תשיז","b":"ממשפחת אדמורי נדבורנא. חתן דודו ר איתמר רוזנבוים מנדבורנא. אדמור מקכניא בנובוסליץ, עלה לירושלים, ניו יורק-תרצט."},{"i":55743,"n":"שפירא, שלום מלודז","b":"פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":55744,"n":"שפירא, שלום מפשיטיק","f":"יעקב יצחק מבלנדוב","k":"אדמור מפשיטיק","dt":"ה-ו אדר","b":"חתן ר דוד מקשאנוב (צאנז). אדמו\"ר בפשיטיק-תרן. מצאצאי המגיד מקוזניץ. חתנו - ר ישראל (שפירא) מפשיטיק."},{"i":55745,"n":"שפירא, שלום מראוא-רוסקא","f":"אבי עזרי זליג אונגר","dt":"תרנד - א תמוז","b":"בנו של האדמור ר אבי עזרי מקאלושין, ושינה שמו מ\"אונגר\" ל\"שפירא\". רב בראוא-רוסקה. נפטר בחיי אביו."},{"i":55746,"n":"שפירא, שלום מרובזביץ","b":"רב ברובזעוויץ"},{"i":55747,"n":"שפירא, שלום צבי מבריסק","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"תורה אור\" - שנחאי תשו."},{"i":55748,"n":"שפירא, שלמה","f":"נתן - מבוא שערים","b":"חתן המהרש\"א? (כך במגילת יוחסין למהר\"ל). מגדולי דורו-שן. בנו - ר נתן בעל המגלה עמוקות."},{"i":55749,"n":"שפירא, שלמה דב מברשיבקא","b":"מצאצאי ר פנחס מקוריץ, נכד ר זאב מבאלטא. חתן ר צבי נכד ר שמואל מקמינקא. נסמך מאת: ר יצחק אהרן אטינגר מלבוב, ר נפתלי מסקווירא. רב בקיטארד-פלך קיוב-תרלט, ברשיבקא(=בארשיווקע)-פלך קיוב. בנו ר שמואל-חתן ר אברהם משפטובקא, חתנו - אהרן מרדכי משפאלע"},{"i":55750,"n":"שפירא, שלמה דב משפיטובקא","f":"שמואל משפיטובקא","b":"היגר מרוסיה לארה\"ב-תשלב. מומחה לרפואה."},{"i":55751,"n":"שפירא, שלמה זלמן מלבוב","b":"רב בלמברג. חיבר תולדות הרבנים-תרצד. הו\"ל \"יבנה\" - למברג תרפט, \"הנצח\" - לבוב תרפז."},{"i":55752,"n":"שפירא, שלמה מברוד","b":"מחכמי ברודי - תשובה אליו בשו\"מ."},{"i":55753,"n":"שפירא, שלמה מדולינא","b":"חתן הרבי מדולינא וישב בדולינא-תרמד."},{"i":55754,"n":"שפירא, שלמה מורמיזא","f":"שמואל","b":"נכד(-אבי אמו) ר מתתיהו טרויש מפאריס. מגדולי מרביצי התורה, פוסק, רב בוורמייזא, היילברון, ברסלוי, לנדא-רך. חתנו - ר שמשון לוריא מורמיזא וערפורט."},{"i":55755,"n":"שפירא, שלמה ממישקולץ","dt":"תשד","b":"רב במישקולץ. חיבר ספר על תולדות קהילת מישקולץ. קובץ נאומים - מישקולץ תרסה, ועוד."},{"i":55756,"n":"שפירא, שלמה מסאבקוב","f":"שלום שפירא","b":"רב בסאבאקוב"},{"i":55757,"n":"שפירא, שלמה מסטנוב - הקדוש","f":"נתן - המגלה עמוקות","bt":"שעו","dt":"תח","b":"היה גאון בילדותו, חתן ר פיבש מוילנא. רב בסטאנוב. הו\"ל ספר אביו מגלה עמוקות על ואתחנן עם הגהות והקדמה ממנו. נהרג עק\"ה. נזכר בקינה של קרובו בעל הש\"ך על הרוגי הפרעות. בנו - ר אברהם נתן מקראקא."},{"i":55758,"n":"שפירא, שלמה מסטריזוב","f":"אלעזר מלנצהוט וריבטש","k":"אדמור ממונקטש-שם שלמ","bt":"תקצב","bp":"ריבטיטש","dt":"תרנג - כא סיון","b":"חתן ר יקותיאל שמלקא מנדבורנה. רב בסאסוב, סטריזוב-תריז, לנצהוט, טארניגרד, ולאחר פטירת אביו ורבו ה\"דברי חיים\" כיהן כאדמור. חסיד הדברי חיים בהשפעת הדיין ר יוסף מרדכי וינר. לאחר שפסל חזן שהיה קצין בצבא ומחלל שבת - נאלץ לעזוב (למרות הפצרת רבים וביניהם הרוזן וולקוביצקי), רב במונקטש-תרמב (זקנו שכיהן שם בתקפה נאלץ לעזוב בגלל ההתנגדות לחסידות, אולם עתה התגברו החסידים שם), בנו ר צבי הירש על מקומו במונקטש, בנו ר יהודה ליב על מקומו בסטריזוב. ר דוד כהנא גלב הדפיס \"בית שלמה\" לתולדותיו. חיבר \"שם שלמה\" ואסר להדפיסו וכן את שאר ספריו. מתורתו בספרי בנו ונכדו."},{"i":55759,"n":"שפירא, שלמה מפירם","f":"אריה ליב מקובנא","dt":"תרמו - ב סיון","b":"אב\"ד פירם(=פערמא). בנו ר זונדל שינה שמו לרבינוביץ."},{"i":55760,"n":"שפירא, שלמה מקלנקוביץ","dt":"תרסה","b":"רב בקאלנקוביץ(=קאלענקאוויץ)-פלך מינסק, ובנו ר מרדכי על מקומו אחריו-תרסה."},{"i":55761,"n":"שפירא, שלמה צבי מוורקלין","b":"רב בוורקלין,ווילאן,קליקול(=קליקאל), עלה לא\"י"},{"i":55762,"n":"שפירא, שלמה ראובן מסטוקלישוק","b":"רב בסטוקלישוק-תרלב."},{"i":55763,"n":"שפירא, שמואל","b":"מרביץ תורה-תק\"י"},{"i":55764,"n":"שפירא, שמואל","f":"שלמה דב מברשיבקא","b":"חתן ר אברהם מפטובקא-ווהלין. רב-שנת תרס."},{"i":55765,"n":"שפירא, שמואל","f":"הבני יששכר","b":"רב-שנת תר\"ל"},{"i":55766,"n":"שפירא, שמואל","f":"צבי אלימלך מדינוב","b":"חתן ר נפתלי הרץ לבין (חתן ה\"עטרת צבי\"). תלמיד ר שמעון מירוסלב. סירב למלא מקום אביו ועסק בהפצת תורתו, ועסק בהדפסת ספרי זקנו הבני\"ש."},{"i":55767,"n":"שפירא, שמואל","dt":"תשמט - כא ניסן","b":"תלמיד ר איסר זלמן מלצר. התקרב לחסידות ברסלב בהשפעת ר שמואל הורביץ והיה תלמיד ר אברהם שטרנהרץ. מתולדותיו ב\"ושמואל בקוראי שמו\"."},{"i":55768,"n":"שפירא, שמואל אברהם אבא מסלויטה","f":"משה מסלאויטה","k":"אדמור מסלאויטה","bt":"תקמז","dt":"תרכד - ה אדר","dp":"טפליק","b":"נכד ר פנחס מקוריץ. תלמיד ר זושא מאניפולי ור ברוך ממזבוב. חתן ר אריה ליב מחמלניק וזיטומיר. עסק בדפוס עם אביו ואחיו, נאסר בעלילה-תקצה עם אביו ואחיו והוגלו לסיביר - ולאחר שנשתחרר-תרטו החל לנהוג אדמורות בסלאויטה. בניו ר פנחס, ר אריה לייב, ור חנינא ליפא מזיטומיר מדפיסים בבית הדפוס אחריו."},{"i":55769,"n":"שפירא, שמואל אריה מסטאויסק","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":55770,"n":"שפירא, שמואל הכהן מוילנא","k":"שמואל פאטראן","dt":"תרח - ט אב","dp":"וילנא","b":"תלמיד ישיבת מייליס בוילנא כ-17 שנה."},{"i":55771,"n":"שפירא, שמואל הכהן מקראקא","k":"בעל אספת הרבנים","b":"סוחר ומחכמי קראקא, ציוני, שפרסם ב\"המגיד\" ו\"הצפירה\". חיבר \"אספת הרבנים\" דרוהוביטש תרסג."},{"i":55772,"n":"שפירא, שמואל ויליאם","bt":"1872","bp":"וילנא","dt":"1936","dp":"ניו יורק","b":"היגר לארה\"ב ולמד רפואה. פרופ' לרפואה בארה\"ב ורופא מומחה."},{"i":55773,"n":"שפירא, שמואל זאב מיגלניצה","f":"ישראל שפירא","b":"רב ביגיעלניצא-תק\"פ"},{"i":55774,"n":"שפירא, שמואל זנויל כץ מגריידץ","b":"רב בגריידץ-תעו, זלאטאווע-תפג. הסכים-תעו על \"אהל יעקב\" לר יעקב שפירא מטיקטין, הסכים-תפג על \"נחמת ציון\"-ברלין תקלב, הסכים-תץ על \"פני יצחק זוטא\"."},{"i":55775,"n":"שפירא, שמואל זנויל מבריסק","f":"זכריה מנדל","b":"מחכמי בריסק. חתם-תטו בפנקס בריסק, חתם עם ר אברהם אפשטין מבריסק על גבית עדות."},{"i":55776,"n":"שפירא, שמואל זנויל מוילנא","b":"רב בוילנא, חתם-תסח עם ר אליהו בן משה קרמר."},{"i":55777,"n":"שפירא, שמואל מגלוגוב","f":"מנחם מנדל פנחס","k":"בעל אור לשמים","bt":"תרכב","dt":"תרצז - יט שבט","b":"נכד ר צבי אלימלך מדינוב בעל \"בני ישכר\". רב בגלאגוב-תרמה, ראדום(=רעדים)-תרסד (והיה שם מחלוקת עם חסידי בלז שהתנגדו לו). חתן ר יעקב יוסף רובין מגלוגוב. נסמך מאת: ר יצחק שמלקיס מלבוב."},{"i":55778,"n":"שפירא, שמואל מדוברומיל","f":"אברהם חיים הלוי","bt":"תרטז","bp":"ברזן","dt":"תרפח","b":"נקרא על שם דודו אחי אמו ר שמואל מהליטש. חתן ר אריה ליבוש וילנר מהליטש. חסיד מהרי\"א מזידיטשוב והתפלל בנוסח זידיטשוב. רב בדוברומיל-תרמב, והתקרב לרד\"מ מצורטקוב ובבנו ישראל, רב בזלוטשוב-תרנז, בנו ר בן ציון על מקומו אחריו בזלוטשוב."},{"i":55779,"n":"שפירא, שמואל מטלז","f":"אברהם מטלז","k":"בעל מעיל שמואל","b":"אב\"ד דרויא, פוניבז, טלז על מקום ר לייב שפירא."},{"i":55780,"n":"שפירא, שמואל מלידניבקה","f":"מרדכי","bt":"תרכח","b":"תלמיד ישיבת ר פנחס נימינסקע באומאן. רב בלידניווקה(=לידווינקע)-פודוליה-תרנה. יסד חברת \"מפיצי תלמוד\" במחוזות פודוליה, חרסון וקיוב והקים ישיבות במירספאל, ויזשיויטאוו-פלך קיוב."},{"i":55781,"n":"שפירא, שמואל מנסכיז קאוולי","f":"יצחק דוד מאיוואנצק","k":"אדמור מנסכיז קאוולי","bt":"תרנו","dt":"תשכב","dp":"קאוולי","b":"חתן דודו ר שמואל מרדכי, אדמור מנסכיז בקאוולי על מקום חותנו. דיין בקאוולי. נספה בשואה."},{"i":55782,"n":"שפירא, שמואל מפרג","b":"עק\"ה,מגדולי חכמי פרג-ש\"מ"},{"i":55783,"n":"שפירא, שמואל מפרג","f":"האליהו רבא","dt":"תק - טו שבט","b":"ראב\"ד בפרג"},{"i":55784,"n":"שפירא, שמואל מרדכי מסטביחוב","f":"יעקב אריה מנסכיז","k":"אדמור מנסכיז סטביחוב","dt":"תרף - ב אייר","b":"חתן ר שלמה מזוויהל (זלוטשוב). אדמור בסטביחוב, קאוולי, נסכיז."},{"i":55785,"n":"שפירא, שמואל משה מרמיגולא","f":"אריה ליב מקובנא","bt":"תרג","bp":"קובנא","dt":"תרעז - תרסח","b":"תלמיד ישיבת וולוזין. רב ברמיגולה(=רעמיגאלע)-פלך קובנא-תרכט, טרישקי (אולי על מקום אחיו ר לוי בעל בית לוי), קוארשאן(=קורשאן)-פלך קובנא, בוברויסק-תרנה או תרנט על מקום אחיו - ר רפאל. בניו: ר אבא אריה ליב מויטבסק ואיזנה, ר חיים צבי הירש מלאפיטש, ר אברהם, ר לוי, ר ישעיה מאיר, ר נח איסר, ר ראובן מדוינסק. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":55786,"n":"שפירא, שמואל משפיטובקא","f":"שלמה דב מברשיבקא","dt":"תשג - ח ניסן","dp":"סיביר","b":"חתן ר אברהם משפיטובקא (סטרליסק), אדמור משפיטובקא-תרפד על מקום חותנו. רב במוסקבה, הוגלה לסיביר-תרצח. נהרג עק\"ה בסיביר."},{"i":55787,"n":"שפירא, שמואל משפירא","b":"חתן ר מתתיהו טרויש מפאריס. מרביץ תורה בקהילת אשפירא-קע"},{"i":55788,"n":"שפירא, שמואל פנחס מלודז","f":"ישעיה מלודז","dt":"תש..","b":"מצאצאי המגיד מקוזניץ. חתן ר אליעזר מסוסנוביץ-ראודשיץ. נספה בשואה."},{"i":55789,"n":"שפירא, שמחה אבי עזרי מלודז","f":"שלום","b":"הו\"ל \"רשפי אש\" - לודז תרפז."},{"i":55790,"n":"שפירא, שמחה בונם","f":"שמה שפירא","b":"רב-שנת ת\"ס"},{"i":55791,"n":"שפירא, שמחה מלנצהוט","f":"אלעזר מלנצהוט","bt":"תר","dt":"תרעג","b":"נכד ר צבי אלימלך מדינוב. רב בלנצהוט(=לנצוט)-תרכה על מקום אביו. (והיה מחלוקת עם אחיו ר מנדלי), היה חסיד אחיו הגדול ר שלמה מסטריזוב. קרא לנדות את יצחק וייסמן שקנה ספר של גרץ והפיץ ספרי השכלה - ועל כך ישבו כמה יהודים במאסר. חתן ר ישראל ליב ורמן מבוצאץ. בנו ר אלעזר על מקומו בלנצהוט."},{"i":55792,"n":"שפירא, שמעון מברודויץ","b":"רב בברודוביץ. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":55793,"n":"שפירא, שמעון מוילנא","dt":"תשג","b":"רב בועד הרבנים בוילנא. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":55794,"n":"שפירא, שמעון מסאניואץ וראדויץ","f":"אלתר משה שפירא","bt":"תרטו","bp":"ראדויץ","b":"רב בסאניואץ, רדיוויץ(=ראדויץ)-בוקובינה-תרמג על מקום זקנו. בנו - ר יוסף, חתנו - ר עזריאל קאווא."},{"i":55795,"n":"שפירא, שמעון מפרג","b":"מגדולי דורו,רב בפרג-ת\"י"},{"i":55796,"n":"שפירא, שמעון מראדויל","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":55797,"n":"שפירא, שמעון מרקל מבירז","f":"אברהם שוועקשנער מטלז","k":"שימעלע בירזער","b":"מקורב לר שמואל חסיד מקעלם. רב בבירז-תקפ על מקום ר עזריאל זיו, ור שלמה זלמן בן מאיר זקש על מקומו אחריו. בשליחות בפטרבורג-תריב. חתניו - ר שמואל סלנט (בזיוו\"ר), ר אשר ניסן לוינזון על מקומו אחריו בבירז (ביניהם היה ר שלמה זלמן זקש). נכדו - העסקן ר שמעון מרקל מקובנא."},{"i":55798,"n":"שפירא, שמריה מויסוקי וזולקוא","f":"יהודה ליב","b":"רב בויסאקי(=ויסוקי), זולקוא-תלט."},{"i":55799,"n":"שפירא, שמשון מפוזנא","f":"נתן שפירא","b":"רב בפוזנא-שנת ש'"},{"i":55800,"n":"שפירא, שרגא פיבל מהיידה","bt":"תרס","dt":"תשג","b":"מרביץ תורה בהיידה(בלגיה)"},{"i":55801,"n":"שפירא-דכנר, יעקב מדלטין","f":"פנחס יוסף מדלטין","k":"אדמור מדלטין","b":"חתן ר ישראל מדלטין. אדמור בדלטין על מקום אביו."},{"i":55802,"n":"שפירא-דכנר, פנחס יוסף מדלטין","f":"ישכר דב ברצי מזסלב","k":"אדמור מדלטין","bt":"תקע","dt":"תרלד","b":"שינה שמו משפירא לדכנר (כשעבר מרוסיה לאוסטריה). חתן ר חיים מקוסוב וישב אצלו. רב בדלטין-תרל. בנו ר יעקב אדמור בדלטין על מקום אביו."},{"i":55803,"n":"שפירא-רבינוביץ, אליעזר מוילנא","f":"אברהם אליהו מסוייר","dt":"תקצ.. - טו אדר","b":"חתן ר שמעון נעכעס. דיין בוילנא-תר."},{"i":55804,"n":"שפל, יוסף מבוצאץ","dt":"תשא","b":"תלמיד ר מאיר ארק, חברו של ר מנדלה הורביץ אב\"ד דזיקוב ונתמנה לרב אצלו בדזיקוב. נספה בשואה."},{"i":55805,"n":"שפלטר, יעקב מברטש","f":"ישראל מאיר מברטש","b":"רב בברטש, איליטש (ליד סנוק), סטריזוב (והיה במחלוקת עם האב\"ד ר נחמיה שפירא). ר\"מ בישיבת עץ חיים בובוב שבסטריזוב-תרץ."},{"i":55806,"n":"שפלטר, ישראל מאיר מברטש","b":"רב בברטש, איליטש. בנו ר יעקב על מקומו ובנו ר מרדכי גרשון רב בסנוק."},{"i":55807,"n":"שפלטר, מרדכי גרשון מסנוק","f":"ישראל מאיר מברטש","k":"בעל אמרי מרדכי","bt":"תרמו","dt":"תשכב","b":"תלמיד ר צבי אלימלך שפירא מבלוזוב. רב בברטש, איליטש, סנוק על מקום אביו. ר\"מ בישיבת בובוב בסנוק. ניצל מהשואה, רב במחנה שוועביש-האלל בגרמניה, רישער (ליד פריס), עבר לניו יורק. חיבר \"אמרי מרדכי\" ו\"עטרת מרדכי\"."},{"i":55808,"n":"שפלטר, שלום","f":"מרדכי גרשון מסנוק","b":"ר\"מ בישיבת \"תומכי תמימים\" במוריסטון-ניו ג'רסי."},{"i":55809,"n":"שפמי, שלמה מקושטא","b":"מגיה בדפוס יונה בן יעקב בקושטא-תצו."},{"i":55810,"n":"שפנדורף, מאיר מסמבור","b":"רב בסמבור. חתום-תרמט כדיין עם ר דוד רפפורט ור יצחק טרוי."},{"i":55811,"n":"שפנר, אברהם מארה\"ב","k":"בעל צרור המור","b":"רב בארה\"ב-תרמז."},{"i":55812,"n":"שפקטר-שפיוואק, אהרן מנ\"י","f":"יעקב","k":"בעל חקר הלכה","b":"רב באומסק-רוסיה, היגר לניו יורק-תרנב."},{"i":55813,"n":"שפר, דוד מפרוינקירכן וירושלים","f":"אהרן יהודה","dt":"תרכג-ט - ח אד\"ב","dp":"ירושלים","b":"דיין בפרויקירכן-הונגריה, בשנת תרכג חתם עם רבני ירושלים בחוברת \"אמת ומשפט\"."},{"i":55814,"n":"שפר, שאול מוינה","f":"יעקב מבוקובסק","k":"בעל חוקי הקרבנות","bt":"תרעח","bp":"וינה","dt":"תשנו","dp":"ירושלים","b":"לפני השואה נסע לבלז, הגיע ללונדון, עלה לירושלים-תשד. חתן ר צבי קליין. חיבר \"חוקי הקרבנות\" ירושלים תשיט."},{"i":55815,"n":"שפרבר, דוד מברשוב","f":"ברוך קלונימוס מזביא","k":"בעל אפרקסתא דעניא","r":"אב\"ד בראשוב","bt":"תרלז","bp":"זבלטוב","dt":"תשכב - כה אד\"ב","b":"תלמיד ר מאיר ארק, ר גרשון שטיין מושקוטץ-בוקובינה. נסמך מאת: ר יהודה גרינפלד מסעמיהאלי, ר שמואל גינצלר. חתן ר משה שטרן מפוליען-ריסקובה (במרמורש) ונכדת בעל \"קונטרס הספקות\". רב בפוליען-ריסקובה אצל חותנו ועל מקומו אחריו-תרפג - ופגש שם את המשכיל ר יצחק לאסט והעיר הערות לספר \"עשרה כלי כסף\" שההדיר ר יצחק, רב בברשוב-תרפב-ה. חסיד ר משה הגר מקוסוב וערך את ספריו והוציאם לאור. מראשי אגו\"י. ניצל מהשואה ועסק בהצלה והתרת עגונות. עלה לירושלים-תשי וכיהן כחבר במועצת גדולי התורה של אגודת ישראל. חיבר \"אפרקסתא דעניא\" סטמר תש, ועוד. פרסם מאמרים ב\"אפריון\" - בודפשט תרפד, \"דגל התורה\" - אויבר-וישווה תרפח.","bk":[["אפרקסתא דעניא",""],["הגהות מהר\"ד שפרבר",""],["מכתם לדוד – תורה ימים נוראים, תהילים, משלי, ופרקי אבות",""],["מצודות דוד - ששה סדרי משנה",""],["תהלה לדוד – הגדה של פסח",""]]},{"i":55816,"n":"שפרבר, הלל מיזלוביץ","bt":"תרנא","bp":"יזלוביץ","dt":"תשד","b":"נכד ר דוד הגר מזבלטוב. תלמיד ר מאיר ארק וסידר את ספרו \"אמרי יושר\" עם הערותיו שלו בסוף. רב בצורטקוב, יזלוביץ על מקום רבו ר מאיר ארק. רב בזברז', זלוטשוב-תרצח. מראשי המזרחי. נספה בשואה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":55817,"n":"שפרבר, חיים יצחק מברושא","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":55818,"n":"שפרבר, יעקב מבוצאץ","b":"מחכמי בוצאץ, רב בסטניסלב-תרנו."},{"i":55819,"n":"שפרברג, מנחם מנדל מסטודניצה","b":"רב בסטודניצה-תרכו, באלין, קמניץ-פודולסק."},{"i":55820,"n":"שפרוט ן, חסדאי","f":"יצחק","bt":"ד'תש","bp":"ג'אין-ספרד","dt":"ד'תש","dp":"קורדובה-ספרד","b":"מגדולי חכמי ספרד,הקים מרכזי תורה בקורדובה,כתב למלך כוזר לברר מצב היהודים שם."},{"i":55821,"n":"שפרוט ן, שם טוב מספרד","f":"יצחק","k":"בעל אבן בוחן","bp":"טודילה-נבארה","b":"רופא מחכמי ספרד, השתתף בויכוח עם החשמן דון פידרו די לונא-שנת ק'. בגלל המלחמה בין נבארה וקשטיליה-קלח, עבר ר שם טוב לטראגונה-אראגון. חיבר גם \"צפנת פענח\", פירוש על האבן עזרא, \"פרדס רמונים\" סביוניטה, ועוד."},{"i":55822,"n":"שפרונג, אלעזר","b":"מחכמי סנוק - סירב לרבנות. אירח את מהר\"ם שפירא וסייע לו בישיבתו - סירב לעבור ללמד ביח\"ל."},{"i":55823,"n":"שפריי, אברהם יהודה","dt":"תשד","b":"ר\"מ בנירדהאז"},{"i":55824,"n":"שפרייזר, יצחק איזיק מטאלטשווא","bp":"טאלטשווא","b":"תלמיד החת\"ס, והכת\"ס. העלה את תורת רבותיו על הכתב, ונדפסו ממנו ב\"כתב וחתם סופר\" ברוקלין תשמח, ו\"עטרות סופרים\" ברוקלין תשנה."},{"i":55825,"n":"שפרייר, זאב","dt":"תשד","b":"מרביץ תורב בבסרמין"},{"i":55826,"n":"שפריכר, אברהם יצחק מפלשטין","b":"רב בפלשטין-תריח."},{"i":55827,"n":"שפרינץ, דוד טעבל","b":"מגדולי חכמי אשכנז,מרביץ תורה בבוכנברג,נירנברג-ר\"ט"},{"i":55828,"n":"שפרינץ, שלמה דב מטארלא וארה\"ב","k":"בעל כרם שלמה","b":"רב בטורלה(=טארלא)-פולין-תרלט, ארה\"ב-תרן. חיבר גם \"לשד השמן\"."},{"i":55829,"n":"שפריצר, בן ציון מטומשוב","f":"שמואל אריה מטמומשוב","bt":"תרנו","bp":"טומשוב-לובלסק","dt":"תשמז","b":"חסיד בלז והמהרי\"ד בחר את שמו. חתן נכדת ר הירש מטומשוב. ניצל מהשואה - ברח לבוכרה עם רד\"ב מטשבין. חזר לסוסנוביץ, עבר לבמברג-גרמניה וכיהן כדיין בבית דינו של האדמור מסטרופקוב. עלה לארץ."},{"i":55830,"n":"שפרלינג, אברהם יצחק מלמברג","k":"אי\"ש שו\"ב","bt":"תריא","bp":"למברג","dt":"תרפא","b":"שו\"ב בלמברג. חיבר \"טעמי המנהגים\" תרנד.","bk":[["טעמי המנהגים","הלכה ומנהג - אחרונים"],["טעמי המנהגים - ליקוטים","הלכה ומנהג - אחרונים"],["טעמי המנהגים הילולא דרשב\"י","הלכה ומנהג - אחרונים"],["טעמי המנהגים קונטרס אחרון","הלכה ומנהג - אחרונים"],["טעמי המנהגים - ליקוטים קונטרס אחרון","הלכה ומנהג - אחרונים"]]},{"i":55831,"n":"שפרלינג, זאב וולף","bp":"למברג","dt":"תרפח","b":"תלמיד ר יצחק שמלקיס. חתן ר שמואל רייך מדינוב ועבר לשם והיה מחכמיה ונכבדיה."},{"i":55832,"n":"שפרלינג, יוסף צבי מלמברג","b":"רב בלמברג-תרמז"},{"i":55833,"n":"שפרן, אברהם אבא מארה\"ב","dt":"תרצא - יח טבת","dp":"ניו יורק","b":"ר\"מ בישיבת רבי יעקב יוסף בניו יורק, רב קהלת בני ישראל סלנטר."},{"i":55834,"n":"שפרן, אלכסנדר יהודה מבקוי","f":"בצלאל זאב מבקוי","k":"בעל ישראל ושורשיו","b":"רב בבקוי על מקום אביו, עבר לבוקרשט. בזמן השואה כיהן כרב הראשי ברומניה, ואחריה רב בג'נבה. חיבר \"ישראל ושורשיו\" ירושלים תשנד."},{"i":55835,"n":"שפרן, בצלאל זאב מבקוי","f":"חנוך הניך מפמורן","k":"בעל שו\"ת הרב\"ז","r":"רב בסקולני, ואח\"כ בשטינפשט, ובבאקו","bt":"תרכד או תרכז","bp":"פמורן-גליציה","dt":"תרץ - יד כסלו","b":"תלמיד ר יצחק איטינגא מלבוב, ור יעקב וידנפלד. חתן ר דוד מארמאר מטרנופול. רב בסקולן(=סקולען)-תרמז, שטפנטש(=שטעפאנעשט)-תרמט, באקוי-מולדביה-תרסה. מגדולי הרבנים ברומניה וממיסדי אגודת הרבנים שם. מקורב לגדולי המדינה ופעל אצלם למען היהודים. בעל \"שרידי אש\" שפגשו - תיאר בכתב את דמותו המרשימה וכן בעל \"מנחת אלעזר\". חתן ר דוד מארמאר מטרנופול נכד בעל \"ההפלאה\", ובזיוו\"ש חתן ר אברהם יוסף ריינהרץ מיאסי. בנו ר אלכסנדר יהודה על מקומו בבקוי. חיבר \"שאלוות ותשובות הרב\"ז\" ורשא תרץ. הסכים על \"בית ועד לחכמים\" - יאסי תרסט. הספד עליו ב\"קבוצי אפרים\" - יאסי-בוקרשט תרעד, תלמיד אחיו ר ישכר בריש מבענדין, חתן ר אלכסנדר זיסקינד ליפשיץ מאוזארקוב. רב ביאנוב(=יאנווא-פאלאצק)-תרמד, מאדוב(מאקאווי)-תרמח, סטשוב-תרסא, גלה לרוסיה במלחמה העולם ה-I, וחזר לסטשוב. עבר לאמריקה, רב בטורונטו-תרף, סט לואיס-תרפז, טורונטו בשנית. פעל רבות למען שמירת השבת וגם פנה לממשלה לתת אפשרות ליהודים לשמור על השבת. תיקן עירוב בעיר (כנראה הראשון באמריקה). נספד ב\"הפרדס\". חיבר גם \"דברים ככתבם\" סט לואיס תרצב, \"יביע אומר\", חיבר זכרון ממלחמת העולם ה-I - לודז תרפו, פרסם מאמרים ב\"המגיד\" - סטמר תרפח, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז. \"שערי ציון\" - ירושלים תרפא.","bk":[["רב\"ז","שו\"ת - אחרונים"],["שו\"ת הרב\"ז",""]]},{"i":55836,"n":"שפרן, דוד מבוקרשט","f":"חנוך הניך מבוקרשט","bt":"תרעה","dt":"תשנא","dp":"ירושלים","b":"רב בבוקרשט, חיבר כ-30 ספרים. נאסר כציוני, עלה לארץ-תשיח."},{"i":55837,"n":"שפרן, חנוך הניך מבוקרשט","f":"בצלאל זאב מבקוי","k":"בעל מנחת חינוך","bt":"תרמז","dt":"תשיט - י אלול","dp":"ירושלים","b":"רב בביוואלאדרי-תרסח. ניצל מהשואה ואחריה רב בבוקרשט. עלה לארץ. הוציא לאור ספר אביו שו\"ת הרב\"ז עם הערותיו. חיבר \"מנחת חינוך\" - בכתב יד. לזכרון ספר זכרון \"עלי שפר\" רמת גן תשן. בנו ר דוד רב בבוקרשט וירושלים. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט, \"מחזיקי הדת\", \"המצפה\", \"דבר בעתו\"."},{"i":55838,"n":"שפרן, יוסף מיאסי","f":"בצלאל זאב מבקוי","k":"בעל פרקי ציון","b":"רב ביאסי. ניצל מהשואה. עלה לארץ-תשו וכיהן כרב בתל אביב, עבר לארה\"ב וכיהן כרב ופרופ' בישיבה-אוניברסיטה בניו יורק. חיבר \"פרקי עיון בתולדות החינוך\" ירושלים תשמו. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":55839,"n":"שפרן, יעקב מקומרנו - דברצין","k":"הצדיק מקומרנא","b":"הגיע מגליציה לדברצין ונקרא הצדיק מקומרנא. גורש ע\"י השלטונות בגלל אזרחותו."},{"i":55840,"n":"שפרן, יצחק מהוסיאטין","f":"חנוך הניך","bt":"תרכט","b":"רב בקאמינק-תרמח, הוסיאטין(=הויסאטין)-פודוליה. אחיו של ר בצלאל זאב שהזכירו בספרו - \"שו\"ת הרב\"ז\"."},{"i":55841,"n":"שפרן, מנחם מפלוישט","dt":"תשם","dp":"תל אביב","b":"רב בפלוישט. ניצל מהשואה, עלה לארץ-תשיג."},{"i":55842,"n":"שפרניק, מנחם מנדל מפמורן","f":"גבריאל מברודי","k":"בעל תפארת מנחם","dp":"טיסמניץ","b":"רב בפמורן, טיסמניץ. חיבר \"תפארת מנחם\" למברג תרלה."},{"i":55843,"n":"שפת-אמת"},{"i":55844,"n":"שץ, ברוך בוריס","k":"בעל אחד מרבים","bt":"1866","bp":"וורנה-ליטא","dt":"1932","dp":"דנבר-קולורדו","b":"למד אמנות בוילנא, בעידודו של אנטולולסקי יצא ללמוד בצרפת. עוזרו של אנטוקולסקי-1890. פסל החצר בסופיה וממיסדי האקדמיה הבולגרית לאמנות. התקרב לציונות, ובהשפעת הרצל עלה לירושלים ויסד את ביה\"ס לאמנות \"בצלאל\". בזמן מלחמ\"ה ה-I נאסר ע\"י התורכים. בשליחות המוסד בחו\"ל ונפטר בשליחותו. חיבר גם \"על אמנות אמנים ומבקריהם\" ירושלים תרפד, ועוד."},{"i":55845,"n":"שץ, מאיר הכהן מארה\"ב","f":"שמואל","k":"בעל רנה ותפלה","b":"רב בניו יורק-תרטז."},{"i":55846,"n":"שץ, צבי יצחק מדינוב","b":"רב בדינוב-תרכט."},{"i":55847,"n":"שצברג, אליעזר זאב מזלישטשיק","k":"בעל מנחת אליעזר","b":"רב בזלישטשיק. חיבר \"מנחת אליעזר\", \"זכרון בספר\" - לקורות העיר ורבניה - כנראה לא נדפסו. פרסם מאמרים ב\"הנצח\" - לבוב תרפז."},{"i":55848,"n":"שצברג, אלעזר מסקלט","f":"אלעזר?","b":"רב בסקלט, זבורוב-תרמא, אב\"ד סקלט-תרן."},{"i":55849,"n":"שצברג, משה אהרן מסקלט","f":"ישראל מסקלט","b":"רב בסקלט על מקום אביו, אולי בנו ר אלעזר על מקומו אחריו."},{"i":55850,"n":"שצדרביצקי, מאיר שלום מביאליסטו","f":"דב","k":"אדמור מקוברין ביאליס","bt":"תרלה","dt":"תש - כב חשון","b":"חתן ר מנחם נחום אפשטין האדמור מקוברין. משנה לרב בביאליסטוק-תרעא, ואדמור לחסידי קוברין על מקום חותנו אחריו. נספה בשואה. בנו ר שמואל אהרן."},{"i":55851,"n":"שצדרביצקי, משה זאב מביאליסטוק","dt":"תש..","b":"חתן ר יהושע עוזיאל וינטרוב האדמור ממרקישוב וארשא."},{"i":55852,"n":"שצדרביצקי, שמואל אהרן מתל אביב","f":"מאיר שלום מביאליסטוק","dt":"תשלח - ה ניסן","dp":"תל אביב","b":"בן האדמור מקוברין. חתן ר פנחס ישכר מסוסנוביץ (שושלת רדושיץ). עלה לארץ והתישב בתל אביב, סגן יו\"ר אגו\"י בא\"י."},{"i":55853,"n":"שצ'ופק, א' מסארהיי","b":"רב בסארהיי-ליטא."},{"i":55854,"n":"שצוצינר, יוסף","bt":"תרכ","dt":"תרצ - א תשרי"},{"i":55855,"n":"שציגל, זאב מתתיהו","f":"צבי מיכאל","bt":"תרנו","bp":"אוסטרוב","dt":"תשכ","b":"מרביץ תורה,עלה לבני ברק-תר\"צ,ראש ישיבת בית יוסף שם"},{"i":55856,"n":"שצקס, אברהם אהרן - הנכד","f":"משה","k":"בעל בירור הלכות-כת\"י","bt":"תרעה","bp":"איוויע-פלך וילנא","b":"תלמיד ישיבית גרודנא, מיר. חתן ר חיים יצחק קארב משיקגו. נסמך מאת: ר דוד טבל דינובסקי מפיאנטניצא, ר חנוך הניך אייגש מוילנא, ר אליעזר יהודה פינקל. ניצל מהשואה והגיע לארה\"ב-תשא וכיהן כרב \"חכמת אדם אנשי לומזה\" בניו יורק, ר\"מ בישיבת רבי יצחק אלחנן בניו יורק. פרסם מאמרים ב\"שערי ציון\", \"כנסת ישראל\", \"הפרדס\", \"תלפיות\". חבר אגודת הרבנים באמריקה."},{"i":55857,"n":"שצקס, אברהם אהרן מוילנא - הזקן","b":"חתן ר אברהם אבא בן חיים מזעלווא. מחכמי וילנא כונה בשם \"העילוי מזעטיל\". בנו - ר משה מארה\"ב."},{"i":55858,"n":"שצקס, אריה ליב מברודי","b":"מנהיג מדינה בברודי-ת\"ק"},{"i":55859,"n":"שצקס, חיים","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":55860,"n":"שצקס, יוסף מברוד","f":"אריה ליב מברודי","bt":"תס","dt":"תקלא - כא טבת","b":"רב בברודי על מקום ר איציקל הורביץ - שעבר לאה\"ו. בפרשת הגט מקליווא תמך בר ישראל ליפשיץ. הסכמים על ספרים רבים מ-תקיג. (ביקש להיקבר ליד מי שבקי בירושלמי ויוכלו לפלפל - ואז נזדמן לשם בעל \"פני משה\" ונפטר-תקמא, ואכן נקבר לידו)."},{"i":55861,"n":"שצקס, משה מלומזה וארה\"ב","f":"אברהם אהרן","k":"בעל ענף פרי","bt":"תרמב","bp":"וילנא","dt":"תשיט","b":"לאחר שנתייתם גדל אצל אביו חורגו - ר יצחק בלזר בפטרבורג. תלמיד ישיבות סלובודקא, טלז. נסמך מאת: ר רפאל שפירא, ר אליעזר גורדון מטלז, ר אליעזר רבינוביץ ממינסק. רב בליפנישק(=ליפנישאק)-פלך וילנא-תרסט, איוויע-תרעה, לומזה-תרצא, וילנא-תש וכיהן כר\"מ בישיבת גרודנא שעברה אז לוילנא על מקום ר שמעון שקופ, ניצל מהשואה והגיע לארה\"ב-תשא וכיהן כר\"מ בישיבת רבי יצחק אלחנן בניו יורק. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"שערי ציון\" - ירושלים תרפא, \"כנסת הגדולה\" - וארשא תרן. חיבר \"ענף פרי\" שנספח ל\"פרי יצחק\" לאביו חורגו."},{"i":55862,"n":"שצ’רנסקי מאיר בן בנימין","bt":"1905","dt":"ה'תשלב 1972","bk":[["דיני חנוכה ופורים וארבע הפרשיות",""],["דיני שלש רגלים",""],["דינים לנוער ולעם",""]]},{"i":55863,"n":"ש\"ק, מנחם נחום מוילנא","f":"אליעזר","b":"רב בוילנא, חתם-תסא עם ר הלל בן נפתלי הרץ מוילנא וקידאן."},{"i":55864,"n":"שקארוטה, משה","k":"בעל אור משה - כת\"י","bt":"תרמח","bp":"רז'יצה-לטביה","dt":"תשד","b":"גדל אצל דודו שאמצו. תלמיד ר איצל'ה מרז'יצה, ור מאיר שמחה מדוינסק בעל \"אור שמח\" והיה מזכירו של רבו. חתן ר משה מרדכי אפשטין. עסק לפרנסתו במסחר וכיהן כרבה של רז'יצה - ללא שכר. רב בסלובודקה-תרצז. דרשן מפורסם, ומיטיב נגן. נספה בשואה."},{"i":55865,"n":"שקארמילא, גרשון","f":"אשר","b":"עבר בהרבה מקומות בארץ ישראל, חיבר ספר \"יחוס הצדיקים\" מנטובה שכא. בשנת שכא שהה באיטליה כנראה בשליחות ירושלים."},{"i":55866,"n":"שקוביצקי, בנימין הכהן ממינסק","f":"מרדכי","bt":"תרלג","bp":"איישישוק","dt":"תרצח","dp":"תל אביב","b":"תלמיד ישיבות וילנא, ז'אלודק, ווילקי. כונה \"הבחור מאיישישוק\". מגיד מישרים במינסק ונודע כ\"מגיד ממינסק\" היה דרשן מחונן והיה מרתק המון עם במשך שעות. סייע לפליטים שהגיעו למינסק בזמן מלחמ\"ה ה-I. בתקופת הקומוניסטים נאסר על פעולתו, והוגלה לפרילוקי. עלה לארץ-תרצד והשתקע בתל אביב."},{"i":55867,"n":"שקוביצקי, נפתלי הכהן","f":"בנימין","dt":"תשכג","b":"אב\"ד גייטסהד-אנגליה. פרסם מאמרים ב\"קול תורה\" - גייטסהד תשז, \"תבונה\" - ירושלים תשא-תשח."},{"i":55868,"n":"שקולי, אברהם","b":"פייטן ומשורר-ד'תתקן. נזכר בשיר \"חותם תכנית\" לר\"א הבדרשי."},{"i":55869,"n":"שקולניק, אבא הלל","f":"שלמה","bt":"1850","bp":"פלוטל","b":"בן רבה של פלוטל. התישב בליבאו והחל לכתוב שירים. בעת \"שלום עליכם\" התמסר למחקר ולאיסוף פתגמים."},{"i":55870,"n":"שקולניק, שלמה מפלוטל-ליטא","f":"אליעזר","k":"בעל תשובה שלמה","bt":"תקצח","dt":"תרעה - יג אלול","b":"חתן ר אליהו מרגליות משאלאנט. רב בפלאטל(=פלוטל)-פלך קובנא-תרל כ-50 שנה. חיבר \"תשובה שלמה\" - בכת\"י. בנו - ר זאב וולף לרמן מערזועליק, חתנו - ר חיים יעקב דבנובסקי מטרישיק."},{"i":55871,"n":"שקולניקוב, מנחם מנדל","b":"מרביץ תורה בהומל"},{"i":55872,"n":"שקופ, משה מרדכי הכהן","f":"שמעון שקופ","bt":"תרמב","bp":"סמרגון","b":"תלמיד ישיבת טלז. נסמך מאת: ר אליעזר גורדון, ר יצחק רבינוביץ. חתן ר מרדכי קלמן כץ מגרודנא. ר\"מ בגרודנא-תרפב, רב בפערשטט-בקובנא-תרצט על מקום אביו, עבר עם הישיבה לוילנא-תש, הגיע לארה\"ב-תשא וכיהן כר\"מ. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":55873,"n":"שקופ, שמעון יהודה הכהן","f":"יצחק שמואל ממאלץ","k":"בעל שערי יושר","r":"גאב\"ד ניאמץ","bt":"תרך","bp":"טוריץ - פלך מינסק","dt":"תש - ט חשון","dp":"וילנא","b":"תלמיד ישיבת מיר, וולוזין. חתן ר משה מרדכי אידלביץ מסמרגון. ר\"מ בישיבת טלז-תרמד אצל דודו (דוד של אשתו) ר אליעזר גורדון, רב במאלטש-תרסג על מקום אביו, בריינסק-תרסז, ראש ישיבת גרודנא-תרף, סולל דרך ישרה בהבנה ועמקות, הגיע לניו יורק-תרפט וכיהן כראש ישיבת \"רבי יצחק אלחנן\" במשך כשנה. נענה לבקשת החפץ חיים ור חיים עוזר מוילנא וחזר לאירופה. העביר את ישיבתו לוילנא. חיבר גם \"מערכת הקנינים\", וחדושים בש\"ס. תלמידיו הו\"ל \"שערי תורה\" משיעוריו, ו\"ספר היובל\" - וילנא תרצו. פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"כנסת ישראל\" - וילנא תרץ, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז.","bk":[["חדושי ר' שמעון יהודא הכהן (שקופ)","מפרשי ש\"ס - אחרונים"],["שיעורי ר' שמעון שקופ",""],["שערי יושר - ענינים",""],["שערי יושר",""],["חי' רבי שמעון שקאפ",""],["שערי יושר - ענינים, שיעורי ר' שמעון שקופ",""],["חידושי רבי שמעון שקאפ",""],["שיעורי רבי שמעון שקאפ",""],["שערי ישר",""],["שעורי ר' שמעון יהודא הכהן [שקופ]","מפרשי ש\"ס - אחרונים"],["שערי ישר","מערכות"]],"e":"תר\"כ-ת\"ש"},{"i":55874,"n":"שקלא, יוסף מלודז","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":55875,"n":"שקלובר, אהרן דוד מוילנא","b":"ערך את הספר \"באר אברהם\" מתורתו של ר אברהם אבלי פוסוואלר מוילנא יחד עם ר שמעון סאבאלניק."},{"i":55876,"n":"שקלי, שמואל","b":"מגדולי חכמי סיציליה-ק\"ע"},{"i":55877,"n":"שקלרסקי, צבי הירש","bt":"1891","bp":"סקידל-פלך גרודנא","dt":"1931","dp":"קניגסברג","b":"מורה ומוסיקאי. התישב בוארשא, קובנא. מבקר מוסיקלי ב\"נייס\", \"אידישע שטימע\", ועוד. פרסם גם ב\"הד ליטא\", ו\"נתיבות\"."},{"i":55878,"n":"שקרון, אהרן מאלגיר","bt":"תקפא","bp":"גרדאייה-אלגיר","dt":"תרעג","b":"רב בגרדאייא-אלגיר, לאגוואט-אלגיר-תרעג. קברו מקום עליה לרגל בל\"ג בעומר."},{"i":55879,"n":"שקרון, אליהו ממרוקו","b":"מחכמי מרוקו-תקע. אין פרטים נוספים."},{"i":55880,"n":"שקרון, אליעזר ממרוקו","b":"מחכמי מרוקו-שנות ה-תק'."},{"i":55881,"n":"שקרון, יוסף מפאס","b":"מחכמי פאס, חתם-תצב, חתם על פס\"ד עם ר שמואל סעדון."},{"i":55882,"n":"שקרון, יעקב מאלגיר","dt":"תשיז","b":"רב בלמדיא-אלגיר. נהרג עק\"ה."},{"i":55883,"n":"שקרון, יצחק מאלגיר","bt":"תרעה","bp":"וואהראן","dt":"תריב","dp":"צרפת","b":"רב במילייאנה-אלגיר, דיג'ון-צרפת. חיבר מאמרים בצרפתית על תורת ישראל."},{"i":55884,"n":"שקרון, מימון מפאס","b":"מחכמי פאס-תצב."},{"i":55885,"n":"שקרון, מסעוד ממרוקו","b":"מחכמי מרוקו-תקסב."},{"i":55886,"n":"שקרון, ציון מאלגיר","bt":"תרמז","dt":"תשלג","b":"רב בקצמטינא. תרגם לערבית יהודית חלק מספר יהושע, יחד עם ר דוד הכהן ור ש' זגביב - תונס תרעא."},{"i":55887,"n":"שר שלום גאון סורא","f":"רב בועז","b":"גאון סורא-ד'תרי על מקום רב כהן צדק בר רב איבומאי, ורב נטרונאי בר רב הילאי על מקומו אחריו. תשובות רבות ממנו גם לספרד, ומהם בסדור רב עמרם. היה במחלוקת עם ניסי בנו של ראש הגולה."},{"i":55888,"n":"שר שלום פורטוגזי","f":"אברהם","k":"בעל קב ונקי","b":"חיבר \"קב ונקי\"."},{"i":55889,"n":"שר שלום, רבנא מפרס","b":"רב הרבנים במדינת פרס מטעם ראש הגולה בבבל-תתק (1140). חתנו - ר משה מאיר אויסאהאן. ונזכרו בספר מסעות רבי בנימין."},{"i":55890,"n":"שר, גדליה מארה\"ב","b":"פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":55891,"n":"שר, חיים יצחק","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":55892,"n":"שר, יהושע מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":55893,"n":"שר, יוסף מסלובודקה","f":"יצחק איזיק מסלובודקה","b":"עורך \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח-תש - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":55894,"n":"שר, יצחק איזיק חיים מסלובודקה","f":"יוסף חיים","k":"בעל עמק הבנה","r":"ראש ישיבת סלבודקא שבבני ברק, חתנו של ה'סבא' מסלבודקא","bt":"תרלה-ו","bp":"הלוסק-פלך מינסק","dt":"תשיא-ב - י שבט","dp":"בני ברק","b":"מגדולי מרביצי התורה בדורו. תלמיד ישיבות וולוזין, פלאצק, סלובודקה. חתן הסבא מסלובודקה, תלמיד ר שמחה זיסל בקלם, עבר למיר וחזר לסובודקה. ר\"מ בישיבת סלובודקה-תרסט, בזמן מלחה\"ע ה-I נדד עם הישיבה למינסק וקרמנצ'וג, ואחריה ראש כולל האברכים \"בית ישראל\" שע\"י הישיבה. לאחר עליית חלק מהישיבה-תרפה נתמנה לר\"מ בישיבה לצדו של חותנו. בשליחות בארה\"ב כמה פעמים מטעם הישיבה ויסד שם \"הסתדרות חניכי סלובודקה\" לשם חיזוק התורה והמוסר. ראש הישיבה על מקום חותנו. ניצל מהשואה (היה בשוייץ) עלה לארץ והקים את ישיבת סלובודקה מחדש בבני ברק. הו\"ל את שיחות חותנו יחד עם חברו ר אברהם גרודזנסקי בשם \"אור הצפון\". פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג, פרסם מאמרים ב\"תבונה\" - ירושלים תשא, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה. עורך המאסף \"בית ישראל\" - קובנא תרפב. בנו ר יוסף ממנהלי הישיבה - נספה בשואה בלטביה.","bk":[["לקט שיחות מוסר - על התורה, שבת ומועדים, תלמוד תורה, ומסילת ישרים ועניינים שונים",""]]},{"i":55895,"n":"שר, מנחם מנדל מקופצאווה","dt":"תשג","b":"רבה האחרון של קופצאווה(=קאטשעווא). נספה בשואה."},{"i":55896,"n":"שר, נחום מדאוג-ליטא","dt":"תשג","b":"רב ברוזאליה, רבה האחרון של דאוג. נספה בשואה."},{"i":55897,"n":"שר, שמואל משובאץ","f":"יהודה","k":"בעל בגדי שש - בכת\"י","bt":"תרלח","b":"תלמיד ישיבת ר בינוש ראבינער בבויסק, ישיבת סלובודקא. חתן ר שלמה זלמן משובאץ, רב בשובאץ-פלך קובנא-תרסד על מקום חותנו, בזיוו\"ש חתן ר יקותיאל זוסמן מדראזאליא. נסמך מאת ר יצחק יעקב רבינוביץ מפוניבז."},{"i":55898,"n":"שרבאני, ראובן","b":"אחיו של ר יהושע שרבאני."},{"i":55899,"n":"שרביט הזהב, אברהם מקושטא","f":"שמריה","b":"רב בקושטא-שנות ה-ש'-ת'."},{"i":55900,"n":"שרביט הזהב, שלמה מאפסוס","f":"אליהו","k":"בעל חשק שלמה","bt":"קפ","bp":"רמא-ב","b":"רב באפסוס-יוון, שלוניקי - קמ. מחכמי יוון בזמן הריב\"ש. פייטן, מדקדק, משורר ותוכן. חיבר גם ספר אסטרונומיה \"מהלך כוכבים\", ושירים ופיוטים."},{"i":55901,"n":"שרביט הזהב, שמריה משלוניקי","bp":"ליפאנטו","dt":"שסב - אחרי","b":"מחכמי ליפאנטו, שלוניקי, רב בקהלת ליובנטינזש (לבנטינים) בונציה, קושטא-שנז."},{"i":55902,"n":"שרביט, אלעזר מסנוק","f":"שוורד","k":"בעל שמייך ירושלים","bt":"תרסח","bp":"סנוק","dt":"תשמה","b":"ראש השומר הדתי בסנוק. למד בבלז. עלה לירושלים-תרצד. חיבר \"שמייך ירושלים\" ועוד. עורך ספר זכרון - סנוק. עורך ומגיה בתלמד שטיינזלץ."},{"i":55903,"n":"שרביט, מכלוף מירושלים","dt":"תרסח - כו תשרי","dp":"ירושלים","b":"מקובל בירושלים מראשי \"בית אל\"."},{"i":55904,"n":"שרביט, מסעוד ממרוקו","b":"מחכמי מרוקו, תשובות אליו במר יוסף משאש."},{"i":55905,"n":"שרביט, משה","b":"ראש הקהל (?)-תקנב. (כנזכר באוצר מכתבים ח\"ב ע' קטו)."},{"i":55906,"n":"שרביט, סעדיה","b":"מחכמי מרוקו, ושאל את ר\"י משאש ב\"אוצר המכתבים\"."},{"i":55907,"n":"שרביט, שלמה מאלגיר","f":"מרדכי","bt":"תל - בערך","dt":"תק - בערך","b":"רב בתלמסאן וזכה לעשירות."},{"i":55908,"n":"שרבני, יהושע מירושלים","bt":"תרלז","dt":"תשלג - יא טבת","b":"מקובל,איש מופת בירושלים"},{"i":55909,"n":"שרברק, יוסף","f":"שכנא","bt":"1896","bp":"פוסטאב","dt":"1957","dp":"תל אביב","b":"פעיל בצ.צ. בוילנא. עלה לארץ-1914. מראשוני המתנדבים לגדוד העברי-1918. היה בין מגיני הישוב בירושלים ונאסר יחד עם זבוטינסקי-1920. מיסד הוצאת הספרים \"מצפה\" יחד עם י. צ'צ'יק ומ. ניומן - שהיתה הוצאת הספרים הפרטית הראשונה בארץ, ואח\"כ הוצאת \"שרברק\"."},{"i":55910,"n":"שרברק, שלמה","f":"שכנא","bt":"1876","bp":"פוסטאב","dt":"1944","dp":"תל אביב","b":"בעל הוצאת ספרים בוילנא, וממיסדי צנטרל - התאחדות המו\"לים בוארשא יחד עם בן אביגדור וא.ל. קפלן. הו\"ל את העתון \"דאס לעבן\" בוארשא. יסד את \"אחיאסף\". עלה לארץ-1933 והיה בעל הוצאת ספרים בת\"א. ממיסדי התאחדות המו\"לים בארץ ונשיאה."},{"i":55911,"n":"שרגא אל, שמואל מספרד","b":"מקובל מחכמי ספרד בזמן הגירוש. רבו של המקובל ר יהודה בן יעקב חייט."},{"i":55912,"n":"שרגא מלובלין","dt":"תרד - יט תשרי","b":"דיין בלובלין"},{"i":55913,"n":"שרגא ן, יוסף מאריינטי","b":"חיבר פירוש התפלות ע\"ד הקבלה (בספרית ר חיים בן יוסף מיכל). ב\"מושיע חוסים\" - סדר תיקון מגפה ממנו. (לא ברור אם השם מאריינטי הוא שם עירו או כינויו)."},{"i":55914,"n":"שרגא פיבוש וולף מצאנז","b":"ראב\"ד בצאנז-תר\"נ"},{"i":55915,"n":"שרגא פיבוש מדוברובנא","k":"בעל מנורת שלמה","b":"רב בדוברוונא-תק\"נ. חתן הגר\"א?. חיבר גם \"מנחת כליל\". הו\"ל ביאור הגר\"א לתורה."},{"i":55916,"n":"שרגא פיבוש מזלשין","b":"מג\"מ בזאלשין-תק\"מ"},{"i":55917,"n":"שרגא פיבל מהורודוק","b":"רב ביסקולקא, סייני, הורודוק. הסכים על \"אור מתוק\" וילנא תרמח."},{"i":55918,"n":"שרגא פיבל מלבוב","f":"שמואל","b":"מנהיג בלבוב, חתם-תקד על כרוז ותקנה, ועוד."},{"i":55919,"n":"שרגא פיבל מלוקאוו","dt":"תרכט - ב אדר","b":"רב בלוקאוו,מו\"צ בווארשה"},{"i":55920,"n":"שרגא פיבל מסייני","f":"יוסף","b":"חתן ר יצחק מרגליות משצוצין. ראב\"ד בסייני-רומניה-תריט. הסכים על משניות - וארשא תרך."},{"i":55921,"n":"שרגא פיבל מפופיליאן-ליטא","bt":"תקפג","dt":"תרנב","b":"רב בפופיליאן-ליטא."},{"i":55922,"n":"שרגא, דוד","f":"שלמה","bt":"תרלב","b":"דיין, רב ראשי ביזד, דרשן, עלה לירושלים, לימד תורה בישיבת \"שערע ציון\" בנחלת שבעה, גר בשכונת הבוכרים"},{"i":55923,"n":"שרגא, יהודה מפיעטרקוב","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":55924,"n":"שרגא, שלמה מפרס","dt":"תרעג - יז טבת","b":"רב ומקובל בפרס. מצאצאיו מחכמי ירושלים."},{"i":55925,"n":"שרגורדסקי, זלמינא מקישינוב","dt":"תקמב","b":"תלמיד הבעשט. רבה הראשון של קישנוב, ומפיץ החסידות בבסרביה."},{"i":55926,"n":"שרה אמנו ע\"ה"},{"i":55927,"n":"שרהזון, אברהם חיים מארה\"ב","f":"כתריאל צבי","b":"נכד ר אליהו שרהזון מלומזה, ונכד(-אבי אמו) ר דוד יהלומשטין מסובאלק. חכם ועורך דין בניו יורק. אחיו - ר יחזקאל מניו יורק, גיסו - ר אריה ליב קאמייקא."},{"i":55928,"n":"שרהזון, אליהו יהודה","f":"יצחק אייזיק","k":"בעל חיבת ירושלים","bt":"תקס","bp":"מיכלישוק","dt":"תרלח","dp":"ירושלים","b":"רב בקהלות שונות ברוסיה ליטא, עלה לירושלים, היה רב ודרשן בבית הכנסת \"בית יעקב\" . חיבר ספר \"חיבת ירושלים\" וארשא תריא, \"עוגת אליהו\" ירושלים תרעג ועוד","bk":[["אגדת אליהו - הגדה של פסח",""],["חבת ירושלם - מזמור פ\"ז שבתהילים",""],["משאת משה - לכבודו של השר משה מונטיפיירי",""],["נשמת חיים",""],["עגת אליהו – אבות",""]]},{"i":55929,"n":"שרהזון, כתריאל צבי מארה\"ב","f":"אליהו","b":"היגר לארה\"ב, יסד את העתון היומי החרדי \"די אידישע טאנגעבלאט\" בניו יורק."},{"i":55930,"n":"שרהיי, מנחם מנדל יהודה ליב","f":"יואל שלום","k":"בעל משיב נפש","bp":"ריטובה","b":"למד רפואה בברלין, השתקע בריגה-תרע והיה מגדולי הרופאים. קבע עתים לתורה וחיבר חדושי תורה כאחד הרבנים. חליפת מכתבים בינו לבין ר חיים חזקיה מדיני נתפרסה ב\"שדה חמד\". פעל גם כעסקן ציבור ותמך בתלמידי חכמים."},{"i":55931,"n":"שרה'לה ר טובי'עס מוילנא","b":"אחות ר ליב'לי אביו של ר אורי בער מוילנא. נדבה את בתי מייליס לגבאי צ\"ג בוילנא ליסוד הישיבה, ונמסרו לועדת רבנים: ר אבלי-רבה של וילנא, ר זלמן ר אורי'ס, ור יהושע נאיישטאטער, ובעזרת ר שבתי בן שבתי נתקנו לישיבה-תקצא."},{"i":55932,"n":"שרה'ס רוסטובסקי, ליב מפלונגיאן","b":"רב בפלונגיאן-תרך. חתנו - ר בנימין ביניש מטאווריג."},{"i":55933,"n":"שרויט, אפרים פישל מקורטשין","b":"מחכמי קורטשין. חתן אב\"ד סטרי. ממשתתפי \"אהל מועד\"."},{"i":55934,"n":"שרוץ, שרגא פיבוש מפודהייץ","f":"[פיבל מפדוהייץ]","b":"רב בפודההיץ לפני השואה."},{"i":55935,"n":"שרטר, אליעזר","dt":"תרכד - יד תשרי","b":"ראב\"ד בטפלטשין"},{"i":55936,"n":"שרטר, דוד לייפניק","k":"בעל קרן לדוד","dt":"תרמב - כט שבט","b":"רב בפרערוי,דרזניץ,זשמבקרט-תר\"כ,ראב\"ד בלייפניק"},{"i":55937,"n":"שרטר, ישראל חיים","f":"דוד שרטר","dt":"תר - יח טבת","b":"רב בלונדנבורג-תקצ\"ג"},{"i":55938,"n":"שריאן (שריון), סעדיה מירושלים","r":"גאב\"ד אנטוורפן","bt":"תרמב","dt":"תשלא - טז טבת","dp":"ירושלים","b":"תלמיד ר יעקב עדס בירושלים. סופר אומן. ראש ישיבת \"חיי שלום\" בירושלים ודיין בבית הדין של העדה התימנית."},{"i":55939,"n":"שריאנו, יצחק משלוניקי","f":"אברהם","b":"מגיה בשלוניקי אצל יתומי בצלאל אשכנזי-תקטז."},{"i":55940,"n":"שרייבמן, מרדכי אליהו מוארשא","b":"ר\"מ בישיבת \"בית אהרן\" ו\"תחכמוני\" - וארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו, \"בית אברהם\" - וארשא תרצד."},{"i":55941,"n":"שרייבמן, מרדכי מבירזולא","f":"עזרא","k":"בעל מנחת מרדכי","bt":"תרמה","b":"נסמך מאת: ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\". חתן ר מיכאל מיריינא מקאפרד. רב בביזלה(=בירזולא)-פלך חרסון-תרסח, פרסם מאמרים ב\"המאור\" - תל אביב תרצה. חיבר \"מנחת מרדכי\" - בכת\"י."},{"i":55942,"n":"שרייבער, ברוך מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":55943,"n":"שרייבר, אברהם מירושלים","f":"שלמה מאיסטריק","b":"חתן רא\"ז ורנר מטבריה. רב אצל חסידי בויאן בירושלים וראש כולל \"תפארת ישראל\"."},{"i":55944,"n":"שרייבר, אליהו בצלאל","f":"דוד מטורקא","bt":"תקמו","bp":"טורקא","b":"בעל אדמות ועיבד בעצמו את אדמתו כשספר הש\"ך פתוח לפניו על המחרשה. הנהיג בעיירה את אמירת \"ויצמח פורקניה\"."},{"i":55945,"n":"שרייבר, אפרים מצרפת","b":"חבר באסיפה היהודית צרפתית-תקף, יחד עם אברהם פיקארט, פנחס אטראט."},{"i":55946,"n":"שרייבר, אשר אנשיל מלמברג","dt":"תש..","b":"רב בלמברג (של רובא זולקיב). נספה בשואה. בנו ר משה ממיסדי \"בני עקיבא\"."},{"i":55947,"n":"שרייבר, בנימין אליעזר מטורקא","f":"יהושע נחמן מטורקא","bt":"תרנח","bp":"צורטקוב","dt":"תשמג","b":"חסיד בויאן. חתן הגביר ר נחום מאיר הלר מקולומיאה. יסד את ישיבת \"תפארת ישראל\" ובראשה העמיד את ר משולם אפטייקר. ניצל מהשואה כשברח עם קבוצה מהקרון בדרך לאושביץ - ורמ\"ד וייסמנדל שילם הון לאיכרים לבל יסגירום. התישב בוינה ועסק בשיקום החיים היהודיים, נבחר כנשיא אגו\"י ותמך בפליטים. ר בן ציון יעקובוביץ ב\"זכור ימות עולם\" מתאר את פעולותיו. בזיוו\"ש חתן ר שלמה יוסף לנדוי נכד הברוך טעם. חתנו - ר עקיבא שרייבר מאנטורפן נכד החת\"ס. חתני בנות אשתו - ר משה יהודה שלזינגר ר\"מ בקול תורה בירושלים, ור ישראל ליב פרידמן מלוגנו."},{"i":55948,"n":"שרייבר, דב ברל מקענטי","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":55949,"n":"שרייבר, דוד מטורקא","bp":"פפד\"מ","b":"עבר מפפד\"מ לטורקא-תקכד - לבקשת המושל שיביא עמו יהודים - ויסד שם את הישוב היהודי והיה הרב הראשון. מקור השם מנכרים שראוהו מרבה לכתוב חדושי תורה."},{"i":55950,"n":"שרייבר, זלמן מנישאווי","b":"רב בנישאווי"},{"i":55951,"n":"שרייבר, יהושע מברזנא","dt":"תשד","b":"מו\"צ בברזנא"},{"i":55952,"n":"שרייבר, יהושע נחמן מטורקא","f":"שמואל מטורקא","bt":"תרכו","bp":"טורקא","dt":"תשב","b":"חסיד בויאן. חתן ר שלמה ערטיל, ובזיוו\"ש חתן ר בנימין אליעזר רוזנבך מצורטקוב. נספה בשואה."},{"i":55953,"n":"שרייבר, יוסף ליב מאסאד","f":"פסח מעיר חדש","bt":"תרטו","bp":"עיר חדש","dt":"תרעט - תשרי","dp":"אסאד","b":"תלמיד השב\"ס. חתן ר פנחס שטיין מטירעק-סנט מיקלוש. רב בוינקוועצי-תרלח, אסאד-תרמא."},{"i":55954,"n":"שרייבר, יעקב","dt":"תשד","b":"רב בקירכדורף"},{"i":55955,"n":"שרייבר, יעקב","dt":"תשג","b":"רב ביארדענאוו"},{"i":55956,"n":"שרייבר, ישראל","f":"שלמה מאיסטריק","bt":"תרפז","bp":"למברג","b":"עלה בילדותו לירושלים. משב\"ק אצל האדמורים מבויאן הוסיאטין ובוהוש. חתן ר חיים דוד ידלר-גולדברג."},{"i":55957,"n":"שרייבר, ישראל מיורדנוב","f":"נפתלי הרץ","bt":"תרטז","bp":"למברג","dt":"תרפט","b":"חתן ר ברוך נבנצל מוישניצא. חסיד האדמור ר שלמה מבובוב מוישניצא. רב ביורדנוב-תרמז עם הקהלות הסמוכות (ראבקע ומאקוב) על מקום אביו ביחד עם גיסו ר אלקנה זוברמן (שאותו מינה חותנו בחייו). חתנו ר אלקנה זוברמן על מקומו אחריו."},{"i":55958,"n":"שרייבר, ישראל מלמברג","f":"אנשל?","b":"מחכמי למברג. תשובה אליו ב\"חזון נחום\"-תרץ."},{"i":55959,"n":"שרייבר, משה","dt":"תרעד - כב חשון","b":"רב בפרעטשין"},{"i":55960,"n":"שרייבר, משה","f":"אשר אנשל מלמברג","bt":"תרסב","dt":"תשכג","dp":"תל אביב","b":"מהנהלת ה\"חלוץ המזרחי\" וממיסדי בני עקיבא. עלה לארץ."},{"i":55961,"n":"שרייבר, משה מברוד","f":"נחמן","b":"מחכמי ברודי, עבר לפודקמין ותשובה אליו ב\"כנויי נדרים\"."},{"i":55962,"n":"שרייבר, עקיבא מלמברג","f":"שמעון סופר מערלוי","b":"גדל אצל אביו חורגו ר יצחק שמלקיס, והיה מחכמי למברג-תרס."},{"i":55963,"n":"שרייבר, פסח מעיר חדש","f":"יוסף ליב שרייבר-דיטש","b":"מחכמי עיר חדש. בנו ר יוסף ליב רב באסאד."},{"i":55964,"n":"שרייבר, צבי הירש","b":"רב בפאטיק-ק\"צ"},{"i":55965,"n":"שרייבר, צבי הירש","f":"שלום סופר","dt":"תשד","b":"רב בברעזנא"},{"i":55966,"n":"שרייבר, צבי הירש ליב מטורקא","f":"אליהו בצלאל מטורקא","b":"החליף שו\"ת עם גדולי דורו. האב\"ד ר אליעזר מישל השיב לו-תרעט ב\"משנת אליעזר\" לבוסניץ (בוהמיה)."},{"i":55967,"n":"שרייבר, צבי יהודה מטורקא","b":"רב בטורקא-תרל."},{"i":55968,"n":"שרייבר, שלום מיארדאן","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":55969,"n":"שרייבר, שלמה זלמן מפבנזיק","b":"אב\"ד פבונזיק, ניעשאווא, מדפיס בוארשא."},{"i":55970,"n":"שרייבר, שלמה מאיסטריק","f":"צבי","k":"בעל בית שלמה","bt":"תרן","bp":"איסטריק","dt":"תשלו","b":"הרביץ תורה מגיל טו במשך כ-70 שנה. חתן ר אהרן רטר. עסק בתורה ובמסחר. עלה לארץ-תרצה, וכיהן כראש ישיבת חיי עולם וראש ועד הרבנים של אגו\"י בירושלים. חסיד רוזין. חיבר \"בית שלמה\" ירושלים תשכה."},{"i":55971,"n":"שרייבר, שמואל מטורקא","f":"צבי הירש ליב מטורקא","bt":"תרו","dt":"תרפד","b":"גביר תלמיד חכם בטורקא, חסיד שיניבה וחסיד צאנד."},{"i":55972,"n":"שרייבר-דיטש, יוסף ליב מעיר חדש","b":"אב\"ד עיר חדש. בנו ר פסח מעיר חדש."},{"i":55973,"n":"שריימן, משה מפיליווא","f":"דב","bt":"תרכא","b":"רב בפיליווא-פודוליה-תרן."},{"i":55974,"n":"שריינר, מרטון מצ'ורגוי","b":"רב בקהילה הניאולוגית בצ'ורגוי-מחוז ואלא, ואח\"כ פרופ' בבית הספר למדעי היהדות בברלין."},{"i":55975,"n":"שרייר, אהרן הלוי ממילניצה","f":"אורי שרגא פיבל","k":"בעל מעדה בגד","bt":"תריז","dt":"תרנו","b":"רב במילניצה (והיה במחלוקת עם ר משה רוזנפלד), רב בטלוסט, בוטושן-תרנד. חיבר \"מעדה בגד\" ונדפס בסוף ספר אביו \"משמרת הקודש\" למברג תרלט."},{"i":55976,"n":"שרייר, אורי שרגא פיבל מברודשי","f":"ישראל משה הלוי","k":"בעל גדולי הקדש","bt":"תקעז","bp":"ברודשין","dt":"תרנט - ה כסלו","b":"גיסו היה ר יחיאל שמרלר מברודשין שעלה לצפת. תלמיד \"הדעת קדושים\". חתן הגביר ר אליהו צבי גוטפריד מבוצאץ, ובזיוו\"ש חתן נכדת ר יצחק יוסף תאומים. ולמד אצל ר נתן נטע מלר בפודהייץ, ואצל ר שמחה יואל מבוברקא בעל \"חלת לחם\". המנחת חינוך שפגשו - תמה שעוסק במסחר והפציר בו להסכים לרבנות. רב בתר\"י. רב בברודשין-תרכה, קולומיאה אצל ר הלל ליכטנשטין, דחה הצעה לרבנות מצפת. מראשי חברת \"אהבת ציון\" בטרנוב שיסדה את המושבה \"מחניים\" ליד ראש פינה. והיה מראשי הציונות בגליציה. (היה במחלוקת עם האדמור משיניבה אודות הציונות). הוציא \"אוהב משפט\" למברג תרמז והוא מכתבי רבנים אודות מחלוקת שדן בה בין חצרות צורטקוב וינזיץ וסיגט."},{"i":55977,"n":"שרייר, ישראל","f":"חיים הלוי","bt":"תרנה","bp":"סטניסלב","dt":"תשמה","b":"עסקן עדת החרדים בעירו ופעיל שלומי ישראל בגרמניה. עלה לפתח תקוה ומנהל המחלקה לשרותי דת בהסתדרות."},{"i":55978,"n":"שרייר, מרדכי מבורשטין","b":"רב בבורשטין-תרכא."},{"i":55979,"n":"שרייר, ראובן מסטניסלב","b":"פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":55980,"n":"שריל, זלמן מהאזנפוט","dt":"תשג","b":"רב בהאזנפוט. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":55981,"n":"שרים, יוסף","dt":"תרע - ב אלול","b":"מגדולי רבני ארם צובה"},{"i":55982,"n":"שרים, יוסף חיים מחלב","k":"בעל דרשות - כת\"י","bt":"תריא","bp":"חלב","b":"עלה לארץ בילדותו, מחכמי ירושלים, בשליחות קהלות חברון וירושלים בעירק הודו ועוד. נזכר אצל ה\"בן איש חי\"."},{"i":55983,"n":"שרים, יצחק מאר\"ץ","f":"יוסף","k":"בעל באר יצחק","bt":"תקעח","dt":"תרלג - טז תשרי","dp":"חלב","b":"מחמכי אר\"ץ, התעשר בסוף ימיו ותרם רבות לקהלה. חיבר \"הדר עזר\", \"פי הבאר\", ועוד."},{"i":55984,"n":"שרים, יצחק מחלב וירושלים","f":"יוסף","k":"בעל חדושי מהריץ שרים","bt":"תרך","bp":"ארם צובא","dt":"תרסט - כא שבט","dp":"ירושלים","b":"מחכמי ארם צובא, נכדו של ר יצחק שרים בעל \"הדר עוזר\", בשנת תרנו עלה לירושלים והתצטרף ל\"בית אל\" והיה מרבניה ואחר כך מראשי ישיבת \"רחובות הנהר\". סירב לתפקיד ה\"ראשון לציון\". חיבר \"חדושי מהריץ שרים\" ירושלים תרפח, \"שמות הגיטין\" ועוד בכתב יד ובספרי אחרים."},{"i":55985,"n":"שרים, יצחק מירושלים","f":"דוד","dt":"תרצג - כז ניסן","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":55986,"n":"שרים, עזרא מירושלים","f":"יצחק","bt":"תרנו","dt":"תשכג","dp":"ירושלים","b":"עלה בילדותו מחלב, תלמיד ר שלמה לאניאדו, ישיבת \"טובי ישבעו\", \"אהל מועד\". מחכמי ירושלים. גבאי וממיסדי ישיבת \"פורת יוסף\" בירושלים."},{"i":55987,"n":"שרים, רחמים","dt":"תרסא - כא תשרי","b":"מגדולי רבני ארם צובה"},{"i":55988,"n":"שרים, רחמים מחלב","f":"דוד","k":"בעל שערי רחמים","bt":"תרכט","bp":"עינתב-קיליז-חלב","dt":"תרצד - כב שבט","dp":"ירושלים","b":"נכדו של ר יצחק שרים. עלה לירושלים ולמד בישיבת המקובלים \"רחובות הנהר\". חיבר \"שערי רחמים\" ירושלים תרפו, ועוד."},{"i":55989,"n":"שרירא גאון פומפודיתא","f":"רב חנינא בן רב יהודה","k":"בעל אגרת רב שרירא","b":"גאון פומפודיתא, אביו של רב האי גאון, היה מקודם אב\"ד תחת הגאון רב נחמיה, ונתמנה לגאון על מקומו אחריו. מגדולי המשיבים בכל התפוצות, חתנו ר אליהו הזקן ממנש אחיו של ר יקותיאל ותלמיד רבנו גרשום מאור הגולה. כנראה נהרג עק\"ה ע\"י השלטונות המוסלמים בהיותו כבן מאה."},{"i":55990,"n":"שרלואי, אליעזר","bt":"תרמד","dt":"תשב","b":"מחנך,דיין באמסטרדם-תרע\"ב,רב שם בתרצ\"ו"},{"i":55991,"n":"שרלוויל, מאיר (מאהיר) מאלגיר","f":"מנחם","bt":"תקעד","dt":"תרמח","b":"רב בווהראן-תרכד-תרלח מטעם הקונסיטואר, ופעל להפצת תרבות צרפת בין היהודים."},{"i":55992,"n":"שרליך, יוסף אבלס","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":55993,"n":"שרלין, חיים ברוך מירושלים","f":"ניסן מירושלים","b":"מחכמי ירושלים. תלמיד ר צבי יהושע מיכל."},{"i":55994,"n":"שרלין, נחום משקלוב וירושלים","f":"ניסן","dp":"ירושלים","b":"מחכמי ירושלים, חתם בקונטרס ה\"משמורים\"-תרז. אבי משפחת שרלין בירושלים."},{"i":55995,"n":"שרלין, ניסן מירושלים","f":"נחום משקלוב","bt":"תקצד","bp":"שקלוב","dt":"תרלג","dp":"ביחוב-ישן","b":"עלה לירושלים בילדותו עם אביו. חתן נכדת ר\"י צייטלין משקלוב. תלמיד ר משה יהודה ליב זילברברג בעל \"זית רענן\", ישיבת \"חכם שלמה\" בביירות-לבנון, בשליחות כולל רייסין ונפטר בשליחותו. בנו - ר חיים ברוך."},{"i":55996,"n":"שרליף, זאב וולף מרוזוודוב","f":"שלמה","k":"בעל רמיזי תורה","b":"חסיד ר משה הורביץ האדמור מרוזוודוב. מלמד גפ\"ת ברוזוודוב כ-45 שנה. חיבר \"רמיזי תורה\" מונקטש תרעד."},{"i":55997,"n":"שרמן, אברהם יוסף מוויניטש","dt":"תשג","b":"רב בוויניטש ובקראקא. נספה בשואה."},{"i":55998,"n":"שרמן, יצחק שלמה יואל מראוונא","f":"שמואל","r":"רב באהלאוו, ובבאסאן, ואחר כך בקאלייערקא, ואח\"כ ברוונא","bt":"תרד","dt":"בערך תרע","b":"תלמיד ישיבת שקלוב, פאלאצק, ר שנאור זלמן בעל \"תורת חסד\", ראדין (ולמד ביחד עם החפץ חיים), ר אליהו שיק מלידא, ר מרדכי מלצר מלידא, ר ישראל נח מניעזין. חתן ר אברהם בליטשטין. רב באהילב(=אהלאוו) ובאסאן והגליל-תרכז, קאליירקה, ראוונא(=רובנה)-ווהלין-תרמה וראש ישיבה. נסמך מאת: ר אריה המוניר בעל \"באר היטב\", ר יוסף זכריה שטרן בעל \"זכרון יהוסף\", ר מרדכי דב מהורנסטיפל, ר ישראל נח. פרסם מאמרים ב\"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה. תשובות ממנו ב\"שדי חמד\", \"זכר יהוסף\" ו\"שדה יצחק\" לר יצחק חיות. חיבר \"בית יש\"י\", \"פתחי שערים\", ועוד - בכת\"י. בניו: ר מנשה, ר שניאור זלמן ברוך. חתניו: ר דובער שפירא, ר שמואל ישעיהו ליזאק, ר יהושע השל אבעל מדיביסאר.","bk":[["בית יש\"י - חיבור תורה שבכתב עם תורה שבע\"פ לפי סדר השו\"ע להוכיח שלכל השו\"ע יש מקור בתנ\"ך, ושו\"ת (כת\"י)",""],["פתחי שערים - מחיצות שבת וסוכה (כת\"י)",""]]},{"i":55999,"n":"שרמן, ישעיה מקאשוי","f":"משה","bt":"תרי","dt":"תרצו - כג תשרי","b":"תלמיד הכת\"ס. רב בקאשוי ומיסדי הקהלה החרדית שם."},{"i":56000,"n":"שרמן, משה יהודה","b":"רב באלהרינין-תר\"כ"},{"i":56001,"n":"שרמן, צבי הירש מליניץ","f":"משה יהודה מאלהרינין","bt":"תרכ","b":"מצאצאי רמ\"מ מזלוטשוב, ונכד-אבי אמו ר מנדל מקישינוב המכונה \"מענדילי זשירינער\". רב בליניץ-פלך קיוב-תרע."},{"i":56002,"n":"שרמן, שלום מלודז","b":"ר\"מ בישיבת \"בית אברהם\" בלודז. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":56003,"n":"שרמן, שלמה יואל","b":"רב ברובנה"},{"i":56004,"n":"שרנצל, אליעזר מלבוב","b":"פו\"מ בלבוב"},{"i":56005,"n":"שרנצל, יחיאל מיכל מיזלוביץ","b":"רב ביזלוביץ על מקום ר שמעון כץ שרנצלס בעל \"איתן האזרחי\"."},{"i":56006,"n":"שרנצל, ישראל מלבוב","b":"מגדולי חכמי לבוב-ר\"ל"},{"i":56007,"n":"שרנצל, נפתלי מאיר מקראקא","dt":"תרלט - ד ניסן","dp":"קראקא","b":"רב בקראקא-תרם, ועל מקומו אחריו ר ליבוש וולפגנג ור קלמן כץ גוטוירט."},{"i":56008,"n":"שרנצל, שלמה מהולשיץ","f":"יעקב","dt":"תשג","b":"נכד ר אברהם אריה באבד ממיקוליניץ. רב בהולשיץ-תרע, ראווה על מקום ר יעקב לינסקר. ממקורבי המזרחי. נספה בשואה."},{"i":56009,"n":"שרנצלס, יצחק מלבוב (רפפורט?)","f":"אברהם-איתן האזרחי?","bt":"שס?","bp":"לבוב?","b":"רב בלבוב-שפ, בנה בית כנסת. אולי הוא שהיה בנו של ר אברהם רפפורט בעל איתן האזרחי שהביא בספרו דרשה שדרש בברית המילה בשנת שס. נזכר ב\"פתח השער\" בספר נכדו - ר מנחם מנלי מלבוב -\"זרע ברוך\". חתנו - ר ברמן בן מאיר ליוויש (לוי) מלבוב."},{"i":56010,"n":"שרנצלס, מרדכי מלבוב","f":"יצחק מלבוב","b":"מגדולי לבוב-שנת ת'. חתנו - ר אברהם שרנצלס-רפפורט והספידו בספרו \"איתן האזרחי\"."},{"i":56011,"n":"שרעבי שלום בן יצחק מזרחי","bt":"1720","dt":"ה'תקלז 1777","bk":[["אמת ושלום",""],["ישב רוחו",""],["כונות פרטיות",""],["סדור נהר שלום",""],["סידור תפילה להרש\"ש",""],["שר שלום",""]]},{"i":56012,"n":"שרעבי, מרדכי יפת מירושלים","f":"יהודה יפת תעיזי","r":"זקן המקובלים בירושלים","bt":"תרעב","bp":"תעיז-תימן","dt":"תשמד - כ חשון","dp":"ירושלים","b":"מגדולי המקובלים בדורו. מצאצאי הרש\"ש (=ר שלום שרעבי), נכד ר יפת בן אברהם רב מחוז שרעב-תימן, ולאחר שנתייתם גדל אצל זקנו. עלה לארץ-תרצא (דרך עדן ופורט סעיד - בעזרת מבריחי גבול). הגיע לרחובות ומשם לירושלים ושינה משפחתו מיפת לשרעבי. היה מחכמי \"בית אל\" ולמד אצל ר שאול דוויק הכהן, ולמד עם ר יעקב לופס. ראש ישיבת המקובלים \"נהר שלום\"."},{"i":56013,"n":"שרעבי, רחמים מתימן","k":"בעל מנחת שלום","b":"מחכמי תימן המאה ה-19."},{"i":56014,"n":"שרף, אליהו מביליץ","f":"משה יעקב מביליץ","bt":"תרנח","bp":"ביליץ","b":"חתן ר אלכסנדר זיסקינד פריי מביליץ. ניצל מהשואה כשנלקח לסיביר וברח. חזר לפולין, עבר לפריס ולארה\"ב. חסיד בובוב ותורם חשוב לחסידות. פרש מעסקיו בלונג איילנד כדי לעסוק בתורה."},{"i":56015,"n":"שרף, אשר ישעיה","f":"אליהו מביליץ","bt":"תרפג","bp":"ביאלא","b":"תלמיד רב\"צ מבובוב. ניצל מהשואה כשגורש לסיביר. גרו שם בלנינבד. חתן ר יחזקאל לעזער (החתונה בשנת תשה בסמרקנד). חזר לפולין, עבר לארה\"ב ומחשובי חסידי בובוב."},{"i":56016,"n":"שרף, דוד מקאלווריה","f":"משה יעקב מזאטור","bt":"תקצה","bp":"זאטור","b":"חתן רנ\"נ אייזן מוישניצה, עבר לקלווריה-גליציה ורוב תושביה לעתיד נמנו על צאצאיו. טרח בהדפסת ספרי אביו לאחר פטירתו ולשם כך עבר לתקופה לפשמישל."},{"i":56017,"n":"שרף, יהודה מירושלים ומצרים","dt":"שצב או תלו","dp":"ליוורנו","b":"תלמיד חבר לר זרחיה גוטא, ותלמיד ר אברהם איסכנדרי, היה במצרים והסכים שם על ספר \"כסא כבוד\" לר יהודה עבאס (בכתי). ר משה בן חביב בספרו \"גט פשוט\" מביא שמועה ממנו, וכן ר שמואל ויטאל בספרו \"באר מים חיים\". בשליחות בליוורנו ושם למד אצלו ר חזקיה די סילבה בעל \"פרי חדש\". ר משה ן חביב מירושלים העיד עליו שהיה אחד משני גדולי הדור בזמנו. מתלמידיו גם - ר יהודה פרימו ור מאיר פאפירש. נספד בספר \"מדרש אליהו\"."},{"i":56018,"n":"שרף, יהושע השל מפפד\"מ","k":"בעל מור ואהלות","b":"רב בפפד\"מ-תרכד. חיבר \"מור ואהלות - ספיח קציר\" - אמשטרדם תרמז. העניק תעודת סמיכה וחבר לתלמידו ר יוסף ייאדיל בן אליעזר פונגס-שטאדט-תרכד (ומצוה את תלמידו שלא ללכת לריקודי נשים, שלא לישב במשחקי קלפים זולת חנוכה ופורים עם בני משפחתו וכו'."},{"i":56019,"n":"שרף, יעקב מקראקא","f":"משה חיים הלוי","b":"מחכמי קראקא."},{"i":56020,"n":"שרף, מאיר מארה\"ב","f":"אליעזר בן אהרן ישראל","k":"בעל אמרי שפר","bt":"תרמ","bp":"סמאליאן-פלך מוהילוב","b":"תלמיד ישיבת סלונים, סלובודקא. נסמך מאת: ר משה דנישבסקי, ר שלמה זלמן זיסל שיינין מועליזש, ר צבי בענינסון, ר רפאל שפירא, ר משה שמואל שפירא, ר שמריה נח. חתן ר חיים דובר מטשעריי. רב בדוברבנא-פלך מוהילוב-תרסג, לאדי, קאזאן, לוהאנסק, הצליח לצאת מרוסיה הקומוניסטית והגיע לארה\"ב-תרפה, וכיהן כרב בניו יורק. חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":56021,"n":"שרף, משה יוסף מזבלטוב","f":"אברהם אריה ליב","k":"בעל מעין החכמה","bt":"תקי","dt":"תקצא","dp":"זלישטשיק","b":"רב בזבלטוב-תקנט, זלישטשיק. חיבר \"מעין החכמה\" למברג תקצד."},{"i":56022,"n":"שרף, משה יעקב יעקל מזאטור","f":"אפרים מאושפיצין","k":"בעל דרכי יושר","r":"ראב\"ד ומו\"צ בק\"ק אושפיצין","bt":"תקמו","bp":"פולין","dt":"תרכט - ג ניסן","b":"תלמיד ר צבי הירש חריף הלר וה\"אריה דבי עילאי\" מוישניצה, ור דב בעריש פרומר מאושפיצין. מקורב לגדולי האדמורים ובהם לבעל \"מאור ושמש\" ואף סידר את ספרו. רב בזאטור-תקעט, קשנוב-תרג (ופינהו לר דוד בן הדברי חיים). רב באושפיצין-תרה אצל ר אלעזר מינץ. חיבר \"דרכי יושר\" פרמישלא תרלב, ועוד.","bk":[["דרכי יושר –",""]]},{"i":56023,"n":"שרף, משה יעקב מביליץ","f":"אשר ישעיה מקלוואריה","bt":"תרל","dt":"תשג","b":"חסיד בובוב. שו\"ב בביליץ-תרסב. חתן ר יהודה ליביש ברונר. נספה בשואה."},{"i":56024,"n":"שרפברג, ישעיה מזלישטשיק","f":"אברהם","k":"בעל דרך מצותיך","bt":"תר","dt":"תרע","b":"רב בזלישטשיק, זבלטוב. חסיד רוזין. חיבר \"דרך מצותיך\" על \"כתר תורה\" הוסיאטין תרסז."},{"i":56025,"n":"שרפזון, י' יונה גבריאל","bt":"תרמב","dt":"תרצה","b":"רב בשעניץ-תרפ\"ג"},{"i":56026,"n":"שרקנסקי, אברהם מיכל מארה\"ב","f":"דובער","bp":"ליובאווא-ליד קלוואריא","b":"סופר ומשורר בארה\"ב."},{"i":56027,"n":"שרשבסקי, אברהם חיים מסטאכוב","f":"אריה ליב","bt":"תרלג","bp":"דראהיטשין-פלך גרודנא","b":"מצאצאי בעל \"כנסת יחזקאל\". תלמיד ישיבת וולוזין. רב סטאכוב-פלך מינסק-תרסח."},{"i":56028,"n":"שרשבסקי, אברהם משה מבוסטון","k":"בעל נחל אברהם","bt":"תריז","bp":"בוטען","dt":"תרפד - ב סיון","b":"תלמיד ר ישראל בעל \"כנסת ישראל\", ישיבת וולוזין אצל ר יוסף דב סולוביציק והנצי\"ב. היגר לארה\"ב-תרנז, רב בפורטלנד-מיין-תרנב, בוסטון-תרנח. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":56029,"n":"שרשבסקי, אליהו ישראל","f":"יהודה","k":"בעל ספר הקהל","bp":"וילנא","dt":"1890","dp":"וילנא","b":"אביו היה מלמד בביהמ\"ד למורות וחוקר תלמוד. פרסם מאמרים בכתבי עת עבריים. חיבר ספר הקהל כנגד ספר הקהל של ברפמן. פרסם מאמר ב\"נוויא וורעמיא\" ובו שולל את המקורות עליהם הסתמך ברפמן. ?? לא באוצר ??"},{"i":56030,"n":"שרשבסקי, אליעזר","b":"רב בנייאסוויז-תר\"ל"},{"i":56031,"n":"שרשבסקי, אליעזר מטלז","f":"שמרל","b":"מראשי קהלת טלז-תקץ בזמן המרד הפולני."},{"i":56032,"n":"שרשבסקי, דוד","b":"מו\"צ בטויראגן"},{"i":56033,"n":"שרשבסקי, דוד משה","f":"ישראל איזנשטט","b":"נכד ר דוד יוסף איזנשטט ממיר."},{"i":56034,"n":"שרשבסקי, חנוך הניך מלומזא","f":"יצחק אליעזר מנעשויז","bt":"תרכ","b":"תלמיד ישיבת וולוזין, כולל קובנא. חתן ר אהרן קויפמן מוילקומיר וישב אצלו, ובזיוו\"ש חתן ר אהרן מזעטיל-אחיו של ה\"חפץ חיים\". רב בסאלעצניק-פלך וילנא-תרסח ובביניקאני הסמוכה, לומזה. פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח. נסמך מאת: ר יצחק אלחנן מקובנא, ר משה דנישבסקי."},{"i":56035,"n":"שרשבסקי, יהודה אידל מוילנא","f":"בנימין מסלונים","k":"בעל כור לזהב","bt":"1804","bp":"ראזינאי - סלונים","dt":"תרכז - י תשרי","dp":"קובנא","b":"תלמיד ר מאיר מיאלובקה. חברו של ר מרדכי זקהיים מפינסק. ממשכילי וילנא. מורה לתלמוד בביהמ\"ד לרבנים בוילנא. פרסם ב\"הכרמל\", המגיד\". חיבר דרוש בשם \"עוז מלך\". הניח קונטרס ביאורים לכתה\"ק בכת\"י. בניו: ר שמשון, ר אליהו ישראל, ר יום טוב."},{"i":56036,"n":"שרשבסקי, יצחק אליעזר ליפמן","bt":"תר","bp":"וילנא","dt":"תרסח - ה שבט","dp":"נעשויז","b":"נכד ר שמואל בן אביגדור אב\"ד וילנא. תלמיד ישיבות וולוזין, סלובודקה. רב בסילצניק-תרכד, שירווינט-ליד וילקומיר-תרכט או תרמו, ז'וסלי-תרמג, נאשוויז(=נאסוויז, נעשויז)-תרמט."},{"i":56037,"n":"שרשבסקי, יצחק ליפמן (אפמן)","dt":"תרסח","b":"רב בנשביז(=נעשוויז)-תרמה. חתנו ר ירחמיאל יצחק צבי בורגמן."},{"i":56038,"n":"שרשבסקי, מאיר מבאקשט","dt":"תשג","b":"רב בבאקשט"},{"i":56039,"n":"שרשבסקי, מנחם מנדל מירושלים","bt":"תרה","dt":"תרפט","dp":"ירושלים","b":"רב בקאסובה, עלה לירושלים בשנת תרפז."},{"i":56040,"n":"שרשבסקי, צבי הכהן","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":56041,"n":"שרשבסקי, שמואל יוסף","bt":"1831","bp":"טאווריג","dt":"1906","b":"תלמיד ישיבת קרוז', ביהמ\"ד לרבנים בזיטומיר. אוני' ברסלאו. היגר לארה\"ב-1854 והתנצר. נסע לסין ותרגם את התנ\"ך לסינית. עבר לטוקיו."},{"i":56042,"n":"שרשובר, חיים - פרלמוטר","f":"זבולון יעקב","k":"בעל אלף אומר","dt":"תקף","b":"רב בשרשוב, מארימאפול-תקמ כ-40 שנה וחתנו ר יהודה ליב חרלפ על מקומו אחריו-תרכה. חיבר גם \"שירה לחיים\" ועוד."},{"i":56043,"n":"ששון אהרן בן יוסף","bt":"1650","dt":"ה'שפח 1628","bk":[["תורת אמת",""]]},{"i":56044,"n":"ששון אשכנזי","b":"מחכמי ירושלים, מוזכר בספרו של ר משולם מוולטרא בשנת רמא."},{"i":56045,"n":"ששון בן משה","bt":"1823","dt":"ה'תרסג 1903","bk":[["פתח עינים",""],["שמן ששון",""]]},{"i":56046,"n":"ששון דוד בן סלימאן","bt":"1880","dt":"ה'תשב 1942","bk":[["מעט דבש",""]]},{"i":56047,"n":"ששון הלוי מבגדד","f":"משה","bt":"תרעא","bp":"בגדד","dt":"תשנב - טז סיון","dp":"ירושלים","b":"מחכמי בגדד, תלמיד ר צדקה חוצין, חברו של ר יצחק כדורי, עלה לירושלים-תרצב, היה דורש במוצ\"ש את השיעור המוקדם לפני שיעורו של ר עובדיה יוסף."},{"i":56048,"n":"ששון הלוי סמוחה מבגדד","f":"אליהו בן משה","dt":"תרעא - כב כסלו","b":"דיין בבגדד-תרה וכיהן כחכם באשי. תלמיד ר עבדאללה סומך."},{"i":56049,"n":"ששון ישראל מבגדד","bt":"תקף","dt":"תרעא - כז אלול","dp":"בגדד","b":"מחכמי בגדד, תלמיד ר עבדאללה סומך. רב ומשורר בבגדד."},{"i":56050,"n":"ששון מבגדד","f":"צאלח בן דוד","bt":"תקי","bp":"בגדד","dt":"תקץ - טבת - לפנ","dp":"אבושהר","b":"ראש משפחת ששון מבגדד והודו."},{"i":56051,"n":"ששון מבגדד","f":"יחזקאל ראובן ששון","b":"גביר בבגדד, סייע בבנין ה\"חורבה\" בירושלים יחד עם אחיו משה - לפי צוואת אביהם."},{"i":56052,"n":"ששון מירושלים","f":"משה","b":"מחכמי ישיבת \"בית אל\" בירושלים. הו\"ל עם אחיו ר אפרים \"ספר התכונה\"-תרך."},{"i":56053,"n":"ששון מרדכי מירושלים","k":"בעל מקראי קדש","b":"מחכמי ירושלים-תרג."},{"i":56054,"n":"ששון ן, אברהם ממזיתרא","b":"רב במזיתרא-שנות ה-ש'."},{"i":56055,"n":"ששון ן, אהרן מאזמיר","dt":"תל - ו חשון","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":56056,"n":"ששון ן, שמואל מספרד","f":"צדיק","k":"בעל עץ חיים","b":"מחכמי ספרד בזמן ר יצחק קנפנטון. חיבר קיצור לטור אורח חיים בשם \"עץ חיים\". חיבר פיוטים ומהם שנכנסו למחזור ספרד."},{"i":56057,"n":"ששון, אברהם מחלב","f":"ישועה-ישועות ישראל","dt":"תרל - כה כסלו","dp":"חלב","b":"נכד ר ישראל ששון בכל \"כנסת ישראל\" (והו\"ל את ספר זקנו). פייטן מחכמי ארם צובא, הקים דפוס בחלב-תרכה. הו\"ל ספרים מכת\"י קדמונים. בניו - המדפיסים ר אליהו, ר משה חי."},{"i":56058,"n":"ששון, אברהם מספרד ואיטליה","k":"בעל קול מבשר","b":"מקובל, ממגורשי ספרד, רב באיטליה. מחכמי איטליה-ש'. חיבר ספר על עניני הגאולה בשם \"קול ששון\" - ונציה שסה, \"קול מבשר\", \"אפריון שלמה\" - ונציה, ועוד."},{"i":56059,"n":"ששון, אהרן מקושטא - הנכד","f":"יצחק","k":"בעל הן ישלח","bt":"שפט-שצ","b":"מחכמי קושטא. בן אחותו של ר חיים בנבנישתי בעל \"כנסת הגדולה\". (יש שרשמו תאריך לידתו בטעות - תפט)."},{"i":56060,"n":"ששון, אהרן משלוניקי - הזקן","f":"יוסף","k":"בעל תורת אמת","bt":"שטו","bp":"קושטא","b":"תלמיד ר מרדכי מטלון. חתן ר שלמה הלוי הזקן, וגיסו של ר דוד ן נחמיאש. מגדולי הפוסקים, מרביץ תורה בשלוניקי, קושטא-שסא, חיבר \"תורת אמת\", וחדושים על הרמב\"ם - ואבדו. בנו ר יוסף ששון, ר אהרן ששון, ומנכדיו ר יעקב בעל \"בני יעקב\", חתנו - ר מאיר בן אברהם די בוטון מגליפולי. מתלמידיו: ר חיים שבתי - מהרח\"ש, מהר\"ם קלעי משלוניקי, ר שבתי יונה בעל \"שי למורא\", ר חיים אלפנדרי."},{"i":56061,"n":"ששון, אלברט (עבדללה) מלונדון","f":"דוד צאלח מבגדד ובומב","b":"ראש חברת \"דוד ששון\" בבומביי-הודו, עבר ללונדון וקיבל תואר ברון. יסד מוסדות חינוך וצדקה."},{"i":56062,"n":"ששון, אליהו חי מחלב","b":"מדפיס בחלב, למד את מלאכת הדפוס בליוורנו-תרכד, ובשובו יסד עם אביו ואחיו ר משה חי בית דפוס בחלב-תרכה."},{"i":56063,"n":"ששון, אליהו מבומבי","b":"גביר בבומבי-הודו, תרם להקמת ביהכ\"נ חב\"ד בירושלים-תרלד, כהמשך לתרומת אביו - דוד."},{"i":56064,"n":"ששון, ברוך ליב","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":56065,"n":"ששון, דוד מבומבי ולונדון","f":"סלימן דוד","k":"בעל מעט דבש","bt":"תרמא","bp":"בומבי","b":"תלמיד ר יצחק שמעון אגסי, ר יהושע אברהם אליהו, עבר ללונדון ועסק במחקר ורכש כתבי יד רבים. בתו - פרחה פויכטוונגר."},{"i":56066,"n":"ששון, דוד צאלח מבומבי","f":"צאלח מבגדד","bt":"תקנג","bp":"בגדד","dt":"תרכה - ה חשון","dp":"פונה-הודו","b":"אביו ברח מבגדד עם משפחתו לבומבי, גביר בהודו, תרם הרבה ליהודי ארץ ישראל, ובין היתר לבור מים ליד קבר רחל, מימן את ספרו של שטינשנידר - קובץ שירי משוררי הודו, יסד מוסדות חינוך ותרם הרבה לקהלה, בנה בית כנסת בפונא. חבר בפרלמנט בהודו. מאמר עליו ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב - מאת ר יעקב ספיר. בניו: עבדאלה, אליהו. גיסו - שלמה בן יחזקאל יהודה מבגדד וירושלים."},{"i":56067,"n":"ששון, חיים","b":"מחכמי קושטא"},{"i":56068,"n":"ששון, חיים משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"מהרוגי דולייא."},{"i":56069,"n":"ששון, חיים שלמה משלוניקי","b":"דיין בשלוניקי-תרג."},{"i":56070,"n":"ששון, יהודה ממצרים","dt":"תרטז - ו אלול","b":"מגדולי רבני מצרים"},{"i":56071,"n":"ששון, יוסף מאיר משלוניקי","k":"בעל מוסר השכל ודרכי","b":"מחכמי שלוניקי-תרג. תרגם \"ספר הברית\" ללאדינו בשם \"מוסר השכל\" ו\"דרכי האדם\" - יחד עם ר יצחק בכור אמאראג'י."},{"i":56072,"n":"ששון, יוסף מגליפולי","b":"מרביץ תורה בגאליפולי-ש\"ע"},{"i":56073,"n":"ששון, יוסף מחלב","dt":"תקצב - כה תמוז","b":"מרבני ארם צובה"},{"i":56074,"n":"ששון, יוסף משלוניקי","f":"משה","b":"דיין בשלוניקי-שמג, וסופר מומחה."},{"i":56075,"n":"ששון, יוסף משלוניקי וגליפולי","dt":"תרנב - ב תמוז","b":"מחכמי ירושלים,שד\"ר לאירופה,רב בנאפולי"},{"i":56076,"n":"ששון, יוסף משלוניקי וגליפולי","f":"אהרן","bp":"שלוניקי","b":"מחכמי שלוניקי, רב בגאליפולי. חתן ר אברהם די בוטון בעל \"לחם משנה\", וגיסו של ר מאיר די בוטון מגליפולי, גיסו גם של ר יוסף טרני-מהרי\"ט (היו נשואים לשתי אחיות)."},{"i":56077,"n":"ששון, יחזקאל מבגדד","bt":"תרטז","bp":"בגדד","dt":"תרצב - כט אב","dp":"פאריס","b":"מראשי הקהלה בבגדד, וחבר בבית הנבחרים התורכי ומקורב לשלטון התורכי, לאחר הכבוש הבריטי בעירק כיהן כשר האוצר והיה מקורב למלך עירק פייסל הראשון."},{"i":56078,"n":"ששון, יחזקאל מבצרה","b":"לאחר שנתייתם בילדותו גדל אצל זקנו בכפר \"אל כפל\" (שבו נמצא קבר יחזקאל הנביא). ראש ישיבה במקום הקבר בעזרתו של הגביר מנחם דניאל, ולאחר מכן רב בבצרה - בזמן מלחמת העולם ה-I."},{"i":56079,"n":"ששון, יחזקאל ראובן מעירק","b":"גביר בעירק, תרם להקמת בית כנסת \"החורבה\" בירושלים."},{"i":56080,"n":"ששון, יעקב אליהו דוד","f":"אליהו דוד ששון","b":"גביר בהודו? תרם עם אחיו עזרא אליהו דוד לבנין בית גבול אלמנה בירושלים."},{"i":56081,"n":"ששון, יעקב מצפת ושלוניקי","f":"ישראל ששון","k":"בעל בני יעקב","bt":"תמג - בערך","dt":"תעד","b":"מצאצאי ר אברהם ששון. מחכמי צפת, קושטא, שלוניקי. תלמיד ר יעקב אלפנדרי. חיבר \"בני יעקב\" קושטא תעד. בשנת תסב חתם על פסק דין בכפר פקיעין (בוקיעא) מובא בשות מהרי\"ט. נפטר צעיר ללא ילדים."},{"i":56082,"n":"ששון, יצחק מהורדנא","f":"אריה ליב","k":"בעל שמן ששון","dt":"תרל - ב אדר","dp":"הורדנא","b":"מגדולי הורדנא."},{"i":56083,"n":"ששון, יצחק מפאס","dt":"שפח","b":"מחכמי פאס - שנות ה-ר'-ש'. נספד ע\"י ר שאול סירירו."},{"i":56084,"n":"ששון, יצחק מקושטא","f":"אהרן-תורת אמת","b":"תלמיד ר אברהם מונסון. מחכמי קושטא-ת, גיסו של ר יהושע רפאל בנבנישתי - אחי הכנה\"ג המזכירו בספרו (ולפי רוזניס גיסו של ר חיים עצמו - נשא את אחותו של ר חיים). נזכר גם ב\"תורת אמת\". בנו - ר אהרן ששון ונקרא ע\"ש סבו."},{"i":56085,"n":"ששון, יצחק מרדכי מבגדד","b":"מחכמי בבגדד - שנות ה-תר', תלמידו ר שמעון אגסי."},{"i":56086,"n":"ששון, ישועה מחלב","f":"ישראל-כנסת ישראל","k":"בעל ישועות ישראל","b":"רב בחלב-תר."},{"i":56087,"n":"ששון, ישראל מאר\"ץ","k":"בעל כנסת ישראל","dt":"כה טבת","b":"מרבני דמשק, ארם צובה-תקע. נכדו - ר אברהם ששון הו\"ל את ספרו \"כנסת ישראל\"."},{"i":56088,"n":"ששון, מאיר מחלב","b":"רב בארם צובה-תרמ\"ה"},{"i":56089,"n":"ששון, מנחם מאזמיר","dt":"תמה - יא אדר","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":56090,"n":"ששון, מרדכי מירושלים","b":"מחכמי ירושלים-תר\"נ"},{"i":56091,"n":"ששון, משה מבגדד","f":"ששון מרדכי-קול ששון","k":"בעל ויאמר משה","b":"רב בבגדד."},{"i":56092,"n":"ששון, נסים ישראל מירושלים","dt":"תרנא","dp":"מוגדור","b":"מחכמי ירושלים, דיין העדה הספרדית, בשליחות במגרב, בהודו-תרמט, ונפטר בדרך שליחותו (בהודו או במרוקו)."},{"i":56093,"n":"ששון, סלימן דוד מבומבי","bt":"תרב","bp":"בומבי","dt":"תרנד - י אד\"ב","dp":"בומבי","b":"גביר בבומבי, שנהאי-סין, הונג-קונג, תרם ליהודי המזרח וארץ ישראל. חתן יחזקאל יהושע גבאי מבגדד, ואשתו - פרחה - גם היא אשת חסד."},{"i":56094,"n":"ששון, סלימן מלונדון","f":"דוד מלונדון","k":"בעל נתן חכמה לשלמה","bt":"תרעה","bp":"לונדון","dt":"תשמה - ז סיון","dp":"ירושלים","b":"מחכמי קהלת הספרדים בלונדון. תלמיד ישיבת \"עץ חיים\" בלונדון ולמד אצל ר אליהו דסלר, נסמך מאת ר יצחק איזיק הלוי הרצוג, ר שם טוב גאגין, ר אליעזר אליהו דסלר. סירב לרבנות לונדון וכן לכהן כראשל\"צ בירושלים על מקום הרב עוזיאל. נשיא ישיבת \"פורת יוסף\" בירושלים, ופעל רבות למען היהודים שהגיעו ללונדון מהודו, סינגפור, הונג קונג ועוד. הקים בצרפת ישיבות עבור יהודי צפון אפריקה. עלה לארץ-תשלא. יסד את תנועת יהדות בבל המתחדשת."},{"i":56095,"n":"ששון, עזרא מחלב","f":"שלמה","k":"בעל אסתר - ת\"א תרצג","b":"עבר לאלכסנדריה, יסד עתון \"הציונות\" בצרפתית. פרופ' למדעים, צייר, עלה לארץ-תרפט והתישב בתל אביב."},{"i":56096,"n":"ששון, פרג'י מחלב","dt":"תרע - כח אד\"ב","dp":"[חלב]","b":"רב בחלב."},{"i":56097,"n":"ששון, פרחה פלורה מבומבי","f":"יחזקאל יהושע גבאי מב","bt":"תריז","bp":"בומבי","b":"אשת הגביר סלימן דוד ששון מבומבי, מלומדת ואשת חסד. עברה ללונדון-תרעא."},{"i":56098,"n":"ששון, ראובן מלונדון","f":"דוד מבומבי ולונדון","b":"גביר בלונדון. תרם ליהודי ירושלים, ולבית הספר כי\"ח בשלוניקי-תרלה."},{"i":56099,"n":"ששון, שלמה","dt":"תריא - ט חשון","b":"מרבני ירושלים"},{"i":56100,"n":"ששון, שלמה בכור","dt":"תרכז - יט כסלו","b":"רב בירושלים."},{"i":56101,"n":"ששון, שלמה מירושלים","dt":"תריא - ט חשון","b":"מחכמי ירושלים."},{"i":56102,"n":"ששנא גאון סורא","dt":"ד'תמט - בערך","b":"גאון סורא אחרי רב הונאי. הגאון הראשון שנשארו ממנו תשובות."},{"i":56103,"n":"ששפורטש, אברהם מאמשטרדם","f":"יעקב","bp":"אלגיר","dt":"תק","b":"רב באמשטרדם. הו\"ל ספרי אביו \"אהל יעקב\" ו\"קיצור ציצת נובל צבי\"."},{"i":56104,"n":"ששפורטש, אברהם מספרד","bt":"קך","dt":"רץ - בערך","b":"מחכמי מיורקה, הגיע להוניין-קנא, עשיר ומקורב למלך בתלמסאן, ונזכר בשו\"ת הריב\"ש, ובתשב\"ץ."},{"i":56105,"n":"ששפורטש, אהרן","k":"מגזע הרמב\"ן"},{"i":56106,"n":"ששפורטש, דוד מאלגיר","f":"פרג'","bt":"תף","dt":"תקן - בערך","b":"רב בתלמסאן. נזכר ב\"אשכבתא דרבנן\"."},{"i":56107,"n":"ששפורטש, יהודה מאלגיר","f":"יוסף מהוניין","dt":"רנב","dp":"אלגיר","b":"רב בתלמסאן."},{"i":56108,"n":"ששפורטש, יוסף מאלגיר","f":"אברהם","bt":"קס","dt":"רן - בערך","b":"תלמיד הרשב\"ץ באלגיר. רב ודיין בהוניין, והתפרנס ממסחר. חתנו - ר שלמה דסמשתרי גיסו של הרשב\"ץ. היה בקשרים עם הרשב\"ץ, בנו הרשב\"ש ונכדו ר צמח. השיב לקהלות שונות באלגיר ומרוקו ומתשובותיו נדפס ע\"י ר נח עמינח בתל אביב תשנה. בידי ר יצחק באדהב היו כתב יד ממנו בהלכות טריפות."},{"i":56109,"n":"ששפורטש, יוסף מאלגיר","f":"נתנאל","bt":"קל","dt":"ר - בערך","b":"רב בתנס-אלגיר. תשובות אליו בשו\"ת התשב\"ץ."},{"i":56110,"n":"ששפורטש, יעקב מאמשטרדם","f":"אהרן","k":"בעל ציצית נובל צבי","bt":"שפ","bp":"ווהראן","dt":"תנט - ד אייר","b":"מצאצאי הרמב\"ן. מגדולי חכמי הספרדים, רב ודיין בתלמסאן-שצד, נאסר ע\"י המלך והצליח לברוח לסאלי-מרוקו, רב קהלת הספרדים בהמבורג, אמשטרדם, נסע עם ר מנשה בן ישראל ללונדון-תכד לבקש מקרומוול רשות ישיבה ליהודים באנגליה, דיין בלונדון ועזב בגלל מגפה, המבורג-תכו, אמשטרדם-תלג, וראש ישיבת \"עץ חיים\" באמשטרדם. בשליחות מלך מרוקו בספרד. מראשוני הלוחמים בשבתאות חיבר גם \"אהל יעקב\", \"עדות ביעקב\", ועוד."},{"i":56111,"n":"ששפורטש, יצחק","f":"שלמה","b":"נזכר בשטר-תקכט."},{"i":56112,"n":"ששפורטש, יצחק מאמשטרדם","f":"יעקב","k":"בעל שיח יצחק","dt":"תץ","b":"רב באמשטרדם על מקום אביו. חיבר \"שיח יצחק\" - בכת\"י, ושו\"ת."},{"i":56113,"n":"ששפורטש, שלום מצפת","b":"עלה מאלגיר, וכיהן כרב בצפת, וחתם עם רבני צפת על \"שדה יצחק\" לר יצחק גויטע, חתם עם רבני צפת-תרה על כתב שליחות ר חיים נחום מזרחי."},{"i":56114,"n":"ששפורטש, שלמה מאמשטרדם","k":"בעל שש שערים","dp":"ניצה די פרובינצא","b":"רב בניצה די פרובינצא. חיבר \"שש שערים\"."},{"i":56115,"n":"ששפורטש, שמואל מאלגיר ואיטליה","bt":"שע","dt":"תן - בערך","b":"נגיד קהלת ווהראן, גורש עם שאר היהודים בכבוש הספרדי-תכט והגיע לליוורנו."},{"i":56116,"n":"ששת","b":"אביו של הריב\"ש. נזכר ע\"י ר משה ניגרין מגורי האר\"י - בסדר עבודה שלו - בכת\"י שהיה בידי השליח ר ישראל קמחי."},{"i":56117,"n":"ששת גאון","f":"מנוח","b":"נזכר בספר העיטור - תשובה אליו, ויתכן והוא טעות סופר."},{"i":56118,"n":"ששת הנשיא ממרוקו","b":"תלמיד מוסא אבו עמרן. מראשי קהלת פאס, מכתב ממנו לחכמי לוניל."},{"i":56119,"n":"ששת הרופא מחלב","f":"יפת","k":"בעל חמדת התעודה","b":"רופא מחכמי חלב - ה'ן. חיבר פירוש לתורה בשם \"חמאת התעודה\" וקטעים ממנו נדפסו בירושלים תרצג.בניו ר יפת המכונה אנגניב אבו למחאסן, ור משה המכונה איש שמם עבדא אללסיף. בפירושו מזכיר חכמים בלתי ידועים ובהם ר חיים בן ברכאל, ר טוביה האשורי ועוד. חיבר גם \"אל מינתובב\" על המדרשים בערבית, וקיצור \"חמדת התעודה\" בשם \"חמדת החמאה\"."},{"i":56120,"n":"ששת מברצלונה","dt":"ט (1249)","b":"מחכמי ברצלונה בזמן הרמב\"ן."},{"i":56121,"n":"ששת ן, יעקב מגירונא","k":"בעל שער השמים","b":"מראשוני המקובלים הספרדים בגירונא-שנת ו'"},{"i":56122,"n":"ששת ן, יצחק מספרד - ריב\"ש","k":"בעל שות הריב\"ש","bt":"פו","bp":"[ברצלונה]","dt":"קסח","dp":"אלג'יר","b":"תלמיד הר\"ן, ר פרץ הכהן, ר חסדאי קרשקש. מגדולי חכמי ספרד. רב בסרגוסה, ולניסה ועוד. ברח מספרד-קנא - לאחר ששני בניו ר ששת ור שאלתיאל - נהרגו עק\"ה במיורקא, והגיע לתנס - אלגיר (ולא תוניס), מיליאנא, רב באלג'יר-קנד בעזרת הדיין ר שאול אשתרוק הכהן. העביר את הרבנות לתשב\"ץ. תיקן תקנות ליהודי אלגיר, ונחשב למגן היהודים באלגיר (והיו שטענו שבשנת תקלד נכשל הצי הספרדי בנסיונו לכבוש את אלגיר בגלל להבות אש שעלו מקברי הריב\"ש והרשב\"ץ ושרפו את ספינותיהם). חתנו - ממשפחת סטורה באלגיר."},{"i":56123,"n":"ששת ן, מאיר מפאס","bt":"תרכא","b":"רב בפאס-תר\"ע"},{"i":56124,"n":"ששת ן, מרדכי מפאס","bp":"מראקש","dt":"תרסא","b":"מחכמי פאס. סגי נהור. נפטר ללא ילדים."},{"i":56125,"n":"ששת ן, ראובן מצפת","dt":"תרלג - יד סיון","dp":"טבריה","b":"מחכמי צפת, עבר לטבריה עם כמה מחבריו. בנו ר מאיר ן ששת."},{"i":56126,"n":"שתוי, אהרן מקהיר","b":"מחכמי קהיר, בשנת שמז חתם על התקנה לשחרור תלמידי חכמים ממסים."},{"i":56127,"n":"שתוי, נתן מקהיר וירושלים","b":"מחכמי קהיר. חתם עם רבני מצרים-שמז. (ולפי רוזניס - בשנת רסט, והיה מחכמי ירושלים)"},{"i":56128,"n":"שתיוי, חלאפו מלוב","bt":"תרס","dt":"תשל - בערך","b":"רב בבארצ'ה(=ברדה)-לוב."},{"i":56129,"n":"שתרוג, ישועה חי מתונס","b":"רב בתונס-תרלח. אחיהם של ר מרדכי ור משה מתונס. הטיל על מהר\"ש דאנה ואחיו הנזכרים לחבר ספר \"שבת אחים\" על מנהגי תונס בהלכות טרפות. מתשובותיו ב\"ישיב משה\"."},{"i":56130,"n":"שתרוג, משה מתונס","k":"בעל ישיב משה","bt":"תרו","bp":"תונס","dt":"תרפח - יג כסלו","dp":"תונס","b":"רב וראש ישיבה בתונס, מגדולי רבני תונס. פוסק חדשני שדן בשאלות הקשורות לחדושים בחשמל ועוד. לחם בהשכלה שהתפשטה בתונס ע\"י \"אליאנס\". חיבר גם \"שבת אחים\", ועוד. נספד ב\"פקד משה\"."}];
